let _funcEditSnapJSON = null;
function _funcEditAtualizarSnapshot(){
  try{ _funcEditSnapJSON = localStorage.getItem('mm_funcionarios_edit') || JSON.stringify(typeof FUNCIONARIOS!=='undefined'?FUNCIONARIOS:[]); }catch(e){ _funcEditSnapJSON = null; }
}


function _mesclarFuncEdit(remoto, remotoDel){
  try{
    var local=[];
    try{ local = JSON.parse(localStorage.getItem('mm_funcionarios_edit')||'null'); }catch(e){ local=null; }
    if(!Array.isArray(local)) local = (typeof FUNCIONARIOS!=='undefined'?FUNCIONARIOS.slice():[]);
    var rem = Array.isArray(remoto)?remoto.filter(Boolean)
            : (remoto && typeof remoto==='object' ? Object.values(remoto).filter(Boolean) : []);
    if(!rem.length && !local.length) return null;

    try{ localStorage.removeItem('mm_funcedit_del'); }catch(e){}
    function pontos(f){ if(!f) return -1; var p=0; if(Number(f.sal||0)>0) p+=1000; p+=Object.keys(f).length; return p; }
    function ganha(novo, atual){
      if(!atual) return true;
      var nu=Number(novo&&novo._upd)||0, au=Number(atual&&atual._upd)||0;
      if(nu!==au) return nu>au;           
      return pontos(novo)>pontos(atual); 
    }
    var mapa={};
    function add(f){ if(!f||!f.mat) return; var k=String(f.mat).toUpperCase(); if(ganha(f, mapa[k])) mapa[k]=f; }
    local.forEach(add); rem.forEach(add);
    return Object.keys(mapa).map(function(k){ return mapa[k]; });
  }catch(e){ return null; }
}

const _CHAVES_DELETED_ARRAYS = ['ticketsDeleted','adtPorFornDeleted','chequesPorFornDeleted',
  'saldoDevedorDeleted','estoqueDeleted','fcSaldoIniDeleted','adtItensDeleted','chequeItensDeleted',
  'contasReceberDeleted','vendasDeleted','valesDeleted','lancBancoDeleted','viagemDeleted',
  'combustivelDeleted','tanqueDeleted','frotaDeleted','manutencaoDeleted','almoxaDeleted','almoxaMovDeleted',
  'clientesDeleted','fornecedoresDeleted','bancosDeleted','despGrupoDeleted','coordNotasDeleted',
  'contratosDeleted','docsEmpresasDeleted','epiDeleted','reunioesDeleted','advertenciasDeleted',
  'bagsMovDeleted','historicoDeleted','pontoDeleted','pontoBatidasDeleted','fornDespesaDeleted','afazeresDeleted'];
let _deletedArrSnap = {};

function _deletedArrPularSeIgual(dados){
  const _valoresAtuais = {};
  _CHAVES_DELETED_ARRAYS.forEach(function(chave){
    if(!(chave in dados)) return;
    const arr = dados[chave];
    delete dados[chave];
    if(!Array.isArray(arr)) return;
    let atual; try{ atual = JSON.stringify(arr.slice().sort()); }catch(e){ atual = null; }
    _valoresAtuais[chave] = atual;
    if(atual !== undefined && atual === _deletedArrSnap[chave]) return;
    if(!arr.length) return;
    const obj = {}; arr.forEach(function(id){ obj[id] = true; });
    dados[chave+'V2'] = obj;
  });
  return _valoresAtuais;
}
function _deletedArrConfirmarSnapshots(_valoresAtuais){
  Object.keys(_valoresAtuais).forEach(function(chave){ _deletedArrSnap[chave] = _valoresAtuais[chave]; });
}

function _idsDeArrayOuObjeto(v){
  if(Array.isArray(v)) return v;
  if(v && typeof v==='object') return Object.keys(v);
  return [];
}
function _juntarDeletedV1eV2(v1, v2){
  const ids = _idsDeArrayOuObjeto(v1).concat(_idsDeArrayOuObjeto(v2));
  return ids.length ? ids : null;
}

function _normalizarDeletedV2EmD(d){
  if(!d) return;
  _CHAVES_DELETED_ARRAYS.forEach(function(chave){
    const v2 = d[chave+'V2'];
    if(!v2) return;
    const idsV2 = _idsDeArrayOuObjeto(v2);
    if(!idsV2.length) return;
    d[chave] = (Array.isArray(d[chave]) ? d[chave] : []).concat(idsV2);
  });
}
function _ticketExcluir(tid){
  delete TICKETS_DB[tid];
  TICKETS_DELETED.add(tid);
  try{ localStorage.setItem('mm_tickets_deletados', JSON.stringify([...TICKETS_DELETED])); }catch(e){}
}

const _DEL_SETS = {
  adtPorForn: new Set(),
  chequesPorForn: new Set(),
  saldoDevedor: new Set(),
  estoque: new Set(),
  fcSaldoIni: new Set(),
  adtItens: new Set(),
  chequeItens: new Set()
};
const _DEL_LS_KEY = {
  adtPorForn: 'mm_adtforn_deletados',
  chequesPorForn: 'mm_chequesforn_deletados',
  saldoDevedor: 'mm_saldodev_deletados',
  estoque: 'mm_estoque_deletados',
  fcSaldoIni: 'mm_fcsaldoini_deletados',
  adtItens: 'mm_adtitens_deletados',
  chequeItens: 'mm_chequeitens_deletados'
};
function _apagarChave(nome, target, key){
  delete target[key];
  _DEL_SETS[nome].add(key);
  try{ localStorage.setItem(_DEL_LS_KEY[nome], JSON.stringify([..._DEL_SETS[nome]])); }catch(e){}
}

function _mergeMetaisRemoto(dMetais, dDeleted){
  if(typeof METAIS==='undefined' || !Array.isArray(dMetais) || !dMetais.length) return;
  const del=new Set();
  try{ if(_DEL_SETS && _DEL_SETS.estoque) _DEL_SETS.estoque.forEach(function(x){ del.add(x); }); }catch(e){}
  if(Array.isArray(dDeleted)) dDeleted.forEach(function(x){ del.add(x); });
  const locais=METAIS.slice(); 
  METAIS.length=0;
  dMetais.forEach(function(m){ if(!del.has(m) && METAIS.indexOf(m)<0) METAIS.push(m); });
  locais.forEach(function(m){ if(!del.has(m) && METAIS.indexOf(m)<0) METAIS.push(m); });
  try{ localStorage.setItem('mm_metais', JSON.stringify(METAIS)); }catch(e){}
}

function _patchIncremental(dados, path, obj, delSet){
  Object.keys(obj||{}).forEach(function(k){ dados[path+'/'+k] = obj[k]; });
  if(delSet){ delSet.forEach(function(k){ if(!obj || !(k in obj)) dados[path+'/'+k] = null; }); }
}

function _aplicarTombstonesRemotos(nome, target, listaRemota){
  if(nome==='adtPorForn') return;

  const ks = _idsDeArrayOuObjeto(listaRemota);
  if(!ks.length) return;
  ks.forEach(function(k){ delete target[k]; _DEL_SETS[nome].add(k); });
  try{ localStorage.setItem(_DEL_LS_KEY[nome], JSON.stringify([..._DEL_SETS[nome]])); }catch(e){}
}


function _mergeArrayPorId(localArr, remoteArr, idField){
  const porId = new Map();
  (Array.isArray(localArr) ? localArr : []).forEach(function(item){
    if(item) porId.set(item[idField] != null ? item[idField] : JSON.stringify(item), item);
  });
  (Array.isArray(remoteArr) ? remoteArr : []).forEach(function(item){
    if(item) porId.set(item[idField] != null ? item[idField] : JSON.stringify(item), item);
  });
  return [...porId.values()];
}

function _mergeObjDeArraysPorId(local, remote, target, idField, confiavel){
  if(confiavel){
    Object.keys(target||{}).forEach(function(k){ delete target[k]; });
    Object.keys(remote||{}).forEach(function(k){
      const arr=(remote||{})[k];
      target[k]=Array.isArray(arr)
        ? arr.filter(Boolean).slice()
        : (arr && typeof arr==='object' ? Object.values(arr).filter(Boolean) : []);
    });
    return;
  }
  const chaves = new Set(Object.keys(local||{}).concat(Object.keys(remote||{})));
  chaves.forEach(function(k){
    target[k] = _mergeArrayPorId((local||{})[k], (remote||{})[k], idField);
  });
}


window._ADT_PENDENTES = window._ADT_PENDENTES || {};
function _adtMarcarPendente(fornCod, item){
  try{
    if(!item || item.cod==null || !fornCod) return;
    window._ADT_PENDENTES[fornCod+'::'+item.cod] = {fornCod:fornCod, cod:item.cod, item:JSON.parse(JSON.stringify(item)), ts:Date.now()};
  }catch(e){}
}
function _adtTemCod(arr, cod){
  try{
    if(Array.isArray(arr)) return arr.some(function(x){return x && x.cod==cod;});
    if(arr && typeof arr==='object') return Object.keys(arr).some(function(k){return arr[k] && arr[k].cod==cod;});
  }catch(e){}
  return false;
}
function _adtReporPendentes(target, remote){
  try{
    var agora=Date.now();
    Object.keys(window._ADT_PENDENTES).forEach(function(chave){
      var p=window._ADT_PENDENTES[chave];
      if(!p){ delete window._ADT_PENDENTES[chave]; return; }

      if(remote && _adtTemCod(remote[p.fornCod], p.cod)){ delete window._ADT_PENDENTES[chave]; return; }

      if(agora - p.ts > 90000){ delete window._ADT_PENDENTES[chave]; return; }

      if(!Array.isArray(target[p.fornCod])) target[p.fornCod]=[];
      if(!_adtTemCod(target[p.fornCod], p.cod)) target[p.fornCod].push(p.item);
    });
  }catch(e){}
}

function _adtSalvarNaNuvem(fornCod){
  try{
    if(!fornCod) return;
    var arr = ADT_POR_FORN[fornCod];
    if(Array.isArray(arr)) arr.forEach(function(it){ if(it) _adtMarcarPendente(fornCod, it); });
    if(window._fbDB){
      window._fbDB.ref('erp/adiantamentos/'+fornCod).set((arr&&arr.length)?arr:null);
      window._fbDB.ref('erp/_ts').set(Date.now());
    }
  }catch(e){}
}

function _mergeAdtCloudManda(local, remote, target, fbConfiavel, cloudTinhaAdt){
  if(!fbConfiavel){ _mergeObjDeArraysPorId(local||{}, remote||{}, target, 'cod'); return; }

  var temRemote = remote && typeof remote==='object' && Object.keys(remote).length>0;
  if(!temRemote){
    Object.keys(target).forEach(function(k){ delete target[k]; });
    _adtReporPendentes(target, remote);
    return;
  }

  var novo={};
  Object.keys(remote).forEach(function(k){
    var arr=remote[k];
    novo[k] = Array.isArray(arr) ? arr.slice() : (arr && typeof arr==='object' ? Object.values(arr).filter(Boolean) : []);
  });
  Object.keys(target).forEach(function(k){ delete target[k]; });
  Object.keys(novo).forEach(function(k){ target[k]=novo[k]; });
  _adtReporPendentes(target, remote);
}

function _aplicarTombstonesItensPorForn(nome, targetPorForn, idField, listaRemota){

  if(nome==='adtItens') return;

  const _ksItens = _idsDeArrayOuObjeto(listaRemota);
  if(_ksItens.length){
    _ksItens.forEach(function(k){ _DEL_SETS[nome].add(k); });
    try{ localStorage.setItem(_DEL_LS_KEY[nome], JSON.stringify([..._DEL_SETS[nome]])); }catch(e){}
  }
  if(!_DEL_SETS[nome].size) return;
  Object.keys(targetPorForn||{}).forEach(function(fornCod){
    const arr=targetPorForn[fornCod];
    if(!Array.isArray(arr)) return;
    const filtrado=arr.filter(function(item){
      const idItem = item && item[idField] != null ? item[idField] : null;
      return !(idItem!=null && _DEL_SETS[nome].has(fornCod+'::'+idItem));
    });
    if(filtrado.length!==arr.length) targetPorForn[fornCod]=filtrado;
  });
}
















function _cpParaObjeto(){
  const obj={};
  CONTAS_PAGAR.forEach(function(c){
    if(!c) return;
    if(!c.id) c.id=_novoIdCP(); 
    obj[c.id]=c;
  });
  return obj;
}
let _cpMigracaoEmAndamento=false;




function _cpMigrarParaFormatoPorChave(){
  if(_cpMigracaoEmAndamento || !window._fbDB) return;
  _cpMigracaoEmAndamento=true;
  try{
    window._fbDB.ref('erp/contasPagar').set(_cpParaObjeto())
      .then(function(){ console.info('Contas a Pagar migrado pro formato por-chave na nuvem.'); })
      .catch(function(e){ console.warn('Falha ao migrar Contas a Pagar pro formato por-chave:', e); })
      .finally(function(){ _cpMigracaoEmAndamento=false; });
  }catch(e){ _cpMigracaoEmAndamento=false; }
}







function _cpCarregarDeRemoto(remotoContasPagar, confiavel){
  const remotoEhArray=Array.isArray(remotoContasPagar);
  const vals=remotoEhArray
    ? remotoContasPagar.filter(Boolean)
    : (remotoContasPagar && typeof remotoContasPagar==='object' ? Object.values(remotoContasPagar).filter(Boolean) : []);

  if(confiavel){
    CONTAS_PAGAR.length=0;
    vals.forEach(function(rc){
      if(!rc) return;
      if(!rc.id) rc.id=_cpIdDeterministico(rc);
      CONTAS_PAGAR.push(rc);
    });
    if(remotoEhArray && vals.length) _cpMigrarParaFormatoPorChave();
    return;
  }

  if(!vals.length) return;
  const porIdLocal={};
  CONTAS_PAGAR.forEach(function(c){ if(c&&c.id) porIdLocal[c.id]=c; });
  vals.forEach(function(rc){
    if(!rc) return;
    if(!rc.id) rc.id=_cpIdDeterministico(rc);
    if(CONTAS_PAGAR_DELETED.has(rc.id)) return;
    const loc=porIdLocal[rc.id];
    if(!loc){ CONTAS_PAGAR.push(rc); porIdLocal[rc.id]=rc; return; }
    if(Number(rc._upd||0) > Number(loc._upd||0)) Object.assign(loc,rc);
  });
  if(remotoEhArray) _cpMigrarParaFormatoPorChave();
}
let CONTAS_PAGAR_DELETED = new Set();
function _novoIdCP(){ return 'CP'+Date.now().toString(36)+Math.random().toString(36).slice(2,7); }





function _cpIdDeterministico(c){
  const chave=[c.ticket||'', c.desc||'', c.cred||'', Number(c.valor||0).toFixed(2), c.venc||'', c.status||''].join('|');
  let h=0;
  for(let i=0;i<chave.length;i++){ h=((h<<5)-h+chave.charCodeAt(i))|0; }
  return 'CPX'+Math.abs(h).toString(36);
}

















function _cpDeletedParaObjeto(){ const obj={}; CONTAS_PAGAR_DELETED.forEach(function(id){ obj[id]=true; }); return obj; }
let _cpDeletedMigrando=false;
function _cpDeletedMigrar(){
  if(_cpDeletedMigrando || !window._fbDB) return;
  _cpDeletedMigrando=true;
  try{
    window._fbDB.ref('erp/contasPagarDeleted').set(_cpDeletedParaObjeto())
      .then(function(){ console.info('contasPagarDeleted migrado pro formato por-chave na nuvem.'); })
      .catch(function(e){ console.warn('Falha ao migrar contasPagarDeleted:', e); })
      .finally(function(){ _cpDeletedMigrando=false; });
  }catch(e){ _cpDeletedMigrando=false; }
}
function _cpDeletedCarregarDeRemoto(remotoBruto){
  if(Array.isArray(remotoBruto)){
    if(!remotoBruto.length) return;
    remotoBruto.forEach(function(id){ CONTAS_PAGAR_DELETED.add(id); });
    try{ localStorage.setItem('mm_cp_deletados', JSON.stringify([...CONTAS_PAGAR_DELETED])); }catch(e){}
    _cpDeletedMigrar();
    return;
  }
  if(remotoBruto && typeof remotoBruto==='object'){
    let mudou=false;
    Object.keys(remotoBruto).forEach(function(id){ if(remotoBruto[id] && !CONTAS_PAGAR_DELETED.has(id)){ CONTAS_PAGAR_DELETED.add(id); mudou=true; } });
    if(mudou){ try{ localStorage.setItem('mm_cp_deletados', JSON.stringify([...CONTAS_PAGAR_DELETED])); }catch(e){} }
  }
}








function _criarSincroniaPorChave(nome, lista, prefixoId){
  const deletedSet = new Set();
  const lsKey = 'mm_'+nome+'_deletados';
  try{
    const raw = localStorage.getItem(lsKey);
    if(raw) JSON.parse(raw).forEach(function(id){ deletedSet.add(id); });
  }catch(e){}
  let migracaoEmAndamento=false;
  function novoId(){ return prefixoId+Date.now().toString(36)+Math.random().toString(36).slice(2,7); }
  
  
  
  function _chaveConteudo(item){
    const chaves=Object.keys(item||{}).filter(function(k){ return k!=='id'; }).sort();
    const norm={};
    chaves.forEach(function(k){ norm[k]=item[k]; });
    return JSON.stringify(norm);
  }
  
  
  
  
  
  
  
  
  function _idDeterministico(item){
    const chave=_chaveConteudo(item);
    let h=0;
    for(let i=0;i<chave.length;i++){ h=((h<<5)-h+chave.charCodeAt(i))|0; }
    return prefixoId+'X'+Math.abs(h).toString(36);
  }
  
  
  
  
  
  function limparDuplicatasExatas(){
    const vistos={};
    const remover_=[];
    lista.forEach(function(item,i){
      if(!item) return;
      const chave=_chaveConteudo(item);
      if(Object.prototype.hasOwnProperty.call(vistos,chave)) remover_.push(i);
      else vistos[chave]=i;
    });
    if(!remover_.length) return false;
    remover_.sort(function(a,b){ return b-a; }).forEach(function(i){ remover(i); });
    return true;
  }
  function paraObjeto(){
    const obj={};
    lista.forEach(function(item){
      if(!item) return;
      if(!item.id) item.id=novoId();
      obj[item.id]=item;
    });
    return obj;
  }
  
  
  
  function remover(idx){
    
    
    
    if(typeof idx!=='number'){
      const _j=lista.findIndex(function(x){ return x && x.id===idx; });
      if(_j<0){
        if(/^\d+$/.test(String(idx))) idx=parseInt(idx,10); else return;
      } else idx=_j;
    }
    const item=lista[idx];
    if(item && item.id){
      deletedSet.add(item.id);
      try{ localStorage.setItem(lsKey, JSON.stringify([...deletedSet])); }catch(e){}
    }
    if(idx>=0) lista.splice(idx,1);
  }
  function migrar(){
    if(migracaoEmAndamento || !window._fbDB) return;
    migracaoEmAndamento=true;
    try{
      window._fbDB.ref('erp/'+nome).set(paraObjeto())
        .then(function(){ console.info(nome+' migrado pro formato por-chave na nuvem.'); })
        .catch(function(e){ console.warn('Falha ao migrar '+nome+' pro formato por-chave:', e); })
        .finally(function(){ migracaoEmAndamento=false; });
    }catch(e){ migracaoEmAndamento=false; }
  }
  function carregarDeRemoto(remotoBruto, confiavel){
    const remotoEhArray=Array.isArray(remotoBruto);
    const vals=remotoEhArray
      ? remotoBruto.filter(Boolean)
      : (remotoBruto && typeof remotoBruto==='object' ? Object.values(remotoBruto).filter(Boolean) : []);

    if(confiavel){
      lista.length=0;
      vals.forEach(function(item){
        if(!item) return;
        if(!item.id) item.id=_idDeterministico(item);
        if(deletedSet.has(item.id)) return;
        lista.push(item);
      });
      if(remotoEhArray && vals.length) migrar();
      return;
    }

    if(!vals.length) return;
    const porIdLocal={};
    lista.forEach(function(it){ if(it&&it.id) porIdLocal[it.id]=it; });
    vals.forEach(function(item){
      if(!item) return;
      if(!item.id) item.id=_idDeterministico(item);
      if(deletedSet.has(item.id)) return;
      const atual=porIdLocal[item.id];
      if(!atual){ lista.push(item); porIdLocal[item.id]=item; }
      else Object.assign(atual,item);
    });
    if(remotoEhArray) migrar();
  }
  
  
  try{ if(deletedSet.size>5000){ console.warn('deletedSet('+nome+') local gigante ('+deletedSet.size+') — zerado por segurança'); deletedSet.clear(); localStorage.setItem(lsKey, '[]'); } }catch(_e){}
  function aplicarTombstonesRemotos(remotoDel){
    
    
    
    const ids = _idsDeArrayOuObjeto(remotoDel);
    if(!ids.length) return;
    
    
    
    
    if(ids.length>5000){ console.warn('tombstones('+nome+'): '+ids.length+' IGNORADOS (limite de segurança)'); return; }
    ids.forEach(function(id){ deletedSet.add(id); });
    try{ localStorage.setItem(lsKey, JSON.stringify([...deletedSet])); }catch(e){}
    for(let i=lista.length-1;i>=0;i--){
      const it=lista[i];
      if(it && it.id && deletedSet.has(it.id)) lista.splice(i,1);
    }
  }
  
  
  
  
  
  
  
  async function buscarTombstonesRemotosEAplicar(){
    if(!window._fbDB) return;
    try{
      
      
      
      
      const [snap, snapV2] = await Promise.all([
        new Promise(function(resolve,reject){ window._fbDB.ref('erp/'+nome+'Deleted').once('value', resolve, reject); }),
        new Promise(function(resolve,reject){ window._fbDB.ref('erp/'+nome+'DeletedV2').once('value', resolve, reject); })
      ]);
      const remotoDel = snap && snap.val ? snap.val() : null;
      const remotoDelV2 = snapV2 && snapV2.val ? snapV2.val() : null;
      aplicarTombstonesRemotos(remotoDel);
      aplicarTombstonesRemotos(remotoDelV2);
    }catch(e){ console.warn('buscarTombstonesRemotosEAplicar('+nome+') falhou:', e); }
  }
  return { deletedSet:deletedSet, paraObjeto:paraObjeto, remover:remover, migrar:migrar, carregarDeRemoto:carregarDeRemoto, aplicarTombstonesRemotos:aplicarTombstonesRemotos, buscarTombstonesRemotosEAplicar:buscarTombstonesRemotosEAplicar, novoId:novoId, limparDuplicatasExatas:limparDuplicatasExatas };
}








function _cpIdxPorId(id){ return id ? CONTAS_PAGAR.findIndex(c=>c && c.id===id) : -1; }
function _removerCPporIndice(idx){
  const c = CONTAS_PAGAR[idx];
  if(c && c.id){
    CONTAS_PAGAR_DELETED.add(c.id);
    try{ localStorage.setItem('mm_cp_deletados', JSON.stringify([...CONTAS_PAGAR_DELETED])); }catch(e){}
  }
  CONTAS_PAGAR.splice(idx,1);
}











function _cpAutoLimparDuplicatas(){
  const porChave={};
  CONTAS_PAGAR.forEach(function(c,i){
    if(!c || !c.ticket || c.status==='Pago') return;
    const chave=c.ticket+'|'+c.status+'|'+Number(c.valor||0).toFixed(2);
    (porChave[chave]=porChave[chave]||[]).push(i);
  });
  const remover=[];
  Object.keys(porChave).forEach(function(chave){
    const idxs=porChave[chave];
    if(idxs.length>1) idxs.slice(1).forEach(i=>remover.push(i));
  });
  if(!remover.length) return false;
  remover.sort((a,b)=>b-a).forEach(function(i){ _removerCPporIndice(i); });
  return true;
}











function _cpLimparDuplicatasExatas(){
  const vistos={};
  const remover=[];
  CONTAS_PAGAR.forEach(function(c,i){
    if(!c) return;
    const chave=[c.ticket||'', c.desc||'', c.cred||'', Number(c.valor||0).toFixed(2), c.venc||'', c.status||'', c.dataPgto||''].join('|');
    if(Object.prototype.hasOwnProperty.call(vistos,chave)){
      remover.push(i);
    } else {
      vistos[chave]=i;
    }
  });
  if(!remover.length) return false;
  remover.sort((a,b)=>b-a).forEach(function(i){ _removerCPporIndice(i); });
  return true;
}
async function _mesclarContasPagarComNuvem(){
  if(!window._fbDB) return;
  try{
    const [snap, snapDel] = await Promise.all([
      new Promise((resolve,reject)=>{ window._fbDB.ref('erp/contasPagar').once('value', s=>resolve(s), e=>reject(e)); }),
      new Promise((resolve,reject)=>{ window._fbDB.ref('erp/contasPagarDeleted').once('value', s=>resolve(s), e=>reject(e)); })
    ]);
    
    
    
    const remotoDel = snapDel && snapDel.val ? snapDel.val() : null;
    _cpDeletedCarregarDeRemoto(remotoDel);
    if(remotoDel){
      for(let i=CONTAS_PAGAR.length-1;i>=0;i--){
        const c=CONTAS_PAGAR[i];
        if(c && c.id && CONTAS_PAGAR_DELETED.has(c.id)) CONTAS_PAGAR.splice(i,1);
      }
    }
    const remotoBruto = snap && snap.val ? snap.val() : null;
    
    
    
    const remoto = Array.isArray(remotoBruto) ? remotoBruto
      : (remotoBruto && typeof remotoBruto==='object' ? Object.values(remotoBruto).filter(Boolean) : null);
    if(!remoto || !remoto.length) return;
    const porIdLocal = {};
    CONTAS_PAGAR.forEach(function(c){ if(c && c.id) porIdLocal[c.id]=c; });
    
    
    
    const chavesTicketLocais = new Set(CONTAS_PAGAR.filter(c=>c&&c.ticket).map(c=>c.ticket+'|'+c.status));
    remoto.forEach(function(rc){
      if(!rc) return;
      if(rc.id && CONTAS_PAGAR_DELETED.has(rc.id)) return;
      if(rc.id && porIdLocal[rc.id]){
        
        
        
        
        
        
        
        
        
        
        
        
        if(Number(rc._upd||0) > Number(porIdLocal[rc.id]._upd||0)){
          Object.assign(porIdLocal[rc.id], rc);
        }
        return;
      }
      if(!rc.id && rc.ticket && chavesTicketLocais.has(rc.ticket+'|'+rc.status)) return;
      CONTAS_PAGAR.push(rc); 
    });
    try{ _cpAutoLimparDuplicatas(); }catch(e){}
  }catch(e){ console.warn('_mesclarContasPagarComNuvem falhou:', e); }
}

