const _SEC_MAX_TENTATIVAS = 5;
const _SEC_BLOQUEIO_MS    = 30 * 60 * 1000; 
const _SEC_INATIVIDADE_MS = 45 * 60 * 1000; 
let _secInativTimer = null;

function _secChave(u){ return 'mm_sec_' + u; }

function _secRegistrarFalha(u){
  try{
    const key = _secChave(u);
    const raw = localStorage.getItem(key);
    const rec = (raw ? JSON.parse(raw) : null) || {count:0};
    rec.count = (rec.count||0) + 1;
    rec.ultimo = Date.now();
    if(rec.count >= _SEC_MAX_TENTATIVAS) rec.bloqueadoAte = Date.now() + _SEC_BLOQUEIO_MS;
    localStorage.setItem(key, JSON.stringify(rec));
    return rec;
  }catch(e){ return {count:1}; }
}

function _secLimparFalhas(u){
  localStorage.removeItem(_secChave(u));
}

function _secVerificarBloqueio(u){
  try{
    const raw = localStorage.getItem(_secChave(u));
    if(!raw) return 0;
    const rec = JSON.parse(raw)||{};
    if(rec.bloqueadoAte && Date.now() < rec.bloqueadoAte){
      const min = Math.ceil((rec.bloqueadoAte - Date.now()) / 60000);
      return min;
    }
    
    if(rec.bloqueadoAte && Date.now() >= rec.bloqueadoAte) localStorage.removeItem(_secChave(u));
  }catch(e){}
  return 0;
}

function _secIniciarInatividade(){
  _secCancelarInatividade();
  _secInativTimer = setTimeout(()=>{
    if(cu){ 
      showToast('Sessão encerrada por inatividade (45 min).','info',5000);
      setTimeout(doLogout, 1500);
    }
  }, _SEC_INATIVIDADE_MS);
}

function _secCancelarInatividade(){
  if(_secInativTimer){ clearTimeout(_secInativTimer); _secInativTimer=null; }
}

function _secResetarInatividade(){
  if(cu) _secIniciarInatividade();
}


