function _montarFinClientes(){
  try{
    var host=document.getElementById('fincli-host');
    var cli=document.getElementById('adt-painel-cli');
    if(host && cli && cli.parentElement!==host){ cli.style.display=''; host.appendChild(cli); }
    var bc=document.getElementById('adt-tipo-cli-btn'); if(bc) bc.style.display='none';
    var bf=document.getElementById('adt-tipo-forn-btn');
    if(bf && bf.parentElement){ bf.parentElement.style.display='none'; } 
  }catch(e){ console.warn('montarFinClientes',e); }
}
if(document.readyState==='loading'){ document.addEventListener('DOMContentLoaded', _montarFinClientes); }
else { _montarFinClientes(); }

function switchTab(tid){
  
  const _openOv=document.getElementById('modal-ov'); if(_openOv) _openOv.classList.remove('open');
  document.querySelectorAll('.nav-tab').forEach(e=>e.classList.remove('active'));
  document.querySelectorAll('.tab-panel').forEach(e=>e.classList.remove('active'));
  const n=document.querySelector(`.nav-tab[data-tab="${tid}"]`);
  if(n){
    n.classList.add('active');
    const grp=n.closest('.sb-group');
    if(grp && !grp.classList.contains('open')) grp.classList.add('open');
  }
  const p=document.getElementById(`tab-${tid}`);
  if(p)p.classList.add('active');
  try{ if(typeof avisosAtualizarBadge==='function') avisosAtualizarBadge(); }catch(e){}
  try{
    if(tid==='avisos'){ if(typeof renderAvisos==='function') renderAvisos(); }
    else if(tid==='dashboard'){ renderFornInativos(); renderDashboard(); }
    else if(tid==='fornecedores') renderFornInativos();
    else if(tid==='compra_sucata'){ populateFornSelects(); csTab(_csSubTabAtiva||'pesagens'); }
    else if(tid==='canhoto_compra'){ populateFornSelects(); }
    else if(tid==='precos_fornecedores'){ populateFornSelects(); }
    else if(tid==='estoque') renderEstoque();
    else if(tid==='balanceiro'){
      try{ refreshMetaisGlobals(); }catch(e){}
      try{ populateFornSelects(); }catch(e){}
      try{ renderBalanceiro(); }catch(e){}
      try{ setTimeout(balRenderHistorico,50); }catch(e){}
      try{ balAtualizarTicketsDoBanco(); }catch(e){}
    }
    else if(tid==='vendas') renderVendas();
    else if(tid==='clientes'){ renderClientes(); try{ recarregarClientesDoBanco(); }catch(e){} }
    else if(tid==='contas_pagar') renderContasPagar();
    else if(tid==='contas_receber') renderContasReceber();
    else if(tid==='afazeres') renderAfazeres();
    else if(tid==='adiantamentos') renderAdiantamentos();
    else if(tid==='cheques') renderCheques();
    else if(tid==='cheques_compensar'){ chqInit(); renderChequesCompensar(); }
    else if(tid==='fin_clientes'){ var _pc=document.getElementById('adt-painel-cli'); if(_pc) _pc.style.display=''; try{ renderFichaCliente(); }catch(e){} try{ fcSetAba(_fcAba||'extrato'); }catch(e){} }
    else if(tid==='contas_banco'){ renderBancos(); try{ recarregarBancosDoBanco(); }catch(e){} }
    else if(tid==='senhas') renderSenhas();
    else if(tid==='fluxo_caixa') renderFluxo();
    else if(tid==='folha_pagamento') renderFolha();
    else if(tid==='despesas_grupo') initDespesas();
    else if(tid==='vales') renderVales();
    else if(tid==='epi') renderEpi();
    else if(tid==='ponto') renderPontoTab();
    else if(tid==='viagem_motorista') renderViagens();
    else if(tid==='combustivel_rudnick'){ cruSwitchTab(typeof _cruSubTabAtiva!=='undefined'?_cruSubTabAtiva:'abastecer'); renderCombustivel(); renderTanque(); }
    else if(tid==='rod_balanca'){ populateFornSelects(); renderRodBalanca(); setTimeout(()=>{ rodSubTab(typeof _rodSubTabAtiva!=='undefined'?_rodSubTabAtiva:'pesagem'); rodIniciarCameras(); },50); }
    else if(tid==='custo_casa') renderCustoCasa();
    else if(tid==='lista_compras') renderListaCompras();
    else if(tid==='usuarios') populateUsers();
    else if(tid==='almoxarifado'){ loadAlmoxa(); alxTab(typeof _alxSubTabAtiva!=='undefined'?_alxSubTabAtiva:'itens'); }
    else if(tid==='coordenacao'){ loadCoordenacao(); coordTab(typeof _coordTabAtiva!=='undefined'?_coordTabAtiva:'reunioes'); }
    else if(tid==='agenda_entregas'){ try{ agendaRender(); }catch(e){ console.warn('agendaRender:',e); } }
    else if(tid==='documentos_empresas'){ renderDocsEmpresas(); }
    else if(tid==='fiscal'){ renderFiscal(); }
    else if(tid==='chat'){ chatInit(); }
    
    if(tid!=='chat'){ try{ chatDestroy(); }catch(e){} }
    if(tid==='suporte_tecnico') renderSuporteTecnico();
  }catch(e){ console.warn('switchTab render error',tid,e); }
}

function renderDashboard(){
  const now=new Date();
  const mesAtual=now.getFullYear()+'-'+String(now.getMonth()+1).padStart(2,'0');
  const mesDeData=d=>{
    if(!d) return '';
    if(d.includes('-')) return d.substring(0,7);
    const p=d.split('/'); if(p.length<3) return '';
    return p[2]+'-'+p[1].padStart(2,'0');
  };

  const ticketsMes=Object.values(TICKETS_DB).filter(tk=>mesDeData(tk.data)===mesAtual);
  const totalCompras=ticketsMes.reduce((s,tk)=>s+Number(tk.totalGeral||0),0);
  const vendasMes=(VENDAS_DB||[]).filter(v=>mesDeData(v.data)===mesAtual);
  const totalVendas=vendasMes.reduce((s,v)=>s+Number(v.total||0),0);
  const resultado=totalVendas-totalCompras;

  let totalEstoque=0;
  const estoqueMatData={};
  Object.entries(ESTOQUE_DB||{}).forEach(([mat,e])=>{
    const entradas=getEntradasMaterial(mat);
    const saidas=getSaidasMaterial(mat)+Number(e.saidas||0);
    const saldo=Number(e.inicial||0)+entradas-saidas;
    const s=Math.max(0,saldo);
    totalEstoque+=s;
    estoqueMatData[mat]=s;
  });

  const funcAtivos=(FUNCIONARIOS||[]).filter(f=>f.status!=='Inativo').length;
  let totalChequesPend=0, qtdCheqPend=0;
  Object.values(CHEQUES_POR_FORN||{}).forEach(lista=>{
    lista.filter(c=>c.status==='Pendente').forEach(c=>{
      totalChequesPend+=Number(c.valor||0);
      qtdCheqPend++;
    });
  });

  const fmtR=v=>'R$ '+Number(v).toLocaleString('pt-BR',{minimumFractionDigits:2});
  const fmtKg=v=>Number(v).toLocaleString('pt-BR',{maximumFractionDigits:0})+' kg';
  const nomeMes=now.toLocaleDateString('pt-BR',{month:'long',year:'numeric'});
  const el=id=>document.getElementById(id);
  if(el('kpi-dash-compras')) el('kpi-dash-compras').textContent=fmtR(totalCompras);
  if(el('kpi-dash-compras-sub')) el('kpi-dash-compras-sub').textContent=ticketsMes.length+' tickets em '+nomeMes;
  if(el('kpi-dash-vendas')) el('kpi-dash-vendas').textContent=fmtR(totalVendas);
  if(el('kpi-dash-vendas-sub')) el('kpi-dash-vendas-sub').textContent=vendasMes.length+' vendas em '+nomeMes;
  if(el('kpi-dash-resultado')){
    el('kpi-dash-resultado').textContent=fmtR(resultado);
    el('kpi-dash-resultado').style.color=resultado>=0?'#1a7a41':'#c0392b';
  }
  if(el('kpi-dash-resultado-sub')) el('kpi-dash-resultado-sub').textContent=resultado>=0?'Lucro bruto do mes':'Deficit do mes';
  if(el('kpi-dash-estoque')) el('kpi-dash-estoque').textContent=fmtKg(totalEstoque);
  if(el('kpi-dash-func')) el('kpi-dash-func').textContent=funcAtivos+' ativos';
  if(el('kpi-dash-cheques')) el('kpi-dash-cheques').textContent=fmtR(totalChequesPend);
  if(el('kpi-dash-cheques-sub')) el('kpi-dash-cheques-sub').textContent=qtdCheqPend+' cheque'+(qtdCheqPend!==1?'s':'')+' pendente'+(qtdCheqPend!==1?'s':'');

  
  if(typeof Chart === 'undefined') return;

  
  const canvas1=el('chart-faturamento');
  if(canvas1){
    const labels=[], dataCompras=[], dataVendas=[];
    for(let i=5;i>=0;i--){
      const d=new Date(now.getFullYear(),now.getMonth()-i,1);
      const ym=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0');
      const lbl=d.toLocaleDateString('pt-BR',{month:'short',year:'2-digit'});
      labels.push(lbl);
      const comp=Object.values(TICKETS_DB).filter(tk=>mesDeData(tk.data)===ym)
        .reduce((s,tk)=>s+Number(tk.totalGeral||0),0);
      const vend=(VENDAS_DB||[]).filter(v=>mesDeData(v.data)===ym)
        .reduce((s,v)=>s+Number(v.total||0),0);
      dataCompras.push(+(comp/1000).toFixed(1));
      dataVendas.push(+(vend/1000).toFixed(1));
    }
    if(canvas1._chartInst) canvas1._chartInst.destroy();
    canvas1._chartInst=new Chart(canvas1,{
      type:'bar',
      data:{
        labels,
        datasets:[
          {label:'Compras (R$ mil)',data:dataCompras,backgroundColor:'rgba(192,57,43,.75)',borderRadius:5,borderSkipped:false},
          {label:'Vendas (R$ mil)',data:dataVendas,backgroundColor:'rgba(26,122,65,.8)',borderRadius:5,borderSkipped:false}
        ]
      },
      options:{responsive:true,maintainAspectRatio:false,
        plugins:{legend:{position:'bottom',labels:{font:{family:"'Inter',sans-serif",size:11},boxWidth:12}},
          tooltip:{callbacks:{label:ctx=>'R$ '+ctx.raw.toFixed(1)+'K'}}},
        scales:{
          x:{grid:{display:false},ticks:{font:{family:"'Inter',sans-serif",size:11}}},
          y:{grid:{color:'rgba(0,0,0,.06)'},ticks:{font:{family:"'Inter',sans-serif",size:10},callback:v=>v+'K'}}
        }
      }
    });
  }

  
  const canvas2=el('chart-estoque');
  if(canvas2){
    const mats=Object.keys(estoqueMatData).filter(m=>estoqueMatData[m]>0);
    const vals=mats.map(m=>+estoqueMatData[m].toFixed(0));
    const COLORS=['#1a7a41','#c8a400','#c0392b','#1a5276','#7c3aed','#2e6b46','#d68910','#128c7e'];
    if(canvas2._chartInst) canvas2._chartInst.destroy();
    if(mats.length===0){
      canvas2.parentElement.innerHTML='<div style="display:flex;align-items:center;justify-content:center;height:100%;color:#aaa;font-size:.85rem">Sem dados de estoque</div>';
    } else {
      canvas2._chartInst=new Chart(canvas2,{
        type:'doughnut',
        data:{
          labels:mats,
          datasets:[{data:vals,backgroundColor:COLORS.slice(0,mats.length),borderWidth:2,borderColor:'#fff'}]
        },
        options:{responsive:true,maintainAspectRatio:false,cutout:'62%',
          plugins:{legend:{position:'right',labels:{font:{family:"'Inter',sans-serif",size:11},boxWidth:12,padding:8}},
            tooltip:{callbacks:{label:ctx=>ctx.label+': '+Number(ctx.raw).toLocaleString('pt-BR')+'kg'}}}
        }
      });
    }
  }
}

