function imprimirCanhoto(){
  const t=document.getElementById('ticket-input').value.toUpperCase().trim();
  const tk=TICKETS_DB[t];
  if(!tk){alert('Nenhum ticket selecionado.');return;}

  const fmt=v=>_numFinito(v,0).toLocaleString('pt-BR',{minimumFractionDigits:2});
  const fornCod=tk.fornecedorCod||tk.fornCod||'';

  
  const adtsNaoQuit=(ADT_POR_FORN[fornCod]||[]).filter(a=>a.status!=='Quitado'&&Number(a.valor||0)>0);
  const totalAdtNQ=adtsNaoQuit.reduce((s,a)=>s+Number(a.valor||0),0);

  
  const sdRaw=SALDO_DEVEDOR_FORN[fornCod];
  const sdValor=sdRaw?(typeof sdRaw==='object'?(sdRaw.valor||0):Number(sdRaw||0)):0;
  const sdData=sdRaw&&typeof sdRaw==='object'?sdRaw.data:'';

  const itensRows=tk.itens.map((it,i)=>
    `<tr><td style="padding:5px 8px;text-align:center">${i+1}</td>
     <td style="padding:5px 8px">${it.mat}</td>
     <td style="padding:5px 8px">${it.ident||it.qual||''}</td>
     <td style="padding:5px 8px;text-align:right">${Number(it.pesoLiq).toLocaleString('pt-BR',{minimumFractionDigits:1})} kg</td>
     <td style="padding:5px 8px;text-align:right">R$ ${Number(it.preco).toFixed(2).replace('.',',')}</td>
     <td style="padding:5px 8px;text-align:right"><b>R$ ${fmt(it.total)}</b></td></tr>`
  ).join('');

  const negativo=tk.saldoPagar<0;

  let extrasHtml='';
  if(sdValor>0){
    extrasHtml+=`<tr style="background:#fff3cd;color:#856404;font-weight:700">
      <td colspan="5" style="padding:6px 8px;text-align:right">⚠️ Saldo Negativo Anterior${sdData?' ('+sdData+')':''}</td>
      <td style="padding:6px 8px;text-align:right">+R$ ${fmt(sdValor)}</td>
    </tr>`;
  }
  if(adtsNaoQuit.length>0){
    adtsNaoQuit.forEach(a=>{
      extrasHtml+=`<tr style="color:#e67e22">
        <td colspan="5" style="padding:4px 8px;text-align:right;font-size:11px">💰 Adiantamento não quitado – ${fmtDate(a.data)||''}</td>
        <td style="padding:4px 8px;text-align:right;font-size:11px">R$ ${fmt(a.valor)}</td>
      </tr>`;
    });
  }

  const win=window.open('','_blank','width=700,height=900');
  win.document.write(`<!DOCTYPE html><html lang="pt-BR"><head>
  <meta charset="UTF-8"><title>Recibo ${tk.ticket} – ${_empresaPrincipalLabel()}</title>
  <style>
    body{font-family:'Segoe UI',Arial,sans-serif;padding:28px;color:#111;font-size:13px}
    .logo{font-size:22px;font-weight:900;color:#1a3a2a;letter-spacing:1px}
    .logo span{color:#c8a400}
    .sub{color:#555;font-size:11px;margin-bottom:2px}
    .titulo{text-align:center;font-size:14px;font-weight:800;border:2px solid #333;padding:8px;border-radius:4px;margin:14px 0;letter-spacing:1px}
    table{width:100%;border-collapse:collapse;font-size:12px}
    th{background:#1a3a2a;color:#fff;padding:7px 8px;text-align:left}
    td{border-bottom:1px solid #eee}
    .info-grid{display:grid;grid-template-columns:1fr 1fr;gap:3px 14px;margin-bottom:12px;font-size:12px}
    .footer{margin-top:20px;text-align:center;font-size:11px;color:#888;border-top:1px solid #ddd;padding-top:10px}
    @media print{body{padding:12px}button{display:none}}
  </style></head><body>
  <div style="text-align:center;margin-bottom:8px">
    <div class="logo">${_empresaLogoHtml()}</div>
    <div class="sub">${_empresaPrincipalRazao()} · CNPJ: ${_empresaPrincipalInfo().cnpj||''}</div>
    <div class="sub">${_empresaPrincipalEnderecoCurto()} · 📞 ${_empresaPrincipalTelefonesInline()}</div>
    <div class="sub">IE: ${_empresaPrincipalInfo().ie||''} · ${_empresaPrincipalInfo().email||''}</div>
  </div>
  <div class="titulo">RECIBO DE COMPRA DE SUCATA</div>
  <div class="info-grid">
    <div><b style="color:#555">Ticket Nº:</b> ${tk.ticket}</div>
    <div><b style="color:#555">Data:</b> ${fmtDate(tk.data)||'—'}</div>
    <div><b style="color:#555">Fornecedor:</b> <b>${tk.fornecedor}</b></div>
    <div><b style="color:#555">Responsável:</b> ${tk.resp||'—'}</div>
    <div><b style="color:#555">Adiantamento:</b> R$ ${fmt(tk.adiantamento)}</div>
    <div><b style="color:#555">Status:</b> ${tk.status||'Pendente'}</div>
  </div>
  <table>
    <thead><tr><th>#</th><th>Material</th><th>Identificação</th><th style="text-align:right">Peso Líq.(kg)</th><th style="text-align:right">R$/kg</th><th style="text-align:right">Total R$</th></tr></thead>
    <tbody>
      ${itensRows}
      <tr style="background:#e8f5e9;font-weight:800">
        <td colspan="5" style="padding:7px 8px;text-align:right">TOTAL</td>
        <td style="padding:7px 8px;text-align:right">R$ ${fmt(tk.totalGeral)}</td>
      </tr>
      <tr style="color:#e67e22;font-weight:700">
        <td colspan="5" style="padding:5px 8px;text-align:right">(-) Adiantamento desta compra</td>
        <td style="padding:5px 8px;text-align:right">R$ ${fmt(tk.adiantamento)}</td>
      </tr>
      ${_adtDescontadosRowsHtml(tk,fmt)}
      ${extrasHtml}
      <tr style="background:${negativo?'#ffd5d5':'#d5f0e0'};font-weight:900;font-size:13px">
        <td colspan="5" style="padding:9px 8px;text-align:right;color:${negativo?'#c0392b':'#1a3a2a'}">${negativo?'⚠️ FORNECEDOR DEVE À EMPRESA':'SALDO A PAGAR'}</td>
        <td style="padding:9px 8px;text-align:right;color:${negativo?'#c0392b':'#1a3a2a'}">R$ ${fmt(Math.abs(tk.saldoPagar))}</td>
      </tr>
    </tbody>
  </table>
  <div style="margin-top:36px;display:grid;grid-template-columns:1fr 1fr;gap:20px">
    <div style="border-top:1px solid #333;padding-top:6px;text-align:center;font-size:11px">Assinatura do Fornecedor</div>
    <div style="border-top:1px solid #333;padding-top:6px;text-align:center;font-size:11px">Responsável ${_empresaPrincipalRazao()}</div>
  </div>
  <div class="footer">${_empresaPrincipalLabel()} · ${_empresaPrincipalTelefonesInline()} · ${_empresaPrincipalInfo().email||''}</div>
  <div style="text-align:center;margin-top:14px">
    <button onclick="window.print()" style="background:#1a3a2a;color:#fff;border:none;padding:10px 24px;border-radius:6px;font-size:13px;font-weight:700;cursor:pointer">🖨️ Imprimir / Salvar PDF</button>
  </div>
  </body></html>`);
  win.document.close();
  setTimeout(()=>win.focus(),300);
}

async function compartilharImagem(){
  const t=document.getElementById('ticket-input').value.toUpperCase().trim();
  const tk=TICKETS_DB[t];
  if(!tk){alert('Nenhum ticket selecionado.');return;}

  const btn=document.querySelector('.btn-img');
  btn.textContent='⏳ Gerando imagem...';
  btn.disabled=true;

  const fmt=v=>_numFinito(v,0).toLocaleString('pt-BR',{minimumFractionDigits:2});
  const fornCod=tk.fornecedorCod||tk.fornCod||'';

  const adtsNaoQuit=(ADT_POR_FORN[fornCod]||[]).filter(a=>a.status!=='Quitado'&&Number(a.valor||0)>0);
  const sdRaw=SALDO_DEVEDOR_FORN[fornCod];
  const sdValor=sdRaw?(typeof sdRaw==='object'?(sdRaw.valor||0):Number(sdRaw||0)):0;
  const sdData=sdRaw&&typeof sdRaw==='object'?sdRaw.data:'';
  const negativo=tk.saldoPagar<0;

  const itensRows=tk.itens.map((it,i)=>
    `<tr><td style="padding:4px 7px;text-align:center;border-bottom:1px solid #eee">${i+1}</td>
     <td style="padding:4px 7px;border-bottom:1px solid #eee">${it.mat}</td>
     <td style="padding:4px 7px;border-bottom:1px solid #eee">${it.ident||it.qual||''}</td>
     <td style="padding:4px 7px;text-align:right;border-bottom:1px solid #eee">${Number(it.pesoLiq).toLocaleString('pt-BR',{minimumFractionDigits:1})} kg</td>
     <td style="padding:4px 7px;text-align:right;border-bottom:1px solid #eee">R$ ${Number(it.preco).toFixed(2).replace('.',',')}</td>
     <td style="padding:4px 7px;text-align:right;border-bottom:1px solid #eee"><b>R$ ${fmt(it.total)}</b></td></tr>`
  ).join('');

  let extrasHtml='';
  if(sdValor>0){
    extrasHtml+=`<tr style="background:#fff3cd;color:#856404;font-weight:700">
      <td colspan="5" style="padding:5px 7px;text-align:right">⚠️ Saldo Negativo Anterior${sdData?' ('+sdData+')':''}</td>
      <td style="padding:5px 7px;text-align:right">+R$ ${fmt(sdValor)}</td></tr>`;
  }
  adtsNaoQuit.forEach(a=>{
    extrasHtml+=`<tr style="color:#e67e22">
      <td colspan="5" style="padding:3px 7px;text-align:right;font-size:11px">💰 Adiantamento não quitado – ${fmtDate(a.data)||''}</td>
      <td style="padding:3px 7px;text-align:right;font-size:11px">R$ ${fmt(a.valor)}</td></tr>`;
  });

  const wrapper=document.createElement('div');
  wrapper.style.cssText='position:fixed;left:-9999px;top:0;width:620px;background:#fff;padding:32px;font-family:Segoe UI,Arial,sans-serif;font-size:13px;color:#111;z-index:-1';
  wrapper.innerHTML=`
    <div style="text-align:center;margin-bottom:10px">
      <div style="font-size:22px;font-weight:900;color:#1a3a2a;letter-spacing:1px">${esc(_empresaPrincipalLabel())}</div>
      <div style="font-size:11px;color:#555;margin-top:2px">${_empresaPrincipalRazao()} · CNPJ: ${_empresaPrincipalInfo().cnpj||''}</div>
      <div style="font-size:11px;color:#555">${_empresaPrincipalEnderecoCurto()} · 📞 ${[_empresaPrincipalInfo().financeiro,_empresaPrincipalInfo().escritorio].filter(Boolean).join(' · ')}</div>
    </div>
    <div style="text-align:center;font-size:14px;font-weight:800;border:2px solid #333;padding:8px;border-radius:4px;margin:12px 0;letter-spacing:1px">RECIBO DE COMPRA DE SUCATA</div>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:3px 14px;margin-bottom:12px;font-size:12px">
      <div><b style="color:#555">Ticket Nº:</b> ${tk.ticket}</div>
      <div><b style="color:#555">Data:</b> ${fmtDate(tk.data)||'—'}</div>
      <div><b style="color:#555">Fornecedor:</b> <b>${tk.fornecedor}</b></div>
      <div><b style="color:#555">Responsável:</b> ${tk.resp||'—'}</div>
      <div><b style="color:#555">Adiantamento:</b> R$ ${fmt(tk.adiantamento)}</div>
      <div><b style="color:#555">Status:</b> ${tk.status||'Pendente'}</div>
    </div>
    <table style="width:100%;border-collapse:collapse;font-size:12px">
      <thead><tr style="background:#1a3a2a;color:#fff">
        <th style="padding:6px 7px;text-align:left">#</th><th style="text-align:left">Material</th>
        <th style="text-align:left">Ident.</th><th style="text-align:right">Peso(kg)</th>
        <th style="text-align:right">R$/kg</th><th style="text-align:right">Total</th>
      </tr></thead>
      <tbody>
        ${itensRows}
        <tr style="background:#e8f5e9;font-weight:800">
          <td colspan="5" style="padding:7px 7px;text-align:right">TOTAL</td>
          <td style="padding:7px 7px;text-align:right">R$ ${fmt(tk.totalGeral)}</td>
        </tr>
        <tr style="color:#e67e22;font-weight:700">
          <td colspan="5" style="padding:5px 7px;text-align:right">(-) Adiantamento desta compra</td>
          <td style="padding:5px 7px;text-align:right">R$ ${fmt(tk.adiantamento)}</td>
        </tr>
        ${_adtDescontadosRowsHtml(tk,fmt,7)}
        ${extrasHtml}
        <tr style="background:${negativo?'#ffd5d5':'#d5f0e0'};font-weight:900;font-size:13px">
          <td colspan="5" style="padding:9px 7px;text-align:right;color:${negativo?'#c0392b':'#1a3a2a'}">${negativo?'⚠️ FORNECEDOR DEVE À EMPRESA':'SALDO A PAGAR'}</td>
          <td style="padding:9px 7px;text-align:right;color:${negativo?'#c0392b':'#1a3a2a'}">R$ ${fmt(Math.abs(tk.saldoPagar))}</td>
        </tr>
      </tbody>
    </table>
    <div style="margin-top:32px;display:grid;grid-template-columns:1fr 1fr;gap:20px">
      <div style="border-top:1px solid #333;padding-top:5px;text-align:center;font-size:11px">Assinatura do Fornecedor</div>
      <div style="border-top:1px solid #333;padding-top:5px;text-align:center;font-size:11px">Responsável ${_empresaPrincipalRazao()}</div>
    </div>
    <div style="margin-top:12px;text-align:center;font-size:10px;color:#888;border-top:1px solid #ddd;padding-top:8px">
      ${_empresaPrincipalLabel()} · ${[_empresaPrincipalInfo().financeiro,_empresaPrincipalInfo().escritorio].filter(Boolean).join(' · ')} · ${_empresaPrincipalInfo().email||''}
    </div>`;
  document.body.appendChild(wrapper);

  try{
    const canvas=await html2canvas(wrapper,{scale:2,useCORS:true,backgroundColor:'#ffffff',logging:false});
    document.body.removeChild(wrapper);
    canvas.toBlob(async(blob)=>{
      const fileName=`recibo-${tk.ticket}.png`;
      const file=new File([blob],fileName,{type:'image/png'});
      if(navigator.share&&navigator.canShare&&navigator.canShare({files:[file]})){
        try{await navigator.share({files:[file],title:`Recibo ${tk.ticket} – ${_empresaPrincipalLabel()}`});}catch(e){}
      } else {
        const url=URL.createObjectURL(blob);
        const a=document.createElement('a');
        a.href=url;a.download=fileName;a.click();
        URL.revokeObjectURL(url);
        alert('✅ Imagem salva!\nAbra o WhatsApp e envie o arquivo "'+fileName+'" para o fornecedor.');
      }
      btn.innerHTML='📷 Salvar Imagem p/ WhatsApp';
      btn.disabled=false;
    },'image/png');
  }catch(e){
    document.body.removeChild(wrapper);
    btn.innerHTML='📷 Salvar Imagem p/ WhatsApp';
    btn.disabled=false;
    alert('Erro ao gerar imagem: '+e.message);
  }
}



async function abrirEdicaoDadosEmpresa(){
  if(!_usuarioAtualEhElaine()){alert('Somente Elaine pode editar os dados da empresa.');return;}
  const cfg=(window.__PUBLIC_BUSINESS_CONFIG__||{});
  const info=cfg.company||_empresaPrincipalInfo();
  const brand=cfg.branding||ERP_BUSINESS_CONFIG.branding||{};
  const body=document.getElementById('modal-body');if(!body)return;
  const companyFields=[['nome','Nome fantasia'],['razaoSocial','Razão social'],['cnpj','CNPJ'],['ie','IE'],['endereco','Endereço'],['enderecoCurto','Endereço curto'],['financeiro','Telefone financeiro'],['escritorio','Telefone escritório'],['compras','Telefone compras/vendas'],['email','E-mail'],['responsavel','Responsável']];
  const brandFields=[['logoPrefix','Logo — início'],['logoAccent','Logo — destaque'],['tagline','Subtítulo do sistema'],['title','Título da aba']];
  const field=(obj,prefix,pair)=>'<div class="fg"><label>'+esc(pair[1])+'</label><input id="cfg-'+prefix+'-'+pair[0]+'" value="'+esc(obj[pair[0]]||'')+'" maxlength="256" style="width:100%"></div>';
  body.className='modal';
  body.innerHTML='<h3>✏️ Dados da Empresa Principal</h3><p style="font-size:.8rem;color:#666">Atualiza a empresa principal, o cabeçalho e o login. Ao trocar o nome fantasia sem mexer na identidade visual, a marca do cabeçalho/login acompanha o novo nome. Outras empresas do grupo permanecem independentes.</p>'+
    '<div style="max-height:62vh;overflow:auto">'+companyFields.map(p=>field(info,'company',p)).join('')+
    '<h4>Identidade visual</h4>'+brandFields.map(p=>field(brand,'brand',p)).join('')+'</div>'+
    '<div class="modal-ft"><button class="btn-cancel" onclick="cm()">Cancelar</button><button class="btn-save" onclick="salvarEdicaoDadosEmpresa()">💾 Salvar no Firebase</button></div>';
  document.getElementById('modal-ov').classList.add('open');
}
async function salvarEdicaoDadosEmpresa(){
  if(!_usuarioAtualEhElaine())return;
  const fields=['nome','razaoSocial','cnpj','ie','endereco','enderecoCurto','financeiro','escritorio','compras','email','responsavel'];
  const bfields=['logoPrefix','logoAccent','tagline','title'];
  const collect=(names,prefix)=>Object.fromEntries(names.map(n=>[n,document.getElementById('cfg-'+prefix+'-'+n)?.value||'']));
  const btn=document.querySelector('#modal-body .btn-save');if(btn)btn.disabled=true;
  try{
    const company=collect(fields,'company'),branding=collect(bfields,'brand');
    const previous=window.__PUBLIC_BUSINESS_CONFIG__||{},oldBrand=previous.branding||{};
    
    
    const nomeMudou=company.nome && company.nome!==(previous.company||{}).nome;
    const marcaInalterada=branding.logoPrefix===(oldBrand.logoPrefix||'') && branding.logoAccent===(oldBrand.logoAccent||'');
    if(nomeMudou&&marcaInalterada){branding.logoPrefix=company.nome;branding.logoAccent='';}
    const token=await firebase.auth().currentUser.getIdToken();
    const response=await fetch('/api/admin/branding',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json',Authorization:'Bearer '+token},
      body:JSON.stringify({company,branding})});
    const result=await response.json();
    if(!response.ok)throw new Error(result.message||'Firebase não confirmou a alteração.');
    showToast('Dados institucionais confirmados no Firebase. Atualizando...','success');
    window.location.reload();
  }catch(error){if(btn)btn.disabled=false;alert('Não foi possível salvar: '+error.message);}
}



let EMPRESAS_INFO = {};
let ERP_BUSINESS_CONFIG = {};

function _empresaPrincipalChave(){
  const cfg=(ERP_BUSINESS_CONFIG&&ERP_BUSINESS_CONFIG.primaryCompanyKey)||'';
  if(cfg && EMPRESAS_INFO && EMPRESAS_INFO[cfg]) return cfg;
  const ks=Object.keys(EMPRESAS_INFO||{});
  return ks[0]||'';
}
function _empresaPrincipalInfo(){ const k=_empresaPrincipalChave(); return k?(EMPRESAS_INFO[k]||{}):{}; }
function _empresaPrincipalLabel(){ const k=_empresaPrincipalChave(), e=_empresaPrincipalInfo(); return k||e.nome||e.razaoSocial||''; }
function _empresaPrincipalRazao(){ const e=_empresaPrincipalInfo(); return e.razaoSocial||e.nome||_empresaPrincipalLabel(); }
function _empresaPrincipalResponsavel(){ const e=_empresaPrincipalInfo(); return e.responsavel||_usuarioAdminNome(); }
function _empresaLogoHtml(){
  const b=(ERP_BUSINESS_CONFIG&&ERP_BUSINESS_CONFIG.branding)||{};
  const pre=String(b.logoPrefix||_empresaPrincipalLabel()||'');
  const acc=String(b.logoAccent||'');
  return esc(pre)+(acc?'<span>'+esc(acc)+'</span>':'');
}
function _empresaPrincipalEnderecoCurto(){ const e=_empresaPrincipalInfo(); return e.enderecoCurto||e.endereco||''; }
function _empresaPorTexto(valor){
  const raw=String(valor||'').toLowerCase();
  const digits=raw.replace(/\D/g,'');
  const entries=Object.entries(EMPRESAS_INFO||{});
  for(const [key,e] of entries){
    const candidates=[key,e&&e.nome,e&&e.razaoSocial,e&&e.cnpj].filter(Boolean).map(x=>String(x));
    if(candidates.some(function(x){ const low=x.toLowerCase(); const d=x.replace(/\D/g,''); return (low&&raw.includes(low))||(d.length>=8&&digits.includes(d)); })) return key;
  }
  return _empresaPrincipalChave();
}
function _cfgPublicBusiness(){
  return window.__PUBLIC_BUSINESS_CONFIG__&&typeof window.__PUBLIC_BUSINESS_CONFIG__==='object'?window.__PUBLIC_BUSINESS_CONFIG__:{};
}
function _cfgRegisteredCompanies(){
  const out=[], seen={};
  function add(v){
    const x=String(v||'').trim();
    if(!x||seen[x.toLowerCase()]) return;
    seen[x.toLowerCase()]=1;
    out.push(x);
  }
  const pub=_cfgPublicBusiness();
  const primary=String((ERP_BUSINESS_CONFIG&&ERP_BUSINESS_CONFIG.primaryCompanyKey)||(pub.company&&pub.company.key)||'').trim();
  add(primary);
  Object.keys((ERP_BUSINESS_CONFIG&&ERP_BUSINESS_CONFIG.companies)||{}).forEach(add);
  Object.keys(EMPRESAS_INFO||{}).forEach(add);
  (Array.isArray(pub.companyKeys)?pub.companyKeys:[]).forEach(add);
  (Array.isArray(ERP_BUSINESS_CONFIG.financeCompanies)?ERP_BUSINESS_CONFIG.financeCompanies:[]).forEach(add);
  (Array.isArray(pub.financeCompanies)?pub.financeCompanies:[]).forEach(add);
  (Array.isArray(ERP_BUSINESS_CONFIG.transferCompanies)?ERP_BUSINESS_CONFIG.transferCompanies:[]).forEach(add);
  (Array.isArray(pub.transferCompanies)?pub.transferCompanies:[]).forEach(add);
  return out;
}
function _cfgFinanceCompanies(){
  const a=Array.isArray(ERP_BUSINESS_CONFIG.financeCompanies)?ERP_BUSINESS_CONFIG.financeCompanies:[];
  const pub=_cfgPublicBusiness();
  const b=Array.isArray(pub.financeCompanies)?pub.financeCompanies:[];
  return a.length?a.slice():(b.length?b.slice():_cfgRegisteredCompanies());
}
function _cfgFinanceCompanyColor(company){
  const colors=['#1a5e2a','#8e44ad','#c0392b']; 
  const i=_cfgFinanceCompanies().indexOf(String(company||''));
  return i>=0&&i<colors.length?colors[i]:'#888';
}
function _cfgEmployeeCompanies(){
  const a=Array.isArray(ERP_BUSINESS_CONFIG.employeeCompanies)?ERP_BUSINESS_CONFIG.employeeCompanies:[];
  const pub=_cfgPublicBusiness();
  const b=Array.isArray(pub.employeeCompanies)?pub.employeeCompanies:[];
  return a.length?a.slice():b.slice();
}
function _cfgTransferCompanies(){
  const a=Array.isArray(ERP_BUSINESS_CONFIG.transferCompanies)?ERP_BUSINESS_CONFIG.transferCompanies:[];
  const pub=_cfgPublicBusiness();
  const b=Array.isArray(pub.transferCompanies)?pub.transferCompanies:[];
  return a.length?a.slice():(b.length?b.slice():_cfgRegisteredCompanies());
}
function _cfgChequeCompanies(){
  const a=Array.isArray(ERP_BUSINESS_CONFIG.chequeCompanies)?ERP_BUSINESS_CONFIG.chequeCompanies:[];
  return a.length?a.slice():_cfgRegisteredCompanies();
}
function _cfgExpenseGroupCompanyMap(){
  const m=ERP_BUSINESS_CONFIG&&ERP_BUSINESS_CONFIG.expenseGroupCompanyMap;
  return m&&typeof m==='object'?m:{};
}
function _cfgExpenseGroupForCompany(company){
  const map=_cfgExpenseGroupCompanyMap();
  return map[company]||map[String(company||'').toUpperCase()]||String(company||'').toUpperCase();
}
function _cfgFiscalCompany(key){
  const all=ERP_BUSINESS_CONFIG&&ERP_BUSINESS_CONFIG.fiscalCompanies;
  const v=all&&typeof all==='object'?all[key]:null;
  return v&&typeof v==='object'?v:{};
}
function _cfgBankDisplayToken(key){
  const all=ERP_BUSINESS_CONFIG&&ERP_BUSINESS_CONFIG.bankDisplayTokens;
  return all&&typeof all==='object'&&all[key]?String(all[key]):'';
}
function _cfgEmployeeCompanyOptionsHtml(sel){
  const values=_cfgEmployeeCompanies();
  if(sel && values.indexOf(sel)<0) values.push(sel);
  return '<option value="">— Selecione —</option>'+values.map(function(v){return '<option value="'+esc(v)+'"'+(v===sel?' selected':'')+'>'+esc(v)+'</option>';}).join('');
}
function _empresaPrincipalContatosInline(){
  const e=_empresaPrincipalInfo(), a=[];
  if(e.financeiro) a.push('Financeiro: '+e.financeiro);
  if(e.escritorio) a.push('Escritório: '+e.escritorio);
  if(e.compras) a.push('Compras: '+e.compras);
  return a.join(' · ');
}
function _empresaPrincipalTelefonesInline(){
  const e=_empresaPrincipalInfo(); return [e.financeiro,e.escritorio,e.compras].filter(Boolean).join(' · ');
}
function _documentHeaderConfig(key){
  const all=(ERP_BUSINESS_CONFIG&&ERP_BUSINESS_CONFIG.documentHeaders)||{};
  return all[key]||{};
}
function _legacyRepairConfig(key){
  const all=(ERP_BUSINESS_CONFIG&&ERP_BUSINESS_CONFIG.legacyRepairs)||{};
  return all[key]||{};
}

function _cfgChequeBanks(){
  const legacy=Array.isArray(ERP_BUSINESS_CONFIG.chequeBanks)?ERP_BUSINESS_CONFIG.chequeBanks:[];
  const live=(typeof BANCOS_DB!=='undefined'&&Array.isArray(BANCOS_DB)?BANCOS_DB:[]).filter(function(b){
    if(!b||!String(b.banco||'').trim()) return false;
    const t=String(b.tipo||'').toLowerCase();
    return t.indexOf('aplica')<0&&t!=='caixa';
  });
  const palette=['#c0392b','#1565c0','#2e7d32','#e67e22','#8e44ad','#1a5276','#117864','#7d6608','#566573','#922b21'];
  return live.map(function(b,i){
    const name=String(b.banco||'').trim();
    const match=legacy.find(function(x){
      if(!x) return false;
      if(x.code&&b.cod&&String(x.code)===String(b.cod)) return true;
      const xn=String(x.name||'').toLowerCase(), bn=name.toLowerCase();
      return xn===bn||xn.indexOf(bn)>=0||bn.indexOf(xn)>=0;
    })||{};
    const code=String(b.cod||b.id||'');
    const slug=String(match.slug||code||name).replace(/[^A-Za-z0-9]/g,'').slice(-8).toUpperCase()||'BK'+String(i+1);
    return {name:name,code:code,slug:slug,color:String(match.color||palette[i%palette.length]),order:i+1,aliases:Array.isArray(match.aliases)?match.aliases:[]};
  });
}
function _cfgChequeBankNames(){
  const out=_cfgChequeBanks().map(x=>String(x.name||'')).filter(Boolean);
  const terceiro=String((ERP_BUSINESS_CONFIG&&ERP_BUSINESS_CONFIG.thirdPartyChequeBank)||'').trim();
  if(terceiro&&out.indexOf(terceiro)<0) out.push(terceiro);
  if(typeof CHQ_CTRL==='object'&&CHQ_CTRL){ Object.keys(CHQ_CTRL).forEach(function(k){ const b=String((CHQ_CTRL[k]&&CHQ_CTRL[k].b)||'').trim(); if(b&&out.indexOf(b)<0) out.push(b); }); }
  return out;
}
function _cfgChequeBank(name){
  const target=String(name||'');
  const live=_cfgChequeBanks().find(x=>String(x.name||'')===target);
  if(live) return live;
  const legacy=Array.isArray(ERP_BUSINESS_CONFIG.chequeBanks)?ERP_BUSINESS_CONFIG.chequeBanks:[];
  return legacy.find(x=>String(x.name||'')===target)||null;
}
function _cfgChequeBankOptionsHtml(sel){
  const names=_cfgChequeBankNames();
  if(sel&&names.indexOf(sel)<0) names.push(sel);
  return names.map(b=>'<option value="'+esc(b)+'"'+(b===sel?' selected':'')+'>'+esc(b)+'</option>').join('');
}
function _cfgChequeBankSlug(name){ const x=_cfgChequeBank(name); return x&&x.slug?String(x.slug):String(name||'XX').replace(/[^A-Za-z0-9]/g,'').slice(0,8).toUpperCase()||'XX'; }
function _cfgChequeBankCode(name){ const x=_cfgChequeBank(name); return x&&x.code?String(x.code):''; }
function _cfgChequeBankColor(name){ const x=_cfgChequeBank(name); return x&&x.color?String(x.color):'#888'; }
function _cfgChequeBankNormalize(value){
  const raw=String(value||'').toLowerCase();
  const direct=_cfgChequeBanks().find(x=>String(x.name||'').toLowerCase()===raw);
  if(direct) return String(direct.name||'');
  const legacy=Array.isArray(ERP_BUSINESS_CONFIG.chequeBanks)?ERP_BUSINESS_CONFIG.chequeBanks:[];
  const item=legacy.find(x=>Array.isArray(x.aliases)&&x.aliases.some(a=>raw.includes(String(a).toLowerCase())));
  return item?String(item.name||''):String(value||'');
}
function _empresasOptions(sel, incluirOutra){
  const values=_cfgRegisteredCompanies();
  if(sel&&sel!=='Outra'&&values.indexOf(sel)<0) values.push(sel);
  const other=incluirOutra===false?'':'<option value="Outra"'+(sel==='Outra'?' selected':'')+'>Outra</option>';
  return values.map(function(k){return '<option value="'+esc(k)+'"'+(k===sel?' selected':'')+'>'+esc(k)+'</option>';}).join('')+other;
}
function _sincronizarEmpresaPorBanco(bancoSelId, empresaSelId){
  const bs=document.getElementById(bancoSelId), es=document.getElementById(empresaSelId);
  if(!bs||!es) return;
  const val=bs.value;
  if(!val) return;
  const b=(BANCOS_DB||[]).find(x=>String(x.cod||'')===String(val)||String(x.banco||'')===String(val));
  if(!b||!b.empresa) return;
  const empresa=String(b.empresa||'').trim();
  if(es.tagName==='SELECT'){
    if(![...es.options].some(function(o){return o.value===empresa;})) es.insertAdjacentHTML('beforeend','<option value="'+esc(empresa)+'">'+esc(empresa)+'</option>');
    es.value=empresa;
  }else es.value=empresa;
}
function _erpRefreshCompanySources(){
  const transfer=_cfgTransferCompanies();
  const dl=document.getElementById('dlist-empresas');
  if(dl) dl.innerHTML=transfer.map(function(v){return '<option value="'+esc(v)+'">';}).join('');
  function repop(id, blankLabel, incluirOutra){
    const el=document.getElementById(id); if(!el) return;
    const cur=el.value||'';
    el.innerHTML=(blankLabel?'<option value="">'+blankLabel+'</option>':'')+_empresasOptions(cur,incluirOutra);
    if(cur&&[...el.options].some(function(o){return o.value===cur;})) el.value=cur;
  }
  repop('cp-empresa','— Selecione a empresa —',true);
  repop('ecp-empresa','— Selecione a empresa —',true);
  repop('bc-empresa','',true);
  repop('eb-empresa','',true);
}
window.__erpRefreshCompanySources=_erpRefreshCompanySources;
function _bcPreencheEndereco(selId, endId){
  const sel=document.getElementById(selId), end=document.getElementById(endId);
  if(!sel||!end) return;
  if(end.value.trim()) return; 
  const info=EMPRESAS_INFO[sel.value];
  if(info && info.endereco) end.value=info.endereco;
}


