const PRECOS_CLI_DATA = {};   







const ADT_POR_FORN = {};





var FISCAL_DB = {};

var FISCAL_APUR = {};
function saveFiscalApur(){ try{ localStorage.setItem('mm_fiscal_apur', JSON.stringify(FISCAL_APUR)); }catch(_){ } if(typeof fbSalvar==='function') fbSalvar(); }
function fiscalApurSeed(){
  
}




let FISCAL_LANC_SEED_2026 = {};
function fiscalLancamentosSeed(){
  if(typeof FISCAL_LANC_SEED_2026==='undefined') return;
  if(FISCAL_DB.__lancSeed2026Done) return;
  Object.keys(FISCAL_LANC_SEED_2026).forEach(mm=>{
    const chave='2026-'+mm;
    const seed=FISCAL_LANC_SEED_2026[mm];
    const saidas=(seed.saidasVenda||[]).concat(seed.saidasDespesa||[]);
    const existente=FISCAL_DB[chave];
    const existenteTemDadosReais = existente && (
      (existente.entradas||[]).some(e=>Number(e.valorTotal)>0) ||
      (existente.saidas||[]).some(s=>Number(s.valorTotal)>0)
    );
    if(mm==='07'){
      
      
      if(existente){
        try{ localStorage.setItem('mm_backup_fiscal_2026-07_'+Date.now(), JSON.stringify(existente)); }catch(_){}
      }
      FISCAL_DB[chave] = { entradas:seed.entradas, saidas:saidas, impostos:(existente&&existente.impostos)||{} };
    } else if(!existenteTemDadosReais){
      FISCAL_DB[chave] = { entradas:seed.entradas, saidas:saidas, impostos:(existente&&existente.impostos)||{} };
    }
    
  });
  FISCAL_DB.__lancSeed2026Done = true;
  fiscalSalvar();
}
let FISCAL_KG_PATCH_2026 = {};

function fiscalKgEnrich2026(){
  if(typeof FISCAL_KG_PATCH_2026==='undefined') return;
  if(FISCAL_DB.__kgEnrich2026V5Done) return;
  Object.keys(FISCAL_KG_PATCH_2026).forEach(mm=>{
    const chave='2026-'+mm;
    const db=FISCAL_DB[chave];
    if(!db) return;
    const p=FISCAL_KG_PATCH_2026[mm];
    (p.entradas||[]).forEach(pe=>{
      const alvo=(db.entradas||[]).find(e=>e.num===pe.num);
      if(alvo) alvo.itens = pe.itens;
    });
    (p.saidas||[]).forEach(ps=>{
      const alvo=(db.saidas||[]).find(s=>s.num===ps.num);
      if(alvo) alvo.itens = ps.itens;
    });
  });
  FISCAL_DB.__kgEnrich2026Done = true;
  FISCAL_DB.__kgEnrich2026V2Done = true;
  FISCAL_DB.__kgEnrich2026V3Done = true;
  FISCAL_DB.__kgEnrich2026V4Done = true;
  FISCAL_DB.__kgEnrich2026V5Done = true;
  fiscalSalvar();
}





let FISCAL_KG_PATCH_2026_V6 = {};
function fiscalKgEnrichV6_2026(){
  if(typeof FISCAL_KG_PATCH_2026_V6==='undefined') return;
  if(FISCAL_DB.__kgEnrich2026V6Done) return;
  Object.keys(FISCAL_KG_PATCH_2026_V6).forEach(mm=>{
    const chave='2026-'+mm;
    const db=FISCAL_DB[chave];
    if(!db) return;
    FISCAL_KG_PATCH_2026_V6[mm].forEach(pe=>{
      const alvo=(db.entradas||[]).find(e=>e.num===pe.num && e.fornecedor===pe.fornecedor);
      if(alvo) alvo.itens = pe.itens;
    });
  });
  FISCAL_DB.__kgEnrich2026V6Done = true;
  fiscalSalvar();
}









let FISCAL_ENTRADA_PATCH_NF4954 = {};
