function saveUsers(){
  try{ localStorage.setItem('mm_users_del', JSON.stringify(_USERS_DEL)); }catch(e){}
  localStorage.setItem('mm_users', JSON.stringify(
    Object.fromEntries(Object.entries(USERS).map(([k,u])=>[k,{password:u.password,name:u.name,role:u.role,descricao:u.descricao,tabs:[...u.tabs],tabsCustom:!!u.tabsCustom}]))
  ));
  fbSalvar();
}
function loadUsers(){
  try{
    const u=localStorage.getItem('mm_users');
    if(u){
      const saved=JSON.parse(u);
      Object.entries(saved).forEach(([k,v])=>{
        if(_USERS_DEL.indexOf(k)>=0) return; 
        if(USERS[k]){
          
          if(v.password && v.password.trim()) USERS[k].password=v.password; 
          USERS[k].name=v.name||USERS[k].name;
          USERS[k].role=v.role||USERS[k].role;
          USERS[k].descricao=v.descricao||USERS[k].descricao;
          
          if(v.tabs){
            if(v.tabsCustom){
              
              
              USERS[k].tabs=[...v.tabs];
              USERS[k].tabsCustom=true;
            } else {
              
              
              const base=USERS[k].tabs;
              v.tabs.forEach(t=>{ if(!base.includes(t)) base.push(t); });
            }
          }
        } else {
          USERS[k]=v; 
        }
      });
    }
  }catch(e){console.warn('loadUsers error',e);}
  
  _usersAplicarTombstones();
}



function toggleCcParc(on){
  const box=document.getElementById('cc-parc-box');
  const dataBox=document.getElementById('cc-data-box');
  const statusBox=document.getElementById('cc-status-box');
  const pgBox=document.getElementById('cc-datapago-box');
  if(box) box.style.display=on?'block':'none';
  if(dataBox) dataBox.style.display=on?'none':'block';
  if(statusBox) statusBox.style.display=on?'none':'block';
  if(pgBox) pgBox.style.display=on?'none':'block';
  if(on) previewCcParc();
}
function previewCcParc(){
  const nparc=parseInt(document.getElementById('cc-nparc')?.value||'12');
  const dia=parseInt(document.getElementById('cc-diaparc')?.value||'10');
  const mes=document.getElementById('cc-mesparc')?.value;
  const prev=document.getElementById('cc-parc-prev');
  if(!prev)return;
  if(!mes){prev.style.display='none';return;}
  prev.style.display='block';
  prev.textContent='📅 '+nparc+' parcela(s), vencendo todo dia '+dia+', a partir de '+mes.replace('-','/');
}


let _ccArea = '';
function _ccConfigAreas(){
  const cfg=(ERP_BUSINESS_CONFIG&&Array.isArray(ERP_BUSINESS_CONFIG.homeCostAreas))?ERP_BUSINESS_CONFIG.homeCostAreas:[];
  const out=[];
  cfg.forEach(function(item){
    const obj=typeof item==='string'?{name:item}:item;
    const name=String((obj&&obj.name)||'').trim();
    if(!name||out.some(function(x){return x.name===name;})) return;
    out.push({name:name,icon:String((obj&&obj.icon)||'📌'),vehicleExpenses:!!(obj&&obj.vehicleExpenses)});
  });
  try{
    Object.keys(CUSTO_CASA||{}).forEach(function(mes){
      (CUSTO_CASA[mes]||[]).forEach(function(x){
        const name=String((x&&x.area)||'').trim();
        if(name&&!out.some(function(a){return a.name===name;})) out.push({name:name,icon:'📌',vehicleExpenses:false});
      });
    });
  }catch(e){}
  return out;
}
function _ccDefaultArea(){
  const cfg=String((ERP_BUSINESS_CONFIG&&ERP_BUSINESS_CONFIG.homeCostDefaultArea)||'').trim();
  const areas=_ccConfigAreas();
  if(cfg&&areas.some(function(x){return x.name===cfg;})) return cfg;
  return areas.length?areas[0].name:'';
}
function _ccVehicleArea(){
  const item=_ccConfigAreas().find(function(x){return x.vehicleExpenses;});
  return item?item.name:'';
}
function _ccAreaIcon(name){
  const item=_ccConfigAreas().find(function(x){return x.name===name;});
  return item?item.icon:'📌';
}
function _ccEnsureArea(){
  const areas=_ccConfigAreas();
  if(!_ccArea||(!areas.some(function(x){return x.name===_ccArea;})&&_ccArea!=='__resumo__')) _ccArea=_ccDefaultArea();
}
function _ccMatch(x){
  _ccEnsureArea();
  const fallback=_ccDefaultArea();
  return (x&&String(x.area||fallback))===_ccArea;
}
function _ccRenderAreaTabs(){
  const wrap=document.getElementById('cc-area-tabs');
  if(!wrap) return;
  _ccEnsureArea();
  const areas=_ccConfigAreas();
  wrap.innerHTML=areas.map(function(item){
    const ativo=item.name===_ccArea;
    return '<button data-cc-area="'+esc(item.name)+'" style="padding:8px 18px;border:none;border-bottom:3px solid '+(ativo?'#1a5e2a':'transparent')+';background:transparent;font-weight:700;font-size:.88rem;color:'+(ativo?'#1a5e2a':'#999')+';cursor:pointer">'+esc(item.icon)+' '+esc(item.name)+'</button>';
  }).join('')+'<button data-cc-area="__resumo__" style="padding:8px 18px;border:none;border-bottom:3px solid '+(_ccArea==='__resumo__'?'#8e44ad':'transparent')+';background:transparent;font-weight:800;font-size:.88rem;color:'+(_ccArea==='__resumo__'?'#8e44ad':'#8e44ad')+';cursor:pointer;margin-left:auto">📊 Resumo (Tudo)</button>';
  wrap.querySelectorAll('[data-cc-area]').forEach(function(btn){ btn.onclick=function(){ccSetArea(btn.getAttribute('data-cc-area')||'');}; });
}
function ccSetArea(a){
  const areas=_ccConfigAreas();
  if(a!=='__resumo__'&&!areas.some(function(x){return x.name===a;})) return;
  _ccArea=a;
  _ccRenderAreaTabs();
  renderCustoCasa();
}
function renderCustoCasa(){
  _ccEnsureArea();
  _ccRenderAreaTabs();
  const mesEl=document.getElementById('cc-filtro-mes');
  if(mesEl&&!mesEl.value) mesEl.value=new Date().toISOString().slice(0,7);
  const mes=mesEl?.value||new Date().toISOString().slice(0,7);
  const todas=(CUSTO_CASA[mes]||[]);
  const fmt=v=>Number(v||0).toLocaleString('pt-BR',{minimumFractionDigits:2});

  if(_ccArea==='__resumo__'){
    const areas=_ccConfigAreas();
    const vehicleArea=_ccVehicleArea();
    let gPrev=0,gPago=0;
    const linhasR=areas.map(function(item){
      const area=item.name;
      const ls=todas.filter(function(x){return String((x&&x.area)||_ccDefaultArea())===area;});
      let prev=ls.reduce((s,x)=>s+Number(x.valor||0),0);
      let pago=ls.filter(x=>x.pago).reduce((s,x)=>s+Number(x.valor||0),0);
      if(vehicleArea&&area===vehicleArea){
        const ml=MANUTPESS_DB.filter(function(m){return (m.mes||_mnpMes(m.data))===mes;});
        prev+=ml.reduce((s,m)=>s+Number(m.custo||0),0);
        pago+=ml.filter(m=>m.status==='Concluída').reduce((s,m)=>s+Number(m.custo||0),0);
      }
      gPrev+=prev; gPago+=pago;
      return '<tr>'
        +'<td style="font-weight:700">'+esc(item.icon||'📌')+' '+esc(area)+'</td>'
        +'<td style="text-align:center;color:#888">'+ls.length+'</td>'
        +'<td style="text-align:right;font-weight:700">R$ '+fmt(prev)+'</td>'
        +'<td style="text-align:right;color:#1a5c35">R$ '+fmt(pago)+'</td>'
        +'<td style="text-align:right;color:#c0392b;font-weight:700">R$ '+fmt(prev-pago)+'</td>'
        +'</tr>';
    }).join('');
    const kpisR=document.querySelectorAll('#tab-custo_casa .kpi');
    if(kpisR[0]){kpisR[0].querySelector('.kpi-val').textContent=mes.replace('-','/');kpisR[0].querySelector('.kpi-sub').textContent='Resumo de todas as áreas';}
    if(kpisR[1]) kpisR[1].querySelector('.kpi-val').textContent='R$ '+fmt(gPrev);
    if(kpisR[2]) kpisR[2].querySelector('.kpi-val').textContent='R$ '+fmt(gPago);
    if(kpisR[3]) kpisR[3].querySelector('.kpi-val').textContent='R$ '+fmt(gPrev-gPago);
    const tbR=document.getElementById('tb-custo-casa');
    if(tbR){
      tbR.innerHTML=linhasR
        +'<tr style="background:#f3e9fb;font-weight:900;color:#6a1b9a;border-top:2px solid #cbb2e0">'
        +'<td>💰 TOTAL GERAL</td><td style="text-align:center">'+todas.length+'</td>'
        +'<td style="text-align:right">R$ '+fmt(gPrev)+'</td>'
        +'<td style="text-align:right">R$ '+fmt(gPago)+'</td>'
        +'<td style="text-align:right">R$ '+fmt(gPrev-gPago)+'</td></tr>';
      const thead=tbR.closest('table')?.querySelector('thead tr');
      if(thead) thead.innerHTML='<th>Área</th><th style="text-align:center">Lançamentos</th><th style="text-align:right">Total Previsto</th><th style="text-align:right">Total Pago</th><th style="text-align:right">A Pagar</th>';
    }
    return;
  }
  (function(){ const _tb=document.getElementById('tb-custo-casa'); const _th=_tb&&_tb.closest('table')?_tb.closest('table').querySelector('thead tr'):null; if(_th) _th.innerHTML='<th>Nº</th><th>Vencimento</th><th>Descrição</th><th>Categoria</th><th style="text-align:right">Valor R$</th><th>Forma Pgto</th><th>Status</th><th>Pago em</th><th>Obs.</th><th>Ações</th>'; })();
  const ehVeic=!!_ccVehicleArea()&&_ccArea===_ccVehicleArea();
  const wrapV=document.getElementById('cc-veiculos-wrap');
  if(wrapV) wrapV.style.display=ehVeic?'block':'none';
  const tituloDesp=document.getElementById('cc-despesas-titulo');
  if(tituloDesp) tituloDesp.textContent=ehVeic?'Outras Despesas dos Veículos (IPVA, seguro, combustível…)':'Despesas do Mês';
  let manutPrev=0, manutPago=0;
  if(ehVeic){
    const mlist=MANUTPESS_DB.filter(function(m){return (m.mes||_mnpMes(m.data))===mes;});
    manutPrev=mlist.reduce((s,m)=>s+Number(m.custo||0),0);
    manutPago=mlist.filter(m=>m.status==='Concluída').reduce((s,m)=>s+Number(m.custo||0),0);
    renderVeicPess(); renderManutPess();
  }
  const lista=todas.map(function(x,i){return {x:x,i:i};}).filter(function(o){return _ccMatch(o.x);});
  const hoje=new Date().toISOString().slice(0,10);
  const totalPrev=lista.reduce((s,o)=>s+Number(o.x.valor||0),0)+manutPrev;
  const totalPago=lista.filter(o=>o.x.pago).reduce((s,o)=>s+Number(o.x.valor||0),0)+manutPago;
  const aPagar=totalPrev-totalPago;
  const kpis=document.querySelectorAll('#tab-custo_casa .kpi');
  if(kpis[0]){kpis[0].querySelector('.kpi-val').textContent=mes.replace('-','/');kpis[0].querySelector('.kpi-sub').textContent=_ccArea+' · '+lista.length+' lançamento(s)'+(ehVeic?' + manutenção':'');}
  if(kpis[1]) kpis[1].querySelector('.kpi-val').textContent='R$ '+fmt(totalPrev);
  if(kpis[2]) kpis[2].querySelector('.kpi-val').textContent='R$ '+fmt(totalPago);
  if(kpis[3]) kpis[3].querySelector('.kpi-val').textContent='R$ '+fmt(aPagar);
  const tb=document.getElementById('tb-custo-casa');
  if(!tb)return;
  if(!lista.length){tb.innerHTML='<tr><td colspan="10" style="color:var(--gray);text-align:center;padding:20px">Nenhuma despesa lançada ainda em '+esc(_ccArea)+'.</td></tr>';return;}
  tb.innerHTML='';
  lista.forEach(function(o,seq){
    const x=o.x, i=o.i;
    const atras=!x.pago&&x.venc&&x.venc<hoje;
    const tr=document.createElement('tr');
    if(atras) tr.style.background='#fff5f5';
    const pagoEmBR=x.dataPgto?(x.dataPgto.indexOf('/')>=0?x.dataPgto:x.dataPgto.split('-').reverse().join('/')):'';
    tr.innerHTML='<td>'+(seq+1)+'</td>'
      +'<td>'+(x.venc||'—')+'</td>'
      +'<td>'+esc(x.desc||'—')+'</td>'
      +'<td>'+esc(x.cat||'—')+'</td>'
      +'<td style="text-align:right;font-weight:700">R$ '+fmt(x.valor)+'</td>'
      +'<td>'+esc(x.forma||'—')+'</td>'
      +'<td><span class="b '+(x.pago?'b-pago':atras?'b-atrasado':'b-pendente')+'">'+(x.pago?'✅ Pago':atras?'🔴 Atrasado':'⏳ Pendente')+'</span></td>'
      +'<td style="white-space:nowrap;font-size:.82rem;color:'+(pagoEmBR?'#1a5c35':'#bbb')+'">'+(pagoEmBR||'—')+'</td>'
      +'<td>'+esc(x.obs||'—')+'</td>'
      +'<td style="white-space:nowrap"></td>';
    const tdAcao=tr.querySelector('td:last-child');
    const btnPago=document.createElement('button');
    btnPago.className='btn-edit'; btnPago.title=x.pago?'Desmarcar':'Marcar como pago'; btnPago.textContent='💰';
    btnPago.onclick=function(){ccTogglePago(mes,i);};
    const btnEd=document.createElement('button');
    btnEd.className='btn-edit'; btnEd.title='Editar (inclusive a data do pagamento)'; btnEd.textContent='✏️';
    btnEd.onclick=function(){ccEditar(mes,i);};
    const btnDel=document.createElement('button');
    btnDel.className='btn-edit-danger'; btnDel.textContent='🗑️';
    btnDel.onclick=function(){ccExcluir(mes,i);};
    tdAcao.appendChild(btnPago); tdAcao.appendChild(document.createTextNode(' ')); tdAcao.appendChild(btnEd); tdAcao.appendChild(document.createTextNode(' ')); tdAcao.appendChild(btnDel);
    tb.appendChild(tr);
  });
}

function ccTogglePago(mes,idx){
  if(!CUSTO_CASA[mes])return;
  const x=CUSTO_CASA[mes][idx]; if(!x)return;
  x.pago=!x.pago; x.dataPgto=x.pago?new Date().toISOString().slice(0,10):'';
  saveDB(); renderCustoCasa();
  showToast(x.pago?'✅ Marcado como pago!':'↩️ Marcado como pendente','success');
}
function ccExcluir(mes,idx){
  if(!confirm('Excluir esta despesa?'))return;
  CUSTO_CASA[mes].splice(idx,1);
  saveDB(); renderCustoCasa();
  showToast('Despesa excluída','success');
}


function ccEditar(mes,idx){
  const x=CUSTO_CASA[mes] && CUSTO_CASA[mes][idx];
  if(!x){ showToast('Despesa não encontrada.','error'); return; }
  const body=document.getElementById('modal-body');
  if(!body) return;
  body.className='modal';
  const vencISO=x.venc?(x.venc.indexOf('/')>=0?x.venc.split('/').reverse().join('-'):x.venc):'';
  const pgISO=x.dataPgto?(x.dataPgto.indexOf('/')>=0?x.dataPgto.split('/').reverse().join('-'):x.dataPgto):'';
  const stOpts=['Pendente','Pago','Agendado'].map(s=>'<option'+((x.pago&&s==='Pago')||(!x.pago&&s==='Pendente')?' selected':'')+'>'+s+'</option>').join('');
  body.innerHTML=
    '<h3>✏️ Editar Despesa da Casa</h3>'+
    '<div class="fg"><label>Descrição</label><input id="cce-desc" value="'+esc(x.desc||'')+'"></div>'+
    '<div class="fg"><label>Categoria</label><input id="cce-cat" value="'+esc(x.cat||'')+'"></div>'+
    '<div class="fg"><label>Valor R$</label><input id="cce-valor" type="number" min="0" step="0.01" value="'+(Number(x.valor)||0)+'"></div>'+
    '<div class="fg"><label>Vencimento</label><input id="cce-venc" type="date" value="'+vencISO+'"></div>'+
    '<div class="fg"><label>Status</label><select id="cce-status">'+stOpts+'</select></div>'+
    '<div class="fg"><label>Data do pagamento <span style="font-weight:400;color:var(--gray)">(pode ser uma data passada)</span></label><input id="cce-datapago" type="date" value="'+pgISO+'"></div>'+
    '<div class="fg"><label>Obs.</label><input id="cce-obs" value="'+esc(x.obs||'')+'"></div>'+
    '<div class="modal-ft"><button class="btn-cancel" onclick="cm()">Cancelar</button>'+
    '<button class="btn-save" onclick="ccSalvarEdicao(\''+mes+'\','+idx+')">💾 Salvar</button></div>';
  document.getElementById('modal-ov').classList.add('open');
}
function ccSalvarEdicao(mes,idx){
  const x=CUSTO_CASA[mes] && CUSTO_CASA[mes][idx];
  if(!x) return;
  x.desc=(document.getElementById('cce-desc')?.value||'').trim();
  x.cat=(document.getElementById('cce-cat')?.value||'').trim()||'Outros';
  x.valor=parseFloat(document.getElementById('cce-valor')?.value||'0')||0;
  const venc=document.getElementById('cce-venc')?.value||'';
  x.venc=venc;
  const status=document.getElementById('cce-status')?.value||'Pendente';
  x.pago=status==='Pago';
  const pg=document.getElementById('cce-datapago')?.value||'';
  x.dataPgto=x.pago?(pg||x.dataPgto||new Date().toISOString().slice(0,10)):'';
  x.obs=(document.getElementById('cce-obs')?.value||'').trim();
  saveDB(); renderCustoCasa(); cm();
  showToast('✅ Despesa atualizada!','success');
}
function salvarCustoCasa(){
  _ccEnsureArea();
  if(_ccArea==='__resumo__') _ccArea=_ccDefaultArea();
  if(!_ccArea){ alert('Configure ao menos uma área de custo no Firebase.'); return; }
  const mesEl=document.getElementById('cc-filtro-mes');
  const mes=mesEl?.value||new Date().toISOString().slice(0,7);
  const desc=(document.getElementById('cc-desc')?.value||'').trim();
  const cat=document.getElementById('cc-cat')?.value||'Outros';
  const valor=parseFloat(document.getElementById('cc-valor')?.value||'0');
  const forma=document.getElementById('cc-forma')?.value||'PIX';
  const obs=(document.getElementById('cc-obs')?.value||'').trim();
  const parcelado=document.getElementById('cc-parcelado')?.checked||false;
  const status=document.getElementById('cc-status')?.value||'Pendente';
  if(!desc){alert('Informe a descrição!');return;}
  if(!valor||valor<=0){alert('Informe um valor válido!');return;}
  if(!CUSTO_CASA[mes]) CUSTO_CASA[mes]=[];
  if(parcelado){
    const nparc=parseInt(document.getElementById('cc-nparc')?.value||'1');
    const dia=parseInt(document.getElementById('cc-diaparc')?.value||'10');
    const mesInicio=document.getElementById('cc-mesparc')?.value||mes;
    const [ano0,m0]=mesInicio.split('-').map(Number);
    for(let p=0;p<nparc;p++){
      let ma=m0+p; let ya=ano0+Math.floor((ma-1)/12); ma=((ma-1)%12)+1;
      const mesP=ya+'-'+String(ma).padStart(2,'0');
      const vencP=mesP+'-'+String(Math.min(dia,28)).padStart(2,'0');
      if(!CUSTO_CASA[mesP]) CUSTO_CASA[mesP]=[];
      CUSTO_CASA[mesP].push({desc:desc+' ('+(p+1)+'/'+nparc+')',cat,valor,venc:vencP,forma,obs,pago:false,dataPgto:'',area:_ccArea});
    }
    showToast('✅ '+nparc+' parcela(s) lançada(s) em '+_ccArea+'!','success');
  } else {
    const venc=document.getElementById('cc-data')?.value||'';
    const pago=status==='Pago';
    
    
    const dataPagoInput=document.getElementById('cc-datapago')?.value||'';
    const dataPgto=pago?(dataPagoInput||new Date().toISOString().slice(0,10)):'';
    CUSTO_CASA[mes].push({desc,cat,valor,venc,forma,obs,pago,dataPgto,area:_ccArea});
    showToast('✅ Despesa lançada em '+_ccArea+'!','success');
  }
  saveDB(); cm(); renderCustoCasa();
}


