async function _snapshotDiario(){
  try{
    if(!_usuarioAtualEhElaine() || !firebase.auth().currentUser) return;
    const key=_hojeISO();
    const token=await firebase.auth().currentUser.getIdToken();
    const response=await fetch('/api/admin/snapshots',{
      method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json',Authorization:'Bearer '+token},
      body:JSON.stringify({action:'snapshot',key})
    });
    if(!response.ok) throw new Error('Falha ao capturar snapshot do Firebase: '+response.status);
    
    _limparSnapshotsAntigos();
  }catch(e){ console.warn('_snapshotDiario:',e); }
}

function _limparSnapshotsAntigos(){
  
  
  
  
  try{
    if(!window._fbDB || typeof firebase==='undefined' || !firebase.auth || !firebase.auth().currentUser) return;
    firebase.auth().currentUser.getIdToken().then(function(tk){
      return fetch(window.__firebaseRestUrl('erp_snapshots', {shallow:'true', auth:tk})).then(function(r){ return r.json(); });
    }).then(function(d){
      if(!d) return;
      const chaves=Object.keys(d).filter(k=>/^\d{4}-\d{2}-\d{2}$/.test(k)).sort();
      const LIMITE=30;
      if(chaves.length>LIMITE){
        chaves.slice(0, chaves.length-LIMITE).forEach(k=>{
          window._fbDB.ref('erp_snapshots/'+k).remove().catch(()=>{});
        });
      }
    }).catch(function(){});
  }catch(e){}
}

function abrirSnapshots(){
  om('snapshots_diarios');
  const body=document.getElementById('modal-body');
  if(!body) return;
  if(!window._fbDB){
    body.innerHTML='<div style="padding:28px;text-align:center;color:#c0392b">Sem conexão com o Firebase agora — tente de novo em alguns segundos.</div>';
    return;
  }
  window._fbDB.ref('erp_snapshots').once('value').then(snap=>{
    const d=snap.val()||{};
    const chaves=Object.keys(d).sort().reverse();
    const rows=chaves.map(k=>{
      const s=d[k];
      const isDia=/^\d{4}-\d{2}-\d{2}$/.test(k);
      const isManual=/^manual-\d{13}$/.test(k);
      const label=isDia?new Date(k+'T12:00:00').toLocaleDateString('pt-BR',{weekday:'long',day:'2-digit',month:'2-digit',year:'numeric'})
        :(isManual?'Snapshot manual — ':'Backup de emergência — ')+new Date(s._ts||0).toLocaleString('pt-BR');
      const nAdt=Object.values(s.adiantamentos||{}).reduce((t,l)=>t+(l?l.length:0),0);
      const nCheq=Object.values(s.cheques||{}).reduce((t,l)=>t+(l?l.length:0),0);
      return '<tr>'
        +'<td style="padding:7px 10px;font-size:.85rem">'+esc(label)+'</td>'
        +'<td style="padding:7px 10px;font-size:.8rem;color:#666">'+nAdt+' adiant. / '+nCheq+' cheque(s) / '+(Array.isArray(s.bancos)?s.bancos.length:Object.keys(s.bancos||{}).length)+' contas</td>'
        +'<td style="padding:7px 10px;text-align:center">'+(_usuarioAtualEhElaine()?'<button onclick="restaurarSnapshot(&#39;'+k+'&#39;)" style="background:#e67e22;color:#fff;border:none;border-radius:4px;padding:5px 12px;cursor:pointer;font-size:.78rem;font-weight:700">↩️ Restaurar este dia</button>':'<span style="font-size:.72rem;color:#999">Somente Elaine</span>')+'</td>'
        +'</tr>';
    }).join('');
    body.innerHTML='<div style="padding:22px;max-width:760px">'
      +'<h3 style="margin-bottom:6px;color:var(--primary-dark)">📦 Snapshots Diários</h3>'
      +'<p style="font-size:.8rem;color:#777;margin-bottom:14px">Snapshots de dados de negócio no Firebase (não incluem arquivos do Storage). Snapshots novos são capturados diretamente do RTDB. Restaure apenas em janela de manutenção, com outros usuários desconectados.</p>'
      +(_usuarioAtualEhElaine()?'<button onclick="_criarSnapshotManual()" style="margin-bottom:12px;background:#1a5e2a;color:white;border:0;border-radius:6px;padding:8px 14px;cursor:pointer">📸 Criar snapshot agora (RTDB)</button>':'')
      +'<div style="max-height:55vh;overflow:auto;border:1px solid #eee;border-radius:8px">'
      +'<table style="width:100%;border-collapse:collapse">'
      +'<thead style="position:sticky;top:0;background:#f0f0f0"><tr>'
      +'<th style="text-align:left;padding:7px 10px;font-size:.78rem">Data</th>'
      +'<th style="text-align:left;padding:7px 10px;font-size:.78rem">Conteúdo</th>'
      +'<th style="padding:7px 10px"></th>'
      +'</tr></thead>'
      +'<tbody>'+(rows||'<tr><td colspan="3" style="padding:16px;text-align:center;color:#999">Nenhum snapshot ainda — o primeiro é criado automaticamente no próximo login.</td></tr>')+'</tbody>'
      +'</table></div>'
      +'<div id="snapshots-backups-audit"></div>'
      +'<div style="margin-top:16px;text-align:right"><button onclick="cm()" style="padding:8px 22px;background:#1a3a2a;color:#fff;border:none;border-radius:6px;cursor:pointer;font-weight:700">Fechar</button></div>'
      +'</div>';
    if(_usuarioAtualEhElaine())_carregarHistoricoRestauracoes('snapshots-backups-audit');
  }).catch(e=>{
    body.innerHTML='<div style="padding:28px;text-align:center;color:#c0392b">Erro ao buscar snapshots: '+esc(e.message||String(e))+'</div>';
  });
}



async function _criarSnapshotManual(){
  if(!_usuarioAtualEhElaine()||!firebase.auth().currentUser)return;
  if(!confirm('Criar um snapshot novo do estado ATUAL dos dados de negócio no Firebase?\n\nEle não inclui os arquivos binários do Storage nem autenticação.'))return;
  try{
    const result=await _supAdminApi('/api/admin/snapshots',{action:'snapshot',key:'manual-'+Date.now()});
    if(!result.created)throw new Error('Uma cópia com essa identificação já existia.');
    showToast('📸 Snapshot manual criado no Firebase.','success');
    abrirSnapshots();
  }catch(error){showToast('Falha ao criar snapshot: '+error.message,'error',7000);}
}

function _snapshotLimparTombstones(){
  try{ TICKETS_DELETED.clear(); localStorage.setItem('mm_tickets_deletados','[]'); }catch(e){}
  try{ FORN_DELETED.clear(); localStorage.setItem('mm_fornecedores_deleted','[]'); }catch(e){}
  try{ CONTAS_PAGAR_DELETED.clear(); localStorage.setItem('mm_cp_deletados','[]'); }catch(e){}
  ['bancos','lancBanco','fornecedores','clientes','contasReceber','vales','ponto','epi','frota','manutencao','viagem','combustivel','agendaEntregas','almoxa','almoxaMov','historico'].forEach(function(nome){ try{ localStorage.setItem('mm_'+nome+'_deletados','[]'); }catch(e){} });
  [
    typeof _syncBancos!=='undefined'?_syncBancos:null,
    typeof _syncLancBanco!=='undefined'?_syncLancBanco:null,
    typeof _syncFornecedores!=='undefined'?_syncFornecedores:null,
    typeof _syncClientes!=='undefined'?_syncClientes:null,
    typeof _syncContasReceber!=='undefined'?_syncContasReceber:null,
    typeof _syncVales!=='undefined'?_syncVales:null,
    typeof _syncPonto!=='undefined'?_syncPonto:null,
    typeof _syncEpi!=='undefined'?_syncEpi:null,
    typeof _syncFrota!=='undefined'?_syncFrota:null,
    typeof _syncManutencao!=='undefined'?_syncManutencao:null,
    typeof _syncViagem!=='undefined'?_syncViagem:null,
    typeof _syncCombustivel!=='undefined'?_syncCombustivel:null,
    typeof _syncAgenda!=='undefined'?_syncAgenda:null,
    typeof _syncAlxItens!=='undefined'?_syncAlxItens:null,
    typeof _syncAlxMov!=='undefined'?_syncAlxMov:null,
    typeof _syncHistorico!=='undefined'?_syncHistorico:null
  ].filter(Boolean).forEach(function(sync){ try{ sync.deletedSet.clear(); }catch(e){} });
}

function _snapshotPersistirExato(s){
  if(!window._fbDB) return Promise.reject(new Error('Firebase não conectado'));
  _snapshotLimparTombstones();
  const refs={
    tickets: s.tickets||{},
    adiantamentos: s.adiantamentos||{},
    cheques: s.cheques||{},
    adtCli: s.adtCli||{},
    chequesCli: s.chequesCli||{},
    bancos: (typeof _syncBancos!=='undefined'?_syncBancos.paraObjeto():{}),
    lancBanco: (typeof _syncLancBanco!=='undefined'?_syncLancBanco.paraObjeto():{}),
    fornecedores: (typeof _syncFornecedores!=='undefined'?_syncFornecedores.paraObjeto():{}),
    clientes: (typeof _syncClientes!=='undefined'?_syncClientes.paraObjeto():{}),
    contasPagar: (typeof _cpParaObjeto==='function'?_cpParaObjeto():{}),
    contasReceber: (typeof _syncContasReceber!=='undefined'?_syncContasReceber.paraObjeto():{}),
    estoque: s.estoque||{},
    historico: (typeof _syncHistorico!=='undefined'?_syncHistorico.paraObjeto():{}),
    funcEdit: Array.isArray(s.funcEdit)?s.funcEdit:[],
    folha: s.folha||{},
    vales: (typeof _syncVales!=='undefined'?_syncVales.paraObjeto():{}),
    ponto: (typeof _syncPonto!=='undefined'?_syncPonto.paraObjeto():{}),
    epi: (typeof _syncEpi!=='undefined'?_syncEpi.paraObjeto():{}),
    frota: (typeof _syncFrota!=='undefined'?_syncFrota.paraObjeto():{}),
    manutencao: (typeof _syncManutencao!=='undefined'?_syncManutencao.paraObjeto():{}),
    viagem: (typeof _syncViagem!=='undefined'?_syncViagem.paraObjeto():{}),
    combustivel: (typeof _syncCombustivel!=='undefined'?_syncCombustivel.paraObjeto():{}),
    agendaEntregas: (typeof _syncAgenda!=='undefined'?_syncAgenda.paraObjeto():{}),
    almoxa: (typeof _syncAlxItens!=='undefined'?_syncAlxItens.paraObjeto():{}),
    almoxaMov: (typeof _syncAlxMov!=='undefined'?_syncAlxMov.paraObjeto():{})
  };
  const tombstones=[
    'ticketsDeleted','ticketsDeletedV2','fornDeleted','fornDeletedV2','contasPagarDeleted','contasPagarDeletedV2',
    'bancosDeleted','bancosDeletedV2','lancBancoDeleted','lancBancoDeletedV2','fornecedoresDeleted','fornecedoresDeletedV2',
    'clientesDeleted','clientesDeletedV2','contasReceberDeleted','contasReceberDeletedV2','valesDeleted','valesDeletedV2',
    'pontoDeleted','pontoDeletedV2','epiDeleted','epiDeletedV2','frotaDeleted','frotaDeletedV2','manutencaoDeleted','manutencaoDeletedV2',
    'viagemDeleted','viagemDeletedV2','combustivelDeleted','combustivelDeletedV2','agendaEntregasDeleted','agendaEntregasDeletedV2',
    'almoxaDeleted','almoxaDeletedV2','almoxaMovDeleted','almoxaMovDeletedV2','historicoDeleted','historicoDeletedV2'
  ];
  const ops=Object.keys(refs).map(function(k){ return window._fbDB.ref('erp/'+k).set(refs[k]); });
  tombstones.forEach(function(k){ ops.push(window._fbDB.ref('erp/'+k).remove()); });
  ops.push(window._fbDB.ref('erp/_ts').set(Date.now()));
  return Promise.all(ops);
}



async function restaurarSnapshot(dataKey){
  if(!_usuarioAtualEhElaine()){alert('Apenas a Elaine pode restaurar snapshots.');return;}
  if(!window._fbDB || !firebase.auth().currentUser){alert('Firebase desconectado.');return;}
  const confirmacao=prompt('ATENÇÃO: feche o ERP nos outros computadores antes de restaurar.\n\nUm backup de emergência será criado no Firebase.\n\nPara restaurar '+dataKey+', digite RESTAURAR:');
  if(confirmacao!=='RESTAURAR')return;
  if(!confirm('Confirma substituir os dados de negócio contidos no snapshot '+dataKey+'? A operação não inclui arquivos do Storage.'))return;
  const status=document.getElementById('sup-backup-status');
  window.__ERP_RESTORING__=true;
  try{
    const token=await firebase.auth().currentUser.getIdToken();
    const response=await fetch('/api/admin/snapshots',{
      method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json',Authorization:'Bearer '+token},
      body:JSON.stringify({action:'restore',key:dataKey,confirmation:'RESTAURAR'})
    });
    const result=await response.json();
    if(!response.ok)throw new Error(result.message||'Falha na restauração');
    if(status)status.textContent='✅ Restauração confirmada no Firebase. Recarregando...';
    
    window.location.reload();
  }catch(error){
    window.__ERP_RESTORING__=false;
    alert('Restauração NÃO confirmada: '+error.message+'; preserve a cópia de emergência e verifique o console.');
  }
}



