function _removerMovBancoDeAdiantamento(fornCod, a){
  if(!a) return;
  let i=-1;
  if(a.movBancoId) i=LANC_BANCO_DB.findIndex(l=>l.id===a.movBancoId);
  if(i<0 && a.bancoNome && a.bancoNome!=='Não informado'){
    const banco=BANCOS_DB.find(x=>x.banco===a.bancoNome);
    if(banco){
      const forn=FORNECEDORES.find(f=>f.cod===fornCod);
      const descEsperada='Adiantamento: '+(forn?forn.nome:fornCod)+(a.ticket?' Ticket '+a.ticket:'');
      i=LANC_BANCO_DB.findIndex(l=>l.bancoCod===banco.cod && l.tipo==='Saida' &&
        Math.abs(Number(l.valor)-Number(a.valor))<0.01 &&
        (l.descricao===descEsperada || l.descricao===('Adiantamento: '+fornCod+(a.ticket?' Ticket '+a.ticket:''))));
    }
  }
  if(i>=0){ _syncLancBanco.remover(i); saveBancos(); renderBancos(); }
}

function excluirAdiantamento(fornCod, adtCod){
  if(!confirm('Excluir este adiantamento?')) return;
  const lista = ADT_POR_FORN[fornCod];
  if(!lista) return;
  const idx = lista.findIndex(a=>a.cod===adtCod);
  if(idx<0) return;
  const _removido=lista[idx];
  _removerMovBancoDeAdiantamento(fornCod, lista[idx]);
  lista.splice(idx,1);
  try{ delete window._ADT_PENDENTES[fornCod+'::'+adtCod]; }catch(e){}
  
  
  
  
  _DEL_SETS.adtItens.add(fornCod+'::'+adtCod);
  try{ localStorage.setItem(_DEL_LS_KEY.adtItens, JSON.stringify([..._DEL_SETS.adtItens])); }catch(e){}
  saveDB();
  
  try{ if(window._fbDB){ var _v=ADT_POR_FORN[fornCod]; window._fbDB.ref('erp/adiantamentos/'+fornCod).set((_v&&_v.length)?_v:null); window._fbDB.ref('erp/_ts').set(Date.now()); } }catch(e){}
  {
    const _forn=FORNECEDORES.find(f=>f.cod===fornCod);
    registrarHistorico('Adiantamento','Excluído',
      (_forn?_forn.nome:fornCod)+' '+adtCod+' — R$ '+Number(_removido.valor||0).toLocaleString('pt-BR',{minimumFractionDigits:2})+' ('+(_removido.data||'')+')',
      _removido, {fornCod});
  }
  
  onCanhotFornChange();
  renderAdiantamentos();
}

function excluirAdiantamentoLista(btn){
  const fornNome = btn.dataset.forn;
  const adtCod   = btn.dataset.cod;
  if(!confirm('Excluir adiantamento '+adtCod+'?')) return;
  
  const forn = FORNECEDORES.find(f=>f.nome===fornNome);
  const fornCod = forn ? forn.cod : Object.keys(ADT_POR_FORN).find(k=>{
    return (ADT_POR_FORN[k]||[]).some(a=>a.cod===adtCod);
  });
  if(!fornCod) return;
  const lista = ADT_POR_FORN[fornCod];
  if(!lista) return;
  const idx = lista.findIndex(a=>a.cod===adtCod);
  if(idx<0) return;
  const _removido2=lista[idx];
  _removerMovBancoDeAdiantamento(fornCod, lista[idx]);
  lista.splice(idx,1);
  try{ delete window._ADT_PENDENTES[fornCod+'::'+adtCod]; }catch(e){}
  saveDB();
  
  try{ if(window._fbDB){ var _v=ADT_POR_FORN[fornCod]; window._fbDB.ref('erp/adiantamentos/'+fornCod).set((_v&&_v.length)?_v:null); window._fbDB.ref('erp/_ts').set(Date.now()); } }catch(e){}
  registrarHistorico('Adiantamento','Excluído',
    (fornNome||fornCod)+' '+adtCod+' — R$ '+Number(_removido2.valor||0).toLocaleString('pt-BR',{minimumFractionDigits:2})+' ('+(_removido2.data||'')+')',
    _removido2, {fornCod});
  renderAdiantamentos();
}



function zerarTodosAdiantamentos(){
  var qt=0; Object.keys(ADT_POR_FORN||{}).forEach(function(fc){ qt+=(ADT_POR_FORN[fc]||[]).length; });
  if(!qt){ alert('Não há adiantamentos pra apagar. Já está zerado.'); return; }
  if(!confirm('APAGAR TODOS os '+qt+' adiantamento(s) pra você começar do zero?\n\nFaço backup antes. Depois você lança os certos de novo — e eles NÃO vão mais voltar nem sumir.')) return;
  if(!confirm('Tem certeza? Isso apaga TODOS os adiantamentos agora.')) return;
  try{
    var ts=Date.now();
    var copia=JSON.parse(JSON.stringify(ADT_POR_FORN));
    if(window._fbDB){ window._fbDB.ref('erp/_bkp_zerar_adt_'+ts).set({quando:new Date().toISOString(), adiantamentos:copia}); }
    localStorage.setItem('mm_bkp_zerar_adt', JSON.stringify({ts:ts, adiantamentos:copia}));
  }catch(e){}
  
  Object.keys(ADT_POR_FORN).forEach(function(fc){ delete ADT_POR_FORN[fc]; });
  try{ window._ADT_PENDENTES={}; }catch(e){}
  try{ _DEL_SETS.adtItens.clear(); _DEL_SETS.adtPorForn.clear(); localStorage.removeItem(_DEL_LS_KEY.adtItens); localStorage.removeItem(_DEL_LS_KEY.adtPorForn); }catch(e){}
  saveDB();
  
  try{ if(window._fbDB){ window._fbDB.ref('erp/adiantamentos').set(null); window._fbDB.ref('erp/adtItensDeleted').set(null); window._fbDB.ref('erp/adtPorFornDeleted').set(null); window._fbDB.ref('erp/_ts').set(Date.now()); } }catch(e){}
  try{ registrarHistorico('Adiantamento','Zerado tudo','Apaguei todos os '+qt+' adiantamentos (recomeçar)', null, null); }catch(e){}
  try{ renderAdiantamentos(); }catch(e){}
  alert('✅ Pronto! Apaguei todos os adiantamentos (na nuvem também). Agora está ZERADO. Pode lançar os certos — eles vão ficar. Tem backup, se precisar.');
}
window['zerarTodosAdiantamentos']=zerarTodosAdiantamentos;



function verValesFunc(mat){
  const f=FUNCIONARIOS.find(x=>x.mat===mat);
  const nome=f?f.nome:mat;
  const vales=VALES_DB.filter(v=>v.mat===mat);
  const fmt=v=>_numFinito(v,0).toLocaleString('pt-BR',{minimumFractionDigits:2});
  const total=vales.reduce((s,v)=>s+Number(v.valor),0);
  const body=document.getElementById('modal-body');
  body.className='modal';
  if(vales.length===0){
    body.innerHTML='<h3>💳 Vales – '+esc(nome)+'</h3>'+
      '<p style="color:var(--gray);text-align:center;padding:20px">Nenhum vale registrado para este funcionário.</p>'+
      '<div class="modal-ft"><button class="btn-cancel" onclick="cm()">Fechar</button></div>';
  } else {
    body.innerHTML='<h3>💳 Vales – '+esc(nome)+'</h3>'+
      '<table style="width:100%;border-collapse:collapse;font-size:.85rem">'+
      '<thead><tr style="background:#f5f5f5"><th style="padding:6px 8px;text-align:left">Data</th><th style="padding:6px 8px;text-align:left">Mês Ref.</th><th style="padding:6px 8px;text-align:right">Valor</th><th style="padding:6px 8px;text-align:left">Forma</th><th style="padding:6px 8px">Recibo</th><th style="padding:6px 8px">Ações</th></tr></thead>'+
      '<tbody>'+
      vales.map((v,i)=>{
        const gi=VALES_DB.indexOf(v);
        const ass=v.assinatura?'<span style="background:#e8f5e9;color:#2e7d32;border-radius:10px;padding:2px 7px;font-size:.72rem;font-weight:700">✅ Assinado</span>':'<span style="background:#fff3cd;color:#856404;border-radius:10px;padding:2px 7px;font-size:.72rem;font-weight:700">⏳ Pendente</span>';
        return '<tr style="border-bottom:1px solid #eee">'+
        '<td style="padding:6px 8px">'+esc(v.data||'—')+'</td>'+
        '<td style="padding:6px 8px">'+esc(v.mes||'—')+'</td>'+
        '<td style="padding:6px 8px;text-align:right;font-weight:700">R$ '+fmt(v.valor)+'</td>'+
        '<td style="padding:6px 8px">'+esc(v.forma||'—')+'</td>'+
        '<td style="padding:6px 8px;text-align:center">'+ass+'</td>'+
        '<td style="padding:6px 8px;text-align:center;white-space:nowrap">'+
        '<button class="btn-edit" style="font-size:.75rem;margin-right:3px" onclick="editVale('+gi+')">✏️</button>'+
        '<button class="btn-edit" style="font-size:.75rem;margin-right:3px;background:#1565c0;color:#fff" onclick="valeAssinarModal('+gi+',\''+mat+'\')">✍️</button>'+
        '<button class="btn-edit" style="font-size:.75rem;margin-right:3px;background:#2e7d32;color:#fff" onclick="valeGerarRecibo('+gi+')">📄</button>'+
        '<button class="btn-edit-danger" style="font-size:.75rem" onclick="excluirValeModal('+gi+',\''+mat+'\')">🗑️</button></td>'+
        '</tr>';
      }).join('')+
      '</tbody>'+
      '<tfoot><tr style="background:#f0f7f0"><td colspan="2" style="padding:8px;font-weight:700">TOTAL</td>'+
      '<td style="padding:8px;text-align:right;font-weight:900;color:var(--primary)">R$ '+fmt(total)+'</td><td colspan="2"></td></tr></tfoot>'+
      '</table>'+
      '<div style="margin-top:12px;text-align:right">'+
      '<button class="btn-add" style="font-size:.82rem" onclick="cm();switchTab(&#39;vales&#39;)">+ Lançar Novo Vale</button>'+
      '</div>'+
      '<div class="modal-ft"><button class="btn-cancel" onclick="cm()">Fechar</button></div>';
  }
  document.getElementById('modal-ov').classList.add('open');
}

function excluirValeModal(idx, mat){
  const v=VALES_DB[idx];
  if(!v||!confirm('Excluir vale de R$ '+Number(v.valor).toFixed(2)+'?')) return;
  _syncVales.remover(idx);
  saveDB();
  renderVales();
  renderFolha();
  cm();
  setTimeout(()=>verValesFunc(mat),100);
}





