function renderEpi(){
  
  const selFunc=document.getElementById('epi-fil-func');
  if(selFunc&&selFunc.options.length<=1){
    FUNCIONARIOS.filter(f=>f.status!=='Inativo').forEach(f=>{
      const o=document.createElement('option'); o.value=f.mat; o.textContent=f.mat+' – '+f.nome; selFunc.appendChild(o);
    });
  }
  
  const filFunc=(document.getElementById('epi-fil-func')?.value||'');
  const filMes=(document.getElementById('epi-fil-mes')?.value||'');
  let lista=EPI_DB.filter(e=>{
    if(filFunc&&e.mat!==filFunc) return false;
    if(filMes&&!(e.data||'').startsWith(filMes.replace('-','/').split('/').reverse().join('/'))) return false;
    return true;
  });
  
  if(filMes) lista=EPI_DB.filter(e=>{
    if(filFunc&&e.mat!==filFunc) return false;
    
    if(filMes){
      const [yy,mm]=filMes.split('-');
      if(e.data){
        const parts=e.data.split('/');
        if(parts.length===3&&(parts[2]!==yy||parts[1]!==mm)) return false;
      }
    }
    return true;
  });
  const tb=document.getElementById('tb-epi');
  if(!tb) return;
  const cnt=document.getElementById('epi-count');
  if(cnt) cnt.textContent=lista.length+' registro(s)';
  if(!lista.length){
    tb.innerHTML='<tr><td colspan="10" style="text-align:center;padding:20px;color:var(--gray)">Nenhuma entrega encontrada</td></tr>';
    return;
  }
  const sorted=[...lista].sort((a,b)=>(b.data||'').localeCompare(a.data||''));
  tb.innerHTML=sorted.map(e=>{
    const f=FUNCIONARIOS.find(x=>x.mat===e.mat);
    const nome=f?f.nome:e.mat;
    const cargo=f?f.cargo||'':'';
    const ass=e.assinatura
      ?'<span style="background:#e8f5e9;color:#2e7d32;border-radius:10px;padding:2px 7px;font-size:.72rem;font-weight:700">✅ Assinado</span>'
      :'<span style="background:#fff3cd;color:#856404;border-radius:10px;padding:2px 7px;font-size:.72rem;font-weight:700">⏳ Pendente</span>';
    return `<tr>
      <td style="font-size:.8rem">${esc(fmtDate(e.data)||'')}</td>
      <td><b>${esc(nome)}</b></td>
      <td style="font-size:.78rem">${esc(cargo)}</td>
      <td style="font-size:.78rem">${esc(e.atividade||'')}</td>
      <td style="font-size:.78rem">${esc(e.risco||'')}</td>
      <td style="font-weight:700">${esc(e.epi||'')}</td>
      <td style="font-size:.78rem">${esc(e.ca||'')}</td>
      <td style="font-size:.78rem">${esc(e.motivo||'')}</td>
      <td style="text-align:center">${ass}<br><div style="display:flex;gap:3px;justify-content:center;margin-top:3px">
        <button class="btn-edit" style="font-size:.7rem;background:#1565c0;color:#fff" onclick="epiAssinarModal('${e.id}')">✍️</button>
        <button class="btn-edit" style="font-size:.7rem;background:#2e7d32;color:#fff" onclick="epiGerarRecibo('${e.id}')">📄</button>
      </div></td>
      <td><button class="btn-edit-danger" style="font-size:.72rem" onclick="excluirEpi('${e.id}')">🗑️</button></td>
    </tr>`;
  }).join('');
}

function novoEpiModal(matPre){
  const funcOpts=FUNCIONARIOS.filter(f=>f.status!=='Inativo')
    .map(f=>`<option value="${f.mat}" ${f.mat===matPre?'selected':''}>${f.mat} – ${f.nome}</option>`).join('');
  const epiOpts=_EPI_CATALOGO.map((c,i)=>`<option value="${i}">${c.epi}</option>`).join('');
  const motivoOpts=_EPI_MOTIVOS.map(m=>`<option>${m}</option>`).join('');
  om('novoEpi');
  const body=document.getElementById('modal-body');
  body.style.maxWidth='560px';
  body.innerHTML=`<h3>🦺 Registrar Entrega de EPI</h3>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px">
      <div class="fg" style="grid-column:1/-1"><label>Colaborador</label><select id="ei-func">${funcOpts}</select></div>
      <div class="fg"><label>Data da Entrega</label><input type="date" id="ei-data" value="${_hojeISO()}"></div>
      <div class="fg"><label>EPI Fornecido</label>
        <select id="ei-epi-sel" onchange="epiPreencherCatalogo(this.value)" style="margin-bottom:4px">${epiOpts}</select>
        <input id="ei-epi" placeholder="ou digite o nome do EPI" style="margin-top:4px">
      </div>
      <div class="fg"><label>Atividade Exercida</label><input id="ei-ativ" placeholder="Ex: Seleção de materiais"></div>
      <div class="fg"><label>Risco da Atividade</label><input id="ei-risco" placeholder="Ex: Corte / Impacto"></div>
      <div class="fg"><label>Nº CA</label><input id="ei-ca" placeholder="Ex: 67890"></div>
      <div class="fg"><label>Motivo</label><select id="ei-motivo">${motivoOpts}</select></div>
    </div>
    <div style="display:flex;gap:10px;margin-top:14px">
      <button class="btn-save" onclick="salvarEpiEntrega()">💾 Salvar</button>
      <button class="btn-cancel" onclick="cm()">Cancelar</button>
    </div>`;
  document.getElementById('modal-ov').classList.add('open');
  epiPreencherCatalogo(0);
}

function epiPreencherCatalogo(idx){
  const c=_EPI_CATALOGO[parseInt(idx)];
  if(!c) return;
  const epiInp=document.getElementById('ei-epi');
  const ativInp=document.getElementById('ei-ativ');
  const riscoInp=document.getElementById('ei-risco');
  if(epiInp&&!epiInp.value) epiInp.value=c.epi;
  else if(epiInp) epiInp.value=c.epi;
  if(ativInp&&!ativInp.value) ativInp.value=c.atividade;
  else if(ativInp) ativInp.value=c.atividade;
  if(riscoInp&&!riscoInp.value) riscoInp.value=c.risco;
  else if(riscoInp) riscoInp.value=c.risco;
}

function salvarEpiEntrega(){
  const mat=document.getElementById('ei-func')?.value;
  const dataRaw=document.getElementById('ei-data')?.value||'';
  const epi=(document.getElementById('ei-epi')?.value||'').trim();
  const ativ=(document.getElementById('ei-ativ')?.value||'').trim();
  const risco=(document.getElementById('ei-risco')?.value||'').trim();
  const ca=(document.getElementById('ei-ca')?.value||'').trim();
  const motivo=document.getElementById('ei-motivo')?.value||'';
  if(!mat||!epi){ showToast('Preencha o funcionário e o EPI.','error'); return; }
  const data=dataRaw?dataRaw.split('-').reverse().join('/'):'';
  EPI_DB.push({id:'epi_'+Date.now(), mat, data, epi, atividade:ativ, risco, ca, motivo});
  saveEpi();
  cm();
  renderEpi();
  showToast('EPI registrado!','success');
}

function excluirEpi(id){
  if(!confirm('Excluir este registro de EPI?')) return;
  const idx=EPI_DB.findIndex(e=>e.id===id);
  if(idx<0) return;
  _syncEpi.remover(idx);
  saveEpi();
  renderEpi();
  showToast('Registro removido.','info');
}



function epiAssinarModal(id){
  const e=EPI_DB.find(x=>x.id===id);
  if(!e) return;
  const f=FUNCIONARIOS.find(x=>x.mat===e.mat);
  const nome=f?f.nome:e.mat;
  om('epiAssinar');
  const body=document.getElementById('modal-body');
  body.style.maxWidth='520px';
  body.innerHTML=`<h3>✍️ Assinatura de Recebimento de EPI</h3>
    <div style="background:#f9f9f9;border-radius:8px;padding:10px 14px;margin-bottom:14px;font-size:.85rem">
      <b>${esc(nome)}</b> &nbsp;·&nbsp; <b>${esc(e.epi)}</b> &nbsp;·&nbsp; ${esc(fmtDate(e.data)||'')}
    </div>
    <p style="font-size:.82rem;color:#555;margin:0 0 8px">Colaborador assina confirmando o recebimento do EPI:</p>
    <div style="border:2px solid #1565c0;border-radius:10px;background:#fff;margin-bottom:10px;position:relative">
      <canvas id="epi-sig-canvas" width="460" height="160" style="display:block;width:100%;height:160px;border-radius:8px;touch-action:none;cursor:crosshair"></canvas>
      <div style="position:absolute;bottom:2px;left:50%;transform:translateX(-50%);font-size:.7rem;color:#bbb;pointer-events:none">Assinatura do Colaborador</div>
    </div>
    <div style="display:flex;gap:8px;margin-bottom:12px">
      <button onclick="epiSigLimpar()" style="background:#eee;color:#555;border:none;border-radius:7px;padding:7px 14px;cursor:pointer;font-size:.82rem">🗑 Limpar</button>
      ${e.assinatura?`<button onclick="epiRemoverAss('${id}')" style="background:#e74c3c;color:#fff;border:none;border-radius:7px;padding:7px 14px;cursor:pointer;font-size:.82rem">❌ Remover</button>`:''}
    </div>
    <div class="modal-ft">
      <button class="btn-cancel" onclick="cm()">Cancelar</button>
      <button class="btn-save" onclick="epiSalvarAss('${id}')">💾 Salvar Assinatura</button>
    </div>`;
  document.getElementById('modal-ov').classList.add('open');
  setTimeout(()=>_epiInitCanvas(),100);
}

let _epiSigCtx=null, _epiSigDrawing=false, _epiSigLX=0, _epiSigLY=0;
function _epiInitCanvas(){
  const canvas=document.getElementById('epi-sig-canvas');
  if(!canvas) return;
  const rect=canvas.getBoundingClientRect();
  const dpr=window.devicePixelRatio||1;
  canvas.width=rect.width*dpr; canvas.height=160*dpr;
  _epiSigCtx=canvas.getContext('2d');
  _epiSigCtx.scale(dpr,dpr);
  _epiSigCtx.strokeStyle='#1a1a1a'; _epiSigCtx.lineWidth=2.5; _epiSigCtx.lineCap='round'; _epiSigCtx.lineJoin='round';
  const gp=(e,c)=>{ const r=c.getBoundingClientRect(),s=e.touches?e.touches[0]:e; return{x:s.clientX-r.left,y:s.clientY-r.top}; };
  const st=e=>{ e.preventDefault(); _epiSigDrawing=true; const p=gp(e,canvas); _epiSigLX=p.x; _epiSigLY=p.y; };
  const dr=e=>{ e.preventDefault(); if(!_epiSigDrawing) return; const p=gp(e,canvas); _epiSigCtx.beginPath(); _epiSigCtx.moveTo(_epiSigLX,_epiSigLY); _epiSigCtx.lineTo(p.x,p.y); _epiSigCtx.stroke(); _epiSigLX=p.x; _epiSigLY=p.y; };
  const sp=()=>{ _epiSigDrawing=false; };
  canvas.addEventListener('mousedown',st); canvas.addEventListener('mousemove',dr); canvas.addEventListener('mouseup',sp); canvas.addEventListener('mouseleave',sp);
  canvas.addEventListener('touchstart',st,{passive:false}); canvas.addEventListener('touchmove',dr,{passive:false}); canvas.addEventListener('touchend',sp);
}
function epiSigLimpar(){ const c=document.getElementById('epi-sig-canvas'); if(c&&_epiSigCtx) _epiSigCtx.clearRect(0,0,c.width,c.height); }
function _epiCanvasVazio(){ const c=document.getElementById('epi-sig-canvas'); if(!c) return true; return !c.getContext('2d').getImageData(0,0,c.width,c.height).data.some(v=>v!==0); }

function epiSalvarAss(id){
  if(_epiCanvasVazio()){ showToast('Assine antes de salvar.','error'); return; }
  const e=EPI_DB.find(x=>x.id===id); if(!e) return;
  e.assinatura=document.getElementById('epi-sig-canvas').toDataURL('image/png');
  e.assinadoEm=new Date().toISOString().slice(0,10);
  saveEpi(); cm(); renderEpi(); showToast('Assinatura registrada! ✅','success');
}

function epiRemoverAss(id){
  if(!confirm('Remover assinatura?')) return;
  const e=EPI_DB.find(x=>x.id===id); if(!e) return;
  delete e.assinatura; delete e.assinadoEm;
  saveEpi(); cm(); renderEpi(); showToast('Assinatura removida.','info');
}



