function getFolhaMes(){
  const el=document.getElementById('folha-mes');
  if(!el||!el.value){
    
    const n=new Date();
    const m=n.getFullYear()+'-'+(String(n.getMonth()+1).padStart(2,'0'));
    if(el) el.value=m;
    return m;
  }
  return el.value;
}
function setFolhaValor(mat,campo,val){
  const mes=getFolhaMes();
  const key=mes+'-'+mat;
  if(!FOLHA_DB[key]) FOLHA_DB[key]={};
  FOLHA_DB[key][campo]=parseFloat(val)||0;
  saveDB();
  renderFolha();
}


function parseDataBR(d){
  if(!d) return null;
  try{
    if(d.includes('/')){const p=d.split('/');return{m:parseInt(p[1]),y:parseInt(p[2])};}
    if(d.includes('-')){const p=d.split('-');return{m:parseInt(p[1]),y:parseInt(p[0])};}
  }catch(e){}
  return null;
}

function fluxoSumCP(cat, mes, ano){
  
  return CONTAS_PAGAR.filter(c=>{
    if(c.status!=='Pago') return false;
    const dt=parseDataBR(c.dataPgto||c.lancto);
    if(!dt||dt.y!==ano||dt.m!==mes) return false;
    if(cat==='folha') return (c.cat||'').toLowerCase().includes('folha');
    if(cat==='sucata') return (c.cat||'').toLowerCase().includes('sucata');
    if(cat==='outros') return !(c.cat||'').toLowerCase().includes('folha')&&!(c.cat||'').toLowerCase().includes('sucata');
    return false;
  }).reduce((s,c)=>s+Number(c.valor||0),0);
}

function fluxoSumCR(mes, ano){
  
  return CONTAS_RECEBER.filter(c=>{
    if(c.status!=='Recebido'&&c.status!=='Pago') return false;
    const dt=parseDataBR(c.dataReceb||c.data);
    return dt&&dt.y===ano&&dt.m===mes;
  }).reduce((s,c)=>s+Number(c.valor||0),0);
}

function fluxoSumAdt(mes, ano){
  
  let total=0;
  Object.values(ADT_POR_FORN).forEach(lista=>{
    lista.forEach(a=>{
      if(a.forma==='Crédito') return;
      const dt=parseDataBR(a.data);
      if(dt&&dt.y===ano&&dt.m===mes) total+=Number(a.valor||0);
    });
  });
  return total;
}

function renderFluxo(){
  const fluxoAnoEl=document.getElementById('fluxo-ano'); if(fluxoAnoEl&&!fluxoAnoEl.value) fluxoAnoEl.value=_anoAtual();
  const tbody=document.getElementById('tb-fluxo-body');
  if(!tbody) return;
  const ano=parseInt(document.getElementById('fluxo-ano')?.value)||new Date().getFullYear();
  const fmt=v=>_numFinito(v,0).toLocaleString('pt-BR',{minimumFractionDigits:2});
  const mNomes=['Jan','Fev','Mar','Abr','Mai','Jun','Jul','Ago','Set','Out','Nov','Dez'];

  
  const cats=[
    {key:'vendas',   lbl:'Vendas de Metais',        tipo:'entrada', fn:(m,y)=>fluxoSumCR(m,y)},
    {key:'sucata',   lbl:'Adiantamentos Forn.',      tipo:'saida',   fn:(m,y)=>fluxoSumAdt(m,y)},
    {key:'saldo',    lbl:'Saldo Compra Sucata',       tipo:'saida',   fn:(m,y)=>fluxoSumCP('sucata',m,y)},
    {key:'folha',    lbl:'Folha de Pagamento',        tipo:'saida',   fn:(m,y)=>fluxoSumCP('folha',m,y)},
    {key:'outros',   lbl:'Outras Despesas',           tipo:'saida',   fn:(m,y)=>fluxoSumCP('outros',m,y)},
  ];

  const data=cats.map(cat=>{
    const vals=Array.from({length:12},(_,i)=>cat.fn(i+1,ano));
    const total=vals.reduce((s,v)=>s+v,0);
    return{...cat,vals,total};
  });

  const entradas=data.filter(d=>d.tipo==='entrada');
  const saidas=data.filter(d=>d.tipo==='saida');

  const totEnt=Array.from({length:12},(_,i)=>entradas.reduce((s,d)=>s+d.vals[i],0));
  const totSai=Array.from({length:12},(_,i)=>saidas.reduce((s,d)=>s+d.vals[i],0));
  const result=Array.from({length:12},(_,i)=>totEnt[i]-totSai[i]);
  const totEntG=totEnt.reduce((s,v)=>s+v,0);
  const totSaiG=totSai.reduce((s,v)=>s+v,0);
  const resultG=totEntG-totSaiG;

  function fmtCell(v,tipo){
    if(v===0) return '<span style="color:#bbb">—</span>';
    const color=tipo==='entrada'?'#1a5e2a':tipo==='saida'?'#c0392b':'';
    return '<span style="color:'+color+';font-weight:'+(v!==0?'600':'400')+'">'+fmt(v)+'</span>';
  }
  function dataRow(d){
    const cells=d.vals.map(v=>'<td style="text-align:right;font-size:.82rem">'+fmtCell(v,d.tipo)+'</td>').join('');
    const tot='<td style="text-align:right;font-weight:700;font-size:.82rem">'+fmtCell(d.total,d.tipo)+'</td>';
    return '<tr><td style="padding-left:16px;font-size:.83rem">'+d.lbl+'</td>'+cells+tot+'</tr>';
  }
  function sumRow(lbl,vals,total,bg,color){
    const cells=vals.map(v=>'<td style="text-align:right;font-weight:700;font-size:.82rem">'+
      (v===0?'<span style="color:#bbb">0</span>':fmt(v))+'</td>').join('');
    return '<tr style="background:'+bg+';font-weight:800"><td style="color:'+color+'">'+lbl+'</td>'+
      cells+'<td style="text-align:right;color:'+color+';font-size:.9rem">'+fmt(total)+'</td></tr>';
  }

  let html='';
  html+='<tr style="background:#e8f5e9"><td colspan="14"><b>📥 ENTRADAS</b></td></tr>';
  entradas.forEach(d=>{ html+=dataRow(d); });
  html+=sumRow('TOTAL ENTRADAS',totEnt,totEntG,'#d5f0e0','#1a5e2a');
  html+='<tr style="background:#fde8e8"><td colspan="14"><b>📤 SAÍDAS</b></td></tr>';
  saidas.forEach(d=>{ html+=dataRow(d); });
  html+=sumRow('TOTAL SAÍDAS',totSai,totSaiG,'#fde8e8','#c0392b');
  
  const resRows=result.map(v=>{
    const col=v>=0?'#1a5e2a':'#c0392b';
    return '<td style="text-align:right;font-weight:900;color:'+col+'">'+fmt(v)+'</td>';
  }).join('');
  const resCol=resultG>=0?'#1a5e2a':'#c0392b';
  html+='<tr style="background:#fff3cd;font-weight:900"><td>RESULTADO</td>'+resRows+
    '<td style="text-align:right;font-weight:900;font-size:.95rem;color:'+resCol+'">'+fmt(resultG)+'</td></tr>';

  tbody.innerHTML=html;

  
  const kpis=document.getElementById('fluxo-kpis');
  if(kpis) kpis.innerHTML=
    '<div class="kpi g"><div class="kpi-lbl">Total Entradas '+ano+'</div><div class="kpi-val">R$ '+fmt(totEntG)+'</div><div class="kpi-sub">Recebimentos</div></div>'+
    '<div class="kpi r"><div class="kpi-lbl">Total Saídas '+ano+'</div><div class="kpi-val">R$ '+fmt(totSaiG)+'</div><div class="kpi-sub">Pagamentos</div></div>'+
    '<div class="kpi '+(resultG>=0?'g':'r')+'"><div class="kpi-lbl">Resultado '+ano+'</div><div class="kpi-val">R$ '+fmt(resultG)+'</div><div class="kpi-sub">'+(resultG>=0?'Superávit':'Déficit')+'</div></div>';
}


function fecharFolha(){
  
  
  
  try{ if(_syncPonto.limparDuplicatasExatas()){ saveDB(); } }catch(e){}
  const mes=getFolhaMes();
  const [ano,mn]=mes.split('-');
  const meses=['Janeiro','Fevereiro','Março','Abril','Maio','Junho','Julho','Agosto','Setembro','Outubro','Novembro','Dezembro'];
  const nomeMes=meses[parseInt(mn)-1]+'/'+ano;
  const fmt=v=>_numFinito(v,0).toLocaleString('pt-BR',{minimumFractionDigits:2});

  
  let totalLiq=0;
  const lista=FUNCIONARIOS.filter(f=>f.status!=='Inativo');
  lista.forEach(f=>{
    const key=mes+'-'+f.mat;
    const fd=FOLHA_DB[key]||{};
    const lancPonto=PONTO_DB.filter(p=>{
      if(p.mat!==f.mat) return false;
      const d=p.data&&p.data.includes('/')?p.data.split('/').reverse().join('-'):p.data;
      return d&&d.startsWith(mes);
    });
    const valesM=VALES_DB.filter(v=>{
      if(v.mat!==f.mat) return false;
      const d=v.data&&v.data.includes('/')?v.data.split('/').reverse().join('-'):v.data;
      return d&&d.startsWith(mes);
    });
    const vales=valesM.reduce((s,v)=>s+Number(v.valor),0);
    const faltas=lancPonto.filter(p=>p.tipo==='Falta').length;
    const atestados=lancPonto.filter(p=>p.tipo==='Atestado').length;
    const heHoras=lancPonto.filter(p=>p.tipo==='HE').reduce((s,p)=>s+Number(p.horas||0),0);
    const valorHora=f.sal/220;
    const heValor=heHoras*valorHora;
    const descFaltas=(faltas*8)*valorHora;
    const adicional=Number(fd.adicional||0);
    const abono=(faltas===0&&atestados===0)?Number(fd.abono||0):0;
    const viagensM=VIAGEM_DB.filter(v=>{
      if(v.motorista!==f.nome) return false;
      const d=v.data&&v.data.includes('/')?v.data.split('/').reverse().join('-'):v.data;
      return d&&d.startsWith(mes);
    });
    const totalDiarias=viagensM.reduce((s,v)=>s+Number(v.totalDiarias!==undefined?v.totalDiarias:(v.diaria||0)*(v.numDiarias||1)),0);
    const bruto=f.sal-descFaltas+heValor+adicional+abono+totalDiarias;
    const inss=bruto*0.075;
    let irrf=0;
    if(bruto>4664.68) irrf=bruto*0.275-869.36;
    else if(bruto>3751.05) irrf=bruto*0.225-636.13;
    else if(bruto>2826.66) irrf=bruto*0.15-354.80;
    else if(bruto>2259.20) irrf=bruto*0.075-169.44;
    if(irrf<0) irrf=0;
    const desc=inss+irrf+vales;
    const liq=Math.max(0,bruto-desc);
    totalLiq+=liq;
  });

  if(totalLiq<=0){alert('Nenhum valor a lançar na folha de '+nomeMes+'.');return;}
  const jaExiste=CONTAS_PAGAR.find(c=>c.cat==='Folha de Pagamento'&&c.obs&&c.obs.includes(nomeMes));
  if(jaExiste){
    if(!confirm('Já existe uma conta a pagar de Folha para '+nomeMes+'. Deseja criar mesmo assim?')) return;
  }
  const vencISO=ano+'-'+mn+'-05'; 
  const vencDt=new Date(vencISO); vencDt.setMonth(vencDt.getMonth()+1);
  const vencFmt=vencDt.toLocaleDateString('pt-BR');
  const lancFmt=new Date().toLocaleDateString('pt-BR');
  CONTAS_PAGAR.push({ id:_novoIdCP(),
    lancto:lancFmt, desc:'Folha de Pagamento – '+nomeMes,
    cred:'Funcionários', cat:'Folha de Pagamento',
    bancoCod:'', bancoNome:'',
    venc:vencFmt, valor:totalLiq,
    status:'Pendente', dataPgto:'',
    obs:'Gerado automaticamente – Folha '+nomeMes
  });
  saveContasPagar();
  renderContasPagar();
  renderFluxo();
  renderDashboard();
  showToast('Folha de '+nomeMes+' lancada em Contas a Pagar! Total Liquido: R$ '+fmt(totalLiq),'success');
}

function renderFolha(){
  const tbFolha=document.getElementById('tb-folha');
  if(!tbFolha) return;
  
  try{ if(_syncPonto.limparDuplicatasExatas()){ saveDB(); } }catch(e){}
  const mes=getFolhaMes();
  const fmt=v=>_numFinito(v,0).toLocaleString('pt-BR',{minimumFractionDigits:2});
  const meses=['Janeiro','Fevereiro','Março','Abril','Maio','Junho','Julho','Agosto','Setembro','Outubro','Novembro','Dezembro'];
  const [ano,mn]=mes.split('-');
  const nomeMes=meses[parseInt(mn)-1]+'/'+ano;
  const titulo=document.getElementById('folha-titulo');
  const listaTodos=FUNCIONARIOS.filter(function(f){return f.status!=='Inativo';});
  const termoEl=document.getElementById('folha-pesquisa');
  const termo=String(termoEl&&termoEl.value||'').trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
  const lista=termo?listaTodos.filter(function(f){
    const texto=[f.mat,f.nome,f.cargo,f.empresa,f.role,f.descricao].map(function(v){return String(v||'');}).join(' ').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
    return texto.includes(termo);
  }):listaTodos;
  if(titulo) titulo.textContent='Folha – '+nomeMes+(termo?' · '+lista.length+' de '+listaTodos.length+' funcionário(s)':'');
  let totalBruto=0,totalInss=0,totalLiq=0,totalDec=0,totalFer=0,totalDiariasAll=0;
  tbFolha.innerHTML=lista.map(f=>{
    const key=mes+'-'+f.mat;
    const fd=FOLHA_DB[key]||{};
    
    const lancPonto=PONTO_DB.filter(p=>{
      if(p.mat!==f.mat) return false;
      if(!p.data) return true;
      const d=p.data.includes('/')?p.data.split('/').reverse().join('-'):p.data;
      return d.startsWith(mes);
    });
    const valesM=VALES_DB.filter(v=>{
      if(v.mat!==f.mat) return false;
      if(v.mes) return v.mes===nomeMes||v.mes.includes(mn+'/'+ano)||v.mes.includes(nomeMes);
      if(!v.data) return true;
      const d=v.data.includes('/')?v.data.split('/').reverse().join('-'):v.data;
      return d.startsWith(mes);
    });
    const vales=valesM.reduce((s,v)=>s+Number(v.valor),0);
    
    const viagensM=VIAGEM_DB.filter(v=>{
      if(v.motorista!==f.nome) return false;
      if(!v.data) return false;
      const d=v.data.includes('/')?v.data.split('/').reverse().join('-'):v.data;
      return d.startsWith(mes);
    });
    const qtdViagens=viagensM.length;
    
    const totalDiarias=viagensM.reduce((s,v)=>s+Number(v.totalDiarias!==undefined?v.totalDiarias:(v.diaria||0)*(v.numDiarias||1)),0);
    const faltas=lancPonto.filter(p=>p.tipo==='Falta').length;
    const atestados=lancPonto.filter(p=>p.tipo==='Atestado').length;
    const heHoras=lancPonto.filter(p=>p.tipo==='HE').reduce((s,p)=>s+Number(p.horas||0),0);
    const valorHora=f.sal/220;
    const heValor=heHoras*valorHora;
    const descFaltas=(faltas*8)*valorHora;
    const adicional=Number(fd.adicional||0);
    const abono=(faltas===0&&atestados===0)?Number(fd.abono||0):0;
    const bruto=f.sal-descFaltas+heValor+adicional+abono+totalDiarias;
    const inss=bruto*0.075;
    let irrf=0;
    if(bruto>4664.68) irrf=bruto*0.275-869.36;
    else if(bruto>3751.05) irrf=bruto*0.225-636.13;
    else if(bruto>2826.66) irrf=bruto*0.15-354.80;
    else if(bruto>2259.20) irrf=bruto*0.075-169.44;
    if(irrf<0) irrf=0;
    
    
    const vtDesc=Math.min(Number(f.sal||0)*0.06, Number(f.valeTransporte||0));
    const desc=inss+irrf+vales+vtDesc;
    const liq=bruto-desc>0?bruto-desc:0;
    const provDec=Number(fd.decTerceiro!==undefined?fd.decTerceiro:bruto/12);
    const provFer=Number(fd.ferias!==undefined?fd.ferias:(bruto*(4/3))/12);
    totalBruto+=bruto; totalInss+=inss; totalLiq+=liq; totalDec+=provDec; totalFer+=provFer; totalDiariasAll+=totalDiarias;
    const inpStyle='width:70px;padding:2px 4px;border:1px solid #ddd;border-radius:4px;font-size:.82rem;text-align:right';
    const inpStyleDec='width:75px;padding:2px 4px;border:1px solid #f0c040;border-radius:4px;font-size:.82rem;text-align:right;background:#fffbea';
    const inpStyleFer='width:75px;padding:2px 4px;border:1px solid #a0c4e0;border-radius:4px;font-size:.82rem;text-align:right;background:#f0f7ff';
    return '<tr style="'+(f.status==='Inativo'?'opacity:.5':'')+'">'+
      '<td>'+f.mat+'</td><td>'+esc(f.nome)+'</td><td>'+esc(f.cargo)+'</td>'+
      '<td>R$ '+fmt(f.sal)+'</td>'+
      '<td style="color:'+(faltas>0?'#e74c3c':'inherit')+';font-weight:'+(faltas>0?'700':'400')+'">'+faltas+'</td>'+
      '<td style="color:'+(atestados>0?'#e67e22':'inherit')+'">'+atestados+'</td>'+
      '<td>R$ '+fmt(heValor)+'</td>'+
      '<td><input type="number" min="0" step="0.01" style="'+inpStyle+'" value="'+(fd.adicional||0)+'" onchange="setFolhaValor(&#39;'+f.mat+'&#39;,&#39;adicional&#39;,this.value)" title="Editar adicional deste mês"></td>'+
      '<td><input type="number" min="0" step="0.01" style="'+inpStyle+(faltas>0||atestados>0?';background:#fff0f0':'')+'" value="'+(fd.abono||0)+'" onchange="setFolhaValor(&#39;'+f.mat+'&#39;,&#39;abono&#39;,this.value)" title="'+(faltas>0||atestados>0?'Atenção: funcionário tem falta/atestado':'Editar abono deste mês')+'"></td>'+
      '<td>R$ '+fmt(bruto)+'</td>'+
      '<td>R$ '+fmt(inss)+'</td>'+
      '<td>R$ '+fmt(irrf)+'</td>'+
      '<td style="cursor:pointer;color:var(--primary);text-decoration:underline" onclick="verValesFunc(&#39;'+f.mat+'&#39;)" title="Ver vales">R$ '+fmt(vales)+'</td>'+
      '<td title="Desconto do Vale Transporte (menor entre 6% do salário e o valor do VT cadastrado)">R$ '+fmt(vtDesc)+'</td>'+
      '<td>R$ '+fmt(desc)+'</td>'+
      '<td style="background:#e8f5e9;text-align:center">'+qtdViagens+'</td>'+
      '<td style="background:#e8f5e9;font-weight:600;color:#1a5e2a">R$ '+fmt(totalDiarias)+'</td>'+
      '<td><b>R$ '+fmt(liq)+'</b></td>'+
      '<td style="background:#fffbea"><input type="number" min="0" step="0.01" style="'+inpStyleDec+'" value="'+fmt(provDec).replace('.','').replace(',','.')+'" onchange="setFolhaValor(&#39;'+f.mat+'&#39;,&#39;decTerceiro&#39;,this.value)" title="Provisão 13º salário"></td>'+
      '<td style="background:#f0f7ff"><input type="number" min="0" step="0.01" style="'+inpStyleFer+'" value="'+fmt(provFer).replace('.','').replace(',','.')+'" onchange="setFolhaValor(&#39;'+f.mat+'&#39;,&#39;ferias&#39;,this.value)" title="Provisão férias"></td>'+
      '<td style="white-space:nowrap">'+
      '<button class="btn-edit" onclick="toggleInativarFunc(&#39;'+f.mat+'&#39;)" style="font-size:.75rem;background:#e67e22" title="Inativar">⏸️</button> '+
      '<button class="btn-edit-danger" onclick="excluirFuncionario(&#39;'+f.mat+'&#39;)" title="Excluir" style="font-size:.75rem">🗑️</button>'+
      '</td></tr>';
  }).join('');
  
  const kpis=document.getElementById('folha-kpis');
  if(kpis) kpis.innerHTML=
    '<div class="kpi r"><div class="kpi-lbl">Total Bruto</div><div class="kpi-val">R$ '+fmt(totalBruto)+'</div><div class="kpi-sub">'+lista.length+' funcionários</div></div>'+
    '<div class="kpi o"><div class="kpi-lbl">Total INSS</div><div class="kpi-val">R$ '+fmt(totalInss)+'</div><div class="kpi-sub">7,5%</div></div>'+
    '<div class="kpi g"><div class="kpi-lbl">Total Líquido</div><div class="kpi-val">R$ '+fmt(totalLiq)+'</div><div class="kpi-sub">A pagar (incl. diárias)</div></div>'+
    '<div class="kpi" style="background:#e8f5e9;border-left:4px solid #27ae60"><div class="kpi-lbl" style="color:#1a5e2a">Diárias Viagem</div><div class="kpi-val" style="color:#1a5e2a">R$ '+fmt(totalDiariasAll)+'</div><div class="kpi-sub">Incluído no líquido</div></div>'+
    '<div class="kpi" style="background:#fffbea;border-left:4px solid #c8a400"><div class="kpi-lbl" style="color:#856404">Prov. 13º Salário</div><div class="kpi-val" style="color:#856404">R$ '+fmt(totalDec)+'</div><div class="kpi-sub">1/12 por mês</div></div>'+
    '<div class="kpi" style="background:#f0f7ff;border-left:4px solid #2980b9"><div class="kpi-lbl" style="color:#1a4a7c">Prov. Férias</div><div class="kpi-val" style="color:#1a4a7c">R$ '+fmt(totalFer)+'</div><div class="kpi-sub">Sal. + 1/3</div></div>';
}

function verCustoAnual(){
  
  try{ if(_syncPonto.limparDuplicatasExatas()){ saveDB(); } }catch(e){}
  const fmt=v=>_numFinito(v,0).toLocaleString('pt-BR',{minimumFractionDigits:2});
  const mes=getFolhaMes();
  const ano=mes.split('-')[0];
  const meses=['01','02','03','04','05','06','07','08','09','10','11','12'];
  const nomeMeses=['Jan','Fev','Mar','Abr','Mai','Jun','Jul','Ago','Set','Out','Nov','Dez'];
  const lista=FUNCIONARIOS.filter(f=>f.status!=='Inativo');

  const rows=lista.map(f=>{
    let totalBruto=0,totalLiq=0,totalVales=0,totalInss=0,mesesAtivos=0;
    meses.forEach((mn,mi)=>{
      const mesRef=ano+'-'+mn;
      const key=mesRef+'-'+f.mat;
      const fd=FOLHA_DB[key]||{};
      const lancPonto=PONTO_DB.filter(p=>{
        if(p.mat!==f.mat) return false;
        if(!p.data) return false;
        const d=p.data.includes('/')?p.data.split('/').reverse().join('-'):p.data;
        return d.startsWith(mesRef);
      });
      const valesM=VALES_DB.filter(v=>{
        if(v.mat!==f.mat) return false;
        if(!v.data) return false;
        const d=v.data.includes('/')?v.data.split('/').reverse().join('-'):v.data;
        return d.startsWith(mesRef);
      });
      const vales=valesM.reduce((s,v)=>s+Number(v.valor),0);
    
    const viagensM=VIAGEM_DB.filter(v=>{
      if(v.motorista!==f.nome) return false;
      if(!v.data) return false;
      const d=v.data.includes('/')?v.data.split('/').reverse().join('-'):v.data;
      return d.startsWith(mes);
    });
    const qtdViagens=viagensM.length;
    
    const totalDiarias=viagensM.reduce((s,v)=>s+Number(v.totalDiarias!==undefined?v.totalDiarias:(v.diaria||0)*(v.numDiarias||1)),0);
      const faltas=lancPonto.filter(p=>p.tipo==='Falta').length;
      const atestados=lancPonto.filter(p=>p.tipo==='Atestado').length;
      const heHoras=lancPonto.filter(p=>p.tipo==='HE').reduce((s,p)=>s+Number(p.horas||0),0);
      const valorHora=f.sal/220;
      const heValor=heHoras*valorHora;
      const descFaltas=(faltas*8)*valorHora;
      const adicional=Number(fd.adicional||0);
      const abono=(faltas===0&&atestados===0)?Number(fd.abono||0):0;
      const bruto=f.sal-descFaltas+heValor+adicional+abono;
      if(bruto>0||f.sal>0){ mesesAtivos++; }
      const inss=bruto*0.075;
      let irrf=0;
      if(bruto>4664.68) irrf=bruto*0.275-869.36;
      else if(bruto>3751.05) irrf=bruto*0.225-636.13;
      else if(bruto>2826.66) irrf=bruto*0.15-354.80;
      else if(bruto>2259.20) irrf=bruto*0.075-169.44;
      if(irrf<0) irrf=0;
      const desc=inss+irrf+vales;
      const liq=bruto-desc>0?bruto-desc:0;
      totalBruto+=bruto; totalLiq+=liq; totalVales+=vales; totalInss+=inss;
    });
    
    const cfgFolha=(ERP_BUSINESS_CONFIG&&ERP_BUSINESS_CONFIG.payrollDefaults)||{};
    const taxaEncargos=Math.max(0,Number(cfgFolha.employerCostRate)||0);
    const encargos=totalBruto*taxaEncargos;
    const custoTotal=totalBruto+encargos;
    return {f,totalBruto,totalLiq,totalVales,totalInss,encargos,custoTotal,mesesAtivos};
  }).sort((a,b)=>b.custoTotal-a.custoTotal);

  const totalGeral=rows.reduce((s,r)=>s+r.custoTotal,0);
  const taxaEncargosRel=Math.max(0,Number(((ERP_BUSINESS_CONFIG&&ERP_BUSINESS_CONFIG.payrollDefaults)||{}).employerCostRate)||0);
  const tableRows=rows.map(r=>
    '<tr>'+
    '<td>'+r.f.mat+'</td>'+
    '<td><b>'+esc(r.f.nome)+'</b></td>'+
    '<td style="font-size:.78rem;color:var(--gray)">'+esc(r.f.cargo)+'</td>'+
    '<td>'+r.mesesAtivos+'/12</td>'+
    '<td style="text-align:right">R$ '+fmt(r.totalBruto)+'</td>'+
    '<td style="text-align:right;color:#e74c3c">R$ '+fmt(r.totalInss)+'</td>'+
    '<td style="text-align:right;color:#e67e22">R$ '+fmt(r.totalVales)+'</td>'+
    '<td style="text-align:right;color:#8e44ad">R$ '+fmt(r.encargos)+'</td>'+
    '<td style="text-align:right;font-weight:700;color:#c0392b">R$ '+fmt(r.custoTotal)+'</td>'+
    '</tr>'
  ).join('');

  const body=document.getElementById('modal-body');
  body.className='modal';
  body.style.maxWidth='900px';
  body.innerHTML=
    '<h3>📅 Custo Anual por Funcionário — '+ano+'</h3>'+
    '<p style="color:var(--gray);font-size:.83rem">Encargos patronais estimados em '+(taxaEncargosRel*100).toLocaleString('pt-BR',{maximumFractionDigits:2})+'%. Valores baseados nos lançamentos registrados no sistema.</p>'+
    '<div style="overflow-x:auto"><table>'+
      '<thead><tr>'+
        '<th>Matr.</th><th>Nome</th><th>Cargo</th><th>Meses</th>'+
        '<th style="text-align:right">Total Bruto</th>'+
        '<th style="text-align:right">INSS Emp.</th>'+
        '<th style="text-align:right">Vales</th>'+
        '<th style="text-align:right;color:#8e44ad">Encargos Patr.</th>'+
        '<th style="text-align:right;color:#c0392b">Custo Total</th>'+
      '</tr></thead>'+
      '<tbody>'+tableRows+'</tbody>'+
      '<tfoot><tr style="background:#f5f5f5;font-weight:700">'+
        '<td colspan="4">TOTAL GERAL '+ano+'</td>'+
        '<td colspan="4" style="text-align:right;color:var(--gray)">Todos os funcionários</td>'+
        '<td style="text-align:right;color:#c0392b;font-size:1.05rem">R$ '+fmt(totalGeral)+'</td>'+
      '</tr></tfoot>'+
    '</table></div>'+
    '<div class="modal-ft"><button class="btn-cancel" onclick="cm()">Fechar</button></div>';
  document.getElementById('modal-ov').classList.add('open');
}

function renderVales(){
  const tb=document.getElementById('tb-vales');
  if(!tb) return;
  const fmt=function(v){return _numFinito(v,0).toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2});};
  const filtroMes=_valeMesFiltroAtual();
  const listaFiltrada=_valeListaFiltrada();
  const agora=new Date();
  const mesKpi=filtroMes||agora.getFullYear()+'-'+String(agora.getMonth()+1).padStart(2,'0');
  const doMes=VALES_DB.filter(function(v){return _valeMesChave(v)===mesKpi;});
  const totalMes=doMes.reduce(function(s,v){return s+_numFinito(v.valor,0);},0);
  const totalGeral=VALES_DB.reduce(function(s,v){return s+_numFinito(v.valor,0);},0);
  const cfgV=(ERP_BUSINESS_CONFIG&&ERP_BUSINESS_CONFIG.employeeBenefits)||{};
  const diaVale=Math.max(1,Math.min(31,Number(cfgV.voucherPaymentDay)||20));
  const tituloVales=document.getElementById('vales-titulo');
  const kMes=document.getElementById('kpi-vales-mes');
  const kSub=document.getElementById('kpi-vales-mes-sub');
  const kAberto=document.getElementById('kpi-vales-aberto');
  const kTotal=document.getElementById('kpi-vales-total');
  const count=document.getElementById('vales-filtro-count');
  const [anoK,mnK]=mesKpi.split('-');
  const nomeMesK=new Date(Number(anoK),Number(mnK)-1,1).toLocaleDateString('pt-BR',{month:'long',year:'numeric'});
  if(tituloVales) tituloVales.textContent='💳 Controle de Vales – Pagamento Dia '+diaVale;
  if(kMes) kMes.textContent='R$ '+fmt(totalMes);
  if(kSub) kSub.textContent='Dia '+diaVale+' · '+nomeMesK;
  if(kAberto) kAberto.textContent=String(doMes.length);
  if(kTotal) kTotal.textContent='R$ '+fmt(totalGeral);
  if(count) count.textContent=filtroMes?('Vales encontrados: '+listaFiltrada.length):('Todos os vales: '+VALES_DB.length);
  if(listaFiltrada.length===0){
    tb.innerHTML='<tr><td colspan="9" style="color:var(--gray);text-align:center;padding:20px">Nenhum vale encontrado para o período selecionado</td></tr>';
    return;
  }
  const sorted=listaFiltrada.slice().sort(function(a,b){
    const pa=String(a&&a.data||'').split('/'), pb=String(b&&b.data||'').split('/');
    const da=pa.length===3?new Date(Number(pa[2]),Number(pa[1])-1,Number(pa[0])).getTime():Date.parse(a&&a.data||'')||0;
    const db=pb.length===3?new Date(Number(pb[2]),Number(pb[1])-1,Number(pb[0])).getTime():Date.parse(b&&b.data||'')||0;
    return db-da;
  });
  tb.innerHTML=sorted.map(function(v){
    const gi=VALES_DB.indexOf(v);
    const f=FUNCIONARIOS.find(function(x){return x.mat===v.mat;});
    const nome=f?f.nome:v.mat;
    const assBadge=v.assinatura
      ?'<span style="background:#e8f5e9;color:#2e7d32;border-radius:10px;padding:2px 8px;font-size:.72rem;font-weight:700">✅ Assinado</span>'
      :'<span style="background:#fff3cd;color:#856404;border-radius:10px;padding:2px 8px;font-size:.72rem;font-weight:700">⏳ Pendente</span>';
    return '<tr>'+ 
      '<td>'+esc(v.mat||'—')+'</td>'+ 
      '<td>'+esc(_fmtDataBR(v.data)||'—')+'</td>'+ 
      '<td>'+esc(v.mes||'—')+'</td>'+ 
      '<td><b>'+esc(nome||'—')+'</b></td>'+ 
      '<td style="font-weight:700">R$ '+fmt(v.valor)+'</td>'+ 
      '<td>'+esc(v.forma||'—')+'</td>'+ 
      '<td style="font-size:.78rem">'+esc(v.obs||'—')+'</td>'+ 
      '<td style="white-space:nowrap;text-align:center">'+assBadge+
        '<br><div style="margin-top:4px;display:flex;gap:4px;justify-content:center">'+
        '<button class="btn-edit" style="font-size:.72rem;background:#1565c0;color:#fff" onclick="valeAssinarModal('+gi+',\''+String(v.mat||'').replace(/'/g,"\\'")+'\')" title="Capturar assinatura">✍️ Assinar</button>'+ 
        '<button class="btn-edit" style="font-size:.72rem;background:#2e7d32;color:#fff" onclick="valeGerarRecibo('+gi+')" title="Gerar recibo">📄 Recibo</button>'+ 
        '</div></td>'+ 
      '<td style="white-space:nowrap"><button class="btn-edit" onclick="editVale('+gi+')" title="Editar" style="margin-right:4px">✏️</button>'+ 
      '<button class="btn-edit-danger" onclick="excluirVale('+gi+')" title="Excluir">🗑️</button></td>'+ 
      '</tr>';
  }).join('');
}

function salvarPontoLancamento(){
  const mat=document.getElementById('pt-func')?.value;
  const data=document.getElementById('pt-data')?.value;
  const tipo=document.getElementById('pt-tipo')?.value||'Falta';
  const horas=parseFloat(document.getElementById('pt-horas')?.value)||0;
  if(!mat){alert('Selecione o funcionário.');return;}
  if(!data){alert('Informe a data.');return;}
  const dataFmt=data.split('-').reverse().join('/');
  PONTO_DB.push({mat,data:dataFmt,tipo,horas,obs:document.getElementById('pt-obs')?.value||''});
  saveDB();
  renderPontoTab();
  cm();
  alert('✅ Lançamento registrado!');
}

function salvarValeFunc(){
  const mat=document.getElementById('vl-func')?.value;
  const data=document.getElementById('vl-data')?.value;
  const valor=parseFloat(document.getElementById('vl-valor')?.value)||0;
  if(!mat){alert('Selecione o funcionário.');return;}
  if(!valor||valor<=0){alert('Informe o valor do vale.');return;}
  const dataFmt=data?data.split('-').reverse().join('/'):'';
  VALES_DB.push({
    mat,
    data:dataFmt,
    mes:document.getElementById('vl-mes')?.value||'',
    valor,
    forma:document.getElementById('vl-forma')?.value||'PIX',
    obs:document.getElementById('vl-obs')?.value||''
  });
  saveDB();
  renderVales();
  cm();
  alert('✅ Vale registrado!');
}

function excluirVale(idx){
  const v=VALES_DB[idx];
  if(!v||!confirm('Excluir vale de R$ '+Number(v.valor).toFixed(2)+'?')) return;
  _syncVales.remover(idx);
  saveDB();
  renderVales();
}


function _diasUteisNoMes(ano,mesIndex){
  let total=0;
  const dias=new Date(ano,mesIndex+1,0).getDate();
  for(let d=1;d<=dias;d++){
    const wd=new Date(ano,mesIndex,d).getDay();
    if(wd!==0&&wd!==6) total++;
  }
  return total;
}
function renderPontoTab(){
  const tb=document.getElementById('tb-ponto');
  if(!tb) return;
  const agora=new Date();
  const mes=String(agora.getMonth()+1).padStart(2,'0');
  const ano=String(agora.getFullYear());
  const lancamentosMes=PONTO_DB.filter(function(p){
    const partes=String(p&&p.data||'').split('/');
    return partes.length===3 && partes[1]===mes && partes[2]===ano;
  });
  const diasUteis=_diasUteisNoMes(agora.getFullYear(),agora.getMonth());
  const ativos=FUNCIONARIOS.filter(function(f){ return f && f.status!=='Inativo'; }).length;
  const faltasMes=lancamentosMes.filter(function(p){ return p.tipo==='Falta'; }).length;
  const horasExtrasMes=lancamentosMes.filter(function(p){ return p.tipo==='HE'; }).reduce(function(total,p){ return total+Number(p.horas||0); },0);
  const kDias=document.getElementById('kpi-ponto-dias-uteis');
  const kFunc=document.getElementById('kpi-ponto-funcionarios');
  const kFaltas=document.getElementById('kpi-ponto-faltas');
  const kHe=document.getElementById('kpi-ponto-he');
  if(kDias) kDias.textContent=String(diasUteis);
  if(kFunc) kFunc.textContent=String(ativos);
  if(kFaltas) kFaltas.textContent=String(faltasMes);
  if(kHe) kHe.textContent=(Number.isInteger(horasExtrasMes)?String(horasExtrasMes):horasExtrasMes.toLocaleString('pt-BR',{maximumFractionDigits:2}))+'h';
  
  
  
  
  
  
  
  
  
  
  
  try{ if(_syncPonto.limparDuplicatasExatas()){ saveDB(); } }catch(e){}
  tb.innerHTML=FUNCIONARIOS.map(f=>{
    const lancs=lancamentosMes.filter(p=>p.mat===f.mat);
    const faltas=lancs.filter(p=>p.tipo==='Falta').length;
    const he=lancs.filter(p=>p.tipo==='HE').reduce((s,p)=>s+Number(p.horas||0),0);
    const hf=lancs.filter(p=>p.tipo==='Falta').reduce((s,p)=>s+8,0);
    const ates=lancs.filter(p=>p.tipo==='Atestado').length;
    const diasTrab=Math.max(0,diasUteis-faltas);
    return '<tr>'+
      '<td>'+f.mat+'</td><td><b>'+esc(f.nome)+'</b></td>'+
      '<td>'+diasTrab+'</td><td>'+faltas+'</td>'+
      '<td>'+he+'h</td><td>'+hf+'h</td><td>'+ates+'</td>'+
      '<td style="font-size:.75rem">'+(lancs.map(l=>l.tipo+' '+l.data).join(', ')||'—')+'</td>'+
      '<td><button class="btn-edit-danger" onclick="excluirPontoFunc(&#39;'+f.mat+'&#39;)" title="Excluir lançamentos">🗑️</button></td>'+
      '</tr>';
  }).join('');

  try{ _popularSelectPontoFuncionarios(); }catch(e){}
  try{ renderCartaoPontoImportado(); }catch(e){}
}




function _popularSelectPontoFuncionarios(){
  const sel=document.getElementById('ponto-cartao-func');
  if(!sel) return;
  const valorAtual=sel.value;
  const matsComDados=new Set(PONTO_BATIDAS_DB.map(r=>r.mat));
  const funcs=FUNCIONARIOS.filter(f=>matsComDados.has(f.mat)).sort((a,b)=>a.nome.localeCompare(b.nome));
  sel.innerHTML='<option value="">— Selecione —</option>'+
    funcs.map(f=>'<option value="'+f.mat+'">'+esc(f.nome)+'</option>').join('');
  if(valorAtual && matsComDados.has(valorAtual)) sel.value=valorAtual;
}




function renderCartaoPontoImportado(){
  const host=document.getElementById('ponto-cartao-host');
  if(!host) return;
  const mat=document.getElementById('ponto-cartao-func')?.value;
  const mesFiltro=document.getElementById('ponto-cartao-mes')?.value; 
  if(!mat){ host.innerHTML='<div style="color:#888;font-size:.85rem;padding:10px 0">Selecione um funcionário pra ver o cartão de ponto importado.</div>'; return; }

  let regs=PONTO_BATIDAS_DB.filter(r=>r.mat===mat);
  if(mesFiltro){
    const [ano,mes]=mesFiltro.split('-');
    regs=regs.filter(r=>{
      const partes=(r.data||'').split('/'); 
      return partes.length===3 && partes[1]===mes && partes[2]===ano;
    });
  }
  if(!regs.length){ host.innerHTML='<div style="color:#888;font-size:.85rem;padding:10px 0">Nenhuma batida importada pra esse funcionário'+(mesFiltro?' nesse mês':'')+'.</div>'; return; }

  
  function isoData(d){ const p=(d||'').split('/'); return p.length===3 ? p[2]+'-'+p[1]+'-'+p[0] : ''; }
  regs=regs.slice().sort((a,b)=>isoData(a.data).localeCompare(isoData(b.data)));

  
  
  const extraChaves=new Set();
  regs.forEach(r=>Object.keys(r.extras||{}).forEach(k=>extraChaves.add(k)));
  const extraChavesOrdenadas=[...extraChaves].sort();
  function labelExtra(chave){
    const partes=chave.split('_'); 
    return 'EXTRA '+partes[1]+'%'+partes[2];
  }

  const th='<th>Dia</th><th>Previsto</th><th>Ent.1</th><th>Saí.1</th><th>Ent.2</th><th>Saí.2</th><th>Ent.3</th><th>Saí.3</th><th>Total Trab.</th><th>Falta e Atraso</th>'+
    extraChavesOrdenadas.map(c=>'<th>'+labelExtra(c)+'</th>').join('');

  const linhas=regs.map(r=>{
    const extrasTd=extraChavesOrdenadas.map(c=>'<td>'+esc((r.extras&&r.extras[c]&&r.extras[c].valor)||'')+'</td>').join('');
    return '<tr>'+
      '<td>'+esc(r.data)+' - '+esc(r.diaSemana||'')+'</td>'+
      '<td style="font-size:.75rem">'+esc(r.previsto||'')+'</td>'+
      '<td>'+esc(r.ent1||'')+'</td><td>'+esc(r.sai1||'')+'</td>'+
      '<td>'+esc(r.ent2||'')+'</td><td>'+esc(r.sai2||'')+'</td>'+
      '<td>'+esc(r.ent3||'')+'</td><td>'+esc(r.sai3||'')+'</td>'+
      '<td><b>'+esc(r.total||'')+'</b></td>'+
      '<td style="color:#c0392b">'+esc(r.faltaAtraso||'')+'</td>'+
      extrasTd+
      '</tr>';
  }).join('');

  const origem=regs[0];
  host.innerHTML='<div style="font-size:.78rem;color:#888;margin-bottom:8px">Importado do RH iD em '+esc(origem.importadoEm||'—')+
    (origem.periodoInicio?(' — período exportado: '+esc(origem.periodoInicio)+' a '+esc(origem.periodoFim)):'')+'</div>'+
    '<table><thead><tr>'+th+'</tr></thead><tbody>'+linhas+'</tbody></table>';
}

function excluirPontoFunc(mat){
  const f=FUNCIONARIOS.find(x=>x.mat===mat);
  if(!confirm('Excluir todos os lançamentos de ponto de '+(f?f.nome:mat)+'?')) return;
  const before=PONTO_DB.length;
  
  
  for(let i=PONTO_DB.length-1;i>=0;i--){ if(PONTO_DB[i] && PONTO_DB[i].mat===mat) _syncPonto.remover(i); }
  saveDB();
  renderPontoTab();
  alert('✅ '+(before-PONTO_DB.length)+' lançamento(s) removido(s).');
}


function adtTipoTab(tipo){
  const painForn=document.getElementById('adt-painel-forn');
  const painCli=document.getElementById('adt-painel-cli');
  const btnForn=document.getElementById('adt-tipo-forn-btn');
  const btnCli=document.getElementById('adt-tipo-cli-btn');
  const ativo='font-weight:700;color:#1a3a2a;border-bottom:3px solid #1a3a2a';
  const inativo='font-weight:400;color:#999;border-bottom:3px solid transparent';
  if(tipo==='forn'){
    if(painForn) painForn.style.display='';
    if(painCli)  painCli.style.display='none';
    if(btnForn) btnForn.style.cssText=btnForn.style.cssText.replace(/font-weight:[^;]+;color:[^;]+;border-bottom:[^;]+/,ativo);
    if(btnCli)  btnCli.style.cssText=btnCli.style.cssText.replace(/font-weight:[^;]+;color:[^;]+;border-bottom:[^;]+/,inativo);
  } else {
    if(painForn) painForn.style.display='none';
    if(painCli)  painCli.style.display='';
    if(btnForn) btnForn.style.cssText=btnForn.style.cssText.replace(/font-weight:[^;]+;color:[^;]+;border-bottom:[^;]+/,inativo);
    if(btnCli)  btnCli.style.cssText=btnCli.style.cssText.replace(/font-weight:[^;]+;color:[^;]+;border-bottom:[^;]+/,ativo);
    renderAdtCli();
    renderChequesCli();
  }
}


function saveAdtCli(){ localStorage.setItem('mm_adt_cli', JSON.stringify(ADT_CLI)); fbSalvar(); }
function saveChequesCli(){ localStorage.setItem('mm_cheques_cli', JSON.stringify(CHEQUES_CLI)); fbSalvar(); }






let _fcAba='extrato';
let _fcCliente='';
function _fcMoneyFmt(v){ return 'R$ '+_numFinito(v,0).toLocaleString('pt-BR',{minimumFractionDigits:2}); }
function _fcNomeKey(v){ return String(v||'').trim().toUpperCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/\s+/g,' '); }
function _fcMesmoNome(a,b){ return _fcNomeKey(a)===_fcNomeKey(b); }
function _fcData2Ord(d){ if(!d) return '00000000'; if(d.indexOf('/')>=0){ const p=d.split('/'); return (p[2]||'0000')+(p[1]||'00')+(p[0]||'00'); } return d.replace(/-/g,''); }
function _fcClientesAtivos(){
  return [...new Set((CLIENTES||[]).map(c=>c&&c.nome).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'pt-BR'));
}
function _fcClientesHistoricosSemCadastro(){
  const ativos=new Set(_fcClientesAtivos());
  const nomes=new Set();
  (typeof VENDAS_DB!=='undefined'?VENDAS_DB:[]).forEach(v=>{if(v&&v.cliente)nomes.add(v.cliente);});
  Object.keys(ADT_CLI||{}).forEach(n=>{if(n)nomes.add(n);});
  Object.keys(CHEQUES_CLI||{}).forEach(n=>{if(n)nomes.add(n);});
  (typeof CONTAS_RECEBER!=='undefined'?CONTAS_RECEBER:[]).forEach(c=>{if(c&&c.cli)nomes.add(c.cli);});
  try{Object.values(CHQ_CTRL||{}).forEach(c=>{if(c&&c.clienteNome)nomes.add(c.clienteNome);});}catch(e){}
  return [...nomes].filter(n=>!ativos.has(n)).sort((a,b)=>a.localeCompare(b,'pt-BR'));
}
function _fcListaClientes(){return _fcClientesAtivos().concat(_fcClientesHistoricosSemCadastro());}
function _fcMovimentos(cli){
  const mov=[];
  (typeof VENDAS_DB!=='undefined'?VENDAS_DB:[]).forEach(function(v){
    if(!v||!_fcMesmoNome(v.cliente,cli)) return;
    const kg=(v.itens||[]).reduce((s,it)=>s+Number(it.qt||0),0);
    mov.push({ord:_fcData2Ord(v.data), data:v.data||'—', tipo:'venda', desc:'Venda'+(v.nf?' NF '+v.nf:'')+(v.itens&&v.itens[0]?' — '+esc(v.itens[0].mat||''):''), kg:kg, deb:Number(v.total||0), cred:0});
  });
  Object.keys(ADT_CLI||{}).filter(function(k){return _fcMesmoNome(k,cli);}).forEach(function(k){ (ADT_CLI[k]||[]).forEach(function(a){
    mov.push({ord:_fcData2Ord(a.data), data:a.data||'—', tipo:'adt', desc:'Adiantamento'+(a.forma?' ('+esc(a.forma)+')':'')+(a.vinculo?' — '+esc(a.vinculo):''), kg:0, deb:0, cred:Number(a.valor||0)});
  }); });
  Object.keys(CHEQUES_CLI||{}).filter(function(k){return _fcMesmoNome(k,cli);}).forEach(function(k){ (CHEQUES_CLI[k]||[]).forEach(function(c){
    mov.push({ord:_fcData2Ord(c.bomPara||c.data), data:(c.bomPara||c.data||'—'), tipo:'cheq', desc:'Cheque nº '+esc(c.num||'—')+(c.banco?' — '+esc(c.banco):''), kg:0, deb:0, cred:Number(c.valor||0)});
  }); });
  try{
    const _ja=new Set(Object.keys(CHEQUES_CLI||{}).filter(function(k){return _fcMesmoNome(k,cli);}).flatMap(function(k){return CHEQUES_CLI[k]||[];}).map(function(c){ return String(c.num||'')+'|'+Number(c.valor||0).toFixed(2)+'|'+String(c.bomPara||c.data||''); }));
    Object.values(CHQ_CTRL||{}).forEach(function(c){
      if(!c) return;
      const ligado=_fcMesmoNome(c.clienteNome||c.c,cli);
      if(!ligado) return;
      const chave=String(c.n||'')+'|'+Number(c.v||0).toFixed(2)+'|'+String(c.venc||c.d||'');
      if(_ja.has(chave)) return;
      mov.push({ord:_fcData2Ord(c.venc||c.d), data:(c.venc||c.d||'—'), tipo:'cheq', desc:'Cheque nº '+esc(c.n||'—')+(c.b?' — '+esc(c.b):''), kg:0, deb:0, cred:Number(c.v||0)});
    });
  }catch(e){}
  (typeof CONTAS_RECEBER!=='undefined'?CONTAS_RECEBER:[]).forEach(function(cr){
    if(!cr||!_fcMesmoNome(cr.cli,cli)) return;
    if(cr.status!=='Recebido') return;
    if(cr.forma==='Adiantamento'||cr.forma==='Cheque') return; 
    mov.push({ord:_fcData2Ord(cr.dataReceb||cr.data), data:(cr.dataReceb||cr.data||'—'), tipo:'pag', desc:'Pagamento'+(cr.forma?' ('+esc(cr.forma)+')':'')+(cr.nf?' — NF '+esc(cr.nf):'')+(cr.obs?' — '+esc(cr.obs):''), kg:0, deb:0, cred:Number(cr.valor||0)});
  });
  mov.sort((a,b)=>a.ord.localeCompare(b.ord));
  return mov;
}
function _fcTotais(cli){
  const mov=_fcMovimentos(cli); let deb=0,cred=0,kg=0;
  mov.forEach(m=>{deb+=m.deb;cred+=m.cred;kg+=m.kg;});
  return {mov,deb,cred,kg,saldo:deb-cred};
}
function fcSetAba(a){
  _fcAba=a;
  ['extrato','resumo','antigo'].forEach(function(n){
    const v=document.getElementById('fc-view-'+n); if(v) v.style.display=(n===a?'':'none');
    const b=document.getElementById('fc-aba-'+n); if(b){ const at=(n===a); b.style.borderBottomColor=at?'#1a5e2a':'transparent'; b.style.color=at?'#1a5e2a':'#999'; }
  });
  if(a==='resumo') fcRenderResumo();
  if(a==='antigo'){ try{ renderAdtCli(); }catch(e){} try{ renderChequesCli(); }catch(e){} }
}
let _fcFiltroChip='';
function renderFichaCliente(){
  if(!window.__ERP_FINANCE_CLOUD_READY__){ const box=document.getElementById('fc-cli-box'); if(box&&!box.children.length) box.innerHTML='<span style="color:#888;font-size:.85rem">Sincronizando histórico financeiro...</span>'; }
  if(_fcCliente && !_fcListaClientes().includes(_fcCliente)) _fcCliente='';
  fcRenderChips();
  if(_fcCliente) fcSelecionarCliente(_fcCliente);
}
function fcRenderChips(){
  const box=document.getElementById('fc-cli-box'); if(!box) return;
  const termo=(_fcFiltroChip||'').toLowerCase().trim();
  let lista=_fcListaClientes();
  if(termo) lista=lista.filter(c=>c.toLowerCase().indexOf(termo)>=0);
  if(!lista.length){ box.innerHTML='<span style="color:#999;font-size:.85rem">Nenhum cliente encontrado.</span>'; return; }
  const ativos=new Set(_fcClientesAtivos());
  box.innerHTML=lista.map(function(c){
    const sel=(c===_fcCliente);
    const historico=!ativos.has(c);
    const cc=esc(c).replace(/'/g,"\\'");
    return '<div title="'+(historico?'Sem cadastro ativo: histórico financeiro preservado':'Cliente cadastrado')+'" onclick="fcSelecionarCliente(\''+cc+'\')" style="padding:8px 16px;border:2px solid '+(sel?'#1a5e2a':'#cfe3d6')+';border-radius:22px;background:'+(sel?'#1a5e2a':'#fff')+';color:'+(sel?'#fff':'#1a5e2a')+';cursor:pointer;font-weight:700;font-size:.85rem">'+(historico?'⚠️ Histórico: ':'')+esc(c)+'</div>';
  }).join('');
}
function fcFiltrarChips(v){ _fcFiltroChip=v||''; fcRenderChips(); }
function fcSelecionarCliente(cli){
  _fcCliente=(cli||'').trim();
  fcRenderChips();
  const temCli=!!_fcCliente;
  const show=id=>{ const e=document.getElementById(id); if(e) e.style.display=temCli?'':'none'; };
  document.getElementById('fk-kpis').style.display=temCli?'grid':'none';
  document.getElementById('fc-lancar').style.display=temCli?'flex':'none';
  document.getElementById('fc-extrato-card').style.display=temCli?'':'none';
  document.getElementById('fc-vazio').style.display=temCli?'none':'';
  if(!temCli) return;
  const t=_fcTotais(_fcCliente);
  document.getElementById('fc-cli-nome').textContent=_fcCliente;
  document.getElementById('fc-k-kg').textContent=Number(t.kg).toLocaleString('pt-BR',{minimumFractionDigits:1})+' kg';
  document.getElementById('fc-k-deb').textContent=_fcMoneyFmt(t.deb);
  document.getElementById('fc-k-cred').textContent=_fcMoneyFmt(t.cred);
  document.getElementById('fc-k-saldo').textContent=_fcMoneyFmt(t.saldo);
  const pills={venda:['Venda','#fdecea','#c0392b'],adt:['Adiantamento','#e8f5e9','#1a5e2a'],cheq:['Cheque','#f3e9fb','#6a1b9a'],pag:['Pagamento','#e3f0fb','#1565c0']};
  let saldo=0;
  const tb=document.getElementById('fc-extrato');
  if(!t.mov.length){ tb.innerHTML='<tr><td colspan="6" style="text-align:center;color:#999;padding:18px">Nenhum lançamento para este cliente ainda.</td></tr>'; }
  else tb.innerHTML=t.mov.map(function(m){
    saldo+=m.deb-m.cred;
    const p=pills[m.tipo]||['',' #eee','#333'];
    const sc=saldo>0.009?'color:#c0392b;font-weight:800':(saldo<-0.009?'color:#1a5e2a;font-weight:800':'font-weight:800');
    return '<tr>'+
      '<td>'+esc(m.data)+'</td>'+
      '<td><span style="display:inline-block;border-radius:20px;padding:2px 10px;font-size:.72rem;font-weight:700;background:'+p[1]+';color:'+p[2]+'">'+p[0]+'</span></td>'+
      '<td style="font-size:.83rem">'+m.desc+(m.kg?' <span style="color:#888">('+Number(m.kg).toLocaleString('pt-BR',{minimumFractionDigits:1})+' kg)</span>':'')+'</td>'+
      '<td style="text-align:right">'+(m.deb?'<span style="color:#c0392b;font-weight:700">'+_fcMoneyFmt(m.deb)+'</span>':'—')+'</td>'+
      '<td style="text-align:right">'+(m.cred?'<span style="color:#1a5e2a;font-weight:700">'+_fcMoneyFmt(m.cred)+'</span>':'—')+'</td>'+
      '<td style="text-align:right;'+sc+'">'+_fcMoneyFmt(saldo)+'</td>'+
    '</tr>';
  }).join('');
  const sit=document.getElementById('fc-situacao');
  const kSit=document.getElementById('fc-k-sit');
  if(Math.abs(t.saldo)<0.009){ sit.innerHTML='<span style="background:#e8f5e9;color:#1a5e2a;border-radius:8px;padding:4px 12px;font-weight:800">✅ Cliente QUITADO</span>'; if(kSit)kSit.textContent='Quitado'; }
  else if(t.saldo>0){ sit.innerHTML='<span style="background:#fdecea;color:#c0392b;border-radius:8px;padding:4px 12px;font-weight:800">🔴 Cliente DEVE '+_fcMoneyFmt(t.saldo)+'</span>'; if(kSit)kSit.textContent='A receber'; }
  else { sit.innerHTML='<span style="background:#e8f5e9;color:#1a5e2a;border-radius:8px;padding:4px 12px;font-weight:800">🟢 Cliente tem CRÉDITO de '+_fcMoneyFmt(-t.saldo)+'</span>'; if(kSit)kSit.textContent='Crédito a favor'; }
}
function fcRenderResumo(){
  const tb=document.getElementById('fc-resumo'); if(!tb) return;
  let gKg=0,gDeb=0,gCred=0;
  const linhas=_fcListaClientes().map(function(c){
    const t=_fcTotais(c); gKg+=t.kg; gDeb+=t.deb; gCred+=t.cred;
    if(t.deb===0 && t.cred===0) return '';
    const sit=Math.abs(t.saldo)<0.009?'<span style="color:#1a5e2a;font-weight:700">✅ Quitado</span>':(t.saldo>0?'<span style="color:#c0392b;font-weight:700">🔴 Deve</span>':'<span style="color:#1a5e2a;font-weight:700">🟢 Crédito</span>');
    const sc=t.saldo>0.009?'color:#c0392b;font-weight:700':(t.saldo<-0.009?'color:#1a5e2a;font-weight:700':'font-weight:700');
    const semCadastro=!_fcClientesAtivos().includes(c);
    return '<tr>'+
      '<td style="font-weight:700;cursor:pointer;color:#1a5e2a" onclick="fcSetAba(\'extrato\');fcSelecionarCliente(\''+esc(c).replace(/'/g,"\\'")+'\')">'+(semCadastro?'⚠️ Histórico sem cadastro: ':'')+esc(c)+'</td>'+
      '<td style="text-align:right">'+Number(t.kg).toLocaleString('pt-BR',{minimumFractionDigits:1})+'</td>'+
      '<td style="text-align:right;color:#c0392b">'+_fcMoneyFmt(t.deb)+'</td>'+
      '<td style="text-align:right;color:#1a5e2a">'+_fcMoneyFmt(t.cred)+'</td>'+
      '<td style="text-align:right;'+sc+'">'+_fcMoneyFmt(t.saldo)+'</td>'+
      '<td>'+sit+'</td>'+
    '</tr>';
  }).filter(Boolean).join('');
  tb.innerHTML=linhas||'<tr><td colspan="6" style="text-align:center;color:#999;padding:18px">Sem movimentação de clientes ainda.</td></tr>';
  document.getElementById('fc-resumo-total').innerHTML='<tr style="background:#1a3a2a;color:#fff;font-weight:800"><td>💰 TOTAL GERAL</td><td style="text-align:right">'+Number(gKg).toLocaleString('pt-BR',{minimumFractionDigits:1})+'</td><td style="text-align:right">'+_fcMoneyFmt(gDeb)+'</td><td style="text-align:right">'+_fcMoneyFmt(gCred)+'</td><td style="text-align:right">'+_fcMoneyFmt(gDeb-gCred)+'</td><td>—</td></tr>';
}

function _fcPrefill(id,val){ setTimeout(function(){ const e=document.getElementById(id); if(e){ e.value=val; try{ e.dispatchEvent(new Event('input',{bubbles:true})); e.dispatchEvent(new Event('change',{bubbles:true})); }catch(x){} } },120); }
function fcLancarVenda(){ om('venda'); _fcPrefill('v-cliente',_fcCliente); }
function fcLancarAdiantamento(){ om('adiantamento_cli'); _fcPrefill('adtcli-cli',_fcCliente); }
function fcLancarCheque(){ om('cheque_cli'); _fcPrefill('cheqcli-cli',_fcCliente); }
function fcLancarPagamento(){
  if(!_fcCliente){ alert('Escolha um cliente primeiro.'); return; }
  const body=document.getElementById('modal-body'); if(!body) return;
  document.querySelectorAll('.modal-ov[data-dynamic="1"]').forEach(e=>e.remove());
  const ov=document.createElement('div'); ov.className='modal-ov open'; ov.id='modal-ov'; ov.dataset.dynamic='1';
  const bx=document.createElement('div'); bx.id='modal-body'; bx.className='modal';
  ov.appendChild(bx); document.body.appendChild(ov);
  const bancos=(typeof BANCOS_DB!=='undefined'&&Array.isArray(BANCOS_DB)?BANCOS_DB:[]).map(b=>'<option value="'+esc(b.banco)+'">'+esc(b.banco)+'</option>').join('');
  bx.innerHTML='<h3>💵 Pagamento recebido — '+esc(_fcCliente)+'</h3>'+
    '<div style="font-size:.8rem;color:#666;margin-bottom:10px">Use para registrar um pagamento recebido (inclusive quando o cliente do seu cliente paga direto pra sua empresa).</div>'+
    '<div class="fg"><label>Data</label><input id="fcp-data" type="date" value="'+new Date().toISOString().slice(0,10)+'"></div>'+
    '<div class="fg"><label>Valor R$</label><input id="fcp-valor" type="number" min="0" step="0.01" placeholder="0,00"></div>'+
    '<div class="fg"><label>Forma</label><select id="fcp-forma"><option>PIX</option><option>TED</option><option>Dinheiro</option><option>Depósito</option><option>Pagamento direto (cliente do cliente)</option></select></div>'+
    '<div class="fg"><label>Banco de Entrada</label><select id="fcp-banco"><option value="">— Selecione —</option>'+bancos+'</select></div>'+
    '<div class="fg"><label>Obs.</label><input id="fcp-obs" placeholder="Ex: NF referente, quem pagou..."></div>'+
    '<div class="modal-ft"><button class="btn-cancel" onclick="cm()">Cancelar</button><button class="btn-save" onclick="fcSalvarPagamento()">💾 Salvar Pagamento</button></div>';
}
function fcSalvarPagamento(){
  const valor=parseFloat(document.getElementById('fcp-valor')?.value)||0;
  if(valor<=0){ alert('Informe um valor válido.'); return; }
  const dataISO=document.getElementById('fcp-data')?.value||new Date().toISOString().slice(0,10);
  const dataBR=dataISO.split('-').reverse().join('/');
  CONTAS_RECEBER.push({
    data:dataBR, cli:_fcCliente, nf:'',
    valor:valor, forma:(document.getElementById('fcp-forma')?.value||'Pagamento'),
    banco:(document.getElementById('fcp-banco')?.value||''),
    venc:dataBR, status:'Recebido', dataReceb:dataBR,
    obs:(document.getElementById('fcp-obs')?.value||'').trim()||'Pagamento avulso'
  });
  try{ saveContasReceber(); }catch(e){}
  try{ renderContasReceber(); }catch(e){}
  cm();
  fcSelecionarCliente(_fcCliente,true);
  showToast('✅ Pagamento registrado para '+_fcCliente,'success');
}
function saveFcLanc(){ try{ localStorage.setItem('mm_fc_lanc', JSON.stringify(FC_LANC)); localStorage.setItem('mm_fc_saldoini', JSON.stringify(FC_SALDO_INI)); }catch(_){ } if(typeof fbSalvar==='function') fbSalvar(); }


function _popularClientesSel(){
  const opts='<option value="">— Selecione o cliente —</option>'+(CLIENTES||[]).slice().sort((a,b)=>String(a.nome||'').localeCompare(String(b.nome||''),'pt-BR',{sensitivity:'base'})).map(c=>`<option value="${esc(c.nome)}">${esc(c.nome)}</option>`).join('');
  ['adtcli-cli','cheqcli-cli'].forEach(id=>{ const s=document.getElementById(id); if(s) s.innerHTML=opts; });
}

function _popularClientesVenda(){
  const dl=document.getElementById('dlist-clientes-venda');
  if(dl) dl.innerHTML=(CLIENTES||[]).slice().sort((a,b)=>(a.nome||'').localeCompare(b.nome||'','pt-BR')).map(c=>`<option value="${esc(c.nome)}">`).join('');
}

function vClienteInfo(){
  try{ aplicarPrecosClienteVenda(); }catch(e){}
  const box=document.getElementById('v-cliente-info');
  if(!box) return;
  const nome=(document.getElementById('v-cliente')?.value||'').trim();
  if(!nome){ box.innerHTML=''; return; }
  const fmt=v=>Number(v||0).toLocaleString('pt-BR',{minimumFractionDigits:2});
  const adts=(ADT_CLI[nome]||[]).filter(a=>(a.status||'Pendente')==='Pendente');
  const totAdt=adts.reduce((s,a)=>s+Number(a.valor||0),0);
  const chsPend=(CHEQUES_CLI[nome]||[]).filter(c=>{ const st=(c.status||'Pendente'); return st!=='Compensado' && st!=='Devolvido' && st!=='Quitado'; });
  const totCh=chsPend.reduce((s,c)=>s+Number(c.valor||0),0);
  if(!adts.length && !chsPend.length){
    box.innerHTML='<div style="font-size:.8rem;color:#888;background:#f5f5f5;border-radius:8px;padding:6px 10px">Cliente sem adiantamentos ou cheques pendentes.</div>';
    return;
  }
  let html='<div style="background:#e8f5e9;border:1.5px solid #a5d6a7;border-radius:8px;padding:8px 12px;font-size:.82rem;color:#1b5e20">';
  html+='<b>💰 '+esc(nome)+' já enviou (pendente) — marque o que abater desta venda:</b><br>';
  (ADT_CLI[nome]||[]).forEach(function(a,i){
    if((a.status||'Pendente')!=='Pendente') return;
    html+='<label style="display:block;margin:3px 0;cursor:pointer"><input type="checkbox" class="v-abate-adt" data-idx="'+i+'" onchange="vRecalcAbate()"> Adiantamento '+esc(a.data)+' — <b>R$ '+fmt(a.valor)+'</b>'+(a.forma?' ('+esc(a.forma)+')':'')+'</label>';
  });
  (CHEQUES_CLI[nome]||[]).forEach(function(c,i){
    const st=(c.status||'Pendente'); if(st==='Compensado'||st==='Devolvido'||st==='Quitado') return;
    html+='<label style="display:block;margin:3px 0;cursor:pointer"><input type="checkbox" class="v-abate-cheq" data-idx="'+i+'" onchange="vRecalcAbate()"> Cheque nº '+esc(c.num||'—')+' bom p/ '+esc(c.bomPara||'—')+' — <b>R$ '+fmt(c.valor)+'</b></label>';
  });
  html+='<div style="border-top:1px dashed #a5d6a7;margin-top:5px;padding-top:5px;color:#555">Disponível: <b>R$ '+fmt(totAdt+totCh)+'</b> · Selecionado p/ abater: <b id="v-abate-sel" style="color:#1b5e20">R$ 0,00</b></div>';
  html+='</div>';
  box.innerHTML=html;
}

function vRecalcAbate(){
  const nome=(document.getElementById('v-cliente')?.value||'').trim();
  let sel=0;
  document.querySelectorAll('.v-abate-adt:checked').forEach(function(chk){
    const a=(ADT_CLI[nome]||[])[Number(chk.dataset.idx)]; if(a) sel+=Number(a.valor||0);
  });
  document.querySelectorAll('.v-abate-cheq:checked').forEach(function(chk){
    const c=(CHEQUES_CLI[nome]||[])[Number(chk.dataset.idx)]; if(c) sel+=Number(c.valor||0);
  });
  const el=document.getElementById('v-abate-sel');
  if(el) el.textContent='R$ '+Number(sel).toLocaleString('pt-BR',{minimumFractionDigits:2});
  return sel;
}

function salvarAdiantamentoCli(){
  const cliNome=document.getElementById('adtcli-cli')?.value||'';
  const valor=parseFloat(document.getElementById('adtcli-valor')?.value)||0;
  const data=document.getElementById('adtcli-data')?.value||'';
  if(!cliNome||valor<=0||!data){showToast('⚠️ Preencha cliente, valor e data!','error');return;}
  if(!ADT_CLI[cliNome]) ADT_CLI[cliNome]=[];
  const cod='ADTC'+String(Date.now()).slice(-6);
  const dataFmt=data.split('-').reverse().join('/');
  const bancoCod=document.getElementById('adtcli-banco')?.value||'';
  const bancoNome=bancoCod?((BANCOS_DB.find(b=>b.cod===bancoCod)?.banco)||''):'';
  ADT_CLI[cliNome].push({
    cod, data:dataFmt, valor,
    forma: document.getElementById('adtcli-forma')?.value||'PIX',
    bancoCod, bancoNome,
    vinculo: document.getElementById('adtcli-vinculo')?.value.trim()||'',
    obs:     document.getElementById('adtcli-obs')?.value.trim()||'',
    status: 'Pendente'
  });
  saveAdtCli();
  renderAdtCli();
  cm();
  showToast('✅ Adiantamento de '+cliNome+' registrado! R$ '+valor.toLocaleString('pt-BR',{minimumFractionDigits:2}),'success');
}


function renderAdtCli(){
  const tbody=document.getElementById('tb-adtcli-list');
  if(!tbody) return;
  const fmt=v=>_numFinito(v,0).toLocaleString('pt-BR',{minimumFractionDigits:2});
  const all=[];
  Object.entries(ADT_CLI).forEach(([cliNome,lista])=>{
    lista.forEach((a,i)=>all.push({...a,cliNome,_idx:i}));
  });
  all.sort((a,b)=>{var _f=d=>{d=String(d||'');return d.indexOf('/')>=0?d.split('/').reverse().join('-'):d;};return _f(b.data).localeCompare(_f(a.data));}); 
  if(all.length===0){
    tbody.innerHTML='<tr><td colspan="9" style="color:var(--gray);text-align:center;padding:20px">Nenhum adiantamento de cliente lançado ainda</td></tr>';
  } else {
    tbody.innerHTML=all.map(a=>`<tr>
      <td>${a.cod}</td><td>${fmtDate(a.data)||'—'}</td>
      <td><b>${esc(a.cliNome)}</b></td>
      <td style="font-weight:700;color:#1a5c35">R$ ${fmt(a.valor)}</td>
      <td>${a.forma||'—'}</td>
      <td style="font-size:.78rem">${esc(a.vinculo||'—')}</td>
      <td><span class="b ${a.status==='Aplicado'?'b-pago':'b-pend'}">${a.status}</span></td>
      <td style="font-size:.78rem">${esc(a.obs||'—')}</td>
      <td><button class="btn-edit-danger" onclick="excluirAdtCli('${esc(a.cliNome)}','${a.cod}')" title="Excluir">🗑️</button></td>
    </tr>`).join('');
  }
  const pend=all.filter(a=>a.status!=='Aplicado');
  const aplic=all.filter(a=>a.status==='Aplicado');
  const fmt2=v=>'R$ '+Number(v).toLocaleString('pt-BR',{minimumFractionDigits:2});
  const k0=document.getElementById('adtcli-kpi-total');
  const k1=document.getElementById('adtcli-kpi-pend');
  const k2=document.getElementById('adtcli-kpi-quit');
  if(k0) k0.textContent=fmt2(all.reduce((s,a)=>s+Number(a.valor||0),0));
  if(k1) k1.textContent=pend.length;
  if(k2) k2.textContent=aplic.length;
}

function excluirAdtCli(cliNome,cod){
  if(!confirm('Excluir este adiantamento?')) return;
  if(ADT_CLI[cliNome]) ADT_CLI[cliNome]=ADT_CLI[cliNome].filter(a=>a.cod!==cod);
  saveAdtCli(); renderAdtCli();
  showToast('Adiantamento excluído.','warn');
}


function salvarChequeCli(){
  const cliNome=document.getElementById('cheqcli-cli')?.value||'';
  const valor=parseFloat(document.getElementById('cheqcli-valor')?.value)||0;
  const num=(document.getElementById('cheqcli-num')?.value||'').trim();
  if(!cliNome||valor<=0||!num){showToast('⚠️ Preencha cliente, nº cheque e valor!','error');return;}
  if(!CHEQUES_CLI[cliNome]) CHEQUES_CLI[cliNome]=[];
  const data=document.getElementById('cheqcli-data')?.value||'';
  const bomPara=document.getElementById('cheqcli-bompara')?.value||'';
  CHEQUES_CLI[cliNome].push({
    num, data: data?data.split('-').reverse().join('/'):'',
    bomPara: bomPara?bomPara.split('-').reverse().join('/'):'',
    valor,
    banco:   document.getElementById('cheqcli-banco')?.value.trim()||'',
    tipo:    document.getElementById('cheqcli-tipo')?.value||'Adiantamento',
    vinculo: document.getElementById('cheqcli-vinculo')?.value.trim()||'',
    obs:     document.getElementById('cheqcli-obs')?.value.trim()||'',
    status: 'Pendente'
  });
  saveChequesCli(); renderChequesCli(); cm();
  showToast('✅ Cheque de '+cliNome+' lançado!','success');
}


function renderChequesCli(){
  const tbody=document.getElementById('tb-cheques-cli-list');
  if(!tbody) return;
  const fmt=v=>_numFinito(v,0).toLocaleString('pt-BR',{minimumFractionDigits:2});
  const all=[];
  Object.entries(CHEQUES_CLI).forEach(([cliNome,lista])=>{
    lista.forEach(c=>all.push({...c,cliNome}));
  });
  all.sort((a,b)=>(a.bomPara||a.data).localeCompare(b.bomPara||b.data));
  if(all.length===0){
    tbody.innerHTML='<tr><td colspan="12" style="color:var(--gray);text-align:center;padding:20px">Nenhum cheque de cliente lançado</td></tr>';
    return;
  }
  const hoje=new Date().toISOString().slice(0,10);
  tbody.innerHTML=all.map(c=>{
    const bomISO=c.bomPara&&c.bomPara.indexOf('/')>=0?c.bomPara.split('/').reverse().join('-'):c.bomPara;
    const devolvido=c.status==='Devolvido';
    const pagoDev=c.status==='Pago (após devolução)';
    const atrasado=c.status==='Pendente'&&bomISO&&bomISO<hoje;
    const stCls=(c.status==='Compensado'||pagoDev)?'b-pago':(devolvido||atrasado)?'b-pend':'b-zerado';
    const stHtml=devolvido
      ? `<span class="b" style="background:#fff3cd;color:#8a6d00;border:1px solid #f1c40f">🟡 Devolvido (não pago)</span>`+(c.motivoDevolucao?`<br><span style="font-size:.68rem;color:#8a6d00" title="${esc(c.motivoDevolucao)}">motivo: ${esc(c.motivoDevolucao)}</span>`:'')
      : pagoDev
        ? `<span class="b b-pago">✅ Pago (devolv.)</span>`+(c.motivoDevolucao?`<br><span style="font-size:.66rem;color:#888" title="${esc(c.motivoDevolucao)}">havia voltado: ${esc(c.motivoDevolucao)}</span>`:'')
        : `<span class="b ${stCls}">${atrasado?'Atrasado':c.status}</span>`;
    return `<tr style="${devolvido?'background:#fff8e1':atrasado?'background:#fff5f5':''}">
      <td>${esc(c.num)}</td><td>${fmtDate(c.data)||'—'}</td><td>${fmtDate(c.bomPara)||'—'}</td>
      <td><b>${esc(c.cliNome)}</b></td>
      <td style="font-size:.82rem">${esc(c.emitente||'—')}</td>
      <td style="font-weight:700;color:#1a5c35">R$ ${fmt(c.valor)}</td>
      <td><span style="font-size:.75rem;padding:2px 7px;border-radius:10px;background:${c.tipo==='Adiantamento'?'#e8f5e9':'#e3f2fd'};color:${c.tipo==='Adiantamento'?'#2e7d32':'#1565c0'}">${c.tipo}</span></td>
      <td style="font-size:.78rem">${esc(c.banco||'—')}</td>
      <td style="font-size:.78rem">${esc(c.vinculo||'—')}</td>
      <td>${stHtml}</td>
      <td style="font-size:.78rem">${esc(c.obs||'—')}</td>
      <td style="white-space:nowrap">
        <button onclick="editarChequeCli('${esc(c.cliNome)}','${esc(c.num)}')" class="btn-edit" style="font-size:.72rem" title="Editar cheque">✏️</button>
        <button onclick="alterarStatusChequeCli('${esc(c.cliNome)}','${esc(c.num)}')" class="btn-edit" style="font-size:.72rem" title="Alterar status">🔄</button>
        <button onclick="excluirChequeCli('${esc(c.cliNome)}','${esc(c.num)}')" class="btn-edit-danger" title="Excluir">🗑️</button>
      </td>
    </tr>`;
  }).join('');
}

function alterarStatusChequeCli(cliNome,num){
  const lista=CHEQUES_CLI[cliNome]||[];
  const c=lista.find(x=>x.num===num);
  if(!c) return;
  const ops=['Pendente','Compensado','Devolvido','Pago (após devolução)'];
  const cur=ops.indexOf(c.status);
  const novo=ops[(cur+1)%ops.length];
  if(novo==='Devolvido'){
    const motivo=prompt('Motivo da devolução do cheque nº '+num+' (ex: sem fundos, sustado, divergência...):', c.motivoDevolucao||'');
    if(motivo===null) return; 
    c.motivoDevolucao=(motivo||'').trim();
  } else if(novo==='Pendente'){
    c.motivoDevolucao=''; 
  }
  c.status=novo;
  saveChequesCli(); renderChequesCli();
  try{renderFluxo();}catch(e){}
}
function excluirChequeCli(cliNome,num){
  if(!confirm('Excluir este cheque?')) return;
  if(CHEQUES_CLI[cliNome]) CHEQUES_CLI[cliNome]=CHEQUES_CLI[cliNome].filter(c=>c.num!==num);
  saveChequesCli(); renderChequesCli();
}


function editarChequeCli(cliNome,num){
  const lista=CHEQUES_CLI[cliNome]||[];
  const c=lista.find(x=>x.num===num);
  if(!c){ try{showToast('Cheque não encontrado.','error');}catch(e){} return; }
  const toISO=d=> d&&String(d).indexOf('/')>=0 ? String(d).split('/').reverse().join('-') : (d||'');
  const old=document.getElementById('modal-edit-cheqcli'); if(old) old.remove();
  const ov=document.createElement('div'); ov.className='modal-ov open'; ov.id='modal-edit-cheqcli';
  const box=document.createElement('div'); box.className='modal'; box.style.maxWidth='560px';
  box.innerHTML=
    '<h3 style="margin-bottom:6px">✏️ Editar Cheque de Cliente</h3>'+
    '<div style="font-size:.8rem;color:#888;margin-bottom:12px">Cliente: <b>'+esc(cliNome)+'</b></div>'+
    '<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px">'+
      '<div class="fg" style="margin:0"><label>Nº Cheque</label><input id="ecc-num" value="'+esc(c.num||'')+'"></div>'+
      '<div class="fg" style="margin:0"><label>Valor R$</label><input id="ecc-valor" type="number" min="0" step="0.01" value="'+Number(c.valor||0)+'"></div>'+
      '<div class="fg" style="margin:0"><label>Data do Cheque</label><input id="ecc-data" type="date" value="'+toISO(c.data)+'"></div>'+
      '<div class="fg" style="margin:0"><label>Bom Para</label><input id="ecc-bompara" type="date" value="'+toISO(c.bomPara)+'"></div>'+
      '<div class="fg" style="margin:0"><label>Banco / Agência</label><input id="ecc-banco" value="'+esc(c.banco||'')+'"></div>'+
      '<div class="fg" style="margin:0"><label>Emitente (nome no cheque)</label><input id="ecc-emitente" value="'+esc(c.emitente||'')+'"></div>'+
      '<div class="fg" style="margin:0"><label>Tipo</label><select id="ecc-tipo"><option'+(c.tipo==='Adiantamento'?' selected':'')+'>Adiantamento</option><option'+(c.tipo==='Pagamento'?' selected':'')+'>Pagamento</option></select></div>'+
      '<div class="fg" style="margin:0"><label>Status</label><select id="ecc-status"><option'+(c.status==='Pendente'?' selected':'')+'>Pendente</option><option'+(c.status==='Compensado'?' selected':'')+'>Compensado</option><option'+(c.status==='Devolvido'?' selected':'')+'>Devolvido</option><option'+(c.status==='Pago (após devolução)'?' selected':'')+'>Pago (após devolução)</option></select></div>'+
      '<div class="fg" style="margin:0;grid-column:1/-1"><label>Vinculado à Venda/NF</label><input id="ecc-vinculo" value="'+esc(c.vinculo||'')+'"></div>'+
      '<div class="fg" style="margin:0;grid-column:1/-1"><label>Motivo da devolução <span style="font-weight:400;color:#888;font-size:.8rem">(só se Devolvido)</span></label><input id="ecc-motivo" value="'+esc(c.motivoDevolucao||'')+'" placeholder="Ex: sem fundos, sustado..."></div>'+
      '<div class="fg" style="margin:0;grid-column:1/-1"><label>Obs.</label><input id="ecc-obs" value="'+esc(c.obs||'')+'"></div>'+
    '</div>'+
    '<div class="modal-ft" style="margin-top:14px">'+
      '<button class="btn-cancel" onclick="document.getElementById(\'modal-edit-cheqcli\').remove()">Cancelar</button>'+
      '<button class="btn-save" onclick="salvarEdicaoChequeCli(\''+esc(cliNome).replace(/'/g,"\\'")+'\',\''+esc(c.num).replace(/'/g,"\\'")+'\')">💾 Salvar</button>'+
    '</div>';
  ov.appendChild(box); document.body.appendChild(ov);
}
function salvarEdicaoChequeCli(cliNome,numOrig){
  const lista=CHEQUES_CLI[cliNome]||[];
  const c=lista.find(x=>x.num===numOrig);
  if(!c){ try{showToast('Cheque não encontrado.','error');}catch(e){} return; }
  const g=id=>document.getElementById(id);
  const toBR=d=> d? String(d).split('-').reverse().join('/') : '';
  const novoNum=(g('ecc-num').value||'').trim();
  const valor=parseFloat(g('ecc-valor').value)||0;
  if(!novoNum||valor<=0){ alert('Informe número e valor do cheque.'); return; }
  c.num=novoNum;
  c.valor=valor;
  c.data=toBR(g('ecc-data').value);
  c.bomPara=toBR(g('ecc-bompara').value);
  c.banco=(g('ecc-banco').value||'').trim();
  c.emitente=(g('ecc-emitente').value||'').trim();
  c.tipo=g('ecc-tipo').value;
  c.status=g('ecc-status').value;
  c.vinculo=(g('ecc-vinculo').value||'').trim();
  c.motivoDevolucao=(g('ecc-motivo').value||'').trim();
  c.obs=(g('ecc-obs').value||'').trim();
  if(c.status!=='Devolvido' && c.status!=='Pago (após devolução)') c.motivoDevolucao=''; 
  saveChequesCli();
  const m=document.getElementById('modal-edit-cheqcli'); if(m) m.remove();
  renderChequesCli(); try{renderFluxo();}catch(e){}
  try{showToast('Cheque atualizado!','success');}catch(e){}
}










function adtCorrigeEmpresa(){
  let mudou=false;
  Object.values(ADT_POR_FORN).forEach(lista=>{
    (lista||[]).forEach(a=>{
      if(a._empresaAuto){ a.empresa=''; delete a._empresaAuto; mudou=true; }
      
      
      
      
      else if((a.bancoNome||'').toLowerCase().includes('terceiro') && a.empresa===_empresaPrincipalChave()){
        a.empresa=''; mudou=true;
      }
    });
  });
  if(mudou) saveDB();
}











function _adtCorrigirDataCompensacaoParcial(){
  let mudou=false;
  Object.values(ADT_POR_FORN).forEach(function(lista){
    (lista||[]).forEach(function(a){
      if(!a || !a.obs) return;
      const m=/Compensação parcial – CP (\d{2}\/\d{2}\/\d{4})/.exec(a.obs);
      if(m && a.data!==m[1]){ a.data=m[1]; mudou=true; }
    });
  });
  if(mudou) saveDB();
  return mudou;
}








function sincronizarAdiantamentosBanco(){
  const usados=new Set(
    Object.values(ADT_POR_FORN).flat().filter(a=>a && a.movBancoId).map(a=>a.movBancoId)
  );
  const pendentes=[]; 
  const paraVincular=[]; 

  Object.entries(ADT_POR_FORN).forEach(([fornCod,lista])=>{
    (lista||[]).forEach(a=>{
      if(!a || a.movBancoId) return;
      if(!a.bancoNome || a.bancoNome==='Não informado') return;
      const banco=BANCOS_DB.find(x=>x.banco===a.bancoNome);
      if(!banco) return; 
      const forn=FORNECEDORES.find(f=>f.cod===fornCod);
      const descEsperada='Adiantamento: '+(forn?forn.nome:fornCod)+(a.ticket?' Ticket '+a.ticket:'');
      const existente=LANC_BANCO_DB.find(l=>
        !usados.has(l.id) && l.bancoCod===banco.cod && l.tipo==='Saida' &&
        Math.abs(Number(l.valor)-Number(a.valor))<0.01 &&
        (l.descricao===descEsperada || l.descricao===('Adiantamento: '+fornCod+(a.ticket?' Ticket '+a.ticket:'')))
      );
      if(existente){ usados.add(existente.id); paraVincular.push({a,movId:existente.id}); }
      else { pendentes.push({a,fornCod,banco,descEsperada}); }
    });
  });

  
  
  
  const orfaos=LANC_BANCO_DB.filter(l=>!usados.has(l.id) && !paraVincular.some(p=>p.movId===l.id) && /^Adiantamento:/.test(l.descricao||''));

  if(pendentes.length===0 && paraVincular.length===0 && orfaos.length===0){
    alert('✅ Tudo certo — todos os adiantamentos com banco definido estão somando certinho no saldo do banco, e não há lançamentos de adiantamento sobrando sem adiantamento correspondente.');
    return;
  }

  const totalPendente=pendentes.reduce((s,p)=>s+Number(p.a.valor||0),0);
  const totalOrfaos=orfaos.reduce((s,l)=>s+Number(l.valor||0),0);
  const fmt=v=>Number(v||0).toLocaleString('pt-BR',{minimumFractionDigits:2});
  let msg='Encontrei:\n\n';
  if(paraVincular.length>0) msg+='• '+paraVincular.length+' adiantamento(s) com lançamento já existente no banco, só faltando vincular (não muda nenhum valor).\n';
  if(pendentes.length>0) msg+='• '+pendentes.length+' adiantamento(s) SEM nenhum lançamento no banco, totalizando R$ '+fmt(totalPendente)+' — vou criar esses lançamentos agora.\n';
  if(orfaos.length>0) msg+='• '+orfaos.length+' lançamento(s) de adiantamento no banco que NÃO correspondem a nenhum adiantamento cadastrado hoje (provavelmente de adiantamentos já excluídos), totalizando R$ '+fmt(totalOrfaos)+' — vou remover esses lançamentos agora.\n';
  msg+='\nUm backup de contas e lançamentos será baixado antes. Continuar?';
  if(!confirm(msg)) return;

  
  try{
    const agora=new Date();
    const backup={geradoEm:agora.toISOString(),bancos:JSON.parse(JSON.stringify(BANCOS_DB)),lancamentos:JSON.parse(JSON.stringify(LANC_BANCO_DB)),adiantamentos:JSON.parse(JSON.stringify(ADT_POR_FORN))};
    const blob=new Blob([JSON.stringify(backup,null,2)],{type:'application/json'});
    const url=URL.createObjectURL(blob);
    const link=document.createElement('a');
    link.href=url; link.download='backup-adiantamentos-bancos-'+agora.toISOString().slice(0,10)+'.json';
    document.body.appendChild(link); link.click(); document.body.removeChild(link);
    setTimeout(()=>URL.revokeObjectURL(url),2000);
  }catch(e){ console.warn('backup falhou:',e); }

  paraVincular.forEach(({a,movId})=>{ a.movBancoId=movId; });
  pendentes.forEach(({a,fornCod,descEsperada})=>{
    const mov=registrarMovBanco(a.bancoNome, a.data?a.data.split('/').reverse().join('-'):'', descEsperada, 'Saida', a.valor);
    if(mov) a.movBancoId=mov.id;
  });
  if(orfaos.length>0){
    const orfaosIds=new Set(orfaos.map(l=>l.id));
    for(let i=LANC_BANCO_DB.length-1;i>=0;i--){ if(orfaosIds.has(LANC_BANCO_DB[i].id)) _syncLancBanco.remover(i); }
    saveBancos(); renderBancos();
  }
  saveDB();
  renderAdiantamentos();
  alert('✅ Pronto! '+paraVincular.length+' vinculado(s), '+pendentes.length+' lançamento(s) novo(s) criado(s) (R$ '+fmt(totalPendente)+') e '+orfaos.length+' lançamento(s) órfão(s) removido(s) (R$ '+fmt(totalOrfaos)+'). Confira o saldo em Contas Bancárias.');
}







function sincronizarPagamentosBanco(){
  if(typeof CONTAS_PAGAR==='undefined'||!Array.isArray(CONTAS_PAGAR)){ alert('Contas a Pagar não carregou ainda. Abra a aba Contas a Pagar e tente de novo.'); return; }
  const fmt=v=>Number(v||0).toLocaleString('pt-BR',{minimumFractionDigits:2});
  
  const usados=new Set();
  CONTAS_PAGAR.forEach(c=>{
    if(c && c.movBancoIdCP) usados.add(c.movBancoIdCP);
    if(c && Array.isArray(c.pagamentos)) c.pagamentos.forEach(p=>{ if(p && p.movBancoId) usados.add(p.movBancoId); });
  });

  const pendentes=[];   
  const paraVincular=[];

  function _acharBanco(nome){
    if(!nome) return null;
    return BANCOS_DB.find(x=>{
      const n=x.banco+(x.tipo==='Conta Terceiro'&&x.titular?' ('+x.titular+')':'');
      return n===nome||x.banco===nome;
    });
  }
  function _tentar(alvo, banco, valor, dataISO, desc){
    if(!banco||!(Number(valor)>0)) return;
    
    
    const existente=LANC_BANCO_DB.find(l=>
      !usados.has(l.id) && l.bancoCod===banco.cod && l.tipo==='Saida' &&
      Math.abs(Number(l.valor)-Number(valor))<0.01 &&
      /^Pagto:/i.test(l.descricao||'')
    );
    if(existente){ usados.add(existente.id); paraVincular.push({alvo, movId:existente.id}); }
    else { pendentes.push({alvo, banco, valor:Number(valor), dataISO, desc}); }
  }

  CONTAS_PAGAR.forEach(c=>{
    if(!c) return;
    const temPagamentos=Array.isArray(c.pagamentos)&&c.pagamentos.length>0;
    if(temPagamentos){
      c.pagamentos.forEach(p=>{
        if(!p||p.movBancoId) return;
        if(!p.banco||!(Number(p.valor)>0)) return;
        const banco=_acharBanco(p.banco);
        if(!banco) return;
        const dataISO=p.data?p.data.split('/').reverse().join('-'):'';
        _tentar({tipo:'pagamento',c,p}, banco, p.valor, dataISO, 'Pagto: '+(c.desc||c.cred||''));
      });
    } else if(c.status==='Pago' && c.bancoNome && !c.movBancoIdCP){
      
      const banco=_acharBanco(c.bancoNome);
      if(!banco) return;
      const valor=Number(c.valorPago||c.valor||0);
      const dataISO=c.dataPgto?c.dataPgto.split('/').reverse().join('-'):'';
      _tentar({tipo:'conta',c}, banco, valor, dataISO, 'Pagto: '+(c.desc||c.cred||''));
    }
  });

  if(pendentes.length===0 && paraVincular.length===0){
    alert('✅ Tudo certo — todos os pagamentos a fornecedor com banco definido já estão puxando do saldo do banco.');
    return;
  }

  const totalPendente=pendentes.reduce((s,p)=>s+Number(p.valor||0),0);
  let msg='Encontrei:\n\n';
  if(paraVincular.length>0) msg+='• '+paraVincular.length+' pagamento(s) com lançamento já existente no banco, só faltando vincular (não muda nenhum valor).\n';
  if(pendentes.length>0) msg+='• '+pendentes.length+' pagamento(s) SEM lançamento no banco, totalizando R$ '+fmt(totalPendente)+' — vou criar essas saídas agora pra puxar do saldo.\n';
  msg+='\nUm backup de contas e lançamentos será baixado antes. Continuar?';
  if(!confirm(msg)) return;

  
  try{
    const agora=new Date();
    const backup={geradoEm:agora.toISOString(),bancos:JSON.parse(JSON.stringify(BANCOS_DB)),lancamentos:JSON.parse(JSON.stringify(LANC_BANCO_DB)),contasPagar:JSON.parse(JSON.stringify(CONTAS_PAGAR))};
    const blob=new Blob([JSON.stringify(backup,null,2)],{type:'application/json'});
    const url=URL.createObjectURL(blob);
    const link=document.createElement('a');
    link.href=url; link.download='backup-pagamentos-bancos-'+agora.toISOString().slice(0,10)+'.json';
    document.body.appendChild(link); link.click(); document.body.removeChild(link);
    setTimeout(()=>URL.revokeObjectURL(url),2000);
  }catch(e){ console.warn('backup falhou:',e); }

  paraVincular.forEach(({alvo,movId})=>{
    if(alvo.tipo==='pagamento'){ alvo.p.movBancoId=movId; if(!alvo.c.movBancoIdCP) alvo.c.movBancoIdCP=movId; }
    else { alvo.c.movBancoIdCP=movId; }
    alvo.c._upd=Date.now();
  });
  pendentes.forEach(({alvo,banco,valor,dataISO,desc})=>{
    const mov=registrarMovBanco(banco.banco+(banco.tipo==='Conta Terceiro'&&banco.titular?' ('+banco.titular+')':''), dataISO, desc, 'Saida', valor);
    if(mov){
      if(alvo.tipo==='pagamento'){ alvo.p.movBancoId=mov.id; if(!alvo.c.movBancoIdCP) alvo.c.movBancoIdCP=mov.id; }
      else { alvo.c.movBancoIdCP=mov.id; }
      alvo.c._upd=Date.now();
    }
  });
  try{ saveContasPagar(); renderContasPagar(); }catch(e){}
  saveBancos(); renderBancos();
  alert('✅ Pronto! '+paraVincular.length+' pagamento(s) vinculado(s) e '+pendentes.length+' saída(s) nova(s) criada(s) (R$ '+fmt(totalPendente)+'). Confira o saldo em Contas Bancárias.');
}




function adtSetEmpresaInline(fornCod, adtCod, novaEmpresa){
  const lista=ADT_POR_FORN[fornCod]||[];
  const a=lista.find(x=>x.cod===adtCod);
  if(!a) return;
  a.empresa=novaEmpresa;
  delete a._empresaAuto; 
  saveDB();
  showToast('Empresa do adiantamento '+adtCod+' definida como '+novaEmpresa+'.','success');
}




function _bancoKey(nome){
  var s=(nome||'').toString().toLowerCase().trim();
  if(!s || s==='não informado' || s==='nao informado' || s.indexOf('sem banco')>=0) return '__none__';
  s=s.normalize('NFD').replace(/[\u0300-\u036f]/g,'');   
  s=s.replace(/[–—\-\/|·.,]/g,' ');                        
  s=s.replace(/\bmetais\b/g,' ');                          
  s=s.replace(/\bsicredi?\b/g,'sicredi');                  
  s=s.replace(/\bitau\b/g,'itau');
  s=s.replace(/\s+/g,' ').trim();
  return s || '__none__';
}
function _bancoDisplay(key){
  if(key==='__none__') return '⚠️ Sem Banco';
  return key.split(' ').map(function(w){
    if(w==='itau') return 'Itaú';
    if(w==='sicredi') return 'Sicredi';
    if(w==='santander') return 'Santander';
    if(_cfgBankDisplayToken(w)) return _cfgBankDisplayToken(w);
    if(w==='acredi') return 'Acredi';
    if(w==='terceiro') return 'Terceiro';
    if(w==='terceiros') return 'Terceiros';
    return w ? w.charAt(0).toUpperCase()+w.slice(1) : w;
  }).join(' ');
}




function _adtIso(d){
  d=String(d||'').trim(); if(!d) return '';
  if(d.indexOf('/')>=0){ var p=d.split(' ')[0].split('/'); if(p.length===3) return p[2]+'-'+String(p[1]).padStart(2,'0')+'-'+String(p[0]).padStart(2,'0'); }
  var m=d.match(/^(\d{4})-(\d{2})-(\d{2})/); return m?m[0]:'';
}

function renderAdiantamentos(){
  const tbody=document.getElementById('tb-adiantamentos-list');
  if(!tbody)return;
  try{ adtCorrigeEmpresa(); }catch(_){}
  try{ _adtCorrigirDataCompensacaoParcial(); }catch(_){}
  const fmt=v=>_numFinito(v,0).toLocaleString('pt-BR',{minimumFractionDigits:2});
  const empCor={}; _cfgFinanceCompanies().forEach(function(n){ empCor[n]=_cfgFinanceCompanyColor(n); });
  const all=[];
  Object.entries(ADT_POR_FORN).forEach(([cod,lista])=>{
    const forn=FORNECEDORES.find(f=>f.cod===cod);
    lista.forEach(a=>all.push({...a,fornNome:forn?forn.nome:cod,fornCod:cod}));
  });
  
  
  
  
  const _pagCargaOcultos=all.filter(_adtEhPagamentoCarga);
  const allVis=all.filter(a=>!_adtEhPagamentoCarga(a));
  return _renderAdiantamentosLista(allVis, _pagCargaOcultos.length);
}



function _adtEhPagamentoCarga(a){
  return !!(a && a.origem==='compra_inline');
}
function _renderAdiantamentosLista(all, _qtdCargaOculta){
  const tbody=document.getElementById('tb-adiantamentos-list');
  if(!tbody)return;
  const fmt=v=>_numFinito(v,0).toLocaleString('pt-BR',{minimumFractionDigits:2});
  const empCor={}; _cfgFinanceCompanies().forEach(function(n){ empCor[n]=_cfgFinanceCompanyColor(n); });
  if(all.length===0){
    tbody.innerHTML=`<tr><td colspan="9" style="color:var(--gray);text-align:center;padding:20px">Nenhum adiantamento lançado ainda</td></tr>`;
    
    const kT=document.getElementById('adt-kpi-total'); if(kT) kT.textContent='R$ 0,00';
    const kP=document.getElementById('adt-kpi-pend');  if(kP) kP.textContent='0';
    const kQ=document.getElementById('adt-kpi-quit');  if(kQ) kQ.textContent='0';
    
    const hEl=document.getElementById('adt-historico-cards'); if(hEl) hEl.innerHTML='<p style="color:var(--gray);text-align:center;padding:20px">Nenhum adiantamento lançado ainda</p>';
    return;
  }
  
  all.sort((a,b)=>{var _f=d=>{d=String(d||'');return d.indexOf('/')>=0?d.split('/').reverse().join('-'):d;};return _f(b.data).localeCompare(_f(a.data));}); 
  
  const buscaForn=(document.getElementById('adt-busca-forn')?.value||'').trim().toLowerCase();
  const allFiltrado=buscaForn?all.filter(a=>(a.fornNome||'').toLowerCase().includes(buscaForn)):all;
  if(buscaForn && allFiltrado.length===0){
    tbody.innerHTML=`<tr><td colspan="9" style="color:var(--gray);text-align:center;padding:20px">Nenhum adiantamento encontrado para "${esc(document.getElementById('adt-busca-forn').value)}"</td></tr>`;
    
  }
  else tbody.innerHTML=allFiltrado.map(a=>`
    <tr style="${a.status==='Quitado'?'background:#eaf7ee':''}">
      <td>${a.cod}</td>
      <td>${fmtDate(a.data)||'—'}</td>
      <td><b>${a.fornNome}</b></td>
      <td style="font-weight:700">R$ ${fmt(a.valor)}</td>
      <td>${a.forma||'—'}</td>
      <td style="font-size:.78rem">${a.bancoNome||'—'}</td>
      <td><input list="dlist-empresas" value="${esc(a.empresa||'')}" placeholder="De quem veio?" onchange="adtSetEmpresaInline('${a.fornCod}','${a.cod}',this.value)" style="width:110px;font-size:.72rem;font-weight:700;color:${empCor[a.empresa]||'#555'};border:1px solid #ddd;border-radius:5px;padding:3px 5px"></td>
      <td>${a.ticket||'—'}</td>
      <td><span class="b ${a.status==='Quitado'?'b-pago':'b-pend'}">${a.status}</span></td>
      <td style="font-size:.78rem;color:#555;max-width:160px">${a.obs?`<span title="${esc(a.obs)}" style="cursor:help">📝 ${esc(a.obs.length>30?a.obs.slice(0,30)+'…':a.obs)}</span>`:'—'}</td>
      <td style="white-space:nowrap">
        <button class="btn-edit" onclick="editAdiantamentoLista('${a.fornCod||a.fornNome}','${a.cod}')" title="Editar" style="margin-right:4px">✏️</button>
        <button class="btn-edit-danger" data-forn="${a.fornNome}" data-cod="${a.cod}" onclick="excluirAdiantamentoLista(this)" title="Excluir">🗑️</button>
      </td>
    </tr>`).join('');
  
  
  
  
  
  
  const pend=all.filter(a=>a.status!=='Quitado');
  const quit=all.filter(a=>a.status==='Quitado');
  const totalAberto=pend.reduce((s,a)=>s+Number(a.valor),0);
  const kTotal=document.getElementById('adt-kpi-total');
  const kPend=document.getElementById('adt-kpi-pend');
  const kQuit=document.getElementById('adt-kpi-quit');
  if(kTotal) kTotal.textContent='R$ '+fmt(totalAberto);
  if(kPend) kPend.textContent=pend.length;
  if(kQuit) kQuit.textContent=quit.length;

  
  const histEl=document.getElementById('adt-historico-cards');
  const histPanel=document.getElementById('adt-panel-historico');
  if(!histEl||!histPanel||histPanel.style.display==='none') return;

  
  const porBanco={};
  all.forEach(a=>{
    const k=_bancoKey(a.bancoNome);
    if(!porBanco[k]) porBanco[k]={label:_bancoDisplay(k),pendentes:[],quitados:[]};
    if(a.status==='Quitado') porBanco[k].quitados.push(a);
    else porBanco[k].pendentes.push(a);
  });

  
  const porForn={};
  all.forEach(a=>{
    const n=a.fornNome||'—';
    if(!porForn[n]) porForn[n]={pendentes:[],quitados:[]};
    if(a.status==='Quitado') porForn[n].quitados.push(a);
    else porForn[n].pendentes.push(a);
  });

  const fmtCard=(label,pendentes,quitados,cor)=>{
    const totPend=pendentes.reduce((s,a)=>s+Number(a.valor||0),0);
    const totQuit=quitados.reduce((s,a)=>s+Number(a.valor||0),0);
    const temPend=pendentes.length>0;
    const bc=temPend?'#c0392b':'#1a5c35';
    const pendRows=pendentes.map(a=>
      `<div style="display:flex;gap:8px;padding:5px 10px;border-bottom:1px solid #fde8e8;background:#fff9f9;align-items:center">
        <span style="font-size:.8rem;color:#555;flex:1">${a.fornNome} · ${fmtDate(a.data)||'—'}</span>
        <span style="font-weight:800;color:#c0392b;font-size:.85rem">R$ ${fmt(a.valor)}</span>
        <span style="font-size:.72rem;color:#888">${a.forma||'—'}</span>
      </div>`).join('');
    const quitRows=quitados.slice(0,5).map(a=>
      `<div style="display:flex;gap:8px;padding:5px 10px;border-bottom:1px solid #e8f5e9;background:#f6fff8;align-items:center">
        <span style="font-size:.78rem;color:#777;flex:1">${a.fornNome} · ${fmtDate(a.data)||'—'}</span>
        <span style="font-weight:700;color:#27ae60;font-size:.82rem">R$ ${fmt(a.valor)}</span>
        <span style="font-size:.7rem;color:#27ae60">${a.ticket||'quitado'}</span>
      </div>`).join('');
    return `<div style="background:#fff;border:2px solid ${bc};border-radius:12px;overflow:hidden;flex:1;min-width:260px;max-width:380px">
      <div style="background:${bc};color:#fff;padding:10px 14px;display:flex;justify-content:space-between;align-items:center">
        <b style="font-size:.9rem">${label}</b>
        <span style="font-size:.78rem;opacity:.9">${pendentes.length} pend · ${quitados.length} quit</span>
      </div>
      ${temPend?`<div style="background:#fff3f3;padding:6px 10px;font-size:.75rem;font-weight:700;color:#c0392b">⏳ Pendente: R$ ${fmt(totPend)}</div>`:''}
      ${pendRows}
      ${quitados.length?`<div style="background:#e8f5e9;padding:5px 10px;font-size:.73rem;color:#27ae60;font-weight:700;cursor:pointer" onclick="this.nextElementSibling.style.display=this.nextElementSibling.style.display==='none'?'block':'none'">✅ Quitados: R$ ${fmt(totQuit)} (${quitados.length}) ▼</div><div style="display:none">${quitRows}${quitados.length>5?'<div style="padding:4px 10px;font-size:.72rem;color:#888">... e mais '+(quitados.length-5)+'</div>':''}</div>`:''}
    </div>`;
  };

  
  const bancosOrdenados=Object.entries(porBanco).sort((a,b)=>b[1].pendentes.length-a[1].pendentes.length);
  
  const fornTodos=Object.entries(porForn).sort((a,b)=>{
    const totA=(a[1].pendentes.concat(a[1].quitados)).reduce((s,x)=>s+Number(x.valor||0),0);
    const totB=(b[1].pendentes.concat(b[1].quitados)).reduce((s,x)=>s+Number(x.valor||0),0);
    return totB-totA;
  });
  const totaisRows=fornTodos.map(([n,v])=>{
    const tPend=v.pendentes.reduce((s,x)=>s+Number(x.valor||0),0);
    const tQuit=v.quitados.reduce((s,x)=>s+Number(x.valor||0),0);
    const tTotal=tPend+tQuit;
    return `<tr>
      <td style="font-weight:700">${esc(n)}</td>
      <td style="text-align:right;color:#c0392b;font-weight:700">${tPend>0?'R$ '+fmt(tPend):'—'}</td>
      <td style="text-align:right;color:#27ae60;font-weight:700">${tQuit>0?'R$ '+fmt(tQuit):'—'}</td>
      <td style="text-align:right;font-weight:800;color:#1a3a2a">R$ ${fmt(tTotal)}</td>
    </tr>`;
  }).join('');
  const grandPend=all.filter(a=>a.status!=='Quitado').reduce((s,a)=>s+Number(a.valor||0),0);
  const grandQuit=all.filter(a=>a.status==='Quitado').reduce((s,a)=>s+Number(a.valor||0),0);
  const totaisHTML=`
    <div style="font-weight:800;font-size:.9rem;color:var(--primary-dark);margin-bottom:10px;border-bottom:2px solid var(--accent);padding-bottom:6px">💰 Total por Fornecedor</div>
    <div style="overflow-x:auto;margin-bottom:24px">
    <table style="width:100%;border-collapse:collapse;font-size:.85rem">
      <thead><tr style="background:#f0f0f0">
        <th style="text-align:left;padding:7px 12px">Fornecedor</th>
        <th style="text-align:right;padding:7px 12px;color:#c0392b">Pendente</th>
        <th style="text-align:right;padding:7px 12px;color:#27ae60">Quitado</th>
        <th style="text-align:right;padding:7px 12px">Total Geral</th>
      </tr></thead>
      <tbody>${totaisRows}</tbody>
      <tfoot><tr style="background:#1a3a2a;color:#fff;font-weight:800">
        <td style="padding:7px 12px">TOTAL</td>
        <td style="text-align:right;padding:7px 12px">R$ ${fmt(grandPend)}</td>
        <td style="text-align:right;padding:7px 12px">R$ ${fmt(grandQuit)}</td>
        <td style="text-align:right;padding:7px 12px">R$ ${fmt(grandPend+grandQuit)}</td>
      </tr></tfoot>
    </table></div>`;

  const fornOrdenados=Object.entries(porForn).filter(([,v])=>v.pendentes.length>0).sort((a,b)=>b[1].pendentes.reduce((s,x)=>s+Number(x.valor),0)-a[1].pendentes.reduce((s,x)=>s+Number(x.valor),0));

  histEl.innerHTML= totaisHTML+
    `<div style="font-weight:800;font-size:.9rem;color:var(--primary-dark);margin-bottom:10px;border-bottom:2px solid var(--accent);padding-bottom:6px">🏦 Por Banco de Saída</div>
    <div style="display:flex;flex-wrap:wrap;gap:14px;margin-bottom:24px">`+
    (bancosOrdenados.length?bancosOrdenados.map(([b,v])=>fmtCard(v.label,v.pendentes,v.quitados)).join(''):'<p style="color:var(--gray)">—</p>')+
    `</div>`;
}




function _adtSincronizaEmpresa(bancoSelId, empresaSelId){
  _sincronizarEmpresaPorBanco(bancoSelId,empresaSelId);
}



var _ADT_CHQ_BANCOS=[];
var _adtChqDefBanco='';
function _adtFormaChange(){
  const forma=document.getElementById('adt-forma')?.value||'';
  const box=document.getElementById('adt-cheque-box');
  const ehCheque=(forma==='Cheque'||forma==='Cheque de Terceiro');
  if(box) box.style.display=ehCheque?'block':'none';
  _ADT_CHQ_BANCOS=_cfgChequeBankNames();
  const bancosConta=_cfgChequeBanks().map(function(x){return String(x.name||'');}).filter(Boolean);
  const terceiro=String((ERP_BUSINESS_CONFIG&&ERP_BUSINESS_CONFIG.thirdPartyChequeBank)||'').trim();
  _adtChqDefBanco = forma==='Cheque de Terceiro'
    ? (terceiro&&_ADT_CHQ_BANCOS.includes(terceiro)?terceiro:(_ADT_CHQ_BANCOS.find(x=>/terceiro/i.test(x))||''))
    : (bancosConta[0]||'');
  if(ehCheque){
    const rows=document.getElementById('adt-chq-rows');
    if(rows && !rows.children.length) _adtChqAddRow(); 
    _adtChqCalc();
  }
}


function _adtChqRowBankOptions(sel){
  _ADT_CHQ_BANCOS=_cfgChequeBankNames();
  return _cfgChequeBankOptionsHtml(sel||'');
}
function _adtDefData(){ return document.getElementById('adt-data')?.value||''; }
function _adtChqAddRow(banco, num, valor, dataISO, vencISO, cli){
  const rows=document.getElementById('adt-chq-rows'); if(!rows) return;
  const b=banco||_adtChqDefBanco;
  const d=(dataISO!=null&&dataISO!=='')?dataISO:_adtDefData();
  const vc=vencISO||'';
  const div=document.createElement('div');
  div.className='adt-chq-row';
  div.style.cssText='border:1px solid #cfe1f3;border-radius:8px;padding:7px 8px;margin-bottom:6px;background:#fff';
  var ip='padding:6px;border:1px solid #b6d3f2;border-radius:6px;font-size:.78rem;box-sizing:border-box;width:100%';
  var lb='font-size:.66rem;color:#5a7a95;font-weight:700;display:block;margin-bottom:2px';
  div.innerHTML=
    '<div style="display:grid;grid-template-columns:1.4fr .7fr .9fr auto;gap:5px;align-items:end">'+
      '<div><span style="'+lb+'">Banco</span><select class="rb" style="'+ip+'">'+_adtChqRowBankOptions(b)+'</select></div>'+
      '<div><span style="'+lb+'">Nº</span><input class="rn" placeholder="250" value="'+(num!=null?num:'')+'" style="'+ip+'"></div>'+
      '<div><span style="'+lb+'">Valor</span><input class="rv" placeholder="4990,00" value="'+(valor!=null?valor:'')+'" oninput="_adtChqCalc()" style="'+ip+'"></div>'+
      '<button type="button" title="Tirar este cheque" onclick="this.closest(\'.adt-chq-row\').remove();_adtChqCalc()" style="background:#e74c3c;color:#fff;border:none;border-radius:6px;padding:7px 9px;font-size:.78rem;cursor:pointer">✕</button>'+
    '</div>'+
    '<div style="display:grid;grid-template-columns:1fr 1fr;gap:5px;margin-top:5px">'+
      '<div><span style="'+lb+'">Data de lançamento</span><input type="date" class="rd" value="'+d+'" style="'+ip+'"></div>'+
      '<div><span style="'+lb+'">Vencimento (bom para)</span><input type="date" class="rvenc" value="'+vc+'" style="'+ip+'"></div>'+
    '</div>'+
    '<div style="margin-top:5px">'+
      '<span style="'+lb+'">👤 De qual cliente <span style="font-weight:400;color:#9ab">(dono do cheque de terceiro)</span></span>'+
      '<input class="rcli" autocomplete="off" placeholder="nome do cliente que te deu o cheque" value="'+esc(cli||'')+'" style="'+ip+'">'+
    '</div>';
  rows.appendChild(div);
  _adtChqCalc();
}



function _adtChqGerarSeq(){
  const banco=document.getElementById('adt-seq-banco')?.value||_adtChqDefBanco;
  const val=_adtParseVal(document.getElementById('adt-seq-val')?.value||'');
  const ini=parseInt(document.getElementById('adt-seq-ini')?.value)||0;
  const qtd=Math.max(1,Math.min(200,parseInt(document.getElementById('adt-seq-qtd')?.value)||1));
  const dataBase=document.getElementById('adt-seq-data')?.value||_adtDefData();
  const vencBase=document.getElementById('adt-seq-venc')?.value||'';
  const intervalo=parseInt(document.getElementById('adt-seq-int')?.value)||0;
  if(ini<1){ showToast('Preencha o nº do 1º cheque na sequência','error'); return; }
  const valStr = val>0 ? val.toLocaleString('pt-BR',{minimumFractionDigits:2}) : '';
  for(let i=0;i<qtd;i++){
    let venc=vencBase;
    if(vencBase && intervalo>0){ const dt=new Date(vencBase+'T00:00:00'); dt.setDate(dt.getDate()+i*intervalo); venc=dt.toISOString().slice(0,10); }
    _adtChqAddRow(banco, String(ini+i), valStr, dataBase, venc);
  }
  showToast('Adicionei '+qtd+' cheque(s) '+banco+' à lista','success');
}


function _adtChqAplicarDatas(){
  const lanc=document.getElementById('adt-datas-lanc')?.value||'';
  const venc=document.getElementById('adt-datas-venc')?.value||'';
  if(!lanc && !venc){ showToast('Escolha a data de lançamento e/ou o vencimento pra aplicar','info',5000); return; }
  const rows=document.querySelectorAll('#adt-chq-rows .adt-chq-row');
  if(!rows.length){ showToast('Adicione os cheques primeiro, depois aplique as datas','info',5000); return; }
  rows.forEach(function(r){
    if(lanc){ const el=r.querySelector('.rd'); if(el) el.value=lanc; }
    if(venc){ const el=r.querySelector('.rvenc'); if(el) el.value=venc; }
  });
  showToast('Datas aplicadas em '+rows.length+' cheque(s)','success');
}

function _adtChqLer(){
  const out=[];
  document.querySelectorAll('#adt-chq-rows .adt-chq-row').forEach(function(r){
    const b=r.querySelector('.rb')?.value||'';
    const n=(r.querySelector('.rn')?.value||'').trim();
    const v=_adtParseVal(r.querySelector('.rv')?.value||'');
    const d=r.querySelector('.rd')?.value||'';
    const venc=r.querySelector('.rvenc')?.value||'';
    const cli=(r.querySelector('.rcli')?.value||'').trim();
    if(n||v) out.push({b:b,n:n,v:v,d:d,venc:venc,cli:cli});
  });
  return out;
}
function _adtChqCalc(){
  const lista=_adtChqLer();
  const total=lista.reduce(function(s,c){ return s+(c.v||0); },0);
  const vEl=document.getElementById('adt-valor'); if(vEl && total>0) vEl.value=total.toFixed(2);
  const el=document.getElementById('adt-chq-prev'); if(!el) return;
  if(!lista.length){ el.textContent='Nenhum cheque na lista ainda.'; return; }
  el.textContent='📋 '+lista.length+' cheque(s) na lista · Total do adiantamento: R$ '+total.toLocaleString('pt-BR',{minimumFractionDigits:2});
}
function _adtParseVal(s){
  s=String(s||'').trim().replace(/[^0-9.,]/g,'');
  if(s.indexOf(',')>=0){ s=s.replace(/\./g,'').replace(',','.'); }
  var n=parseFloat(s); return isFinite(n)?n:0;
}
function _populateBancosSelects(){
  const bancos=Array.isArray(BANCOS_DB)?BANCOS_DB.filter(function(b){return b&&String(b.banco||'').trim();}):[];
  const opts='<option value="">— Selecione o banco —</option>'+bancos.map(function(b){
    const label=String(b.banco||'')+(b.empresa?' — '+b.empresa:'')+(b.tipo==='Conta Terceiro'&&b.titular?' 👤 '+b.titular:'');
    return '<option value="'+esc(String(b.cod||b.id||b.banco||''))+'">'+esc(label)+'</option>';
  }).join('')+(bancos.length?'':'<option value="" disabled>Nenhuma conta cadastrada em Bancos</option>');
  ['adt-banco','cheq-banco','cp-banco','ct-banco','adtcli-banco','rcr-banco','ecr-banco'].forEach(function(id){
    const el=document.getElementById(id); if(!el) return;
    const cur=el.value||'';
    el.innerHTML=opts;
    if(cur&&[...el.options].some(function(o){return o.value===cur;})) el.value=cur;
  });
}


let _camDest='';
function abrirCamera(destInputId){
  _camDest=destInputId;
  let cam=document.getElementById('_cam-input-global');
  if(!cam){
    cam=document.createElement('input');
    cam.type='file'; cam.id='_cam-input-global'; cam.accept='image/*';
    cam.setAttribute('capture','environment');
    cam.style.display='none';
    cam.onchange=function(){
      try{
        const f=cam.files && cam.files[0];
        if(f){
          const dest=document.getElementById(_camDest);
          if(dest){
            try{ const dt=new DataTransfer(); dt.items.add(f); dest.files=dt.files; }catch(e){}
            dest.dispatchEvent(new Event('change',{bubbles:true}));
            const st=document.getElementById(_camDest.replace('-file','-status').replace('-arquivo','-status'));
            if(st) st.textContent='📷 Foto capturada: '+(f.name||'foto.jpg')+' — agora clique em salvar/adicionar.';
          }
        }
      }catch(e){ alert('Não consegui usar a foto: '+((e&&e.message)||e)); }
      cam.value='';
    };
    document.body.appendChild(cam);
  }
  cam.value='';
  cam.click();
}
function _btnFoto(destInputId){
  return '<button type="button" onclick="abrirCamera(\''+destInputId+'\')" style="margin-top:6px;background:#1565c0;color:#fff;border:none;border-radius:7px;padding:8px 14px;font-size:.85rem;font-weight:700;cursor:pointer;display:inline-flex;align-items:center;gap:6px">📷 Tirar Foto</button>';
}


function adtSubTab(t){
  ['controle','historico'].forEach(function(n){
    const panel=document.getElementById('adt-panel-'+n);
    const btn=document.getElementById('adt-btn-'+n);
    if(panel) panel.style.display = n===t ? '' : 'none';
    if(btn){
      btn.style.fontWeight = n===t ? '700' : '400';
      btn.style.color = n===t ? '#1a3a2a' : '#999';
      btn.style.borderBottomColor = n===t ? '#1a3a2a' : 'transparent';
    }
  });
  if(t==='historico'){
    
    try{ renderAdiantamentos(); }catch(e){}
  }
}


function excluirCheque(cheqId){
  if(!confirm('Excluir este cheque?')) return;
  let found=false;
  Object.keys(CHEQUES_POR_FORN).forEach(cod=>{
    const idx=CHEQUES_POR_FORN[cod].findIndex(x=>(x.id||('CHQ_'+x.num+'_'+cod))===cheqId);
    if(idx!==-1){
      const _removido=CHEQUES_POR_FORN[cod][idx];
      CHEQUES_POR_FORN[cod].splice(idx,1);
      
      _DEL_SETS.chequeItens.add(cod+'::'+(_removido.id||('CHQ_'+_removido.num+'_'+cod)));
      try{ localStorage.setItem(_DEL_LS_KEY.chequeItens, JSON.stringify([..._DEL_SETS.chequeItens])); }catch(e){}
      found=true;
      const _forn=FORNECEDORES.find(f=>f.cod===cod);
      registrarHistorico('Cheque','Excluído',
        (_forn?_forn.nome:cod)+' — cheque nº '+(_removido.num||'')+' — R$ '+Number(_removido.valor||0).toLocaleString('pt-BR',{minimumFractionDigits:2}),
        _removido, {fornCod:cod});
    }
  });
  if(found){ saveDB(); renderCheques(); showToast('Cheque excluído.','success'); }
}

function compensarCheque(cheqId, dataVal){
  let found=false;
  Object.values(CHEQUES_POR_FORN).forEach(lista=>{
    const c=lista.find(x=>x.id===cheqId);
    if(c){
      c.dataCompensacao=dataVal;
      if(dataVal) c.status='Compensado';
      else c.status='Pendente';
      found=true;
    }
  });
  if(found){ saveDB(); renderCheques(); }
}



function abrirBaixaCheque(cheqId){
  let cheq=null;
  Object.values(CHEQUES_POR_FORN).forEach(lista=>{
    const c=lista.find(x=>(x.id||('CHQ_'+x.num))===cheqId||x.id===cheqId);
    if(c) cheq=c;
  });
  if(!cheq){ showToast('Cheque não encontrado','error'); return; }
  document.getElementById('baixa-cheq-id').value=cheqId;
  document.getElementById('baixa-cheq-info').innerHTML=
    `<b>Nº ${cheq.num}</b> — <b>R$ ${Number(cheq.valor).toLocaleString('pt-BR',{minimumFractionDigits:2})}</b><br>`+
    `Bom Para: ${cheq.bomPara||'—'} · Banco: ${cheq.banco||'—'}<br>`+
    `Fornecedor: ${(Object.entries(CHEQUES_POR_FORN).find(([k,l])=>l.includes(cheq))||[])[0]||'—'}`;
  
  document.getElementById('baixa-cheq-data').value=new Date().toISOString().slice(0,10);
  document.getElementById('modal-baixa-cheque').style.display='flex';
}

function confirmarBaixaCheque(){
  const cheqId=document.getElementById('baixa-cheq-id').value;
  const dataISO=document.getElementById('baixa-cheq-data').value;
  if(!dataISO){ showToast('Informe a data do desconto','error'); return; }
  const dataFmt=dataISO.split('-').reverse().join('/');
  compensarCheque(cheqId, dataFmt);
  document.getElementById('modal-baixa-cheque').style.display='none';
  showToast('✅ Baixa registrada! Cheque compensado em '+dataFmt,'success',4000);
}

function estornarBaixaCheque(cheqId){
  if(!confirm('Estornar a baixa deste cheque? Ele voltará para Pendente.')) return;
  compensarCheque(cheqId,'');
  showToast('↩ Baixa estornada. Cheque volta para Pendente.','info',4000);
}

function _popularSelectRuntime(selectId, values, selected){
  const sel=document.getElementById(selectId); if(!sel) return null;
  const atual=selected==null?'':String(selected);
  const unique=[];
  (values||[]).forEach(function(v){ v=String(v||'').trim(); if(v && unique.indexOf(v)<0) unique.push(v); });
  if(atual && unique.indexOf(atual)<0) unique.push(atual); 
  sel.innerHTML='<option value="">— Selecione —</option>'+unique.map(function(v){return '<option>'+esc(v)+'</option>';}).join('');
  sel.value=atual;
  return sel;
}

function editarCheque(cheqId){
  let cheq=null, fornCodFound='';
  Object.entries(CHEQUES_POR_FORN).forEach(([cod,lista])=>{
    const c=lista.find(x=>(x.id||('CHQ_'+x.num+'_'+cod))===cheqId);
    if(c){ cheq=c; fornCodFound=cod; }
  });
  if(!cheq){ showToast('Cheque não encontrado','error'); return; }
  document.getElementById('ec-id').value=cheqId;
  document.getElementById('ec-forn-cod').value=fornCodFound;
  document.getElementById('ec-num').value=cheq.num||'';
  document.getElementById('ec-valor').value=cheq.valor||0;
  const bp=cheq.bomPara||'';
  document.getElementById('ec-bomPara').value=bp.includes('/')?bp.split('/').reverse().join('-'):bp;
  _popularSelectRuntime('ec-banco',_cfgChequeBankNames(),cheq.banco||'');
  document.getElementById('ec-tipo').value=cheq.tipo||'Emitido (A Pagar)';
  document.getElementById('ec-finalidade').value=cheq.finalidade||'Adiantamento';
  _popularSelectRuntime('ec-empresa',EMPRESAS,cheq.empresa||'');
  document.getElementById('ec-vinculo').value=cheq.vinculo||'';
  const modal=document.getElementById('modal-editar-cheque');
  modal.style.display='flex';
}

function salvarEdicaoCheque(){
  const cheqId=document.getElementById('ec-id').value;
  const fornCod=document.getElementById('ec-forn-cod').value;
  const lista=CHEQUES_POR_FORN[fornCod];
  if(!lista){ showToast('Fornecedor não encontrado','error'); return; }
  const cheq=lista.find(x=>(x.id||('CHQ_'+x.num+'_'+fornCod))===cheqId);
  if(!cheq){ showToast('Cheque não encontrado','error'); return; }
  const num=document.getElementById('ec-num').value.trim();
  const valor=parseFloat(document.getElementById('ec-valor').value)||0;
  const bomParaISO=document.getElementById('ec-bomPara').value;
  const bomPara=bomParaISO?bomParaISO.split('-').reverse().join('/'):'';
  const banco=document.getElementById('ec-banco').value;
  const tipo=document.getElementById('ec-tipo').value;
  const finalidade=document.getElementById('ec-finalidade').value;
  const empresa=document.getElementById('ec-empresa').value;
  const vinculo=document.getElementById('ec-vinculo').value.trim();
  if(!num||valor<=0||!bomPara){ showToast('Preencha número, valor e Bom Para','error'); return; }
  cheq.num=num; cheq.valor=valor; cheq.bomPara=bomPara;
  cheq.banco=banco; cheq.tipo=tipo; cheq.finalidade=finalidade;
  cheq.empresa=empresa; cheq.vinculo=vinculo;
  saveDB();
  renderCheques();
  document.getElementById('modal-editar-cheque').style.display='none';
  showToast('✅ Cheque atualizado!','success');
}


function cheqTab(t){
  ['lista','desconto','historico'].forEach(id=>{
    const p=document.getElementById('cheqtab-'+id); if(p) p.style.display=id===t?'':'none';
    const b=document.getElementById('cheqtab-btn-'+id);
    if(b){
      b.style.fontWeight=id===t?'700':'400';
      b.style.color=id===t?'#1a3a2a':'#999';
      b.style.borderBottomColor=id===t?'#1a3a2a':'transparent';
    }
  });
  if(t==='historico') renderCheqHistorico();
  if(t==='desconto') renderDescontoForn();
}

function renderCheqHistorico(){
  const el=document.getElementById('cheq-hist-body'); if(!el) return;
  const fmt=v=>Number(v||0).toLocaleString('pt-BR',{minimumFractionDigits:2});
  const all=[];
  Object.entries(CHEQUES_POR_FORN).forEach(([cod,lista])=>{
    const forn=FORNECEDORES.find(f=>f.cod===cod);
    lista.forEach(c=>all.push({...c,fornCod:cod,fornNome:forn?forn.nome:cod}));
  });
  if(!all.length){
    el.innerHTML='<p style="color:#aaa;text-align:center;padding:40px">Nenhum cheque lançado.</p>';
    return;
  }
  
  const porBanco={};
  all.forEach(c=>{
    const banco=(c.banco||'Sem Banco').trim();
    if(!porBanco[banco]) porBanco[banco]={pendentes:[],compensados:[]};
    if(c.status==='Compensado') porBanco[banco].compensados.push(c);
    else porBanco[banco].pendentes.push(c);
  });
  
  const bancos=Object.entries(porBanco).sort((a,b)=>b[1].pendentes.length-a[1].pendentes.length);

  el.innerHTML=bancos.map(([banco,{pendentes,compensados}])=>{
    const totPend=pendentes.reduce((s,c)=>s+Number(c.valor||0),0);
    const totComp=compensados.reduce((s,c)=>s+Number(c.valor||0),0);
    const allCheqs=[...pendentes,...compensados].sort((a,b)=>(a.bomPara||'').localeCompare(b.bomPara||''));

    const rows=allCheqs.map(c=>{
      const comp=c.status==='Compensado';
      return `<tr style="border-bottom:1px solid #eee;background:${comp?'#f0fff4':'#fff'}">
        <td style="padding:6px 10px;font-weight:700;color:#1565c0">${c.num||'—'}</td>
        <td style="padding:6px 10px">${c.fornNome}</td>
        <td style="padding:6px 10px">${c.empresa||'—'}</td>
        <td style="padding:6px 10px;font-weight:700">R$ ${fmt(c.valor)}</td>
        <td style="padding:6px 10px">${fmtDate(c.bomPara)||'—'}</td>
        <td style="padding:6px 10px">${c.finalidade?`<span style="font-size:.7rem;font-weight:700;padding:2px 5px;border-radius:3px;background:${c.finalidade==='Adiantamento'?'#1a3a2a':'#1565c0'};color:#fff">${c.finalidade==='Adiantamento'?'ADT':'PGTO'}</span>`:'—'}</td>
        <td style="padding:6px 10px">
          ${comp
            ?`<span style="color:#27ae60;font-weight:700">✅ ${c.dataCompensacao||'—'}</span>`
            :`<span style="color:#e65100;font-weight:700">⏳ Pendente</span>`}
        </td>
      </tr>`;
    }).join('');

    return `<div style="background:#fff;border:2px solid ${pendentes.length?'#c0392b':'#27ae60'};border-radius:12px;margin-bottom:16px;overflow:hidden">
      <div style="background:${pendentes.length?'#c0392b':'#1a5c35'};color:#fff;padding:12px 16px;display:flex;align-items:center;gap:16px;flex-wrap:wrap">
        <span style="font-size:1rem;font-weight:800">🏦 ${esc(banco)}</span>
        <span style="background:rgba(255,255,255,.2);border-radius:6px;padding:4px 12px;font-size:.82rem">
          ⏳ À compensar: <b>R$ ${fmt(totPend)}</b> · ${pendentes.length} cheque${pendentes.length!==1?'s':''}
        </span>
        <span style="background:rgba(255,255,255,.15);border-radius:6px;padding:4px 12px;font-size:.82rem">
          ✅ Compensados: <b>R$ ${fmt(totComp)}</b> · ${compensados.length} cheque${compensados.length!==1?'s':''}
        </span>
        <span style="margin-left:auto;font-size:.82rem;opacity:.85">Total: R$ ${fmt(totPend+totComp)}</span>
      </div>
      <div style="overflow-x:auto">
        <table style="width:100%;border-collapse:collapse;font-size:.82rem">
          <thead><tr style="background:#f5f5f5">
            <th style="padding:6px 10px;text-align:left">Nº</th>
            <th style="padding:6px 10px;text-align:left">Fornecedor</th>
            <th style="padding:6px 10px;text-align:left">Empresa</th>
            <th style="padding:6px 10px;text-align:right">Valor</th>
            <th style="padding:6px 10px;text-align:left">Bom Para</th>
            <th style="padding:6px 10px;text-align:left">Finalidade</th>
            <th style="padding:6px 10px;text-align:left">Status</th>
          </tr></thead>
          <tbody>${rows}</tbody>
          <tfoot><tr style="background:#f5f5f5;font-weight:800">
            <td colspan="3" style="padding:7px 10px">TOTAL</td>
            <td style="padding:7px 10px;text-align:right">R$ ${fmt(totPend+totComp)}</td>
            <td colspan="3" style="padding:7px 10px;color:#888;font-size:.8rem">${allCheqs.length} cheque${allCheqs.length!==1?'s':''} · ${compensados.length} compensado${compensados.length!==1?'s':''} · ${pendentes.length} pendente${pendentes.length!==1?'s':''}</td>
          </tfoot>
        </table>
      </div>
    </div>`;
  }).join('');
}




function _cheqDescPend(c){
  return c && c.status!=='Cancelado' && (c.statusDesc ? c.statusDesc==='A descontar' : c.finalidade==='Adiantamento');
}
function _findCheqById(cheqId){
  let found=null;
  Object.keys(CHEQUES_POR_FORN).forEach(cod=>{
    const c=(CHEQUES_POR_FORN[cod]||[]).find(x=>(x.id||('CHQ_'+x.num+'_'+cod))===cheqId||x.id===cheqId);
    if(c) found=c;
  });
  return found;
}
function marcarDescontado(cheqId){ const c=_findCheqById(cheqId); if(!c)return; c.statusDesc='Descontado'; saveDB(); try{renderDescontoForn();}catch(e){} try{renderCheques();}catch(e){} try{showToast('Cheque descontado do fornecedor.','success');}catch(e){} }
function desfazerDesconto(cheqId){ const c=_findCheqById(cheqId); if(!c)return; c.statusDesc='A descontar'; saveDB(); try{renderDescontoForn();}catch(e){} try{renderCheques();}catch(e){} try{showToast('Desconto desfeito.','info');}catch(e){} }
function marcarDescontadoFornecedor(fornCod){
  const lista=CHEQUES_POR_FORN[fornCod]||[];
  const alvo=lista.filter(c=>_cheqDescPend(c));
  if(alvo.length===0) return;
  const total=alvo.reduce((s,c)=>s+Number(c.valor||0),0);
  const fmt=v=>Number(v||0).toLocaleString('pt-BR',{minimumFractionDigits:2});
  if(!confirm('Descontar TODOS os '+alvo.length+' cheque(s) deste fornecedor (R$ '+fmt(total)+') na carga?')) return;
  alvo.forEach(c=>c.statusDesc='Descontado');
  saveDB(); try{renderDescontoForn();}catch(e){} try{renderCheques();}catch(e){}
  try{showToast(alvo.length+' cheque(s) descontados (R$ '+fmt(total)+').','success');}catch(e){}
}
function cancelarCheque(cheqId){
  if(!confirm('Cancelar este cheque? Ele sai dos totais do banco (não conta como a compensar nem compensado).')) return;
  const c=_findCheqById(cheqId); if(!c)return;
  c.status='Cancelado'; c.dataCompensacao='';
  saveDB(); try{renderCheques();}catch(e){} try{renderDescontoForn();}catch(e){}
  try{showToast('Cheque cancelado.','info');}catch(e){}
}
function reativarCheque(cheqId){
  const c=_findCheqById(cheqId); if(!c)return;
  c.status='Pendente';
  saveDB(); try{renderCheques();}catch(e){} try{renderDescontoForn();}catch(e){}
  try{showToast('Cheque reativado (a compensar).','success');}catch(e){}
}
function renderDescontoForn(){
  const box=document.getElementById('desconto-forn-body'); if(!box) return;
  const fmt=v=>Number(v||0).toLocaleString('pt-BR',{minimumFractionDigits:2});
  const grupos=[]; let totalGeral=0;
  Object.keys(CHEQUES_POR_FORN).forEach(cod=>{
    const lista=CHEQUES_POR_FORN[cod]||[];
    const forn=(typeof FORNECEDORES!=='undefined')?FORNECEDORES.find(f=>f.cod===cod):null;
    const nome=forn?forn.nome:cod;
    const aDescontar=lista.filter(c=>_cheqDescPend(c));
    const descontados=lista.filter(c=>c.status!=='Cancelado' && !_cheqDescPend(c) && (c.finalidade==='Adiantamento'||c.statusDesc==='Descontado'));
    if(aDescontar.length===0 && descontados.length===0) return;
    const saldo=aDescontar.reduce((s,c)=>s+Number(c.valor||0),0);
    totalGeral+=saldo;
    grupos.push({cod,nome,aDescontar,descontados,saldo});
  });
  grupos.sort((a,b)=>b.saldo-a.saldo);
  let html='<div class="kpi-grid" style="margin-bottom:14px">'
    +'<div class="kpi o"><div class="kpi-lbl">Total a Descontar</div><div class="kpi-val" style="color:#8a6d00">R$ '+fmt(totalGeral)+'</div><div class="kpi-sub">Cheques entregues, ainda não abatidos na carga</div></div>'
    +'<div class="kpi g"><div class="kpi-lbl">Fornecedores com saldo</div><div class="kpi-val">'+grupos.filter(g=>g.saldo>0).length+'</div><div class="kpi-sub">A descontar</div></div>'
    +'</div>';
  if(grupos.length===0){ box.innerHTML=html+'<p style="color:#aaa;text-align:center;padding:20px">Nenhum cheque de adiantamento a descontar.</p>'; return; }
  html+=grupos.map(g=>`
    <div class="tcard" style="margin-bottom:12px">
      <div class="tcard-hdr" style="align-items:center;flex-wrap:wrap;gap:8px">
        <div class="tcard-title">${esc(g.nome)}</div>
        <div style="display:flex;align-items:center;gap:10px;margin-left:auto">
          <span style="font-weight:800;color:${g.saldo>0?'#8a6d00':'#1a5c35'}">Saldo a descontar: R$ ${fmt(g.saldo)}</span>
          ${g.saldo>0?`<button onclick="marcarDescontadoFornecedor('${g.cod}')" style="background:#1a5c35;color:#fff;border:none;border-radius:6px;padding:5px 12px;cursor:pointer;font-size:.8rem;font-weight:700">✅ Descontar tudo (carga)</button>`:''}
        </div>
      </div>
      <table><thead><tr><th>Nº</th><th>Valor</th><th>Bom Para</th><th>Situação no banco</th><th>Desconto</th><th>Ação</th></tr></thead><tbody>
      ${[...g.aDescontar, ...g.descontados].map(c=>{
        const cid=c.id||('CHQ_'+c.num+'_'+g.cod);
        const pend=_cheqDescPend(c);
        const bankTxt=c.status==='Cancelado'?'🚫 Cancelado':c.status==='Compensado'?'✅ Compensado':'⏳ A compensar';
        return `<tr style="${pend?'':'background:#f0fff4'}">
          <td>${esc(c.num)}</td>
          <td style="font-weight:700">R$ ${fmt(c.valor)}</td>
          <td>${fmtDate(c.bomPara)||'—'}</td>
          <td style="font-size:.78rem;color:#666">${bankTxt}</td>
          <td>${pend?'<span class="b" style="background:#fff3cd;color:#8a6d00">📉 A descontar</span>':'<span class="b b-pago">✅ Descontado</span>'}</td>
          <td>${pend
            ?`<button onclick="marcarDescontado('${cid}')" style="background:#27ae60;color:#fff;border:none;border-radius:5px;padding:3px 10px;cursor:pointer;font-size:.78rem;font-weight:700">✅ Descontar</button>`
            :`<button onclick="desfazerDesconto('${cid}')" style="background:#f39c12;color:#fff;border:none;border-radius:5px;padding:3px 10px;cursor:pointer;font-size:.75rem;font-weight:700">↩ Desfazer</button>`}</td>
        </tr>`;
      }).join('')}
      </tbody></table>
    </div>`).join('');
  box.innerHTML=html;
}


function renderCheques(){
  const tbody=document.getElementById('tb-cheques-list');
  if(!tbody)return;
  const fmt=v=>_numFinito(v,0).toLocaleString('pt-BR',{minimumFractionDigits:2});
  const isSecretaria=cu&&(cuKey==='thais'||cu.role?.includes('Secretária'));
  const banner=document.getElementById('cheq-secretaria-banner');
  if(banner) banner.style.display=isSecretaria?'block':'none';
  
  document.querySelectorAll('#tab-cheques .kpi-grid').forEach(el=>el.style.display=isSecretaria?'none':'');
  const histBtn=document.getElementById('cheqtab-btn-historico');
  if(histBtn) histBtn.style.display=isSecretaria?'none':'';
  if(isSecretaria){
    const histPanel=document.getElementById('cheqtab-historico');
    if(histPanel) histPanel.style.display='none';
  }
  const all=[];
  Object.entries(CHEQUES_POR_FORN).forEach(([cod,lista])=>{
    const forn=FORNECEDORES.find(f=>f.cod===cod);
    lista.forEach(c=>all.push({...c,fornCod:cod,fornNome:forn?forn.nome:cod}));
  });
  if(all.length===0){
    tbody.innerHTML=`<tr><td colspan="9" style="color:var(--gray);text-align:center;padding:20px">Nenhum cheque lançado ainda</td></tr>`;
    return;
  }
  all.sort((a,b)=>b.bomPara.localeCompare(a.bomPara));

  
  const buscaNum=(document.getElementById('cheq-busca-num')?.value||'').trim().toLowerCase();
  const buscaDe=document.getElementById('cheq-busca-de')?.value||'';
  const buscaAte=document.getElementById('cheq-busca-ate')?.value||'';
  const parseBomPara=bp=>{
    if(!bp) return '';
    if(bp.includes('-')) return bp;
    const p=bp.split('/'); return p.length===3?`${p[2]}-${p[1]}-${p[0]}`:'';
  };
  const temFiltro=buscaNum||buscaDe||buscaAte;
  const allFiltrado=all.filter(c=>{
    if(buscaNum && !(c.num||'').toLowerCase().includes(buscaNum) && !(c.fornNome||'').toLowerCase().includes(buscaNum)) return false;
    if(buscaDe||buscaAte){
      const bp=parseBomPara(c.bomPara);
      if(buscaDe && bp < buscaDe) return false;
      if(buscaAte && bp > buscaAte) return false;
    }
    return true;
  });
  if(temFiltro && allFiltrado.length===0){
    tbody.innerHTML=`<tr><td colspan="9" style="color:var(--gray);text-align:center;padding:20px">Nenhum cheque encontrado para a busca</td></tr>`;
    return;
  }

  
  const totalEmitido=all.filter(c=>c.tipo&&c.tipo.includes('Emitido')&&c.status==='Pendente').reduce((s,c)=>s+Number(c.valor),0);
  const totalReceber=all.filter(c=>c.tipo&&c.tipo.includes('Recebido')&&c.status==='Pendente').reduce((s,c)=>s+Number(c.valor),0);
  const totalACompensar=all.filter(c=>c.status==='Pendente').reduce((s,c)=>s+Number(c.valor),0);
  const totalCompensado=all.filter(c=>c.status==='Compensado').reduce((s,c)=>s+Number(c.valor),0);
  const kpis=document.querySelectorAll('#tab-cheques .kpi-val');
  if(kpis[0]) kpis[0].textContent='R$ '+fmt(totalEmitido);
  if(kpis[1]) kpis[1].textContent='R$ '+fmt(totalReceber);
  if(kpis[2]) kpis[2].textContent='R$ '+fmt(totalACompensar);
  if(kpis[3]) kpis[3].textContent='R$ '+fmt(totalCompensado);

  
  const filtDe=document.getElementById('cheq-filt-de')?.value||'';
  const filtAte=document.getElementById('cheq-filt-ate')?.value||'';
  const dataCompISO=dc=>{
    if(!dc) return '';
    if(dc.includes('-')) return dc;
    const p=dc.split('/'); return p.length===3?p[2]+'-'+p[1]+'-'+p[0]:'';
  };
  const compDentroFiltro=c=>{
    if(!filtDe && !filtAte) return true;
    const dc=dataCompISO(c.dataCompensacao);
    if(!dc) return false; 
    if(filtDe && dc<filtDe) return false;
    if(filtAte && dc>filtAte) return false;
    return true;
  };

  
  
  const BANCOS_CHEQ_LISTA=(function(){
    const cfg=_cfgChequeBanks().map(function(x){return {nome:x.name,cor:x.color||'#2c7b7b',bg:'#f5f7f7'};});
    const seen=new Set(cfg.map(x=>x.nome));
    (typeof BANCOS_DB!=='undefined'?BANCOS_DB:[]).forEach(function(b){ const n=String((b&&b.banco)||'').trim(); if(n&&!seen.has(n)){seen.add(n);cfg.push({nome:n,cor:'#2c7b7b',bg:'#e0f7fa'});} });
    return cfg;
  })();
  const totPorBanco={};
  BANCOS_CHEQ_LISTA.forEach(b=>{ totPorBanco[b.nome]={comp:0,pend:0,qtdPend:0}; });
  
  const semBanco={comp:0,pend:0,qtdPend:0};
  all.forEach(c=>{
    const banco=(c.banco||'').trim();
    const bucket=banco?(totPorBanco[banco]!==undefined?totPorBanco[banco]:(()=>{
      totPorBanco[banco]={comp:0,pend:0,qtdPend:0};
      BANCOS_CHEQ_LISTA.push({nome:banco,cor:'#2c7b7b',bg:'#e0f7fa'});
      return totPorBanco[banco];
    })()):semBanco;
    if(c.status==='Compensado'){
      if(compDentroFiltro(c)) bucket.comp+=Number(c.valor);
    } else {
      bucket.pend+=Number(c.valor);
      bucket.qtdPend++;
    }
  });
  
  const grandComp=Object.values(totPorBanco).reduce((s,v)=>s+v.comp,0)+semBanco.comp;
  const grandPend=Object.values(totPorBanco).reduce((s,v)=>s+v.pend,0)+semBanco.pend;
  const grandQtdPend=Object.values(totPorBanco).reduce((s,v)=>s+v.qtdPend,0)+semBanco.qtdPend;

  
  const gc=document.getElementById('cheq-grand-comp');
  const gp=document.getElementById('cheq-grand-pend');
  const gt=document.getElementById('cheq-grand-total');
  if(gc) gc.textContent='R$ '+fmt(grandComp);
  if(gp) gp.textContent='R$ '+fmt(grandPend);
  if(gt) gt.textContent='R$ '+fmt(grandComp+grandPend);
  const gps=document.getElementById('cheq-grand-pend-sub');
  if(gps) gps.textContent=grandQtdPend+' cheque'+(grandQtdPend!==1?'s':'')+' pendente'+(grandQtdPend!==1?'s':'');

  
  const cardsEl=document.getElementById('cheq-banco-cards');
  if(cardsEl){
    
    const porBancoCards={};
    all.forEach(c=>{
      const banco=(c.banco||'⚠️ Sem Banco').trim();
      if(!porBancoCards[banco]) porBancoCards[banco]={pendentes:[],compensados:[]};
      if(c.status==='Compensado') porBancoCards[banco].compensados.push(c);
      else porBancoCards[banco].pendentes.push(c);
    });
    
    const bancosOrdenados=Object.entries(porBancoCards).filter(([,v])=>v.pendentes.length||v.compensados.length)
      .sort((a,b)=>b[1].pendentes.length-a[1].pendentes.length||(b[1].pendentes.reduce((s,c)=>s+Number(c.valor),0))-(a[1].pendentes.reduce((s,c)=>s+Number(c.valor),0)));

    cardsEl.innerHTML=bancosOrdenados.map(([banco,{pendentes,compensados}])=>{
      const totPend=pendentes.reduce((s,c)=>s+Number(c.valor||0),0);
      const totComp=compensados.reduce((s,c)=>s+Number(c.valor||0),0);
      const temPend=pendentes.length>0;
      const borderColor=temPend?'#c0392b':'#27ae60';
      const headerBg=temPend?'#c0392b':'#1a5c35';

      
      const pendRows=pendentes.sort((a,b)=>(a.bomPara||'').localeCompare(b.bomPara||'')).map(c=>
        `<div style="display:flex;align-items:center;gap:8px;padding:6px 10px;border-bottom:1px solid #fde8e8;background:#fff9f9">
          <span style="font-size:1rem;font-weight:900;color:#c0392b;min-width:80px">Nº ${c.num||'—'}</span>
          <span style="flex:1;font-size:.78rem;color:#555">${c.fornNome} · ${c.empresa||'—'}</span>
          <span style="font-weight:800;color:#c0392b;font-size:.88rem">R$ ${fmt(c.valor)}</span>
          <span style="font-size:.72rem;color:#888;min-width:70px;text-align:right">📅 ${fmtDate(c.bomPara)||'—'}</span>
        </div>`
      ).join('');

      
      const compRows=compensados.sort((a,b)=>(b.dataCompensacao||'').localeCompare(a.dataCompensacao||'')).map(c=>
        `<div style="display:flex;align-items:center;gap:8px;padding:5px 10px;border-bottom:1px solid #e8f5e9;background:#f6fff8">
          <span style="font-size:.9rem;font-weight:700;color:#27ae60;min-width:80px">Nº ${c.num||'—'}</span>
          <span style="flex:1;font-size:.75rem;color:#777">${c.fornNome} · ${c.empresa||'—'}</span>
          <span style="font-weight:700;color:#27ae60;font-size:.85rem">R$ ${fmt(c.valor)}</span>
          <span style="font-size:.7rem;color:#27ae60;min-width:80px;text-align:right">✅ ${c.dataCompensacao||'—'}</span>
        </div>`
      ).join('');

      return `<div style="background:#fff;border:2px solid ${borderColor};border-radius:12px;overflow:hidden;display:flex;flex-direction:column">
        <!-- Header do banco -->
        <div style="background:${headerBg};color:#fff;padding:10px 14px">
          <div style="font-size:.95rem;font-weight:800;margin-bottom:6px">🏦 ${esc(banco)}</div>
          <div style="display:flex;gap:10px;flex-wrap:wrap">
            <div style="background:rgba(0,0,0,.2);border-radius:6px;padding:5px 10px;flex:1;min-width:120px">
              <div style="font-size:.62rem;font-weight:800;opacity:.85;text-transform:uppercase">⏳ À Compensar</div>
              <div style="font-size:1rem;font-weight:900">${pendentes.length>0?'R$ '+fmt(totPend):'—'}</div>
              <div style="font-size:.68rem;opacity:.8">${pendentes.length} cheque${pendentes.length!==1?'s':''}</div>
            </div>
            <div style="background:rgba(0,0,0,.15);border-radius:6px;padding:5px 10px;flex:1;min-width:120px">
              <div style="font-size:.62rem;font-weight:800;opacity:.85;text-transform:uppercase">✅ Compensados</div>
              <div style="font-size:1rem;font-weight:900">${compensados.length>0?'R$ '+fmt(totComp):'—'}</div>
              <div style="font-size:.68rem;opacity:.8">${compensados.length} cheque${compensados.length!==1?'s':''}</div>
            </div>
          </div>
        </div>
        <!-- Cheques pendentes -->
        ${pendentes.length?`
        <div style="padding:6px 10px;background:#fde8e8;font-size:.7rem;font-weight:800;color:#7b2c00;text-transform:uppercase;letter-spacing:.5px">
          ⏳ Faltam compensar — ${pendentes.length} cheque${pendentes.length!==1?'s':''}
        </div>
        ${pendRows}`:''}
        <!-- Cheques compensados -->
        ${compensados.length?`
        <div style="padding:6px 10px;background:#e8f5e9;font-size:.7rem;font-weight:800;color:#1a5c35;text-transform:uppercase;letter-spacing:.5px">
          ✅ Já compensados — ${compensados.length} cheque${compensados.length!==1?'s':''}
        </div>
        ${compRows}`:''}
      </div>`;
    }).join('') || '<p style="color:#aaa;text-align:center;padding:20px;grid-column:1/-1">Nenhum cheque lançado.</p>';
  }

  
  const baseList=temFiltro?allFiltrado:all;
  const allParaLista=baseList.filter(c=>c.status!=='Compensado'||compDentroFiltro(c));
  tbody.innerHTML=allParaLista.map(c=>{
    const cheqId=c.id||('CHQ_'+c.num+'_'+c.fornCod);
    const dataVal=c.dataCompensacao||'';
    const dataInput=dataVal?dataVal.split('/').reverse().join('-'):'';
    const trBg=c.status==='Compensado'?'background:#f0fff4':'';
    const compensado=c.status==='Compensado';
    return `<tr style="${trBg}">
      <td>${c.num}</td>
      <td>${c.empresa||'—'}</td>
      <td>${c.banco||'—'}</td>
      <td>${c.finalidade?`<span style="font-size:.72rem;font-weight:700;padding:2px 6px;border-radius:4px;background:${c.finalidade==='Adiantamento'?'#1a3a2a':'#1565c0'};color:#fff">${c.finalidade==='Adiantamento'?'💰 ADT':'✅ PGTO'}</span>`:c.tipo||'—'}</td>
      <td><b>${c.fornNome}</b></td>
      <td style="font-weight:700">R$ ${fmt(c.valor)}</td>
      <td>${c.bomPara}</td>
      <td>${c.vinculo||'—'}</td>
      <td>
        ${(()=>{
          const isS=cu&&(cuKey==='thais'||cu.role?.includes('Secretária'));
          let bank;
          if(c.status==='Cancelado') bank='<span class="b" style="background:#eee;color:#999">🚫 Cancelado</span>';
          else if(isS) bank='<span style="color:#aaa;font-size:.78rem">—</span>';
          else bank=compensado?`<span class="b b-pago">✅ Compensado</span><br><span style="font-size:.72rem;color:#27ae60">${c.dataCompensacao||''}</span>`:`<span class="b b-pend">⏳ A compensar</span>`;
          let desc='';
          if(c.status!=='Cancelado' && (c.finalidade==='Adiantamento'||c.statusDesc)){
            const p=_cheqDescPend(c);
            desc='<br><span class="b" style="background:'+(p?'#fff3cd':'#e8f5e9')+';color:'+(p?'#8a6d00':'#1a5c35')+';font-size:.66rem;margin-top:2px;display:inline-block">'+(p?'📉 A descontar':'📉 Descontado')+'</span>';
          }
          return bank+desc;
        })()}
      </td>
      <td style="display:flex;gap:4px;flex-wrap:wrap">
        ${(()=>{const isS=cu&&(cuKey==='thais'||cu.role?.includes('Secretária'));if(isS)return '';
          if(c.status==='Cancelado') return `<button onclick="reativarCheque('${cheqId}')" title="Reativar" style="background:#7f8c8d;color:#fff;border:none;border-radius:5px;padding:3px 8px;cursor:pointer;font-size:.75rem;font-weight:700">↩ Reativar</button>`;
          const baixa=compensado?`<button onclick="estornarBaixaCheque('${cheqId}')" title="Estornar baixa" style="background:#f39c12;color:#fff;border:none;border-radius:5px;padding:3px 8px;cursor:pointer;font-size:.75rem;font-weight:700">↩ Estornar</button>`:`<button onclick="abrirBaixaCheque('${cheqId}')" title="Dar baixa no banco" style="background:#27ae60;color:#fff;border:none;border-radius:5px;padding:3px 8px;cursor:pointer;font-size:.78rem;font-weight:700">💵 Baixa</button>`;
          return baixa+`<button onclick="cancelarCheque('${cheqId}')" title="Cancelar cheque" style="background:#95a5a6;color:#fff;border:none;border-radius:5px;padding:3px 8px;cursor:pointer;font-size:.78rem">🚫</button>`;})()}
        <button onclick="editarCheque('${cheqId}')" title="Editar" style="background:#1a3a2a;color:#fff;border:none;border-radius:5px;padding:3px 8px;cursor:pointer;font-size:.8rem">✏️</button>
        <button onclick="excluirCheque('${cheqId}')" title="Excluir" style="background:#e74c3c;color:#fff;border:none;border-radius:5px;padding:3px 8px;cursor:pointer;font-size:.8rem">🗑</button>
      </td>
    </tr>`;
  }).join('');
}


function limparFiltrosCompra(){
  const s=document.getElementById('filt-compra-status');
  const d=document.getElementById('filt-compra-de');
  const a=document.getElementById('filt-compra-ate');
  const f=document.getElementById('filt-compra-forn');
  if(s) s.value='todos';
  if(d) d.value='';
  if(a) a.value='';
  if(f) f.value='';
  renderTickets();
}






let _dcDbKey=null;
function abrirDetalheCompra(dbKey){
  const t=TICKETS_DB[dbKey];
  if(!t){ showToast('Ticket não encontrado.','error'); return; }
  _dcDbKey=dbKey;
  const modal=document.getElementById('modal-detalhe-compra');
  if(!modal) return;
  const fmt=v=>Number(v||0).toLocaleString('pt-BR',{minimumFractionDigits:2});
  const titulo=document.getElementById('dc-titulo');
  const info=document.getElementById('dc-info');
  if(titulo) titulo.textContent='🧾 Detalhes da Compra — Ticket '+(t.ticket||dbKey);
  if(info) info.innerHTML='<b>Fornecedor:</b> '+esc(t.fornecedor||'—')+' &nbsp;|&nbsp; <b>Data:</b> <span id="dc-data-txt">'+esc(t.data||'—')+'</span> '
    +'<button onclick="corrigirDataCompra()" title="Corrigir a data da compra" style="border:1px solid #f0a500;background:#fff8e1;color:#856404;border-radius:6px;padding:2px 8px;cursor:pointer;font-size:.78rem;font-weight:700">✏️ Corrigir data</button>'
    +' &nbsp;|&nbsp; <b>Status:</b> '+esc(t.status||'—')
    +'<div id="dc-data-editor"></div>';
  const tbody=document.getElementById('dc-itens-body');
  if(!tbody) return;
  const itens=t.itens||[];
  let _bodyHtml=itens.length===0
    ?'<tr><td colspan="5" style="text-align:center;color:#aaa">Nenhum item no ticket</td></tr>'
    :itens.map(function(it){
      const bruto=Number(it.pesoBruto!=null?it.pesoBruto:(it.br||0));
      const liq=Number(it.pesoLiqAjust!=null?it.pesoLiqAjust:(it.pesoLiq!=null?it.pesoLiq:(it.lq!=null?it.lq:bruto)));
      const preco=Number(it.preco||0);
      const total=Number(it.total!=null?it.total:liq*preco);
      const _idt=(it.ident||it.matBase&&it.matBase!==it.mat?it.ident:it.ident)||'';
      return '<tr>'
        +'<td style="font-size:.82rem">'+esc(it.mat||'—')+(_idt?' <small style="color:#c0392b;font-weight:600">('+esc(_idt)+')</small>':'')+'</td>'
        +'<td style="text-align:right">'+bruto.toFixed(3)+'</td>'
        +'<td style="text-align:right">'+liq.toFixed(3)+'</td>'
        +'<td style="text-align:right">'+preco.toLocaleString('pt-BR',{minimumFractionDigits:2})+'</td>'
        +'<td style="text-align:right;font-weight:700">R$ '+fmt(total)+'</td>'
        +'</tr>';
    }).join('');
  
  const _acr=Array.isArray(t.acrescimos)?t.acrescimos:[];
  _acr.forEach(function(a,idx){
    const _neg=Number(a.v||0)<0;
    const _bgA=_neg?'#fdecec':'#f1f8e9';
    const _cor=_neg?'#c0392b':'#2e7d32';
    const _lbl=_neg?'➖ Desconto':'➕ Valor extra';
    const _valTxt=(_neg?'− R$ ':'R$ ')+fmt(Math.abs(Number(a.v||0)));
    _bodyHtml+='<tr style="background:'+_bgA+'">'
      +'<td style="font-size:.82rem;color:'+_cor+';font-weight:700">'+_lbl+(a.obs?' <small style="color:#666;font-weight:400">('+esc(a.obs)+')</small>':'')+'</td>'
      +'<td style="text-align:right;color:#bbb">—</td>'
      +'<td style="text-align:right;color:#bbb">—</td>'
      +'<td style="text-align:right;color:#bbb">—</td>'
      +'<td style="text-align:right;font-weight:700;white-space:nowrap;color:'+_cor+'">'+_valTxt+' <button onclick="removerAcrescimoCompra('+idx+')" title="Remover este lançamento" style="border:1px solid #f3c0c0;background:#fff;color:#c0392b;border-radius:5px;padding:1px 6px;cursor:pointer;font-size:.72rem">🗑️</button></td>'
      +'</tr>';
  });
  tbody.innerHTML=_bodyHtml;
  const foot=document.getElementById('dc-itens-foot');
  if(foot){
    const _acrTot=(Array.isArray(t.acrescimos)?t.acrescimos:[]).reduce(function(s,a){ return s+Number(a.v||0); },0);
    const _acrCor=_acrTot<0?'#c0392b':'#2e7d32';
    const _acrLbl=_acrTot<0?'Descontos aplicados':'Valores extras somados';
    const _acrVal=(_acrTot<0?'− R$ ':'R$ ')+fmt(Math.abs(_acrTot));
    foot.innerHTML=(_acrTot?('<tr style="font-size:.8rem;color:'+_acrCor+'">'
      +'<td colspan="4" style="padding:4px 10px;text-align:right">'+_acrLbl+'</td>'
      +'<td style="padding:4px 10px;text-align:right;font-weight:700">'+_acrVal+'</td></tr>'):'')
      +'<tr style="background:#f5f5f5;font-weight:800">'
      +'<td colspan="4" style="padding:8px 10px;text-align:right">Total Geral</td>'
      +'<td style="padding:8px 10px;text-align:right">R$ '+fmt(t.totalGeral)+'</td></tr>'
      +'<tr style="font-size:.8rem;color:#666">'
      +'<td colspan="4" style="padding:6px 10px;text-align:right">Adiantamento '
      +'<button onclick="editarAdiantamentoCompra()" title="Corrigir ou tirar o adiantamento desta compra" style="border:1px solid #f0a500;background:#fff8e1;color:#856404;border-radius:6px;padding:1px 7px;cursor:pointer;font-size:.72rem;font-weight:700">✏️ Corrigir</button></td>'
      +'<td style="padding:6px 10px;text-align:right">R$ '+fmt(t.adiantamento)+'</td></tr>'
      +'<tr style="font-size:.85rem;font-weight:700;color:var(--primary)">'
      +'<td colspan="4" style="padding:6px 10px;text-align:right">Saldo a Pagar</td>'
      +'<td style="padding:6px 10px;text-align:right">R$ '+fmt(t.saldoPagar)+'</td></tr>';
  }
  modal.style.display='flex';
  setTimeout(()=>_atualizarDicaScroll('dc-itens-body','dc-scroll-dica'),0);
}
function fecharDetalheCompra(){
  const modal=document.getElementById('modal-detalhe-compra');
  if(modal) modal.style.display='none';
  _dcDbKey=null;
}






function corrigirDataCompra(){
  const t=TICKETS_DB[_dcDbKey];
  if(!t){ showToast('Ticket não encontrado.','error'); return; }
  const ed=document.getElementById('dc-data-editor');
  if(!ed) return;
  const iso=(t.data||'').indexOf('/')>=0 ? t.data.split('/').reverse().join('-') : (t.data||'');
  ed.innerHTML='<div style="margin-top:8px;padding:10px 12px;background:#fff8e1;border:1px solid #f0c36d;border-radius:8px;display:flex;gap:8px;align-items:center;flex-wrap:wrap">'
    +'<label style="font-size:.82rem;font-weight:700;color:#856404">Nova data:</label>'
    +'<input type="date" id="dc-data-nova" value="'+esc(iso)+'" style="padding:6px 8px;border:1px solid #c8a400;border-radius:6px;font-size:.85rem">'
    +'<button class="btn-save" style="padding:6px 12px;font-size:.82rem" onclick="salvarDataCompra()">💾 Salvar data</button>'
    +'<button class="btn-cancel" style="padding:6px 12px;font-size:.82rem" onclick="document.getElementById(\'dc-data-editor\').innerHTML=\'\'">Cancelar</button>'
    +'</div>';
}
function salvarDataCompra(){
  const t=TICKETS_DB[_dcDbKey];
  if(!t){ showToast('Ticket não encontrado.','error'); return; }
  const iso=document.getElementById('dc-data-nova')?.value||'';
  if(!iso){ alert('Escolha a nova data.'); return; }
  const nova=iso.split('-').reverse().join('/');
  const antiga=t.data||'';
  if(nova===antiga){ document.getElementById('dc-data-editor').innerHTML=''; return; }
  t.data=nova;
  
  let mudouCP=false;
  CONTAS_PAGAR.forEach(function(cp){
    if(cp.ticket!==t.ticket) return;
    
    if(!cp.lancto || cp.lancto===antiga){ cp.lancto=nova; mudouCP=true; }
    
    
    if(!cp.venc || cp.venc===antiga){ cp.venc=nova; mudouCP=true; }
    if(mudouCP) cp._upd=Date.now();
  });
  saveDB();
  try{ if(mudouCP){ saveContasPagar(); renderContasPagar(); } }catch(e){}
  try{ renderTickets(); }catch(e){}
  showToast('✅ Data corrigida para '+nova+'!','success');
  abrirDetalheCompra(_dcDbKey);
}






function editarAdiantamentoCompra(){
  const t=TICKETS_DB[_dcDbKey];
  if(!t){ showToast('Ticket não encontrado.','error'); return; }
  const ed=document.getElementById('dc-adt-editor');
  if(!ed) return;
  const atual=Number(t.adiantamento||0);
  const atualTxt=atual.toLocaleString('pt-BR',{minimumFractionDigits:2});
  ed.innerHTML='<div style="margin-top:10px;padding:12px 14px;background:#fff8e1;border:1px solid #f0c36d;border-radius:8px">'
    +'<div style="font-size:.82rem;font-weight:700;color:#856404;margin-bottom:8px">✏️ Corrigir o adiantamento desta compra</div>'
    +'<div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap">'
    +'<label style="font-size:.82rem;font-weight:700;color:#555">Novo valor do adiantamento R$:</label>'
    +'<input type="text" id="dc-adt-novo" value="'+esc(atualTxt)+'" style="width:140px;padding:6px 8px;border:1px solid #c8a400;border-radius:6px;font-size:.9rem;text-align:right">'
    +'<button class="btn-save" style="padding:6px 12px;font-size:.82rem" onclick="salvarAdiantamentoCompra()">💾 Salvar</button>'
    +'<button class="btn-cancel" style="padding:6px 12px;font-size:.82rem" onclick="document.getElementById(\'dc-adt-editor\').innerHTML=\'\'">Cancelar</button>'
    +'</div>'
    +'<div style="font-size:.75rem;color:#8a6d3b;margin-top:8px;line-height:1.5">💡 Pra <b>tirar</b> o adiantamento, coloque <b>0</b>. Isso corrige o <b>Saldo a Pagar</b> desta compra e a <b>Conta a Pagar</b> ligada a ela. Se você também tinha lançado esse adiantamento na aba <b>Adiantamentos</b>, confira lá também.</div>'
    +'</div>';
  const inp=document.getElementById('dc-adt-novo'); if(inp){ inp.focus(); inp.select(); }
}
function salvarAdiantamentoCompra(){
  const t=TICKETS_DB[_dcDbKey];
  if(!t){ showToast('Ticket não encontrado.','error'); return; }
  const raw=(document.getElementById('dc-adt-novo')?.value||'').trim();
  
  let s=raw.replace(/[^0-9.,]/g,'');
  if(s.indexOf(',')>=0){ s=s.replace(/\./g,'').replace(',','.'); }
  const novo=_r2(parseFloat(s)||0);
  if(novo<0){ alert('Valor inválido.'); return; }
  const antigo=Number(t.adiantamento||0);
  if(Math.abs(novo-antigo)<0.005){ document.getElementById('dc-adt-editor').innerHTML=''; return; }
  if(!confirm('Trocar o adiantamento desta compra de R$ '+antigo.toLocaleString('pt-BR',{minimumFractionDigits:2})+' para R$ '+novo.toLocaleString('pt-BR',{minimumFractionDigits:2})+'?\n\nIsso recalcula o Saldo a Pagar e a Conta a Pagar desta compra.')) return;
  t.adiantamento=novo;
  
  var _cpAd=CONTAS_PAGAR.find(function(c){ return c.ticket===t.ticket && c.status!=='Pago'; });
  var _jaPagoAd=_cpAd?Number(_cpAd.valorPago||0):0;
  t.saldoPagar=_r2(Number(t.totalGeral||0) - novo + Number(t.saldoAnterior||0) - _jaPagoAd);
  if(t.saldoPagar<0) t.saldoPagar=0;
  t.status = (t.saldoPagar<=0.01) ? 'Pago' : 'Pendente';
  try{
    if(_cpAd){ _cpAd.valor=Math.max(Number(t.saldoPagar||0),0); if(_cpAd.valor<=0.01){ _cpAd.status='Pago'; if(!_cpAd.dataPgto) _cpAd.dataPgto=t.data||''; } _cpAd._upd=Date.now(); saveContasPagar(); try{ renderContasPagar(); }catch(e){} }
  }catch(e){}
  saveDB();
  try{ registrarHistorico('Compra','Adiantamento corrigido',(t.fornecedor||'')+' — Ticket '+(t.ticket||'')+' — adiant. de R$ '+antigo.toLocaleString('pt-BR',{minimumFractionDigits:2})+' → R$ '+novo.toLocaleString('pt-BR',{minimumFractionDigits:2}), null, {ticket:t.ticket}); }catch(e){}
  try{ renderTickets(); }catch(e){}
  try{ renderComprasSucata(); }catch(e){}
  try{ renderFluxo(); renderDashboard(); }catch(e){}
  showToast('✅ Adiantamento corrigido! Saldo a Pagar recalculado.','success');
  abrirDetalheCompra(_dcDbKey);
}








function adicionarItemTicket(){
  const t=TICKETS_DB[_dcDbKey];
  if(!t){ showToast('Ticket não encontrado.','error'); return; }
  const matEl=document.getElementById('dc-add-mat');
  const brEl=document.getElementById('dc-add-br');
  const lqEl=document.getElementById('dc-add-lq');
  const prEl=document.getElementById('dc-add-pr');
  const rawMat=(matEl&&matEl.value||'').trim();
  const mat=(typeof METAIS!=='undefined'?METAIS.find(m=>m.toUpperCase()===rawMat.toUpperCase()):null)||(rawMat?rawMat.toUpperCase():'');
  const br=parseFloat(brEl&&brEl.value)||0;
  const lqRaw=parseFloat(lqEl&&lqEl.value)||0;
  const lq=lqRaw>0?lqRaw:br;
  const pr=parseFloat(prEl&&prEl.value)||0;
  if(!mat||!(lq>0)){ showToast('⚠️ Informe Material e Peso.','error'); return; }
  if(typeof METAIS!=='undefined' && !METAIS.includes(mat)){
    try{ _garantirMetalCadastrado(mat); saveEstoque(); }catch(e){}
  }
  t.itens=t.itens||[];
  t.itens.push({ mat:mat, pesoBruto:br||lq, pesoLiq:lq, preco:pr, total:_r2(lq*pr) });
  t.totalGeral=t.itens.reduce((s,it)=>{
    const liq=Number(it.pesoLiqAjust!=null?it.pesoLiqAjust:(it.pesoLiq!=null?it.pesoLiq:(it.br||0)));
    return s + Number(it.total!=null?it.total:liq*Number(it.preco||0));
  },0) + Number(t.acrescimo||0);
  t.saldoPagar=_r2(t.totalGeral - Number(t.adiantamento||0) + Number(t.saldoAnterior||0));
  const cpExistente=CONTAS_PAGAR.find(cp=>cp.ticket===t.ticket && cp.status==='Pendente');
  if(cpExistente){
    cpExistente.valor=Math.max(t.saldoPagar,0);
    cpExistente._upd=Date.now();
    saveContasPagar(); renderContasPagar();
  } else if(t.saldoPagar>0){
    CONTAS_PAGAR.push({ id:_novoIdCP(),
      lancto:t.data, desc:'Compra Sucata – Ticket '+t.ticket+' – '+(t.fornecedor||''),
      cred:t.fornecedor||'', cat:'Compra de Sucata', bancoCod:'', bancoNome:'', tipoForn:'compra',
      venc:t.data, valor:t.saldoPagar, status:'Pendente',
      dataPgto:'', obs:'Gerado automaticamente – Ticket '+t.ticket, ticket:t.ticket,
      fornCod:t.fornecedorCod||''
    });
    saveContasPagar(); renderContasPagar();
  }
  saveDB();
  showToast('✅ Item adicionado à compra!','success');
  if(matEl) matEl.value=''; if(brEl) brEl.value=''; if(lqEl) lqEl.value=''; if(prEl) prEl.value='';
  abrirDetalheCompra(_dcDbKey);
  try{ renderTickets(); }catch(e){}
}





function _recalcTotaisCompra(t){
  const itensSum=(t.itens||[]).reduce(function(s,it){
    const liq=Number(it.pesoLiqAjust!=null?it.pesoLiqAjust:(it.pesoLiq!=null?it.pesoLiq:(it.pesoBruto!=null?it.pesoBruto:(it.br||0))));
    return s+Number(it.total!=null?it.total:liq*Number(it.preco||0));
  },0);
  t.totalGeral=_r2(itensSum+Number(t.acrescimo||0));
  t.saldoPagar=_r2(t.totalGeral-Number(t.adiantamento||0)+Number(t.saldoAnterior||0));
}
function lancarValorCompra(sinal){
  const t=TICKETS_DB[_dcDbKey];
  if(!t){ showToast('Ticket não encontrado.','error'); return; }
  const vEl=document.getElementById('dc-add-valor');
  const oEl=document.getElementById('dc-add-valor-obs');
  let raw=(vEl&&vEl.value||'').trim().replace(/[^0-9.,]/g,'');
  if(raw.indexOf(',')>=0){ raw=raw.replace(/\./g,'').replace(',','.'); }
  let v=parseFloat(raw);
  if(!isFinite(v)||v<=0){ showToast('⚠️ Informe um valor (ex: 165,00).','error'); return; }
  v=v*(sinal<0?-1:1);              
  const obs=(oEl&&oEl.value||'').trim();
  t.acrescimos=Array.isArray(t.acrescimos)?t.acrescimos:[];
  t.acrescimos.push({v:v, obs:obs, quando:_hojeISO()});
  t.acrescimo=t.acrescimos.reduce(function(s,a){ return s+Number(a.v||0); },0);
  _recalcTotaisCompra(t);
  
  
  
  
  try{
    const cpPend=CONTAS_PAGAR.find(function(cp){ return cp.ticket===t.ticket && cp.status==='Pendente'; });
    if(cpPend){
      cpPend.valor=Math.max(Number(t.saldoPagar||0),0);
      cpPend._upd=Date.now();
      saveContasPagar(); try{ renderContasPagar(); }catch(e){}
    } else if(v>0){
      CONTAS_PAGAR.push({ id:_novoIdCP(), lancto:t.data,
        desc:'Valor extra – Ticket '+t.ticket+' – '+(t.fornecedor||''),
        cred:t.fornecedor||'', cat:'Compra de Sucata', bancoCod:'', bancoNome:'', tipoForn:'compra',
        venc:t.data, valor:Math.max(v,0), status:'Pendente', dataPgto:'',
        obs:'Valor extra adicionado à compra'+(obs?(' – '+obs):''), ticket:t.ticket, fornCod:t.fornecedorCod||'' });
      saveContasPagar(); try{ renderContasPagar(); }catch(e){}
    }
  }catch(e){ console.warn('acrescimo CP',e); }
  saveDB();
  showToast((v<0?'➖ Valor de R$ '+Math.abs(v).toLocaleString('pt-BR',{minimumFractionDigits:2})+' tirado da compra!':'✅ Valor de R$ '+Number(v).toLocaleString('pt-BR',{minimumFractionDigits:2})+' adicionado à compra!'),'success');
  if(vEl) vEl.value=''; if(oEl) oEl.value='';
  abrirDetalheCompra(_dcDbKey);
  try{ renderTickets(); }catch(e){}
}

function adicionarValorCompra(){ lancarValorCompra(1); }
function removerAcrescimoCompra(idx){
  const t=TICKETS_DB[_dcDbKey];
  if(!t||!Array.isArray(t.acrescimos)||!t.acrescimos[idx]) return;
  const a=t.acrescimos[idx];
  if(!confirm('Remover o valor extra de R$ '+Number(a.v||0).toLocaleString('pt-BR',{minimumFractionDigits:2})+(a.obs?(' ('+a.obs+')'):'')+' desta compra?')) return;
  t.acrescimos.splice(idx,1);
  t.acrescimo=t.acrescimos.reduce(function(s,x){ return s+Number(x.v||0); },0);
  _recalcTotaisCompra(t);
  try{
    const cpPend=CONTAS_PAGAR.find(function(cp){ return cp.ticket===t.ticket && cp.status==='Pendente'; });
    if(cpPend){ cpPend.valor=Math.max(Number(t.saldoPagar||0),0); cpPend._upd=Date.now(); saveContasPagar(); try{ renderContasPagar(); }catch(e){} }
  }catch(e){}
  saveDB();
  showToast('Valor extra removido.','success');
  abrirDetalheCompra(_dcDbKey);
  try{ renderTickets(); }catch(e){}
}

function renderTickets(){
  const tbody=document.getElementById('tb-compras');
  if(!tbody)return;
  const _numFinito=function(v, fallback){
    const n=Number(v);
    return Number.isFinite(n)?n:(fallback==null?0:fallback);
  };
  const fmt=v=>_numFinito(v,0).toLocaleString('pt-BR',{minimumFractionDigits:2});

  
  
  
  
  
  
  try{
    if(typeof CONTAS_PAGAR!=='undefined' && Array.isArray(CONTAS_PAGAR) && typeof TICKETS_DB!=='undefined'){
      let _reconcMudou=false;
      Object.values(TICKETS_DB).forEach(function(tk){
        if(!tk || tk._balSessao || tk._rodEntrada || tk.status==='Aguard. Saída' || tk.status==='Aguard. Preço') return;
        const _saldoAtual=Number(tk.saldoPagar);
        if(tk.status==='Pago' || (Number.isFinite(_saldoAtual)&&_saldoAtual<=0.01)) return; 
        var cps=CONTAS_PAGAR.filter(function(cp){ return cp && cp.ticket && String(cp.ticket)===String(tk.ticket); });
        if(!cps.length) return;                       
        var temAberta=cps.some(function(cp){ return cp.status!=='Pago'; });
        if(!temAberta){                               
          tk.saldoPagar=0; tk.status='Pago';
          if(!tk.dataPgto){ var _ult=cps[cps.length-1]; tk.dataPgto=(_ult&&_ult.dataPgto)||new Date().toLocaleDateString('pt-BR'); }
          tk._upd=Date.now(); _reconcMudou=true;
        }
      });
      if(_reconcMudou){ try{ saveDB(); }catch(e){} }
    }
  }catch(e){ console.warn('reconc compras↔contas:',e); }

  
  const filtStatus=(document.getElementById('filt-compra-status')?.value)||'todos';
  const filtDe=document.getElementById('filt-compra-de')?.value||'';
  const filtAte=document.getElementById('filt-compra-ate')?.value||'';
  const filtForn=document.getElementById('filt-compra-forn')?.value||'';

  
  const toIso=d=>{
    if(!d) return '';
    if(d.includes('-')) return d;
    const p=d.split('/'); return p[2]+'-'+p[1]+'-'+p[0];
  };

  
  
  const dlForn=document.getElementById('filt-compra-forn-list');
  if(dlForn){
    const nomesForn=[...new Set(Object.values(TICKETS_DB)
      .filter(tk=>!tk._balSessao)
      .map(tk=>tk.fornecedor||tk.fornecedorNome||tk.forn||'')
      .filter(Boolean))].sort((a,b)=>a.localeCompare(b,'pt-BR'));
    dlForn.innerHTML=nomesForn.map(n=>`<option value="${esc(n)}">`).join('');
  }

  
  
  
  let _ticketsReparados=false; Object.values(TICKETS_DB).forEach(function(tk){ if(_normalizarTicketFinanceiro(tk)) _ticketsReparados=true; }); if(_ticketsReparados){ try{ saveDB(); }catch(e){} }
  const baseTodos=Object.values(TICKETS_DB).filter(tk=>!tk._balSessao && !tk._rodEntrada && tk.status!=='Aguard. Saída');
  const creditosTodos=[];
  Object.entries(ADT_POR_FORN).forEach(([cod,lista])=>{
    lista.filter(a=>a.forma==='Crédito'&&a.status==='Pendente').forEach(a=>{ creditosTodos.push(a); });
  });
  const totalCompradoKpi=baseTodos.reduce((s,tk)=>s+(Number(tk.totalGeral)||0),0);
  const totalAdtKpi=baseTodos.reduce((s,tk)=>s+(Number(tk.adiantamento)||0),0);
  const totalSaldoKpi=baseTodos.reduce((s,tk)=>s+Math.max(0,(Number(tk.saldoPagar)||0)),0)
                    - creditosTodos.reduce((s,c)=>s+Number(c.valor),0);
  { const kpiT=document.getElementById('kpi-tickets-mes');
    const kpiC=document.getElementById('kpi-total-compras');
    const kpiA=document.getElementById('kpi-total-adt');
    const kpiS=document.getElementById('kpi-saldo-pagar');
    if(kpiT) kpiT.textContent=baseTodos.length;
    if(kpiC) kpiC.textContent='R$ '+fmt(totalCompradoKpi);
    if(kpiA) kpiA.textContent='R$ '+fmt(totalAdtKpi);
    if(kpiS) kpiS.textContent='R$ '+fmt(Math.max(0,totalSaldoKpi)); }

  
  let all=Object.entries(TICKETS_DB).filter(([k,tk])=>!tk._balSessao && !tk._rodEntrada && tk.status!=='Aguard. Saída').map(([k,tk])=>({...tk,_dbKey:k}));
  if(filtStatus==='aguard_preco') all=all.filter(tk=>tk._balFinalizado && tk.status==='Aguard. Preço');
  else if(filtStatus==='pendente') all=all.filter(tk=>{
    const saldo=Number(tk.saldoPagar);
    return tk.status==='Aguard. Preço'||tk.status==='Consolidado'||tk._balFinalizado||(tk.status!=='Pago'&&Number.isFinite(saldo)&&saldo>0);
  });
  else if(filtStatus==='pago') all=all.filter(tk=>{
    const saldo=Number(tk.saldoPagar);
    return tk.status!=='Aguard. Preço'&&tk.status!=='Consolidado'&&!tk._balFinalizado&&(tk.status==='Pago'||(Number.isFinite(saldo)&&saldo<=0));
  });
  if(filtForn){ const fn=filtForn.trim().toLowerCase(); all=all.filter(tk=>(tk.fornecedor||tk.fornecedorNome||tk.forn||'').toLowerCase().includes(fn)); }
  if(filtDe) all=all.filter(tk=>toIso(tk.data)>=filtDe);
  if(filtAte) all=all.filter(tk=>toIso(tk.data)<=filtAte);


  
  const creditos=[];
  if(filtStatus!=='pago'){
    Object.entries(ADT_POR_FORN).forEach(([cod,lista])=>{
      lista.filter(a=>a.forma==='Crédito'&&a.status==='Pendente').forEach(a=>{
        const forn=FORNECEDORES.find(f=>f.cod===cod);
        creditos.push({...a, fornNome:forn?forn.nome:cod});
      });
    });
  }

  const countEl=document.getElementById('filt-compra-count');
  if(countEl) countEl.textContent=all.length+' registro'+(all.length!==1?'s':'');

  if(all.length===0&&creditos.length===0){
    tbody.innerHTML=`<tr><td colspan="9" style="color:var(--gray);text-align:center;padding:20px">Nenhum registro encontrado</td></tr>`;
    return;
  }
  all.sort((a,b)=>{var _f=d=>{d=String(d||'');return d.indexOf('/')>=0?d.split('/').reverse().join('-'):d;};return _f(b.data).localeCompare(_f(a.data));}); 

  let rows=all.map(tk=>{
    const statusEspecial=tk.status==='Aguard. Preço'||tk.status==='Consolidado';
    const saldoNum=Number(tk.saldoPagar);
    const saldoFinito=Number.isFinite(saldoNum);
    const totalFinito=Number.isFinite(Number(tk.totalGeral));
    const adtFinito=Number.isFinite(Number(tk.adiantamento));
    const isPago=!statusEspecial&&(tk.status==='Pago'||(saldoFinito&&saldoNum<=0));
    const bgRow=isPago?'background:#f2faf3':'';
    const statusBadge=tk.status==='Aguard. Preço'
      ?'<span class="b b-pendente">Aguard. Preço</span>'
      :tk.status==='Consolidado'
        ?'<span class="b" style="background:#e8eaf6;color:#3949ab">Consolidado</span>'
        :isPago
          ?'<span class="b b-pago">Quitado</span>'
          :'<span class="b b-pendente">Pendente</span>';
    const saldoCell=statusEspecial||!saldoFinito
      ?'<span style="color:#888">—</span>'
      :saldoNum<0
        ?'<span style="background:#ffd5d5;color:#c0392b;padding:2px 7px;border-radius:6px;font-size:.78rem;font-weight:700">⚠️ FORN. DEVE</span> R$ '+fmt(Math.abs(saldoNum))
        :isPago
          ?'<span style="color:#27ae60;font-weight:800">✅ Quitado</span>'
          :'<b style="color:var(--primary)">R$ '+fmt(saldoNum)+'</b>';
    const totalCell=(tk.status==='Aguard. Preço'||!totalFinito)?'—':'R$ '+fmt(tk.totalGeral);
    const adtCell=(tk.status==='Aguard. Preço'||!adtFinito)?'—':'R$ '+fmt(tk.adiantamento);
    return `<tr style="${bgRow}">
      <td><b>${tk.ticket}</b></td>
      <td>${fmtDate(tk.data)||'—'}</td>
      <td style="cursor:pointer;color:#1565c0;text-decoration:underline" onclick="abrirDetalheCompra('${tk._dbKey}')" title="Ver todos os itens desta compra">${tk.fornecedor}</td>
      <td>${(tk.itens||[]).reduce((s,i)=>s+Number(i.pesoLiq||0),0).toFixed(1)} kg</td>
      <td style="cursor:pointer;color:#1565c0;text-decoration:underline" onclick="abrirDetalheCompra('${tk._dbKey}')" title="Ver todos os itens desta compra">${totalCell}</td>
      <td>${adtCell}</td>
      <td style="font-weight:800">${saldoCell}</td>
      <td>${statusBadge}</td>
      <td style="display:flex;gap:4px;align-items:center">
        ${isPago
          ? '<button onclick="desmarcarCompraPaga(\''+tk._dbKey+'\')" title="Desmarcar pago (volta a pendente)" style="background:#e0e7ef;color:#556;border:none;border-radius:6px;padding:4px 8px;cursor:pointer;font-size:.75rem;font-weight:700">↩️</button>'
          : '<button onclick="marcarCompraPaga(\''+tk._dbKey+'\')" title="Marcar como paga (quando o pagamento já está lançado na Ficha) — não cria adiantamento nem duplica" style="background:#1a7f4b;color:#fff;border:none;border-radius:6px;padding:4px 8px;cursor:pointer;font-size:.75rem;font-weight:700">✅ Pago</button>'}
        <button onclick="csAbrirImpureza('${tk._dbKey}')" title="Editar / Desconto de Impureza" style="background:#1a3a2a;color:#fff;border:none;border-radius:6px;padding:4px 8px;cursor:pointer;font-size:.75rem">✏️</button>
        <button class="btn-edit-danger" onclick="excluirEntradaCompra('${tk._dbKey}')" title="Excluir entrada" style="font-size:.75rem">🗑️</button>
      </td>
    </tr>`;
  }).join('');

  
  if(creditos.length>0){
    rows+=`<tr style="background:#e8eceb">
      <td colspan="9" style="color:#fff;font-weight:700;font-size:.82rem;padding:8px 12px;letter-spacing:.5px">
        ⚠️ FORNECEDORES COM SALDO NEGATIVO (CRÉDITO A DESCONTAR NA PRÓXIMA COMPRA)
      </td></tr>`;
    rows+=creditos.map(c=>`
      <tr>
        <td><b style="color:#c0392b;font-size:.95rem">⚠️ ${c.cod}</b></td>
        <td style="color:#c0392b">${fmtDate(c.data)||'—'}</td>
        <td style="color:#c0392b;font-weight:700">${c.fornNome}</td>
        <td colspan="2" style="color:#c0392b;font-style:italic">SALDO DEVEDOR da carga anterior${c.obs?' – '+c.obs:''}</td>
        <td>—</td>
        <td style="font-weight:900;color:#c0392b;font-size:1rem">R$ ${fmt(c.valor)}</td>
        <td><span style="background:#c0392b;color:#fff;padding:3px 10px;border-radius:10px;font-size:.75rem;font-weight:700">⚠️ SALDO DEVEDOR</span></td>
        <td></td>
      </tr>`).join('');
  }

  
  if(all.length>0){
    const totPeso=all.reduce((s,tk)=>s+(tk.itens?tk.itens.reduce((ss,i)=>ss+Number(i.pesoLiq||0),0):0),0);
    const totVal=all.reduce((s,tk)=>s+Number(tk.totalGeral||0),0);
    const totAdt=all.reduce((s,tk)=>s+Number(tk.adiantamento||0),0);
    const totSaldo=all.reduce((s,tk)=>s+Math.max(0,Number(tk.saldoPagar||0)),0);
    rows+=`<tr style="background:#e8f5e9;font-weight:800;border-top:2px solid #27ae60">
      <td colspan="3" style="text-align:right;padding:8px 12px;color:#1a5e2a">📊 TOTAL (${all.length} ticket${all.length!==1?'s':''})</td>
      <td style="text-align:center;color:#1a5e2a">${totPeso.toFixed(1)} kg</td>
      <td style="color:#1a5e2a;font-size:1.05rem">R$ ${fmt(totVal)}</td>
      <td style="color:#856404">R$ ${fmt(totAdt)}</td>
      <td style="color:var(--primary);font-size:1.05rem">R$ ${fmt(totSaldo)}</td>
      <td colspan="2"></td>
    </tr>`;
  }
  tbody.innerHTML=rows;
}

function excluirEntradaCompra(ticket){
  const tk=TICKETS_DB[ticket];
  if(!tk) return;
  const msg='Excluir a entrada de compra Ticket #'+ticket+' ('+tk.fornecedor+')?\n\nEsta ação não pode ser desfeita.';
  if(!confirm(msg)) return;
  _ticketExcluir(ticket);
  saveDB();
  
  var cpAntes=CONTAS_PAGAR.length;
  for(var _i=CONTAS_PAGAR.length-1;_i>=0;_i--){
    var _cp=CONTAS_PAGAR[_i];
    if(_cp.ticket===ticket||(_cp.obs&&_cp.obs.indexOf('Ticket '+ticket)>=0)){
      _removerCPporIndice(_i);
    }
  }
  if(CONTAS_PAGAR.length!==cpAntes){ saveContasPagar(); renderContasPagar(); }
  renderTickets();
  const tbCanh=document.getElementById('tb-canhotos');
  if(tbCanh) renderCanhotos();
  if(typeof showToast==='function') showToast('🗑️ Entrada #'+ticket+' excluída e removida de Contas a Pagar.','warn',3000);
}






function marcarCompraPaga(dbKey){
  var tk=TICKETS_DB[dbKey];
  if(!tk){ showToast('Ticket não encontrado.','error'); return; }
  var _fmt=function(v){ return Number(v||0).toLocaleString('pt-BR',{minimumFractionDigits:2}); };
  if(!confirm('Marcar a compra '+(tk.ticket||'')+' (R$ '+_fmt(tk.totalGeral)+') como PAGA?\n\nUse quando o pagamento JÁ está lançado na Ficha (adiantamento). Não cria pagamento novo e não duplica a Ficha. Dá pra desfazer no ↩️.')) return;
  
  tk._pagoUndo={ adiantamento:Number(tk.adiantamento||0), saldoPagar:Number(tk.saldoPagar||0), status:tk.status||'' };
  tk.adiantamento=0;      
  tk.saldoPagar=0;
  tk.status='Pago';
  
  
  try{
    var cps=CONTAS_PAGAR.filter(function(c){ return c && c.ticket===tk.ticket && c.status!=='Pago'; });
    cps.forEach(function(c){
      if(!Array.isArray(c.pagamentos)) c.pagamentos=[];
      c.pagamentos.push({ data:tk.data||'', valor:0, adt:Number(c.valor||0), banco:'', obs:'Coberto por adiantamento (Ficha) — marcado como pago' });
      c.status='Pago'; c.dataPgto=tk.data||''; c._upd=Date.now();
    });
    if(cps.length){ saveContasPagar(); try{ renderContasPagar(); }catch(e){} }
  }catch(e){}
  saveDB();
  try{ registrarHistorico('Compra','Marcada como paga',(tk.fornecedor||'')+' — '+(tk.ticket||'')+' — R$ '+_fmt(tk.totalGeral)+' (coberto pela Ficha)', null, {ticket:tk.ticket}); }catch(e){}
  try{ renderTickets(); }catch(e){}
  try{ renderFluxo(); renderDashboard(); }catch(e){}
  showToast('✅ Compra '+(tk.ticket||'')+' marcada como paga.','success');
}
window['marcarCompraPaga']=marcarCompraPaga;


function desmarcarCompraPaga(dbKey){
  var tk=TICKETS_DB[dbKey];
  if(!tk){ showToast('Ticket não encontrado.','error'); return; }
  if(!confirm('Desmarcar o pago da compra '+(tk.ticket||'')+'? Ela volta a ficar pendente.')) return;
  if(tk._pagoUndo){
    tk.adiantamento=Number(tk._pagoUndo.adiantamento||0);
    tk.saldoPagar=Number(tk._pagoUndo.saldoPagar||0);
    tk.status=tk._pagoUndo.status||'Pendente';
    delete tk._pagoUndo;
  } else {
    tk.status='Pendente';
    tk.saldoPagar=_r2(Number(tk.totalGeral||0)-Number(tk.adiantamento||0)+Number(tk.saldoAnterior||0));
  }
  
  try{
    var cps=CONTAS_PAGAR.filter(function(c){ return c && c.ticket===tk.ticket; });
    cps.forEach(function(c){
      if(Array.isArray(c.pagamentos)){
        c.pagamentos=c.pagamentos.filter(function(p){ return !(p && Number(p.valor||0)===0 && String(p.obs||'').indexOf('Coberto por adiantamento (Ficha)')>=0); });
      }
      if(c.status==='Pago'){ c.status='Pendente'; c.dataPgto=''; }
      c._upd=Date.now();
    });
    if(cps.length){ saveContasPagar(); try{ renderContasPagar(); }catch(e){} }
  }catch(e){}
  saveDB();
  try{ renderTickets(); renderFluxo(); renderDashboard(); }catch(e){}
  showToast('↩️ Compra '+(tk.ticket||'')+' voltou a pendente.','info');
}
window['desmarcarCompraPaga']=desmarcarCompraPaga;


function getPrecosFornMsg(){
  const cod=document.getElementById('pf-forn-sel')?.value;
  if(!cod) return null;
  const precos=PRECOS_FORN_DATA[cod]||{};
  const forn=FORNECEDORES.find(f=>f.cod===cod);
  const fornNome=forn?forn.nome:cod;
  const fmt=v=>_numFinito(v,0).toLocaleString('pt-BR',{minimumFractionDigits:2});
  const hoje=new Date().toLocaleDateString('pt-BR');
  const div='━━━━━━━━━━━━━━━━━━━━━━━━━';
  const itens=Object.entries(precos).filter(([,v])=>v>0);
  if(itens.length===0){alert('Nenhum preço definido para este fornecedor.');return null;}
  let msg=`🏷️ *TABELA DE PREÇOS DE COMPRA*
`;
  msg+=`${div}
`;
  msg+=`👤 *Fornecedor:* ${fornNome}
`;
  msg+=`📅 *Emitida em:* ${hoje}
`;
  msg+=`${div}
`;
  itens.forEach(([mat,val])=>{
    msg+=`▸ ${mat}: *R$ ${fmt(val)}/kg*
`;
  });
  msg+=`${div}
`;
  msg+=`_Preços sujeitos a alteração sem aviso prévio._`;
  return msg;
}

function compartilharPrecosFornWpp(){
  const msg=getPrecosFornMsg();
  if(!msg) return;
  window.open('https://wa.me/?text='+encodeURIComponent(msg),'_blank');
}

function compartilharPrecosFornNumero(){
  const msg=getPrecosFornMsg();
  if(!msg) return;
  const num=prompt('Número WhatsApp do fornecedor (com DDD, só números):');
  if(!num) return;
  window.open('https://wa.me/55'+num.replace(/\D/g,'')+'?text='+encodeURIComponent(msg),'_blank');
}

async function compartilharImagemPrecosForn(){
  const cod=document.getElementById('pf-forn-sel')?.value;
  if(!cod){alert('Selecione um fornecedor primeiro.');return;}
  const precos=PRECOS_FORN_DATA[cod]||{};
  const itens=Object.entries(precos).filter(([,v])=>v>0);
  if(itens.length===0){alert('Nenhum preço definido para este fornecedor.');return;}
  const forn=FORNECEDORES.find(f=>f.cod===cod);
  const fornNome=forn?forn.nome:cod;
  const fmt=v=>_numFinito(v,0).toLocaleString('pt-BR',{minimumFractionDigits:2});
  const hoje=new Date().toLocaleDateString('pt-BR');

  
  const box=document.getElementById('pf-img-box');
  box.style.display='block';
  box.innerHTML=`
    <div style="margin-bottom:14px;border-bottom:2px solid #1a3a2a;padding-bottom:12px">
      <div style="font-size:16px;font-weight:800;color:#1a3a2a">🏷️ TABELA DE PREÇOS DE COMPRA</div>
      <div style="font-size:12px;color:#444;margin-top:4px">Fornecedor: <b>${fornNome}</b> &nbsp;·&nbsp; Emitida em: ${hoje}</div>
    </div>
    <table style="width:100%;border-collapse:collapse;font-size:13px">
      <thead><tr style="background:#1a3a2a;color:#fff">
        <th style="padding:8px 12px;text-align:left">Material</th>
        <th style="padding:8px 12px;text-align:right">Preço R$/kg</th>
      </tr></thead>
      <tbody>${itens.map(([mat,val],i)=>`
        <tr style="background:${i%2===0?'#f9f9f9':'#fff'}">
          <td style="padding:7px 12px;border-bottom:1px solid #eee">${mat}</td>
          <td style="padding:7px 12px;border-bottom:1px solid #eee;text-align:right;font-weight:700;color:#1a3a2a">R$ ${fmt(val)}/kg</td>
        </tr>`).join('')}
      </tbody>
    </table>
    <div style="margin-top:10px;font-size:11px;color:#888;text-align:center">
      <i>Preços sujeitos a alteração sem aviso prévio.</i>
    </div>`;

  const btn=document.getElementById('pf-img-btn');
  btn.textContent='⏳ Gerando...';
  btn.disabled=true;
  try{
    const canvas=await html2canvas(box,{scale:2,useCORS:true,backgroundColor:'#ffffff',logging:false});
    box.style.display='none';
    canvas.toBlob(async(blob)=>{
      const fileName=`precos-${fornNome.replace(/[^a-zA-Z0-9]/g,'-').toLowerCase()}.png`;
      const file=new File([blob],fileName,{type:'image/png'});
      if(navigator.share&&navigator.canShare&&navigator.canShare({files:[file]})){
        try{await navigator.share({files:[file],title:`Tabela de Preços – ${fornNome}`});}catch(e){}
      } else {
        const url=URL.createObjectURL(blob);
        const a=document.createElement('a');
        a.href=url; a.download=fileName; a.click();
        URL.revokeObjectURL(url);
        alert('✅ Imagem salva! Envie o arquivo via WhatsApp.');
      }
      btn.innerHTML='📷 Imagem WhatsApp';
      btn.disabled=false;
    },'image/png');
  }catch(e){
    box.style.display='none';
    btn.innerHTML='📷 Imagem WhatsApp';
    btn.disabled=false;
    alert('Erro ao gerar imagem: '+e.message);
  }
}

