function calcCheqTotal(){
  const inputs=document.querySelectorAll('#cheq-rows .cheq-val-input');
  let total=0, qtde=0;
  inputs.forEach(inp=>{const v=parseFloat(inp.value)||0; total+=v; qtde++;});
  const bar=document.getElementById('cheq-total-bar');
  const totalRows=document.querySelectorAll('#cheq-rows tr').length;
  if(bar){
    bar.style.display=totalRows>0?'flex':'none';
    bar.style.gap='12px';
    bar.style.flexWrap='wrap';
    const fmt=v=>_numFinito(v,0).toLocaleString('pt-BR',{minimumFractionDigits:2});
    document.getElementById('cheq-total-val').textContent='R$ '+fmt(total);
    document.getElementById('cheq-qtde').textContent=totalRows+' cheque(s)';
  }
}

function salvarCheques(){
  const fornBusca=document.getElementById('cheq-forn-busca');
  const fornCod=document.getElementById('cheq-forn')?.value||'';
  if(!fornCod){
    alert(fornBusca&&fornBusca.value.trim()
      ? 'Fornecedor "'+fornBusca.value.trim()+'" não encontrado — escolha um nome da lista de sugestões.'
      : 'Selecione o fornecedor!');
    return;
  }
  const tipo=document.getElementById('cheq-tipo')?.value||'Emitido (A Pagar)';
  const finalidadePad=document.getElementById('cheq-finalidade')?.value||'Adiantamento';
  const empresaPad=document.getElementById('cheq-empresa')?.value||'';
  const bancoPad=document.getElementById('cheq-banco')?.value.trim()||'';
  const vinculoPad=document.getElementById('cheq-vinculo')?.value.trim()||'';
  const rows=document.querySelectorAll('#cheq-rows tr');
  if(rows.length===0){alert('Adicione ao menos um cheque!');return;}
  let salvos=0;
  if(!CHEQUES_POR_FORN[fornCod]) CHEQUES_POR_FORN[fornCod]=[];
  rows.forEach(tr=>{
    const inputs=tr.querySelectorAll('input');
    const num=inputs[0]?.value.trim();
    const valor=parseFloat(inputs[1]?.value)||0;
    const bomPara=inputs[2]?.value;
    
    const bancoEl=tr.querySelectorAll('select')[0]||tr.querySelectorAll('input')[3];
    const banco=(bancoEl?.value||'').trim()||bancoPad;
    const vinculoInp=Array.from(tr.querySelectorAll('input')).find(el=>el.placeholder&&el.placeholder.includes('nculo'));
    const vinculo=(vinculoInp?.value||'').trim()||vinculoPad;
    if(!num||valor<=0) return; 
    const bomFmt=bomPara?bomPara.split('-').reverse().join('/'):'';
    const cid='CHQ'+String(Date.now()).slice(-8)+salvos;
    
    const statusImport=tr.dataset.statusImport||'Pendente';
    const statusFinal=statusImport==='Compensado'?'Compensado':'Pendente';
    const dataComp=statusFinal==='Compensado'?bomFmt:'';
    CHEQUES_POR_FORN[fornCod].push({id:cid,num,banco,tipo,finalidade:finalidadePad,empresa:empresaPad,valor,bomPara:bomFmt,vinculo,status:statusFinal,dataCompensacao:dataComp,statusDesc:'Descontado'});
    salvos++;
  });
  if(salvos===0){alert('Nenhum cheque valido (verifique numero, valor e Bom Para)!');return;}
  saveDB();
  renderCheques();
  try{renderAdiantamentos();}catch(e){}
  try{renderFluxo();}catch(e){}
  try{renderDashboard();}catch(e){}
  cm();
  const pagosCount=Array.from(document.querySelectorAll('#cheq-rows tr')).filter(r=>r.dataset.statusImport==='Compensado').length;
  showToast(salvos+' cheque(s) salvos com sucesso!'+(pagosCount?' ('+pagosCount+' ja compensados)':''),'success');
}


function _addCheqCliRowEl(num, valor, bomParaISO, banco, vinculo, idx, statusImport, emitente){
  const tbody=document.getElementById('cheqcli-rows'); if(!tbody) return;
  const id='ccr'+Date.now()+idx;
  const isPago=statusImport==='Compensado';
  const rowBg=isPago?'#f0fff4':idx%2===0?'#fff':'#f9fbfa';
  const statusLabel=isPago?'<span style="background:#27ae60;color:#fff;border-radius:4px;padding:1px 5px;font-size:.7rem;font-weight:700">PAGO</span>':'';
  const tr=document.createElement('tr'); tr.id=id; tr.style.background=rowBg;
  if(isPago) tr.dataset.statusImport='Compensado';
  tr.innerHTML=`
    <td style="padding:3px 4px"><input value="${String(num||'').trim()}" placeholder="000001" style="width:80px;padding:4px 6px;border:1px solid #ccc;border-radius:4px;font-size:.8rem" oninput="calcCheqCliTotal()"></td>
    <td style="padding:3px 4px"><input type="number" min="0" step="0.01" value="${(valor!==''&&valor!=null)?Number(valor):''}" placeholder="0,00" style="width:90px;padding:4px 6px;border:1px solid #ccc;border-radius:4px;font-size:.8rem" class="cheqcli-val-input" oninput="calcCheqCliTotal()"></td>
    <td style="padding:3px 4px"><input type="date" value="${bomParaISO||''}" style="padding:4px 6px;border:1px solid #ccc;border-radius:4px;font-size:.8rem" oninput="calcCheqCliTotal()"></td>
    <td style="padding:3px 4px"><input value="${String(banco||'').trim()}" placeholder="banco" style="width:110px;padding:4px 6px;border:1px solid #ccc;border-radius:4px;font-size:.8rem"></td>
    <td style="padding:3px 4px"><input value="${String(vinculo||'').trim()}" placeholder="vínculo" style="width:90px;padding:4px 6px;border:1px solid #ccc;border-radius:4px;font-size:.8rem"></td>
    <td style="padding:3px 4px"><input value="${String(emitente||'').trim()}" placeholder="nome no cheque" style="width:130px;padding:4px 6px;border:1px solid #ccc;border-radius:4px;font-size:.8rem"></td>
    <td style="padding:3px 4px;text-align:center">${statusLabel}<button onclick="document.getElementById('${id}').remove();calcCheqCliTotal()" style="background:#e74c3c;color:#fff;border:none;border-radius:4px;padding:2px 7px;cursor:pointer;font-size:.8rem;margin-left:2px">✕</button></td>
  `;
  tbody.appendChild(tr);
}

function addCheqCliRow(){ _addCheqCliRowEl('', '', '', '', '', document.querySelectorAll('#cheqcli-rows tr').length); calcCheqCliTotal(); }

function limparChequesCli(){
  const tbody=document.getElementById('cheqcli-rows'); if(tbody) tbody.innerHTML='';
  const lbl=document.getElementById('cheqcli-count-lbl'); if(lbl) lbl.textContent='';
  calcCheqCliTotal();
}

function calcCheqCliTotal(){
  const inputs=document.querySelectorAll('#cheqcli-rows .cheqcli-val-input');
  let total=0; inputs.forEach(inp=>{ total+=parseFloat(inp.value)||0; });
  const bar=document.getElementById('cheqcli-total-bar');
  const totalRows=document.querySelectorAll('#cheqcli-rows tr').length;
  if(bar){
    bar.style.display=totalRows>0?'flex':'none'; bar.style.gap='12px'; bar.style.flexWrap='wrap';
    const fmt=v=>_numFinito(v,0).toLocaleString('pt-BR',{minimumFractionDigits:2});
    const tv=document.getElementById('cheqcli-total-val'); if(tv) tv.textContent='R$ '+fmt(total);
    const tq=document.getElementById('cheqcli-qtde'); if(tq) tq.textContent=totalRows+' cheque(s)';
  }
}

function gerarSerieChequesCli(){
  const inicio=parseInt(document.getElementById('qscli-inicio')?.value)||0;
  const qtde=parseInt(document.getElementById('qscli-qtde')?.value)||0;
  const valorUnit=parseFloat(document.getElementById('qscli-valor')?.value)||0;
  const bomBase=document.getElementById('qscli-bomPara')?.value||'';
  const intervalo=parseInt(document.getElementById('qscli-intervalo')?.value)||0;
  if(inicio<1){alert('Informe o número inicial do cheque!');return;}
  if(qtde<1||qtde>200){alert('Quantidade deve ser entre 1 e 200!');return;}
  const tbody=document.getElementById('cheqcli-rows'); if(!tbody) return;
  tbody.innerHTML='';
  for(let i=0;i<qtde;i++){
    const num=String(inicio+i).padStart(String(inicio).length,0);
    let dataFmt='';
    if(bomBase){ const dt=new Date(bomBase+'T00:00:00'); dt.setDate(dt.getDate()+(i*intervalo)); dataFmt=dt.toISOString().slice(0,10); }
    _addCheqCliRowEl(num, valorUnit||'', dataFmt, '', '', i);
  }
  calcCheqCliTotal();
  const lbl=document.getElementById('cheqcli-count-lbl'); if(lbl) lbl.textContent='('+qtde+' cheques: '+inicio+' → '+(inicio+qtde-1)+')';
  try{showToast('Série gerada: cheques '+inicio+' a '+(inicio+qtde-1),'success');}catch(e){}
}

function importarPlanilhaChequesCli(input){
  const file=input.files[0]; if(!file) return;
  const log=document.getElementById('cheqcli-import-log');
  if(log){ log.style.display='block'; log.textContent='Carregando...'; }
  _loadSheetJS(()=>{
    const reader=new FileReader();
    reader.onload=e=>{
      try{
        const wb=XLSX.read(e.target.result,{type:'array',cellDates:false});
        const ws=wb.Sheets[wb.SheetNames[0]];
        const aoa=XLSX.utils.sheet_to_json(ws,{header:1,defval:''});
        if(!aoa.length){ if(log) log.textContent='Planilha vazia.'; return; }
        const norm=s=>String(s).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/[^a-z0-9]/g,'');
        let headerRowIdx=0;
        for(let i=0;i<Math.min(5,aoa.length);i++){ if(aoa[i].some(c=>norm(c).includes('cheque'))){ headerRowIdx=i; break; } }
        const headers=aoa[headerRowIdx];
        const colIdx={num:-1,banco:-1,valor:-1,bompara:-1,situacao:-1,vinculo:-1};
        headers.forEach((h,i)=>{ const n=norm(h);
          if(n.match(/^n.*cheque$/)||n.includes('ncheque')||n.includes('ndocheque')) colIdx.num=i;
          else if(n.includes('banco')) colIdx.banco=i;
          else if(n.includes('bompar')||n.includes('vencimento')||n.includes('compensado')) colIdx.bompara=i;
          else if(n==='valor'||n.includes('vlr')||n.includes('valor')) colIdx.valor=i;
          else if(n.includes('cliente')||n.includes('vinculo')||n.includes('venda')||n.includes('destino')) colIdx.vinculo=i;
          else if(n.includes('situac')||n.includes('status')) colIdx.situacao=i;
        });
        const dataRows=aoa.slice(headerRowIdx+1);
        const tbody=document.getElementById('cheqcli-rows'); if(tbody) tbody.innerHTML='';
        let importados=0, ignorados=0, pagos=0;
        dataRows.forEach((row,i)=>{
          const num=colIdx.num>=0?String(row[colIdx.num]||'').trim():'';
          const valor=_parseValorCheque(colIdx.valor>=0?row[colIdx.valor]:'');
          const bomPara=_parseDateCheque(colIdx.bompara>=0?row[colIdx.bompara]:'');
          const banco=colIdx.banco>=0?String(row[colIdx.banco]||'').trim():'';
          const vinculo=colIdx.vinculo>=0?String(row[colIdx.vinculo]||'').trim():'';
          const situacao=colIdx.situacao>=0?String(row[colIdx.situacao]||'').trim():'';
          if(!num&&valor<=0){ ignorados++; return; }
          const isPago=['pago','compensado','baixado','quitado'].includes(situacao.toLowerCase());
          if(isPago) pagos++;
          _addCheqCliRowEl(num, valor, bomPara, banco, vinculo, i, isPago?'Compensado':'Pendente');
          importados++;
        });
        calcCheqCliTotal();
        const lbl=document.getElementById('cheqcli-count-lbl'); if(lbl) lbl.textContent='('+importados+' importados)';
        if(log) log.innerHTML='<b style="color:#27ae60">'+importados+' cheque(s) importados</b>'+(pagos?' &middot; '+pagos+' compensados':'')+(ignorados?' &middot; '+ignorados+' ignoradas':'');
        try{showToast('Planilha importada: '+importados+' cheques','success');}catch(e){}
      }catch(err){ if(log) log.textContent='Erro ao processar: '+err.message; console.error(err); }
    };
    reader.readAsArrayBuffer(file); input.value='';
  });
}

function downloadTemplateChequesCli(){
  _loadSheetJS(()=>{
    const titulo=['Cheques de Clientes','','','','','',''];
    const headers=['N do Cheque','Banco','Data','Cliente','Valor','Bom Para','Situacao'];
    const primeiroBanco=(Array.isArray(BANCOS_DB)&&BANCOS_DB[0])?String(BANCOS_DB[0].banco||''):'';
    const hoje=new Date().toLocaleDateString('pt-BR');
    const exemplos=primeiroBanco?[[1,primeiroBanco,hoje,'Cliente',0,'','PENDENTE']]:[];
    const ws=XLSX.utils.aoa_to_sheet([titulo,headers,...exemplos]);
    ws['!merges']=[{s:{r:0,c:0},e:{r:0,c:6}}];
    ws['!cols']=[{wch:14},{wch:18},{wch:14},{wch:20},{wch:14},{wch:14},{wch:20}];
    const wb=XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb,'Cheques Clientes',ws);
    XLSX.writeFile(wb,'cheques_clientes.xlsx');
    try{showToast('Template baixado: cheques_clientes.xlsx','success');}catch(e){}
  });
}

function salvarChequesCli(){
  const cliSel=document.getElementById('cheqcli-cli');
  const cliNome=cliSel?cliSel.value:'';
  if(!cliNome){alert('Selecione o cliente!');return;}
  const tipoPad=document.getElementById('cheqcli-tipo')?.value||'Adiantamento';
  const bancoPad=(document.getElementById('cheqcli-banco')?.value||'').trim();
  const vinculoPad=(document.getElementById('cheqcli-vinculo')?.value||'').trim();
  const rows=document.querySelectorAll('#cheqcli-rows tr');
  if(rows.length===0){alert('Adicione ao menos um cheque!');return;}
  if(!CHEQUES_CLI[cliNome]) CHEQUES_CLI[cliNome]=[];
  let salvos=0;
  rows.forEach(tr=>{
    const inputs=tr.querySelectorAll('input');
    const num=(inputs[0]?.value||'').trim();
    const valor=parseFloat(inputs[1]?.value)||0;
    const bomParaISO=inputs[2]?.value||'';
    const banco=((inputs[3]?.value||'').trim())||bancoPad;
    const vinculo=((inputs[4]?.value||'').trim())||vinculoPad;
    const emitente=(inputs[5]?.value||'').trim();
    if(!num||valor<=0) return; 
    const bomFmt=bomParaISO?bomParaISO.split('-').reverse().join('/'):'';
    const statusImport=tr.dataset.statusImport==='Compensado'?'Compensado':'Pendente';
    CHEQUES_CLI[cliNome].push({ num, data:'', bomPara:bomFmt, valor, banco, tipo:tipoPad, vinculo, emitente, obs:'', status:statusImport, motivoDevolucao:'' });
    salvos++;
  });
  if(salvos===0){alert('Nenhum cheque válido (informe número e valor)!');return;}
  saveChequesCli();
  try{renderChequesCli();}catch(e){}
  try{renderAdtCli();}catch(e){}
  try{renderFluxo();}catch(e){}
  try{renderDashboard();}catch(e){}
  cm();
  try{showToast(salvos+' cheque(s) de '+cliNome+' salvos!','success');}catch(e){}
}


function salvarCheque(){
  const num=document.getElementById('cheq-num')?.value.trim();
  const banco=document.getElementById('cheq-banco')?.value.trim();
  const tipo=document.getElementById('cheq-tipo')?.value;
  const finalidade=document.getElementById('cheq-finalidade')?.value||'Adiantamento';
  const fornSel=document.getElementById('cheq-forn');
  const valor=parseFloat(document.getElementById('cheq-valor')?.value)||0;
  const bomPara=document.getElementById('cheq-bomPara')?.value;
  const vinculo=document.getElementById('cheq-vinculo')?.value.trim()||'';
  if(!num||!fornSel||valor<=0){alert('Preencha número, fornecedor e valor!');return;}
  const fornCod=fornSel.options[fornSel.selectedIndex]?.value;
  const bomFmt=bomPara?bomPara.split('-').reverse().join('/'):'';
  if(!CHEQUES_POR_FORN[fornCod]) CHEQUES_POR_FORN[fornCod]=[];
  const cid2='CHQ'+String(Date.now()).slice(-8);
  CHEQUES_POR_FORN[fornCod].push({id:cid2,num,banco,tipo,finalidade,valor,bomPara:bomFmt,vinculo,status:'Pendente',dataCompensacao:'',statusDesc:'Descontado'});
  saveDB();
  {
    const _forn=FORNECEDORES.find(f=>f.cod===fornCod);
    registrarHistorico('Cheque','Criado',
      (_forn?_forn.nome:fornCod)+' — cheque nº '+num+' — R$ '+Number(valor).toLocaleString('pt-BR',{minimumFractionDigits:2})+(finalidade?' — '+finalidade:''),
      null, {fornCod, id:cid2});
  }
  renderCheques();
  cm();
  alert('✅ Cheque salvo!');
}




