BAL_FORN_OPTS = '<option value="">— Selecione o Fornecedor —</option>'+FORNECEDORES.slice().sort((a,b)=>(a.nome||'').localeCompare(b.nome||'','pt-BR')).map(f=>`<option value="${f.nome}">${f.nome}</option>`).join('');
let compraRowId=0, vendaRowId=0;


