const IDENT_OPTS = IDENT.map(i=>`<option>${i}</option>`).join('');










const IDENT_SEPARA_ESTOQUE = new Set(['304','316','410','430','201','310']);




function _matEfetivoEstoque(mat, ident){
  const id=(ident||'').trim().toUpperCase();
  const m=(mat||'').trim();
  if(!m||!id||!IDENT_SEPARA_ESTOQUE.has(id)) return m;
  
  if(m.toUpperCase().endsWith(' '+id)) return m;
  return m+' '+id;
}




function _garantirMetalCadastrado(nome){
  if(!nome) return;
  
  
  if(/[.#$\/\[\]]/.test(nome) || String(nome).length>60) return;
  
  
  if(/nf\s*:/i.test(nome) || /\d\s*,/.test(nome)) return;
  if(typeof METAIS==='undefined') return;
  if(!METAIS.includes(nome)){
    METAIS.push(nome);
    METAIS.sort((a,b)=>a.localeCompare(b,'pt-BR'));
  }
  if(typeof ESTOQUE_DB!=='undefined' && !ESTOQUE_DB[nome]){
    ESTOQUE_DB[nome]={mat:nome,inicial:0,entradas:0,saidas:0,precoVenda:0,obs:''};
  }
}



function _r2(x){ var n=Number(x); if(!isFinite(n)) return 0; return Math.round((n+Number.EPSILON)*100)/100; }
window['_r2']=_r2;
function _arredondarDinheiro2Casas(){
  try{
    var mud=false;
    if(typeof TICKETS_DB!=='undefined'){
      Object.keys(TICKETS_DB).forEach(function(k){
        var t=TICKETS_DB[k]; if(!t) return;
        (t.itens||[]).forEach(function(it){ if(it && it.total!=null){ var r=_r2(it.total); if(r!==it.total){ it.total=r; mud=true; } } });
        ['totalGeral','saldoPagar','adiantamento','saldoAnterior','acrescimo','valorExtra','totalKg'].forEach(function(c){
          if(t[c]!=null && typeof t[c]==='number'){ var r=_r2(t[c]); if(r!==t[c]){ t[c]=r; mud=true; } }
        });
      });
    }
    if(typeof ADT_POR_FORN!=='undefined'){
      Object.keys(ADT_POR_FORN).forEach(function(cod){
        var lst=ADT_POR_FORN[cod]; if(!Array.isArray(lst)) return;
        lst.forEach(function(a){ if(a && a.valor!=null){ var r=_r2(a.valor); if(r!==a.valor){ a.valor=r; mud=true; } } });
      });
    }
    if(mud){ try{ if(typeof saveDB==='function') saveDB(); else if(typeof fbSalvar==='function') fbSalvar(); }catch(e){} }
  }catch(e){ console.warn('arredondar 2 casas:', e&&e.message); }
}
window['_arredondarDinheiro2Casas']=_arredondarDinheiro2Casas;
function _limparMateriaisInvalidos(){
  try{
    var inval=function(n){ return !n || /[.#$\/\[\]]/.test(n) || String(n).length>60 || /nf\s*:/i.test(n) || /\d\s*,/.test(n); };
    var removidos=false;
    if(typeof ESTOQUE_DB!=='undefined'){
      Object.keys(ESTOQUE_DB).forEach(function(k){ if(inval(k)){ delete ESTOQUE_DB[k]; removidos=true; } });
    }
    if(typeof METAIS!=='undefined' && Array.isArray(METAIS)){
      for(var i=METAIS.length-1;i>=0;i--){ if(inval(METAIS[i])){ METAIS.splice(i,1); removidos=true; } }
    }
    if(removidos){
      try{ localStorage.setItem('mm_estoque', JSON.stringify(ESTOQUE_DB)); }catch(e){}
      try{ localStorage.setItem('mm_metais', JSON.stringify(METAIS)); }catch(e){}
    }
    if(window._fbDB && !window._estqLimpoNuvem){
      window._estqLimpoNuvem=true;
      window._fbDB.ref('erp/estoque').once('value').then(function(s){
        var v=s.val()||{}; var limpo={}; var mudou=false;
        Object.keys(v).forEach(function(k){ if(inval(k)){ mudou=true; } else { limpo[k]=v[k]; } });
        if(mudou) return window._fbDB.ref('erp/estoque').set(limpo);
      }).catch(function(){});
      
      
      window._fbDB.ref('erp/metais').once('value').then(function(s){
        var v=s.val(); var arr=Array.isArray(v)?v:Object.values(v||{});
        var limpo=arr.filter(function(k){ return !inval(k); });
        if(limpo.length!==arr.length) return window._fbDB.ref('erp/metais').set(limpo);
      }).catch(function(){});
    }
  }catch(e){}
}
window['_limparMateriaisInvalidos']=_limparMateriaisInvalidos;


function getNextTicketId(){
  try{
    
    
    
    
    
    
    
    
    const usados=new Set(Object.keys(TICKETS_DB));
    try{ if(typeof TICKETS_DELETED!=='undefined') TICKETS_DELETED.forEach(t=>usados.add(String(t))); }catch(e){}
    let max=0;
    usados.forEach(k=>{const m=String(k).match(/(\d+)$/);if(m){const n=parseInt(m[1]);if(n>max)max=n;}});
    let hw=0; try{ hw=parseInt(localStorage.getItem('mm_ticket_hw')||'0')||0; }catch(e){}
    let nxt=Math.max(max,hw)+1;
    while(usados.has('T'+String(nxt).padStart(3,'0'))) nxt++;
    try{ localStorage.setItem('mm_ticket_hw', String(nxt)); }catch(e){}
    return 'T'+String(nxt).padStart(3,'0');
  }catch(e){ return 'T'+Date.now().toString().slice(-4); }
}


function importarRomaneioPDF(input){
  const file = input.files[0];
  if(!file) return;
  const status = document.getElementById('pdf-import-status');
  if(status) status.textContent = '⏳ Lendo PDF...';

  const reader = new FileReader();
  reader.onload = async function(e){
    try{
      
      if(typeof pdfjsLib === 'undefined'){
        showToast('PDF.js não carregou. Verifique sua conexão.','error',6000);
        return;
      }
      pdfjsLib.GlobalWorkerOptions.workerSrc =
        'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';

      const pdfData = new Uint8Array(e.target.result);
      const pdf = await pdfjsLib.getDocument({data: pdfData}).promise;

      
      let fullText = '';
      for(let i=1; i<=pdf.numPages; i++){
        const page = await pdf.getPage(i);
        const content = await page.getTextContent();
        fullText += content.items.map(it=>it.str).join(' ') + '\n';
      }

      
      const get = (pattern, flags='i') => {
        const m = fullText.match(new RegExp(pattern, flags));
        return m ? m[1].trim() : '';
      };

      
      const ticket = get('TICKET\\s+(\\d+)') || get('(\\d{3,6})\\s+$','im') || '';

      
      const pesoBrutoStr  = get('Peso\\s+Bruto[:\\s]+([\\d.,]+)');
      const pesoTaraStr   = get('Peso\\s+Tara[:\\s]+([\\d.,]+)');
      const pesoLiqStr    = get('TOTAL\\s+PESO\\s+LIQUIDO\\s*[:\\s]+([\\d.,]+)')
                         || get('Peso\\s+Balan[cç]a[:\\s]+([\\d.,]+)');

      const parsePeso = s => parseFloat(s.replace(/\./g,'').replace(',','.')) || 0;
      const pesoBruto = parsePeso(pesoBrutoStr);
      const pesoTara  = parsePeso(pesoTaraStr);
      const pesoLiq   = parsePeso(pesoLiqStr) || (pesoBruto - pesoTara);

      
      const produto = get('PRODUTO[:\\s]+[\\d]+\\s*[-–]?\\s*([\\w\\s]+?)(?:\\s{2,}|EXPEDI|$)');

      
      const clienteRaw = get('CLIENTE[:\\s]+([^\\n]{3,60})');
      
      const cliMatch = clienteRaw.match(/^(\d+)\s*[-–]\s*(.+?)(?:\s*[-–]\s*[\d./-]{5,})?$/);
      const cliCod  = cliMatch ? cliMatch[1].trim() : '';
      const cliNome = cliMatch ? cliMatch[2].trim().toUpperCase() : clienteRaw.toUpperCase();

      
      const placa     = get('PLACA[:\\s]+([A-Z0-9]{6,8})');
      const motorista = get('MOTORISTA[:\\s]+([^\\n]{3,40})');

      
      let msgs = [];

      if(ticket){
        const el=document.getElementById('c-ticket');
        if(el) el.value=ticket;
        msgs.push('Ticket: '+ticket);
      }
      
      if(pesoLiq > 0){
        const elRod=document.getElementById('c-peso-rod');
        if(elRod){ elRod.value=pesoLiq; }
      }

      if(motorista){
        const el=document.getElementById('c-resp');
        if(el) el.value=motorista;
      }

      
      let fornFound = false;
      if(cliCod || cliNome){
        const sel = document.getElementById('c-forn');
        if(sel){
          for(let opt of sel.options){
            const txt = opt.text.toUpperCase();
            const val = opt.value || '';
            if((cliCod && val === cliCod) ||
               (cliNome && txt.includes(cliNome.substring(0,10)))){
              sel.value = opt.value;
              const _bi=document.getElementById('c-forn-busca'); if(_bi) _bi.value=opt.text;
              fornFound = true;
              try{ onFornChange(); }catch(ee){}
              msgs.push('Fornecedor: '+opt.text.substring(0,30));
              break;
            }
          }
          if(!fornFound) msgs.push('⚠️ Fornecedor não encontrado: '+clienteRaw.substring(0,25));
        }
      }

      
      if(pesoBruto > 0){
        const elBr = document.getElementById('cbr-1');
        if(elBr){ elBr.value=pesoBruto; }
        msgs.push('Peso Bruto: '+pesoBruto+' kg');
      }
      if(pesoLiq > 0){
        const elLq = document.getElementById('clq-1');
        if(elLq){ elLq.value=pesoLiq; }
        msgs.push('Peso Líq: '+pesoLiq+' kg');
      }

      
      if(produto){
        const elMat = document.getElementById('cmat-1');
        if(elMat){
          const prodUp = produto.toUpperCase();
          const match = METAIS.find(m=>prodUp.includes(m.toUpperCase())||m.toUpperCase().includes(prodUp));
          if(match){ elMat.value=match; try{onMaterialChange(1);}catch(ee){} msgs.push('Material: '+match); }
          else{ elMat.value=produto; msgs.push('Material (manual): '+produto); }
        }
      }

      try{ calcCompra(); }catch(ee){}

      if(status) status.textContent = '✅ Importado! ' + msgs.join(' | ');
      showToast('✅ Romaneio importado com sucesso!','success',5000);

    }catch(err){
      console.error('Erro PDF:', err);
      if(status) status.textContent = '❌ Erro ao ler PDF: '+err.message;
      showToast('Erro ao ler PDF: '+err.message,'error',7000);
    }
  };
  reader.readAsArrayBuffer(file);
}

















function _agruparItensPorLinha(items){
  const porY = {};
  items.forEach(function(it){
    const txt = (it.str||'').trim();
    if(!txt) return;
    const y = Math.round(it.transform[5]);
    const x = it.transform[4];
    if(!porY[y]) porY[y] = [];
    porY[y].push({str:txt, x:x});
  });
  const ys = Object.keys(porY).map(Number).sort(function(a,b){ return b-a; }); 
  return ys.map(function(y){
    const linha = porY[y].sort(function(a,b){ return a.x-b.x; });
    return {y:y, itens:linha};
  });
}

function _colunaPorBordaEsquerda(x, bordas){
  const TOL = 3;
  let melhor=null, melhorX=-1e9;
  Object.keys(bordas).forEach(function(nome){
    const bx = bordas[nome];
    if(bx===null || bx===undefined) return;
    if(bx - TOL <= x && bx > melhorX){ melhor=nome; melhorX=bx; }
  });
  return melhor;
}

function _parseCartaoPontoPagina(linhas, textoCompleto){
  
  
  
  
  
  
  
  
  
  
  
  
  function campoPorRotulo(rotuloExato){
    for(let i=0;i<linhas.length;i++){
      const itens = linhas[i].itens;
      const idx = itens.findIndex(function(it){ return it.str.trim()===rotuloExato; });
      if(idx<0) continue;
      const partes=[];
      for(let k=idx+1;k<itens.length;k++){
        if(/:$/.test(itens[k].str.trim())) break;
        partes.push(itens[k].str);
      }
      return partes.join(' ').trim();
    }
    return null;
  }
  const nome = campoPorRotulo('NOME DO FUNCIONÁRIO:');
  const cpf = campoPorRotulo('CPF DO FUNCIONÁRIO:');
  const pis = campoPorRotulo('PIS DO FUNCIONÁRIO:');
  const cargo = campoPorRotulo('NOME DO CARGO:');
  const mPeriodo = textoCompleto.match(/DE (\d{2}\/\d{2}\/\d{4}) ATÉ (\d{2}\/\d{2}\/\d{4})/);
  const periodoInicio = mPeriodo ? mPeriodo[1] : null;
  const periodoFim = mPeriodo ? mPeriodo[2] : null;

  let idxHeader = -1;
  for(let i=0;i<linhas.length;i++){
    const txts = linhas[i].itens.map(function(it){ return it.str; });
    if(txts.indexOf('DIA')>=0 && (txts.indexOf('PREVISTO')>=0 || txts.indexOf('TRABALHADO')>=0 || txts.some(function(t){return /^ENT\.\s*1$/.test(t);}))){ idxHeader=i; break; }
  }
  if(idxHeader<0) return {nome:nome, cpf:cpf, pis:pis, cargo:cargo, periodoInicio:periodoInicio, periodoFim:periodoFim, erro:'cabecalho_nao_encontrado', dias:[], extraColunas:{}};

  const headerItens = linhas[idxHeader].itens;
  function bordaDe(regex){
    const it = headerItens.find(function(x){ return regex.test(x.str); });
    return it ? it.x : null;
  }
  const bordas = {
    dia: bordaDe(/^DIA$/),
    previsto: bordaDe(/^PREVISTO$/),
    ent1: bordaDe(/^ENT\.\s*1$/),
    sai1: bordaDe(/^SAÍ\.\s*1$/),
    ent2: bordaDe(/^ENT\.\s*2$/),
    sai2: bordaDe(/^SAÍ\.\s*2$/),
    ent3: bordaDe(/^ENT\.\s*3$/),
    sai3: bordaDe(/^SAÍ\.\s*3$/),
    total: bordaDe(/^TRABALHADO$/),
    faltaAtraso: bordaDe(/^ATRASO$/)
  };
  const extraColunas = {};
  headerItens.forEach(function(it){
    const m = it.str.match(/^(\d{1,3})%([DN])$/);
    if(m){
      const chave = 'extra_'+m[1]+'_'+m[2];
      bordas[chave] = it.x;
      extraColunas[chave] = {pct:m[1], periodo:m[2]};
    }
  });

  const dias = [];
  const alteracoes = [];
  let modoAlteracoes = false;
  for(let i=idxHeader+1;i<linhas.length;i++){
    const itens = linhas[i].itens;
    if(!itens.length) continue;
    const primeiro = itens[0].str;
    if(primeiro==='TOTAIS') continue; 
    if(primeiro.indexOf('Alterações')===0){ modoAlteracoes=true; continue; }
    if(modoAlteracoes){ alteracoes.push(itens.map(function(x){return x.str;}).join(' ')); continue; }
    const mData = primeiro.match(/^(\d{2}\/\d{2}\/\d{4})\s*-\s*([A-ZÇÃÁ]{3})$/);
    if(!mData) continue; 

    const cols = {};
    for(let k=1;k<itens.length;k++){
      const col = _colunaPorBordaEsquerda(itens[k].x, bordas);
      if(!col) continue;
      if(!cols[col]) cols[col]=[];
      cols[col].push(itens[k].str);
    }
    function j(col){ return (cols[col]||[]).join(' ').trim(); }

    const extras = {};
    Object.keys(extraColunas).forEach(function(chave){
      const v = j(chave);
      if(v) extras[chave] = {pct:extraColunas[chave].pct, periodo:extraColunas[chave].periodo, valor:v};
    });

    dias.push({
      data: mData[1], diaSemana: mData[2],
      previsto: j('previsto'),
      ent1: j('ent1'), sai1: j('sai1'),
      ent2: j('ent2'), sai2: j('sai2'),
      ent3: j('ent3'), sai3: j('sai3'),
      total: j('total'), faltaAtraso: j('faltaAtraso'),
      extras: extras
    });
  }

  return {nome:nome, cpf:cpf, pis:pis, cargo:cargo, periodoInicio:periodoInicio, periodoFim:periodoFim, extraColunas:extraColunas, dias:dias, alteracoes:alteracoes};
}

async function _lerCartaoPontoRHiD(pdfData){
  if(typeof pdfjsLib === 'undefined') throw new Error('PDF.js não carregou. Verifique sua conexão.');
  pdfjsLib.GlobalWorkerOptions.workerSrc =
    'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';
  const pdf = await pdfjsLib.getDocument({data: pdfData}).promise;
  const paginas = [];
  for(let i=1;i<=pdf.numPages;i++){
    const page = await pdf.getPage(i);
    const content = await page.getTextContent();
    const linhas = _agruparItensPorLinha(content.items);
    const textoCompleto = linhas.map(function(l){ return l.itens.map(function(it){return it.str;}).join(' '); }).join('\n');
    paginas.push(_parseCartaoPontoPagina(linhas, textoCompleto));
  }
  return paginas;
}

function _cpfSoDigitos(s){ return (s||'').replace(/\D/g,''); }

function importarCartaoPontoRHiD(input){
  const file = input.files[0];
  if(!file) return;
  const status = document.getElementById('ponto-import-status');
  if(status) status.textContent = '⏳ Lendo PDF...';

  const reader = new FileReader();
  reader.onload = async function(e){
    try{
      const paginas = await _lerCartaoPontoRHiD(new Uint8Array(e.target.result));

      const naoEncontrados = [];
      let funcImportados = 0, diasImportados = 0;
      const agora = new Date().toLocaleString('pt-BR');

      paginas.forEach(function(pag){
        if(pag.erro || !pag.dias.length) return;
        const cpfDigitos = _cpfSoDigitos(pag.cpf).slice(0,11);
        const func = FUNCIONARIOS.find(function(f){ return _cpfSoDigitos(f.cpf) === cpfDigitos && cpfDigitos; });
        if(!func){
          naoEncontrados.push((pag.nome||'?')+' (CPF '+(pag.cpf||'?')+')');
          return;
        }
        
        
        
        for(let i=PONTO_BATIDAS_DB.length-1;i>=0;i--){
          const r = PONTO_BATIDAS_DB[i];
          if(r && r.mat===func.mat && pag.dias.some(function(d){ return d.data===r.data; })){
            _syncPontoBatidas.remover(i);
          }
        }
        pag.dias.forEach(function(d){
          PONTO_BATIDAS_DB.push(Object.assign({mat:func.mat, origem:'rhid',
            periodoInicio:pag.periodoInicio, periodoFim:pag.periodoFim, importadoEm:agora}, d));
          diasImportados++;
        });
        funcImportados++;
      });

      saveDB();
      try{ renderPontoTab(); }catch(ee){}
      try{ _popularSelectPontoFuncionarios(); }catch(ee){}

      const nadaLido = (funcImportados===0 && diasImportados===0);
      let msg;
      if(nadaLido && !naoEncontrados.length){
        msg = '⚠️ Não consegui ler nenhum dia deste PDF.\n\nConfira se é mesmo o "Cartão de Ponto" exportado do RH iD em PDF (não uma foto/print). Se for e mesmo assim não ler, me avise.';
      } else {
        msg = '✅ '+funcImportados+' funcionário(s), '+diasImportados+' dia(s) importado(s) do RH iD.';
        if(naoEncontrados.length){
          msg += '\n\n⚠️ '+naoEncontrados.length+' funcionário(s) do RH iD NÃO encontrado(s) no cadastro (CPF não bate com nenhum funcionário) — não foram importados:\n• '+naoEncontrados.join('\n• ');
        }
      }
      if(status) status.textContent = nadaLido ? '⚠️ Nada foi lido do PDF — confira o arquivo.' : (naoEncontrados.length ? '⚠️ Importado com pendências — veja o aviso.' : '✅ Importado com sucesso!');
      alert(msg);
      showToast(nadaLido ? '⚠️ Nada foi importado — confira o PDF' : (naoEncontrados.length ? '⚠️ Importado com '+naoEncontrados.length+' pendência(s)' : '✅ Cartão de ponto importado!'), nadaLido?'warn':(naoEncontrados.length?'warn':'success'), 6000);
    }catch(err){
      console.error('Erro ao importar cartão de ponto:', err);
      if(status) status.textContent = '❌ Erro: '+err.message;
      showToast('Erro ao importar PDF do RH iD: '+err.message, 'error', 7000);
    }
  };
  reader.readAsArrayBuffer(file);
}

function verificarPesos(){
  const rodVal = parseFloat(document.getElementById('c-peso-rod')?.value) || 0;
  const div = document.getElementById('c-verif-pesos');
  if(!div) return;
  if(rodVal <= 0){ div.innerHTML='<span style="color:#888;font-size:.8rem">Informe o peso da rodoviária para iniciar a conferência.</span>'; return; }

  
  let rows = [];
  let somaLiq = 0;
  for(let i=1; i<=compraRowId; i++){
    const br = parseFloat(document.getElementById('cbr-'+i)?.value)||0;
    const lq = parseFloat(document.getElementById('clq-'+i)?.value)||0;
    const mat = document.getElementById('cmat-'+i)?.value||'Item '+i;
    const peso = lq > 0 ? lq : br;
    if(peso > 0){
      somaLiq += peso;
      const restante = rodVal - somaLiq;
      const pct = Math.min(100,(somaLiq/rodVal*100));
      rows.push({mat, peso, acumulado: somaLiq, restante, pct});
    }
  }

  const restFinal = rodVal - somaLiq;
  const pctFinal = Math.min(100, somaLiq/rodVal*100);
  const zerou = Math.abs(restFinal) <= rodVal*0.02;
  const excedeu = restFinal < -(rodVal*0.02);

  
  const barColor = zerou ? '#2e7d32' : excedeu ? '#c62828' : '#1565c0';
  const barHTML = `<div style="background:#cfd8dc;border-radius:20px;height:12px;margin-bottom:8px;overflow:hidden">
    <div style="background:${barColor};height:100%;width:${pctFinal.toFixed(1)}%;border-radius:20px;transition:width .3s"></div>
  </div>`;

  
  let tableHTML = '';
  if(rows.length > 0){
    tableHTML = '<table style="width:100%;border-collapse:collapse;font-size:.78rem;margin-bottom:8px">'
      + '<thead><tr style="background:#bbdefb;color:#1565c0">'
      + '<th style="padding:4px 8px;text-align:left">Material</th>'
      + '<th style="padding:4px 8px;text-align:right">Peso (kg)</th>'
      + '<th style="padding:4px 8px;text-align:right">Acumulado</th>'
      + '<th style="padding:4px 8px;text-align:right">Restante</th>'
      + '<th style="padding:4px 8px;text-align:right">%</th>'
      + '</tr></thead><tbody>';
    rows.forEach((r,idx)=>{
      const restCor = r.restante < 0 ? '#c62828' : r.restante===0 ? '#2e7d32' : '#333';
      const bg = idx%2===0?'#f5f9ff':'#fff';
      tableHTML += `<tr style="background:${bg}">
        <td style="padding:4px 8px">${r.mat}</td>
        <td style="padding:4px 8px;text-align:right;font-weight:700">${r.peso.toFixed(1)}</td>
        <td style="padding:4px 8px;text-align:right">${r.acumulado.toFixed(1)}</td>
        <td style="padding:4px 8px;text-align:right;font-weight:800;color:${restCor}">${r.restante>=0?'':'-'}${Math.abs(r.restante).toFixed(1)}</td>
        <td style="padding:4px 8px;text-align:right">${r.pct.toFixed(1)}%</td>
      </tr>`;
    });
    tableHTML += '</tbody></table>';
  }

  
  let statusHTML = '';
  if(zerou){
    statusHTML = `<div style="background:#e8f5e9;border-radius:6px;padding:7px 12px;color:#2e7d32;font-weight:800;font-size:.85rem">
      ✅ Conferência OK! Rodoviária: ${rodVal.toFixed(1)} kg = Balança pequena: ${somaLiq.toFixed(1)} kg</div>`;
  } else if(excedeu){
    statusHTML = `<div style="background:#ffebee;border-radius:6px;padding:7px 12px;color:#c62828;font-weight:800;font-size:.85rem">
      ⚠️ EXCEDEU! Balança pequena (${somaLiq.toFixed(1)} kg) passou da rodoviária (${rodVal.toFixed(1)} kg) em ${Math.abs(restFinal).toFixed(1)} kg</div>`;
  } else if(rows.length > 0){
    statusHTML = `<div style="background:#fff8e1;border-radius:6px;padding:7px 12px;color:#e65100;font-weight:700;font-size:.85rem">
      ⏳ Pesado: ${somaLiq.toFixed(1)} kg de ${rodVal.toFixed(1)} kg — Restante: <b>${restFinal.toFixed(1)} kg</b> (${(100-pctFinal).toFixed(1)}%)</div>`;
  } else {
    statusHTML = `<div style="color:#666;font-size:.8rem">Adicione itens e informe os pesos para conferir.</div>`;
  }

  div.innerHTML = barHTML + tableHTML + statusHTML;
}

