let _cFornIdx=-1; 
function _cFornNorm(s){ return (s||'').toString().normalize('NFD').replace(/[̀-ͯ]/g,'').toLowerCase().trim(); }
function _cFornLista(){
  return getFornAtivos().slice()
    .filter(f=>f&&String(f.nome||'').trim())
    .sort((a,b)=>(a.nome||'').localeCompare(b.nome||'','pt-BR'));
}
function cFornFiltrar(){
  const inp=document.getElementById('c-forn-busca');
  const drop=document.getElementById('c-forn-drop');
  if(!inp||!drop) return;
  const q=_cFornNorm(inp.value);
  let lista=_cFornLista();
  if(q) lista=lista.filter(f=>_cFornNorm(f.nome).includes(q));
  _cFornIdx=-1;
  if(!lista.length){
    drop.innerHTML='<div style="padding:10px 12px;color:#999;font-size:.85rem">Nenhum fornecedor encontrado.</div>';
    drop.style.display='block';
    return;
  }
  drop.innerHTML=lista.slice(0,200).map(function(f){
    return '<div class="cforn-item" data-cod="'+esc(f.cod)+'" data-nome="'+esc(f.nome)+'" '
      +'onmousedown="event.preventDefault();cFornEscolher(this.getAttribute(\'data-cod\'),this.getAttribute(\'data-nome\'))" '
      +'style="padding:9px 12px;font-size:.9rem;cursor:pointer;border-bottom:1px solid #f0f2f5">'+esc(f.nome)+'</div>';
  }).join('');
  drop.style.display='block';
}
function cFornEscolher(cod,nome){
  const inp=document.getElementById('c-forn-busca');
  const sel=document.getElementById('c-forn');
  const drop=document.getElementById('c-forn-drop');
  if(inp) inp.value=nome||'';
  if(sel){
    
    if(![...sel.options].some(o=>o.value===cod)){
      const o=document.createElement('option'); o.value=cod; o.textContent=nome||cod; sel.appendChild(o);
    }
    sel.value=cod;
  }
  if(drop) drop.style.display='none';
  _cFornIdx=-1;
  try{ onFornChange(); }catch(e){}
}
function cFornKey(ev){
  const drop=document.getElementById('c-forn-drop');
  if(!drop||drop.style.display==='none') return;
  const itens=drop.querySelectorAll('.cforn-item');
  if(!itens.length) return;
  if(ev.key==='ArrowDown'){ ev.preventDefault(); _cFornIdx=Math.min(_cFornIdx+1,itens.length-1); }
  else if(ev.key==='ArrowUp'){ ev.preventDefault(); _cFornIdx=Math.max(_cFornIdx-1,0); }
  else if(ev.key==='Enter'){ if(_cFornIdx>=0){ ev.preventDefault(); const it=itens[_cFornIdx]; cFornEscolher(it.getAttribute('data-cod'),it.getAttribute('data-nome')); } return; }
  else if(ev.key==='Escape'){ drop.style.display='none'; return; }
  else return;
  itens.forEach(function(it,i){ it.style.background = i===_cFornIdx?'#e8f0fe':''; });
  if(itens[_cFornIdx]) itens[_cFornIdx].scrollIntoView({block:'nearest'});
}

document.addEventListener('click',function(ev){
  const drop=document.getElementById('c-forn-drop');
  if(!drop||drop.style.display==='none') return;
  const inp=document.getElementById('c-forn-busca');
  if(ev.target===inp||drop.contains(ev.target)) return;
  drop.style.display='none';
});

function onMaterialChange(n){
  const cod=getFornCod();
  if(!cod) return;
  const matSel=document.getElementById(`cmat-${n}`);
  const prEl=document.getElementById(`cpr-${n}`);
  if(!matSel||!prEl) return;
  const mat=(matSel.value||'').trim();
  const preco=(PRECOS_FORN_DATA[cod]&&PRECOS_FORN_DATA[cod][mat])||0;
  if(preco>0) prEl.value=preco.toFixed(2);
  calcCompra();
}

function onFornChange(){
  const cod=getFornCod();
  const infoDiv=document.getElementById('c-forn-info');

  
  for(let i=1;i<=compraRowId;i++){ try{onMaterialChange(i);}catch(e){} }

  if(!infoDiv||!cod){ return; }

  const fmt=v=>_numFinito(v,0).toLocaleString('pt-BR',{minimumFractionDigits:2});
  const adts=(ADT_POR_FORN[cod]||[]);
  const cheqs=(CHEQUES_POR_FORN[cod]||[]);

  
  const adtPend=adts.filter(a=>a.status==='Pendente'&&a.forma!=='Crédito');
  const adtCred=adts.filter(a=>a.forma==='Crédito'&&a.status!=='Quitado');
  const cheqPend=cheqs.filter(c=>c.status==='Pendente');

  const totalAdtPend=adtPend.reduce((s,a)=>s+Number(a.valor),0);
  const totalAdtCred=adtCred.reduce((s,a)=>s+Number(a.valor),0);
  const totalCheqPend=cheqPend.reduce((s,c)=>s+Number(c.valor),0);
  const totalGeral=totalAdtPend+totalAdtCred+totalCheqPend;

  
  const sdRaw=SALDO_DEVEDOR_FORN&&SALDO_DEVEDOR_FORN[cod];
  const saldoDev=sdRaw?(typeof sdRaw==='object'?(sdRaw.valor||0):Number(sdRaw||0)):0;

  
  const ticksForn=Object.values(TICKETS_DB)
    .filter(t=>t.fornecedorCod===cod)
    .sort((a,b)=>{ const da=a.data.split('/').reverse().join('-'); const db=b.data.split('/').reverse().join('-'); return db.localeCompare(da); })
    .slice(0,5);

  const totalDesconto=totalGeral+saldoDev;

  
  const adtInput=document.getElementById('c-adt');
  if(adtInput){ adtInput.value=totalDesconto>0?totalDesconto.toFixed(2):'0'; calcCompra(); }

  
  let html='<div style="background:#f0f7ff;border:1.5px solid #2980b9;border-radius:10px;padding:14px 16px;margin-bottom:10px;font-size:.82rem">';
  html+='<div style="font-weight:800;color:#1a5276;margin-bottom:10px;font-size:.88rem">📋 Resumo Financeiro do Fornecedor</div>';

  
  html+='<div style="display:flex;flex-wrap:wrap;gap:8px;margin-bottom:10px">';
  html+=`<div style="background:#fff;border-radius:7px;padding:8px 12px;border:1px solid #bee3f8;min-width:140px">
    <div style="font-size:.7rem;color:#666;text-transform:uppercase;letter-spacing:.4px">Adiantamentos Pend.</div>
    <div style="font-size:1rem;font-weight:800;color:${totalAdtPend>0?'#c0392b':'#27ae60'}">${totalAdtPend>0?'R$ '+fmt(totalAdtPend):'—'}</div>
  </div>`;
  html+=`<div style="background:#fff;border-radius:7px;padding:8px 12px;border:1px solid #bee3f8;min-width:140px">
    <div style="font-size:.7rem;color:#666;text-transform:uppercase;letter-spacing:.4px">Cheques Pendentes</div>
    <div style="font-size:1rem;font-weight:800;color:${totalCheqPend>0?'#e67e22':'#27ae60'}">${totalCheqPend>0?'R$ '+fmt(totalCheqPend):'—'}</div>
  </div>`;
  if(saldoDev>0) html+=`<div style="background:#fff3cd;border-radius:7px;padding:8px 12px;border:1px solid #ffc107;min-width:140px">
    <div style="font-size:.7rem;color:#666;text-transform:uppercase;letter-spacing:.4px">Saldo Devedor</div>
    <div style="font-size:1rem;font-weight:800;color:#e74c3c">R$ ${fmt(saldoDev)}</div>
  </div>`;
  if(totalDesconto>0) html+=`<div style="background:#fdecea;border-radius:7px;padding:8px 12px;border:1.5px solid #e74c3c;min-width:140px">
    <div style="font-size:.7rem;color:#c0392b;text-transform:uppercase;letter-spacing:.4px;font-weight:700">Total a Descontar</div>
    <div id="c-total-descontar-val" style="font-size:1.1rem;font-weight:800;color:#c0392b">R$ ${fmt(totalDesconto)}</div>
  </div>`;
  html+='</div>';

  
  
  if(adtPend.length>0){
    html+='<div style="font-weight:700;color:#1a5276;margin-bottom:4px">💰 Adiantamentos Pendentes <span style="font-weight:400;color:#666;font-size:.72rem">(desmarque os que NÃO quer descontar nesta compra)</span></div>';
    html+='<table style="width:100%;border-collapse:collapse;font-size:.76rem;margin-bottom:8px"><thead><tr style="background:#d6eaf8"><th style="padding:4px 6px;text-align:center">Usar?</th><th style="padding:4px 6px;text-align:left">Cód.</th><th style="padding:4px 6px;text-align:left">Data</th><th style="padding:4px 6px;text-align:right">Valor</th><th style="padding:4px 6px;text-align:left">Forma</th></tr></thead><tbody>';
    adtPend.forEach(a=>{ html+=`<tr><td style="padding:3px 6px;text-align:center"><input type="checkbox" class="c-adt-chk" data-cod="${a.cod}" data-valor="${Number(a.valor)}" checked onchange="recalcAdtSelecionado()"></td><td style="padding:3px 6px">${a.cod}</td><td style="padding:3px 6px">${fmtDate(a.data)||'—'}</td><td style="padding:3px 6px;text-align:right;font-weight:700">R$ ${fmt(a.valor)}</td><td style="padding:3px 6px">${a.forma||'—'}</td></tr>`; });
    html+='</tbody></table>';
  }

  
  if(cheqPend.length>0){
    html+='<div style="font-weight:700;color:#1a5276;margin-bottom:4px">📋 Cheques Pendentes</div>';
    html+='<table style="width:100%;border-collapse:collapse;font-size:.76rem;margin-bottom:8px"><thead><tr style="background:#d6eaf8"><th style="padding:4px 6px;text-align:left">Nº</th><th style="padding:4px 6px;text-align:right">Valor</th><th style="padding:4px 6px;text-align:left">Bom Para</th></tr></thead><tbody>';
    cheqPend.forEach(c=>{ html+=`<tr><td style="padding:3px 6px">${c.num||'—'}</td><td style="padding:3px 6px;text-align:right;font-weight:700">R$ ${fmt(c.valor)}</td><td style="padding:3px 6px">${fmtDate(c.bomPara)||'—'}</td></tr>`; });
    html+='</tbody></table>';
  }

  
  
  const ticksAberto=ticksForn.filter(function(t){ return !(t.status==='Pago'||t.status==='Quitado'||Number(t.saldoPagar||0)<=0.01); });
  if(ticksAberto.length>0){
    html+='<div style="font-weight:700;color:#1a5276;margin-bottom:4px">🛒 Compras em aberto</div>';
    html+='<table style="width:100%;border-collapse:collapse;font-size:.76rem"><thead><tr style="background:#d6eaf8"><th style="padding:4px 6px;text-align:left">Ticket</th><th style="padding:4px 6px;text-align:left">Data</th><th style="padding:4px 6px;text-align:right">Total</th><th style="padding:4px 6px;text-align:left">Status</th></tr></thead><tbody>';
    ticksAberto.forEach(t=>{ const cor=t.status==='Pago'?'#27ae60':'#e74c3c'; html+=`<tr><td style="padding:3px 6px;font-weight:700">${t.ticket}</td><td style="padding:3px 6px">${fmtDate(t.data)||'—'}</td><td style="padding:3px 6px;text-align:right">R$ ${fmt(t.totalGeral||0)}</td><td style="padding:3px 6px;color:${cor};font-weight:700">${t.status}</td></tr>`; });
    html+='</tbody></table>';
  }

  if(totalDesconto===0&&adtPend.length===0&&cheqPend.length===0&&ticksForn.length===0){
    html+='<div style="color:#666;font-style:italic;font-size:.8rem">Nenhum adiantamento, cheque pendente ou compra anterior encontrada.</div>';
  }

  html+='</div>';
  infoDiv.innerHTML=html;
}




function recalcAdtSelecionado(){
  const cod=getFornCod();
  if(!cod) return;
  const cheqs=(CHEQUES_POR_FORN[cod]||[]).filter(c=>c.status==='Pendente');
  const totalCheqPend=cheqs.reduce((s,c)=>s+Number(c.valor),0);
  const sdRaw=SALDO_DEVEDOR_FORN&&SALDO_DEVEDOR_FORN[cod];
  const saldoDev=sdRaw?(typeof sdRaw==='object'?(sdRaw.valor||0):Number(sdRaw||0)):0;
  let totalAdtSel=0;
  document.querySelectorAll('.c-adt-chk').forEach(chk=>{
    if(chk.checked) totalAdtSel+=parseFloat(chk.dataset.valor)||0;
  });
  const totalDesconto=totalAdtSel+totalCheqPend+saldoDev;
  const adtInput=document.getElementById('c-adt');
  if(adtInput){ adtInput.value=totalDesconto>0?totalDesconto.toFixed(2):'0'; calcCompra(); }
  const totalEl=document.getElementById('c-total-descontar-val');
  if(totalEl) totalEl.textContent='R$ '+Number(totalDesconto).toLocaleString('pt-BR',{minimumFractionDigits:2});
}

function calcCompra(){
  let total=0, totalKg=0;
  for(let i=1;i<=compraRowId;i++){
    const lq=parseFloat(document.getElementById(`clq-${i}`)?.value)||0;
    const pr=parseFloat(document.getElementById(`cpr-${i}`)?.value)||0;
    const sub=lq*pr;
    total+=sub; totalKg+=lq;
    const el=document.getElementById(`ctot-${i}`);
    if(el) el.textContent='R$ '+sub.toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2});
  }
  const _ckg=document.getElementById('c-totalkg');
  if(_ckg) _ckg.textContent=totalKg.toLocaleString('pt-BR',{minimumFractionDigits:1,maximumFractionDigits:1})+' kg';
  
  const extra=_somaExtras();
  total+=extra;
  const adt=parseFloat(document.getElementById('c-adt')?.value)||0;
  const saldo=total-adt;
  document.getElementById('c-total').textContent='R$ '+total.toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2});
  document.getElementById('c-adt-show').textContent='R$ '+adt.toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2});
  const saldoEl=document.getElementById('c-saldo');
  const saldoLbl=document.getElementById('c-saldo-label');
  if(saldoEl){
    if(saldo>0.005){
      
      if(saldoLbl){ saldoLbl.textContent='SALDO A PAGAR:'; saldoLbl.style.color='#555'; }
      saldoEl.textContent='R$ '+saldo.toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2});
      saldoEl.style.color='var(--primary)';
      saldoEl.style.background=''; saldoEl.style.padding='';
    } else if(saldo<-0.005){
      
      
      if(saldoLbl){ saldoLbl.textContent='✅ Carga paga. Sobrou:'; saldoLbl.style.color='#1a7f4b'; }
      saldoEl.textContent='R$ '+Math.abs(saldo).toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2})+' (crédito p/ próxima carga)';
      saldoEl.style.color='#1a7f4b';
      saldoEl.style.background='#eafaf0'; saldoEl.style.padding='2px 8px'; saldoEl.style.borderRadius='6px';
    } else {
      if(saldoLbl){ saldoLbl.textContent='SALDO:'; saldoLbl.style.color='#1a7f4b'; }
      saldoEl.textContent='✅ R$ 0,00 (quitada)';
      saldoEl.style.color='#1a7f4b';
      saldoEl.style.background=''; saldoEl.style.padding='';
    }
  }
  try{verificarPesos();}catch(e){}
}

function _normalizarNomePrecoCli(v){
  return String(v||'').trim().toUpperCase();
}
function _precoClienteVenda(cliente, material){
  const cli=String(cliente||'').trim();
  const mat=String(material||'').trim();
  if(!cli||!mat||typeof PRECOS_CLI_DATA==='undefined') return 0;
  const direto=PRECOS_CLI_DATA[cli];
  if(direto && Number(direto[mat])>0) return Number(direto[mat]);
  const ck=Object.keys(PRECOS_CLI_DATA||{}).find(k=>_normalizarNomePrecoCli(k)===_normalizarNomePrecoCli(cli));
  if(!ck) return 0;
  const tabela=PRECOS_CLI_DATA[ck]||{};
  if(Number(tabela[mat])>0) return Number(tabela[mat]);
  const mk=Object.keys(tabela).find(k=>_normalizarNomePrecoCli(k)===_normalizarNomePrecoCli(mat));
  return mk ? Number(tabela[mk]||0) : 0;
}
function aplicarPrecoClienteVendaRow(n, force){
  const row=document.getElementById('vrow-'+n); if(!row) return;
  const cliente=(document.getElementById('v-cliente')?.value||'').trim();
  const mat=row.querySelector('select')?.value||'';
  const inp=document.getElementById('vpr-'+n); if(!inp) return;
  const atual=parseFloat(inp.value)||0;
  const preco=_precoClienteVenda(cliente,mat);
  if(preco>0 && (force || atual<=0)) inp.value=String(preco);
}
function aplicarPrecosClienteVenda(){
  for(let i=1;i<=vendaRowId;i++) aplicarPrecoClienteVendaRow(i,false);
  try{ calcVenda(); }catch(e){}
}

function buildVendaForm(){
  vendaRowId=0;
  return `
  <h3>💵 Nova Venda de Material</h3>
  <div class="mi-header">
    <div class="fg" style="margin:0"><label>NF / Pedido</label><input id="v-nf" placeholder="NF001"></div>
    <div class="fg" style="margin:0"><label>Data</label><input id="v-data" type="date" value="${_hojeISO()}"></div>
    <div class="fg" style="margin:0"><label>Vencimento</label><input id="v-venc" type="date"></div>
  </div>
  <div class="mi-header-2">
    <div class="fg" style="margin:0"><label>Cliente</label>
      <input id="v-cliente" list="dlist-clientes-venda" placeholder="Digite ou escolha o cliente" autocomplete="off" oninput="vClienteInfo()" onchange="vClienteInfo()">
      <datalist id="dlist-clientes-venda"></datalist>
    </div>
    <div class="fg" style="margin:0"><label>Status Pagamento</label><select id="v-status"><option>Pendente</option><option>Pago</option><option>A prazo</option><option>Permuta</option></select></div>
  </div>
  <div id="v-cliente-info" style="margin:2px 0 10px"></div>
  <hr class="divider">
  <div style="font-size:.8rem;font-weight:800;color:var(--primary);margin-bottom:8px">📦 ITENS DA VENDA</div>
  <table class="itens-table">
    <thead><tr>
      <th>#</th><th style="min-width:160px">Material</th><th style="min-width:110px">Identificação</th>
      <th style="min-width:100px">Quantidade (kg)</th><th style="min-width:100px">Preço R$/kg</th>
      <th style="min-width:110px">Total R$</th>
      <th style="min-width:90px;color:#27ae60">Estoque Disp.</th><th></th>
    </tr></thead>
    <tbody id="venda-rows"></tbody>
  </table>
  <button class="btn-add-row" onclick="addVendaRow()">+ Adicionar Item</button>
  <div style="display:flex;justify-content:flex-end;align-items:flex-end;gap:14px;margin:8px 0;flex-wrap:wrap">
    <div style="font-size:.82rem;color:#1a5e2a;font-weight:700;margin-right:auto">Total: <b id="v-totalkg">0 kg</b></div>
    <div style="font-size:.82rem;color:#555">Subtotal: <b id="v-subtotal">R$ 0,00</b></div>
    <div class="fg" style="margin:0"><label style="font-size:.75rem">Desconto / Devolução</label>
      <div style="display:flex;gap:4px">
        <input id="v-desconto" type="number" min="0" step="0.01" placeholder="0,00" value="" oninput="calcVenda()" style="width:110px" title="Desconto no pagamento, % ou valor de material devolvido — abate do total">
        <select id="v-desconto-tipo" onchange="calcVenda()" style="width:62px;padding:6px 4px;border:1px solid #ccc;border-radius:5px"><option value="R$">R$</option><option value="%">%</option></select>
      </div>
    </div>
    <div style="font-size:.8rem;color:#c0392b">Desconto aplicado: <b id="v-desc-aplicado">R$ 0,00</b></div>
  </div>
  <div style="background:#f1f8e9;border:1px solid #a5d6a7;border-radius:8px;padding:10px 13px;margin:8px 0">
    <label style="font-size:.72rem;font-weight:700;color:#555;display:block;margin-bottom:6px">➕ Valores extras <span style="font-weight:400;color:#999">(opcional — ex: frete, mão de obra…) — somam no total</span></label>
    <div id="v-extras">${_vExtraRowHTML('','')}</div>
    <button type="button" onclick="addVExtraRow()" style="margin-top:2px;background:#e8f5e9;border:1px dashed #7cb342;color:#33691e;border-radius:6px;padding:5px 12px;font-size:.8rem;font-weight:700;cursor:pointer">+ Adicionar outro valor extra</button>
  </div>
  <div class="total-bar">
    <span>TOTAL DA VENDA</span>
    <strong id="v-total">R$ 0,00</strong>
    <span>${new Date().toLocaleDateString('pt-BR')}</span>
  </div>
  <div class="fg"><label>Observações</label><input id="v-obs" placeholder="Observações da venda..."></div>
  <hr class="divider">
  <div style="font-size:.8rem;font-weight:800;color:var(--primary);margin-bottom:8px">🏦 RECEBIMENTO (Como será pago)</div>
  <table style="width:100%;border-collapse:collapse;font-size:.8rem;margin-bottom:6px">
    <thead><tr style="background:#e8eceb">
      <th style="padding:5px 8px;text-align:left">Forma</th>
      <th style="padding:5px 8px;text-align:left">Conta Bancária</th>
      <th style="padding:5px 8px;text-align:right">Valor R$</th>
      <th style="padding:5px 8px;text-align:left">Obs.</th>
      <th style="width:32px"></th>
    </tr></thead>
    <tbody id="v-pgto-rows"></tbody>
  </table>
  <div style="display:flex;align-items:center;gap:10px;margin-bottom:8px">
    <button onclick="addVPgtoRow()" style="background:var(--primary);color:#fff;border:none;border-radius:6px;padding:5px 12px;font-size:.78rem;font-weight:700;cursor:pointer">+ Adicionar Conta</button>
    <div id="v-pgto-saldo-bar" style="font-size:.8rem;display:none">
      Alocado: <b id="v-pgto-alocado" style="color:var(--primary)">R$ 0,00</b>
      &nbsp;|&nbsp; Restante: <b id="v-pgto-restante" style="color:var(--danger)">R$ 0,00</b>
    </div>
  </div>
  <div class="modal-ft">
    <button class="btn-cancel" onclick="cm()">Cancelar</button>
    <button class="btn-save" onclick="salvarVenda()">💾 Salvar Venda</button>
  </div>`;
}

function addVendaRow(){
  vendaRowId++;
  const n=vendaRowId;
  
  
  
  try{ if(typeof refreshMetaisGlobals==='function') refreshMetaisGlobals(); }catch(e){}
  const _optsMat = (typeof METAIS!=='undefined' && METAIS.length)
    ? METAIS.map(m=>`<option>${m}</option>`).join('')
    : (METAIS_OPTS||'');
  const tr=document.createElement('tr');
  tr.id=`vrow-${n}`;
  tr.innerHTML=`
    <td style="text-align:center;font-weight:700;color:var(--gray)">${n}</td>
    <td><select onchange="aplicarPrecoClienteVendaRow(${n},false);calcVenda();atualizarSaldoVendaRow(${n})">${_optsMat}</select></td>
    <td><select onchange="calcVenda()">${IDENT_OPTS}</select></td>
    <td><input type="number" min="0" step="0.1" placeholder="0" id="vqt-${n}" oninput="calcVenda();atualizarSaldoVendaRow(${n})"></td>
    <td><input type="number" min="0" step="0.01" placeholder="0,00" id="vpr-${n}" oninput="calcVenda()"></td>
    <td class="td-total" id="vtot-${n}">R$ 0,00</td>
    <td id="vsaldo-${n}" style="font-size:.78rem;text-align:center;min-width:90px">—</td>
    <td class="td-rm"><button class="btn-rm-row" onclick="rmRow('vrow-${n}');calcVenda()">✕</button></td>`;
  document.getElementById('venda-rows').appendChild(tr);
  aplicarPrecoClienteVendaRow(n,false);
  calcVenda();
}

function calcVenda(){
  let subtotal=0, totalKg=0;
  for(let i=1;i<=vendaRowId;i++){
    const qt=parseFloat(document.getElementById(`vqt-${i}`)?.value)||0;
    const pr=parseFloat(document.getElementById(`vpr-${i}`)?.value)||0;
    const sub=qt*pr;
    subtotal+=sub; totalKg+=qt;
    const el=document.getElementById(`vtot-${i}`);
    if(el) el.textContent='R$ '+sub.toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2});
  }
  const kgEl=document.getElementById('v-totalkg');
  if(kgEl) kgEl.textContent=totalKg.toLocaleString('pt-BR',{minimumFractionDigits:1,maximumFractionDigits:1})+' kg';
  const descRaw=parseFloat(document.getElementById('v-desconto')?.value)||0;
  const tipoDesc=document.getElementById('v-desconto-tipo')?.value||'R$';
  const descValor=tipoDesc==='%' ? subtotal*descRaw/100 : descRaw;
  const extrasV=_somaVExtras();
  const total=Math.max(0, subtotal-descValor+extrasV);
  const subEl=document.getElementById('v-subtotal');
  if(subEl) subEl.textContent='R$ '+subtotal.toLocaleString('pt-BR',{minimumFractionDigits:2});
  const daEl=document.getElementById('v-desc-aplicado');
  if(daEl) daEl.textContent='R$ '+descValor.toLocaleString('pt-BR',{minimumFractionDigits:2})+(tipoDesc==='%'&&descRaw>0?' ('+descRaw+'%)':'');
  document.getElementById('v-total').textContent='R$ '+total.toLocaleString('pt-BR',{minimumFractionDigits:2});
  if(typeof calcVPgto==='function') calcVPgto();
}

function atualizarSaldoVendaRow(n){
  const row=document.getElementById('vrow-'+n);
  if(!row) return;
  const sel=row.querySelector('select');
  const mat=sel?sel.value:'';
  const saldoEl=document.getElementById('vsaldo-'+n);
  if(!saldoEl) return;
  if(!mat){ saldoEl.innerHTML='—'; return; }
  const e=ESTOQUE_DB[mat]||{inicial:0,saidas:0};
  const entradas=getEntradasMaterial(mat);
  const saidasAnt=getSaidasMaterial(mat)+Number(e.saidas||0);
  const saldo=Number(e.inicial||0)+entradas-saidasAnt;
  const qt=parseFloat(document.getElementById('vqt-'+n)?.value)||0;
  const excede=qt>saldo&&qt>0;
  const cor=excede?'#e74c3c':saldo<=0?'#e67e22':'#27ae60';
  const icone=excede?'❌':saldo<=0?'⚠️':'✅';
  saldoEl.innerHTML='<span style="color:'+cor+';font-weight:700">'+icone+' '+
    Number(saldo).toLocaleString('pt-BR',{minimumFractionDigits:1,maximumFractionDigits:1})+' kg</span>'+
    (excede?'<br><span style="color:#e74c3c;font-size:.7rem">insuficiente</span>':'');
}

function rmRow(id){
  const el=document.getElementById(id);
  if(el) el.remove();
}




let CLIENTES = [];





const _syncClientes = _criarSincroniaPorChave('clientes', CLIENTES, 'CL');
function saveClientes(){
  try{
    const obj=_syncClientes.paraObjeto();
    if(window.__businessRepository) window.__businessRepository.upsertMany('clientes',obj).catch(e=>console.warn('clientes RTDB:',e));
    if(typeof fbSalvarImediato==='function') fbSalvarImediato(); else if(typeof fbSalvar==='function') fbSalvar();
  }catch(e){ console.warn('saveClientes:',e); }
  try{ if(typeof rodPopularPessoaSelect==='function' && (_rodTipoAtual||'compra')==='venda') rodPopularPessoaSelect(); }catch(e){}
}
async function recarregarClientesDoBanco(){
  try{
    if(!window.__businessRepository) return false;
    const remoto=await window.__businessRepository.read('clientes');
    _syncClientes.carregarDeRemoto(remoto||{}, true);
    try{ renderClientes(); }catch(e){}
    try{ populatePrecosCliSel(); }catch(e){}
    try{ popularClientesVenda(); }catch(e){}
    try{ if((_rodTipoAtual||'compra')==='venda') rodPopularPessoaSelect(); }catch(e){}
    return true;
  }catch(e){ console.warn('clientes RTDB leitura:',e); return false; }
}

function populatePrecosCliSel(){
  const sel=document.getElementById('pc-cli-sel');
  if(!sel) return;
  const cur=sel.value;
  sel.innerHTML='<option value="">— Selecione —</option>'+
    CLIENTES.slice().sort((a,b)=>String(a.nome||'').localeCompare(String(b.nome||''),'pt-BR',{sensitivity:'base'})).map(c=>`<option value="${esc(c.nome)}">${esc(c.nome)}</option>`).join('');
  if(cur) sel.value=cur;
}

function renderPrecosCliTab(){
  const div=document.getElementById('precos-cli-container');
  if(!div) return;
  const fmt=v=>_numFinito(v,0).toLocaleString('pt-BR',{minimumFractionDigits:2});
  const cliNome=document.getElementById('pc-cli-sel')?.value;
  const shareBar=document.getElementById('pc-share-btns');
  if(!cliNome){
    div.innerHTML='<p style="color:var(--gray);text-align:center;padding:20px">Selecione um cliente acima.</p>';
    if(shareBar) shareBar.style.display='none';
    return;
  }
  if(!PRECOS_CLI_DATA[cliNome]) PRECOS_CLI_DATA[cliNome]={};
  const precos=PRECOS_CLI_DATA[cliNome];
  const comPreco=Object.entries(precos).filter(([,v])=>v>0);
  if(shareBar && comPreco.length>0) shareBar.style.display='flex';
  else if(shareBar) shareBar.style.display='none';

  
  const semPreco=METAIS.filter(m=>!(precos[m]>0));

  
  const addRow=semPreco.length>0?`
    <tr style="background:#f0f7ff">
      <td style="padding:6px 10px">
        <select id="pc-add-mat" style="width:100%;padding:5px 8px;border:1px solid #c5dff8;border-radius:6px;font-size:.83rem">
          <option value="">— Selecione material —</option>
          ${semPreco.map(m=>`<option value="${m}">${m}</option>`).join('')}
        </select>
      </td>
      <td style="padding:4px 8px">
        <input type="number" min="0" step="0.01" id="pc-add-val" placeholder="0,00"
          style="width:100%;border:1px solid #c5dff8;border-radius:6px;padding:5px 8px;text-align:right;font-size:.85rem">
      </td>
      <td style="padding:4px 8px;text-align:center">
        <button onclick="adicionarPrecoCliItem('${cliNome}')" style="background:var(--primary);color:#fff;border:none;border-radius:6px;padding:5px 12px;cursor:pointer;font-size:.82rem;font-weight:700">➕ Add</button>
      </td>
    </tr>`:
    `<tr><td colspan="3" style="padding:8px 12px;font-size:.8rem;color:var(--gray);text-align:center">Todos os materiais já têm preço definido.</td></tr>`;

  div.innerHTML=`
    <table style="width:100%;border-collapse:collapse;font-size:.85rem">
      <thead><tr style="background:#1a5c35;color:#fff">
        <th style="padding:8px 12px;text-align:left">Material</th>
        <th style="padding:8px 12px;text-align:center;width:160px">Preço R$/kg</th>
        <th style="padding:8px 12px;text-align:center;width:90px">Ação</th>
      </tr></thead>
      <tbody>
        ${comPreco.length===0
          ? `<tr><td colspan="3" style="padding:20px;text-align:center;color:var(--gray);font-size:.88rem">
              Nenhum preço definido para <strong>${cliNome}</strong> ainda.<br>
              <span style="font-size:.8rem">Adicione materiais abaixo conforme for vendendo.</span>
             </td></tr>`
          : comPreco.map(([m,v])=>`
            <tr style="border-bottom:1px solid var(--border)">
              <td style="padding:6px 12px;font-weight:600">${m}</td>
              <td style="padding:4px 8px">
                <input type="number" min="0" step="0.01" value="${v}"
                  id="pc_${m.replace(/[^a-zA-Z0-9]/g,'_')}"
                  style="width:100%;border:1px solid var(--border);border-radius:6px;padding:5px 8px;text-align:right;font-size:.85rem"
                  onchange="salvarPrecosCliInline('${cliNome}','${m}',this)">
              </td>
              <td style="padding:4px 8px;text-align:center">
                <button onclick="removerPrecoCliItem('${cliNome}','${m}')" title="Remover" style="background:#fde8e8;color:#c0392b;border:none;border-radius:6px;padding:4px 8px;cursor:pointer;font-size:.8rem">🗑️</button>
              </td>
            </tr>`).join('')
        }
        ${addRow}
      </tbody>
    </table>
    ${comPreco.length>0?`<div style="margin-top:10px;padding:8px 14px;background:#e8f5e9;border-radius:8px;font-size:.8rem;color:#2e7d32">
      ✅ ${comPreco.length} material(is) com preço definido para ${cliNome}.
    </div>`:''}`;

}

function adicionarPrecoCliItem(cliNome){
  const mat=(document.getElementById('pc-add-mat')?.value||'').trim();
  const val=parseFloat(document.getElementById('pc-add-val')?.value)||0;
  if(!mat){alert('Selecione o material!');return;}
  if(val<=0){alert('Informe um preço maior que zero!');return;}
  if(!PRECOS_CLI_DATA[cliNome]) PRECOS_CLI_DATA[cliNome]={};
  PRECOS_CLI_DATA[cliNome][mat]=val;
  saveDB();
  renderPrecosCliTab();
}
function removerPrecoCliItem(cliNome,mat){
  if(!confirm('Remover preço de '+mat+' para '+cliNome+'?')) return;
  if(PRECOS_CLI_DATA[cliNome]) delete PRECOS_CLI_DATA[cliNome][mat];
  saveDB();
  renderPrecosCliTab();
}
function salvarPrecosCli(cliNome,mat,val){
  if(!PRECOS_CLI_DATA[cliNome]) PRECOS_CLI_DATA[cliNome]={};
  const n=parseFloat(val)||0;
  if(n>0) PRECOS_CLI_DATA[cliNome][mat]=n;
  else delete PRECOS_CLI_DATA[cliNome][mat];
  saveDB();
  renderPrecosCliTab();
}
function salvarPrecosCliInline(cliNome,mat,el){
  if(!PRECOS_CLI_DATA[cliNome]) PRECOS_CLI_DATA[cliNome]={};
  const n=parseFloat(el.value)||0;
  const fmt=v=>_numFinito(v,0).toLocaleString('pt-BR',{minimumFractionDigits:2});
  if(n>0) PRECOS_CLI_DATA[cliNome][mat]=n;
  else delete PRECOS_CLI_DATA[cliNome][mat];
  saveDB();
  const key='pc_ind_'+mat.replace(/[^a-zA-Z0-9]/g,'_');
  const span=document.getElementById(key);
  if(span) span.innerHTML=n>0?`<span style="color:var(--success);font-size:.75rem;font-weight:700">✓ ${fmt(n)}</span>`:'<span style="color:var(--gray);font-size:.75rem">—</span>';
}

function getPrecosCliMsg(cliNome){
  const precos=PRECOS_CLI_DATA[cliNome]||{};
  const itens=Object.entries(precos).filter(([,v])=>v>0);
  if(itens.length===0){alert('Nenhum preço definido para este cliente.');return null;}
  const fmt=v=>_numFinito(v,0).toLocaleString('pt-BR',{minimumFractionDigits:2});
  const hoje=new Date().toLocaleDateString('pt-BR');
  const div='━━━━━━━━━━━━━━━━━━━━━━━━━';
  let msg=`🏭 *${_empresaPrincipalRazao()}*
`;
  msg+=`CNPJ: ${_empresaPrincipalInfo().cnpj||''}
`;
  msg+=`${div}
`;
  msg+=`🏷️ *TABELA DE PREÇOS DE VENDA*
`;
  msg+=`${div}
`;
  msg+=`👤 *Cliente:* ${cliNome}
`;
  msg+=`📅 *Emitida em:* ${hoje}
`;
  msg+=`${div}
`;
  itens.forEach(([mat,val])=>{ msg+=`▸ ${mat}: *R$ ${fmt(val)}/kg*
`; });
  msg+=`${div}
`;
  msg+=`📞 ${_empresaPrincipalTelefonesInline()}
`;
  msg+=`📧 ${_empresaPrincipalInfo().email||''}
`;
  msg+=`_Preços sujeitos a alteração sem aviso prévio._`;
  return msg;
}

function compartilharPrecosCliWpp(){
  const cliNome=document.getElementById('pc-cli-sel')?.value;
  if(!cliNome) return;
  const msg=getPrecosCliMsg(cliNome);
  if(!msg) return;
  window.open('https://wa.me/?text='+encodeURIComponent(msg),'_blank');
}

function compartilharPrecosCliNumero(){
  const cliNome=document.getElementById('pc-cli-sel')?.value;
  if(!cliNome) return;
  const msg=getPrecosCliMsg(cliNome);
  if(!msg) return;
  const num=prompt('Número WhatsApp do cliente (com DDD, só números):');
  if(!num) return;
  window.open('https://wa.me/55'+num.replace(/\D/g,'')+'?text='+encodeURIComponent(msg),'_blank');
}

function imprimirPrecosCli(){
  const cliNome=document.getElementById('pc-cli-sel')?.value;
  if(!cliNome) return;
  const precos=PRECOS_CLI_DATA[cliNome]||{};
  const itens=Object.entries(precos).filter(([,v])=>v>0);
  if(itens.length===0){alert('Nenhum preço definido.');return;}
  const fmt=v=>_numFinito(v,0).toLocaleString('pt-BR',{minimumFractionDigits:2});
  const hoje=new Date().toLocaleDateString('pt-BR');
  const linhas=itens.map(([mat,val],i)=>`
    <tr style="${i%2===0?'background:#f9f9f9':''}">
      <td style="padding:8px 12px;border-bottom:1px solid #eee">${mat}</td>
      <td style="padding:8px 12px;border-bottom:1px solid #eee;text-align:right;font-weight:700">R$ ${fmt(val)}/kg</td>
    </tr>`).join('');
  const win=window.open('','_blank');
  win.document.write(`<!DOCTYPE html><html><head><meta charset="UTF-8">
    <title>Tabela de Preços – ${cliNome}</title>
    <style>body{font-family:Arial,sans-serif;max-width:600px;margin:30px auto;color:#222}
    .hdr{text-align:center;border-bottom:3px solid #1a3a2a;padding-bottom:12px;margin-bottom:16px}
    .empresa{font-size:20px;font-weight:900;color:#1a3a2a}
    table{width:100%;border-collapse:collapse}th{background:#1a3a2a;color:#fff;padding:8px 12px;text-align:left}
    .footer{margin-top:20px;font-size:11px;color:#666;text-align:center;border-top:1px solid #ccc;padding-top:10px}
    @media print{button{display:none}}</style></head><body>
    <div class="hdr">
      <div class="empresa">🏭 ${esc(_empresaPrincipalRazao())}</div>
      <div style="font-size:12px;color:#555;margin-top:4px">CNPJ: ${_empresaPrincipalInfo().cnpj||''} · ${_empresaPrincipalEnderecoCurto()}</div>
    </div>
    <div style="margin-bottom:14px">
      <strong>🏷️ TABELA DE PREÇOS DE VENDA</strong><br>
      <span style="font-size:13px">Cliente: <b>${cliNome}</b> &nbsp;|&nbsp; Emitida em: ${hoje}</span>
    </div>
    <table><thead><tr><th>Material</th><th style="text-align:right">Preço R$/kg</th></tr></thead>
    <tbody>${linhas}</tbody></table>
    <div class="footer">
      📞 ${_empresaPrincipalTelefonesInline()} · ${_empresaPrincipalInfo().email||''}<br>
      Preços sujeitos a alteração sem aviso prévio.
    </div>
    <div style="text-align:center;margin-top:16px">
      <button onclick="window.print()" style="background:#1a3a2a;color:#fff;border:none;padding:9px 22px;border-radius:6px;font-size:13px;cursor:pointer">🖨️ Imprimir / Salvar PDF</button>
    </div></body></html>`);
  win.document.close();
}

async function compartilharImagemPrecosCli(){
  const cliNome=document.getElementById('pc-cli-sel')?.value;
  if(!cliNome) return;
  const precos=PRECOS_CLI_DATA[cliNome]||{};
  const itens=Object.entries(precos).filter(([,v])=>v>0);
  if(itens.length===0){alert('Nenhum preço definido para este cliente.');return;}
  const fmt=v=>_numFinito(v,0).toLocaleString('pt-BR',{minimumFractionDigits:2});
  const hoje=new Date().toLocaleDateString('pt-BR');
  const box=document.getElementById('pc-img-box');
  box.style.display='block';
  box.innerHTML=`
    <div style="text-align:center;border-bottom:3px solid #1a3a2a;padding-bottom:14px;margin-bottom:16px">
      <div style="font-size:20px;font-weight:900;color:#1a3a2a">🏭 ${esc(_empresaPrincipalRazao())}</div>
      <div style="font-size:11px;color:#555;margin-top:4px">CNPJ: ${_empresaPrincipalInfo().cnpj||''} · ${_empresaPrincipalEnderecoCurto()}</div>
    </div>
    <div style="margin-bottom:14px">
      <div style="font-size:15px;font-weight:800;color:#1a3a2a">🏷️ TABELA DE PREÇOS DE VENDA</div>
      <div style="font-size:12px;color:#444;margin-top:4px">Cliente: <b>${cliNome}</b> &nbsp;·&nbsp; Emitida em: ${hoje}</div>
    </div>
    <table style="width:100%;border-collapse:collapse;font-size:13px">
      <thead><tr style="background:#1a3a2a;color:#fff">
        <th style="padding:8px 12px;text-align:left">Material</th>
        <th style="padding:8px 12px;text-align:right">Preço R$/kg</th>
      </tr></thead>
      <tbody>${itens.map(([mat,val],i)=>`
        <tr style="background:${i%2===0?'#f9f9f9':'#fff'}">
          <td style="padding:7px 12px;border-bottom:1px solid #eee">${mat}</td>
          <td style="padding:7px 12px;border-bottom:1px solid #eee;text-align:right;font-weight:700;color:#1a3a2a">R$ ${fmt(val)}/kg</td>
        </tr>`).join('')}
      </tbody>
    </table>
    <div style="margin-top:14px;padding:10px;background:#e8f5e9;border-radius:6px;font-size:11px;color:#2e7d32;text-align:center">
      📞 ${_empresaPrincipalTelefonesInline()} · ${_empresaPrincipalInfo().email||''}<br>
      <i>Preços sujeitos a alteração sem aviso prévio.</i>
    </div>`;
  const btn=document.getElementById('pc-img-btn');
  btn.textContent='⏳ Gerando...'; btn.disabled=true;
  try{
    const canvas=await html2canvas(box,{scale:2,useCORS:true,backgroundColor:'#ffffff',logging:false});
    box.style.display='none';
    canvas.toBlob(async(blob)=>{
      const fileName=`precos-cliente-${cliNome.replace(/[^a-zA-Z0-9]/g,'-').toLowerCase()}.png`;
      const file=new File([blob],fileName,{type:'image/png'});
      if(navigator.share&&navigator.canShare&&navigator.canShare({files:[file]})){
        try{await navigator.share({files:[file],title:`Tabela de Preços – ${cliNome}`});}catch(e){}
      } else {
        const url=URL.createObjectURL(blob);
        const a=document.createElement('a');
        a.href=url; a.download=fileName; a.click();
        URL.revokeObjectURL(url);
        alert('✅ Imagem salva! Envie o arquivo via WhatsApp.');
      }
      btn.innerHTML='📷 Imagem WhatsApp'; btn.disabled=false;
    },'image/png');
  }catch(e){
    box.style.display='none';
    btn.innerHTML='📷 Imagem WhatsApp'; btn.disabled=false;
    alert('Erro: '+e.message);
  }
}

let _cliFiltroAtual='';

function filtrarTabelaCli(val){
  _cliFiltroAtual=(val!==undefined)?val:(document.getElementById('cli-busca-nome')?.value||'');
  renderClientes();
}

function renderClientes(){
  
  
  try{ if(_syncClientes.limparDuplicatasExatas()){ try{fbSalvar();}catch(e){} } }catch(e){}
  const tbody=document.getElementById('tb-clientes-list');
  if(!tbody) return;
  const v=(_cliFiltroAtual||'').toLowerCase().trim();
  const lista=(v
    ? CLIENTES.filter((c,i)=>((c.cod||'C'+String(i+1).padStart(3,'0'))+' '+(c.nome||'')+' '+(c.cidade||'')+' '+(c.cnpj||'')+' '+(c.cpf||'')).toLowerCase().includes(v))
    : CLIENTES.slice()).sort((a,b)=>String(a.nome||'').localeCompare(String(b.nome||''),'pt-BR',{sensitivity:'base'}));
  if(!lista.length){
    tbody.innerHTML='<tr><td colspan="7" style="color:var(--gray);text-align:center;padding:20px">'+(v?'Nenhum cliente encontrado para "'+esc(v)+'"':'Nenhum cliente cadastrado ainda')+'</td></tr>';
    return;
  }
  const _isEl=_usuarioAtualEhAdmin();
  tbody.innerHTML=lista.map((c,i)=>{
    const realIdx=CLIENTES.indexOf(c);
    return '<tr>'+
      '<td>'+(c.cod||'C'+String(realIdx+1).padStart(3,'0'))+'</td>'+
      '<td><b>'+esc(c.nome)+'</b></td>'+
      '<td>'+esc(c.cnpj||c.cpf||'—')+'</td>'+
      '<td>'+esc(c.tel||'—')+'</td>'+
      '<td>'+esc(c.email||'—')+'</td>'+
      '<td>'+esc(c.cidade||'—')+'</td>'+
      '<td style="white-space:nowrap">'+
        '<button class="btn-edit" onclick="editCliente('+realIdx+')">✏️ Editar</button> '+
        '<button class="btn-edit" onclick="cliDocsModal('+realIdx+')" title="Documentos" style="background:#0277bd;color:#fff">📄 Docs</button>'+
        (_isEl?' <button class="btn-edit-danger" onclick="excluirCliente('+realIdx+')" title="Excluir cliente">🗑️</button>':'')+
      '</td>'+
    '</tr>';
  }).join('');
}



function excluirCliente(idx){
  if(!_usuarioAtualEhAdmin()){ alert('Apenas a administradora pode excluir clientes.'); return; }
  const c=CLIENTES[idx]; if(!c) return;
  if(!confirm('Excluir o cliente "'+(c.nome||'')+'"?\n\nOs lançamentos já feitos com ele (vendas, contas a receber) continuam no histórico — ele só some da lista de clientes.')) return;
  const registro=Object.assign({},c);
  try{ _syncClientes.remover(idx); }catch(e){ CLIENTES.splice(idx,1); }
  saveClientes();
  try{ registrarHistorico('Cliente','Excluído','Cliente removido: '+(c.nome||''), registro, {cod:c.cod||''}); }catch(e){}
  renderClientes();
  showToast('Cliente "'+(c.nome||'')+'" excluído.','success');
}


function esc(s){ return String(s||'').replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/'/g,'&#39;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }







function _parseValorBR(v){
  let s=String(v==null?'':v).trim();
  if(!s) return 0;
  const hasComma=s.includes(','), hasDot=s.includes('.');
  if(hasComma && hasDot){
    s=s.replace(/\./g,'').replace(',','.');
  } else if(hasDot && !hasComma){
    const partes=s.split('.');
    const ultima=partes[partes.length-1];
    if(partes.length===2 && ultima.length<=2){
      s=partes[0].replace(/\./g,'')+'.'+ultima; 
    } else {
      s=s.replace(/\./g,''); 
    }
  } else if(hasComma && !hasDot){
    s=s.replace(',', '.');
  }
  const n=parseFloat(s);
  return isNaN(n)?0:n;
}




function _digits(v){ return String(v||'').replace(/\D/g,''); }
function _fmtCpf(v){
  const d=_digits(v).slice(0,11);
  return d.replace(/(\d{3})(\d)/,'$1.$2').replace(/(\d{3})(\d)/,'$1.$2').replace(/(\d{3})(\d{1,2})$/,'$1-$2');
}
function _fmtCnpj(v){
  const d=_digits(v).slice(0,14);
  return d.replace(/(\d{2})(\d)/,'$1.$2').replace(/(\d{3})(\d)/,'$1.$2').replace(/(\d{3})(\d)/,'$1/$2').replace(/(\d{4})(\d{1,2})$/,'$1-$2');
}
function _fmtCpfCnpj(v){
  const d=_digits(v);
  return d.length>11 ? _fmtCnpj(v) : _fmtCpf(v);
}

function _fmtTel(v){
  const d=_digits(v).slice(0,11);
  if(d.length<=2) return d.length?'('+d:'';
  if(d.length<=6) return '('+d.slice(0,2)+') '+d.slice(2);
  if(d.length<=10) return '('+d.slice(0,2)+') '+d.slice(2,6)+'-'+d.slice(6);
  return '('+d.slice(0,2)+') '+d.slice(2,3)+' '+d.slice(3,7)+'-'+d.slice(7);
}

function _fmtMoney(v){
  let d=_digits(v).replace(/^0+/,'')||'0';
  while(d.length<3) d='0'+d;
  const cent=d.slice(-2);
  const intFmt=d.slice(0,-2).replace(/\B(?=(\d{3})+(?!\d))/g,'.');
  return 'R$ '+intFmt+','+cent;
}
function _parseMoney(v){
  const d=_digits(v); if(!d) return 0;
  return parseInt(d,10)/100;
}

function _moneyFromNum(n){ return _fmtMoney(String(Math.round((Number(n)||0)*100))); }


function _fmtPix(v){
  const s=String(v||'');
  if(/[a-zA-Z@]/.test(s)) return s;            
  const d=_digits(s);
  if(!d) return '';
  if(d.length>11) return _fmtCnpj(d);          
  if(d.length===11) return d[2]==='9' ? _fmtTel(d) : _fmtCpf(d); 
  if(d.length===10) return _fmtTel(d);         
  return _fmtCpf(d);                            
}
document.addEventListener('input', function(e){
  const el=e.target;
  if(!el || !el.classList) return;
  let novo=null;
  if(el.classList.contains('mask-cpf')) novo=_fmtCpf(el.value);
  else if(el.classList.contains('mask-cnpj')) novo=_fmtCnpj(el.value);
  else if(el.classList.contains('mask-doc')) novo=_fmtCpfCnpj(el.value);
  else if(el.classList.contains('mask-tel')) novo=_fmtTel(el.value);
  else if(el.classList.contains('mask-money')) novo=_fmtMoney(el.value);
  else if(el.classList.contains('mask-upper')) novo=el.value.toUpperCase();
  else if(el.classList.contains('mask-pix')) novo=_fmtPix(el.value);
  else return;
  if(novo!==el.value){ el.value=novo; }
});



