function _digForn(s){ return String(s||'').replace(/\D/g,''); }
function importarFornecedores(input){
  const file=input && input.files && input.files[0];
  if(!file){ return; }
  _loadSheetJS(function(){
    const reader=new FileReader();
    reader.onload=function(e){
      try{
        const wb=XLSX.read(e.target.result,{type:'array',cellDates:false});
        const ws=wb.Sheets[wb.SheetNames[0]];
        const aoa=XLSX.utils.sheet_to_json(ws,{header:1,defval:''});
        if(!aoa.length){ alert('Planilha vazia.'); return; }
        const norm=function(s){ return String(s).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/[^a-z0-9]/g,''); };
        let hdr=0;
        for(let i=0;i<Math.min(6,aoa.length);i++){ if(aoa[i].some(function(c){return norm(c)==='nome';})){ hdr=i; break; } }
        const H=(aoa[hdr]||[]).map(norm);
        const find=function(fn){ return H.findIndex(fn); };
        const col={
          nome: find(function(h){return h==='nome';}),
          doc:  find(function(h){return h.indexOf('doc')>=0||h.indexOf('cpf')>=0||h.indexOf('cnpj')>=0;}),
          pix:  find(function(h){return h.indexOf('pix')>=0;}),
          banco:find(function(h){return h.indexOf('banco')>=0;}),
          agencia:find(function(h){return h.indexOf('agencia')>=0;}),
          conta:find(function(h){return h.indexOf('conta')>=0;}),
          rua:  find(function(h){return h.indexOf('rua')>=0||h.indexOf('logradouro')>=0||h.indexOf('endereco')>=0;}),
          num:  find(function(h){return h.indexOf('numero')>=0||h==='num'||h==='no';}),
          bairro:find(function(h){return h.indexOf('bairro')>=0;}),
          cidade:find(function(h){return h.indexOf('cidade')>=0;}),
          uf:   find(function(h){return h==='uf'||h.indexOf('estado')>=0;}),
          cep:  find(function(h){return h.indexOf('cep')>=0;}),
          obs:  find(function(h){return h.indexOf('observ')>=0||h==='obs';})
        };
        if(col.nome<0 && col.doc<0){ alert('Não encontrei as colunas "Nome" e "Doc (CPF/CNPJ)" na planilha. Confira o cabeçalho.'); return; }
        const rows=aoa.slice(hdr+1);
        const existDoc=new Set(FORNECEDORES.map(function(f){return _digForn(f.cpf)||_digForn(f.cnpj);}).filter(Boolean));
        const existNome=new Set(FORNECEDORES.map(function(f){return (f.nome||'').trim().toUpperCase();}).filter(Boolean));
        let max=0; FORNECEDORES.forEach(function(f){ const m=/^F(\d+)$/.exec(f.cod||''); if(m) max=Math.max(max,parseInt(m[1],10)); });
        const g=function(r,i){ return i>=0?String(r[i]||'').trim():''; };
        let add=0,dup=0,vazio=0;
        rows.forEach(function(r){
          const nome=g(r,col.nome).toUpperCase();
          const doc=g(r,col.doc);
          if(!nome && !doc){ vazio++; return; }
          const dg=_digForn(doc);
          if(dg && existDoc.has(dg)){ dup++; return; }
          if(!dg && nome && existNome.has(nome)){ dup++; return; }
          const isCnpj=dg.length===14;
          max++; const cod='F'+String(max).padStart(3,'0');
          const cidade=g(r,col.cidade), uf=g(r,col.uf);
          FORNECEDORES.push({ cod, nome,
            cpf: isCnpj?'':doc, cnpj: isCnpj?doc:'', rg:'', ie:'', tel:'', wpp:'', email:'',
            cep:g(r,col.cep), rua:g(r,col.rua), num:g(r,col.num), compl:'', bairro:g(r,col.bairro),
            cidade: (cidade+(uf?'/'+uf:'')).trim(),
            pix:g(r,col.pix), banco:g(r,col.banco), agencia:g(r,col.agencia), conta:g(r,col.conta),
            obs:g(r,col.obs), nota:'', docs:[] });
          if(dg) existDoc.add(dg);
          if(nome) existNome.add(nome);
          if(typeof PRECOS_FORN_DATA==='object' && PRECOS_FORN_DATA) PRECOS_FORN_DATA[cod]={};
          add++;
        });
        localStorage.setItem('mm_fornecedores_edit', JSON.stringify(
          FORNECEDORES.map(function(x){return {cod:x.cod,nome:x.nome,cpf:x.cpf,cnpj:x.cnpj,rg:x.rg,ie:x.ie,
            tel:x.tel,wpp:x.wpp,email:x.email,cep:x.cep,rua:x.rua,num:x.num,compl:x.compl,
            bairro:x.bairro,cidade:x.cidade,obs:x.obs,nota:x.nota,pix:x.pix,banco:x.banco,agencia:x.agencia,conta:x.conta,docs:x.docs||[]};})
        ));
        try{ fbSalvar(); }catch(_){}
        try{ renderTabelaFornecedores(); }catch(_){}
        try{ populateFornSelects(); }catch(_){}
        if(input) input.value='';
        alert('✅ Importação concluída!\n\n• '+add+' fornecedor(es) novo(s) adicionado(s)\n• '+dup+' já existiam (pulados, sem duplicar)\n• '+vazio+' linha(s) em branco ignorada(s)');
      }catch(err){ alert('Erro ao importar a planilha: '+((err&&err.message)||err)); }
    };
    reader.onerror=function(){ alert('Não consegui ler o arquivo.'); };
    reader.readAsArrayBuffer(file);
  });
}


function atualizarKpisFuncionarios(){
  const fmt=v=>_numFinito(v,0).toLocaleString('pt-BR',{minimumFractionDigits:2});
  const ativos=FUNCIONARIOS.filter(f=>f.status!=='Inativo');
  const inativos=FUNCIONARIOS.filter(f=>f.status==='Inativo');
  const gerentes=ativos.filter(f=>(f.cargo||'').toLowerCase().includes('gerente'));
  const supervisores=ativos.filter(f=>(f.cargo||'').toLowerCase().includes('supervisor'));
  const folhaTotal=ativos.reduce((s,f)=>s+Number(f.sal||0),0);
  const el=id=>document.getElementById(id);
  if(el('kpi-func-ativos')) el('kpi-func-ativos').textContent=ativos.length;
  if(el('kpi-func-gerente')) el('kpi-func-gerente').textContent=gerentes.length;
  if(el('kpi-func-gerente-sub')) el('kpi-func-gerente-sub').textContent=gerentes.length>0?'R$ '+Number(gerentes[0].sal||0).toLocaleString('pt-BR',{minimumFractionDigits:0}):'—';
  if(el('kpi-func-supervisores')) el('kpi-func-supervisores').textContent=supervisores.length;
  if(el('kpi-func-supervisores-sub')) el('kpi-func-supervisores-sub').textContent=supervisores.length>0?'R$ '+Number(supervisores[0].sal||0).toLocaleString('pt-BR',{minimumFractionDigits:0})+' cada':'—';
  if(el('kpi-func-folha')) el('kpi-func-folha').textContent='R$ '+fmt(folhaTotal);
}

let _funcSubTabAtual = 'ativos';

function funcSubTab(aba){
  _funcSubTabAtual = aba;
  const corAtivos='#1a3a2a', corInativos='#7b1fa2';
  const corAtiva = aba==='ativos' ? corAtivos : corInativos;
  ['ativos','inativos'].forEach(a=>{
    const panel = document.getElementById('func-subtab-'+a);
    const btn   = document.getElementById('func-stab-btn-'+a);
    if(!panel||!btn) return;
    if(a===aba){
      panel.style.display='';
      btn.style.background=corAtiva;
      btn.style.color='#fff';
      btn.style.borderColor=corAtiva;
      btn.style.borderBottom='none';
    } else {
      panel.style.display='none';
      btn.style.background='#f5f5f5';
      btn.style.color='#555';
      btn.style.borderColor='#ccc';
      btn.style.borderBottom='2px solid '+corAtiva;
    }
  });
  renderTbFuncionarios();
}

function _funcRow(x){
  return '<tr>'+
    '<td>'+x.mat+'</td><td><b>'+esc(x.nome)+'</b></td>'+
    '<td><span class="b b-'+x.status.toLowerCase()+'">'+x.status+'</span></td>'+
    '<td>'+esc(x.cargo)+'</td>'+
    '<td>R$ '+Number(x.sal).toLocaleString('pt-BR',{minimumFractionDigits:2})+'</td>'+
    '<td>'+esc(x.empresa||'—')+'</td>'+
    '<td style="font-size:.78rem">'+esc(x.cpf||'—')+'</td>'+
    '<td style="white-space:nowrap">'+
    '<button class="btn-edit" onclick="editFuncionario(&#39;'+x.mat+'&#39;)">✏️</button> '+
    '<button class="btn-edit" onclick="funcDocsModal(\''+x.mat+'\')" title="Documentos" style="background:#0277bd;color:#fff">📄 Docs</button> '+
    '<button class="btn-edit" onclick="toggleInativarFunc(&#39;'+x.mat+'&#39;)" style="background:'+(x.status==='Inativo'?'#27ae60':'#e67e22')+'" title="'+(x.status==='Inativo'?'Reativar':'Inativar')+'">'+(x.status==='Inativo'?'▶️ Reativar':'⏸️ Inativar')+'</button> '+
    '<button class="btn-edit-danger" onclick="excluirFuncionario(&#39;'+x.mat+'&#39;)" title="Excluir">🗑️</button>'+
    '</td></tr>';
}



let _funcSort={col:'mat',dir:1};
function funcSortBy(col){
  if(_funcSort.col===col) _funcSort.dir*=-1;
  else { _funcSort.col=col; _funcSort.dir=1; }
  renderTbFuncionarios();
}
function _funcCmp(a,b){
  const c=_funcSort.col, dir=_funcSort.dir;
  if(c==='sal'){ return ((Number(a.sal)||0)-(Number(b.sal)||0))*dir; }
  const va=String(a[c]==null?'':a[c]).toLowerCase();
  const vb=String(b[c]==null?'':b[c]).toLowerCase();
  return va.localeCompare(vb,'pt-BR',{numeric:true})*dir;
}
function _funcAtualizarSetas(){
  document.querySelectorAll('.fsort').forEach(function(th){
    let base=th.getAttribute('data-label');
    if(!base){ base=th.textContent.replace(/[▲▼]/g,'').trim(); th.setAttribute('data-label', base); }
    th.innerHTML=base+(th.getAttribute('data-col')===_funcSort.col ? ' <span style="font-size:.8em;color:#8fd19e">'+(_funcSort.dir>0?'▲':'▼')+'</span>' : '');
  });
}

function renderTbFuncionarios(){
  setTimeout(()=>renderFolha(),50);
  atualizarKpisFuncionarios();

  const ativos   = FUNCIONARIOS.filter(x=>x.status!=='Inativo').slice().sort(_funcCmp);
  const inativos = FUNCIONARIOS.filter(x=>x.status==='Inativo').slice().sort(_funcCmp);

  
  const ba=document.getElementById('func-badge-ativos');
  const bi=document.getElementById('func-badge-inativos');
  if(ba) ba.textContent=ativos.length;
  if(bi) bi.textContent=inativos.length;

  
  const tbA=document.getElementById('tb-funcionarios');
  if(tbA) tbA.innerHTML=ativos.length
    ? ativos.map(_funcRow).join('')
    : '<tr><td colspan="8" style="text-align:center;color:var(--gray);padding:20px">Nenhum funcionário ativo</td></tr>';

  
  const tbI=document.getElementById('tb-funcionarios-inativos');
  if(tbI) tbI.innerHTML=inativos.length
    ? inativos.map(_funcRow).join('')
    : '<tr><td colspan="8" style="text-align:center;color:var(--gray);padding:20px">Nenhum funcionário inativo</td></tr>';

  _funcAtualizarSetas();
}

function toggleInativarFunc(mat){
  const f=FUNCIONARIOS.find(x=>x.mat===mat);
  if(!f) return;
  const novoStatus = f.status==='Inativo' ? 'Ativo' : 'Inativo';
  if(!confirm((novoStatus==='Inativo'?'Inativar':'Reativar')+' funcionário '+f.nome+'?')) return;
  f.status=novoStatus;
  f._upd=Date.now(); 
  localStorage.setItem('mm_funcionarios_edit', JSON.stringify(FUNCIONARIOS));
  try{fbSalvar();}catch(e){}
  renderTbFuncionarios();
}

function excluirFuncionario(mat){
  const f=FUNCIONARIOS.find(x=>x.mat===mat);
  if(!f) return;
  if(!confirm('Excluir permanentemente o funcionário '+f.nome+'?\nSugestão: use ⏸️ Inativar para manter o histórico.')) return;
  const idx=FUNCIONARIOS.findIndex(x=>x.mat===mat);
  FUNCIONARIOS.splice(idx,1);
  try{
    const _fd=JSON.parse(localStorage.getItem('mm_funcedit_del')||'[]');
    if(_fd.indexOf(String(mat).toUpperCase())<0) _fd.push(String(mat).toUpperCase());
    localStorage.setItem('mm_funcedit_del', JSON.stringify(_fd));
  }catch(e){}
  localStorage.setItem('mm_funcionarios_edit', JSON.stringify(FUNCIONARIOS));
  try{fbSalvar();}catch(e){}
  renderTbFuncionarios();
  alert('✅ Funcionário excluído.');
}


function salvarNovoFuncionario(){
  const nome=(document.getElementById('nfu-nome')?.value||'').trim().toUpperCase();
  if(!nome){ showToast('Digite o nome do funcionário','error'); return; }
  const empresa=(document.getElementById('nfu-emp')?.value||'').trim();
  if(!empresa){ showToast('Selecione a empresa do funcionário','error'); return; }
  let maxN=0;
  FUNCIONARIOS.forEach(f=>{ const m=String(f.mat||'').match(/(\d+)/); if(m){ const n=parseInt(m[1]); if(n>maxN) maxN=n; } });
  const mat='F'+String(maxN+1).padStart(3,'0');
  const novo={
    mat, nome,
    cpf:(document.getElementById('nfu-cpf')?.value||'').trim(),
    empresa,
    cargo:(document.getElementById('nfu-cargo')?.value||'').trim(),
    sal:_parseMoney(document.getElementById('nfu-sal')?.value||''),
    valeTransporte:parseFloat(document.getElementById('nfu-vt')?.value)||0,
    nascimento:document.getElementById('nfu-nasc')?.value||'',
    admissao:document.getElementById('nfu-adm')?.value||'',
    fimExperiencia1:document.getElementById('nfu-fimexp1')?.value||'',
    fimExperiencia:document.getElementById('nfu-fimexp')?.value||'',
    expAvisarDias:(function(){ const n=parseInt(document.getElementById('nfu-expdias')?.value); return isNaN(n)?7:n; })(),
    tel:(document.getElementById('nfu-tel')?.value||'').trim(),
    adicional:parseFloat(document.getElementById('nfu-adicional')?.value)||0,
    abono:parseFloat(document.getElementById('nfu-abono')?.value)||0,
    banco:(document.getElementById('nfu-banco')?.value||'').trim(),
    status:document.getElementById('nfu-status')?.value||'Ativo'
  };
  novo._upd=Date.now();
  FUNCIONARIOS.push(novo);
  localStorage.setItem('mm_funcionarios_edit', JSON.stringify(FUNCIONARIOS));
  try{ fbSalvar(); }catch(e){}
  cm();
  try{ renderTbFuncionarios(); }catch(e){}
  showToast('✅ Funcionário '+mat+' — '+nome+' cadastrado!','success');
}





function _hojeISO(){ const d=new Date(); return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0'); }
function _diasEntreISO(a,b){ if(!a||!b) return null; const da=new Date(a+'T12:00:00'), db=new Date(b+'T12:00:00'); return Math.round((db-da)/86400000); }
function _coletarAlertas(){
  const hoje=_hojeISO(); let lista=[];
  (FUNCIONARIOS||[]).forEach(function(f){
    if(f.status==='Inativo') return;
    if(f.dataRescisao && _diasEntreISO(hoje, f.dataRescisao)<=0) return; 
    if(f.fimExperiencia1){
      lista.push({sourceTab:'funcionarios',mat:f.mat,nome:f.nome,tipo:'Fim do 1º período de experiência (45 dias)',data:f.fimExperiencia1,dias:_diasEntreISO(hoje,f.fimExperiencia1),aviso:(f.expAvisarDias!=null?f.expAvisarDias:7),key:f.mat+'|exp1|'+f.fimExperiencia1});
    }
    if(f.fimExperiencia){
      lista.push({sourceTab:'funcionarios',mat:f.mat,nome:f.nome,tipo:'Fim do 2º período de experiência (90 dias)',data:f.fimExperiencia,dias:_diasEntreISO(hoje,f.fimExperiencia),aviso:(f.expAvisarDias!=null?f.expAvisarDias:7),key:f.mat+'|exp|'+f.fimExperiencia});
    }
    (f.lembretes||[]).forEach(function(l,li){
      if(!l.d) return;
      lista.push({sourceTab:'funcionarios',mat:f.mat,nome:f.nome,tipo:l.t||'Lembrete',data:l.d,dias:_diasEntreISO(hoje,l.d),aviso:(l.a!=null?l.a:5),key:f.mat+'|lem'+li+'|'+l.d});
    });
  });
  
  try{
    (typeof DOCS_EMPRESAS!=='undefined'?DOCS_EMPRESAS:[]).forEach(function(d){
      if(!d||!d.validade) return;
      lista.push({sourceTab:'documentos_empresas',mat:null, nome:(d.empresaNome||'Empresa')+' — '+(d.categoria||'Documento'), tipo:'Vence documento: '+(d.nomeArq||d.categoria||''), data:d.validade, dias:_diasEntreISO(hoje,d.validade), aviso:(d.avisarDias!=null?d.avisarDias:30), key:'doc|'+d.id });
    });
  }catch(e){}
  
  
  try{
    lista=lista.filter(function(a){
      if(!a||!a.sourceTab) return false;
      if(typeof window.erpCanAccessTab==='function') return !!window.erpCanAccessTab(a.sourceTab);
      return !!(cu&&Array.isArray(cu.tabs)&&cu.tabs.includes(a.sourceTab));
    });
  }catch(e){ lista=[]; }
  return lista;
}
function _alertaVencendo(a){ return a.dias!=null && a.dias<=a.aviso && a.dias>=-7; }
function _alertasFallbackKey(base){ var u='anon'; try{ u=String(cuKey||'anon'); }catch(e){} return base+'_'+u; }

function _alertasVistos(){ try{ return JSON.parse(localStorage.getItem(_alertasFallbackKey('mm_alertas_vistos'))||'{}'); }catch(e){ return {}; } }
function _alertasParados(){ try{ return JSON.parse(localStorage.getItem(_alertasFallbackKey('mm_alertas_parados'))||'{}'); }catch(e){ return {}; } }
function _alertaPararUi(key, btn){
  try{ var p=_alertasParados(); p[key]=_hojeISO(); localStorage.setItem(_alertasFallbackKey('mm_alertas_parados'), JSON.stringify(p)); }catch(e){}
  try{ if(window._alertasAtuais) window._alertasAtuais=window._alertasAtuais.filter(function(a){return a.key!==key;}); }catch(e){}
  try{
    var card=btn&&btn.closest?btn.closest('.alerta-card'):null;
    if(card){ card.parentNode.removeChild(card); }
    var host=document.querySelector('.alerta-ov .alerta-lista');
    if(host && !host.querySelector('.alerta-card')){ document.querySelectorAll('.alerta-ov').forEach(function(e){e.remove();}); }
  }catch(e){}
  try{ showToast('Não vou mais avisar sobre esse item.','info'); }catch(e){}
}
function _alertasMarcarVistos(){
  try{ const v=_alertasVistos(), hoje=_hojeISO(); (window._alertasAtuais||[]).forEach(a=>{ v[a.key]=hoje; }); localStorage.setItem(_alertasFallbackKey('mm_alertas_vistos'), JSON.stringify(v)); }catch(e){}
}
function checarAlertas(forcar){
  const todos=_coletarAlertas(); let mostrar;
  const parados=_alertasParados();
  if(forcar){ mostrar=todos.filter(a=>a.dias!=null&&a.dias<=60).filter(a=>!parados[a.key]).sort((x,y)=>x.dias-y.dias); }
  else { const vistos=_alertasVistos(), hoje=_hojeISO(); mostrar=todos.filter(_alertaVencendo).filter(a=>vistos[a.key]!==hoje).filter(a=>!parados[a.key]).sort((x,y)=>x.dias-y.dias); }
  if(!mostrar.length){ if(forcar) showToast('Nenhum alerta nos próximos 60 dias. 👍','info'); return; }
  document.querySelectorAll('.alerta-ov').forEach(e=>e.remove());
  const ov=document.createElement('div'); ov.className='modal-ov alerta-ov open'; ov.dataset.dynamic='1'; ov.style.zIndex='100000';
  const body=document.createElement('div'); body.className='modal'; body.style.maxWidth='560px';
  const linhas=mostrar.map(function(a){
    let cor,txt;
    if(a.dias<0){ cor='#c0392b'; txt='venceu há '+Math.abs(a.dias)+' dia(s)'; }
    else if(a.dias===0){ cor='#c0392b'; txt='é HOJE'; }
    else { cor=a.dias<=3?'#e67e22':'#1a5e2a'; txt='em '+a.dias+' dia(s)'; }
    const dataBR=a.data.split('-').reverse().join('/');
    return '<div class="alerta-card" style="border-left:5px solid '+cor+';background:#fafafa;border-radius:8px;padding:10px 12px;margin-bottom:8px">'+
      '<div style="font-weight:800">'+esc(a.nome)+'</div>'+
      '<div style="font-size:.88rem;color:#333">'+esc(a.tipo)+' — <b>'+dataBR+'</b> <span style="color:'+cor+';font-weight:800">('+txt+')</span></div>'+
      '<div style="margin-top:6px;display:flex;gap:6px;flex-wrap:wrap">'+
      (a.mat?'<button onclick="cm();editFuncionario(&#39;'+a.mat+'&#39;)" style="background:#eef4f0;color:#1a5e2a;border:1.5px solid #cfe3d6;border-radius:7px;padding:5px 10px;font-weight:700;cursor:pointer;font-size:.8rem">✏️ Abrir funcionário</button>':'')+
      '<button onclick="_alertaPararUi(&#39;'+esc(a.key).replace(/&#39;/g,"\\&#39;")+'&#39;, this)" title="Não avisar mais sobre este item" style="background:#fff3f3;color:#c0392b;border:1.5px solid #f0c4c0;border-radius:7px;padding:5px 10px;font-weight:700;cursor:pointer;font-size:.8rem">🔕 Parar de avisar</button>'+
      '</div>'+
    '</div>';
  }).join('');
  body.innerHTML='<h3 style="color:#b45309">🔔 Alertas'+(forcar?' (próximos 60 dias)':' de hoje')+'</h3>'+
    '<div class="alerta-lista" style="max-height:52vh;overflow:auto;margin:10px 0">'+linhas+'</div>'+
    '<div class="modal-ft">'+(forcar?'':'<button class="btn-cancel" onclick="_alertasMarcarVistos();cm()">Ok, já vi (não mostrar hoje)</button>')+
    '<button class="btn-save" onclick="cm()">Fechar</button></div>';
  ov.appendChild(body); document.body.appendChild(ov);
  window._alertasAtuais=mostrar;
}





let LISTA_COMPRAS = [];
try{ LISTA_COMPRAS = JSON.parse(localStorage.getItem('mm_lista_compras')||'[]'); }catch(e){ LISTA_COMPRAS=[]; }
function lcSalvar(){ try{ localStorage.setItem('mm_lista_compras', JSON.stringify(LISTA_COMPRAS)); }catch(e){} }



function _lcGravar(item){ try{ if(window._fbDB && item && item.id) window._fbDB.ref('erp/listaCompras/'+item.id).set(item); }catch(e){} }
function _lcRemover(id){ try{ if(window._fbDB && id) window._fbDB.ref('erp/listaCompras/'+id).remove(); }catch(e){} }
function _lcPodeExcluir(){ return _usuarioAtualEhAdmin(); }
let _lcListenerOn=false;
function lcInit(){
  try{
    if(_lcListenerOn || !window._fbDB) return;
    _lcListenerOn=true;
    window._fbDB.ref('erp/listaCompras').on('value', function(snap){
      const v=snap.val();
      LISTA_COMPRAS = Array.isArray(v)? v.filter(Boolean) : (v?Object.values(v):[]);
      try{ localStorage.setItem('mm_lista_compras', JSON.stringify(LISTA_COMPRAS)); }catch(e){}
      try{ const p=document.getElementById('tab-lista_compras'); if(p && p.classList.contains('active')) renderListaCompras(); }catch(e){}
    });
  }catch(e){}
}
function lcAdd(){
  const nome=(document.getElementById('lc-nome')?.value||'').trim();
  if(!nome){ showToast('Digite o item','error'); return; }
  const item={ id:'lc_'+Date.now()+'_'+Math.floor(Math.random()*10000), nome:nome, qtd:(document.getElementById('lc-qtd')?.value||'').trim(), quem:(document.getElementById('lc-quem')?.value||'').trim()||(cu&&cu.name)||'', obs:(document.getElementById('lc-obs')?.value||'').trim(), status:'acomprar', criadoEm:new Date().toISOString().slice(0,10), compradoEm:'' };
  LISTA_COMPRAS.push(item);
  lcSalvar(); _lcGravar(item);
  ['lc-nome','lc-qtd','lc-quem','lc-obs'].forEach(id=>{ const el=document.getElementById(id); if(el) el.value=''; });
  renderListaCompras();
  showToast('Item adicionado à lista! 🛒','success');
}
function _lcItensFiltro(){
  const f=(document.getElementById('lc-filtro')||{}).value||'acomprar';
  return (LISTA_COMPRAS||[]).filter(Boolean).filter(function(it){
    if(f==='todos') return true;
    return (it.status||'acomprar')===f;
  });
}
function _lcTexto(){
  const f=(document.getElementById('lc-filtro')||{}).value||'acomprar';
  const rot=f==='comprado'?'COMPRADOS':(f==='todos'?'TODOS OS ITENS':'A COMPRAR');
  const itens=_lcItensFiltro();
  let t='🛒 *LISTA DE COMPRAS — ESCRITÓRIO* ('+rot+')\n';
  t+=_empresaPrincipalLabel()+' — '+new Date().toLocaleDateString('pt-BR')+'\n\n';
  if(!itens.length){ t+='(nenhum item)'; return t; }
  itens.forEach(function(it,i){
    t+=(i+1)+'. '+(it.nome||'')+(it.qtd?(' — '+it.qtd):'');
    if(it.quem) t+=' (pediu: '+it.quem+')';
    if(it.obs) t+='\n   Obs: '+it.obs;
    if((it.status||'')==='comprado') t+='\n   ✅ comprado'+(it.compradoEm?(' em '+String(it.compradoEm).split('-').reverse().join('/')):'');
    t+='\n';
  });
  return t;
}
function lcWhats(){
  const t=_lcTexto();
  window.open('https://wa.me/?text='+encodeURIComponent(t.replace(/🛒 \*|\*/g,function(m){return m;})),'_blank');
}
function lcImprimir(){
  const itens=_lcItensFiltro();
  const f=(document.getElementById('lc-filtro')||{}).value||'acomprar';
  const rot=f==='comprado'?'Comprados':(f==='todos'?'Todos os itens':'A comprar');
  const esc2=function(s){ return String(s==null?'':s).replace(/</g,'&lt;'); };
  let linhas=itens.map(function(it,i){
    return '<tr><td>'+(i+1)+'</td><td><b>'+esc2(it.nome)+'</b></td><td>'+esc2(it.qtd||'')+'</td><td>'+esc2(it.quem||'')+'</td><td>'+esc2(it.obs||'')+'</td><td>'+((it.status||'')==='comprado'?'✅':'🕒')+'</td></tr>';
  }).join('');
  if(!linhas) linhas='<tr><td colspan="6" style="text-align:center;color:#888">Nenhum item</td></tr>';
  const w=window.open('','_blank');
  if(!w){ showToast('O navegador bloqueou a janela de impressão — libere pop-ups pro site.','error'); return; }
  w.document.write('<html><head><title>Lista de Compras</title><style>body{font-family:Arial;padding:20px}h2{margin:0 0 4px}table{border-collapse:collapse;width:100%;margin-top:12px}th,td{border:1px solid #999;padding:6px 8px;font-size:13px;text-align:left}th{background:#eee}</style></head><body>'+
    '<h2>🛒 Lista de Compras — Escritório</h2><div>'+rot+' · '+esc(_empresaPrincipalLabel())+' · '+new Date().toLocaleDateString('pt-BR')+'</div>'+
    '<table><tr><th>#</th><th>Item</th><th>Qtd</th><th>Quem pediu</th><th>Obs</th><th>Status</th></tr>'+linhas+'</table>'+
    '</body></html>');
  w.document.close();
  w.focus();
  setTimeout(function(){ try{ w.print(); }catch(e){} },300);
}
function lcToggle(id){
  const it=LISTA_COMPRAS.find(x=>x.id===id); if(!it) return;
  if(it.status==='comprado'){ it.status='acomprar'; it.compradoEm=''; }
  else { it.status='comprado'; it.compradoEm=new Date().toISOString().slice(0,10); it.compradoPor=(cu&&cu.name)||''; }
  lcSalvar(); _lcGravar(it); renderListaCompras();
}
function lcExcluir(id){
  if(!_lcPodeExcluir()){ showToast('Só '+_usuarioAdminNome()+' pode excluir itens da lista.','error'); return; }
  const it=LISTA_COMPRAS.find(x=>x.id===id); if(!it) return;
  if(!confirm('Excluir "'+it.nome+'" da lista?')) return;
  const i=LISTA_COMPRAS.findIndex(x=>x.id===id); if(i>=0) LISTA_COMPRAS.splice(i,1);
  lcSalvar(); _lcRemover(id); renderListaCompras();
}
function renderListaCompras(){
  const tb=document.getElementById('lc-tbody'); if(!tb) return;
  const filtro=document.getElementById('lc-filtro')?.value||'acomprar';
  let lista=LISTA_COMPRAS.slice();
  if(filtro==='acomprar') lista=lista.filter(x=>x.status!=='comprado');
  else if(filtro==='comprado') lista=lista.filter(x=>x.status==='comprado');
  lista.sort((a,b)=>(a.status===b.status?0:(a.status==='comprado'?1:-1)));
  const dBR=iso=>iso?String(iso).split('-').reverse().join('/'):'—';
  if(!lista.length){ tb.innerHTML='<tr><td colspan="8" style="text-align:center;color:#999;padding:20px">Nenhum item '+(filtro==='comprado'?'comprado':(filtro==='acomprar'?'a comprar':''))+'.</td></tr>'; return; }
  const podeExcluir=_lcPodeExcluir();
  tb.innerHTML=lista.map(function(it){
    const comprado=it.status==='comprado';
    return '<tr style="'+(comprado?'opacity:.6':'')+'">'+
      '<td style="text-align:center"><input type="checkbox" '+(comprado?'checked':'')+' onclick="lcToggle(&#39;'+it.id+'&#39;)" title="Marcar como comprado"></td>'+
      '<td><b>'+esc(it.nome)+'</b></td>'+
      '<td>'+esc(it.qtd||'')+'</td>'+
      '<td>'+esc(it.quem||'')+'</td>'+
      '<td>'+esc(it.obs||'')+'</td>'+
      '<td>'+(comprado?'<span style="color:#1a7a43;font-weight:700">✅ Comprado</span>':'<span style="color:#e67e22;font-weight:700">🕒 A comprar</span>')+'</td>'+
      '<td>'+(comprado?dBR(it.compradoEm):'—')+'</td>'+
      '<td style="white-space:nowrap"><button class="btn-edit" onclick="lcToggle(&#39;'+it.id+'&#39;)">'+(comprado?'↩ Reabrir':'✅ Comprei')+'</button>'+(podeExcluir?' <button class="btn-edit-danger" onclick="lcExcluir(&#39;'+it.id+'&#39;)">🗑️</button>':'')+'</td>'+
    '</tr>';
  }).join('');
}






function funcImprimirModal(){
  document.querySelectorAll('.modal-ov[data-dynamic="1"]').forEach(e=>e.remove());
  const ov=document.createElement('div'); ov.className='modal-ov'; ov.id='modal-ov'; ov.dataset.dynamic='1';
  const body=document.createElement('div'); body.id='modal-body'; body.className='modal';
  ov.appendChild(body); document.body.appendChild(ov);
  const funcOpts=FUNCIONARIOS.slice().sort((a,b)=>String(a.nome||'').localeCompare(String(b.nome||''),'pt-BR')).map(f=>'<option value="'+f.mat+'">'+esc(f.mat+' — '+(f.nome||''))+'</option>').join('');
  const chk=(id,lbl,on)=>'<label style="display:inline-flex;align-items:center;gap:6px;margin:3px 12px 3px 0;font-size:.85rem"><input type="checkbox" id="'+id+'"'+(on?' checked':'')+'> '+lbl+'</label>';
  body.innerHTML=
    '<h3>🖨️ Imprimir / Relatório de Funcionários</h3>'+
    '<div class="fg"><label>O que imprimir?</label>'+
      '<select id="rel-escopo" onchange="_relToggle()">'+
        '<option value="todos">Lista de funcionários</option>'+
        '<option value="um">Ficha de um funcionário só</option>'+
      '</select></div>'+
    '<div id="rel-um-box" style="display:none"><div class="fg"><label>Funcionário</label><select id="rel-func">'+funcOpts+'</select></div></div>'+
    '<div id="rel-todos-box">'+
      '<label style="font-size:.72rem;font-weight:700;color:#555;text-transform:uppercase">Colunas a incluir <span style="font-weight:400;text-transform:none;color:#999">(o Nome sempre aparece)</span></label>'+
      '<div style="margin:6px 0 10px">'+
        chk('rel-c-cargo','Cargo',true)+chk('rel-c-empresa','Empresa',true)+chk('rel-c-sal','Salário',true)+
        chk('rel-c-cpf','CPF',false)+chk('rel-c-tel','Telefone',false)+chk('rel-c-adm','Admissão',false)+
        chk('rel-c-nasc','Aniversário',false)+chk('rel-c-pix','PIX / Banco',false)+chk('rel-c-status','Status',false)+chk('rel-c-resc','Rescisão',false)+
      '</div>'+
      '<div style="border-top:1px dashed #ddd;padding-top:8px">'+
        chk('rel-agrupar','Agrupar por empresa',false)+chk('rel-soativos','Somente ativos',true)+
      '</div>'+
    '</div>'+
    '<div class="modal-ft"><button class="btn-cancel" onclick="cm()">Cancelar</button><button class="btn-save" onclick="funcGerarRelatorio()">🖨️ Gerar PDF / Imprimir</button></div>';
  ov.classList.add('open');
}
function _relToggle(){
  const um=document.getElementById('rel-escopo').value==='um';
  const u=document.getElementById('rel-um-box'), t=document.getElementById('rel-todos-box');
  if(u) u.style.display=um?'':'none';
  if(t) t.style.display=um?'none':'';
}
function funcGerarRelatorio(){
  const empHdr=(typeof CFG_EMPRESA!=='undefined'&&CFG_EMPRESA.nome)||_empresaPrincipalLabel();
  const fmtR=v=>'R$ '+Number(v||0).toLocaleString('pt-BR',{minimumFractionDigits:2});
  const dBR=iso=>iso?String(iso).split('-').reverse().join('/'):'';
  const aniv=iso=>{ if(!iso) return ''; const p=String(iso).split('-'); return p.length===3?(p[2]+'/'+p[1]):dBR(iso); };
  const head='<style>body{font-family:Arial,sans-serif;font-size:12px;padding:20px;color:#111}h1{font-size:18px;color:#1a3a2a;margin:0 0 2px}.sub{color:#666;font-size:12px;margin-bottom:10px}table{width:100%;border-collapse:collapse;margin-bottom:12px}th,td{border:1px solid #ccc;padding:5px 7px;font-size:11px;text-align:left}th{background:#eee}h2{font-size:14px;color:#1a5c35;margin:14px 0 4px}.tot td{font-weight:800;background:#f3f7f4}</style>';
  const win=window.open('','_blank','width=980,height=720');
  if(!win){ showToast('Permita pop-ups no navegador para gerar o PDF.','error',5000); return; }
  const escopo=document.getElementById('rel-escopo').value;
  if(escopo==='um'){
    const mat=document.getElementById('rel-func').value;
    const f=FUNCIONARIOS.find(x=>x.mat===mat);
    if(!f){ showToast('Funcionário não encontrado','error'); return; }
    const linha=(lbl,val)=>val?('<tr><td style="width:210px;background:#f7f7f7;font-weight:700">'+lbl+'</td><td>'+esc(String(val))+'</td></tr>'):'';
    let alertas='';
    if(f.fimExperiencia1) alertas+='<div>Fim do 1º período (45d): <b>'+dBR(f.fimExperiencia1)+'</b></div>';
    if(f.fimExperiencia) alertas+='<div>Fim de experiência (90d): <b>'+dBR(f.fimExperiencia)+'</b></div>';
    (f.lembretes||[]).forEach(l=>{ if(l&&l.d) alertas+='<div>'+esc(l.t||'Lembrete')+': <b>'+dBR(l.d)+'</b></div>'; });
    win.document.write('<!DOCTYPE html><html><head><meta charset="utf-8"><title>Ficha - '+esc(f.nome||'')+'</title>'+head+'</head><body>'+
      '<h1>Ficha do Funcionário</h1><div class="sub">'+esc(empHdr)+'</div>'+
      '<table>'+
        linha('Matrícula',f.mat)+linha('Nome',f.nome)+linha('CPF',f.cpf)+linha('Cargo',f.cargo)+linha('Empresa',f.empresa)+
        linha('Status',f.status)+linha('Salário Base',f.sal?fmtR(f.sal):'')+linha('Telefone',f.tel)+
        linha('Nascimento',dBR(f.nascimento))+linha('Admissão',dBR(f.admissao))+linha('Rescisão',dBR(f.dataRescisao))+
        linha('Dados Bancários / PIX',f.banco)+
      '</table>'+
      (alertas?('<h2>🔔 Alertas</h2><div style="font-size:12px;line-height:1.6">'+alertas+'</div>'):'')+
      '<script>window.onload=function(){window.print()}<\/script></body></html>');
    win.document.close(); return;
  }
  
  const cols=[{lbl:'Nome',fn:f=>esc(f.nome||'')}];
  const add=(id,lbl,fn)=>{ const el=document.getElementById(id); if(el&&el.checked) cols.push({lbl:lbl,fn:fn}); };
  add('rel-c-cargo','Cargo',f=>esc(f.cargo||''));
  add('rel-c-empresa','Empresa',f=>esc(f.empresa||''));
  add('rel-c-sal','Salário',f=>f.sal?fmtR(f.sal):'');
  add('rel-c-cpf','CPF',f=>esc(f.cpf||''));
  add('rel-c-tel','Telefone',f=>esc(f.tel||''));
  add('rel-c-adm','Admissão',f=>dBR(f.admissao));
  add('rel-c-nasc','Aniversário',f=>aniv(f.nascimento));
  add('rel-c-pix','PIX / Banco',f=>esc(f.banco||''));
  add('rel-c-status','Status',f=>esc(f.status||''));
  add('rel-c-resc','Rescisão',f=>dBR(f.dataRescisao));
  const soAtivos=document.getElementById('rel-soativos').checked;
  const agrupar=document.getElementById('rel-agrupar').checked;
  let lista=FUNCIONARIOS.slice();
  if(soAtivos) lista=lista.filter(f=>f.status!=='Inativo');
  lista.sort((a,b)=>String(a.nome||'').localeCompare(String(b.nome||''),'pt-BR'));
  const idxSal=cols.findIndex(c=>c.lbl==='Salário');
  const tabela=(arr)=>{
    const th='<tr>'+cols.map(c=>'<th>'+c.lbl+'</th>').join('')+'</tr>';
    const corpo=arr.map(f=>'<tr>'+cols.map(c=>'<td>'+(c.fn(f)||'')+'</td>').join('')+'</tr>').join('');
    let tot='';
    if(idxSal>=0){ const soma=arr.reduce((s,f)=>s+(Number(f.sal)||0),0);
      tot='<tr class="tot">'+cols.map((c,i)=>i===0?'<td>TOTAL ('+arr.length+')</td>':(i===idxSal?'<td>'+fmtR(soma)+'</td>':'<td></td>')).join('')+'</tr>'; }
    return '<table><thead>'+th+'</thead><tbody>'+corpo+tot+'</tbody></table>';
  };
  let corpo='';
  if(agrupar){
    const emps=Array.from(new Set(lista.map(f=>f.empresa||'—'))).sort((a,b)=>a.localeCompare(b,'pt-BR'));
    emps.forEach(e=>{ const arr=lista.filter(f=>(f.empresa||'—')===e); corpo+='<h2>'+esc(e)+' — '+arr.length+' funcionário(s)</h2>'+tabela(arr); });
  } else { corpo=tabela(lista); }
  win.document.write('<!DOCTYPE html><html><head><meta charset="utf-8"><title>Lista de Funcionários</title>'+head+'</head><body>'+
    '<h1>Lista de Funcionários</h1><div class="sub">'+esc(empHdr)+' · '+lista.length+' funcionário(s)'+(soAtivos?' (somente ativos)':'')+'</div>'+
    corpo+'<script>window.onload=function(){window.print()}<\/script></body></html>');
  win.document.close();
}

function editFuncionario(mat){
  const idx=FUNCIONARIOS.findIndex(x=>x.mat===mat);
  if(idx<0) return;
  const f=FUNCIONARIOS[idx];
  const body=document.getElementById('modal-body');
  body.className='modal';
  const empOpts=_cfgEmployeeCompanyOptionsHtml(f.empresa||'');
  const stOpts=['Ativo','Inativo','Férias','Afastado'].map(s=>'<option value="'+s+'"'+(f.status===s?' selected':'')+'>'+s+'</option>').join('');
  body.innerHTML=
    '<h3>✏️ Editar Funcionário</h3>'+
    '<input type="hidden" id="efn-idx" value="'+idx+'">'+
    '<div class="fg"><label>Matrícula</label><input value="'+esc(f.mat)+'" readonly style="background:#f5f5f5;color:#888"></div>'+
    '<div class="fg"><label>Nome Completo</label><input id="efn-nome" class="mask-upper" value="'+esc(f.nome)+'"></div>'+
    '<div class="fg"><label>CPF</label><input id="efn-cpf" class="mask-cpf" value="'+esc(f.cpf)+'"></div>'+
    '<div class="fg"><label>Empresa</label><select id="efn-emp">'+empOpts+'</select></div>'+
    '<div class="fg"><label>Cargo</label><input id="efn-cargo" value="'+esc(f.cargo)+'"></div>'+
    '<div class="fg"><label>Salário Base R$</label><input id="efn-sal" class="mask-money" inputmode="numeric" value="'+(f.sal?_moneyFromNum(f.sal):'')+'" placeholder="R$ 0,00"></div>'+
    '<div class="fg"><label>Adicional Fixo R$ <small style="color:#888">(periculosidade, quebra de caixa etc.)</small></label><input id="efn-adicional" type="number" min="0" step="0.01" value="'+(f.adicional||0)+'"></div>'+
    '<div class="fg"><label>Abono Assiduidade R$ <small style="color:#888">(pago quando não tem falta/atestado)</small></label><input id="efn-abono" type="number" min="0" step="0.01" value="'+(f.abono||0)+'"></div>'+
    '<div class="fg"><label>Vale Transporte R$ <small style="color:#888">(valor mensal)</small></label><input id="efn-vt" type="number" min="0" step="0.01" value="'+(f.valeTransporte||0)+'"></div>'+
    '<div class="fg"><label>Status</label><select id="efn-status">'+stOpts+'</select></div>'+
    '<div class="fg"><label>Telefone / Celular</label><input id="efn-tel" class="mask-tel" value="'+esc(f.tel||'')+'" placeholder="(47) 9 9999-9999"></div>'+
    '<div class="fg"><label>Data de Nascimento</label><input id="efn-nasc" type="date" value="'+esc(f.nascimento||'')+'"></div>'+
    '<div class="fg"><label>Data de Admissão</label><input id="efn-adm" type="date" value="'+esc(f.admissao||'')+'"></div>'+
    '<div class="fg"><label>Data de Rescisão <small style="color:#888">(deixe em branco se ainda está trabalhando)</small></label><input id="efn-resc" type="date" value="'+esc(f.dataRescisao||'')+'"></div>'+
    '<div style="background:#fff8e1;border:1.5px solid #f0c36d;border-radius:10px;padding:12px 14px;margin:12px 0">'+
      '<div style="font-weight:800;color:#8a6d0b;margin-bottom:8px">🔔 Alertas deste funcionário</div>'+
      '<div id="efn-alertas-resumo" style="background:#fffdf5;border:1px solid #eadb9e;border-radius:8px;padding:8px 10px;margin-bottom:10px;font-size:.82rem">'+_efnResumoAlertas(f)+'</div>'+
      '<div class="fg"><label>Fim do 1º período de experiência <small style="color:#888">(45 dias)</small></label>'+
        '<input id="efn-fimexp1" type="date" value="'+esc(f.fimExperiencia1||'')+'"></div>'+
      '<div class="fg"><label>Fim do 2º período / fim da experiência <small style="color:#888">(90 dias)</small></label>'+
        '<div style="display:flex;gap:8px;align-items:center">'+
          '<input id="efn-fimexp" type="date" value="'+esc(f.fimExperiencia||'')+'" style="flex:1">'+
          '<button type="button" onclick="_efnCalcExp()" style="white-space:nowrap;background:#eef4f0;color:#1a5e2a;border:1.5px solid #cfe3d6;border-radius:8px;padding:8px 10px;font-weight:700;cursor:pointer;font-size:.8rem" title="Preenche as DUAS datas: 45 dias e 90 dias após a admissão">📅 45+45 dias</button>'+
        '</div>'+
        '<div style="font-size:.72rem;color:#a08a4a;margin-top:4px">O botão preenche as duas datas a partir da admissão. Você é avisada nas duas.</div></div>'+
      '<div class="fg"><label>Avisar quantos dias antes</label><input id="efn-expdias" type="number" min="0" step="1" value="'+(f.expAvisarDias!=null?f.expAvisarDias:7)+'" style="width:120px"></div>'+
      '<div style="border-top:1px dashed #e0c98a;margin:10px 0 8px"></div>'+
      '<label style="font-size:.72rem;font-weight:700;color:#8a6d0b;text-transform:uppercase">Outros lembretes (você define a data)</label>'+
      '<div id="efn-lemb-list" style="margin-top:6px"></div>'+
      '<button type="button" onclick="_efnAddLembrete()" style="margin-top:6px;background:#8a6d0b;color:#fff;border:none;border-radius:8px;padding:7px 12px;font-weight:700;cursor:pointer;font-size:.82rem">➕ Adicionar lembrete</button>'+
    '</div>'+
    '<div class="fg"><label>Dados Bancários / PIX</label><textarea id="efn-banco" rows="2" placeholder="Banco, agência, conta, PIX...">'+esc(f.banco||'')+'</textarea></div>'+
    '<div class="modal-ft"><button class="btn-cancel" onclick="cm()">Cancelar</button><button class="btn-save" onclick="salvarEditFuncionario()">💾 Salvar</button></div>';
  _efnLembretes = Array.isArray(f.lembretes) ? f.lembretes.map(l=>({t:l.t||'',d:l.d||'',a:(l.a!=null?l.a:5)})) : [];
  _efnRenderLembretes();
  document.getElementById('modal-ov').classList.add('open');
}



function _efnResumoAlertas(f){
  const hoje=(typeof _hojeISO==='function')?_hojeISO():new Date().toISOString().slice(0,10);
  const linhas=[];
  const fmtBR=iso=>iso?iso.split('-').reverse().join('/'):'';
  const faltam=iso=>{ try{ const d=(typeof _diasEntreISO==='function')?_diasEntreISO(hoje,iso):null; if(d==null) return ''; return d<0?(' (venceu há '+Math.abs(d)+' dia(s))'):(d===0?' (é hoje)':(' (faltam '+d+' dia(s))')); }catch(e){ return ''; } };
  if(f.fimExperiencia1) linhas.push('📌 Fim do 1º período (45d): <b>'+fmtBR(f.fimExperiencia1)+'</b>'+faltam(f.fimExperiencia1));
  if(f.fimExperiencia) linhas.push('📌 Fim da experiência (90d): <b>'+fmtBR(f.fimExperiencia)+'</b>'+faltam(f.fimExperiencia));
  (f.lembretes||[]).forEach(function(l){ if(l&&l.d) linhas.push('🔔 '+(l.t?esc(l.t):'Lembrete')+': <b>'+fmtBR(l.d)+'</b>'+faltam(l.d)); });
  if(!linhas.length) return '<span style="color:#a08a4a">Nenhum alerta ativo ainda. Preencha abaixo e clique em 💾 Salvar.</span>';
  return '<div style="font-weight:700;color:#8a6d0b;margin-bottom:4px">✅ Alertas ativos:</div>'+linhas.map(l=>'<div style="margin:2px 0">'+l+'</div>').join('');
}


let _efnLembretes = [];
function _efnLerInputs(){
  const box=document.getElementById('efn-lemb-list'); if(!box) return;
  box.querySelectorAll('[data-lemb]').forEach(function(row){
    const i=parseInt(row.getAttribute('data-lemb'));
    if(!_efnLembretes[i]) return;
    _efnLembretes[i].t=row.querySelector('.lemb-t').value;
    _efnLembretes[i].d=row.querySelector('.lemb-d').value;
    _efnLembretes[i].a=parseInt(row.querySelector('.lemb-a').value)||0;
  });
}
function _efnRenderLembretes(){
  const box=document.getElementById('efn-lemb-list'); if(!box) return;
  if(!_efnLembretes.length){ box.innerHTML='<div style="font-size:.8rem;color:#a08a4a">Nenhum lembrete. Clique em “Adicionar lembrete”.</div>'; return; }
  box.innerHTML=_efnLembretes.map(function(l,i){
    return '<div data-lemb="'+i+'" style="display:flex;gap:6px;margin-bottom:6px;align-items:center">'+
      '<input class="lemb-t" value="'+esc(l.t||'')+'" placeholder="Ex.: Renovar ASO" style="flex:2;padding:6px 8px;border:1.5px solid #e0c98a;border-radius:6px;font-size:.82rem">'+
      '<input class="lemb-d" type="date" value="'+esc(l.d||'')+'" style="flex:1;padding:6px 8px;border:1.5px solid #e0c98a;border-radius:6px;font-size:.82rem">'+
      '<input class="lemb-a" type="number" min="0" value="'+(l.a!=null?l.a:5)+'" title="Dias antes de avisar" style="width:64px;padding:6px 8px;border:1.5px solid #e0c98a;border-radius:6px;font-size:.82rem">'+
      '<button type="button" onclick="_efnRemoveLembrete('+i+')" title="Remover" style="background:#fde8e8;color:#c0392b;border:none;border-radius:6px;padding:6px 9px;cursor:pointer">🗑️</button>'+
    '</div>';
  }).join('');
}
