function fdSalvarContrato(mat){
  const f=FUNCIONARIOS.find(x=>x.mat===mat);
  if(!f) return;
  const adm=document.getElementById('fd-adm'); if(adm) f.admissao=adm.value||'';
  const term=document.getElementById('fd-term'); if(term) f.fimExperiencia=term.value||'';
  const dias=document.getElementById('fd-termdias'); if(dias){ const n=parseInt(dias.value); f.expAvisarDias=isNaN(n)?7:n; }
  try{ localStorage.setItem('mm_funcionarios_edit', JSON.stringify(FUNCIONARIOS)); }catch(e){}
  try{ fbSalvar(); }catch(e){}
  showToast('Datas do contrato salvas.','success',2500);
}

async function fdAdicionarDoc(mat){
  const f=FUNCIONARIOS.find(x=>x.mat===mat);
  if(!f) return;
  if(!f.docs) f.docs=[];
  const cat  = document.getElementById('fd-cat')?.value||'Outros';
  const data = document.getElementById('fd-data')?.value||new Date().toISOString().slice(0,10);
  const nomeCustom=(document.getElementById('fd-nome')?.value||'').trim();
  const fileEl=document.getElementById('fd-file');
  const statusEl=document.getElementById('fd-status');
  if(!fileEl||!fileEl.files||!fileEl.files.length){alert('Selecione um arquivo ou foto.');return;}
  if(!window._fbDB){ alert('Sem conexão com a nuvem agora. Aguarde alguns segundos e tente de novo — os documentos são guardados na nuvem.'); return; }
  const files=Array.prototype.slice.call(fileEl.files);
  const imgs=files.filter(function(x){return (x.type||'').indexOf('image/')===0;});
  const naoImgs=files.filter(function(x){return (x.type||'').indexOf('image/')!==0;});
  function _ler(file){ return new Promise(function(res,rej){ const r=new FileReader(); r.onload=function(e){res(e.target.result);}; r.onerror=rej; r.readAsDataURL(file); }); }
  function _comprimir(dataUrl){ return new Promise(function(res){ try{ const img=new Image(); img.onload=function(){ let w=img.width,h=img.height; const M=1600; if(w>M||h>M){ const r=Math.min(M/w,M/h); w=Math.round(w*r); h=Math.round(h*r);} const cv=document.createElement('canvas'); cv.width=w; cv.height=h; cv.getContext('2d').drawImage(img,0,0,w,h); let out=cv.toDataURL('image/jpeg',0.82); if(out.length>4*1024*1024) out=cv.toDataURL('image/jpeg',0.6); res(out); }; img.onerror=function(){res(dataUrl);}; img.src=dataUrl; }catch(e){res(dataUrl);} }); }
  function _carregarJsPDF(){ return new Promise(function(res,rej){ if(window.jspdf&&window.jspdf.jsPDF) return res(); const sc=document.createElement('script'); sc.src='https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js'; sc.onload=function(){res();}; sc.onerror=function(){rej(new Error('Não consegui carregar o gerador de PDF (verifique a internet).'));}; document.head.appendChild(sc); }); }
  function _enviar(dataUrl, nomeArq, mime){
    if(dataUrl.length>28*1024*1024){ if(statusEl) statusEl.textContent=''; alert('Ficou grande demais mesmo depois de preparar. Tente com menos fotos ou fotos menores.'); return; }
    if(statusEl) statusEl.textContent='Enviando para a nuvem...';
    const docId='fd_'+Date.now()+'_'+Math.floor(Math.random()*100000);
    let _payload=dataUrl;
    if(dataUrl.length>4000000){ _payload={_partes:0}; const TAM=2000000; let nn=0; for(let i=0;i<dataUrl.length;i+=TAM){ _payload['p'+nn]=dataUrl.slice(i,i+TAM); nn++; } _payload._partes=nn; }
    window._fbDB.ref('erp/funcDocs/'+mat+'/'+docId).set(_payload)
      .then(function(){
        f.docs.push({ id:docId, nomeArq:nomeArq, categoria:cat, data:data, mimeType:mime, _nuvem:true });
        try{ localStorage.setItem('mm_funcionarios_edit', JSON.stringify(FUNCIONARIOS)); }catch(ex){}
        try{ fbSalvar(); }catch(ex){}
        if(statusEl) statusEl.textContent='';
        if(fileEl) fileEl.value='';
        funcDocsModal(mat);
        showToast('✅ Documento adicionado.','success',4000);
      })
      .catch(function(err){
        if(statusEl) statusEl.textContent='';
        alert('Não consegui enviar o documento para a nuvem: '+((err&&err.message)||err));
      });
  }
  try{
    
    if(files.length>1){
      if(naoImgs.length>0){ alert('Para juntar vários num documento só, selecione apenas FOTOS.\n\nPDF adicione um de cada vez.'); return; }
      if(statusEl) statusEl.textContent='Juntando as fotos num PDF...';
      await _carregarJsPDF();
      const JsPDF=window.jspdf.jsPDF;
      const pdf=new JsPDF({unit:'pt',format:'a4'});
      const pw=pdf.internal.pageSize.getWidth(), ph=pdf.internal.pageSize.getHeight();
      for(let k=0;k<imgs.length;k++){
        if(statusEl) statusEl.textContent='Preparando foto '+(k+1)+' de '+imgs.length+'...';
        let du=await _ler(imgs[k]);
        du=await _comprimir(du);
        const props=pdf.getImageProperties(du);
        const mg=18;
        const r=Math.min((pw-mg*2)/props.width, (ph-mg*2)/props.height);
        const iw=props.width*r, ih=props.height*r;
        if(k>0) pdf.addPage();
        pdf.addImage(du,'JPEG',(pw-iw)/2,(ph-ih)/2,iw,ih);
      }
      const pdfData=pdf.output('datauristring');
      const nomeFinal=(nomeCustom||(cat+' '+data)).replace(/[\\/:*?"<>|]/g,'-')+'.pdf';
      return _enviar(pdfData, nomeFinal, 'application/pdf');
    }
    
    const file=files[0];
    const ehImagem=(file.type||'').indexOf('image/')===0;
    if(!ehImagem && file.size>20*1024*1024){ alert('PDF muito grande (máximo 20 MB).\n\nDica: tire FOTOS do documento — o sistema junta e encolhe sozinho.'); return; }
    if(statusEl) statusEl.textContent=(ehImagem&&file.size>1500000)?'Encolhendo a foto...':'Enviando para a nuvem...';
    let dataUrl=await _ler(file);
    if(ehImagem && (file.size>1500000 || dataUrl.length>2000000)){ dataUrl=await _comprimir(dataUrl); }
    return _enviar(dataUrl, (nomeCustom||file.name), file.type||'application/octet-stream');
  }catch(err){
    if(statusEl) statusEl.textContent='';
    alert((err&&err.message)||'Erro ao preparar o documento.');
  }
}

function _fdAbrirDataUrl(d, dataUrl){
  if(!dataUrl){ showToast('Não consegui carregar o documento.','error'); return; }
  const win=window.open('','_blank');
  if(!win){showToast('Permita popups no navegador para visualizar.','error',5000);return;}
  if(/^https?:\/\//i.test(String(dataUrl))){ win.location.href=String(dataUrl); return; }
  if(d.mimeType&&d.mimeType.startsWith('image/')){
    win.document.write('<!DOCTYPE html><html><head><title>'+esc(d.nomeArq)+'</title><style>body{margin:0;background:#111;display:flex;justify-content:center}img{max-width:100%;height:auto}</style></head><body><img src="'+dataUrl+'" alt="'+esc(d.nomeArq)+'"></body></html>');
  } else {
    try{
      const byteStr=atob((dataUrl.split(',')[1])||'');
      const ab=new ArrayBuffer(byteStr.length); const ia=new Uint8Array(ab);
      for(let i=0;i<byteStr.length;i++) ia[i]=byteStr.charCodeAt(i);
      win.location.href=URL.createObjectURL(new Blob([ab],{type:d.mimeType}));
    }catch(e){ try{ win.document.write('Erro ao abrir o documento.'); }catch(_){} }
  }
}
function fdVerDoc(mat,idx){
  const f=FUNCIONARIOS.find(x=>x.mat===mat);
  const d=f&&f.docs?f.docs[idx]:null;
  if(!d){showToast('Documento não encontrado.','error');return;}
  if(d.base64){ _fdAbrirDataUrl(d, d.base64); return; } 
  if(!window._fbDB){ showToast('Sem conexão com a nuvem agora — tente de novo em instantes.','error'); return; }
  showToast('Carregando documento...','info',2500);
  window._fbDB.ref('erp/funcDocs/'+mat+'/'+d.id).once('value')
    .then(function(snap){
      let val=snap.val();
      if(val && typeof val==='object' && val._partes){ let junto=''; for(let i=0;i<val._partes;i++){ junto+=val['p'+i]||''; } val=junto; }
      _fdAbrirDataUrl(d, val);
    })
    .catch(function(){ showToast('Erro ao carregar o documento da nuvem.','error'); });
}

function fdExcluir(mat,idx){
  const f=FUNCIONARIOS.find(x=>x.mat===mat);
  if(!f||!f.docs||!f.docs[idx]) return;
  const d=f.docs[idx];
  if(!confirm('Excluir o documento "'+d.nomeArq+'"?')) return;
  f.docs.splice(idx,1);
  try{ localStorage.setItem('mm_funcionarios_edit', JSON.stringify(FUNCIONARIOS)); }catch(e){}
  try{fbSalvar();}catch(e){}
  try{ if(window._fbDB && d.id) window._fbDB.ref('erp/funcDocs/'+mat+'/'+d.id).remove(); }catch(e){}
  funcDocsModal(mat);
  showToast('Documento excluído.','success');
}


function fdRenomear(mat,idx){
  const f=FUNCIONARIOS.find(x=>x.mat===mat);
  if(!f||!f.docs||!f.docs[idx]) return;
  const d=f.docs[idx];
  const novo=prompt('Novo nome para o documento:', d.nomeArq||'');
  if(novo===null) return; 
  const nome=novo.trim();
  if(!nome) return;
  d.nomeArq=nome;
  try{ localStorage.setItem('mm_funcionarios_edit', JSON.stringify(FUNCIONARIOS)); }catch(e){}
  try{ fbSalvar(); }catch(e){}
  funcDocsModal(mat);
  showToast('Documento renomeado.','success');
}




function _migrarDocsFuncParaNuvem(cb){
  if(!window._fbDB || typeof FUNCIONARIOS==='undefined'){ cb&&cb(false); return; }
  let pend=0, mudou=false;
  FUNCIONARIOS.forEach(function(f){
    (f.docs||[]).forEach(function(d){
      if(d && d.base64){
        pend++;
        const id=d.id||('fd_'+Date.now()+'_'+Math.floor(Math.random()*100000)); d.id=id;
        const b64=d.base64;
        window._fbDB.ref('erp/funcDocs/'+f.mat+'/'+id).set(b64)
          .then(function(){ delete d.base64; d._nuvem=true; mudou=true; })
          .catch(function(){})
          .finally(function(){ pend--; if(pend===0){ if(mudou){ try{ localStorage.setItem('mm_funcionarios_edit', JSON.stringify(FUNCIONARIOS)); }catch(e){} try{ fbSalvar(); }catch(e){} } cb&&cb(mudou); } });
      }
    });
  });
  if(pend===0) cb&&cb(false);
}




function _migrarDocsEmpresaParaNuvem(cb){
  if(!window._fbDB || typeof DOCS_EMPRESAS==='undefined'){ cb&&cb(false); return; }
  let pend=0, mudou=false;
  DOCS_EMPRESAS.forEach(function(d){
    if(d && d.base64){
      pend++;
      const id=d.id||('de_'+Date.now()+'_'+Math.floor(Math.random()*100000)); d.id=id;
      const b64=d.base64;
      window._fbDB.ref('erp/empresaDocs/'+id).set(b64)
        .then(function(){ delete d.base64; d._nuvem=true; mudou=true; })
        .catch(function(){})
        .finally(function(){ pend--; if(pend===0){ if(mudou){ try{ _deSalvar(); }catch(e){} } cb&&cb(mudou); } });
    }
  });
  if(pend===0) cb&&cb(false);
}




function _entidadeDocsModal(entidade, nomeLabel, salvarFn){
  
  
  
  if(!entidade.docs) entidade.docs=[];

  function _renderLista(){
    const lst=document.getElementById('ed-lista');
    if(!lst) return;
    if(!entidade.docs.length){
      lst.innerHTML='<div style="color:#aaa;text-align:center;padding:20px;font-size:.88rem">Nenhum documento cadastrado</div>';
      return;
    }
    lst.innerHTML=entidade.docs.map((d,i)=>{
      const icone=d.mimeType&&d.mimeType.startsWith('image/')?'🖼️':'📄';
      return `<div style="display:flex;align-items:center;gap:10px;padding:8px 4px;border-bottom:1px solid #eee">
        <span style="font-size:1.4rem">${icone}</span>
        <div style="flex:1;min-width:0">
          <div style="font-weight:700;font-size:.85rem;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(d.nomeArq)}</div>
          <div style="font-size:.72rem;color:#888">${esc(d.categoria)} · ${d.data||'—'}</div>
        </div>
        <button onclick="_edVerDoc(${i})" title="Visualizar" style="padding:5px 9px;border:none;border-radius:6px;background:#1a3a2a;color:#fff;cursor:pointer">👁️</button>
        <button onclick="_edRenomear(${i})" title="Renomear" style="padding:5px 9px;border:none;border-radius:6px;background:#1565c0;color:#fff;cursor:pointer">✏️</button>
        <button onclick="_edExcluir(${i})" title="Excluir" style="padding:5px 9px;border:none;border-radius:6px;background:#c0392b;color:#fff;cursor:pointer">🗑️</button>
      </div>`;
    }).join('');
  }

  window._edVerDoc=function(i){
    const d=entidade.docs[i];
    if(!d){showToast('Documento não encontrado.','error');return;}
    if(d.base64){ _fdAbrirDataUrl(d,d.base64); return; } 
    if(!window._fbDB || !d.id){ showToast('Sem conexão com a nuvem agora — tente novamente.','error'); return; }
    showToast('Carregando documento...','info',2000);
    window._fbDB.ref('erp/empresaDocs/'+d.id).once('value')
      .then(function(snap){ _fdAbrirDataUrl(d,snap.val()); })
      .catch(function(){ showToast('Erro ao carregar o documento da nuvem.','error'); });
  };
  window._edExcluir=function(i){
    const d=entidade.docs[i];
    if(!d || !confirm('Excluir o documento "'+(d.nomeArq||'')+'"?')) return;
    const concluir=function(){
      entidade.docs.splice(i,1); salvarFn(); _renderLista(); showToast('Documento excluído.','success');
    };
    if(window._fbDB && d.id && !d.base64){
      window._fbDB.ref('erp/empresaDocs/'+d.id).remove().then(concluir).catch(function(e){
        showToast('Não foi possível excluir o arquivo da nuvem: '+((e&&e.message)||e),'error',6000);
      });
    } else concluir();
  };
  window._edRenomear=function(i){
    const d=entidade.docs[i]; if(!d) return;
    const novo=prompt('Novo nome para o documento:', d.nomeArq||'');
    if(novo===null) return;
    const nome=novo.trim(); if(!nome) return;
    d.nomeArq=nome; salvarFn(); _renderLista(); showToast('Documento renomeado.','success');
  };

  const cats=['Contrato','NF / Nota Fiscal','Alvará','Certidão','Procuração','RG / CNH','CNPJ','Foto','Outros'];
  const body=document.getElementById('modal-body');
  body.className='modal';
  body.innerHTML=`
    <h3>📄 Documentos — ${esc(nomeLabel)}</h3>
    <div id="ed-lista" style="margin-bottom:14px;max-height:280px;overflow-y:auto"></div>
    <div style="border-top:1.5px dashed #ccc;padding-top:12px">
      <div style="font-weight:700;font-size:.85rem;color:var(--primary);margin-bottom:8px">➕ Novo Documento</div>
      <div class="fg"><label>Categoria</label>
        <select id="ed-cat" style="width:100%">${cats.map(c=>`<option>${c}</option>`).join('')}</select>
      </div>
      <div class="fg"><label>Data do documento</label>
        <input type="date" id="ed-data" value="${_hojeISO()}">
      </div>
      <div class="fg"><label>Nome do documento <small style="color:#888">(opcional — se deixar em branco, usa o nome do arquivo)</small></label>
        <input type="text" id="ed-nome" placeholder="Ex: Alvará 2026, Contrato aluguel...">
      </div>
      <div class="fg"><label>Arquivo (PDF ou imagem, máx. 20 MB)</label>
        <input type="file" id="ed-file" accept=".pdf,image/*"
          style="padding:6px;border:1.5px dashed #ccc;border-radius:8px;width:100%;box-sizing:border-box;cursor:pointer">
        ${_btnFoto('ed-file')}
      </div>
      <div id="ed-status" style="font-size:.78rem;color:#888;margin-top:2px"></div>
    </div>
    <div class="modal-ft">
      <button class="btn-cancel" onclick="cm()">Fechar</button>
      <button class="btn-save" id="ed-btn-add">💾 Adicionar Doc</button>
    </div>`;
  document.getElementById('modal-ov').classList.add('open');
  _renderLista();

  document.getElementById('ed-btn-add').onclick=function(){
    const cat=document.getElementById('ed-cat')?.value||'Outros';
    const data=document.getElementById('ed-data')?.value||'';
    const fileEl=document.getElementById('ed-file');
    const statusEl=document.getElementById('ed-status');
    if(!fileEl||!fileEl.files||!fileEl.files[0]){alert('Selecione um arquivo.');return;}
    if(!window._fbDB){ alert('Sem conexão com a nuvem agora. Aguarde alguns segundos e tente novamente.'); return; }
    const file=fileEl.files[0];
    if(file.size>20*1024*1024){alert('Arquivo muito grande. Máximo: 20 MB.');return;}
    if(statusEl) statusEl.textContent='Enviando para a nuvem...';
    const reader=new FileReader();
    reader.onload=function(e){
      const nomeCustom=(document.getElementById('ed-nome')?.value||'').trim();
      const id='de_'+Date.now()+'_'+Math.floor(Math.random()*100000);
      
      
      window._fbDB.ref('erp/empresaDocs/'+id).set(e.target.result)
        .then(function(){
          entidade.docs.push({
            id:id, nomeArq:(nomeCustom||file.name), categoria:cat, data:data,
            mimeType:file.type||'application/octet-stream', _nuvem:true
          });
          salvarFn();
          if(statusEl) statusEl.textContent='';
          if(fileEl) fileEl.value='';
          _renderLista();
          showToast('✅ Documento adicionado: '+file.name,'success',4000);
        })
        .catch(function(err){ if(statusEl) statusEl.textContent=''; showToast('Erro ao enviar documento: '+((err&&err.message)||err),'error',7000); });
    };
    reader.onerror=function(){ if(statusEl) statusEl.textContent='Erro ao ler arquivo.'; };
    reader.readAsDataURL(file);
  };
}




function _migrarDocsEntidadesParaNuvem(cb){
  if(!window._fbDB){ cb&&cb(false); return; }
  const entidades=[];
  try{ (FORNECEDORES||[]).forEach(function(e){ entidades.push({tipo:'forn',e:e}); }); }catch(e){}
  try{ (CLIENTES||[]).forEach(function(e){ entidades.push({tipo:'cli',e:e}); }); }catch(e){}
  let pend=0, mudouF=false, mudouC=false;
  entidades.forEach(function(reg){
    const ent=reg.e; if(!ent||!Array.isArray(ent.docs)) return;
    ent.docs.forEach(function(d){
      if(!d||!d.base64) return;
      pend++;
      const id=d.id||('de_'+Date.now()+'_'+Math.floor(Math.random()*100000)); d.id=id;
      const b64=d.base64;
      window._fbDB.ref('erp/empresaDocs/'+id).set(b64)
        .then(function(){ delete d.base64; d._nuvem=true; if(reg.tipo==='forn') mudouF=true; else mudouC=true; })
        .catch(function(e){ console.warn('migração documento entidade:',e); })
        .finally(function(){
          pend--;
          if(pend===0){
            if(mudouF){ try{ fbSalvar(); }catch(e){} }
            if(mudouC){ try{ saveClientes(); }catch(e){} }
            cb&&cb(mudouF||mudouC);
          }
        });
    });
  });
  if(pend===0) cb&&cb(false);
}

