let ESTOQUE_DB = {};
METAIS.forEach(m => {
  ESTOQUE_DB[m] = {mat:m, inicial:0, entradas:0, saidas:0, precoVenda:0, obs:''};
});





const MATERIAIS_BASE = [];
function _mesclarMateriaisBase(){
  try{
    if(localStorage.getItem('mm_base_merged_v35')==='1') return;
    let add=0;
    MATERIAIS_BASE.forEach(function(m){
      if(typeof METAIS==='undefined') return;
      if(METAIS.includes(m)) return;
      
      try{ if(_DEL_SETS && _DEL_SETS.estoque && _DEL_SETS.estoque.has(m)) return; }catch(e){}
      METAIS.push(m);
      if(!ESTOQUE_DB[m]) ESTOQUE_DB[m]={mat:m,inicial:0,entradas:0,saidas:0,precoVenda:0,obs:''};
      add++;
    });
    if(typeof METAIS!=='undefined') METAIS.sort((a,b)=>a.localeCompare(b,'pt-BR'));
    try{ localStorage.setItem('mm_metais', JSON.stringify(METAIS)); }catch(e){}
    try{ localStorage.setItem('mm_estoque', JSON.stringify(ESTOQUE_DB)); }catch(e){}
    localStorage.setItem('mm_base_merged_v35','1');
    if(add>0){ try{ if(typeof fbSalvar==='function') fbSalvar(); }catch(e){} }
  }catch(e){ console.warn('mesclar materiais base:', e&&e.message); }
}

function saveEstoque(){
  
  
  try{ fbSalvar(); }catch(e){}
  try{ localStorage.setItem('mm_estoque', JSON.stringify(ESTOQUE_DB)); }catch(e){}
  try{ localStorage.setItem('mm_metais', JSON.stringify(METAIS)); }catch(e){}
  refreshMetaisGlobals();
}
function loadEstoque(){
  try{
    
    
    
    const cloudJaHidratou = (typeof _fbDadosCarregados!=='undefined' && _fbDadosCarregados===true);
    if(!cloudJaHidratou){
      const e=localStorage.getItem('mm_estoque');
      if(e){ const d=JSON.parse(e); Object.assign(ESTOQUE_DB,d); }
      const mSaved=localStorage.getItem('mm_metais');
      if(mSaved){
        const mArr=JSON.parse(mSaved);
        if(Array.isArray(mArr)&&mArr.length>0) METAIS=mArr;
        METAIS.forEach(m=>{ if(!ESTOQUE_DB[m]) ESTOQUE_DB[m]={mat:m,inicial:0,entradas:0,saidas:0,precoVenda:0,obs:''}; });
      }
    }
    _mesclarMateriaisBase();
    _dedupeMetais();
  }catch(ex){}
}

function getEntradasMaterial(mat){
  
  return Object.values(TICKETS_DB).reduce((s,tk)=>{
    return s + (tk.itens||[]).filter(it=>it.mat===mat).reduce((ss,it)=>ss+Number(it.pesoLiq||0),0);
  },0);
}

function getSaidasMaterial(mat){
  
  let s = VENDAS_DB.reduce((acc,vd)=>{
    return acc + (vd.itens||[]).filter(it=>it.mat===mat).reduce((ss,it)=>ss+Number(it.qt||0),0);
  },0);
  
  
  try{
    const alvo=String(mat||'').trim().toUpperCase();
    if(typeof FC_LANC==='object' && FC_LANC){
      Object.keys(FC_LANC).forEach(function(cli){
        (FC_LANC[cli]||[]).forEach(function(l){
          if(l && l.tipo==='entrega' && String(l.material||'').trim().toUpperCase()===alvo){
            s += Number(l.peso||0);
          }
        });
      });
    }
  }catch(e){}
  return s;
}





function _dedupeMetais(){
  try{
    if(typeof METAIS==='undefined' || !Array.isArray(METAIS)) return 0;
    var vistos={}, novos=[], removidos=0;
    METAIS.forEach(function(nome){
      var raw=String(nome);
      if(!raw.trim()){ removidos++; return; }        
      if(Object.prototype.hasOwnProperty.call(vistos,raw)){ removidos++; return; } 
      vistos[raw]=1; novos.push(raw);
    });
    if(removidos>0){
      METAIS.length=0;
      novos.sort(function(a,b){return a.localeCompare(b,'pt-BR');}).forEach(function(m){ METAIS.push(m); });
      try{ localStorage.setItem('mm_metais', JSON.stringify(METAIS)); }catch(e){}
      
      try{ if(typeof fbSalvar==='function') fbSalvar(); }catch(e){}
    }
    return removidos;
  }catch(e){ console.warn('dedupe metais:', e&&e.message); return 0; }
}
function refreshMetaisGlobals(){
  _dedupeMetais();
  try{ METAIS.sort(function(a,b){ return String(a).localeCompare(String(b),'pt-BR',{sensitivity:'base'}); }); }catch(e){}
  METAIS_OPTS=METAIS.map(m=>`<option>${m}</option>`).join('');
  METAIS_DATALIST=`<datalist id="metais-list">${METAIS.map(m=>`<option value="${m}">`).join('')}</datalist>`;
  
  ['metais-list','metais-list-mb','metais-list-bal'].forEach(dlId=>{
    const dl=document.getElementById(dlId);
    if(dl) dl.innerHTML=METAIS.map(m=>`<option value="${m}">`).join('');
  });
  
  
  try{
    const sel=document.getElementById('bal-material');
    if(sel){
      const atual=sel.value;
      sel.innerHTML='<option value="">— Selecione o Material —</option>'+METAIS.map(m=>`<option value="${m}">${m}</option>`).join('');
      if(atual && METAIS.includes(atual)) sel.value=atual;
    }
  }catch(e){}
}





function _recuperarMateriaisComMovimento(silent){
  try{
    const nomes=new Set();
    Object.values(TICKETS_DB||{}).forEach(function(tk){ (tk&&tk.itens||[]).forEach(function(it){ if(it&&it.mat) nomes.add(it.mat); if(it&&it.matBase) nomes.add(it.matBase); }); });
    (typeof VENDAS_DB!=='undefined'?VENDAS_DB:[]).forEach(function(vd){ (vd&&vd.itens||[]).forEach(function(it){ if(it&&it.mat) nomes.add(it.mat); }); });
    
    try{ Object.keys(ESTOQUE_DB||{}).forEach(function(k){ if(k) nomes.add(k); }); }catch(e){}
    let mudou=false;
    nomes.forEach(function(m){
      if(!m) return;
      if(METAIS.indexOf(m)<0){
        METAIS.push(m); mudou=true;
        
        try{ if(_DEL_SETS&&_DEL_SETS.estoque&&_DEL_SETS.estoque.has(m)){ _DEL_SETS.estoque.delete(m); localStorage.setItem(_DEL_LS_KEY.estoque, JSON.stringify([..._DEL_SETS.estoque])); } }catch(e){}
      }
      if(!ESTOQUE_DB[m]) ESTOQUE_DB[m]={mat:m,inicial:0,entradas:0,saidas:0,precoVenda:0,obs:''};
    });
    if(mudou){ try{ localStorage.setItem('mm_metais', JSON.stringify(METAIS)); }catch(e){} try{ refreshMetaisGlobals(); }catch(e){} if(!silent){ try{ saveEstoque(); }catch(e){} } }
    return mudou;
  }catch(e){ console.warn('recuperar materiais', e); return false; }
}




const _COND_SUFIXOS=['COM FERRO','100%','DL','DM','DF','LIMPO','SUJO','MISTO','PRENSADO','SOLTO','FERRO'];
function _baseMaterial(nome){
  let n=String(nome||'').trim().toUpperCase().replace(/\s+/g,' ');
  let mudou=true;
  while(mudou){ mudou=false;
    for(let i=0;i<_COND_SUFIXOS.length;i++){
      const suf=_COND_SUFIXOS[i];
      if(n.length>suf.length+1 && n.endsWith(' '+suf)){ n=n.slice(0, n.length-suf.length-1).trim(); mudou=true; }
    }
  }
  return n;
}
function renderEstoque(){
  const tbE=document.getElementById('tb-estoque');
  if(!tbE) return;
  try{ _recuperarMateriaisComMovimento(); }catch(e){}
  const fmt=v=>_numFinito(v,0).toLocaleString('pt-BR',{minimumFractionDigits:2});
  const _isEl=_usuarioAtualEhAdmin();
  
  const grupos={};
  METAIS.forEach(m=>{
    const base=_baseMaterial(m);
    const e=ESTOQUE_DB[m]||{inicial:0,saidas:0,precoVenda:0};
    if(!grupos[base]) grupos[base]={inicial:0,entradas:0,saidas:0,preco:0,membros:[]};
    const g=grupos[base];
    g.inicial+=Number(e.inicial||0);
    g.entradas+=getEntradasMaterial(m);
    g.saidas+=getSaidasMaterial(m)+Number(e.saidas||0);
    if(g.preco===0 && Number(e.precoVenda||0)>0) g.preco=Number(e.precoVenda);
    g.membros.push(m);
  });
  const bases=Object.keys(grupos).sort((a,b)=>a.localeCompare(b,'pt-BR'));
  const rows=bases.map(base=>{
    const g=grupos[base];
    
    const precoBase=Number((ESTOQUE_DB[base]||{}).precoVenda||0)||g.preco;
    const saldo=g.inicial+g.entradas-g.saidas;
    const valor=saldo*precoBase;
    const st=saldo>0?'b-ativo':saldo<0?'b-pend':'b-zerado';
    const stTxt=saldo>0?'OK':saldo<0?'NEGATIVO':'ZERADO';
    const nMembros=g.membros.length;
    return {saldo, entradasAuto:g.entradas, valor, html:
      '<tr>'+
      '<td><b>'+esc(base)+'</b>'+(nMembros>1?' <small style="color:#888;font-weight:400" title="'+esc(g.membros.join(', '))+'">('+nMembros+' formas)</small>':'')+'</td>'+
      '<td style="text-align:right">'+g.inicial.toFixed(1)+'</td>'+
      '<td style="text-align:right;color:var(--success)">'+g.entradas.toFixed(1)+'</td>'+
      '<td style="text-align:right;color:var(--danger)">'+g.saidas.toFixed(1)+'</td>'+
      '<td style="text-align:right;font-weight:800">'+saldo.toFixed(1)+' kg</td>'+
      '<td style="text-align:right">R$ '+fmt(precoBase)+'</td>'+
      '<td style="text-align:right">R$ '+fmt(valor)+'</td>'+
      '<td><span class="b '+st+'">'+stTxt+'</span></td>'+
      '<td style="white-space:nowrap"><button class="btn-edit" onclick="editEstoque(&#39;'+esc(base).replace(/'/g,"\\'")+'&#39;)">✏️ Editar</button>'+
      (_isEl?' <button class="btn-edit-danger" title="Excluir material do cadastro" onclick="excluirMaterial(&#39;'+esc(base).replace(/'/g,"\\'")+'&#39;)">🗑️</button>':'')+
      '</td>'+
    '</tr>'};
  });
  tbE.innerHTML=rows.map(r=>r.html).join('');
  
  const totalSaldo=rows.reduce((s,r)=>s+r.saldo,0);
  const totalEnt=rows.reduce((s,r)=>s+r.entradasAuto,0);
  const totalValor=rows.reduce((s,r)=>s+r.valor,0);
  const el=id=>document.getElementById(id);
  if(el('kpi-est-total-mat')) el('kpi-est-total-mat').textContent=bases.length;
  if(el('kpi-est-saldo')) el('kpi-est-saldo').textContent=totalSaldo.toFixed(1)+' kg';
  if(el('kpi-est-entradas')) el('kpi-est-entradas').textContent=totalEnt.toFixed(1)+' kg';
  if(el('kpi-est-valor')) el('kpi-est-valor').textContent='R$ '+fmt(totalValor);
}





function excluirMaterial(mat){
  if(!_usuarioAtualEhAdmin()){alert('Apenas a '+_usuarioAdminNome()+' pode excluir materiais do estoque.');return;}
  if(!mat||!METAIS.includes(mat)){alert('Material não encontrado.');return;}
  const e=ESTOQUE_DB[mat]||{mat,inicial:0,entradas:0,saidas:0,precoVenda:0,obs:''};
  const entradasAuto=getEntradasMaterial(mat);
  const saidasAuto=getSaidasMaterial(mat)+Number(e.saidas||0);
  const saldo=Number(e.inicial||0)+entradasAuto-saidasAuto;
  let msg='Excluir "'+mat+'" do cadastro de materiais do Estoque?';
  if(Math.abs(saldo)>0.001 || entradasAuto>0 || saidasAuto>0){
    msg='⚠️ "'+mat+'" tem movimentação registrada — saldo atual: '+saldo.toFixed(1)+' kg (entradas: '+entradasAuto.toFixed(1)+' kg, saídas: '+saidasAuto.toFixed(1)+' kg).\n\n'
      +'Excluir só remove esse material da lista do Estoque — as compras/vendas já lançadas com ele continuam existindo no histórico, só não vão mais aparecer somadas aqui.\n\n'
      +'Tem certeza que quer excluir mesmo assim?';
  }
  if(!confirm(msg)) return;
  const registro=Object.assign({},e,{mat});
  METAIS.splice(METAIS.indexOf(mat),1);
  _apagarChave('estoque', ESTOQUE_DB, mat);
  saveEstoque();
  registrarHistorico('Estoque','Excluído','Material removido do cadastro: '+mat+(saldo?' (saldo era '+saldo.toFixed(1)+' kg)':''), registro, null);
  renderEstoque();
  showToast('Material "'+mat+'" excluído do cadastro.','success');
}

function editEstoque(mat){
  const e=ESTOQUE_DB[mat]||{inicial:0,entradas:0,saidas:0,precoVenda:0,obs:''};
  document.querySelectorAll('.modal-ov[data-dynamic="1"]').forEach(e=>e.remove());
  const _ovE=document.createElement('div'); _ovE.className='modal-ov'; _ovE.id='modal-ov'; _ovE.dataset.dynamic='1';
  const body=document.createElement('div'); body.id='modal-body'; body.className='modal';
  _ovE.appendChild(body); document.body.appendChild(_ovE);
  body.innerHTML=
    '<h3>✏️ Editar Estoque – '+esc(mat)+'</h3>'+
    '<div class="fg" style="margin-bottom:10px"><label style="font-weight:700">Nome do Material</label>'+
    '<input id="ee-nome" value="'+esc(mat)+'" style="width:100%;padding:8px;border:2px solid #1a3a2a;border-radius:7px;font-size:.9rem;font-weight:700;box-sizing:border-box" placeholder="Nome do material">'+
    '</div>'+
    '<input type="hidden" id="ee-mat" value="'+esc(mat)+'">'+
    '<div style="background:#e8f5e9;border-radius:8px;padding:10px 14px;margin-bottom:12px;font-size:.82rem">'+
    '📦 Entradas automáticas (via Compras): <b>'+getEntradasMaterial(mat).toFixed(1)+' kg</b></div>'+
    '<div class="fg"><label>Estoque Inicial (kg)</label><input id="ee-ini" type="number" min="0" step="0.1" value="'+(e.inicial||0)+'"></div>'+
    '<div style="background:#fde8e8;border-radius:8px;padding:10px 14px;margin-bottom:12px;font-size:.82rem">'+
    '📤 Saídas automáticas (via Vendas): <b>'+getSaidasMaterial(mat).toFixed(1)+' kg</b></div>'+
    '<div class="fg"><label>Saídas manuais adicionais (kg)</label><input id="ee-sai" type="number" min="0" step="0.1" value="'+(e.saidas||0)+'"></div>'+
    '<div class="fg"><label>Preço de Venda R$/kg</label><input id="ee-pv" type="number" min="0" step="0.01" value="'+(e.precoVenda||0)+'"></div>'+
    '<div class="fg"><label>Observações</label><textarea id="ee-obs" rows="2">'+esc(e.obs||'')+'</textarea></div>'+
    '<div style="background:#e8f5e9;border-radius:8px;padding:10px 14px;margin-bottom:12px;font-size:.82rem">'+
    '📊 Saldo atual: <b>'+(Number(e.inicial)+getEntradasMaterial(mat)-(getSaidasMaterial(mat)+Number(e.saidas||0))).toFixed(1)+' kg</b></div>'+
    '<div class="modal-ft"><button class="btn-cancel" onclick="cm()">Cancelar</button>'+
    '<button class="btn-save" onclick="salvarEditEstoque()">💾 Salvar</button></div>';
  _ovE.classList.add('open');
}



function novoMaterial(){
  document.querySelectorAll('.modal-ov[data-dynamic="1"]').forEach(e=>e.remove());
  const _ovN=document.createElement('div'); _ovN.className='modal-ov'; _ovN.id='modal-ov'; _ovN.dataset.dynamic='1';
  const body=document.createElement('div'); body.id='modal-body'; body.className='modal';
  _ovN.appendChild(body); document.body.appendChild(_ovN);
  body.innerHTML=
    '<h3>➕ Cadastrar Novo Material</h3>'+
    '<div class="fg" style="margin-bottom:10px"><label style="font-weight:700">Nome do Material</label>'+
    '<input id="nm-nome" style="width:100%;padding:8px;border:2px solid #1a3a2a;border-radius:7px;font-size:.9rem;font-weight:700;box-sizing:border-box" placeholder="ex.: COBRE MISTO, ALUMÍNIO, FERRO"></div>'+
    '<div class="fg"><label>Estoque Inicial (kg) — opcional</label><input id="nm-ini" type="number" min="0" step="0.1" value="0"></div>'+
    '<div class="fg"><label>Preço de Venda R$/kg — opcional</label><input id="nm-pv" type="number" min="0" step="0.01" value="0"></div>'+
    '<div class="fg"><label>Observações — opcional</label><textarea id="nm-obs" rows="2"></textarea></div>'+
    '<div style="background:#e8f5e9;border-radius:8px;padding:10px 14px;margin-bottom:12px;font-size:.8rem;color:#1a5c35">As entradas e saídas de kg são preenchidas automaticamente pelas Compras e Vendas. Aqui você só cria o material e, se quiser, já informa o estoque inicial e o preço.</div>'+
    '<div class="modal-ft"><button class="btn-cancel" onclick="cm()">Cancelar</button>'+
    '<button class="btn-save" onclick="salvarNovoMaterial()">💾 Cadastrar</button></div>';
  _ovN.classList.add('open');
  setTimeout(function(){ try{ document.getElementById('nm-nome').focus(); }catch(e){} }, 60);
}

function salvarNovoMaterial(){
  const nome=(document.getElementById('nm-nome')?.value||'').trim().toUpperCase();
  if(!nome){ showToast('Digite o nome do material','error'); return; }
  if(typeof METAIS!=='undefined' && METAIS.includes(nome)){ showToast('Esse material já existe no cadastro','error'); return; }
  if(typeof METAIS!=='undefined') METAIS.push(nome);
  if(typeof METAIS!=='undefined') METAIS.sort((a,b)=>a.localeCompare(b,'pt-BR'));
  ESTOQUE_DB[nome]={
    mat:nome,
    inicial: parseFloat(document.getElementById('nm-ini').value)||0,
    entradas:0, saidas:0,
    precoVenda: parseFloat(document.getElementById('nm-pv').value)||0,
    obs: (document.getElementById('nm-obs').value||'').trim()
  };
  saveEstoque();
  renderEstoque();
  cm();
  showToast('✅ Material "'+nome+'" cadastrado!','success');
}

function salvarEditEstoque(){
  const matOld=document.getElementById('ee-mat').value;
  const matNew=(document.getElementById('ee-nome')?.value||matOld).trim().toUpperCase();
  if(!matNew){showToast('Nome não pode ficar vazio','error');return;}
  
  if(matNew!==matOld){
    const idx=METAIS.indexOf(matOld);
    if(idx!==-1) METAIS[idx]=matNew;
    else METAIS.push(matNew);
    
    const dados=ESTOQUE_DB[matOld]||{};
    ESTOQUE_DB[matNew]={...dados, mat:matNew};
    _apagarChave('estoque', ESTOQUE_DB, matOld);
  }
  if(!ESTOQUE_DB[matNew]) ESTOQUE_DB[matNew]={mat:matNew};
  ESTOQUE_DB[matNew].inicial    = parseFloat(document.getElementById('ee-ini').value)||0;
  ESTOQUE_DB[matNew].saidas     = parseFloat(document.getElementById('ee-sai').value)||0;
  ESTOQUE_DB[matNew].precoVenda = parseFloat(document.getElementById('ee-pv').value)||0;
  ESTOQUE_DB[matNew].obs        = document.getElementById('ee-obs').value.trim();
  saveEstoque();
  renderEstoque();
  cm();
  showToast('✅ '+(matNew!==matOld?'Renomeado para '+matNew+' e atualizado!':'Estoque de '+matNew+' atualizado!'),'success');
}





function _supLog(msg, tipo='info'){
  const log=document.getElementById('sup-log');
  if(!log) return;
  if(log.innerHTML.includes('Nenhuma operação')) log.innerHTML='';
  const cor=tipo==='ok'?'#a8ff78':tipo==='erro'?'#ff6b6b':tipo==='warn'?'#ffd93d':'#a8d8ea';
  const ts=new Date().toLocaleTimeString('pt-BR');
  log.innerHTML+=`<div style="color:${cor}">[${ts}] ${msg}</div>`;
  log.scrollTop=log.scrollHeight;
}










const CHQ_SEED = [];
var CHQ_CTRL = {};
var _chqDel = {};
var _chqInited = false;



var _CHQ_ENSURE = [];
var _chqFbanco = 'TODOS';
var _chqFsit = 'A';        
var _chqFbusca = '';
const _CHQ_SIT_LBL = {A:'A Compensar', C:'Compensado', X:'Cancelado'};

function _chqRef(){ const db=_supGetDB(); return db?db.ref('erp/chequesControle'):null; }
function _chqDelRef(){ const db=_supGetDB(); return db?db.ref('erp/chequesControle_del'):null; }
function _chqFmt(v){
  v = (typeof v==='number' && isFinite(v)) ? v : 0;
  return 'R$ '+v.toLocaleString('pt-BR',{minimumFractionDigits:2, maximumFractionDigits:2});
}
function _chqHojeBR(){ const d=new Date(); return String(d.getDate()).padStart(2,'0')+'/'+String(d.getMonth()+1).padStart(2,'0')+'/'+d.getFullYear(); }

function chqInit(){
  if(_chqInited) return;
  const db=_supGetDB();
  if(!db){ setTimeout(chqInit, 2000); return; }
  _chqInited=true;
  _chqDelRef().on('value', function(s){ _chqDel=s.val()||{}; });
  
  
  
  
  
  
  function _chqRepararBase(){
    _chqRef().once('value').then(function(s){
      var cur=s.val()||{};
      var falta={};
      CHQ_SEED.forEach(function(o){ if(!cur[o.id] && !_chqDel[o.id]) falta[o.id]=o; });
      _CHQ_ENSURE.forEach(function(o){ if(!cur[o.id] && !_chqDel[o.id]) falta[o.id]=o; });
      var ks=Object.keys(falta);
      if(ks.length){ _chqRef().update(falta).then(function(){ console.info('Cheques controle: '+ks.length+' incluídos/reparados.'); }).catch(function(e){ console.warn('reparo cheques',e); }); }
    }).catch(function(){});
  }
  _chqDelRef().once('value').then(function(s){ _chqDel=s.val()||{}; _chqRepararBase(); }).catch(function(){ _chqRepararBase(); });
  _chqRef().on('value', function(s){
    var v=s.val()||{}; var m={};
    Object.keys(v).forEach(function(k){ if(!_chqDel[k]) m[k]=v[k]; });
    CHQ_CTRL=m;
    var p=document.getElementById('tab-cheques_compensar');
    if(p && p.classList.contains('active')){ try{ renderChequesCompensar(); }catch(e){ console.warn(e); } }
  });
}

function _chqLista(){
  return Object.keys(CHQ_CTRL).map(function(k){ return CHQ_CTRL[k]; }).filter(Boolean);
}
function _chqTotais(){
  var t={A:{q:0,v:0},C:{q:0,v:0},X:{q:0,v:0}};
  _chqLista().forEach(function(c){ var s=c.s||'A'; if(!t[s])t[s]={q:0,v:0}; t[s].q++; t[s].v+=(+c.v||0); });
  return t;
}

function chqSetSit(s){ _chqFsit=s; renderChequesCompensar(); }
function chqSetBanco(v){ _chqFbanco=v; renderChequesCompensar(); }
function chqSetBusca(v){ _chqFbusca=(v||'').toLowerCase().trim(); renderChequesCompensar(); }

function chqVerBanco(b){ _chqFbanco=b; _chqFsit='TODOS'; renderChequesCompensar(); }

function _chqAdtCheque(banco, num){
  if(typeof CHEQUES_POR_FORN==='undefined') return null;
  var found=null, keys=Object.keys(CHEQUES_POR_FORN);
  for(var i=0;i<keys.length && !found;i++){
    var lista=CHEQUES_POR_FORN[keys[i]]||[];
    for(var j=0;j<lista.length;j++){
      if(String(lista[j].num)===String(num) && (lista[j].banco||'')===banco){ found=lista[j]; break; }
    }
  }
  return found;
}


function chqToggleDesconto(id){
  var c=CHQ_CTRL[id]; if(!c) return;
  var adt=_chqAdtCheque(c.b, c.n);
  if(!adt){ showToast('Esse cheque não está no adiantamento (não é de carga).','info'); return; }
  if((adt.statusDesc||'A descontar')==='Descontado'){ if(typeof desfazerDesconto==='function') desfazerDesconto(adt.id); }
  else { if(typeof marcarDescontado==='function') marcarDescontado(adt.id); }
  try{ renderChequesCompensar(); }catch(e){}
}


function chqToggleCompra(id){
  var c=CHQ_CTRL[id]; if(!c) return;
  var novo=!c.dc; c.dc=novo; try{ renderChequesCompensar(); }catch(e){}
  var r=_chqRef(); if(!r) return;
  r.child(id).update({dc: novo?true:null})
    .then(function(){ showToast(novo?'Marcado: desconta da compra 🛒':'Desmarcado','success'); })
    .catch(function(e){ showToast('Erro: '+e.message,'error'); });
}

function renderChequesCompensar(){
  var root=document.getElementById('chq-ctrl-root');
  if(!root) return;
  
  
  
  var _chqSec=false;
  try{ _chqSec = (typeof cu!=='undefined' && cu) && ((typeof cuKey!=='undefined'&&cuKey==='thais') || (cu.role&&String(cu.role).indexOf('Secretária')>=0)); }catch(e){}
  var tot=_chqTotais();
  var bancos=_cfgChequeBankNames();
  
  var abBanco={};
  _chqLista().forEach(function(c){
    var b=c.b||''; if(!abBanco[b]) abBanco[b]={aq:0,av:0,cq:0,cv:0};
    var s=c.s||'A';
    if(s==='A'){ abBanco[b].aq++; abBanco[b].av+=(+c.v||0); }
    else if(s==='C'){ abBanco[b].cq++; abBanco[b].cv+=(+c.v||0); }
  });

  
  var arr=_chqLista().filter(function(c){
    if(_chqFsit!=='TODOS' && (c.s||'A')!==_chqFsit) return false;
    if(_chqFbanco!=='TODOS' && c.b!==_chqFbanco) return false;
    if(_chqFbusca){
      var hay=((c.n||'')+' '+(c.c||'')+' '+(c.b||'')).toLowerCase();
      if(hay.indexOf(_chqFbusca)<0) return false;
    }
    return true;
  });
  
  
  var _bOrdem=Object.fromEntries(_cfgChequeBanks().map(function(x,i){return [x.name,Number(x.order||i+1)];}));
  arr.sort(function(a,b){
    var ba=_bOrdem[a.b]||8, bb=_bOrdem[b.b]||8;
    if(ba!==bb) return ba-bb;
    if((a.b||'')!==(b.b||'')) return (a.b||'').localeCompare(b.b||'','pt-BR');
    var na=parseInt(String(a.n).replace(/\D/g,''),10); if(!isFinite(na)) na=0;
    var nb=parseInt(String(b.n).replace(/\D/g,''),10); if(!isFinite(nb)) nb=0;
    return na-nb;
  });

  var somaFiltro=arr.reduce(function(s,c){ return s+(+c.v||0); },0);

  var h='';
  
  if(!_chqSec){
    h+='<div style="background:#fff8e1;border:1px solid #ffe082;border-radius:10px;padding:10px 14px;margin-bottom:14px;font-size:.84rem;color:#7a5c00;line-height:1.5">'+
       '💡 <b>Controle de cheques por banco.</b> Cada banco tem sua cor, com o total <b>🟠 a descontar</b> e <b>🟢 descontado</b>. '+
       'Quando um cheque cai, clique em <b>✔ Compensou</b> — o valor <b>sai do saldo daquele banco</b> (e <b>↩ Reabrir</b> devolve).<br>'+
       '🛒 A coluna <b>"Desc. Compra?"</b> é pra você marcar os cheques que são de <b>adiantamento</b> (descontam da compra). Nesses, o sistema pergunta antes de descontar do banco, pra não contar em dobro.</div>';
  }

  
  if(!_chqSec){
  h+='<div class="kpi-grid">'+
     '<div class="kpi o"><div class="kpi-lbl">A Compensar</div><div class="kpi-val">'+_chqFmt(tot.A.v)+'</div><div class="kpi-sub">'+tot.A.q+' cheques pendentes no banco</div></div>'+
     '<div class="kpi g"><div class="kpi-lbl">Compensados</div><div class="kpi-val">'+tot.C.q+'</div><div class="kpi-sub">'+_chqFmt(tot.C.v)+' já caíram</div></div>'+
     '<div class="kpi"><div class="kpi-lbl">Cancelados</div><div class="kpi-val">'+tot.X.q+'</div><div class="kpi-sub">cheques cancelados</div></div>'+
     '<div class="kpi r"><div class="kpi-lbl">Total no controle</div><div class="kpi-val">'+_chqLista().length+'</div><div class="kpi-sub">cheques registrados</div></div>'+
     '</div>';
  }

  
  
  var cardBancos=bancos.filter(function(b){ return abBanco[b]&&(abBanco[b].aq||abBanco[b].cq); });
  if(!_chqSec && cardBancos.length){
    h+='<div style="display:flex;flex-wrap:wrap;gap:10px;margin:4px 0 16px">';
    cardBancos.forEach(function(b){
      var cor=_cfgChequeBankColor(b);
      h+='<div onclick="chqVerBanco(\''+esc(b)+'\')" title="Ver todos os cheques deste banco em ordem" style="background:#fff;border:1px solid #eee;border-top:4px solid '+cor+';border-radius:10px;padding:9px 14px;min-width:180px;cursor:pointer">'+
         '<div style="font-size:.74rem;font-weight:800;color:'+cor+';text-transform:uppercase;margin-bottom:5px">'+esc(b)+'</div>'+
         '<div style="display:flex;justify-content:space-between;gap:12px;font-size:.79rem"><span style="color:#e67e22;font-weight:700">🟠 A descontar</span><b>'+_chqFmt(abBanco[b].av)+'</b></div>'+
         '<div style="font-size:.67rem;color:#bbb;text-align:right;margin-bottom:4px">'+abBanco[b].aq+' cheque(s)</div>'+
         '<div style="display:flex;justify-content:space-between;gap:12px;font-size:.79rem"><span style="color:#2e7d32;font-weight:700">🟢 Descontado</span><b>'+_chqFmt(abBanco[b].cv)+'</b></div>'+
         '<div style="font-size:.67rem;color:#bbb;text-align:right">'+abBanco[b].cq+' cheque(s)</div>'+
         '</div>';
    });
    h+='</div>';
  }

  
  h+='<div style="display:flex;flex-wrap:wrap;gap:6px;align-items:center;margin:2px 0 12px;padding:8px 10px;background:#f6f8f7;border-radius:9px">';
  h+='<span style="font-size:.78rem;color:#666;font-weight:700;margin-right:2px">📚 Ver por banco (em ordem):</span>';
  [['TODOS','Todos']].concat(bancos.map(function(b){ return [b,b]; })).forEach(function(o){
    var on=_chqFbanco===o[0];
    h+='<button onclick="chqVerBanco(\''+o[0]+'\')" style="border:1px solid '+(on?'#1a3a2a':'#ccd')+';background:'+(on?'#1a3a2a':'#fff')+';color:'+(on?'#fff':'#444')+';border-radius:16px;padding:5px 12px;font-size:.78rem;font-weight:'+(on?'700':'500')+';cursor:pointer">'+esc(o[1])+'</button>';
  });
  h+='</div>';

  
  h+='<div style="display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin-bottom:12px">';
  h+='<div style="display:inline-flex;border:1px solid #ddd;border-radius:8px;overflow:hidden">';
  [['A','🟠 A Compensar'],['C','🟢 Compensados'],['X','⚪ Cancelados'],['N','⛔ Não existe'],['TODOS','Todos']].forEach(function(o){
    var on=_chqFsit===o[0];
    h+='<button onclick="chqSetSit(\''+o[0]+'\')" style="border:none;padding:7px 13px;font-size:.82rem;font-weight:'+(on?'700':'400')+';cursor:pointer;background:'+(on?'#1a3a2a':'#fff')+';color:'+(on?'#fff':'#555')+'">'+o[1]+'</button>';
  });
  h+='</div>';
  h+='<select onchange="chqSetBanco(this.value)" style="font-size:.82rem;padding:6px 10px;border:1px solid #ddd;border-radius:7px">';
  h+='<option value="TODOS"'+(_chqFbanco==='TODOS'?' selected':'')+'>Todos os bancos</option>';
  bancos.forEach(function(b){ h+='<option value="'+esc(b)+'"'+(_chqFbanco===b?' selected':'')+'>'+esc(b)+'</option>'; });
  h+='</select>';
  h+='<input type="text" placeholder="🔍 Nº ou cliente..." value="'+esc(_chqFbusca)+'" oninput="chqSetBusca(this.value)" style="font-size:.82rem;padding:6px 10px;border:1px solid #ddd;border-radius:7px;min-width:170px">';
  if(!_chqSec){
    
    
    var _rpComp=_legacyRepairConfig('gratusSicrediComplete');
    var _rpAcredi=_legacyRepairConfig('gratusAcredi');
    if(_rpComp&&_rpComp.bank&&Array.isArray(_rpComp.records)&&_rpComp.records.length){
      h+='<button class="btn-edit" onclick="chqCompletarGratusSicredi()" title="'+esc(_rpComp.buttonTitle||'Completar cheques configurados sem sobrescrever registros existentes.')+'" style="margin-left:auto;background:#2980b9;color:#fff">'+esc(_rpComp.buttonLabel||'➕ Aplicar complementação')+'</button>';
    }
    h+='<button class="btn-edit" onclick="chqSincronizarAbaAntiga()" title="Traz os cheques reais da aba antiga (fornecedor, valor, bom para) e marca os de adiantamento" style="margin-left:auto;background:#8e44ad;color:#fff">🔄 Sincronizar aba antiga</button>';
    if(_rpAcredi&&_rpAcredi.bank&&Array.isArray(_rpAcredi.records)&&_rpAcredi.records.length){
      h+='<button class="btn-edit" onclick="chqCorrigirAcredi()" title="'+esc(_rpAcredi.buttonTitle||'Aplicar correção de cheques configurada no Firebase.')+'" style="background:#1565c0;color:#fff">'+esc(_rpAcredi.buttonLabel||'🔧 Aplicar correção')+'</button>';
    }
  }
  h+='<button class="btn-add"'+(_chqSec?' style="margin-left:auto"':'')+' onclick="chqNovo()">+ Novo Cheque</button>';
  h+='<button class="btn-add" onclick="chqRemessa()" title="Lançar vários cheques de uma vez (uma remessa: números em sequência)" style="background:#1a4a7c">📦 Remessa (vários)</button>';
  if(!_chqSec){ h+='<button class="btn-add" onclick="chqRemessaDeposito()" title="Depositar vários cheques de uma vez (borderô): marca todos como compensados e desconta do saldo do banco" style="background:#1a7f4b">📥 Depositar em lote</button>'; }
  if(!_chqSec){ h+='<button class="btn-edit" onclick="chqExportCSV()" title="Baixar em Excel/CSV">⬇️ Exportar</button>'; }
  h+='</div>';

  
  h+='<div style="font-size:.82rem;color:#666;margin-bottom:8px">Mostrando <b>'+arr.length+'</b> cheque(s)'+(_chqSec?'':' — total <b>'+_chqFmt(somaFiltro)+'</b>')+'</div>';

  
  h+='<div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse;font-size:.84rem">'+
     '<thead><tr style="background:#1a3a2a;color:#fff;text-align:left">'+
     '<th style="padding:7px 9px">Nº</th><th style="padding:7px 9px">Banco</th><th style="padding:7px 9px">Cliente</th>'+
     '<th style="padding:7px 9px;text-align:right">Valor</th><th style="padding:7px 9px">Data Saída</th>'+
     '<th style="padding:7px 9px">Vencimento</th>'+
     '<th style="padding:7px 9px">Caiu em</th><th style="padding:7px 9px">Situação</th><th style="padding:7px 9px;text-align:center">Desc. Compra?</th><th style="padding:7px 9px;text-align:center">Ações</th></tr></thead><tbody>';
  if(!arr.length){
    h+='<tr><td colspan="10" style="padding:18px;text-align:center;color:#aaa">Nenhum cheque neste filtro.</td></tr>';
  }
  
  
  var _adtIdx={};
  try{
    if(typeof CHEQUES_POR_FORN!=='undefined'){
      Object.keys(CHEQUES_POR_FORN).forEach(function(k){
        (CHEQUES_POR_FORN[k]||[]).forEach(function(x){
          _adtIdx[(x.banco||'')+'|'+String(x.num)]=(x.statusDesc||'A descontar');
        });
      });
    }
  }catch(e){}
  arr.forEach(function(c){
    var s=c.s||'A';
    var bg = s==='A' ? '#fff9e6' : (s==='C' ? '#f2faf3' : (s==='N' ? '#efefef' : '#f5f5f5'));
    var sitTag = s==='A' ? '<span style="background:#fff3cd;color:#8a6d00;border-radius:9px;padding:2px 9px;font-size:.74rem;font-weight:700">🟠 A Compensar</span>'
               : s==='C' ? '<span style="background:#d7f0dd;color:#1a5e2a;border-radius:9px;padding:2px 9px;font-size:.74rem;font-weight:700">🟢 Compensado</span>'
               : s==='N' ? '<span style="background:#e8e8e8;color:#999;border-radius:9px;padding:2px 9px;font-size:.74rem;font-weight:700">⛔ Não existe</span>'
               : '<span style="background:#e0e0e0;color:#777;border-radius:9px;padding:2px 9px;font-size:.74rem;font-weight:700">⚪ Cancelado</span>';
    var cliTxt = (s==='X'||s==='N') ? '<span style="text-decoration:line-through;color:#aaa">'+esc(c.c||(s==='N'?'não emitido':''))+'</span>' : esc(c.c||'');
    var corB=_cfgChequeBankColor(c.b);
    var dc=!!c.dc;
    var compraCell='<button onclick="chqToggleCompra(\''+c.id+'\')" title="'+(dc?'Este cheque desconta da compra (adiantamento). Clique pra desmarcar.':'Marcar: este cheque desconta da compra (adiantamento)')+'" style="border:1px solid '+(dc?'#8e44ad':'#ccc')+';background:'+(dc?'#f3e5f5':'#fff')+';color:'+(dc?'#8e44ad':'#aaa')+';border-radius:14px;padding:3px 11px;font-size:.72rem;font-weight:700;cursor:pointer">'+(dc?'🛒 Sim':'—')+'</button>';
    var acoes='';
    
    if(!_chqSec){
      if(s==='A'){ acoes+='<button onclick="chqMarcarComp(\''+c.id+'\')" title="Marcar como compensado (caiu no banco)" style="border:none;background:#1a5e2a;color:#fff;border-radius:6px;padding:4px 9px;font-size:.75rem;cursor:pointer;font-weight:700">✔ Compensou</button> '; }
      else if(s==='C'){ acoes+='<button onclick="chqReabrir(\''+c.id+'\')" title="Voltar para a compensar" style="border:none;background:#f39c12;color:#fff;border-radius:6px;padding:4px 9px;font-size:.75rem;cursor:pointer">↩ Reabrir</button> '; }
    }
    
    
    var _descSt=_adtIdx[(c.b||'')+'|'+String(c.n)];
    if(_descSt!==undefined){
      var _feito=(_descSt==='Descontado');
      acoes+='<button onclick="chqToggleDesconto(\''+c.id+'\')" title="'+(_feito?'Já descontado da carga do fornecedor. Clique pra desfazer.':'Marcar como descontado da carga do fornecedor')+'" style="border:none;background:'+(_feito?'#7f8c8d':'#2980b9')+';color:#fff;border-radius:6px;padding:4px 9px;font-size:.75rem;cursor:pointer;font-weight:700">'+(_feito?'↩ Desfazer carga':'✅ Descontar carga')+'</button> ';
    }
    acoes+='<button onclick="chqEditar(\''+c.id+'\')" title="Editar" style="border:1px solid #ccc;background:#fff;border-radius:6px;padding:4px 8px;font-size:.75rem;cursor:pointer">✏️</button> ';
    if(!_chqSec){ acoes+='<button onclick="chqExcluir(\''+c.id+'\')" title="Excluir" style="border:1px solid #f3c0c0;background:#fff;color:#c0392b;border-radius:6px;padding:4px 8px;font-size:.75rem;cursor:pointer">🗑️</button>'; }
    h+='<tr style="background:'+bg+';border-bottom:1px solid #eee">'+
       '<td style="padding:6px 9px;font-weight:700">'+esc(String(c.n||''))+'</td>'+
       '<td style="padding:6px 9px;white-space:nowrap"><span style="display:inline-block;width:9px;height:9px;border-radius:50%;background:'+corB+';margin-right:5px;vertical-align:middle"></span>'+esc(c.b||'')+'</td>'+
       '<td style="padding:6px 9px">'+cliTxt+'</td>'+
       '<td style="padding:6px 9px;text-align:right;font-weight:600">'+_chqFmt(+c.v||0)+'</td>'+
       '<td style="padding:6px 9px;color:#777">'+esc(c.d||'')+'</td>'+
       '<td style="padding:6px 9px;color:#555;font-weight:600">'+esc(c.venc||'')+'</td>'+
       '<td style="padding:6px 9px;color:#777">'+esc(c.cd||'')+'</td>'+
       '<td style="padding:6px 9px">'+sitTag+'</td>'+
       '<td style="padding:6px 9px;text-align:center">'+compraCell+'</td>'+
       '<td style="padding:6px 9px;text-align:center;white-space:nowrap">'+acoes+'</td></tr>';
  });
  h+='</tbody></table></div>';
  root.innerHTML=h;
}





var _CHQ_BANCO_COD={};

var _CHQ_BANCO_COR={};
function _chqMovBancoCriar(bancoCod, dataBR, desc, valor){
  try{
    if(!bancoCod || !valor || typeof LANC_BANCO_DB==='undefined') return '';
    var mov={ id:'LB-'+Date.now()+'-'+Math.random().toString(36).slice(2,6),
      bancoCod:bancoCod, data:(dataBR||_chqHojeBR()), descricao:desc, tipo:'Saida', valor:Number(valor)||0 };
    LANC_BANCO_DB.push(mov);
    try{ saveBancos(); }catch(e){} try{ renderBancos(); }catch(e){}
    return mov.id;
  }catch(e){ console.warn('mov banco cheque:',e); return ''; }
}
function _chqMovBancoRemover(movId){
  try{
    if(!movId || typeof LANC_BANCO_DB==='undefined') return;
    var i=LANC_BANCO_DB.findIndex(function(l){ return l && l.id===movId; });
    if(i>=0){
      if(typeof _syncLancBanco!=='undefined' && _syncLancBanco.remover) _syncLancBanco.remover(i);
      else LANC_BANCO_DB.splice(i,1);
      try{ saveBancos(); }catch(e){} try{ renderBancos(); }catch(e){}
    }
  }catch(e){ console.warn('remover mov banco cheque:',e); }
}
function chqMarcarComp(id){
  var c=CHQ_CTRL[id]; if(!c) return;
  var d=prompt('Data que o cheque nº '+c.n+' ('+c.b+') caiu no banco (dd/mm/aaaa):', c.cd||_chqHojeBR());
  if(d===null) return;
  var r=_chqRef(); if(!r) return;
  
  
  var descontarBanco=true;
  if(c.dc){
    descontarBanco=confirm('Este cheque está marcado como "desconta da compra" (adiantamento).\n\nSe você já lançou ele como adiantamento, o saldo do banco JÁ baixou — então NÃO precisa descontar de novo (senão conta em dobro).\n\nDescontar do saldo do banco mesmo assim?\n\nOK = sim, descontar do banco\nCancelar = não, só marcar como compensado');
  }
  
  var movId='';
  if(descontarBanco && !c.movBancoId){ movId=_chqMovBancoCriar(_cfgChequeBankCode(c.b), (d||'').trim(), 'Cheque nº '+c.n+' compensado (controle)', +c.v||0); }
  
  c.s='C'; c.cd=(d||'').trim(); if(movId) c.movBancoId=movId; try{ renderChequesCompensar(); }catch(e){}
  var upd={s:'C', cd:(d||'').trim()}; if(movId) upd.movBancoId=movId;
  r.child(id).update(upd)
    .then(function(){ showToast('Cheque '+c.n+' compensado'+(movId?' — saiu do saldo do banco':'')+' ✔','success'); })
    .catch(function(e){ showToast('Erro: '+e.message,'error'); });
}



function chqRemessaDeposito(){
  var pend=Object.keys(CHQ_CTRL).map(function(k){ return {id:k,c:CHQ_CTRL[k]}; }).filter(function(o){ return o.c && (o.c.s||'A')==='A'; });
  if(_chqFbanco && _chqFbanco!=='TODOS') pend=pend.filter(function(o){ return o.c.b===_chqFbanco; });
  if(!pend.length){ showToast('Não há cheques "A compensar" pra depositar'+(_chqFbanco!=='TODOS'?' nesse banco':'')+'.','info'); return; }
  pend.sort(function(a,b){ if((a.c.b||'')!==(b.c.b||'')) return (a.c.b||'').localeCompare(b.c.b||''); return (+a.c.n||0)-(+b.c.n||0); });
  var old=document.getElementById('chq-remessa-ov'); if(old&&old.parentNode) old.parentNode.removeChild(old);
  var ov=document.createElement('div'); ov.id='chq-remessa-ov';
  ov.style.cssText='position:fixed;inset:0;background:rgba(0,0,0,.55);z-index:10050;display:flex;align-items:flex-start;justify-content:center;overflow:auto;padding:24px 12px';
  var hojeISO=(function(){ var d=new Date(),z=function(n){return String(n).padStart(2,'0');}; return d.getFullYear()+'-'+z(d.getMonth()+1)+'-'+z(d.getDate()); })();
  var linhas=pend.map(function(o){
    var c=o.c; var dc=c.dc?' <span style="background:#fff3cd;color:#856404;padding:1px 6px;border-radius:8px;font-size:.7rem;font-weight:700" title="Marcado como desconto da compra (adiantamento) — não desconta do banco de novo">adiant.</span>':'';
    return '<tr>'
      +'<td style="text-align:center"><input type="checkbox" class="chqrd-chk" checked data-id="'+esc(o.id)+'" data-v="'+(+c.v||0)+'" onchange="chqRemessaTotal()"></td>'
      +'<td>'+esc(c.b||'—')+'</td>'
      +'<td style="text-align:center">'+esc(c.n||'—')+'</td>'
      +'<td>'+esc(c.c||'—')+dc+'</td>'
      +'<td style="text-align:right;font-weight:700">R$ '+_chqFmt(+c.v||0).replace('R$ ','')+'</td>'
      +'</tr>';
  }).join('');
  ov.innerHTML='<div style="background:#fff;border-radius:14px;box-shadow:0 8px 40px #0005;width:96%;max-width:640px">'
    +'<div style="background:#1a7f4b;color:#fff;padding:14px 20px;border-radius:14px 14px 0 0;display:flex;align-items:center;justify-content:space-between">'
      +'<b style="font-size:1rem">📥 Depositar cheques em lote (remessa)</b>'
      +'<span style="cursor:pointer;font-size:1.2rem" onclick="document.getElementById(\'chq-remessa-ov\').remove()">✕</span></div>'
    +'<div style="padding:16px 20px">'
      +'<div style="display:flex;gap:12px;align-items:flex-end;flex-wrap:wrap;margin-bottom:12px">'
        +'<div><label style="font-size:.75rem;font-weight:700;color:#555;display:block">Data do depósito</label>'
          +'<input type="date" id="chqrd-data" value="'+hojeISO+'" style="padding:7px 9px;border:1.5px solid #ccc;border-radius:7px"></div>'
        +'<label style="font-size:.82rem;color:#333;cursor:pointer"><input type="checkbox" id="chqrd-all" checked onchange="chqRemessaMarcarTodos(this.checked)"> Marcar todos</label>'
      +'</div>'
      +'<div style="font-size:.8rem;color:#666;margin-bottom:8px">Marque os cheques que estão indo pro depósito. Ao confirmar, eles viram <b>Compensados</b> e o valor <b>sai do saldo do banco</b> (os marcados como "adiant." não descontam de novo).</div>'
      +'<div style="overflow:auto;max-height:340px;border:1px solid #eee;border-radius:8px">'
        +'<table style="width:100%;border-collapse:collapse;font-size:.84rem"><thead><tr style="background:#f2f6f4;position:sticky;top:0">'
          +'<th style="padding:7px 8px"></th><th style="padding:7px 8px;text-align:left">Banco</th><th style="padding:7px 8px">Nº</th><th style="padding:7px 8px;text-align:left">Cliente</th><th style="padding:7px 8px;text-align:right">Valor</th></tr></thead>'
        +'<tbody>'+linhas+'</tbody></table></div>'
      +'<div style="margin-top:12px;font-size:.95rem;font-weight:800;color:#1a7f4b">Selecionados: <span id="chqrd-count">0</span> cheque(s) · Total: <span id="chqrd-total">R$ 0,00</span></div>'
    +'</div>'
    +'<div style="padding:0 20px 18px;display:flex;gap:8px;justify-content:flex-end">'
      +'<button onclick="document.getElementById(\'chq-remessa-ov\').remove()" style="padding:9px 16px;background:#eee;color:#333;border:none;border-radius:7px;cursor:pointer;font-weight:700">Cancelar</button>'
      +'<button onclick="chqRemessaDepConfirmar()" style="padding:9px 20px;background:#1a7f4b;color:#fff;border:none;border-radius:7px;cursor:pointer;font-weight:800">✔ Confirmar depósito</button>'
    +'</div></div>';
  document.body.appendChild(ov);
  chqRemessaTotal();
}
function chqRemessaMarcarTodos(on){ document.querySelectorAll('#chq-remessa-ov .chqrd-chk').forEach(function(ch){ ch.checked=!!on; }); chqRemessaTotal(); }
function chqRemessaTotal(){
  var checks=Array.prototype.slice.call(document.querySelectorAll('#chq-remessa-ov .chqrd-chk:checked'));
  var tot=0; checks.forEach(function(ch){ tot+=Number(ch.dataset.v||0); });
  var cEl=document.getElementById('chqrd-count'); if(cEl) cEl.textContent=checks.length;
  var tEl=document.getElementById('chqrd-total'); if(tEl) tEl.textContent='R$ '+Number(tot).toLocaleString('pt-BR',{minimumFractionDigits:2});
}
function chqRemessaDepConfirmar(){
  var di=document.getElementById('chqrd-data'); var iso=di?di.value:'';
  if(!iso){ showToast('Informe a data do depósito.','error'); return; }
  var dBR=iso.split('-').reverse().join('/');
  var checks=Array.prototype.slice.call(document.querySelectorAll('#chq-remessa-ov .chqrd-chk:checked'));
  if(!checks.length){ showToast('Marque pelo menos um cheque.','info'); return; }
  if(!confirm('Depositar '+checks.length+' cheque(s) na data '+dBR+'? Eles viram Compensados e saem do saldo do banco (os de adiantamento não descontam de novo).')) return;
  var r=_chqRef();
  var n=0, tot=0;
  checks.forEach(function(chk){
    var id=chk.dataset.id; var c=CHQ_CTRL[id]; if(!c||(c.s||'A')!=='A') return;
    var descontarBanco=!c.dc; 
    var movId='';
    if(descontarBanco && !c.movBancoId){ movId=_chqMovBancoCriar(_cfgChequeBankCode(c.b), dBR, 'Cheque nº '+c.n+' compensado (remessa '+dBR+')', +c.v||0); }
    c.s='C'; c.cd=dBR; if(movId) c.movBancoId=movId;
    var upd={s:'C', cd:dBR}; if(movId) upd.movBancoId=movId;
    if(r){ try{ r.child(id).update(upd); }catch(e){} }
    n++; tot+=Number(c.v||0);
  });
  var ov=document.getElementById('chq-remessa-ov'); if(ov) ov.remove();
  try{ renderChequesCompensar(); }catch(e){}
  showToast('✔ Remessa depositada: '+n+' cheque(s) · R$ '+Number(tot).toLocaleString('pt-BR',{minimumFractionDigits:2})+'. Saiu do saldo do banco.','success',6000);
}
window['chqRemessaDeposito']=chqRemessaDeposito;
window['chqRemessaMarcarTodos']=chqRemessaMarcarTodos;
window['chqRemessaTotal']=chqRemessaTotal;
window['chqRemessaDepConfirmar']=chqRemessaDepConfirmar;

function chqReabrir(id){
  var c=CHQ_CTRL[id]; if(!c) return;
  var r=_chqRef(); if(!r) return;
  
  var tinhaMov=!!c.movBancoId;
  if(tinhaMov){ _chqMovBancoRemover(c.movBancoId); }
  c.s='A'; c.cd=''; delete c.movBancoId; try{ renderChequesCompensar(); }catch(e){}
  var upd={s:'A', cd:''}; if(tinhaMov) upd.movBancoId=null;
  r.child(id).update(upd)
    .then(function(){ showToast('Cheque '+c.n+' voltou para A Compensar'+(tinhaMov?' — devolvido ao saldo do banco':''),'success'); })
    .catch(function(e){ showToast('Erro: '+e.message,'error'); });
}
function chqExcluir(id){
  var c=CHQ_CTRL[id]; if(!c) return;
  if(!confirm('Excluir o cheque nº '+c.n+' ('+c.b+', '+_chqFmt(+c.v||0)+')?\n\nEle sai do controle em todos os computadores.')) return;
  var r=_chqRef(), dr=_chqDelRef(); if(!r||!dr) return;
  if(c.movBancoId){ _chqMovBancoRemover(c.movBancoId); }
  _chqDel[id]=true; delete CHQ_CTRL[id]; try{ renderChequesCompensar(); }catch(e){}
  dr.child(id).set(true).then(function(){
    return r.child(id).remove();
  }).then(function(){ showToast('Cheque excluído','success'); })
    .catch(function(e){ showToast('Erro: '+e.message,'error'); });
}


function _chqModal(id){
  var c = id ? CHQ_CTRL[id] : null;
  var bancos=_cfgChequeBankNames();
  var ov=document.getElementById('chq-modal-ov');
  if(!ov){
    ov=document.createElement('div'); ov.id='chq-modal-ov';
    ov.style.cssText='position:fixed;inset:0;background:rgba(0,0,0,.45);z-index:99999;display:flex;align-items:center;justify-content:center;padding:16px';
    document.body.appendChild(ov);
  }
  var v = c || {b:bancos[0],n:'',c:'',v:'',d:'',cd:'',s:'A'};
  ov.innerHTML='<div style="background:#fff;border-radius:14px;max-width:440px;width:100%;padding:22px;box-shadow:0 10px 40px rgba(0,0,0,.3)">'+
    '<div style="font-size:1.05rem;font-weight:800;color:#1a3a2a;margin-bottom:14px">'+(c?'✏️ Editar Cheque':'+ Novo Cheque')+'</div>'+
    '<input type="hidden" id="chqm-id" value="'+(id||'')+'">'+
    '<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px">'+
      '<label style="font-size:.78rem;color:#666">Banco<select id="chqm-b" style="width:100%;padding:7px;border:1px solid #ccc;border-radius:7px;font-size:.85rem">'+
        bancos.map(function(b){ return '<option'+(v.b===b?' selected':'')+'>'+esc(b)+'</option>'; }).join('')+'</select></label>'+
      '<label style="font-size:.78rem;color:#666">Nº do Cheque<input id="chqm-n" value="'+esc(String(v.n||''))+'" style="width:100%;padding:7px;border:1px solid #ccc;border-radius:7px;font-size:.85rem"></label>'+
      '<label style="font-size:.78rem;color:#666;grid-column:1/3">Cliente / Destino<input id="chqm-c" list="chqm-clientes-list" value="'+esc(v.c||'')+'" placeholder="Digite ou selecione um cliente" style="width:100%;padding:7px;border:1px solid #ccc;border-radius:7px;font-size:.85rem"><datalist id="chqm-clientes-list">'+(CLIENTES||[]).slice().sort((a,b)=>String(a.nome||'').localeCompare(String(b.nome||''),'pt-BR')).map(function(c){return '<option value="'+esc(c.nome||'')+'">';}).join('')+'</datalist></label>'+
      '<label style="font-size:.78rem;color:#666">Valor (R$)<input id="chqm-v" value="'+esc(String(v.v||''))+'" placeholder="4990,00" style="width:100%;padding:7px;border:1px solid #ccc;border-radius:7px;font-size:.85rem"></label>'+
      '<label style="font-size:.78rem;color:#666">Situação<select id="chqm-s" style="width:100%;padding:7px;border:1px solid #ccc;border-radius:7px;font-size:.85rem">'+
        '<option value="A"'+(v.s==='A'?' selected':'')+'>A Compensar</option>'+
        '<option value="C"'+(v.s==='C'?' selected':'')+'>Compensado</option>'+
        '<option value="X"'+(v.s==='X'?' selected':'')+'>Cancelado</option></select></label>'+
      '<label style="font-size:.78rem;color:#666">Data de Saída<input id="chqm-d" value="'+esc(v.d||'')+'" placeholder="dd/mm/aaaa" style="width:100%;padding:7px;border:1px solid #ccc;border-radius:7px;font-size:.85rem"></label>'+
      '<label style="font-size:.78rem;color:#666">Vencimento (bom para)<input id="chqm-venc" value="'+esc(v.venc||'')+'" placeholder="dd/mm/aaaa" style="width:100%;padding:7px;border:1px solid #ccc;border-radius:7px;font-size:.85rem"></label>'+
      '<label style="font-size:.78rem;color:#666">Caiu em (compensado)<input id="chqm-cd" value="'+esc(v.cd||'')+'" placeholder="dd/mm/aaaa" style="width:100%;padding:7px;border:1px solid #ccc;border-radius:7px;font-size:.85rem"></label>'+
    '</div>'+
    '<div style="display:flex;gap:9px;justify-content:flex-end;margin-top:18px">'+
      '<button onclick="chqFecharModal()" style="border:1px solid #ccc;background:#fff;border-radius:8px;padding:8px 16px;font-size:.85rem;cursor:pointer">Cancelar</button>'+
      '<button onclick="chqSalvarModal()" style="border:none;background:#1a3a2a;color:#fff;border-radius:8px;padding:8px 18px;font-size:.85rem;font-weight:700;cursor:pointer">Salvar</button>'+
    '</div></div>';
  ov.style.display='flex';
}




function chqCorrigirAcredi(){
  var cfg=_legacyRepairConfig('gratusAcredi');
  if(!cfg.bank){ showToast('Configuração de correção não encontrada no Firebase.','error'); return; }
  if(!confirm(cfg.confirmText||'Confirmar correção?')) return;
  var r=_chqRef(); if(!r){ showToast('Firebase não conectado','error'); return; }
  var batch={}, n=0, cancel=(cfg.cancelIfPending||[]).map(String), keep=(cfg.keepPending||[]).map(String);
  Object.keys(CHQ_CTRL).forEach(function(id){
    var c=CHQ_CTRL[id]; if(!c || c.b!==cfg.bank) return;
    var num=String(c.n);
    if(cancel.indexOf(num)>=0 && (c.s||'A')==='A'){ c.s='X'; c.cd=''; batch[id]=c; n++; }
    else if(keep.indexOf(num)>=0 && (c.s||'A')!=='C'){ c.s='A'; c.cd=''; batch[id]=c; n++; }
  });
  if(!n){ showToast('Nada a corrigir (cheques não encontrados).','info'); return; }
  try{ renderChequesCompensar(); }catch(e){}
  r.update(batch).then(function(){ showToast(cfg.successText||'✔ Correção aplicada.','success',8000); }).catch(function(e){ showToast('Erro: '+e.message,'error'); });
}
function chqNovo(){ _chqModal(null); }
function chqEditar(id){ _chqModal(id); }
function chqFecharModal(){ var ov=document.getElementById('chq-modal-ov'); if(ov) ov.style.display='none'; }



function chqRemessa(){
  var bancos=_cfgChequeBankNames();
  var ov=document.getElementById('chq-modal-ov');
  if(!ov){
    ov=document.createElement('div'); ov.id='chq-modal-ov';
    ov.style.cssText='position:fixed;inset:0;background:rgba(0,0,0,.45);z-index:99999;display:flex;align-items:center;justify-content:center;padding:16px';
    document.body.appendChild(ov);
  }
  var inp='width:100%;padding:7px;border:1px solid #ccc;border-radius:7px;font-size:.85rem;box-sizing:border-box';
  ov.innerHTML='<div style="background:#fff;border-radius:14px;max-width:520px;width:100%;padding:22px;box-shadow:0 10px 40px rgba(0,0,0,.3);max-height:92vh;overflow-y:auto">'+
    '<div style="font-size:1.05rem;font-weight:800;color:#1a3a2a;margin-bottom:4px">📦 Remessa de Cheques</div>'+
    '<div style="font-size:.8rem;color:#777;margin-bottom:14px">Lança vários cheques de uma vez, com os números em sequência.</div>'+
    '<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px">'+
      '<label style="font-size:.78rem;color:#666">Banco<select id="chqr-b" style="'+inp+'">'+
        bancos.map(function(b){ return '<option>'+esc(b)+'</option>'; }).join('')+'</select></label>'+
      '<label style="font-size:.78rem;color:#666">Cliente / Destino (todos)<input id="chqr-c" placeholder="Ex: FERRO VELHO" style="'+inp+'"></label>'+
      '<label style="font-size:.78rem;color:#666">Nº inicial<input id="chqr-ini" type="number" min="1" placeholder="180" style="'+inp+'"></label>'+
      '<label style="font-size:.78rem;color:#666">Quantidade<input id="chqr-qtd" type="number" min="1" max="200" placeholder="10" style="'+inp+'" oninput="_chqRemPrev()"></label>'+
      '<label style="font-size:.78rem;color:#666">Valor por cheque (R$)<input id="chqr-v" placeholder="4990,00" style="'+inp+'"></label>'+
      '<label style="font-size:.78rem;color:#666">Data de saída (todos)<input id="chqr-d" placeholder="dd/mm/aaaa" style="'+inp+'"></label>'+
      '<label style="font-size:.78rem;color:#666">Vencimento — bom para (todos)<input id="chqr-venc" placeholder="dd/mm/aaaa" style="'+inp+'"></label>'+
      '<label style="font-size:.78rem;color:#666">Situação<select id="chqr-s" style="'+inp+'">'+
        '<option value="A">🟠 A Compensar</option><option value="C">🟢 Compensado</option></select></label>'+
      '<label style="font-size:.78rem;color:#666;display:flex;align-items:center;gap:7px;margin-top:20px"><input type="checkbox" id="chqr-dc" checked style="width:16px;height:16px"> 🛒 Desconta da compra (adiantamento)</label>'+
    '</div>'+
    '<div id="chqr-prev" style="margin-top:12px;font-size:.82rem;color:#1a4a7c;background:#eef4fb;border-radius:8px;padding:8px 12px"></div>'+
    '<div style="display:flex;gap:9px;justify-content:flex-end;margin-top:16px">'+
      '<button onclick="chqFecharModal()" style="border:1px solid #ccc;background:#fff;border-radius:8px;padding:8px 16px;font-size:.85rem;cursor:pointer">Cancelar</button>'+
      '<button onclick="chqRemessaSalvar()" style="border:none;background:#1a4a7c;color:#fff;border-radius:8px;padding:8px 18px;font-size:.85rem;font-weight:700;cursor:pointer">💾 Lançar todos</button>'+
    '</div></div>';
  ov.style.display='flex';
  _chqRemPrev();
}
function _chqRemPrev(){
  var ini=parseInt(document.getElementById('chqr-ini')?.value)||0;
  var qtd=parseInt(document.getElementById('chqr-qtd')?.value)||0;
  var el=document.getElementById('chqr-prev'); if(!el) return;
  if(ini>0 && qtd>0){ el.textContent='Vai lançar '+qtd+' cheque(s): nº '+ini+' até '+(ini+qtd-1)+'.'; }
  else{ el.textContent='Preencha o nº inicial e a quantidade.'; }
}
function chqRemessaSalvar(){
  var b=document.getElementById('chqr-b').value;
  var cli=(document.getElementById('chqr-c').value||'').trim();
  var ini=parseInt(document.getElementById('chqr-ini').value)||0;
  var qtd=parseInt(document.getElementById('chqr-qtd').value)||0;
  var val=_chqParseVal(document.getElementById('chqr-v').value);
  var d=(document.getElementById('chqr-d').value||'').trim();
  var venc=(document.getElementById('chqr-venc')?.value||'').trim();
  var s=document.getElementById('chqr-s').value;
  var dc=!!document.getElementById('chqr-dc').checked;
  if(ini<1){ showToast('Informe o número inicial do cheque','error'); return; }
  if(qtd<1||qtd>200){ showToast('Quantidade deve ser entre 1 e 200','error'); return; }
  var r=_chqRef(); if(!r){ showToast('Firebase não conectado','error'); return; }
  var slug=_cfgChequeBankSlug(b);
  
  var existentes={};
  Object.keys(CHQ_CTRL).forEach(function(x){ var cc=CHQ_CTRL[x]; if(cc&&cc.b===b) existentes[String(cc.n)]=true; });
  var batch={}, add=0, pulou=0;
  for(var i=0;i<qtd;i++){
    var num=String(ini+i);
    if(existentes[num]){ pulou++; continue; }
    var cid='CC'+slug+num, base=cid, k=1;
    while(CHQ_CTRL[cid]||batch[cid]){ k++; cid=base+'_'+k; }
    var obj={id:cid,b:b,n:num,c:cli,v:val,d:d,venc:venc,cd:(s==='C'?d:''),s:s,dc:dc};
    CHQ_CTRL[cid]=obj; batch[cid]=obj; add++;
  }
  if(!add){ showToast('Nada a lançar — esses números já existem nesse banco.','info',6000); return; }
  try{ renderChequesCompensar(); }catch(e){}
  r.update(batch).then(function(){
    chqFecharModal();
    showToast('✔ Remessa lançada: '+add+' cheque(s)'+(pulou?' ('+pulou+' já existiam, pulei)':'')+'.','success',7000);
  }).catch(function(e){ showToast('Erro: '+e.message,'error'); });
}
function _chqParseVal(s){
  s=String(s||'').trim().replace(/[^0-9.,]/g,'');
  if(s.indexOf(',')>=0){ s=s.replace(/\./g,'').replace(',','.'); }
  var n=parseFloat(s); return isFinite(n)?n:0;
}
function chqSalvarModal(){
  var id=(document.getElementById('chqm-id').value||'').trim();
  var b=document.getElementById('chqm-b').value;
  var n=(document.getElementById('chqm-n').value||'').trim();
  var cli=(document.getElementById('chqm-c').value||'').trim();
  var val=_chqParseVal(document.getElementById('chqm-v').value);
  var s=document.getElementById('chqm-s').value;
  var d=(document.getElementById('chqm-d').value||'').trim();
  var venc=(document.getElementById('chqm-venc')?.value||'').trim();
  var cd=(document.getElementById('chqm-cd').value||'').trim();
  if(!n){ showToast('Preencha o número do cheque','error'); return; }
  var r=_chqRef(); if(!r){ showToast('Firebase não conectado','error'); return; }
  if(!id){
    var slug=_cfgChequeBankSlug(b);
    id='CC'+slug+n; var base=id, k=1;
    while(CHQ_CTRL[id]){ k++; id=base+'_'+k; }
  }
  var _cliObj=(CLIENTES||[]).find(function(x){ return x&&String(x.nome||'').trim().toLowerCase()===cli.toLowerCase(); });
  var obj={id:id,b:b,n:n,c:cli,v:val,d:d,venc:venc,cd:cd,s:s};
  if(_cliObj){ obj.clienteNome=_cliObj.nome||cli; obj.clienteCod=_cliObj.cod||''; }
  
  if(CHQ_CTRL[id]&&CHQ_CTRL[id].dc) obj.dc=CHQ_CTRL[id].dc;
  CHQ_CTRL[id]=obj; try{ renderChequesCompensar(); }catch(e){}
  r.child(id).set(obj)
    .then(function(){ chqFecharModal(); showToast('Cheque salvo ✔','success'); })
    .catch(function(e){ showToast('Erro: '+e.message,'error'); });
}

var _CHQ_FIX_GS=[];



function chqCorrigirGratusSicredi(){
  var cfg=_legacyRepairConfig('gratusSicrediDefinitive');
  if(!cfg.bank){ showToast('Configuração de correção não encontrada no Firebase.','error'); return; }
  if(!confirm(cfg.confirmText||'Confirmar correção?')) return;
  var r=_chqRef(); if(!r){ showToast('Firebase não conectado','error'); return; }
  var idPorNum={};
  Object.keys(CHQ_CTRL).forEach(function(id){ var c=CHQ_CTRL[id]; if(c&&c.b===cfg.bank) idPorNum[String(c.n)]=id; });
  var batch={};
  (cfg.records||_CHQ_FIX_GS||[]).forEach(function(o){
    var id=idPorNum[String(o.n)]||o.id;
    var no={id:id,b:o.b,n:o.n,c:o.c,v:o.v,d:o.d,cd:o.cd,s:o.s,dc:o.dc};
    var ex=CHQ_CTRL[id]; if(ex&&ex.movBancoId) no.movBancoId=ex.movBancoId;
    batch[id]=no; CHQ_CTRL[id]=no;
  });
  try{ renderChequesCompensar(); }catch(e){}
  r.update(batch).then(function(){ showToast(cfg.successText||'✔ Correção aplicada.','success',8000); }).catch(function(e){ showToast('Erro: '+e.message,'error'); });
}




function chqCompletarGratusSicredi(){
  var cfg=_legacyRepairConfig('gratusSicrediComplete');
  if(!cfg.bank){ showToast('Configuração de correção não encontrada no Firebase.','error'); return; }
  if(!confirm(cfg.confirmText||'Confirmar complementação?')) return;
  var r=_chqRef(); if(!r){ showToast('Firebase não conectado','error'); return; }
  var idPorNum={};
  Object.keys(CHQ_CTRL).forEach(function(id){ var c=CHQ_CTRL[id]; if(c&&c.b===cfg.bank) idPorNum[String(c.n)]=id; });
  var batch={}, add=0, corr=0, jaTinha=0;
  var novos=Array.isArray(cfg.records)?cfg.records:[];
  novos.forEach(function(o){
    if(idPorNum[String(o.n)]){ jaTinha++; return; } 
    var id='CC'+_cfgChequeBankSlug(cfg.bank)+o.n;
    var no={id:id, b:cfg.bank, n:o.n, c:o.c, v:o.v, d:'', cd:o.cd, s:'C', dc:false};
    batch[id]=no; CHQ_CTRL[id]=no; add++;
  });
  Object.keys(cfg.valueCorrections||{}).forEach(function(num){ var idc=idPorNum[String(num)]; if(idc&&CHQ_CTRL[idc]){ CHQ_CTRL[idc].v=Number(cfg.valueCorrections[num])||0; batch[idc]=CHQ_CTRL[idc]; corr++; } });
  var corrSit=Array.isArray(cfg.statusCorrections)?cfg.statusCorrections:[];
  corrSit.forEach(function(o){
    var idc=idPorNum[String(o.n)];
    if(idc && CHQ_CTRL[idc] && CHQ_CTRL[idc].s!==String(o.status||'C')){ CHQ_CTRL[idc].s=String(o.status||'C'); CHQ_CTRL[idc].cd=o.cd||''; batch[idc]=CHQ_CTRL[idc]; corr++; }
  });
  if(!add && !corr){ showToast('Nada a fazer — os cheques já estão todos lá e certos.','info'); return; }
  try{ renderChequesCompensar(); }catch(e){}
  r.update(batch).then(function(){ showToast('✔ Correção aplicada: '+add+' cheque(s) adicionado(s)'+(jaTinha?(' ('+jaTinha+' já existiam)'):'')+(corr?(' + '+corr+' correção(ões)'):'')+'.','success',8000); }).catch(function(e){ showToast('Erro: '+e.message,'error'); });
}






function chqSincronizarAbaAntiga(){
  if(typeof CHEQUES_POR_FORN==='undefined'){ showToast('A aba antiga de Cheques não carregou. Recarregue a página.','error'); return; }
  var slug=Object.fromEntries(_cfgChequeBanks().map(function(x){return [x.name,x.slug||'XX'];}));
  function normB(b){ return _cfgChequeBankNormalize(b); }
  function mapS(st){ st=(st||'').toLowerCase(); if(st.indexOf('cancel')>=0)return 'X'; if(st.indexOf('compens')>=0)return 'C'; return 'A'; }
  var fornMap={}; try{ FORNECEDORES.forEach(function(f){ fornMap[f.cod]=f.nome; }); }catch(e){}
  var reais={}, bancosOld={};
  Object.keys(CHEQUES_POR_FORN).forEach(function(cod){
    (CHEQUES_POR_FORN[cod]||[]).forEach(function(c){
      var num=String(c.num||'').trim(); if(!num) return;
      var banco=normB(c.banco||''); if(!slug[banco]) return;
      bancosOld[banco]=1; var key=banco+'|'+num;
      var item={banco:banco,num:num,valor:Number(c.valor)||0,d:(c.bomPara||''),s:mapS(c.status),cd:(c.dataCompensacao||''),c:(fornMap[cod]||c._fornNome||cod||'')};
      var prev=reais[key];
      if(!prev || (!prev.d && item.d) || (item.s==='C' && prev.s!=='C')) reais[key]=item;
    });
  });
  var keys=Object.keys(reais);
  if(!keys.length){ showToast('Nenhum cheque encontrado na aba antiga.','info'); return; }
  var batch={}, nov=0, atu=0;
  keys.forEach(function(key){
    var it=reais[key], id='CC'+slug[it.banco]+it.num, ex=CHQ_CTRL[id], s, cd;
    if(ex){ if(ex.s==='C'||it.s==='C')s='C'; else if(ex.s==='X'||it.s==='X')s='X'; else s='A'; cd=ex.cd||it.cd||''; atu++; }
    else { s=it.s; cd=it.cd||''; nov++; }
    var o={id:id,b:it.banco,n:it.num,c:it.c,v:it.valor,d:it.d,cd:cd,s:s,dc:true};
    if(ex&&ex.movBancoId) o.movBancoId=ex.movBancoId;
    batch[id]=o;
  });
  
  
  
  
  
  var fantasmasIds=[], fantasmasLbl=[];
  Object.keys(CHQ_CTRL).forEach(function(id){
    var c=CHQ_CTRL[id]; if(!c||(c.s||'A')!=='A'||!bancosOld[c.b]) return;
    if(!reais[c.b+'|'+String(c.n)]){ fantasmasIds.push(id); fantasmasLbl.push(String(c.n)+' ('+c.b+')'); }
  });
  var msg='Trazer os dados reais da aba antiga:\n\n• '+nov+' cheque(s) novo(s)\n• '+atu+' corrigido(s) (fornecedor / valor / bom para)\n\nTodos marcados como "desconta da compra 🛒". Cheque compensado continua compensado.';
  if(fantasmasIds.length) msg+='\n\n⛔ E vou marcar '+fantasmasIds.length+' cheque(s) como "NÃO EXISTE" (números que não estão na sua lista real): '+fantasmasLbl.slice(0,14).join(', ')+(fantasmasLbl.length>14?'...':'')+'.\nEles continuam aparecendo na lista, cinza, só pra você ver a sequência. Não somam no total.';
  msg+='\n\nConfirmar?';
  if(!confirm(msg)) return;
  var r=_chqRef(); if(!r){ showToast('Firebase não conectado','error'); return; }
  
  fantasmasIds.forEach(function(id){ var c=CHQ_CTRL[id]; if(c){ c.s='N'; batch[id]={id:id,b:c.b,n:c.n,c:'',v:(+c.v||0),d:'',cd:'',s:'N',dc:false}; } });
  Object.keys(batch).forEach(function(id){ CHQ_CTRL[id]=batch[id]; });
  try{ renderChequesCompensar(); }catch(e){}
  r.update(batch)
    .then(function(){ showToast('✔ Sincronizado! '+nov+' novos, '+atu+' corrigidos'+(fantasmasIds.length?', '+fantasmasIds.length+' marcados "não existe"':'')+'.','success',7000); })
    .catch(function(e){ showToast('Erro: '+e.message,'error'); });
}


function cheqExportarJSON(){
  try{
    var fornMap={};
    try{ FORNECEDORES.forEach(function(f){ fornMap[f.cod]=f.nome; }); }catch(e){}
    var out=[];
    Object.keys(CHEQUES_POR_FORN||{}).forEach(function(cod){
      (CHEQUES_POR_FORN[cod]||[]).forEach(function(c){
        var o=JSON.parse(JSON.stringify(c));
        o._fornCod=cod; o._fornNome=fornMap[cod]||cod;
        out.push(o);
      });
    });
    var blob=new Blob([JSON.stringify(out,null,1)],{type:'application/json'});
    var a=document.createElement('a'); a.href=URL.createObjectURL(blob);
    a.download='cheques_aba_antiga.json';
    document.body.appendChild(a); a.click(); document.body.removeChild(a);
    showToast('Exportado '+out.length+' cheques.','success',6000);
  }catch(e){ showToast('Erro ao exportar: '+e.message,'error'); }
}
function chqExportCSV(){
  var arr=_chqLista().slice().sort(function(a,b){ if(a.b!==b.b) return (a.b||'').localeCompare(b.b||''); return (+a.n||0)-(+b.n||0); });
  var linhas=['Nº;Banco;Cliente;Valor;Data Saída;Caiu em;Situação'];
  arr.forEach(function(c){
    linhas.push([c.n||'',c.b||'',(c.c||'').replace(/;/g,','),(+c.v||0).toFixed(2).replace('.',','),c.d||'',c.cd||'',_CHQ_SIT_LBL[c.s||'A']||''].join(';'));
  });
  var blob=new Blob(['﻿'+linhas.join('\n')],{type:'text/csv;charset=utf-8'});
  var a=document.createElement('a'); a.href=URL.createObjectURL(blob); a.download='cheques_controle.csv';
  document.body.appendChild(a); a.click(); document.body.removeChild(a);
}



function _supGetDB(){
  if(window._fbDB) return window._fbDB;
  try{ const db=firebase.database(); window._fbDB=db; return db; }catch(_){ return null; }
}

function supAplicarPatch(){
  const statusEl=document.getElementById('sup-patch-status');
  const msg='🔒 Patches JavaScript remotos estão desativados por segurança. Correções de código devem ser publicadas por uma nova versão/deploy do ERP.';
  if(statusEl){ statusEl.style.color='#b45309'; statusEl.textContent=msg; }
  showToast(msg,'info',8000);
}

function supCarregarPatches(){
  const lista=document.getElementById('sup-patches-lista');
  if(!lista) return;
  const db=_supGetDB();
  if(!db){ lista.innerHTML='<span style="color:#e74c3c">Firebase não conectado. Recarregue a página.</span>'; return; }
  lista.innerHTML='<span style="color:#aaa">Carregando...</span>';
  db.ref('erp/suporte_patches').once('value', snap=>{
    const patches=snap.val()||{};
    const arr=Object.values(patches).sort((a,b)=>(b.id||'').localeCompare(a.id||''));
    if(!arr.length){ lista.innerHTML='<span style="color:#aaa">Nenhum patch aplicado ainda.</span>'; return; }
    lista.innerHTML=`<table style="width:100%;border-collapse:collapse">
      <thead><tr style="background:#e8eaf6;font-size:.79rem;text-align:left">
        <th style="padding:5px 8px">Data</th>
        <th style="padding:5px 8px">Título</th>
        <th style="padding:5px 8px">Por</th>
        <th style="padding:5px 8px">Status</th>
        <th style="padding:5px 8px"></th>
      </tr></thead><tbody>${arr.map(p=>`<tr style="border-bottom:1px solid #eee">
        <td style="padding:5px 8px;font-size:.78rem;color:#888">${p.aplicado||''}</td>
        <td style="padding:5px 8px;font-weight:600">${esc(p.titulo||'')}</td>
        <td style="padding:5px 8px;color:#888">${esc(p.por||'')}</td>
        <td style="padding:5px 8px"><span style="background:#fff3cd;color:#8a6d00;border-radius:10px;padding:2px 8px;font-size:.75rem">🔒 Arquivado — não executa</span></td>
        <td style="padding:5px 8px"><span style="font-size:.72rem;color:#999">Deploy necessário</span></td>
      </tr>`).join('')}</tbody>
    </table>`;
  });
}

