let AFAZERES_DB = [];
const _syncAfazeres = _criarSincroniaPorChave('afazeres', AFAZERES_DB, 'AF');
function saveAfazeres(){ localStorage.setItem('mm_afazeres', JSON.stringify(AFAZERES_DB)); try{fbSalvar();}catch(e){} }





let _afFiltro = 'todos';

function _afHojeISO(){ const d=new Date(),z=n=>String(n).padStart(2,'0'); return d.getFullYear()+'-'+z(d.getMonth()+1)+'-'+z(d.getDate()); }
let _afDiaSel = _afHojeISO();          
let _afMesAtual = _afDiaSel.slice(0,7); 

function _afDataISO(a){
  if(a&&a.data) return a.data;
  const c=(a&&a.criadoEm)||'';
  const m=c.match(/^(\d{2})\/(\d{2})\/(\d{4})/);
  return m?(m[3]+'-'+m[2]+'-'+m[1]):'';
}
function _afISOparaBR(iso){ const m=String(iso||'').match(/^(\d{4})-(\d{2})-(\d{2})$/); return m?(m[3]+'/'+m[2]+'/'+m[1]):(iso||''); }
function _afAgora(){
  const d=new Date(), z=n=>String(n).padStart(2,'0');
  return z(d.getDate())+'/'+z(d.getMonth()+1)+'/'+d.getFullYear()+' '+z(d.getHours())+':'+z(d.getMinutes());
}
function afMes(delta){
  const [y,m]=_afMesAtual.split('-').map(Number);
  const d=new Date(y,(m-1)+delta,1);
  _afMesAtual=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0');
  renderAfazeres();
}
function afSelDia(iso){
  _afDiaSel=iso;
  _afMesAtual=iso.slice(0,7);
  const di=document.getElementById('af-data'); if(di) di.value=iso;
  renderAfazeres();
  const inp=document.getElementById('af-nova'); if(inp) inp.focus();
}
function afDataChange(){
  const di=document.getElementById('af-data');
  if(di&&di.value){ afSelDia(di.value); }
}


function _afSomaMes(iso, n){
  const [y,m,d]=iso.split('-').map(Number);
  const dt=new Date(y,(m-1)+n,1);
  const ultimoDia=new Date(dt.getFullYear(),dt.getMonth()+1,0).getDate();
  const dia=Math.min(d,ultimoDia);
  return dt.getFullYear()+'-'+String(dt.getMonth()+1).padStart(2,'0')+'-'+String(dia).padStart(2,'0');
}
function afazerAdd(){
  const inp=document.getElementById('af-nova'); if(!inp) return;
  const txt=(inp.value||'').trim();
  if(!txt){ inp.focus(); return; }
  const di=document.getElementById('af-data');
  const dia=(di&&di.value)||_afDiaSel||_afHojeISO();
  const repSel=document.getElementById('af-repetir');
  let rep=parseInt((repSel&&repSel.value)||'1',10); if(!(rep>=1)) rep=1;
  const autor=(typeof cu!=='undefined'&&cu?cu.name:'');
  const serie=rep>1?('S'+Date.now()):'';
  const agora=_afAgora();
  for(let k=0;k<rep;k++){
    const diaK=k===0?dia:_afSomaMes(dia,k);
    AFAZERES_DB.push({ id:_syncAfazeres.novoId(), texto:txt, feito:false, data:diaK, serie:serie,
      criadoEm:agora, feitoEm:'', autor:autor });
  }
  inp.value='';
  if(repSel) repSel.value='1';
  saveAfazeres();
  _afDiaSel=dia; _afMesAtual=dia.slice(0,7);
  renderAfazeres();
  if(rep>1){ try{ showToast('Serviço repetido em '+rep+' meses (mesmo dia).','success'); }catch(e){} }
  inp.focus();
}
function afazerToggle(id){
  const a=AFAZERES_DB.find(x=>x&&x.id===id); if(!a) return;
  a.feito=!a.feito;
  a.feitoEm=a.feito?_afAgora():'';
  saveAfazeres();
  renderAfazeres();
}
function afazerExcluir(id){
  const a=AFAFZ_find(id); if(!a) return;
  if(a.serie){
    const todos=AFAZERES_DB.filter(x=>x&&x.serie===a.serie);
    if(todos.length>1){
      const apagarSerie=confirm('Este serviço se repete em '+todos.length+' meses.\n\nAceitar (OK) = apagar TODAS as repetições\nCancelar = apagar só a deste dia');
      if(apagarSerie){
        const idxs=[]; AFAZERES_DB.forEach((x,i)=>{ if(x&&x.serie===a.serie) idxs.push(i); });
        idxs.sort((p,q)=>q-p).forEach(i=>_syncAfazeres.remover(i));
        saveAfazeres(); renderAfazeres(); return;
      }
    }
  }
  if(!confirm('Excluir este serviço?\n\n"'+a.texto+'"')) return;
  const i=AFAZERES_DB.findIndex(x=>x&&x.id===id);
  if(i>=0) _syncAfazeres.remover(i);
  saveAfazeres();
  renderAfazeres();
}
function AFAFZ_find(id){ return AFAZERES_DB.find(x=>x&&x.id===id); }
function afazerFiltro(f){
  _afFiltro=f;
  [['todos','af-f-todos','#1a3a2a'],['fazer','af-f-fazer','#f39c12'],['feito','af-f-feito','#27ae60']].forEach(function(par){
    const b=document.getElementById(par[1]); if(!b) return;
    const ativo=par[0]===f;
    b.style.background=ativo?par[2]:'#fff';
    b.style.color=ativo?'#fff':(par[0]==='todos'?'#1a3a2a':par[0]==='fazer'?'#b9770e':'#1e874b');
  });
  renderAfazeres();
}
function renderAfazeres(){
  const box=document.getElementById('af-lista'); if(!box) return;
  const esc2=t=>String(t==null?'':t).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
  const feitos=AFAZERES_DB.filter(a=>a&&a.feito).length;
  const fazer=AFAZERES_DB.filter(a=>a&&!a.feito).length;
  const setT=(id,v)=>{const e=document.getElementById(id); if(e) e.textContent=v;};
  setT('af-kpi-fazer',fazer); setT('af-kpi-feito',feitos); setT('af-kpi-total',AFAZERES_DB.length);

  
  const di=document.getElementById('af-data'); if(di && !di.value) di.value=_afDiaSel;
  const MES_NOME=['Janeiro','Fevereiro','Março','Abril','Maio','Junho','Julho','Agosto','Setembro','Outubro','Novembro','Dezembro'];
  const [ay,am]=_afMesAtual.split('-').map(Number);
  const tit=document.getElementById('af-cal-titulo'); if(tit) tit.textContent=MES_NOME[am-1]+' de '+ay;
  
  const porDia={};
  AFAZERES_DB.forEach(function(a){ if(!a) return; const iso=_afDataISO(a); if(!iso||iso.slice(0,7)!==_afMesAtual) return;
    if(!porDia[iso]) porDia[iso]={fazer:0,feito:0}; if(a.feito) porDia[iso].feito++; else porDia[iso].fazer++; });
  const primeiro=new Date(ay,am-1,1);
  const diaSemInicio=primeiro.getDay(); 
  const diasNoMes=new Date(ay,am,0).getDate();
  const hojeISO=_afHojeISO();
  const cal=document.getElementById('af-cal');
  if(cal){
    let h='<div style="display:grid;grid-template-columns:repeat(7,1fr);gap:5px">';
    ['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'].forEach(function(d){ h+='<div style="text-align:center;font-size:.68rem;font-weight:700;color:#8a938d;padding:2px 0">'+d+'</div>'; });
    for(let i=0;i<diaSemInicio;i++) h+='<div></div>';
    for(let d=1;d<=diasNoMes;d++){
      const iso=ay+'-'+String(am).padStart(2,'0')+'-'+String(d).padStart(2,'0');
      const info=porDia[iso];
      const sel=iso===_afDiaSel;
      const ehHoje=iso===hojeISO;
      let dot='';
      if(info){ const cor=info.fazer>0?'#f39c12':'#27ae60'; const qt=info.fazer+info.feito;
        dot='<div style="position:absolute;bottom:5px;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:2px"><span style="width:7px;height:7px;border-radius:50%;background:'+cor+'"></span><span style="font-size:.62rem;font-weight:700;color:'+cor+'">'+qt+'</span></div>'; }
      const bg=sel?'#1a3a2a':(ehHoje?'#eafaf1':'#fff');
      const cor=sel?'#fff':'#1a3a2a';
      const bd=sel?'#1a3a2a':(ehHoje?'#27ae60':'#e6eaee');
      h+='<div onclick="afSelDia(\''+iso+'\')" style="position:relative;cursor:pointer;border:1.5px solid '+bd+';background:'+bg+';color:'+cor+';border-radius:9px;min-height:46px;padding:5px 0 0;text-align:center;font-weight:700;font-size:.86rem">'+d+dot+'</div>';
    }
    h+='</div>';
    cal.innerHTML=h;
  }

  
  const dtit=document.getElementById('af-dia-titulo');
  if(dtit){ const bg=_afDiaSel; dtit.textContent='Serviços de '+_afISOparaBR(_afDiaSel)+(_afDiaSel===hojeISO?' (hoje)':''); }
  let lista=AFAZERES_DB.filter(a=>a&&_afDataISO(a)===_afDiaSel);
  if(_afFiltro==='fazer') lista=lista.filter(a=>a&&!a.feito);
  else if(_afFiltro==='feito') lista=lista.filter(a=>a&&a.feito);
  
  lista.sort(function(a,b){
    if((a.feito?1:0)!==(b.feito?1:0)) return a.feito?1:-1;
    return String(b.criadoEm||'').localeCompare(String(a.criadoEm||''));
  });
  if(!lista.length){
    box.innerHTML='<div style="color:#999;text-align:center;padding:26px;font-size:.9rem">Nenhum serviço neste dia. Escreva um acima e clique em Adicionar. 👆</div>';
    return;
  }
  box.innerHTML=lista.map(function(a){
    const feito=!!a.feito;
    const bg=feito?'#eafaf1':'#fff8e1';
    const bd=feito?'#27ae60':'#f39c12';
    const badge=feito
      ? '<span style="background:#27ae60;color:#fff;border-radius:12px;padding:2px 10px;font-size:.72rem;font-weight:700">✓ Feito</span>'
      : '<span style="background:#f39c12;color:#fff;border-radius:12px;padding:2px 10px;font-size:.72rem;font-weight:700">A Fazer</span>';
    const txtStyle=feito?'text-decoration:line-through;color:#7d8a83':'color:#1a3a2a';
    const quando=feito
      ? 'Criado '+esc2(a.criadoEm||'—')+' · Feito '+esc2(a.feitoEm||'—')
      : 'Criado '+esc2(a.criadoEm||'—');
    return '<div style="display:flex;align-items:center;gap:12px;background:'+bg+';border-left:5px solid '+bd+';border-radius:10px;padding:11px 14px;margin-bottom:8px">'
      +'<div style="flex:1;min-width:0">'
        +'<div style="font-weight:700;font-size:.95rem;'+txtStyle+';word-break:break-word">'+esc2(a.texto)+'</div>'
        +'<div style="font-size:.72rem;color:#8a938d;margin-top:3px">'+quando+(a.autor?' · '+esc2(a.autor):'')+(a.serie?' · 🔁 repete todo mês':'')+'</div>'
      +'</div>'
      +badge
      +'<button onclick="afazerToggle(\''+a.id+'\')" title="'+(feito?'Voltar para A Fazer':'Marcar como Feito')+'" style="border:none;border-radius:8px;padding:7px 12px;cursor:pointer;font-weight:700;font-size:.8rem;'+(feito?'background:#eee;color:#555':'background:#27ae60;color:#fff')+'">'+(feito?'↩ Reabrir':'✓ Feito')+'</button>'
      +'<button onclick="afazerExcluir(\''+a.id+'\')" title="Excluir" style="border:none;border-radius:8px;padding:7px 10px;cursor:pointer;background:#fdecea;color:#c0392b;font-size:.85rem">🗑️</button>'
      +'</div>';
  }).join('');
}
