function _cpEmpresa(c){
  if(c && c.empresa) return c.empresa;
  const nome=c&&c.bancoNome;
  if(nome && typeof BANCOS_DB!=='undefined' && BANCOS_DB){
    const b=BANCOS_DB.find(function(x){ const n=x.banco+(x.tipo==='Conta Terceiro'&&x.titular?' ('+x.titular+')':''); return n===nome||x.banco===nome; });
    if(b && b.empresa) return b.empresa;
  }
  return '';
}

