function deSalvarDoc(){
  const empSel = document.getElementById('de-emp-sel')?.value||'';
  const cat    = document.getElementById('de-cat-sel')?.value||'Outros';
  const data   = document.getElementById('de-data-sel')?.value||new Date().toISOString().slice(0,10);
  const fileEl = document.getElementById('de-file-input');
  const statusEl= document.getElementById('de-upload-status');
  if(!empSel){alert('Selecione uma empresa.');return;}
  if(!fileEl||!fileEl.files||!fileEl.files[0]){alert('Selecione um arquivo.');return;}
  const file=fileEl.files[0];
  if(file.size>20*1024*1024){alert('Arquivo muito grande. Máximo permitido: 20 MB.');return;}
  if(!window._fbDB){ alert('Sem conexão com a nuvem agora. Aguarde alguns segundos e tente de novo — os documentos são guardados na nuvem.'); return; }
  if(statusEl) statusEl.textContent='Enviando para a nuvem...';
  const [empTipo,empNome]=empSel.split('|');
  const validade=document.getElementById('de-validade')?.value||'';
  const avisarDias=(function(){ const n=parseInt(document.getElementById('de-avisardias')?.value); return isNaN(n)?30:n; })();
  const reader=new FileReader();
  reader.onload=function(e){
    const id='de_'+Date.now()+'_'+Math.floor(Math.random()*100000);
    window._fbDB.ref('erp/empresaDocs/'+id).set(e.target.result)
      .then(function(){
        const doc={ id:id, empresaTipo:empTipo, empresaNome:empNome, nomeArq:file.name, categoria:cat, data:data, validade:validade, avisarDias:avisarDias, mimeType:file.type||'application/octet-stream', _nuvem:true };
        DOCS_EMPRESAS.push(doc);
        _deSalvar();
        try{ document.dispatchEvent(new CustomEvent('erp:alert-source-changed',{detail:{source:'documentos_empresas'}})); }catch(e){}
        cm();
        renderDocsEmpresas();
        showToast('✅ Documento salvo: '+file.name,'success',4000);
      })
      .catch(function(err){ if(statusEl) statusEl.textContent=''; alert('Não consegui enviar o documento para a nuvem: '+((err&&err.message)||err)); });
  };
  reader.onerror=()=>{ if(statusEl) statusEl.textContent='Erro ao ler arquivo.'; };
  reader.readAsDataURL(file);
}

function deVerDoc(id){
  const d=DOCS_EMPRESAS.find(x=>x.id===id);
  if(!d){showToast('Documento não encontrado.','error');return;}
  if(d.base64){ _fdAbrirDataUrl(d, d.base64); return; } 
  if(!window._fbDB){ showToast('Sem conexão com a nuvem agora — tente de novo em instantes.','error'); return; }
  showToast('Carregando documento...','info',2500);
  window._fbDB.ref('erp/empresaDocs/'+d.id).once('value')
    .then(function(snap){ _fdAbrirDataUrl(d, snap.val()); })
    .catch(function(){ showToast('Erro ao carregar o documento da nuvem.','error'); });
}

function deExcluir(id){
  const d=DOCS_EMPRESAS.find(x=>x.id===id);
  if(!d) return;
  if(!confirm('Excluir o documento "'+d.nomeArq+'" de '+d.empresaNome+'?')) return;
  try{ if(window._fbDB && d.id) window._fbDB.ref('erp/empresaDocs/'+d.id).remove(); }catch(e){}
  _syncDocsEmpresas.remover(DOCS_EMPRESAS.findIndex(x=>x.id===id));
  _deSalvar();
  renderDocsEmpresas();
  showToast('Documento excluído.','success');
}







function _bancoNomePorCod(cod){
  if(!cod) return '';
  const src=(typeof BANCOS_DB!=='undefined'&&Array.isArray(BANCOS_DB))?BANCOS_DB:[];
  const b=src.find(x=>x.cod===cod||x.banco===cod);
  if(!b) return (typeof cod==='string'?cod:'');
  return b.banco+(b.tipo==='Conta Terceiro'&&b.titular?' ('+b.titular+')':'');
}
function salvarContaPagar(){
  const desc=document.getElementById('cp-desc')?.value.trim();
  const valor=parseFloat(document.getElementById('cp-valor')?.value)||0;
  const parcelado=document.getElementById('cp-parcelado')?.checked||false;
  if(!desc||valor<=0){alert('Preencha descrição e valor!');return;}
  const bancoCod=document.getElementById('cp-banco')?.value||'';
  const bancoNome=_bancoNomePorCod(bancoCod);
  const hoje=new Date().toISOString().slice(0,10).split('-').reverse().join('/');
  const cred=document.getElementById('cp-cred')?.value.trim()||'';
  const cat=document.getElementById('cp-cat')?.value.trim()||'Outros';
  const obs=document.getElementById('cp-obs')?.value.trim()||'';
  
  
  
  
  let tipoForn=document.getElementById('cp-tipo-forn')?.value||'';
  if(tipoForn!=='compra'&&tipoForn!=='despesa'){
    if(cred && typeof getFornAtivos==='function' && getFornAtivos().some(f=>f.nome===cred)) tipoForn='compra';
    else tipoForn='despesa';
  }
  const empresa=document.getElementById('cp-empresa')?.value||'';
  if(!empresa){alert('Selecione a empresa responsável por esta conta.');return;}

  if(parcelado){
    
    const nparc=parseInt(document.getElementById('cp-nparc')?.value)||1;
    const dia=parseInt(document.getElementById('cp-diaparc')?.value)||10;
    const mesVal=document.getElementById('cp-mesparc')?.value;
    if(!mesVal||nparc<1){alert('Preencha o mês da 1ª parcela e número de parcelas!');return;}
    const [anoI,mesI]=mesVal.split('-').map(Number);
    const grupoId='grp_'+Date.now(); 
    let adicionados=0;
    for(let i=0;i<nparc;i++){
      let m=mesI+i; let a=anoI+Math.floor((m-1)/12); m=((m-1)%12)+1;
      const diaVenc=Math.min(dia, new Date(a,m,0).getDate());
      const vencFmt=String(diaVenc).padStart(2,'0')+'/'+String(m).padStart(2,'0')+'/'+a;
      CONTAS_PAGAR.push({ id:_novoIdCP(),
        lancto: hoje, desc: desc+' ('+(i+1)+'/'+nparc+')',
        cred, cat, bancoCod, bancoNome, tipoForn, empresa,
        venc: vencFmt, valor, grupoId, totalParcelas: nparc,
        status: 'Pendente', dataPgto:'', obs
      });
      adicionados++;
    }
    saveContasPagar(); renderContasPagar();
    try{renderFluxo();}catch(e){}
    try{renderDashboard();}catch(e){}
    cm();
    showToast('✅ '+adicionados+' parcela(s) lançada(s) em Contas a Pagar!','success');
  } else {
    
    const venc=document.getElementById('cp-venc')?.value;
    if(!venc){alert('Preencha a data de vencimento!');return;}
    CONTAS_PAGAR.push({ id:_novoIdCP(),
      lancto: hoje, desc, cred, cat, bancoCod, bancoNome, tipoForn, empresa,
      venc: venc.split('-').reverse().join('/'), valor,
      status: document.getElementById('cp-status')?.value||'Pendente',
      dataPgto:'', obs
    });
    saveContasPagar(); renderContasPagar();
    try{renderFluxo();}catch(e){}
    try{renderDashboard();}catch(e){}
    cm();
    showToast('Conta a pagar registrada!','success');
  }
}

function editContaPagar(idx, id){
  
  
  
  if(id){ const fresh=_cpIdxPorId(id); if(fresh>=0) idx=fresh; }
  const c=CONTAS_PAGAR[idx];
  if(!c) return;
  const vencISO=c.venc.split('/').reverse().join('-');
  const catOpts=c.cat||'';
  const _bcSrc=(typeof BANCOS_DB!=='undefined'&&Array.isArray(BANCOS_DB))?BANCOS_DB:[];
  const bancoOpts='<option value="">— Selecione —</option>'+_bcSrc.map(b=>{
    const nomeComp=b.banco+(b.tipo==='Conta Terceiro'&&b.titular?' ('+b.titular+')':'');
    const sel=(b.cod===c.bancoCod)||(c.bancoNome&&(c.bancoNome===b.banco||c.bancoNome===nomeComp));
    return '<option value="'+esc(b.cod||b.banco)+'"'+(sel?' selected':'')+'>'+esc(nomeComp)+(b.empresa?' — '+esc(b.empresa):'')+'</option>';
  }).join('');
  const stOpts=['Pendente','Pago','Atrasado','Agendado'].map(s=>'<option'+(s===c.status?' selected':'')+'>'+s+'</option>').join('');
  document.querySelectorAll('.modal-ov[data-dynamic="1"]').forEach(e=>e.remove());
  const _ovE=document.createElement('div'); _ovE.className='modal-ov'; _ovE.id='modal-ov'; _ovE.dataset.dynamic='1';
  const body=document.createElement('div'); body.id='modal-body'; body.className='modal';
  _ovE.appendChild(body); document.body.appendChild(_ovE);
  body.innerHTML=
    '<h3>✏️ Editar Conta a Pagar</h3>'+
    '<input type="hidden" id="ecp-idx" value="'+idx+'">'+
    '<input type="hidden" id="ecp-id" value="'+esc(c.id||'')+'">'+
    '<div class="fg"><label>Descrição</label><input id="ecp-desc" value="'+esc(c.desc)+'"></div>'+
    '<div class="fg"><label>Fornecedor / Credor</label><input id="ecp-cred" value="'+esc(c.cred||'')+'"></div>'+
    '<div class="fg"><label>Categoria <span style="font-weight:400;color:var(--gray)">(escolha ou digite)</span></label>'+
    '<input id="ecp-cat" list="ecp-cat-list" value="'+esc(catOpts)+'" placeholder="Ex: Aluguel, Energia...">'+
    '<datalist id="ecp-cat-list">'+
    '<option>Aluguel</option><option>Energia</option><option>Água</option>'+
    '<option>Internet/Telefone</option><option>Frete</option><option>Folha de Pagamento</option>'+
    '<option>Imposto / FGTS</option><option>Manutenção</option><option>Combustível</option>'+
    '<option>Material de Escritório</option><option>Serviços Terceiros</option>'+
    '<option>Seguro</option><option>Contabilidade</option><option>Advocacia</option>'+
    '<option>Limpeza</option><option>Alimentação</option><option>Transporte</option>'+
    '<option>Equipamentos</option><option>Peças e Insumos</option><option>Outros</option>'+
    '</datalist></div>'+
    '<div class="fg"><label>Empresa</label><select id="ecp-empresa"><option value="">— Selecione a empresa —</option>'+_empresasOptions(c.empresa||'',true)+'</select></div>'+
    '<div class="fg"><label>Banco de Pagamento</label><select id="ecp-banco" onchange="_sincronizarEmpresaPorBanco(&#39;ecp-banco&#39;,&#39;ecp-empresa&#39;)">'+bancoOpts+'</select></div>'+
    '<div class="fg"><label>Vencimento</label><input id="ecp-venc" type="date" value="'+vencISO+'"></div>'+
    '<div class="fg"><label>Valor R$</label><input id="ecp-valor" type="number" min="0" step="0.01" value="'+c.valor+'"></div>'+
    '<div class="fg"><label>Status</label><select id="ecp-status">'+stOpts+'</select></div>'+
    '<div class="fg"><label>Data Pagamento</label><input id="ecp-pgto" type="date" value="'+(c.dataPgto?c.dataPgto.split('/').reverse().join('-'):'')+'"></div>'+
    '<div class="fg"><label>Obs.</label><input id="ecp-obs" value="'+esc(c.obs||'')+'"></div>'+
    '<div class="modal-ft">'+
    '<button class="btn-edit-danger" onclick="excluirContaPagar('+idx+',\''+esc(c.id||'')+'\')">🗑️ Excluir</button>'+
    '<button class="btn-cancel" onclick="cm()">Cancelar</button>'+
    '<button class="btn-save" onclick="salvarEditContaPagar()">💾 Salvar</button></div>';
  _ovE.classList.add('open');
}

function salvarEditContaPagar(){
  let idx=parseInt(document.getElementById('ecp-idx').value);
  const idAlvo=document.getElementById('ecp-id')?.value||'';
  if(idAlvo){ const fresh=_cpIdxPorId(idAlvo); if(fresh>=0) idx=fresh; }
  const c=CONTAS_PAGAR[idx]; if(!c) return;
  const statusAntes=c.status;
  const bancoCod=document.getElementById('ecp-banco').value||'';
  const pgto=document.getElementById('ecp-pgto').value;
  c.desc=document.getElementById('ecp-desc').value.trim();
  c.cred=document.getElementById('ecp-cred').value.trim();
  c.cat=document.getElementById('ecp-cat').value.trim()||'Outros';
  c.bancoCod=bancoCod;
  c.bancoNome=_bancoNomePorCod(bancoCod);
  const empresaEdit=document.getElementById('ecp-empresa')?.value||'';
  if(!empresaEdit){alert('Selecione a empresa responsável por esta conta.');return;}
  c.empresa=empresaEdit;
  c.venc=document.getElementById('ecp-venc').value.split('-').reverse().join('/');
  c.valor=parseFloat(document.getElementById('ecp-valor').value)||0;
  c.status=document.getElementById('ecp-status').value;
  c.dataPgto=pgto?pgto.split('-').reverse().join('/'):'';
  c.obs=document.getElementById('ecp-obs').value.trim();
  
  
  
  
  c._upd=Date.now();
  
  
  
  if(c.status==='Pago' && statusAntes!=='Pago' && c.bancoNome && !c.movBancoIdCP && (Number(c.valor)||0)>0){
    const _movEdit=registrarMovBanco(c.bancoNome, pgto||'', 'Pagto: '+(c.desc||c.cred||''), 'Saida', Number(c.valor)||0);
    if(_movEdit) c.movBancoIdCP=_movEdit.id;
  }
  saveContasPagar(); renderContasPagar();
  try{renderFluxo();}catch(e){}
  try{renderDashboard();}catch(e){}
  cm();
  showToast('Conta a pagar atualizada!','success');
  
  
  
  if(c.ticket && c.status==='Pago' && statusAntes!=='Pago' && TICKETS_DB[c.ticket]){
    _baixarSaldoTicket(c.ticket, Number(c.valor)||0, c.dataPgto);
    saveDB();
    try{renderTickets();}catch(e){}
    showToast('Ticket #'+c.ticket+' atualizado!','success');
  }
}

function registrarMovBanco(bancoNome, dataISO, descricao, tipo, valor){
  
  
  
  if(!bancoNome||!valor) return null;
  const b=BANCOS_DB.find(x=>{
    const n=x.banco+(x.tipo==='Conta Terceiro'?' ('+x.titular+')':'');
    return n===bancoNome||x.banco===bancoNome;
  });
  if(!b){ console.warn('Banco nao encontrado:',bancoNome); return null; }
  const dataFmt=dataISO?dataISO.split('-').reverse().join('/')
    :new Date().toLocaleDateString('pt-BR');
  const mov={
    id:'LB-'+Date.now()+'-'+Math.random().toString(36).slice(2,6),
    bancoCod:b.cod, data:dataFmt, descricao, tipo, valor:Number(valor)
  };
  LANC_BANCO_DB.push(mov);
  saveBancos();
  renderBancos();
  return mov;
}

function pagarContaRapido(idx, id){
  
  
  if(id){ const fresh=_cpIdxPorId(id); if(fresh>=0) idx=fresh; }
  const c=CONTAS_PAGAR[idx]; if(!c) return;
  const fmt=v=>_numFinito(v,0).toLocaleString('pt-BR',{minimumFractionDigits:2});
  const body=document.getElementById('modal-body');
  body.className='modal';
  const hoje=new Date().toISOString().slice(0,10);
  const bancoOpts=(BANCOS_DB||[]).map(b=>{
    const n=b.banco+(b.tipo==='Conta Terceiro'?' ('+b.titular+')':'');
    return '<option value="'+esc(n)+'"'+(n===c.bancoNome||b.banco===c.bancoNome?' selected':'')+'>'+esc(n)+(b.empresa?' — '+esc(b.empresa):'')+'</option>';
  }).join('');

  
  const fornCod = c.fornCod || (FORNECEDORES.find(f=>f.nome===c.cred)||{}).cod || null;
  const adtsPendentes = fornCod ? (ADT_POR_FORN[fornCod]||[]).filter(a=>a.status==='Pendente') : [];
  const totalAdtDisp = adtsPendentes.reduce((s,a)=>s+Number(a.valor),0);
  const valorCP = Number(c.valor);
  const adtSugerido = Math.min(totalAdtDisp, valorCP);

  const saldoAposAdt = Math.max(0, valorCP - adtSugerido);

  const adtBlock = totalAdtDisp > 0
    ? '<div style="background:#fff8e1;border:1px solid #f9a825;border-radius:8px;padding:12px 14px;margin-bottom:14px">'
        +'<div style="font-size:.78rem;font-weight:800;color:#7b4f00;margin-bottom:6px">💰 ADIANTAMENTOS DISPONÍVEIS — '+esc(c.cred||fornCod)+'</div>'
        +'<div style="font-size:.82rem;color:#555;margin-bottom:8px">Saldo em adiantamentos: <b style="color:#27ae60">R$ '+fmt(totalAdtDisp)+'</b> ('+adtsPendentes.length+' lançamento'+(adtsPendentes.length!==1?'s':'')+')</div>'
        +'<div class="fg" style="margin-bottom:6px">'
          +'<label style="font-size:.78rem">Valor a compensar com adiantamento (R$)</label>'
          +'<input id="pcp-adt" type="number" min="0" step="0.01" max="'+adtSugerido.toFixed(2)+'" value="'+adtSugerido.toFixed(2)+'" oninput="atualizarLiquidoCP('+valorCP+')" style="width:100%;box-sizing:border-box;padding:7px 10px;border:1px solid #f9a825;border-radius:5px">'
        +'</div>'
        +'<div style="display:flex;gap:10px;align-items:center">'
          +'<span style="font-size:.82rem;color:#555">Saldo restante após compensação:</span>'
          +'<span id="pcp-liquido-label" style="font-size:1rem;font-weight:900;color:'+(saldoAposAdt>0?'#c0392b':'#1a5c35')+'">R$ '+fmt(saldoAposAdt)+'</span>'
        +'</div>'
      +'</div>'
    : '';

  
  const botoesFooter = totalAdtDisp > 0
    ? '<button class="btn-cancel" onclick="cm()">Cancelar</button>'
      +'<button class="btn-save" style="background:#e67e22;margin-right:6px" id="btn-so-compensar">💰 Compensar e manter saldo em aberto</button>'
      +'<button class="btn-save" style="background:#27ae60" id="btn-pagar-tudo">✅ Pagar valor total</button>'
    : '<button class="btn-cancel" onclick="cm()">Cancelar</button>'
      +'<button class="btn-save" style="background:#27ae60" id="btn-pagar-tudo">✅ Confirmar Pagamento</button>';

  body.innerHTML=
    '<h3>💳 Baixar Pagamento</h3>'+
    '<div style="background:#fde8e8;border-radius:8px;padding:12px 14px;margin-bottom:14px">'+
      '<b>'+esc(c.desc||c.cred)+'</b><br>'+
      '<span style="font-size:.9rem">Valor em aberto: <b>R$ '+fmt(valorCP)+'</b></span>'+
      (c.cred?'<span style="font-size:.82rem;color:#555"> &nbsp;&middot;&nbsp; '+esc(c.cred)+'</span>':'')+
    '</div>'+
    adtBlock+
    '<input type="hidden" id="pcp-idx" value="'+idx+'">'+
    '<input type="hidden" id="pcp-id" value="'+esc(c.id||'')+'">'+
    '<input type="hidden" id="pcp-forn-cod" value="'+(fornCod||'')+'">'+
    '<div class="fg"><label>Valor a Pagar Agora (R$)</label>'+
      '<input id="pcp-valor-pagar" type="number" min="0.01" step="0.01" max="'+valorCP.toFixed(2)+'" value="'+valorCP.toFixed(2)+'">'+
      '<div style="font-size:.74rem;color:#888;margin-top:2px">Pra pagar em partes, digite um valor menor — o restante fica pendente aqui mesmo pra próxima baixa.</div>'+
    '</div>'+
    '<div class="fg"><label>Data</label><input id="pcp-data" type="date" value="'+hoje+'"></div>'+
    '<div class="fg"><label>Conta Bancária (Debitada) — obrigatório para pagar valor total</label><select id="pcp-banco"><option value="">— Selecione —</option>'+bancoOpts+'</select></div>'+
    '<div class="fg"><label>Observação</label><input id="pcp-obs" placeholder="Opcional"></div>'+
    '<div class="modal-ft" style="flex-wrap:wrap;gap:6px">'+botoesFooter+'</div>';
  document.getElementById('modal-ov').classList.add('open');
  
  const btnSoComp=document.getElementById('btn-so-compensar');
  const btnPagarTudo=document.getElementById('btn-pagar-tudo');
  if(btnSoComp) btnSoComp.addEventListener('click', function(){ confirmarPagarCP('so-compensar'); });
  if(btnPagarTudo) btnPagarTudo.addEventListener('click', function(){ confirmarPagarCP('pagar-tudo'); });
}

function atualizarLiquidoCP(valorCP){
  const fmt=v=>_numFinito(v,0).toLocaleString('pt-BR',{minimumFractionDigits:2});
  const adt=parseFloat(document.getElementById('pcp-adt')?.value)||0;
  const liq=Math.max(0,valorCP-adt);
  const el=document.getElementById('pcp-liquido-label');
  if(el) el.textContent='R$ '+fmt(liq);
}

function confirmarPagarCP(modo){
  let idx=parseInt(document.getElementById('pcp-idx').value);
  
  
  
  
  
  
  
  const idAlvo=document.getElementById('pcp-id')?.value||'';
  if(idAlvo){ const fresh=_cpIdxPorId(idAlvo); if(fresh>=0) idx=fresh; }
  const c=CONTAS_PAGAR[idx]; if(!c) return;
  const dataISO=document.getElementById('pcp-data').value;
  const banco=document.getElementById('pcp-banco').value;
  const obs=document.getElementById('pcp-obs').value.trim();
  if(!dataISO){alert('Informe a data!');return;}
  const dataFmt=dataISO.split('-').reverse().join('/');
  const fmt=v=>_numFinito(v,0).toLocaleString('pt-BR',{minimumFractionDigits:2});

  const fornCod=document.getElementById('pcp-forn-cod')?.value||c.fornCod||null;
  const adtInput=document.getElementById('pcp-adt');
  const adtAplicar=adtInput ? Math.max(0,parseFloat(adtInput.value)||0) : 0;

  
  
  const valorOriginalAntes=Number(c.valor);

  
  
  
  
  
  let valorPagarAgora=valorOriginalAntes;
  if(modo==='pagar-tudo'){
    const valorPagarInput=document.getElementById('pcp-valor-pagar');
    if(valorPagarInput && valorPagarInput.value!==''){
      const v=parseFloat(valorPagarInput.value);
      if(!isNaN(v)) valorPagarAgora=Math.min(Math.max(0.01,v), valorOriginalAntes);
    }
  }

  const valorLiquido=Math.max(0,valorPagarAgora-adtAplicar);
  const restanteAposEssaBaixa=Math.max(0,valorOriginalAntes-valorPagarAgora);
  if(!Array.isArray(c.pagamentos)) c.pagamentos=[];

  
  if(modo==='so-compensar'){
    if(adtAplicar<=0){alert('Informe um valor de adiantamento a compensar!');return;}
    const valorAntesCompensar=Number(c.valor);
    
    _aplicarAdiantamentosCP(fornCod, adtAplicar, c, dataFmt);
    
    const novoValor=Math.max(0,valorAntesCompensar-adtAplicar);
    c.valor=novoValor;
    const obsExtra='Compensado adiantamento R$ '+fmt(adtAplicar)+' em '+dataFmt;
    c.obs=(c.obs?c.obs+' | ':'')+[obs,obsExtra].filter(Boolean).join(' | ');
    c.pagamentos.push({data:dataFmt, valor:0, adt:adtAplicar, banco:'', obs:obsExtra});
    c._upd=Date.now();
    
    if(novoValor<=0.01){
      c.status='Pago'; c.dataPgto=dataFmt;
      if(c.ticket && TICKETS_DB[c.ticket]){ _baixarSaldoTicket(c.ticket, valorAntesCompensar, dataFmt); saveDB(); renderTickets(); }
    } else if(c.ticket && TICKETS_DB[c.ticket]){
      
      
      
      
      
      
      _baixarSaldoTicket(c.ticket, adtAplicar, dataFmt, c.id);
      saveDB(); renderTickets();
    }
    
    
    
    registrarHistorico('Contas a Pagar', novoValor<=0.01?'Pago (compensado c/ adiantamento)':'Compensação parcial c/ adiantamento',
      (c.cred||c.desc||c.id)+' — adiantamento R$ '+fmt(adtAplicar)+(novoValor<=0.01?' (quitou o saldo)':' | saldo restante R$ '+fmt(novoValor)),
      c, {cpId:c.id});
    
    saveContasPagar(); renderContasPagar(); saveDB(); renderAdiantamentos();
    renderFluxo(); renderDashboard(); cm();
    if(novoValor<=0.01){
      showToast('Conta totalmente compensada com adiantamento!','success');
    } else {
      showToast('Adiantamento de R$ '+fmt(adtAplicar)+' compensado. Saldo em aberto: R$ '+fmt(novoValor),'success');
    }
    return;
  }

  
  if(valorLiquido>0 && !banco){alert('Selecione a conta bancária para pagar o valor restante!');return;}
  
  if(adtAplicar>0) _aplicarAdiantamentosCP(fornCod, adtAplicar, c, dataFmt);
  const obsPagamento=(adtAplicar>0?'Compensado adiantamento R$ '+fmt(adtAplicar):'');
  c.pagamentos.push({data:dataFmt, valor:valorLiquido, adt:adtAplicar, banco:banco||'', obs:[obs,obsPagamento].filter(Boolean).join(' | ')});
  const fechouAgora=restanteAposEssaBaixa<=0.01;
  if(fechouAgora){
    
    c.status='Pago';
    c.dataPgto=dataFmt;
    c.valor=valorPagarAgora;
    
    
    
    
    
    { const _adtComp=(Number(c.adtCompensado)||0)+(adtAplicar>0?adtAplicar:0); if(_adtComp>0) c.adtCompensado=_adtComp; else delete c.adtCompensado; }
    c.valorPago=(Number(c.valorPago)||0)+valorLiquido;
    if(banco) c.bancoNome=banco;
  } else {
    
    
    
    
    c.status='Pendente';
    c.valor=restanteAposEssaBaixa;
    c.valorPago=(Number(c.valorPago)||0)+valorLiquido;
    if(adtAplicar>0) c.adtCompensado=(Number(c.adtCompensado)||0)+adtAplicar;
    if(banco) c.bancoNome=banco;
  }
  if(obs||obsPagamento) c.obs=(c.obs?c.obs+' | ':'')+[obs,obsPagamento].filter(Boolean).join(' | ');
  c._upd=Date.now();
  
  
  
  
  
  registrarHistorico('Contas a Pagar', fechouAgora?'Pago':'Pagamento parcial',
    (c.cred||c.desc||c.id)+' — R$ '+fmt(valorLiquido)+(banco?' via '+banco:'')+(adtAplicar>0?' + R$ '+fmt(adtAplicar)+' adiantamento':'')+(fechouAgora?'':' | saldo restante R$ '+fmt(restanteAposEssaBaixa)),
    c, {cpId:c.id});
  saveContasPagar(); renderContasPagar();
  if(adtAplicar>0){ saveDB(); renderAdiantamentos(); }
  if(banco && valorLiquido>0){
    const _movPg=registrarMovBanco(banco, dataISO, 'Pagto: '+(c.desc||c.cred)+(adtAplicar>0?' (após comp. adt.)':''), 'Saida', valorLiquido);
    
    
    
    if(_movPg){
      c.movBancoIdCP=_movPg.id;
      const _ultPg=c.pagamentos[c.pagamentos.length-1];
      if(_ultPg) _ultPg.movBancoId=_movPg.id;
    }
  }
  if(c.ticket && TICKETS_DB[c.ticket]){
    
    
    
    
    
    _baixarSaldoTicket(c.ticket, valorPagarAgora, dataFmt, fechouAgora?undefined:c.id);
    saveDB(); renderTickets();
  }
  renderFluxo(); renderDashboard(); cm();
  showToast((fechouAgora?'Conta paga!':'Pagamento parcial registrado! Saldo restante: R$ '+fmt(restanteAposEssaBaixa))
    +(adtAplicar>0?' | Adt. R$ '+fmt(adtAplicar):'')
    +(valorLiquido>0?' | Banco R$ '+fmt(valorLiquido)+(banco?' ('+banco+')':''):(adtAplicar>0?' | 100% adiantamento':''))
    +(c.ticket?' | Ticket #'+c.ticket:''),'success');
}




function _baixarSaldoTicket(ticketId, valorPago, dataFmt, cpJaTratadoId){
  const tk=TICKETS_DB[ticketId]; if(!tk) return;
  const novoSaldo=Math.max(0, Number(tk.saldoPagar||0) - Number(valorPago||0));
  tk.saldoPagar=novoSaldo;
  tk.status = novoSaldo<=0.01 ? 'Pago' : 'Parcial';
  const dataFmtUsar = dataFmt || new Date().toLocaleDateString('pt-BR');

  
  
  
  
  
  
  
  const pendentesDoTicket = CONTAS_PAGAR.filter(cp=>cp.ticket===ticketId && cp.status==='Pendente' && cp.id!==cpJaTratadoId);

  if(novoSaldo>0.01){
    
    
    
    
    if(pendentesDoTicket.length){
      pendentesDoTicket[0].valor=novoSaldo;
      pendentesDoTicket[0]._upd=Date.now();
      for(let i=1;i<pendentesDoTicket.length;i++){
        const idx=CONTAS_PAGAR.indexOf(pendentesDoTicket[i]);
        if(idx>=0) _removerCPporIndice(idx);
      }
    } else if(!cpJaTratadoId){
      
      
      
      
      CONTAS_PAGAR.push({ id:_novoIdCP(),
        lancto:tk.data, desc:'Compra Sucata – Ticket '+ticketId+' – '+(tk.fornecedor||'')+' (saldo restante)',
        cred:tk.fornecedor||'', cat:'Compra de Sucata', bancoCod:'', bancoNome:'', tipoForn:'compra',
        venc:tk.data, valor:novoSaldo, status:'Pendente',
        dataPgto:'', obs:'Saldo restante após pagamento parcial', ticket:ticketId,
        fornCod:tk.fornecedorCod||''
      });
    }
  } else if(pendentesDoTicket.length){
    
    
    
    pendentesDoTicket.forEach(function(cp){
      cp.status='Pago'; cp.dataPgto=dataFmtUsar;
      cp.obs=(cp.obs?cp.obs+' | ':'')+'Baixado automaticamente — saldo do ticket já quitado por outro pagamento';
      cp._upd=Date.now();
    });
  }
  try{ saveContasPagar(); renderContasPagar(); }catch(e){}
}

function _aplicarAdiantamentosCP(fornCod, adtAplicar, c, dataFmt){
  if(!fornCod || !ADT_POR_FORN[fornCod] || adtAplicar<=0) return;
  let restante=adtAplicar;
  for(const a of ADT_POR_FORN[fornCod].filter(a=>a.status==='Pendente')){
    if(restante<=0) break;
    const vAdt=Number(a.valor);
    const usado=Math.min(vAdt,restante);
    if(usado>=vAdt){
      a.status='Quitado'; a.ticket=a.ticket||c.ticket||'';
      a.obs=(a.obs?a.obs+' | ':'')+'Compensado em CP '+dataFmt;
    } else {
      
      
      
      
      
      
      
      
      
      ADT_POR_FORN[fornCod].push({
        cod:'ADT'+String(Date.now()).slice(-6), data:dataFmt, valor:usado,
        status:'Quitado', ticket:c.ticket||'', forma:a.forma,
        bancoCod:a.bancoCod||'', bancoNome:a.bancoNome||'',
        obs:'Compensação parcial – CP '+dataFmt
      });
      a.valor=vAdt-usado;
    }
    restante-=usado;
  }
  
  
  try{ _adtSalvarNaNuvem(fornCod); }catch(e){}
}


function confirmarAcao(msg, onOk, okLabel, okStyle){
  const old=document.getElementById('modal-ov-confirm'); if(old) old.remove();
  const label = okLabel || '🗑️ Excluir';
  const btnClass = okStyle || 'btn-edit-danger';
  const ov=document.createElement('div');
  ov.className='modal-ov open'; ov.id='modal-ov-confirm';
  const box=document.createElement('div');
  box.className='modal'; box.style.maxWidth='420px';
  box.innerHTML='<h3 style="color:#e74c3c;margin-bottom:12px">⚠️ Confirmar</h3>'
    +'<p style="color:#333;margin-bottom:20px;font-size:.9rem;white-space:pre-line">'+msg+'</p>'
    +'<div class="modal-ft">'
    +'<button class="btn-cancel" id="_caCancelBtn">Cancelar</button>'
    +'<button class="'+btnClass+'" id="_caOkBtn">'+label+'</button></div>';
  ov.appendChild(box); document.body.appendChild(ov);
  document.getElementById('_caCancelBtn').onclick=function(){ ov.remove(); };
  document.getElementById('_caOkBtn').onclick=function(){ ov.remove(); onOk(); };
}

function excluirContaPagar(idx, id){
  
  
  
  
  
  
  if(id){ const fresh=_cpIdxPorId(id); if(fresh>=0) idx=fresh; }
  const conta = CONTAS_PAGAR[idx];
  if(!conta) return;
  const idAlvo = id || conta.id || '';
  const grupoId = conta.grupoId;
  
  const irmãs = grupoId ? CONTAS_PAGAR.map((c,i)=>({c,i})).filter(({c,i})=>c.grupoId===grupoId && i!==idx) : [];
  const irmãsPendentes = irmãs.filter(({c})=>c.status==='Pendente');

  if(grupoId && irmãs.length > 0){
    
    const modal = document.createElement('div');
    modal.style.cssText='position:fixed;inset:0;background:rgba(0,0,0,.55);z-index:99999;display:flex;align-items:center;justify-content:center';
    modal.innerHTML=`<div style="background:#fff;border-radius:14px;padding:28px 28px 20px;max-width:420px;width:93%;box-shadow:0 8px 40px #0004">
      <div style="font-size:1rem;font-weight:800;color:#1a3a2a;margin-bottom:8px">🗑️ Excluir Parcela</div>
      <div style="font-size:.88rem;color:#555;margin-bottom:18px">Esta conta faz parte de um lançamento com <b>${irmãs.length+1} parcelas</b>. O que deseja fazer?</div>
      <div style="display:flex;flex-direction:column;gap:9px">
        <button onclick="cpExcluirApenas(${idx},'${esc(idAlvo)}')" style="background:#f5f5f5;color:#333;border:2px solid #ddd;border-radius:9px;padding:11px 14px;text-align:left;cursor:pointer;font-size:.87rem;font-weight:600">
          📌 Excluir só <b>esta parcela</b>
        </button>
        ${irmãsPendentes.length>0?`<button onclick="cpExcluirPendentes('${grupoId}',${idx})" style="background:#fff3e0;color:#e65100;border:2px solid #ffcc80;border-radius:9px;padding:11px 14px;text-align:left;cursor:pointer;font-size:.87rem;font-weight:600">
          ⏳ Excluir esta + <b>${irmãsPendentes.length} pendente(s)</b> do grupo
        </button>`:''}
        <button onclick="cpExcluirTodas('${grupoId}')" style="background:#fdecea;color:#c0392b;border:2px solid #f5c6cb;border-radius:9px;padding:11px 14px;text-align:left;cursor:pointer;font-size:.87rem;font-weight:600">
          🗑️ Excluir <b>todas as ${irmãs.length+1} parcelas</b> do grupo
        </button>
        <button onclick="this.closest('[style*=fixed]').remove()" style="background:#fff;color:#888;border:1px solid #ddd;border-radius:9px;padding:9px;cursor:pointer;font-size:.85rem;margin-top:4px">Cancelar</button>
      </div>
    </div>`;
    document.body.appendChild(modal);
  } else {
    confirmarAcao('Excluir esta conta a pagar?', function(){
      let idxFinal = idx;
      if(idAlvo){ const fresh=_cpIdxPorId(idAlvo); if(fresh>=0) idxFinal=fresh; }
      if(idxFinal<0 || !CONTAS_PAGAR[idxFinal]){ showToast('Essa conta já não existe mais na lista (foi atualizada por outra tela).','error'); try{renderContasPagar();}catch(e){} return; }
      _removerCPporIndice(idxFinal); saveContasPagar();
      try{renderContasPagar();}catch(e){}
      try{renderFluxo();}catch(e){}
      try{renderDashboard();}catch(e){}
      showToast('Conta excluída.','success');
    });
  }
}
function cpExcluirApenas(idx, id){
  if(id){ const fresh=_cpIdxPorId(id); if(fresh>=0) idx=fresh; }
  document.querySelectorAll('[style*="position:fixed"][style*="99999"]').forEach(el=>el.remove());
  _removerCPporIndice(idx); saveContasPagar();
  try{renderContasPagar();}catch(e){}
  try{renderFluxo();}catch(e){}
  try{renderDashboard();}catch(e){}
  showToast('Parcela excluída.','success');
}
function cpExcluirPendentes(grupoId,idxAtual){
  document.querySelectorAll('[style*="position:fixed"][style*="99999"]').forEach(el=>el.remove());
  
  const remover=new Set();
  remover.add(idxAtual);
  CONTAS_PAGAR.forEach((c,i)=>{ if(c.grupoId===grupoId && c.status==='Pendente') remover.add(i); });
  remover.forEach(function(i){ const c=CONTAS_PAGAR[i]; if(c&&c.id) CONTAS_PAGAR_DELETED.add(c.id); });
  try{ localStorage.setItem('mm_cp_deletados', JSON.stringify([...CONTAS_PAGAR_DELETED])); }catch(e){}
  CONTAS_PAGAR.splice(0,CONTAS_PAGAR.length,...CONTAS_PAGAR.filter((_,i)=>!remover.has(i)));
  saveContasPagar();
  try{renderContasPagar();}catch(e){}
  try{renderFluxo();}catch(e){}
  try{renderDashboard();}catch(e){}
  showToast(remover.size+' parcela(s) excluída(s).','success');
}
function cpExcluirTodas(grupoId){
  document.querySelectorAll('[style*="position:fixed"][style*="99999"]').forEach(el=>el.remove());
  const antes=CONTAS_PAGAR.length;
  CONTAS_PAGAR.filter(c=>c.grupoId===grupoId).forEach(function(c){ if(c&&c.id) CONTAS_PAGAR_DELETED.add(c.id); });
  try{ localStorage.setItem('mm_cp_deletados', JSON.stringify([...CONTAS_PAGAR_DELETED])); }catch(e){}
  CONTAS_PAGAR.splice(0,CONTAS_PAGAR.length,...CONTAS_PAGAR.filter(c=>c.grupoId!==grupoId));
  saveContasPagar();
  try{renderContasPagar();}catch(e){}
  try{renderFluxo();}catch(e){}
  try{renderDashboard();}catch(e){}
  showToast((antes-CONTAS_PAGAR.length)+' parcela(s) excluída(s).','success');
}

function renderContasReceber(){
  const tbody=document.getElementById('tb-contas-receber');
  if(!tbody) return;
  
  
  
  try{ if(_syncContasReceber.limparDuplicatasExatas()){ try{ saveContasReceber(); }catch(e){} } }catch(e){}
  const fmt=v=>_numFinito(v,0).toLocaleString('pt-BR',{minimumFractionDigits:2});
  const hoje=new Date().toISOString().slice(0,10);
  
  const _toISOcr=d=>{if(!d)return'';const ds=String(d).trim();if(ds.indexOf('/')>=0){const p=ds.split('/');return(p[2]||'0000')+'-'+(p[1]||'01')+'-'+(p[0]||'01');}return ds.slice(0,10);};
  const _emAberto=CONTAS_RECEBER.filter(c=>c.status!=='Recebido');
  const _totAberto=_emAberto.reduce((s,c)=>s+Number(c.valor||0),0);
  const _totReceb=CONTAS_RECEBER.filter(c=>c.status==='Recebido').reduce((s,c)=>s+Number(c.valor||0),0);
  const _atrasados=_emAberto.filter(c=>{const vi=_toISOcr(c.venc);return vi&&vi<hoje;});
  const _setCR=(id,t)=>{const e=document.getElementById(id);if(e)e.textContent=t;};
  _setCR('kpi-cr-aberto-val','R$ '+fmt(_totAberto));
  _setCR('kpi-cr-aberto-sub',_emAberto.length+' lançamento'+(_emAberto.length!==1?'s':'')+' em aberto');
  _setCR('kpi-cr-pend-val',String(_emAberto.length));
  _setCR('kpi-cr-atras-val',String(_atrasados.length));
  _setCR('kpi-cr-receb-val','R$ '+fmt(_totReceb));
  if(CONTAS_RECEBER.length===0){
    tbody.innerHTML='<tr><td colspan="9" style="color:var(--gray);text-align:center;padding:20px">Nenhum lançamento ainda</td></tr>';
    return;
  }
  const sorted=[...CONTAS_RECEBER].sort((a,b)=>a.venc.localeCompare(b.venc));
  tbody.innerHTML=sorted.map((c,i)=>{
    const idx=CONTAS_RECEBER.indexOf(c);
    const atrasado=c.status==='Pendente'&&c.venc<hoje;
    const stCls=c.status==='Recebido'?'b-pago':atrasado?'b-pend':'b-zerado';
    return '<tr style="'+(atrasado?'background:#fff5f5':'')+'">'
      +'<td>'+fmtDate(c.data)+'</td><td>'+esc(c.nf||'—')+'</td>'
      +'<td><b>'+esc(c.cli)+'</b></td>'
      +'<td style="font-weight:800;text-align:right">R$ '+fmt(c.valor)+'</td>'
      +'<td style="font-size:.78rem">'+esc(c.forma||'—')+'</td>'
      +'<td style="font-size:.78rem">'+esc(c.banco||'—')+'</td>'
      +'<td>'+fmtDate(c.venc)+'</td>'
      +'<td><span class="b '+stCls+'">'+(atrasado?'Atrasado':c.status)+'</span></td>'
      +'<td>'+esc(c.dataReceb||'—')+'</td>'
      +'<td>'+esc(c.obs||'—')+'</td>'
      +'<td style="white-space:nowrap">'
        +(c.vendaId?'<button class="btn-add" style="padding:3px 8px;font-size:.72rem;margin-right:4px" onclick="verVendaDoCR(this.dataset.id)" data-id="'+c.vendaId+'">🔗 Venda</button>':'')
        +'<button class="btn-edit" onclick="editContaReceber('+idx+')" style="margin-right:4px">✏️</button>'
        +(c.status!=='Recebido'?'<button class="btn-edit" style="background:#27ae60;color:#fff;font-size:.75rem;margin-right:4px" onclick="receberContaRapido('+idx+')">✅ Receber</button>':'')
        +'<button class="btn-edit-danger" onclick="excluirContaReceber('+idx+')" title="Excluir lançamento">🗑️</button>'
      +'</td>'
    +'</tr>';
  }).join('');
}

function salvarContaReceber(){
  const cli=document.getElementById('cr-cli')?.value.trim();
  const valor=parseFloat(document.getElementById('cr-valor')?.value)||0;
  const venc=document.getElementById('cr-venc')?.value;
  if(!cli||valor<=0||!venc){alert('Preencha cliente, valor e vencimento!');return;}
  const hoje=new Date().toISOString().slice(0,10).split('-').reverse().join('/');
  CONTAS_RECEBER.push({
    data: hoje, cli, nf: document.getElementById('cr-nf')?.value.trim()||'',
    valor, venc: venc.split('-').reverse().join('/'),
    status: document.getElementById('cr-status')?.value||'Pendente',
    dataReceb:'', obs: document.getElementById('cr-obs')?.value.trim()||''
  });
  saveContasReceber(); renderContasReceber();
  try{renderFluxo();}catch(e){}
  try{renderDashboard();}catch(e){}
  cm();
  showToast('Recebimento registrado!','success');
}

function editContaReceber(idx){
  const c=CONTAS_RECEBER[idx]; if(!c) return;
  const stOpts=['Pendente','Recebido','Atrasado'].map(s=>'<option'+(s===c.status?' selected':'')+'>'+s+'</option>').join('');
  const body=document.getElementById('modal-body');
  body.className='modal';
  body.innerHTML=
    '<h3>✏️ Editar Recebimento</h3>'+
    '<input type="hidden" id="ecr-idx" value="'+idx+'">'+
    '<div class="fg"><label>Cliente</label><input id="ecr-cli" value="'+esc(c.cli)+'"></div>'+
    '<div class="fg"><label>NF/Pedido</label><input id="ecr-nf" value="'+esc(c.nf||'')+'"></div>'+
    '<div class="fg"><label>Valor R$</label><input id="ecr-valor" type="number" min="0" step="0.01" value="'+c.valor+'"></div>'+
    '<div class="fg"><label>Vencimento</label><input id="ecr-venc" type="date" value="'+(c.venc?c.venc.split('/').reverse().join('-'):'')+'"></div>'+
    '<div class="fg"><label>Status</label><select id="ecr-status">'+stOpts+'</select></div>'+
    '<div class="fg"><label>Banco Recebimento</label><select id="ecr-banco"><option value="">— Selecione —</option>'+(BANCOS_DB||[]).map(b=>{const n=b.banco+(b.tipo==='Conta Terceiro'?' ('+b.titular+')':'');return '<option value="'+esc(n)+'"'+(n===c.banco?' selected':'')+'>'+esc(n)+'</option>';}).join('')+'</select></div>'+
    '<div class="fg"><label>Data Recebimento</label><input id="ecr-receb" type="date" value="'+(c.dataReceb?c.dataReceb.split('/').reverse().join('-'):'')+'"></div>'+
    '<div class="fg"><label>Obs.</label><input id="ecr-obs" value="'+esc(c.obs||'')+'"></div>'+
    '<div class="modal-ft">'+
    '<button class="btn-edit-danger" onclick="excluirContaReceber('+idx+')">🗑️ Excluir</button>'+
    '<button class="btn-cancel" onclick="cm()">Cancelar</button>'+
    '<button class="btn-save" onclick="salvarEditContaReceber()">💾 Salvar</button></div>';
  document.getElementById('modal-ov').classList.add('open');
}

function salvarEditContaReceber(){
  const idx=parseInt(document.getElementById('ecr-idx').value);
  const c=CONTAS_RECEBER[idx]; if(!c) return;
  const receb=document.getElementById('ecr-receb').value;
  c.cli=document.getElementById('ecr-cli').value.trim();
  c.nf=document.getElementById('ecr-nf').value.trim();
  c.valor=parseFloat(document.getElementById('ecr-valor').value)||0;
  c.venc=document.getElementById('ecr-venc').value.split('-').reverse().join('/');
  c.status=document.getElementById('ecr-status').value;
  c.dataReceb=receb?receb.split('-').reverse().join('/'):'';
  
  
  
  c.obs=document.getElementById('ecr-obs').value.trim();
  saveContasReceber(); renderContasReceber(); renderFluxo(); try{renderDashboard();}catch(e){} cm();
}

