function _bancoDataCriacao(b){
  if(b && b.criadoEm){
    const iso=String(b.criadoEm).slice(0,10);
    return /^\d{4}-\d{2}-\d{2}$/.test(iso) ? iso.split('-').reverse().join('/') : null;
  }
  if(!b || !b.cod || typeof HISTORICO_DB==='undefined') return null;
  let maisAntigo=null;
  HISTORICO_DB.forEach(function(h){
    if(!h||h.modulo!=='Banco'||h.acao!=='Criado') return;
    if(!h.extra||h.extra.bancoCod!==b.cod) return;
    if(!maisAntigo||Number(h.ts||0)<Number(maisAntigo.ts||0)) maisAntigo=h;
  });
  return maisAntigo ? new Date(maisAntigo.ts).toLocaleDateString('pt-BR') : null;
}

function renderBancos(){
  const tbody=document.getElementById('tb-bancos');
  if(!tbody) return;
  
  
  
  if(!window.__ERP_BANKS_CLOUD_READY__){
    tbody.innerHTML='<tr><td colspan="11" style="text-align:center;padding:20px">Carregando contas do Firebase...</td></tr>';
    const kpi=document.querySelector('#tab-contas_banco .kpi-val');
    if(kpi) kpi.textContent='—';
    return;
  }
  const fmt=v=>Number(v||0).toLocaleString('pt-BR',{minimumFractionDigits:2});
  const empCor={}; _cfgFinanceCompanies().forEach(function(n){ empCor[n]=_cfgFinanceCompanyColor(n); });
  if(BANCOS_DB.length===0){
    tbody.innerHTML='<tr><td colspan="11" style="color:var(--gray);text-align:center;padding:20px">Nenhuma conta cadastrada</td></tr>';
    const kpi=document.querySelector('#tab-contas_banco .kpi-val'); if(kpi)kpi.textContent='0';
    const saldo=document.querySelectorAll('#tab-contas_banco .kpi-val')[1]; if(saldo)saldo.textContent='R$ 0,00';
    return;
  }
  tbody.innerHTML=BANCOS_DB.map((b,i)=>{
    const _empresaVisual=b.empresa||_empresaPorTexto([b.banco,b.titular,b.pix,b.cpfcnpj].filter(Boolean).join(' '));
    const isTerceiro=b.tipo==='Conta Terceiro';
    const movs=LANC_BANCO_DB.filter(l=>l.bancoCod===b.cod);
    const saldoAtual=Number(b.saldo||0)+movs.reduce((s,l)=>s+(l.tipo==='Entrada'?1:-1)*Number(l.valor||0),0);
    const saldoColor=saldoAtual<0?'color:#c0392b':saldoAtual===0?'color:#999':'color:#1a5e2a';
    return '<tr>'
      +'<td style="font-size:.78rem;color:var(--gray)">'+esc(b.cod)+'</td>'
      +'<td><b>'+esc(b.banco)+'</b>'+(b.agencia?' <small>Ag '+esc(b.agencia)+'</small>':'')+' – <small>'+esc(b.conta||'—')+'</small></td>'
      +'<td><span class="b '+(isTerceiro?'b-pend':'b-zerado')+'">'+esc(b.tipo)+'</span></td>'
      +'<td>'+esc(b.titular)+'<br><span style="font-size:.68rem;font-weight:700;color:'+(empCor[_empresaVisual]||'#888')+'">'+esc(_empresaVisual||_empresaPrincipalChave())+'</span></td>'
      +'<td style="font-size:.78rem">'+esc(b.cpfcnpj||'—')+'</td>'
      +'<td style="text-align:right;color:var(--gray);font-size:.82rem">R$ '+fmt(b.saldo)+'</td>'
      +'<td style="font-size:.78rem;color:var(--gray);white-space:nowrap">'+(_bancoDataCriacao(b)||'<span style="color:#bbb">—</span>')+'</td>'
      +'<td style="text-align:right;font-weight:700;'+saldoColor+'">R$ '+fmt(saldoAtual)+'</td>'
      +'<td style="font-size:.78rem">'+esc(b.pix||'—')+'</td>'
      +'<td style="font-size:.78rem">'+esc(b.obs||'—')+'</td>'
      +'<td style="white-space:nowrap">'
        +'<button class="btn-edit" onclick="editBanco('+i+')" title="Editar">✏️</button> '
        +'<button class="btn-edit-danger" onclick="excluirBanco('+i+')" title="Excluir">🗑️</button> '
        +'<button class="btn-add" style="padding:3px 8px;font-size:.72rem;background:#27ae60" onclick="verExtratoBanco(&#39;'+b.cod+'&#39;)" title="Ver extrato">📊 Extrato</button> '
        +'<button class="btn-add" style="padding:3px 8px;font-size:.72rem" onclick="compartilharBanco('+i+')" title="Compartilhar dados para pagamento">📤 Compartilhar</button>'
        +'</td>'
    +'</tr>';
  }).join('');

  
  const kpiTotal=document.querySelector('#tab-contas_banco .kpi-val');
  if(kpiTotal) kpiTotal.textContent=BANCOS_DB.length;
  const kpiSaldo=document.querySelectorAll('#tab-contas_banco .kpi-val')[1];
  
  const saldoTotalAtual=BANCOS_DB.reduce((s,b)=>{
    const movs=LANC_BANCO_DB.filter(l=>l.bancoCod===b.cod);
    const sa=Number(b.saldo||0)+movs.reduce((ms,l)=>ms+(l.tipo==='Entrada'?1:-1)*Number(l.valor||0),0);
    return s+sa;
  },0);
  if(kpiSaldo) kpiSaldo.textContent='R$ '+fmt(saldoTotalAtual);
  const kpiSub=document.querySelector('#tab-contas_banco .kpi-sub');
  if(kpiSub) kpiSub.textContent=BANCOS_DB.length>0?'Saldo consolidado atualizado':'Aguardando saldos';

  
  window._bancosDropdown=BANCOS_DB.map(b=>b.banco+(b.titular&&b.titular!==_empresaPrincipalRazao()?' ('+b.titular+')':''));
}











function _proximoCodBanco(){
  let max=0;
  BANCOS_DB.forEach(function(b){
    const m=/^BC-(\d+)$/.exec((b&&b.cod)||'');
    if(m) max=Math.max(max, parseInt(m[1],10));
  });
  let n=max+1, cod='BC-'+String(n).padStart(3,'0');
  while(BANCOS_DB.some(function(b){ return b&&b.cod===cod; })){ n++; cod='BC-'+String(n).padStart(3,'0'); }
  return cod;
}



function _bancosPrepararTombstonesCloud(){
  if(window.__ERP_BANKS_TOMBSTONES_INIT__) return;
  try{
    const key='mm_bancos_deletados';
    const antigo=localStorage.getItem(key);
    if(antigo && !localStorage.getItem('mm_bancos_deletados_backup_pre_cloud_v28'))
      localStorage.setItem('mm_bancos_deletados_backup_pre_cloud_v28',antigo);
    
    
    
    
    _syncBancos.deletedSet.clear();
    localStorage.setItem(key,'[]');
    window.__ERP_BANKS_TOMBSTONES_INIT__=true;
  }catch(e){console.warn('Tombstones bancários:',e);}
}




function _normalizarBancosRemotos(remoto){
  if(!remoto || typeof remoto!=='object' || Array.isArray(remoto)) return remoto;
  const obj={};
  Object.entries(remoto).forEach(([key,b])=>{
    obj[key]=(b && typeof b==='object' && !Array.isArray(b))
      ? Object.assign({},b,{id:b.id||key}) : b;
  });
  return obj;
}

async function recarregarBancosDoBanco(){
  try{
    if(!window.__businessRepository) return false;
    const remoto=await window.__businessRepository.read('bancos');
    
    
    _bancosPrepararTombstonesCloud();
    _syncBancos.carregarDeRemoto(_normalizarBancosRemotos(remoto||{}), true);
    window.__ERP_BANKS_CLOUD_READY__=true;
    
    
    try{ bancosCorrigeEmpresa(); }catch(e){ console.warn('bancosCorrigeEmpresa',e); }
    
    
    try{
      const backup=JSON.parse(localStorage.getItem('mm_bancos_backup_pre_cloud_v28')||'[]');
      if(Array.isArray(backup) && backup.length){
        const remotos=new Set(BANCOS_DB.map(b=>String(b.id||b.cod||'')));
        const extras=backup.filter(b=>b && !remotos.has(String(b.id||b.cod||'')));
        if(extras.length && !window.__ERP_BANKS_CACHE_WARNING_SHOWN__){
          window.__ERP_BANKS_CACHE_WARNING_SHOWN__=true;
          console.warn('[Bancos] Cache antigo contém '+extras.length+' registros não identificados no RTDB. Backup preservado localmente; revisão manual necessária.');
          try{showToast('⚠️ Existem contas no cache antigo que não foram confirmadas no Firebase. Backup local preservado para conferência.','info',8000);}catch(e){}
        }
      }
    }catch(e){}
    renderBancos();
    try{ rebuildBancosDropdowns(); }catch(e){}
    return true;
  }catch(e){
    console.warn('recarregarBancosDoBanco:',e);
    try{showToast('Não foi possível conferir as contas bancárias no Firebase.','error',5000);}catch(_){}
    return false;
  }
}




async function salvarBanco(){
  const banco=document.getElementById('bc-banco')?.value.trim();
  if(!banco){alert('Informe o nome do banco!');return;}
  if(!window.__businessRepository || !window.__ERP_BANKS_CLOUD_READY__){alert('Aguarde a confirmação do cadastro de contas pelo Firebase antes de salvar.');return;}
  
  
  try{
    const cloud=await window.__businessRepository.read('bancos');
    const registros=cloud ? (Array.isArray(cloud)
      ? cloud.map((x,i)=>[String(i),x]).filter(([,x])=>Boolean(x))
      : Object.entries(cloud).filter(([,x])=>Boolean(x))) : [];
    const idsLocal=new Set(BANCOS_DB.map(x=>String(x.id||x.cod||'')));
    const idsCloud=new Set(registros.map(([key,x])=>String(x.id||key)));
    if(idsLocal.size!==idsCloud.size || [...idsLocal].some(id=>!idsCloud.has(id))){
      await recarregarBancosDoBanco();
      alert('As contas foram atualizadas por outra sessão ou havia dados antigos no navegador. Confira a lista antes de salvar a nova conta.');
      return;
    }
  }catch(e){alert('Não foi possível validar o cadastro no Firebase: '+e.message);return;}
  const tipo=document.getElementById('bc-tipo')?.value||'Conta Corrente';
  const cod=_proximoCodBanco();
  const novo={
    id:'BC'+Date.now().toString(36)+Math.random().toString(36).slice(2,8),cod,banco,tipo,
    empresa:document.getElementById('bc-empresa')?.value||_empresaPrincipalChave(),
    titular:document.getElementById('bc-titular')?.value.trim()||_empresaPrincipalRazao(),
    cpfcnpj:tipo==='Conta Terceiro'?(document.getElementById('bc-cpfcnpj')?.value.trim()||''):'',
    agencia:document.getElementById('bc-agencia')?.value.trim()||'',
    conta:document.getElementById('bc-conta')?.value.trim()||'',
    pix:document.getElementById('bc-pix')?.value.trim()||'',
    endereco:document.getElementById('bc-endereco')?.value.trim()||'',
    saldo:_parseValorBR(document.getElementById('bc-saldo')?.value),
    obs:document.getElementById('bc-obs')?.value.trim()||'',
    criadoEm:(function(){const d=document.getElementById('bc-data')?.value;return d?d+'T12:00:00.000Z':new Date().toISOString();})()
  };
  const btn=document.querySelector('#modal-body .btn-save');if(btn)btn.disabled=true;
  try{
    await window.__businessRepository.upsert('bancos',novo.id,novo);
    if(!BANCOS_DB.some(b=>b.id===novo.id))BANCOS_DB.push(novo);
    localStorage.setItem('mm_bancos',JSON.stringify(BANCOS_DB)); 
    renderBancos();rebuildBancosDropdowns();cm();
    registrarHistorico('Banco','Criado',banco+' — saldo inicial R$ '+Number(novo.saldo||0).toLocaleString('pt-BR',{minimumFractionDigits:2}),null,{bancoCod:cod});
    showToast('✅ Conta bancária confirmada no Firebase!','success');
  }catch(error){
    alert('Não foi possível salvar o banco no Firebase. Nada foi considerado concluído. '+error.message);
  }finally{if(btn)btn.disabled=false;}
}

