async function balAtualizarTicketsDoBanco(){
  try{
    if(!window.__businessRepository) return false;
    const remoto=await window.__businessRepository.read('tickets');
    if(!remoto || typeof remoto!=='object') return false;
    Object.keys(remoto).forEach(function(tid){
      if(typeof TICKETS_DELETED!=='undefined' && TICKETS_DELETED.has && TICKETS_DELETED.has(tid)) return;
      TICKETS_DB[tid]=Object.assign({},TICKETS_DB[tid]||{},remoto[tid]||{});
    });
    renderBalanceiro();
    try{ balRenderHistorico(); }catch(e){}
    return true;
  }catch(e){ console.warn('balAtualizarTicketsDoBanco:',e); return false; }
}

function renderBalanceiro(){
  
  const selForn = document.getElementById('bal-novo-forn');
  if(selForn){
    const fornecedoresBal=getFornAtivos().slice()
      .filter(f=>f&&String(f.nome||'').trim())
      .sort((a,b)=>(a.nome||'').localeCompare(b.nome||'','pt-BR'));
    selForn.innerHTML = '<option value="">— Selecione o Fornecedor —</option>'
      + fornecedoresBal
          .map(f=>'<option value="'+esc(f.nome||'')+'">'+esc(f.nome||'')+'</option>')
          .join('');
  }
  
  const dl = document.getElementById('metais-list-bal');
  if(dl) dl.innerHTML = METAIS.map(m=>`<option value="${m}">`).join('');

  
  const list = document.getElementById('bal-ticket-list');
  if(!list) return;
  const keys = Object.keys(TICKETS_DB).filter(k=>TICKETS_DB[k]._balSessao);
  if(!keys.length){ list.innerHTML='<div class="bal-none" style="padding:16px;text-align:center;color:#aaa">Nenhuma pesagem pendente.<br><span style="font-size:.8rem">Use "Iniciar Nova Sessão" abaixo ou registre entrada na Balança Rodoviária.</span></div>'; return; }

  
  const sorted = keys.slice().sort((a,b)=>{
    const da = TICKETS_DB[a]?.data||''; const db2 = TICKETS_DB[b]?.data||'';
    return db2.localeCompare(da);
  });

  list.innerHTML = sorted.map(tid=>{
    const t = TICKETS_DB[tid];
    const forn = t.fornecedorNome||t.forn||'—';
    const data = t.data ? fmtDate(t.data) : '—';
    const numBags = (_balBags[tid]||t.bags||[]).length;
    const isAtivo = _balTicketAtivo === tid;
    const isRod = !!t._rodEntrada;
    const bagsFinalizado = !!t._balBagsFinalizado;
    const temTara = (parseFloat(t.pesoTara||0)>0);
    
    const prontoPraLiberar = isRod && temTara && bagsFinalizado;
    
    const taraRecebidaSemBags = isRod && temTara && !bagsFinalizado;

    
    let stateBar = '';
    let cardStyle = '';
    let extraBtn = '';
    if(prontoPraLiberar){
      cardStyle = 'border:2px solid #2e7d32;background:#e8f5e9';
      stateBar = `<div style="background:#2e7d32;color:#fff;border-radius:6px;padding:3px 8px;font-size:.72rem;font-weight:800;margin-bottom:5px">✅ Peso vazio recebido — pronto para liberar</div>`;
      extraBtn = `<button onclick="event.stopPropagation();balLiberarParaSecretaria('${tid}')" style="margin-top:6px;width:100%;padding:7px;background:#2e7d32;color:#fff;border:none;border-radius:7px;font-weight:800;font-size:.82rem;cursor:pointer">📤 Liberar para Secretaria</button>`;
    } else if(taraRecebidaSemBags){
      cardStyle = 'border:2px solid #6a1b9a;background:#f3e5f5';
      stateBar = `<div style="background:#6a1b9a;color:#fff;border-radius:6px;padding:3px 8px;font-size:.72rem;font-weight:800;margin-bottom:5px">⚖️ Peso vazio recebido — finalize as bags para liberar</div>`;
    } else if(isRod && bagsFinalizado){
      cardStyle = 'border:2px solid #f57c00;background:#fff8e1';
      stateBar = `<div style="background:#f57c00;color:#fff;border-radius:6px;padding:3px 8px;font-size:.72rem;font-weight:800;margin-bottom:5px">⏳ Bags salvas — aguardando peso vazio na Rodoviária</div>`;
    } else if(isRod){
      cardStyle = 'border-left:4px solid #e65100';
      stateBar = '';
    }

    const rodBadge = isRod ? '<span style="background:#e65100;color:#fff;border-radius:8px;padding:1px 6px;font-size:.68rem;font-weight:700">🚛 Rod.</span> ' : '';
    const bagsBadge = numBags>0 ? `<span style="background:#2e7d32;color:#fff;border-radius:10px;padding:1px 7px;font-size:.7rem">${numBags} bags</span>` : '';
    const excluirBtn = `<button onclick="event.stopPropagation();balRemoverDaFila('${tid}')" title="Remover da fila" style="position:absolute;top:6px;right:6px;background:none;border:1px solid #e57373;border-radius:5px;color:#c62828;cursor:pointer;font-size:.72rem;padding:2px 6px;line-height:1">🗑️</button>`;
    return `<div class="bal-ticket-item${isAtivo?' active':''}" onclick="balSelecionarTicket('${tid}')" style="${cardStyle};position:relative">
      ${excluirBtn}
      ${stateBar}
      <div class="bt-num">${rodBadge}#${tid} ${bagsBadge}</div>
      <div class="bt-forn">${forn.substring(0,35)}</div>
      <div class="bt-info">${data}${t.pesoEntrada>0?' · Bruto: '+t.pesoEntrada.toFixed(0)+' kg':''}${temTara?' · Tara: '+parseFloat(t.pesoTara).toFixed(0)+' kg · Líq: '+parseFloat(t.pesoLiquido||0).toFixed(0)+' kg':''}</div>
      ${extraBtn}
    </div>`;
  }).join('');
}

