function balSelecionarTicket(tid){
  _balTicketAtivo = tid;
  if(!_balBags[tid]) _balBags[tid] = [];
  _balBagCount = _balBags[tid].length;

  const t = TICKETS_DB[tid]||{};
  const forn = t.fornecedorNome||t.forn||'—';
  const titulo = document.getElementById('bal-compra-titulo');
  if(titulo){
    const isSessao = t._balSessao;
    titulo.innerHTML = `<span style="font-weight:900">${isSessao?'Sessão':'Ticket #'+tid}</span> — ${forn.substring(0,30)}`
      + (isSessao ? `<span style="display:inline-flex;align-items:center;gap:5px;margin-left:10px;font-size:.8rem;color:#1565c0">
          Rod: <input id="bal-rod-edit" type="number" value="${t.pesoRodoviaria||0}" min="0" step="0.1" 
            oninput="TICKETS_DB['${tid}'].pesoRodoviaria=parseFloat(this.value)||0;balAtualizarProgress()"
            style="width:80px;padding:3px 6px;border:2px solid #1565c0;border-radius:5px;font-weight:800"> kg</span>` : '');
  }

  
  balAtualizarProgress();

  
  balRenderBags();

  
  _balBagCount++;
  const bl = document.getElementById('bal-bag-label');
  if(bl) bl.textContent = `BAG #${_balBagCount}`;

  
  ['bal-material','bal-peso-br','bal-desconto','bal-peso-lq'].forEach(id=>{
    const el=document.getElementById(id); if(el) el.value='';
  });
  const pb = document.getElementById('bal-peso-big');
  if(pb){ pb.textContent='0.0'; pb.classList.remove('live'); }

  
  renderBalanceiro();
}

function balAtualizarProgress(){
  if(!_balTicketAtivo) return;
  const t = TICKETS_DB[_balTicketAtivo]||{};
  const rodVal = parseFloat(t.pesoRodoviaria)||0;
  const bags = _balBags[_balTicketAtivo]||[];
  const pesado = bags.reduce((s,b)=>s+(b.lq||b.br||0),0);
  const restante = rodVal - pesado;
  const pct = rodVal>0 ? Math.min(100, pesado/rodVal*100) : 0;
  const zerou = rodVal>0 && Math.abs(restante) <= rodVal*0.02;
  const excedeu = restante < -(rodVal*0.02);

  const el = id=>document.getElementById(id);
  if(el('bal-rod-val')) el('bal-rod-val').textContent = rodVal.toFixed(1);
  if(el('bal-pes-val')) el('bal-pes-val').textContent = pesado.toFixed(1);
  if(el('bal-res-val')) el('bal-res-val').textContent = Math.abs(restante).toFixed(1);

  const chip = el('bal-res-chip');
  if(chip){
    chip.className = 'bal-pnum res' + (zerou?' zerou':excedeu?' excedeu':'');
  }
  const bar = el('bal-pbar');
  if(bar){
    bar.style.width = pct.toFixed(1)+'%';
    bar.style.background = zerou?'#2e7d32':excedeu?'#c62828':'#1565c0';
  }
  if(el('bal-pbar-pct')) el('bal-pbar-pct').textContent = pct.toFixed(1)+'%';

  if(zerou) showToast('✅ Conferência completa! Todos os pesos fecharam.','success',5000);
}

