function _rodAtualizarPeso(kg){
  _rodPesoAtual=kg;
  
  const elE=document.getElementById('rod-peso-big');
  if(elE) elE.textContent=kg.toFixed(1);
  
  const elT=document.getElementById('rod-peso-big-saida');
  if(elT) elT.textContent=kg.toFixed(1)+' kg';
  
  const elM=document.getElementById('rod-mat-peso-atual');
  if(elM) elM.textContent=kg.toFixed(1);
  
  if(typeof _rodTicketVendaAtivo!=='undefined' && _rodTicketVendaAtivo && kg>0){
    const _matInput=document.getElementById('rod-mat-peso-input');
    if(_matInput && !_matInput._manualOverride){ _matInput.value=kg.toFixed(1); }
    rodMatPreview();
  }
  
  if(typeof _rodTicketCompraAtivo!=='undefined' && _rodTicketCompraAtivo && kg>0){
    const _matInputC=document.getElementById('rod-matc-peso-input');
    if(_matInputC && !_matInputC._manualOverride){ _matInputC.value=kg.toFixed(1); }
    const elAtualC=document.getElementById('rod-matc-peso-atual');
    if(elAtualC) elAtualC.textContent=kg.toFixed(1);
    rodMatPreviewCompra();
  }
  _rodRecalcularLiquido();
}


function rodMatPreview(){
  if(!_rodTicketVendaAtivo) return;
  const t=TICKETS_DB[_rodTicketVendaAtivo];
  if(!t) return;
  const inputEl=document.getElementById('rod-mat-peso-input');
  const v=parseFloat(inputEl?.value||0);
  const ant=_rodUltimoPeso(t);
  const liq=v>0 ? v-ant : 0;
  const elLiq=document.getElementById('rod-mat-liquido-prev');
  if(elLiq){
    elLiq.textContent=(liq>0?liq:0).toFixed(1)+' kg';
    elLiq.style.color=liq>0?'#29b6f6':'#f44336';
  }
  
  const hintEl=document.getElementById('rod-mat-formula-hint');
  if(hintEl && v>0){
    if(liq>0){
      hintEl.textContent=v.toFixed(0)+' − '+ant.toFixed(0)+' = '+liq.toFixed(1)+' kg';
      hintEl.style.color='#444';
    } else {
      hintEl.textContent='⚠️ '+v.toFixed(0)+' < '+ant.toFixed(0)+' — valor deve ser maior que o desconto!';
      hintEl.style.color='#c62828';
    }
  } else if(hintEl){
    hintEl.textContent='';
  }
  
  const elAnt=document.getElementById('rod-mat-peso-ant');
  if(elAnt) elAnt.textContent=ant.toFixed(1)+' kg';
}


function rodMatUsarBalanca(){
  const inputEl=document.getElementById('rod-mat-peso-input');
  if(inputEl){
    inputEl.value=_rodPesoAtual.toFixed(1);
    inputEl._manualOverride=false;
    rodMatPreview();
  }
}

function _rodRecalcularLiquido(){
  const brutoEl=document.getElementById('rod-display-bruto');
  const liqEl=document.getElementById('rod-display-liquido');
  if(!_rodTicketSaida){
    if(brutoEl) brutoEl.textContent='— kg';
    if(liqEl)   liqEl.textContent='— kg';
    return;
  }
  const t=TICKETS_DB[_rodTicketSaida];
  if(!t){ if(brutoEl) brutoEl.textContent='— kg'; return; }
  const bruto=parseFloat(t.pesoEntrada||0);
  const tara=_rodPesoAtual;
  const descBag=parseFloat(document.getElementById('rod-desc-bag')?.value||0);
  const descPalet=parseFloat(document.getElementById('rod-desc-palet')?.value||0);
  const liq=Math.max(0,bruto-tara-descBag-descPalet);
  if(brutoEl) brutoEl.textContent=bruto.toFixed(1)+' kg';
  if(liqEl)   liqEl.textContent=liq.toFixed(1)+' kg';
}

