function rodAplicarPesoSaida(){
  const v=parseFloat(document.getElementById('rod-saida-manual')?.value||0);
  if(!v||v<=0){showToast('Digite um peso válido para a tara','error');return;}
  if(!_rodTicketSaida){
    
    const aguardando=Object.entries(TICKETS_DB).filter(([k,t])=>
      t._rodEntrada&&!(t.pesoTara>0)&&t.status!=='Aguard. Preço'&&t.status!=='Pendente'&&t.status!=='Pago'&&t.status!=='Consolidado'
    );
    if(aguardando.length===1){ rodSelecionarParaSaida(aguardando[0][0]); }
    else if(aguardando.length>1){ showToast('Selecione o caminhão na lista de espera primeiro','error'); return; }
    else { showToast('Nenhum caminhão aguardando saída','error'); return; }
  }
  _rodPesoAtual=v;
  const elT=document.getElementById('rod-peso-big-saida');
  if(elT) elT.textContent=v.toFixed(1)+' kg';
  _rodRecalcularLiquido();
}

function rodAutoPreencherVeiculo(){
  const fornNome=(document.getElementById('rod-forn-sel')?.value||'').trim();
  const placaEl=document.getElementById('rod-placa');
  const motEl=document.getElementById('rod-motorista');
  const placaHint=document.getElementById('rod-placa-hint');
  const motHint=document.getElementById('rod-motorista-hint');
  
  if(placaHint) placaHint.textContent='';
  if(motHint) motHint.textContent='';
  if(!fornNome||fornNome==='— Selecione —') return;
  try{
    const _fv=JSON.parse(localStorage.getItem('mm_forn_veiculos')||'{}');
    const ult=_fv[fornNome];
    if(ult){
      if(placaEl && ult.placa){ placaEl.value=ult.placa; if(placaHint) placaHint.textContent='↩ Última: '+ult.placa; }
      if(motEl && ult.motorista){ motEl.value=ult.motorista; if(motHint) motHint.textContent='↩ Último: '+ult.motorista; }
    }
  }catch(e){}
}

