let _rodClientesLoadPromise=null;
function rodGarantirClientesDisponiveis(){
  if((CLIENTES||[]).length){
    if((_rodTipoAtual||'compra')==='venda') rodPopularPessoaSelect();
    return Promise.resolve(true);
  }
  if(!window.__businessRepository) return Promise.resolve(false);
  if(_rodClientesLoadPromise) return _rodClientesLoadPromise;
  _rodClientesLoadPromise=window.__businessRepository.read('clientes').then(remoto=>{
    _syncClientes.carregarDeRemoto(remoto||{}, true);
    try{ renderClientes(); }catch(e){}
    try{ if((_rodTipoAtual||'compra')==='venda') rodPopularPessoaSelect(); }catch(e){}
    return (CLIENTES||[]).length>0;
  }).catch(e=>{
    console.warn('rod clientes firebase:',e);
    return false;
  }).finally(()=>{ _rodClientesLoadPromise=null; });
  return _rodClientesLoadPromise;
}

