function _rodPersistirTicketCritico(tid){
  if(!tid || !TICKETS_DB[tid]) return Promise.resolve(false);
  const gravar=window.__businessRepository
    ? window.__businessRepository.upsert('tickets',tid,TICKETS_DB[tid])
    : Promise.resolve();
  return Promise.resolve(gravar).then(()=>{
    try{ if(typeof fbSalvarImediato==='function') fbSalvarImediato(); else if(typeof fbSalvar==='function') fbSalvar(); }catch(e){}
    return true;
  }).catch(e=>{ console.warn('rod ticket RTDB:',e); return false; });
}

function rodRegistrarEntrada(){
  const _tipo = _rodTipoAtual || 'compra';
  const fornSel=document.getElementById('rod-forn-sel');
  const selNome=(fornSel?.value||'').trim();
  const _fornObj=(_tipo==='compra')?FORNECEDORES.find(f=>f.nome===selNome):null;
  const fornCod=_fornObj?.cod||'';
  const placa=(document.getElementById('rod-placa')?.value||'').trim().toUpperCase();
  const motorista=(document.getElementById('rod-motorista')?.value||'').trim();
  const obs=(document.getElementById('rod-obs')?.value||'').trim();
  const material=(document.getElementById('rod-material')?.value||'').trim();
  
  const _manEntrada=parseFloat(document.getElementById('rod-peso-manual')?.value||0);
  if(_manEntrada>0) _rodAtualizarPeso(_manEntrada);
  const pesoEntrada=_rodPesoAtual;

  const _tipoLabel = _tipo==='venda' ? 'cliente' : 'fornecedor';
  if(!selNome||selNome.startsWith('—')){showToast('Selecione o '+_tipoLabel+'!','error');return;}
  if(!pesoEntrada||pesoEntrada<=0){showToast('Digite o peso de entrada antes de registrar!','error');return;}

  const tid=getNextTicketId(); 

  const statusInicial = _tipo==='venda' ? 'Pesando Materiais' : 'Pesando Bags';

  TICKETS_DB[tid]={
    ticket:tid, data:_hojeISO(),
    tipo:_tipo,
    fornecedor:selNome, fornecedorNome:selNome, fornecedorCod:fornCod,
    cliente:_tipo==='venda'?selNome:'',
    placa, motorista, obs, material,
    pesoEntrada, pesoTara:0, pesoLiquido:0,
    _rodSessao:true, _rodEntrada:true, _balSessao:true,
    _balFinalizado:false,
    status:statusInicial,
    pesagens:[], 
    itens:[], bags:[]
  };

  
  try{
    const fotos=rodCapturarAmbas();
    if(fotos&&fotos.cam1) TICKETS_DB[tid].fotoEntrada1=fotos.cam1;
    if(fotos&&fotos.cam2) TICKETS_DB[tid].fotoEntrada2=fotos.cam2;
    const prevEnt=document.getElementById('rod-fotos-entrada-prev');
    if(prevEnt&&fotos&&(fotos.cam1||fotos.cam2)){
      prevEnt.innerHTML=(fotos.cam1?'<img src="'+fotos.cam1+'" style="flex:1;max-width:49%;border-radius:6px;border:2px solid #2e7d32" title="Câm.1 Entrada">':'')+
                        (fotos.cam2?'<img src="'+fotos.cam2+'" style="flex:1;max-width:49%;border-radius:6px;border:2px solid #2e7d32" title="Câm.2 Entrada">':'');
    }
  }catch(eCam){ console.warn('Câmera entrada:', eCam); }
  saveDB();
  _rodPersistirTicketCritico(tid);

  
  if(selNome){
    try{
      const _fvKey='mm_forn_veiculos';
      const _fv=JSON.parse(localStorage.getItem(_fvKey)||'{}');
      if(placa||motorista) _fv[selNome]={placa,motorista};
      localStorage.setItem(_fvKey,JSON.stringify(_fv));
    }catch(e){}
  }

  
  if(fornSel) fornSel.value='';
  _rodTipoAtual='compra'; rodTipoChange('compra');
  const mp=document.getElementById('rod-peso-manual'); if(mp) mp.value='';
  const rp=document.getElementById('rod-placa'); if(rp) rp.value='';
  const rm=document.getElementById('rod-motorista'); if(rm) rm.value='';
  const ro=document.getElementById('rod-obs'); if(ro) ro.value='';
  const rmat=document.getElementById('rod-material'); if(rmat) rmat.value='';
  _rodPesoAtual=0;
  const ep=document.getElementById('rod-peso-big'); if(ep) ep.textContent='0.0';

  renderRodBalanca();

  
  if(_tipo==='venda'){
    rodEntrarModoMateriais(tid);
    showToast('✅ '+tid+' aberto! Tara: '+pesoEntrada.toFixed(1)+' kg — Agora registre cada material','success',6000);
  } else {
    
    rodEntrarModoMateriaisCompra(tid);
    showToast('✅ '+tid+' aberto! Bruto: '+pesoEntrada.toFixed(1)+' kg — Descarregue e registre cada material','success',6000);
  }
}

function rodSelecionarParaSaida(tid){
  _rodTicketSaida=tid||null;
  
  const sel=document.getElementById('rod-sel-saida');
  if(sel&&tid) sel.value=tid;
  _rodRecalcularLiquido();
  if(tid){
    const t=TICKETS_DB[tid];
    if(t){
      
      const brutoEl=document.getElementById('rod-display-bruto');
      if(brutoEl){
        brutoEl.style.background='#e8f5e9';
        brutoEl.style.border='2px solid #2e7d32';
      }
      
      const taraIn=document.getElementById('rod-saida-manual');
      if(taraIn){ taraIn.focus(); taraIn.select(); }
      showToast('🚛 '+( t.fornecedor||t.ticket||tid)+' selecionado — Bruto: '+(t.pesoEntrada||0).toFixed(1)+' kg. Digite o peso tara.','info',4000);
    }
  } else {
    const brutoEl=document.getElementById('rod-display-bruto');
    if(brutoEl){ brutoEl.style.background=''; brutoEl.style.border=''; }
  }
}

function rodFinalizarSaidaSelecionada(){
  
  if(!_rodTicketSaida){
    const aguardando=Object.entries(TICKETS_DB).filter(([k,t])=>
      t._rodEntrada&&!(t.pesoTara>0)&&
      t.status!=='Aguard. Preço'&&t.status!=='Pendente'&&t.status!=='Pago'&&t.status!=='Consolidado'
    );
    if(aguardando.length===1){
      rodSelecionarParaSaida(aguardando[0][0]);
    } else if(aguardando.length>1){
      showToast('Mais de um caminhão aguardando — clique no caminhão desejado na lista de espera','error',5000);
      return;
    } else {
      showToast('Nenhum caminhão aguardando saída','error');
      return;
    }
  }
  const tid=_rodTicketSaida;
  if(!tid){showToast('Selecione um caminhão na lista de espera','error');return;}
  const t=TICKETS_DB[tid];
  if(!t){showToast('Ticket não encontrado','error');return;}
  
  
  const manualInput=parseFloat(document.getElementById('rod-saida-manual')?.value||0);
  if(manualInput>0){
    _rodPesoAtual=manualInput;
    const elT=document.getElementById('rod-peso-big-saida');
    if(elT) elT.textContent=manualInput.toFixed(1)+' kg';
    _rodRecalcularLiquido();
  }
  const tara=_rodPesoAtual;
  const bruto=parseFloat(t.pesoEntrada||0);
  const descBag=parseFloat(document.getElementById('rod-desc-bag')?.value||0);
  const descPalet=parseFloat(document.getElementById('rod-desc-palet')?.value||0);
  const liq=Math.max(0,bruto-tara-descBag-descPalet);
  const fmt=v=>v.toFixed(1);
  if(!tara||tara<=0){showToast('Digite o peso tara (caminhão vazio) no campo acima antes de finalizar!','error');return;}
  const descontoTxt=(descBag>0||descPalet>0)?`\nDesc. Bags: ${fmt(descBag)} kg\nDesc. Paletes: ${fmt(descPalet)} kg`:'';
  confirmarAcao(
    `Finalizar saída do caminhão?\n\nFornecedor: ${t.fornecedor||'—'}\nBruto: ${fmt(bruto)} kg\nTara: ${fmt(tara)} kg${descontoTxt}\nLíquido: ${fmt(liq)} kg`,
    ()=>{
      
      t.pesoTara=tara;
      t.descontoBags=descBag;
      t.descontoPalets=descPalet;
      t.pesoLiquido=liq;
      t.dataSaida=_hojeISO();
      t._rodSessao=false;

      
      try{
        const fotosSai=rodCapturarAmbas();
        if(fotosSai&&fotosSai.cam1) t.fotoSaida1=fotosSai.cam1;
        if(fotosSai&&fotosSai.cam2) t.fotoSaida2=fotosSai.cam2;
        const prevSai=document.getElementById('rod-fotos-saida-prev');
        if(prevSai&&fotosSai&&(fotosSai.cam1||fotosSai.cam2)){
          prevSai.innerHTML=(fotosSai.cam1?'<img src="'+fotosSai.cam1+'" style="flex:1;max-width:49%;border-radius:6px;border:2px solid #e65100" title="Câm.1 Saída">':'')
                           +(fotosSai.cam2?'<img src="'+fotosSai.cam2+'" style="flex:1;max-width:49%;border-radius:6px;border:2px solid #e65100" title="Câm.2 Saída">':'');
        }
      }catch(eCam){ console.warn('Câmera saída:', eCam); }

      
      const _elDB=document.getElementById('rod-desc-bag');   if(_elDB)  _elDB.value='0';
      const _elDP=document.getElementById('rod-desc-palet'); if(_elDP)  _elDP.value='0';
      
      
      try{ _rodPersistirTicketCritico(tid); }catch(e){}
      if(t._rodEntrada){
        
        
        t.status = 'Aguard. Saída';
        saveDB();
        _rodTicketSaida=null;
        _rodPesoAtual=0;
        const elT=document.getElementById('rod-peso-big-saida'); if(elT) elT.textContent='0.0 kg';
        const elB=document.getElementById('rod-display-bruto');  if(elB) elB.textContent='— kg';
        const elL=document.getElementById('rod-display-liquido');if(elL) elL.textContent='— kg';
        renderRodBalanca();
        try{ renderBalanceiro(); }catch(e){}
        showToast('✅ Peso vazio: '+fmt(tara)+' kg · Líquido: '+fmt(liq)+' kg. Vá ao Balanceiro para liberar para a Secretaria.','success',7000);
      } else {
        
        t._balSessao=false;
        t._balFinalizado=true;
        t.status='Aguard. Preço';
        saveDB();
        _rodTicketSaida=null;
        _rodPesoAtual=0;
        const elT=document.getElementById('rod-peso-big-saida'); if(elT) elT.textContent='0.0 kg';
        const elB=document.getElementById('rod-display-bruto');  if(elB) elB.textContent='— kg';
        const elL=document.getElementById('rod-display-liquido');if(elL) elL.textContent='— kg';
        renderRodBalanca();
        try{ renderBalanceiro(); }catch(e){}
        showToast('✅ Saída finalizada! Ticket '+tid+' — Líquido: '+fmt(liq)+' kg','success',5000);
        setTimeout(()=>{
          confirmarAcao('Imprimir Romaneio de Pesagens do ticket '+tid+'?',
            ()=>rodImprimirRomaneio(tid),'🖨️ Imprimir','btn-save');
        },800);
      }
    },
    'Registrar Peso Vazio','btn-save'
  );
}




let _rodSubTabAtiva='pesagem';
function rodSubTab(t){
  _rodSubTabAtiva=t;
  ['pesagem','historico'].forEach(s=>{
    const panel=document.getElementById('rod-subtab-'+s);
    const btn=document.getElementById('rod-stab-btn-'+s);
    if(panel) panel.style.display=s===t?'':'none';
    if(btn){
      if(s===t){
        btn.style.background='#1a3a2a'; btn.style.color='#fff';
        btn.style.borderColor='#1a3a2a'; btn.style.borderBottom='none';
      } else {
        btn.style.background='#f5f5f5'; btn.style.color='#555';
        btn.style.borderColor='#ccc'; btn.style.borderBottom='2px solid #1a3a2a';
      }
    }
  });
  if(t==='historico') renderRodBalanca();
}

function rodExcluirPesagem(tid){
  if(!_usuarioAtualEhAdmin()){
    showToast('Apenas a administradora pode excluir pesagens!','error'); return;
  }
  const t=TICKETS_DB[tid];
  if(!t){ showToast('Pesagem não encontrada!','error'); return; }
  const nome=t.fornecedor||t.cliente||tid;
  if(!confirm('Excluir pesagem '+tid+' ('+nome+')?\n\nEssa ação não pode ser desfeita.')) return;
  _ticketExcluir(tid);
  saveDB();
  try{ fbSalvar(); }catch(e){}
  renderRodBalanca();
  showToast('Pesagem '+tid+' excluída.','success');
}

function renderRodBalanca(){
  
  
  try{ rodPopularPessoaSelect(); }catch(e){}

  
  
  
  const aguardando=Object.entries(TICKETS_DB).filter(([k,t])=>{
    const compraEmEdicao=(typeof _rodTicketCompraAtivo!=='undefined' && _rodTicketCompraAtivo===k);
    return t._rodEntrada && !(t.pesoTara>0) &&
      t.status!=='Aguard. Preço' && t.status!=='Pendente' && t.status!=='Pago' && t.status!=='Consolidado' &&
      t.tipo!=='venda' && !compraEmEdicao;
  });

  
  if(typeof _rodTicketVendaAtivo!=='undefined' && _rodTicketVendaAtivo){
    try{ rodRenderMateriais(); }catch(e){}
  }
  if(typeof _rodTicketCompraAtivo!=='undefined' && _rodTicketCompraAtivo){
    try{ rodRenderMateriaisCompra(); }catch(e){}
  }

  
  const selSaida=document.getElementById('rod-sel-saida');
  if(selSaida){
    const curSaida=selSaida.value;
    selSaida.innerHTML='<option value="">— Selecione —</option>'+
      aguardando.map(([k,t])=>`<option value="${k}">${t.ticket||k} — ${t.fornecedor||'—'} — ${(t.pesoEntrada||0).toFixed(1)} kg</option>`).join('');
    if(curSaida) selSaida.value=curSaida;
  }

  
  const listEl=document.getElementById('rod-aguard-saida-list');
  if(listEl){
    if(!aguardando.length){
      listEl.innerHTML='<p style="color:#aaa;font-style:italic;font-size:.85rem">Nenhum caminhão aguardando saída.</p>';
    } else {
      listEl.innerHTML=aguardando.map(([k,t])=>`
        <div style="background:#fff;border:2px solid #e65100;border-radius:10px;padding:12px 14px;min-width:200px;cursor:pointer"
          onclick="rodSelecionarParaSaida('${k}')">
          <div style="font-weight:800;color:#e65100;font-size:.95rem">${t.ticket||k}</div>
          <div style="font-size:.82rem;color:#555;margin-top:2px">${t.fornecedor||'—'}</div>
          <div style="font-size:.78rem;color:#888;margin-top:2px">${t.placa||''} · Entrada: ${(t.pesoEntrada||0).toFixed(1)} kg</div>
        </div>`).join('');
    }
  }

  
  try{ rodRenderHistorico(); }catch(e){}
}




function balFinalizarPesagem(){
  if(!_balTicketAtivo){ showToast('Nenhuma sessão ativa!','error'); return; }
  const t = TICKETS_DB[_balTicketAtivo];
  if(!t){ showToast('Ticket não encontrado!','error'); return; }
  const bags = _balBags[_balTicketAtivo]||[];
  if(!bags.length){ showToast('Adicione pelo menos uma bag antes de finalizar!','error'); return; }

  const totalKg = bags.reduce((s,b)=>s+(b.lq||b.br||0),0);
  const isRod = !!t._rodEntrada;

  const msg = isRod
    ? `Confirmar pesagem das bags?\n${bags.length} bags · ${totalKg.toFixed(1)} kg\n\nO ticket ficará aberto no Balanceiro aguardando o peso vazio do caminhão na Rodoviária.`
    : `Finalizar pesagem?\n${bags.length} bags · ${totalKg.toFixed(1)} kg\n\nA compra será enviada para a Secretaria.`;

  confirmarAcao(msg, ()=>{
    t.totalKg = totalKg;
    t.bags = bags.slice();
    
    const byMat={};
    bags.forEach(b=>{
      if(!byMat[b.mat]) byMat[b.mat]={mat:b.mat,br:0,lq:0,pesoLiq:0,preco:0};
      byMat[b.mat].br+=(b.br||0);
      byMat[b.mat].lq+=(b.lq||0);
      byMat[b.mat].pesoLiq+=(b.lq||0);
    });
    t.itens = Object.values(byMat);

    if(isRod){
      
      t._balBagsFinalizado = true;
      
      
      t._rodSessao = false;
      t.status = 'Aguard. Saída';
      saveDB();
      renderBalanceiro();
      renderRodBalanca();
      showToast('✅ Bags salvas! Caminhão aparece na fila de saída. Quando o peso vazio for registrado, libere para a Secretaria aqui.','success',7000);
    } else {
      
      t._balSessao = false;
      t._balFinalizado = true;
      t.status = 'Aguard. Preço';
      saveDB();
      _balTicketAtivo = null;
      renderBalanceiro();
      showToast('✅ Pesagem finalizada! Enviado para a Secretaria.','success',4000);
    }
  }, 'Confirmar bags','btn-save');
}


function balLiberarParaSecretaria(tid){
  const t = TICKETS_DB[tid];
  if(!t){ showToast('Ticket não encontrado','error'); return; }
  const bruto = parseFloat(t.pesoEntrada||0);
  const tara  = parseFloat(t.pesoTara||0);
  const liq   = parseFloat(t.pesoLiquido||0);
  const bags  = (t.bags||[]).length;
  confirmarAcao(
    `Liberar ticket ${tid} para a Secretaria?\n\nBruto: ${bruto.toFixed(1)} kg\nTara: ${tara.toFixed(1)} kg\nLíquido: ${liq.toFixed(1)} kg\nBags: ${bags}`,
    ()=>{
      t._balSessao = false;
      t._balFinalizado = true;
      t._rodSessao = false;
      t._rodEntrada = false;
      t.status = 'Aguard. Preço';
      saveDB();
      if(_balTicketAtivo===tid) _balTicketAtivo=null;
      renderBalanceiro();
      showToast('✅ Ticket '+tid+' liberado para a Secretaria! Líquido: '+liq.toFixed(1)+' kg','success',5000);
      setTimeout(()=>{
        confirmarAcao('Imprimir Romaneio de Pesagens do ticket '+tid+'?',
          ()=>rodImprimirRomaneio(tid),'🖨️ Imprimir','btn-save');
      },800);
    },
    '✅ Liberar para Secretaria','btn-save'
  );
}


function balRemoverDaFila(tid){
  const t = TICKETS_DB[tid];
  if(!t){ showToast('Ticket não encontrado','error'); return; }
  const temBags = (t.bags||[]).length > 0 || (_balBags[tid]||[]).length > 0;
  const temPesos = parseFloat(t.pesoEntrada||0)>0 || parseFloat(t.totalKg||0)>0;

  const msg = temBags||temPesos
    ? `Remover ticket ${tid} da fila do Balanceiro?\n\nFornecedor: ${t.fornecedor||'—'}\n\nO ticket será enviado para a Secretaria com os dados já registrados.`
    : `Excluir ticket ${tid} da fila do Balanceiro?\n\nFornecedor: ${t.fornecedor||'—'}\n\nEste ticket não tem pesagens registradas e será removido completamente.`;

  const label = temBags||temPesos ? 'Remover da fila' : 'Excluir ticket';

  confirmarAcao(msg, ()=>{
    if(temBags||temPesos){
      
      t._balSessao = false;
      t._balFinalizado = true;
      t._rodSessao = false;
      t._rodEntrada = false;
      t.status = 'Aguard. Preço';
    } else {
      
      _ticketExcluir(tid);
      delete _balBags[tid];
    }
    if(_balTicketAtivo===tid) _balTicketAtivo=null;
    saveDB();
    renderBalanceiro();
    try{ renderRodBalanca(); }catch(e){}
    showToast('Ticket '+tid+' removido da fila do Balanceiro.','success',4000);
  }, label, temBags||temPesos ? 'btn-save' : 'btn-edit-danger');
}













let _csSubTabAtiva='pesagens';
function csTab(t){
  _csSubTabAtiva=t;
  ['pesagens','lancamento','historico'].forEach(id=>{
    const panel=document.getElementById('cst-'+id);
    if(panel) panel.style.display = id===t ? '' : 'none';
    const btn = document.getElementById('cst-btn-'+id);
    if(btn){
      btn.style.fontWeight = id===t ? '700' : '400';
      btn.style.color      = id===t ? '#1a3a2a' : '#999';
      btn.style.borderBottomColor = id===t ? '#1a3a2a' : 'transparent';
    }
  });
  if(t==='pesagens')   csRenderPesagens();
  if(t==='historico')  renderTickets();
  if(t==='lancamento') csPopularFornSelect();
}

function csExcluirPesagem(tid){
  if(!_usuarioAtualEhAdmin()){
    showToast('Apenas a administradora pode excluir pesagens!','error'); return;
  }
  const t=TICKETS_DB[tid];
  if(!t){ showToast('Pesagem não encontrada!','error'); return; }
  const nome=t.fornecedor||t.fornecedorNome||tid;
  if(!confirm('Excluir pesagem '+tid+' ('+nome+')?\n\nEssa ação não pode ser desfeita.')) return;
  _ticketExcluir(tid);
  saveDB();
  try{ fbSalvar(); }catch(e){}
  csRenderPesagens();
  showToast('Pesagem '+tid+' excluída.','success');
}

function csRenderPesagens(){
  const el=document.getElementById('cs-pesagens-list'); if(!el) return;
  const pendentes=Object.entries(TICKETS_DB).filter(([k,t])=>
    t._balFinalizado && t.status==='Aguard. Preço' && !t._balSessao && !t._rodEntrada
  );
  if(!pendentes.length){
    el.innerHTML='<div style="text-align:center;padding:48px;color:#aaa"><div style="font-size:2rem;margin-bottom:8px">✅</div>Nenhuma pesagem aguardando lançamento.</div>';
    return;
  }
  const porForn={};
  pendentes.forEach(([k,t])=>{
    const nome=(t.fornecedor||t.fornecedorNome||t.forn||'—').trim();
    if(!porForn[nome]) porForn[nome]=[];
    porForn[nome].push({k,t});
  });
  el.innerHTML=Object.entries(porForn).map(([nome,items])=>{
    const totalKg=items.reduce((s,{t})=>{
      return s+(t.itens||[]).reduce((si,it)=>si+(it.pesoLiq||it.lq||it.br||0),0)
              +(t.bags&&!(t.itens||[]).length?(t.bags||[]).reduce((si,b)=>si+(b.lq||b.br||0),0):0)
              +(!(t.itens||[]).length&&!(t.bags||[]).length?t.totalKg||0:0);
    },0);
    const pesRows=items.map(({k,t})=>{
      const kg=(t.itens||[]).reduce((si,it)=>si+(it.pesoLiq||it.lq||it.br||0),0)||
               (t.bags||[]).reduce((si,b)=>si+(b.lq||b.br||0),0)||t.totalKg||0;
      const data=t.data?t.data.split('-').reverse().join('/'):'—';
      const _isAdmCs=_usuarioAtualEhAdmin();
      const delBtnCs=_isAdmCs?`<button onclick="csExcluirPesagem('${k}')" title="Excluir pesagem" style="background:#c62828;color:#fff;border:none;border-radius:5px;padding:3px 7px;cursor:pointer;font-size:.72rem;margin-left:2px">🗑️</button>`:'';
      return `<div style="font-size:.8rem;color:#555;padding:4px 0;border-bottom:1px solid #f0f0f0;display:flex;gap:8px;align-items:center">
        <span style="min-width:70px;color:#1565c0;font-weight:600">${t.ticket||k}</span>
        <span style="min-width:80px">${data}</span>
        <span style="flex:1">${(t.itens||[]).map(it=>it.mat).join(', ')||'—'}</span>
        <span style="font-weight:700">${kg.toFixed(1)} kg</span>
        <button onclick="csAbrirImpureza('${k}')" title="Desconto de Impureza" style="background:#1a3a2a;color:#fff;border:none;border-radius:5px;padding:3px 7px;cursor:pointer;font-size:.72rem;margin-left:4px">✏️ Impureza</button>
        ${delBtnCs}
      </div>`;
    }).join('');
    return `<div style="background:#fff;border:2px solid #1a3a2a;border-radius:12px;padding:16px;margin-bottom:12px">
      <div style="display:flex;align-items:flex-start;gap:14px;flex-wrap:wrap">
        <div style="flex:1;min-width:200px">
          <div style="font-size:1.05rem;font-weight:800;color:#1a3a2a;margin-bottom:4px">${esc(nome)}</div>
          <div style="font-size:.8rem;color:#888;margin-bottom:8px">${items.length} pesagem${items.length>1?'ns':''} · ${totalKg.toFixed(1)} kg total</div>
          <div>${pesRows}</div>
        </div>
        <button class="btn-save" style="min-width:160px;padding:12px 18px;font-size:.9rem"
          onclick="csAbrirLancamento('${esc(nome)}')">
          💰 Lançar Preços →
        </button>
      </div>
    </div>`;
  }).join('');
}

function csPopularFornSelect(){
  const sel=document.getElementById('cs-lanc-forn'); if(!sel) return;
  const cur=sel.value;
  
  const ativos=getFornAtivos().slice().sort((a,b)=>(a.nome||'').localeCompare(b.nome||'','pt-BR'));
  sel.innerHTML='<option value="">— Selecione o fornecedor —</option>'+
    ativos.map(f=>`<option value="${esc(f.nome||'')}"${f.nome===cur?' selected':''}>${esc(f.nome||'')}</option>`).join('');
  if(cur) sel.value=cur;
}

function csAbrirLancamento(fornNome){
  csTab('lancamento');
  const sel=document.getElementById('cs-lanc-forn');
  if(sel){ sel.value=fornNome; }
  csCarregarForn(fornNome);
}

function csCarregarForn(forceName){
  const sel=document.getElementById('cs-lanc-forn');
  const fornNome=(forceName||sel?.value||'').trim();
  const body=document.getElementById('cs-lanc-body'); if(!body) return;
  if(!fornNome){ body.innerHTML='<p style="color:#aaa;font-style:italic;text-align:center;padding:40px">Selecione um fornecedor para ver as pesagens.</p>'; return; }

  const tickets=Object.entries(TICKETS_DB).filter(([k,t])=>
    (t.fornecedor===fornNome||t.fornecedorNome===fornNome||t.forn===fornNome)&&
    t._balFinalizado&&t.status==='Aguard. Preço'&&!t._balSessao&&!t._rodEntrada
  );
  if(!tickets.length){ body.innerHTML='<p style="color:#aaa;font-style:italic;text-align:center;padding:40px">Nenhuma pesagem pendente para '+esc(fornNome)+'.</p>'; return; }

  const fornObj=FORNECEDORES.find(f=>f.nome.trim()===fornNome.trim());
  const fornCod=fornObj?.cod||'';
  
  const adtsTodos=(fornCod?ADT_POR_FORN[fornCod]||[]:Object.values(ADT_POR_FORN).flat()).filter(a=>a.status!=='Quitado');
  const adts=adtsTodos.filter(a=>a.forma!=='Cheque');
  const adtCheqs=adtsTodos.filter(a=>a.forma==='Cheque');
  
  const _cheqsBase=fornCod
    ? (CHEQUES_POR_FORN[fornCod]||[]).length>0
        ? CHEQUES_POR_FORN[fornCod]||[]
        : Object.values(CHEQUES_POR_FORN||{}).flat().filter(c=>{
            const k=Object.keys(CHEQUES_POR_FORN).find(kk=>(CHEQUES_POR_FORN[kk]||[]).includes(c));
            return k===fornCod;
          })
    : Object.values(CHEQUES_POR_FORN||{}).flat();
  const cheqs=[..._cheqsBase.filter(c=>!c._aplicadoTicket), ...adtCheqs];
  const _sdRaw=SALDO_DEVEDOR_FORN&&SALDO_DEVEDOR_FORN[fornCod];
  const saldoDev=_sdRaw?(typeof _sdRaw==='object'?(_sdRaw.valor||0):Number(_sdRaw||0)):0;
  const fmt=v=>Number(v||0).toLocaleString('pt-BR',{minimumFractionDigits:2});

  
  const byMat={};
  tickets.forEach(([k,t])=>{
    (t.itens||[]).forEach(it=>{
      if(!byMat[it.mat]) byMat[it.mat]={mat:it.mat,pesoLiq:0,preco:0};
      byMat[it.mat].pesoLiq+=parseFloat(it.pesoLiq||it.lq||it.br||0);
    });
    if(!(t.itens||[]).length)(t.bags||[]).forEach(b=>{
      if(!byMat[b.mat]) byMat[b.mat]={mat:b.mat,pesoLiq:0,preco:0};
      byMat[b.mat].pesoLiq+=parseFloat(b.lq||b.br||0);
    });
  });
  const itens=Object.values(byMat);

  const pesHtml=tickets.map(([k,t])=>{
    const kg=(t.itens||[]).reduce((s,it)=>s+(it.pesoLiq||it.lq||it.br||0),0)||
             (t.bags||[]).reduce((s,b)=>s+(b.lq||b.br||0),0)||t.totalKg||0;
    const data=t.data?t.data.split('-').reverse().join('/'):'—';
    return `<div style="display:flex;gap:8px;font-size:.8rem;color:#555;padding:3px 0;border-bottom:1px solid #e8f5e9;align-items:center">
      <span style="color:#1565c0;font-weight:700;min-width:70px">${t.ticket||k}</span>
      <span style="min-width:70px">${data}</span>
      <span style="flex:1">${(t.itens||[]).map(it=>it.mat).join(', ')||'—'}</span>
      <span style="font-weight:700">${kg.toFixed(1)} kg</span>
      <button onclick="csAbrirImpureza('${k}')" title="Desconto de Impureza" style="background:#1a3a2a;color:#fff;border:none;border-radius:5px;padding:3px 7px;cursor:pointer;font-size:.72rem;margin-left:4px">✏️ Impureza</button>
    </div>`;
  }).join('');

  const matHtml=itens.map((it,i)=>`
    <tr style="border-bottom:1px solid #e8f5e9">
      <td style="padding:10px 12px;font-weight:700;font-size:.95rem">${it.mat}</td>
      <td style="padding:10px 12px;text-align:right;font-size:.95rem">${it.pesoLiq.toFixed(1)} kg</td>
      <td style="padding:10px 8px">
        <input type="number" min="0" step="0.01" id="cspr-${i}" value="0"
          oninput="csCalc()" placeholder="R$/kg"
          style="width:110px;padding:7px 10px;border:2px solid #1a3a2a;border-radius:7px;font-size:.95rem;text-align:right">
      </td>
      <td style="padding:10px 12px;text-align:right;font-weight:800;font-size:.95rem;color:#1b5e20" id="cssub-${i}">R$ 0,00</td>
    </tr>`).join('');

  const adtRows=adts.map((a,i)=>`<label style="display:flex;align-items:center;gap:10px;padding:8px 0;border-bottom:1px solid #f0f0f0;cursor:pointer;font-size:.88rem">
      <input type="checkbox" id="csadt-${i}" value="${a.valor||0}" onchange="csCalc()" style="width:16px;height:16px;cursor:pointer">
      <span style="flex:1"><b>${a.data||'—'}</b> — R$ ${fmt(a.valor||0)}</span>
      <span style="color:#888">${a.bancoNome||a.forma||'—'}</span>
    </label>`).join('');
  const cheqRows=cheqs.map((c,j)=>{
    const isAdt=!!c.cod; 
    const num=c.num||c.cod||'—';
    const bomPara=c.bomPara||c.data||'—';
    const banco=c.banco||c.bancoNome||c.forma||'—';
    const statusLabel=isAdt?'💰 Adiantamento':(c.status==='Compensado'?'✅ Compensado':'⏳ Pendente');
    const statusColor=isAdt?'#1a3a2a':(c.status==='Compensado'?'#2e7d32':'#e65100');
    return `<label style="display:flex;align-items:center;gap:10px;padding:8px 0;border-bottom:1px solid #f0f0f0;cursor:pointer;font-size:.88rem">
      <input type="checkbox" id="cscheq-${j}" value="${c.valor||0}" onchange="csCalc()" style="width:16px;height:16px;cursor:pointer">
      <span style="flex:1"><b>🧾 Cheque nº ${num}</b> — R$ ${fmt(c.valor||0)} — Bom para: ${bomPara}</span>
      <span style="color:${statusColor};font-size:.78rem;font-weight:700">${statusLabel} · ${banco}</span>
    </label>`;
  }).join('');
  const sdvRow=saldoDev>0
    ?`<label style="display:flex;align-items:center;gap:10px;padding:8px 0;border-bottom:1px solid #ffe082;cursor:pointer;font-size:.88rem;background:#fff8e1;border-radius:6px;padding:8px 10px;margin-top:4px">
      <input type="checkbox" id="cssdv" value="${saldoDev}" onchange="csCalc()" checked style="width:16px;height:16px;cursor:pointer">
      <span style="flex:1;color:#e65100"><b>⚠️ Saldo negativo anterior</b> — R$ ${fmt(saldoDev)}</span>
      <span style="color:#888">Crédito acumulado</span>
    </label>`:'';
  const adtHtml=(adtRows||cheqRows||sdvRow)
    ? (adtRows+cheqRows+sdvRow)
    : '<p style="color:#aaa;font-size:.85rem;margin:0;padding:8px 0">Nenhum adiantamento, cheque ou crédito pendente.</p>';

  body.innerHTML=`
    <div style="max-width:900px">
      <div style="background:#e8f5e9;border-radius:10px;padding:12px 16px;margin-bottom:16px">
        <div style="font-weight:700;color:#1a3a2a;font-size:.85rem;margin-bottom:8px">📦 Pesagens incluídas</div>
        ${pesHtml}
      </div>
      <div style="background:#fff;border:2px solid #1a3a2a;border-radius:10px;overflow:hidden;margin-bottom:16px">
        <div style="background:#1a3a2a;color:#fff;padding:10px 16px;font-weight:700;font-size:.9rem">⚖️ Materiais</div>
        <table style="width:100%;border-collapse:collapse">
          <thead><tr style="background:#f1f8e9">
            <th style="padding:8px 12px;text-align:left;font-size:.8rem;color:#555">Material</th>
            <th style="padding:8px 12px;text-align:right;font-size:.8rem;color:#555">Peso Líq.</th>
            <th style="padding:8px 12px;text-align:center;font-size:.8rem;color:#555">R$/kg</th>
            <th style="padding:8px 12px;text-align:right;font-size:.8rem;color:#555">Subtotal</th>
          </tr></thead>
          <tbody>${matHtml}</tbody>
        </table>
      </div>
      <div style="background:#fff;border:1px solid #ddd;border-radius:10px;overflow:hidden;margin-bottom:16px">
        <div style="background:#fff8e1;padding:10px 16px;font-weight:700;font-size:.9rem;color:#e65100;border-bottom:1px solid #ffe082">💳 Adiantamentos a Descontar</div>
        <div style="padding:8px 16px">${adtHtml}</div>
      </div>
      <div style="display:flex;gap:16px;flex-wrap:wrap;align-items:flex-start">
        <div style="flex:1;min-width:200px">
          <label style="font-size:.78rem;font-weight:700;color:#555;text-transform:uppercase;display:block;margin-bottom:4px">Vencimento do saldo</label>
          <input type="date" id="cs-lanc-venc" style="width:100%;padding:9px 12px;border:2px solid #ccc;border-radius:7px;font-size:.92rem;box-sizing:border-box">
        </div>
        <div style="flex:1;min-width:260px;background:#1a3a2a;border-radius:10px;padding:14px 18px;color:#fff">
          <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px">
            <span style="font-size:.8rem;color:#aaa">TOTAL BRUTO</span>
            <span id="cs-tot" style="font-size:1.15rem;font-weight:800;color:#4caf50">R$ 0,00</span>
          </div>
          <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px">
            <span style="font-size:.8rem;color:#aaa">(−) ADIANTAMENTOS</span>
            <span id="cs-tot-adt" style="font-size:1rem;font-weight:700;color:#ffb74d">R$ 0,00</span>
          </div>
          <div style="border-top:1px solid #2e5c3a;padding-top:8px;display:flex;justify-content:space-between;align-items:center">
            <span style="font-size:.85rem;color:#aaa;font-weight:700">SALDO A PAGAR</span>
            <span id="cs-saldo" style="font-size:1.4rem;font-weight:900;color:#ef5350">R$ 0,00</span>
          </div>
        </div>
      </div>
      <div style="display:flex;gap:10px;justify-content:flex-end;margin-top:16px;padding-top:14px;border-top:1px solid #ddd">
        <button class="btn-cancel" onclick="csTab('pesagens')">← Voltar</button>
        <button class="btn-save" style="min-width:220px;font-size:.95rem;padding:11px 18px" onclick="csConfirmarEntrada('${esc(fornNome)}')">
          ✅ Confirmar Entrada
        </button>
      </div>
    </div>`;

  body.dataset.itensCount=itens.length;
  body.dataset.adtCount=adts.length;
  body.dataset.cheqsCount=cheqs.length;
  body.dataset.saldoAnterior=saldoDev;
  body.dataset.itensData=JSON.stringify(itens);
  body.dataset.adtsData=JSON.stringify(adts);
  body.dataset.cheqsData=JSON.stringify(cheqs);
  body.dataset.ticketKeys=JSON.stringify(tickets.map(([k])=>k));
  body.dataset.fornCod=fornCod;
  csCalc();
}

function csCalc(){
  const body=document.getElementById('cs-lanc-body'); if(!body) return;
  const n=parseInt(body.dataset.itensCount)||0;
  const itens=JSON.parse(body.dataset.itensData||'[]');
  const fmt=v=>Number(v||0).toLocaleString('pt-BR',{minimumFractionDigits:2});
  let total=0;
  for(let i=0;i<n;i++){
    const pr=parseFloat(document.getElementById('cspr-'+i)?.value||0);
    const peso=itens[i]?.pesoLiq||0;
    const sub=peso*pr; total+=sub;
    const subEl=document.getElementById('cssub-'+i);
    if(subEl) subEl.textContent='R$ '+fmt(sub);
  }
  const na=parseInt(body.dataset.adtCount)||0;
  let totalAdt=0;
  for(let i=0;i<na;i++){
    const cb=document.getElementById('csadt-'+i);
    if(cb?.checked) totalAdt+=parseFloat(cb.value||0);
  }
  const nc=parseInt(body.dataset.cheqsCount)||0;
  for(let j=0;j<nc;j++){
    const cb=document.getElementById('cscheq-'+j);
    if(cb?.checked) totalAdt+=parseFloat(cb.value||0);
  }
  const cbSdv=document.getElementById('cssdv');
  if(cbSdv?.checked) totalAdt+=parseFloat(cbSdv.value||0);
  const saldo=total-totalAdt;
  const totEl=document.getElementById('cs-tot');
  const adtEl=document.getElementById('cs-tot-adt');
  const saldoEl=document.getElementById('cs-saldo');
  if(totEl) totEl.textContent='R$ '+fmt(total);
  if(adtEl) adtEl.textContent='R$ '+fmt(totalAdt);
  if(saldoEl){ saldoEl.textContent='R$ '+fmt(Math.abs(saldo)); saldoEl.style.color=saldo<=0?'#4caf50':'#ef5350'; saldoEl.title=saldo<0?'Crédito a favor do fornecedor':''; }
}

function csConfirmarEntrada(fornNome){
  const body=document.getElementById('cs-lanc-body'); if(!body) return;
  const n=parseInt(body.dataset.itensCount)||0;
  const itens=JSON.parse(body.dataset.itensData||'[]');
  const adts=JSON.parse(body.dataset.adtsData||'[]');
  const ticketKeys=JSON.parse(body.dataset.ticketKeys||'[]');
  const fornCod=body.dataset.fornCod||'';
  const fmt=v=>Number(v||0).toLocaleString('pt-BR',{minimumFractionDigits:2});

  let total=0;
  const itensFinal=itens.map((it,i)=>{
    const pr=parseFloat(document.getElementById('cspr-'+i)?.value||0);
    const sub=(it.pesoLiq||0)*pr; total+=sub;
    return {...it,preco:pr,subtotal:sub};
  });
  let totalAdt=0;
  const adtsUsados=[];
  adts.forEach((a,i)=>{
    const cb=document.getElementById('csadt-'+i);
    if(cb?.checked){ totalAdt+=parseFloat(a.valor||0); adtsUsados.push(a); }
  });
  const cheqs2=JSON.parse(body.dataset.cheqsData||'[]');
  const cheqsUsados=[];
  cheqs2.forEach((c,j)=>{
    const cb=document.getElementById('cscheq-'+j);
    if(cb?.checked){ totalAdt+=parseFloat(c.valor||0); cheqsUsados.push(c); }
  });
  const cbSdv2=document.getElementById('cssdv');
  const saldoDevUsado=cbSdv2?.checked?parseFloat(cbSdv2.value||0):0;
  if(saldoDevUsado>0) totalAdt+=saldoDevUsado;
  const saldoPagar=total-totalAdt;
  const vencEl=document.getElementById('cs-lanc-venc');
  const vencISO=vencEl?.value||(new Date().toISOString().slice(0,10));
  const vencBR=vencISO.split('-').reverse().join('/');
  const hoje=new Date().toISOString().slice(0,10).split('-').reverse().join('/');

  const ticketNum=getNextTicketId(); 

  TICKETS_DB[ticketNum]={
    ticket:ticketNum, data:new Date().toISOString().slice(0,10),
    fornecedor:fornNome, fornecedorNome:fornNome, fornecedorCod:fornCod,
    itens:itensFinal,
    totalKg:itensFinal.reduce((s,it)=>s+(it.pesoLiq||0),0),
    totalGeral:total, adiantamento:totalAdt, saldoPagar:Math.max(0,saldoPagar),
    status:saldoPagar<=0?'Pago':'Pendente',
    _balFinalizado:false, _consolidado:true, _ticketsOrigemIds:ticketKeys
  };
  ticketKeys.forEach(k=>{
    if(TICKETS_DB[k]){
      TICKETS_DB[k]._balFinalizado=false;
      TICKETS_DB[k].status='Consolidado';
      TICKETS_DB[k]._consolidadoEm=ticketNum;
    }
  });
  adtsUsados.forEach(a=>{
    const l=ADT_POR_FORN[fornCod]||[];
    const f=l.find(x=>x.cod===a.cod);
    if(f){f.status='Quitado';f.ticket=ticketNum;}
  });
  cheqsUsados.forEach(c=>{
    if(c.cod){
      
      const l=ADT_POR_FORN[fornCod]||[];
      const f=l.find(x=>x.cod===c.cod);
      if(f){ f.status='Quitado'; f.ticket=ticketNum; }
    } else {
      
      const l=CHEQUES_POR_FORN[fornCod]||Object.values(CHEQUES_POR_FORN).flat();
      const f=l.find ? l.find(x=>x.id===c.id) : null;
      if(f){ f._aplicadoTicket=ticketNum; f.vinculo=f.vinculo||ticketNum; }
    }
  });
  if(saldoDevUsado>0){
    _apagarChave('saldoDevedor', SALDO_DEVEDOR_FORN, fornCod);
    localStorage.setItem('mm_saldo_devedor',JSON.stringify(SALDO_DEVEDOR_FORN));
  }
  
  if(saldoPagar<0){
    if(!SALDO_DEVEDOR_FORN[fornCod]) SALDO_DEVEDOR_FORN[fornCod]={};
    SALDO_DEVEDOR_FORN[fornCod]={valor:Math.abs(saldoPagar),ticket:ticketNum};
    localStorage.setItem('mm_saldo_devedor',JSON.stringify(SALDO_DEVEDOR_FORN));
  }
  if(saldoPagar>0){
    CONTAS_PAGAR.push({ id:_novoIdCP(),
      lancto:hoje, desc:'Compra de Sucata — '+fornNome+' — '+ticketNum,
      cred:fornNome, cat:'Compra de Sucata', bancoCod:'', bancoNome:'', tipoForn:'compra',
      venc:vencBR, valor:saldoPagar, status:'Pendente', dataPgto:'',
      obs:itensFinal.map(it=>it.mat+' '+it.pesoLiq.toFixed(1)+'kg×R$'+fmt(it.preco)).join(' | '),
      ticket:ticketNum
    });
    saveContasPagar();
  }
  saveDB();
  body.dataset.itensCount='0';
  csTab('pesagens');
  try{renderDashboard();}catch(e){}
  try{renderContasPagar();}catch(e){}
  showToast('✅ Entrada '+ticketNum+' confirmada!'+(saldoPagar>0?' Conta a Pagar: R$ '+fmt(saldoPagar):''),'success',7000);
}






function _balGetHistorico(){
  const filtForn=(document.getElementById('balhist-forn')?.value||'').trim().toUpperCase();
  const filtDe=document.getElementById('balhist-de')?.value||'';
  const filtAte=document.getElementById('balhist-ate')?.value||'';
  const toIso=d=>{ if(!d) return ''; if(d.includes('-')) return d; const p=d.split('/'); return p[2]+'-'+p[1]+'-'+p[0]; };

  
  const rows=[];
  Object.entries(TICKETS_DB).forEach(([tid,t])=>{
    if(!t._balFinalizado && !t.bags?.length) return;
    const forn=(t.fornecedor||t.fornecedorNome||t.forn||'—').trim();
    if(filtForn && !forn.toUpperCase().includes(filtForn)) return;
    if(filtDe && (t.data||'') < filtDe) return;
    if(filtAte && (t.data||'') > filtAte) return;
    const bags=t.bags||[];
    if(bags.length){
      bags.forEach(b=>{
        rows.push({data:t.data||'—', ticket:t.ticket||tid, forn, mat:b.mat||'—',
          bagNum:b.bagNum||'—', br:b.br||0, tara:b.tara||0, lq:b.lq||b.br||0,
          balanca:b.balanca||'—', status:t.status||'—'});
      });
    } else if(t._balFinalizado||(t.itens||[]).length){
      
      (t.itens||[]).forEach(it=>{
        rows.push({data:t.data||'—', ticket:t.ticket||tid, forn, mat:it.mat||'—',
          bagNum:'—', br:it.br||it.pesoLiq||0, tara:0, lq:it.lq||it.pesoLiq||0,
          balanca:'—', status:t.status||'—'});
      });
    }
  });
  rows.sort((a,b)=>b.data.localeCompare(a.data)||b.ticket.localeCompare(a.ticket));
  return rows;
}

function balRenderHistorico(){
  const rows=_balGetHistorico();
  const tbody=document.getElementById('balhist-body'); if(!tbody) return;
  const cnt=document.getElementById('balhist-count');
  if(cnt) cnt.textContent=rows.length+' registro'+(rows.length!==1?'s':'');
  if(!rows.length){
    tbody.innerHTML='<tr><td colspan="10" style="text-align:center;color:#aaa;padding:20px">Nenhuma pesagem encontrada.</td></tr>';
    return;
  }
  const fmt=v=>Number(v||0).toFixed(1);
  tbody.innerHTML=rows.map(r=>`<tr>
    <td>${fmtDate(r.data)||'—'}</td>
    <td><b>${r.ticket}</b></td>
    <td>${r.forn}</td>
    <td>${r.mat}</td>
    <td style="text-align:center">${r.bagNum}</td>
    <td style="text-align:right">${fmt(r.br)}</td>
    <td style="text-align:right">${r.tara?fmt(r.tara):'—'}</td>
    <td style="text-align:right;font-weight:700;color:#1b5e20">${fmt(r.lq)}</td>
    <td style="font-size:.78rem">${r.balanca}</td>
    <td><span class="b b-${(r.status||'').toLowerCase().replace(/\W/g,'_')}">${r.status}</span></td>
    <td><button onclick="balExcluirTicket('${r.ticket}')" title="Excluir" style="background:#c0392b;color:#fff;border:none;border-radius:5px;padding:3px 8px;cursor:pointer;font-size:.75rem">🗑️</button></td>
  </tr>`).join('');
}

function balLimparFiltrosHist(){
  const ids=['balhist-forn','balhist-de','balhist-ate'];
  ids.forEach(id=>{ const el=document.getElementById(id); if(el) el.value=''; });
  balRenderHistorico();
}

function balDownloadHistorico(){
  const rows=_balGetHistorico();
  if(!rows.length){ showToast('Nenhum dado para exportar','error'); return; }
  const cols=['Data','Ticket','Fornecedor','Material','Nº Bag','Bruto kg','Tara kg','Líquido kg','Balança','Status'];
  const csv=[cols.join(';'),...rows.map(r=>[
    r.data?r.data.split('-').reverse().join('/'):'',
    r.ticket, r.forn, r.mat, r.bagNum,
    Number(r.br||0).toFixed(1), Number(r.tara||0).toFixed(1), Number(r.lq||0).toFixed(1),
    r.balanca, r.status
  ].map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(';'))].join('\r\n');
  const blob=new Blob(['﻿'+csv],{type:'text/csv;charset=utf-8'});
  const a=document.createElement('a');
  a.href=URL.createObjectURL(blob);
  a.download='historico_balanceiro_'+(new Date().toISOString().slice(0,10))+'.csv';
  a.click();
  showToast('✅ CSV exportado!','success',3000);
}

function balImprimirHistorico(){
  const rows=_balGetHistorico();
  if(!rows.length){ showToast('Nenhum dado para imprimir','error'); return; }
  const fmt=v=>Number(v||0).toFixed(1);
  const filtForn=document.getElementById('balhist-forn')?.value||'';
  const filtDe=document.getElementById('balhist-de')?.value||'';
  const filtAte=document.getElementById('balhist-ate')?.value||'';
  const totalLq=rows.reduce((s,r)=>s+(r.lq||0),0);
  const html=`<!DOCTYPE html><html><head><meta charset="UTF-8">
  <title>Histórico Balanceiro</title>
  <style>body{font-family:Arial,sans-serif;font-size:11px;margin:16px}
  h2{color:#1a3a2a;margin:0 0 4px}p{margin:0 0 10px;color:#555;font-size:10px}
  table{width:100%;border-collapse:collapse}
  th{background:#1a3a2a;color:#fff;padding:5px 6px;text-align:left;font-size:10px}
  td{padding:4px 6px;border-bottom:1px solid #e0e0e0}
  tfoot td{font-weight:700;background:#e8f5e9;border-top:2px solid #1a3a2a}
  @media print{@page{size:landscape}}</style></head><body>
  <h2>⚖️ ${_empresaPrincipalLabel()} — Histórico de Pesagens Balanceiro</h2>
  <p>Gerado em ${new Date().toLocaleString('pt-BR')}
  ${filtForn?' · Fornecedor: '+filtForn:''}${filtDe?' · De: '+filtDe.split('-').reverse().join('/'):''}${filtAte?' · Até: '+filtAte.split('-').reverse().join('/'):''}</p>
  <table><thead><tr>
    <th>Data</th><th>Ticket</th><th>Fornecedor</th><th>Material</th><th>Nº Bag</th>
    <th>Bruto kg</th><th>Tara kg</th><th>Líquido kg</th><th>Balança</th><th>Status</th><th></th>
  </tr></thead><tbody>
  ${rows.map(r=>`<tr>
    <td>${fmtDate(r.data)||'—'}</td>
    <td><b>${r.ticket}</b></td><td>${r.forn}</td><td>${r.mat}</td>
    <td style="text-align:center">${r.bagNum}</td>
    <td style="text-align:right">${fmt(r.br)}</td>
    <td style="text-align:right">${r.tara?fmt(r.tara):'—'}</td>
    <td style="text-align:right;font-weight:700;color:#1b5e20">${fmt(r.lq)}</td>
    <td>${r.balanca}</td><td>${r.status}</td>
  </tr>`).join('')}
  </tbody><tfoot><tr>
    <td colspan="7" style="text-align:right">TOTAL LÍQUIDO (${rows.length} registros):</td>
    <td style="text-align:right">${totalLq.toFixed(1)} kg</td><td colspan="2"></td>
  </tr></tfoot></table>
  <script>window.onload=()=>window.print()<\/script></body></html>`;
  const w=window.open('','_blank','width=1100,height=700');
  if(w){ w.document.write(html); w.document.close(); }
}

function balSalvarPDF(){
  
  balImprimirHistorico();
  setTimeout(()=>showToast('Na janela que abriu: use Ctrl+P → "Salvar como PDF"','info',6000),800);
}





function _rodGetHistorico(){
  const q=(document.getElementById('rodhist-forn')?.value||'').trim().toUpperCase();
  const qMat=(document.getElementById('rodhist-mat')?.value||'').trim().toUpperCase();
  const filtDe=document.getElementById('rodhist-de')?.value||'';
  const filtAte=document.getElementById('rodhist-ate')?.value||'';

  return Object.entries(TICKETS_DB)
    .filter(([k,t])=>{
      if(!t._rodEntrada && !t.pesoEntrada && !t.placa) return false;
      
      if(q){
        const campos=[
          t.fornecedor||'', t.fornecedorNome||'', t.forn||'',
          t.cliente||'', t.placa||'', t.motorista||'', t.ticket||k
        ].join(' ').toUpperCase();
        if(!campos.includes(q)) return false;
      }
      
      if(qMat){
        const mats=[t.material||''];
        (t.pesagens||[]).forEach(p=>mats.push(p.material||''));
        (t.pesagensCompra||[]).forEach(p=>mats.push(p.material||''));
        if(!mats.join(' ').toUpperCase().includes(qMat)) return false;
      }
      const dataTicket=t.data||(t.ts||'').slice(0,10)||(t.dataEntrada||'');
      if(filtDe && dataTicket && dataTicket < filtDe) return false;
      if(filtAte && dataTicket && dataTicket > filtAte) return false;
      return true;
    })
    .sort(([ka,a],[kb,b])=>(b.data||'').localeCompare(a.data||'')||(b.ticket||kb).localeCompare(a.ticket||ka));
}


function rodRenderHistorico(){
  const hist=document.getElementById('rod-historico-list');
  if(!hist) return;
  const todos=_rodGetHistorico();
  const countEl=document.getElementById('rodhist-count');
  if(countEl) countEl.textContent=todos.length+' registro(s)';
  if(!todos.length){
    hist.innerHTML='<tr><td colspan="12" style="color:#aaa;text-align:center;padding:20px">Nenhuma pesagem encontrada</td></tr>';
    return;
  }
  hist.innerHTML=todos.map(([k,t])=>{
    const isAguard=t.status==='Aguard. Saída'||(t._rodEntrada&&t._balFinalizado&&!t._rodSessao&&t.status!=='Aguard. Preço'&&t.status!=='Pendente'&&t.status!=='Pago');
    const isPesandoMat=t.status==='Pesando Materiais';
    const isPesandoCompra=t.status==='Pesando Bags' && t.tipo!=='venda' && !!t._rodEntrada;
    const statusBadge=(isPesandoCompra||isPesandoMat)
      ?`<span style="background:${isPesandoMat?'#e65100':'#1565c0'};color:#fff;padding:2px 8px;border-radius:8px;font-size:.72rem;font-weight:700">${isPesandoMat?'🚚 Pesando':'⚖️ Pesando'}</span>`
      :isAguard
      ?'<span style="background:#e65100;color:#fff;padding:2px 8px;border-radius:8px;font-size:.72rem;font-weight:700">⏳ Aguard. Saída</span>'
      :`<span style="background:#2e7d32;color:#fff;padding:2px 8px;border-radius:8px;font-size:.72rem;font-weight:700">✅ ${t.status||'—'}</span>`;
    const finBtn=isPesandoMat
      ?`<button onclick="rodSubTab('pesagem');rodEntrarModoMateriais('${k}')" style="background:#e65100;color:#fff;border:none;border-radius:6px;padding:4px 9px;font-size:.75rem;cursor:pointer;font-weight:700">⚖️ Retomar</button>`
      :isPesandoCompra
      ?`<button onclick="rodSubTab('pesagem');rodEntrarModoMateriaisCompra('${k}')" style="background:#1565c0;color:#fff;border:none;border-radius:6px;padding:4px 9px;font-size:.75rem;cursor:pointer;font-weight:700">⚖️ Retomar</button>`
      :isAguard
      ?`<button onclick="rodSelecionarParaSaida('${k}')" style="background:#e65100;color:#fff;border:none;border-radius:6px;padding:4px 9px;font-size:.75rem;cursor:pointer;font-weight:700">⚖️ Finalizar</button>`
      :`<button onclick="rodImprimirRomaneio('${k}')" style="background:#1a3a2a;color:#fff;border:none;border-radius:6px;padding:4px 9px;font-size:.75rem;cursor:pointer;font-weight:700">🖨️ Romaneio</button>`;
    const _isAdm=_usuarioAtualEhAdmin();
    const delBtn=_isAdm
      ?`<button onclick="rodExcluirPesagem('${k}')" style="background:#c62828;color:#fff;border:none;border-radius:6px;padding:4px 9px;font-size:.75rem;cursor:pointer;font-weight:700;margin-left:4px" title="Excluir">🗑️</button>`:'';
    const tipoBadge=t.tipo==='venda'
      ?'<span style="background:#e65100;color:#fff;padding:2px 7px;border-radius:6px;font-size:.7rem;font-weight:700">🚚 Venda</span>'
      :'<span style="background:#1565c0;color:#fff;padding:2px 7px;border-radius:6px;font-size:.7rem;font-weight:700">🏭 Compra</span>';
    const nomePessoa=t.tipo==='venda'?(t.cliente||t.fornecedor||'—'):(t.fornecedor||t.fornecedorNome||'—');
    return `<tr>
      <td>${fmtDate(t.data)||'—'}</td>
      <td><b>${t.ticket||k}</b></td>
      <td>${tipoBadge}</td>
      <td>${nomePessoa}</td>
      <td style="font-size:.82rem">${t.material||'—'}</td>
      <td>${t.placa||'—'}</td>
      <td>${t.motorista||'—'}</td>
      <td>${(t.pesoEntrada||0).toFixed(1)}</td>
      <td>${t.pesoTara>0?t.pesoTara.toFixed(1):'—'}</td>
      <td>${t.pesoLiquido>0?t.pesoLiquido.toFixed(1):'—'}</td>
      <td>${statusBadge}</td>
      <td>${finBtn}${delBtn}</td>
    </tr>`;
  }).join('');
}

function rodLimparFiltrosHist(){
  const el=document.getElementById('rodhist-forn'); if(el) el.value='';
  const mat=document.getElementById('rodhist-mat'); if(mat) mat.value='';
  const de=document.getElementById('rodhist-de'); if(de) de.value='';
  const ate=document.getElementById('rodhist-ate'); if(ate) ate.value='';
  rodRenderHistorico();
}














let _rodTicketVendaAtivo=null;

function rodEntrarModoMateriais(tid){
  _rodTicketVendaAtivo=tid;
  const fila=document.getElementById('rod-modo-fila');
  const modo=document.getElementById('rod-modo-materiais');
  if(fila) fila.style.display='none';
  if(modo) modo.style.display='flex';
  rodRenderMateriais();
  
  _rodAtualizarPeso(_rodPesoAtual||0);
}

function rodCancelarModoMateriais(){
  _rodTicketVendaAtivo=null;
  const fila=document.getElementById('rod-modo-fila');
  const modo=document.getElementById('rod-modo-materiais');
  if(fila) fila.style.display='';
  if(modo) modo.style.display='none';
}



function _rodUltimoPeso(t){
  if(!t) return 0;
  if(t._ultimoPesoBalanca!=null) return t._ultimoPesoBalanca;
  return parseFloat(t.pesoEntrada||0);
}

function rodRenderMateriais(){
  const tid=_rodTicketVendaAtivo;
  if(!tid) return;
  const t=TICKETS_DB[tid];
  if(!t) return;

  const taraBase=parseFloat(t.pesoEntrada||0);
  const ultimoPeso=_rodUltimoPeso(t);

  
  const infoEl=document.getElementById('rod-mat-ticket-info');
  if(infoEl) infoEl.innerHTML=
    `<b style="color:#fff;font-size:.85rem">${tid}</b> — <span style="color:#a5d6a7">${t.cliente||t.fornecedor||'—'}</span>`+
    ` <span style="font-size:.7rem;color:#555">·</span> ${t.placa||'—'}<br>`+
    `<span style="color:#888;font-size:.72rem">Tara base:</span> <b style="color:#ff9800">${taraBase.toFixed(1)} kg</b>`+
    (ultimoPeso!==taraBase?` &nbsp;·&nbsp; <span style="color:#888;font-size:.72rem">Último peso:</span> <b style="color:#ff9800">${ultimoPeso.toFixed(1)} kg</b>`:'');

  
  const elAnt=document.getElementById('rod-mat-peso-ant');
  if(elAnt) elAnt.textContent=ultimoPeso.toFixed(1)+' kg';
  const elAtual=document.getElementById('rod-mat-peso-atual');
  if(elAtual) elAtual.textContent=(_rodPesoAtual||0).toFixed(1); 
  
  const matInputEl2=document.getElementById('rod-mat-peso-input');
  if(matInputEl2&&!matInputEl2.value&&_rodPesoAtual>0) matInputEl2.value=(_rodPesoAtual).toFixed(1);
  
  const inputVal=parseFloat(matInputEl2?.value||0);
  const liqPrev=Math.max(0,inputVal>0?inputVal-ultimoPeso:(_rodPesoAtual||0)-ultimoPeso);
  const elLiq=document.getElementById('rod-mat-liquido-prev');
  if(elLiq){ elLiq.textContent=liqPrev.toFixed(1)+' kg'; elLiq.style.color=liqPrev>0?'#29b6f6':'#f44336'; }

  
  const lista=t.pesagens||[];
  const listaEl=document.getElementById('rod-mat-lista');
  if(listaEl){
    if(!lista.length){
      listaEl.innerHTML='<p style="color:#444;font-size:.75rem;font-style:italic;text-align:center;padding:8px 0">Nenhum material ainda<br><span style="font-size:.68rem">Coloque o caminhão carregado na balança e registre</span></p>';
    } else {
      listaEl.innerHTML=lista.map((p,i)=>`
        <div style="background:#0d0d0d;border:1px solid #1a3a1a;border-radius:6px;padding:6px 8px">
          <div style="display:flex;justify-content:space-between;align-items:center">
            <span style="font-size:.8rem;color:#c8e6c9;font-weight:700">${i+1}. ${p.material}</span>
            <button onclick="rodRemoverMaterial(${i})"
              style="font-size:.65rem;color:#c62828;background:none;border:none;cursor:pointer;padding:0 4px" title="Remover">✕</button>
          </div>
          <div style="font-size:.68rem;color:#555;margin-top:1px">
            ${p.pesoBrutoAcum.toFixed(1)} kg − ${p.pesoAnt.toFixed(1)} kg
          </div>
          <div style="font-size:.88rem;color:#69f0ae;font-weight:900;text-align:right">${p.pesoLiquido.toFixed(1)} kg</div>
        </div>`).join('');
    }
  }

  
  const totalEl=document.getElementById('rod-mat-total');
  if(totalEl){
    const total=lista.reduce((s,p)=>s+p.pesoLiquido,0);
    totalEl.innerHTML=lista.length
      ? `Total líquido: <b style="color:#fff">${total.toFixed(1)} kg</b> (${(total/1000).toFixed(3)} t) — ${lista.length} material(is)`
      : '';
  }
}

function rodAdicionarMaterial(){
  const tid=_rodTicketVendaAtivo;
  if(!tid){ showToast('Nenhum ticket ativo!','error'); return; }
  const t=TICKETS_DB[tid];
  if(!t){ showToast('Ticket não encontrado!','error'); return; }

  const nomeMat=(document.getElementById('rod-mat-nome')?.value||'').trim();
  if(!nomeMat){ showToast('Informe o nome do material!','error'); return; }

  
  const matInputEl=document.getElementById('rod-mat-peso-input');
  let pesoValMatInput=parseFloat(matInputEl?.value||0);
  
  if(!pesoValMatInput||pesoValMatInput<=0){
    pesoValMatInput=parseFloat(document.getElementById('rod-peso-manual')?.value||0);
  }
  if(pesoValMatInput>0) _rodAtualizarPeso(pesoValMatInput);

  const pesoBrutoAcum=_rodPesoAtual; 
  if(!pesoBrutoAcum||pesoBrutoAcum<=0){ showToast('Informe o peso atual na balança!','error'); return; }

  
  const pesoAnt=_rodUltimoPeso(t);
  const pesoLiquido=pesoBrutoAcum-pesoAnt;

  if(pesoLiquido<=0){
    showToast(
      '❌ O valor digitado ('+pesoBrutoAcum.toFixed(1)+' kg) deve ser o TOTAL na balança — caminhão + material.\n\n'+
      'O desconto atual é '+pesoAnt.toFixed(1)+' kg. Então o display da balança deve mostrar mais que isso.\n\n'+
      'Exemplo: se o caminhão vazio pesa '+pesoAnt.toFixed(0)+' kg e carregou '+
      (pesoAnt>0?(pesoAnt*0.3).toFixed(0):'5.000')+' kg, digite '+
      (pesoAnt>0?(pesoAnt*1.3).toFixed(0):(pesoAnt+5000).toFixed(0))+' kg.',
      'error', 9000
    );
    return;
  }

  if(!t.pesagens) t.pesagens=[];
  const reg={
    material:nomeMat,
    pesoBrutoAcum,   
    pesoAnt,          
    pesoLiquido,      
    tsRegistro:new Date().toLocaleString('pt-BR')
  };
  
  try{
    const fotos=rodCapturarAmbas();
    if(fotos?.cam1) reg.foto1=fotos.cam1;
    if(fotos?.cam2) reg.foto2=fotos.cam2;
  }catch(e){}
  t.pesagens.push(reg);

  
  t._ultimoPesoBalanca=pesoBrutoAcum;

  
  const nmEl=document.getElementById('rod-mat-nome');
  if(nmEl) nmEl.value='';
  
  if(matInputEl){ matInputEl.value=''; matInputEl._manualOverride=false; }
  
  const mpManEl=document.getElementById('rod-peso-manual');
  if(mpManEl) mpManEl.value='';
  
  _rodPesoAtual=0;
  const bigEl=document.getElementById('rod-peso-big');
  if(bigEl) bigEl.textContent='0.0';
  
  const elLiq=document.getElementById('rod-mat-liquido-prev');
  if(elLiq){ elLiq.textContent='0.0 kg'; elLiq.style.color='#29b6f6'; }

  saveDB();
  showToast('✅ '+nomeMat+': '+pesoLiquido.toFixed(1)+' kg registrado! ('+pesoBrutoAcum.toFixed(1)+' − '+pesoAnt.toFixed(1)+')','success',4000);
  rodRenderMateriais();
}

function rodRemoverMaterial(idx){
  const tid=_rodTicketVendaAtivo;
  if(!tid) return;
  const t=TICKETS_DB[tid];
  if(!t?.pesagens?.[idx]) return;
  if(!confirm('Remover "'+t.pesagens[idx].material+'"?\n\nAtenção: o peso acumulado será recalculado a partir da pesagem anterior.')) return;
  t.pesagens.splice(idx,1);
  
  if(t.pesagens.length){
    t._ultimoPesoBalanca=t.pesagens[t.pesagens.length-1].pesoBrutoAcum;
  } else {
    delete t._ultimoPesoBalanca; 
  }
  saveDB();
  rodRenderMateriais();
}

function rodFinalizarVendaMateriais(){
  const tid=_rodTicketVendaAtivo;
  if(!tid){ showToast('Nenhum ticket ativo!','error'); return; }
  const t=TICKETS_DB[tid];
  if(!t){ showToast('Ticket não encontrado!','error'); return; }

  if(!t.pesagens) t.pesagens=[];

  
  if(!t.pesagens.length){
    const matInputEl=document.getElementById('rod-mat-peso-input');
    const pesoAtualField=parseFloat(matInputEl?.value||0)||_rodPesoAtual||0;
    const taraBase=parseFloat(t.pesoEntrada||0);
    if(pesoAtualField>0 && pesoAtualField>taraBase){
      
      const nomeMat=(document.getElementById('rod-mat-nome')?.value||'').trim()||
                    (t.material||'Material');
      const liqAuto=pesoAtualField-taraBase;
      t.pesagens.push({
        material:nomeMat,
        pesoBrutoAcum:pesoAtualField,
        pesoAnt:taraBase,
        pesoLiquido:liqAuto,
        tsRegistro:new Date().toLocaleString('pt-BR')
      });
      t._ultimoPesoBalanca=pesoAtualField;
    } else {
      
      const taraStr=taraBase.toFixed(1);
      const corrente=pesoAtualField.toFixed(1);
      if(pesoAtualField>0 && pesoAtualField<=taraBase){
        showToast(
          '❌ Peso atual ('+corrente+' kg) deve ser MAIOR que a tara ('+taraStr+' kg).\n'+
          'O caminhão deve entrar VAZIO na 1ª pesagem e CARREGADO nas próximas.',
          'error', 8000
        );
      } else {
        showToast('Informe o peso atual na balança e clique "Registrar este Material" antes de finalizar.','error',5000);
      }
      return;
    }
  }

  const lista=t.pesagens;
  const totalLiquido=lista.reduce((s,p)=>s+p.pesoLiquido,0);
  const brutofinal=lista[lista.length-1].pesoBrutoAcum;

  t.pesoTara=parseFloat(t.pesoEntrada||0);
  t.pesoLiquido=totalLiquido;
  t._brutofinal=brutofinal;
  t._balFinalizado=true;
  t._rodSessao=false;
  t.status='Aguard. Preço';
  t.dataSaida=_hojeISO();
  t.tsSaida=new Date().toLocaleString('pt-BR');

  rodCancelarModoMateriais();
  saveDB();
  try{ fbSalvar(); }catch(e){}
  renderRodBalanca();

  showToast(
    '✅ Venda '+tid+' finalizada! '+lista.length+' material(is) — Total: '+totalLiquido.toFixed(1)+' kg ('+(totalLiquido/1000).toFixed(3)+' t)',
    'success', 7000
  );
  setTimeout(()=>{ try{ rodImprimirRomaneio(tid); }catch(e){} },400);
}


function rodExcluirTicketVenda(){
  const tid=_rodTicketVendaAtivo;
  if(!tid) return;
  const t=TICKETS_DB[tid];
  const nMat=(t?.pesagens||[]).length;
  const msg=nMat>0
    ? 'Excluir pesagem '+tid+'?\n\n'+nMat+' material(is) já registrado(s) será(ão) perdido(s).\n\nUse esta opção se a tara (1ª pesagem) foi registrada com valor errado.'
    : 'Cancelar e excluir pesagem '+tid+'?\n\nA tara registrada será removida e você poderá começar novamente.';
  if(!confirm(msg)) return;
  rodCancelarModoMateriais();
  _ticketExcluir(tid);
  saveDB();
  try{ fbSalvar(); }catch(e){}
  renderRodBalanca();
  showToast('🗑️ Pesagem '+tid+' excluída. Registre novamente com os valores corretos.','info',5000);
}








