function rodMatPreviewCompra(){
  if(!_rodTicketCompraAtivo) return;
  const t=TICKETS_DB[_rodTicketCompraAtivo];
  if(!t) return;
  const inputEl=document.getElementById('rod-matc-peso-input');
  const v=parseFloat(inputEl?.value||0);
  const ant=_rodUltimoPesoCompra(t);
  const liq=v>0 ? ant-v : 0; 
  const elLiq=document.getElementById('rod-matc-liquido-prev');
  if(elLiq){
    elLiq.textContent=(liq>0?liq:0).toFixed(1)+' kg';
    elLiq.style.color=liq>0?'#ffcc80':'#f44336';
  }
  const hintEl=document.getElementById('rod-matc-formula-hint');
  if(hintEl && v>0){
    if(liq>0){
      hintEl.textContent=ant.toFixed(0)+' − '+v.toFixed(0)+' = '+liq.toFixed(1)+' kg';
      hintEl.style.color='#555';
    } else {
      hintEl.textContent='⚠️ '+v.toFixed(0)+' deve ser MENOR que '+ant.toFixed(0)+' (caminhão deve ficar mais leve)';
      hintEl.style.color='#c62828';
    }
  } else if(hintEl){ hintEl.textContent=''; }
  const elAnt=document.getElementById('rod-matc-peso-ant');
  if(elAnt) elAnt.textContent=ant.toFixed(1)+' kg';
}

function rodMatUsarBalancaCompra(){
  const inputEl=document.getElementById('rod-matc-peso-input');
  if(inputEl){ inputEl.value=_rodPesoAtual.toFixed(1); inputEl._manualOverride=false; rodMatPreviewCompra(); }
}

function rodRenderMateriaisCompra(){
  const tid=_rodTicketCompraAtivo;
  if(!tid) return;
  const t=TICKETS_DB[tid];
  if(!t) return;

  const brutoBase=parseFloat(t.pesoEntrada||0);
  const ultimoPeso=_rodUltimoPesoCompra(t);

  const infoEl=document.getElementById('rod-matc-ticket-info');
  if(infoEl) infoEl.innerHTML=
    `<b style="color:#fff;font-size:.85rem">${tid}</b> — <span style="color:#ffcc80">${t.fornecedor||t.cliente||'—'}</span>`+
    ` · ${t.placa||'—'}<br>`+
    `<span style="color:#888;font-size:.72rem">Bruto entrada:</span> <b style="color:#ff9800">${brutoBase.toFixed(1)} kg</b>`+
    (ultimoPeso!==brutoBase?` · <span style="color:#888;font-size:.72rem">Último peso:</span> <b style="color:#ff9800">${ultimoPeso.toFixed(1)} kg</b>`:'');

  const elAnt=document.getElementById('rod-matc-peso-ant');
  if(elAnt) elAnt.textContent=ultimoPeso.toFixed(1)+' kg';
  const elAtual=document.getElementById('rod-matc-peso-atual');
  if(elAtual) elAtual.textContent=(_rodPesoAtual||0).toFixed(1);

  const inputEl=document.getElementById('rod-matc-peso-input');
  if(inputEl&&!inputEl.value&&_rodPesoAtual>0) inputEl.value=(_rodPesoAtual).toFixed(1);

  const inputVal=parseFloat(inputEl?.value||0);
  const liqPrev=inputVal>0?Math.max(0,ultimoPeso-inputVal):Math.max(0,ultimoPeso-(_rodPesoAtual||0));
  const elLiq=document.getElementById('rod-matc-liquido-prev');
  if(elLiq){ elLiq.textContent=liqPrev.toFixed(1)+' kg'; elLiq.style.color=liqPrev>0?'#ffcc80':'#f44336'; }

  const lista=t.pesagensCompra||[];
  const listaEl=document.getElementById('rod-matc-lista');
  if(listaEl){
    if(!lista.length){
      listaEl.innerHTML='<p style="color:#444;font-size:.75rem;font-style:italic;text-align:center;padding:8px 0">Nenhum material ainda<br><span style="font-size:.68rem">Descarregue o 1º material e registre o novo peso</span></p>';
    } else {
      listaEl.innerHTML=lista.map((p,i)=>`
        <div style="background:#0d0d0d;border:1px solid #3a1a0a;border-radius:6px;padding:6px 8px">
          <div style="display:flex;justify-content:space-between;align-items:center">
            <span style="font-size:.8rem;color:#ffe0b2;font-weight:700">${i+1}. ${p.material}</span>
            <button onclick="rodRemoverMaterialCompra(${i})"
              style="font-size:.65rem;color:#c62828;background:none;border:none;cursor:pointer;padding:0 4px" title="Remover">✕</button>
          </div>
          <div style="font-size:.68rem;color:#555;margin-top:1px">
            ${p.pesoAnt.toFixed(1)} kg − ${p.pesoBrutoAcum.toFixed(1)} kg
          </div>
          <div style="font-size:.88rem;color:#ffcc80;font-weight:900;text-align:right">${p.pesoLiquido.toFixed(1)} kg</div>
        </div>`).join('');
    }
  }

  const totalEl=document.getElementById('rod-matc-total');
  if(totalEl){
    const total=lista.reduce((s,p)=>s+p.pesoLiquido,0);
    totalEl.innerHTML=lista.length
      ? `Total líquido: <b style="color:#fff">${total.toFixed(1)} kg</b> (${(total/1000).toFixed(3)} t) — ${lista.length} material(is)`
      : '';
  }
}

function rodAdicionarMaterialCompra(){
  const tid=_rodTicketCompraAtivo;
  if(!tid){ showToast('Nenhum ticket ativo!','error'); return; }
  const t=TICKETS_DB[tid];
  if(!t){ showToast('Ticket não encontrado!','error'); return; }

  const nomeMat=(document.getElementById('rod-matc-nome')?.value||'').trim();
  if(!nomeMat){ showToast('Informe o nome do material!','error'); return; }

  const matInputEl=document.getElementById('rod-matc-peso-input');
  let pesoValInput=parseFloat(matInputEl?.value||0);
  if(!pesoValInput||pesoValInput<=0){
    pesoValInput=parseFloat(document.getElementById('rod-peso-manual')?.value||0);
  }
  if(pesoValInput>0) _rodAtualizarPeso(pesoValInput);

  const pesoBrutoAcum=_rodPesoAtual; 
  if(!pesoBrutoAcum||pesoBrutoAcum<=0){ showToast('Informe o peso atual na balança após descarregar!','error'); return; }

  const pesoAnt=_rodUltimoPesoCompra(t); 
  const pesoLiquido=pesoAnt-pesoBrutoAcum; 

  if(pesoLiquido<=0){
    showToast(
      '❌ O valor digitado ('+pesoBrutoAcum.toFixed(1)+' kg) deve ser MENOR que o peso anterior ('+pesoAnt.toFixed(1)+' kg).\n\n'+
      'O caminhão deve ficar mais leve após descarregar cada material.',
      'error', 7000
    );
    return;
  }

  if(!t.pesagensCompra) t.pesagensCompra=[];
  const reg={
    material:nomeMat,
    pesoBrutoAcum,  
    pesoAnt,        
    pesoLiquido,    
    tsRegistro:new Date().toLocaleString('pt-BR')
  };
  try{ const fotos=rodCapturarAmbas(); if(fotos?.cam1) reg.foto1=fotos.cam1; if(fotos?.cam2) reg.foto2=fotos.cam2; }catch(e){}
  t.pesagensCompra.push(reg);
  t._ultimoPesoBalancaCompra=pesoBrutoAcum; 

  
  const nmEl=document.getElementById('rod-matc-nome'); if(nmEl) nmEl.value='';
  if(matInputEl){ matInputEl.value=''; matInputEl._manualOverride=false; }
  const mpManEl=document.getElementById('rod-peso-manual'); if(mpManEl) mpManEl.value='';
  _rodPesoAtual=0;
  const bigEl=document.getElementById('rod-peso-big'); if(bigEl) bigEl.textContent='0.0';
  const elLiq=document.getElementById('rod-matc-liquido-prev'); if(elLiq){ elLiq.textContent='0.0 kg'; elLiq.style.color='#ffcc80'; }

  saveDB();
  _rodPersistirTicketCritico(tid);
  showToast('✅ '+nomeMat+': '+pesoLiquido.toFixed(1)+' kg ('+pesoAnt.toFixed(1)+' − '+pesoBrutoAcum.toFixed(1)+')','success',4000);
  rodRenderMateriaisCompra();
}

function rodRemoverMaterialCompra(idx){
  const tid=_rodTicketCompraAtivo; if(!tid) return;
  const t=TICKETS_DB[tid]; if(!t?.pesagensCompra?.[idx]) return;
  if(!confirm('Remover "'+t.pesagensCompra[idx].material+'"?')) return;
  t.pesagensCompra.splice(idx,1);
  if(t.pesagensCompra.length){
    t._ultimoPesoBalancaCompra=t.pesagensCompra[t.pesagensCompra.length-1].pesoBrutoAcum;
  } else {
    delete t._ultimoPesoBalancaCompra;
  }
  saveDB(); rodRenderMateriaisCompra();
}

function rodFinalizarCompraMateriais(){
  const tid=_rodTicketCompraAtivo;
  if(!tid){ showToast('Nenhum ticket ativo!','error'); return; }
  const t=TICKETS_DB[tid];
  if(!t){ showToast('Ticket não encontrado!','error'); return; }
  if(!t.pesagensCompra) t.pesagensCompra=[];

  
  if(!t.pesagensCompra.length){
    const matInputEl=document.getElementById('rod-matc-peso-input');
    const pesoAtualField=parseFloat(matInputEl?.value||0)||_rodPesoAtual||0;
    const brutoBase=parseFloat(t.pesoEntrada||0);
    if(pesoAtualField>0 && pesoAtualField<brutoBase){
      const nomeMat=(document.getElementById('rod-matc-nome')?.value||'').trim()||(t.material||'Material');
      const liqAuto=brutoBase-pesoAtualField;
      t.pesagensCompra.push({
        material:nomeMat, pesoBrutoAcum:pesoAtualField,
        pesoAnt:brutoBase, pesoLiquido:liqAuto,
        tsRegistro:new Date().toLocaleString('pt-BR')
      });
      t._ultimoPesoBalancaCompra=pesoAtualField;
    } else {
      showToast('Informe o peso atual e registre ao menos um material antes de finalizar.','error',5000);
      return;
    }
  }

  const lista=t.pesagensCompra;
  const totalLiquido=lista.reduce((s,p)=>s+p.pesoLiquido,0);
  const taraFinal=lista[lista.length-1].pesoBrutoAcum; 

  t.pesoEntrada=parseFloat(t.pesoEntrada||0); 
  t.pesoTara=taraFinal;                        
  t.pesoLiquido=totalLiquido;
  t._balFinalizado=true;
  t._rodSessao=false;
  t.status='Aguard. Preço';
  t.dataSaida=_hojeISO();
  t.tsSaida=new Date().toLocaleString('pt-BR');

  rodCancelarModoMateriaisCompra();
  saveDB();
  _rodPersistirTicketCritico(tid);
  renderRodBalanca();
  showToast('✅ Compra '+tid+' finalizada! '+lista.length+' material(is) — Total: '+totalLiquido.toFixed(1)+' kg','success',7000);
  setTimeout(()=>{ try{ rodImprimirRomaneio(tid); }catch(e){} },400);
}

function rodExcluirTicketCompra(){
  const tid=_rodTicketCompraAtivo; if(!tid) return;
  const t=TICKETS_DB[tid];
  const nMat=(t?.pesagensCompra||[]).length;
  const msg=nMat>0
    ? 'Excluir pesagem '+tid+'?\n\n'+nMat+' material(is) já registrado(s) será(ão) perdido(s).'
    : 'Cancelar e excluir pesagem '+tid+'?';
  if(!confirm(msg)) return;
  rodCancelarModoMateriaisCompra();
  _ticketExcluir(tid);
  saveDB(); try{ fbSalvar(); }catch(e){}
  renderRodBalanca();
  showToast('🗑️ Pesagem '+tid+' excluída.','info',4000);
}







let _rodStream1=null, _rodStream2=null;

async function rodIniciarCameras(){
  const cam1Id=localStorage.getItem('rod_cam1')||'';
  const cam2Id=localStorage.getItem('rod_cam2')||'';

  const marcarSemCamera=(msg)=>{
    const hint=document.getElementById('rod-no-cam-hint');
    if(hint){ hint.style.display='flex'; if(msg) hint.textContent='📷 '+msg; }
  };
  const atribuirStream=async(stream,videoId,wrapId)=>{
    const videoEl=document.getElementById(videoId);
    const wrapEl=document.getElementById(wrapId);
    if(!videoEl||!stream) return null;
    videoEl.srcObject=stream;
    try{ await videoEl.play(); }catch(_e){}
    if(wrapEl) wrapEl.style.display='flex';
    return stream;
  };
  const startCam=async(deviceId,videoId,wrapId)=>{
    const wrapEl=document.getElementById(wrapId);
    if(wrapEl) wrapEl.style.display='none';
    try{
      const constraints=deviceId?{video:{deviceId:{exact:deviceId}}}:{video:true};
      const stream=await navigator.mediaDevices.getUserMedia(constraints);
      return await atribuirStream(stream,videoId,wrapId);
    }catch(e){
      
      
      if(deviceId && (e.name==='OverconstrainedError'||e.name==='NotFoundError'||e.name==='DevicesNotFoundError')){
        try{
          const fallback=await navigator.mediaDevices.getUserMedia({video:true});
          return await atribuirStream(fallback,videoId,wrapId);
        }catch(e2){ e=e2; }
      }
      if(e.name==='NotAllowedError'||e.name==='SecurityError'||/permission denied/i.test(String(e.message||''))){
        console.warn('Câmera erro:',videoId,'Permission denied');
        marcarSemCamera('Permissão de câmera bloqueada. Libere a câmera para localhost e recarregue a página.');
      } else {
        console.warn('Câmera erro:',videoId,e.message||e);
      }
      return null;
    }
  };

  if(_rodStream1){_rodStream1.getTracks().forEach(t=>t.stop());_rodStream1=null;}
  if(_rodStream2){_rodStream2.getTracks().forEach(t=>t.stop());_rodStream2=null;}

  if(cam1Id) _rodStream1=await startCam(cam1Id,'rod-video-cam1','rod-cam1-wrap');
  if(cam2Id){
    if(cam1Id && cam2Id===cam1Id && _rodStream1){
      
      
      try{ _rodStream2=_rodStream1.clone(); await atribuirStream(_rodStream2,'rod-video-cam2','rod-cam2-wrap'); }
      catch(e){ _rodStream2=null; }
    } else {
      _rodStream2=await startCam(cam2Id,'rod-video-cam2','rod-cam2-wrap');
    }
  }

  const hint=document.getElementById('rod-no-cam-hint');
  if(hint && (_rodStream1||_rodStream2)) hint.style.display='none';
}

function rodCapturarFoto(videoId,canvasId){
  const video=document.getElementById(videoId);
  const canvas=document.getElementById(canvasId);
  if(!video||!canvas||!video.srcObject) return null;
  if(!video.videoWidth||!video.videoHeight) return null;
  canvas.width=video.videoWidth;
  canvas.height=video.videoHeight;
  canvas.getContext('2d').drawImage(video,0,0);
  return canvas.toDataURL('image/jpeg',0.72);
}


function rodCapturarAmbas(){
  return {
    cam1: rodCapturarFoto('rod-video-cam1','rod-canvas-cam1'),
    cam2: rodCapturarFoto('rod-video-cam2','rod-canvas-cam2')
  };
}

async function rodAbrirConfigCameras(){
  try{
    const permissaoStream=await navigator.mediaDevices.getUserMedia({video:true});
    const devices=await navigator.mediaDevices.enumerateDevices();
    try{ permissaoStream.getTracks().forEach(t=>t.stop()); }catch(_e){}
    const cams=devices.filter(d=>d.kind==='videoinput');
    const saved1=localStorage.getItem('rod_cam1')||'';
    const saved2=localStorage.getItem('rod_cam2')||'';
    const opts=cams.map(cam=>`<option value="${cam.deviceId}">${cam.label||('Câmera '+cam.deviceId.slice(0,14))}</option>`).join('');
    const noneOpt='<option value="">— Nenhuma —</option>';

    const modal=document.getElementById('modal-ov');
    const body=document.getElementById('modal-body');
    if(!modal||!body){showToast('Modal não encontrado','error');return;}

    body.innerHTML=`
      <h3>📷 Configurar Câmeras</h3>
      <div style="display:grid;gap:14px;margin-bottom:16px">
        <div class="fg">
          <label>Câmera 1 (Frente / Entrada)</label>
          <select id="cfg-cam1" style="width:100%;padding:8px;border:2px solid #1a3a2a;border-radius:7px;font-size:.88rem">
            ${noneOpt}${opts}
          </select>
        </div>
        <div class="fg">
          <label>Câmera 2 (Balança / Saída)</label>
          <select id="cfg-cam2" style="width:100%;padding:8px;border:2px solid #1a3a2a;border-radius:7px;font-size:.88rem">
            ${noneOpt}${opts}
          </select>
        </div>
      </div>
      <div class="modal-ft">
        <button class="btn-cancel" onclick="cm()">Cancelar</button>
        <button class="btn-save" onclick="
          const c1=document.getElementById('cfg-cam1')?.value||'';
          const c2=document.getElementById('cfg-cam2')?.value||'';
          localStorage.setItem('rod_cam1',c1);
          localStorage.setItem('rod_cam2',c2);
          cm();
          try{rodIniciarCameras();}catch(e){}
          showToast('Câmeras configuradas!','success');
        ">💾 Salvar</button>
      </div>`;
    document.getElementById('cfg-cam1').value=saved1;
    document.getElementById('cfg-cam2').value=saved2;
    modal.classList.add('open');
  }catch(e){
    if(e.name==='NotAllowedError'||e.name==='SecurityError'||/permission denied/i.test(String(e.message||''))){
      showToast('Permissão de câmera bloqueada no navegador. Libere a câmera para localhost e recarregue a página.','error',7000);
    } else {
      showToast('Erro ao acessar câmeras: '+e.message,'error');
    }
  }
}







