function _coordInitCanvas(){
  const canvas=document.getElementById('coord-sig-canvas');
  if(!canvas) return;
  const dpr=window.devicePixelRatio||1;
  canvas.style.height='160px';
  const w=canvas.offsetWidth||480;
  canvas.width=w*dpr; canvas.height=160*dpr;
  const ctx=canvas.getContext('2d');
  ctx.scale(dpr,dpr); ctx.strokeStyle='#111'; ctx.lineWidth=2.2; ctx.lineCap='round';
  ctx.clearRect(0,0,canvas.width,canvas.height);
  _coordSigCtx=ctx;
  let drawing=false;
  const pos=e=>{ const r=canvas.getBoundingClientRect(); const t=e.touches?e.touches[0]:e; return {x:(t.clientX-r.left),y:(t.clientY-r.top)}; };
  canvas.onmousedown=e=>{ drawing=true; const p=pos(e); ctx.beginPath(); ctx.moveTo(p.x,p.y); };
  canvas.onmousemove=e=>{ if(!drawing) return; const p=pos(e); ctx.lineTo(p.x,p.y); ctx.stroke(); };
  canvas.onmouseup=()=>drawing=false;
  canvas.ontouchstart=e=>{ e.preventDefault(); drawing=true; const p=pos(e); ctx.beginPath(); ctx.moveTo(p.x,p.y); };
  canvas.ontouchmove=e=>{ e.preventDefault(); if(!drawing) return; const p=pos(e); ctx.lineTo(p.x,p.y); ctx.stroke(); };
  canvas.ontouchend=()=>drawing=false;
}

function coordSigLimpar(){
  const canvas=document.getElementById('coord-sig-canvas');
  if(!canvas||!_coordSigCtx) return;
  _coordSigCtx.clearRect(0,0,canvas.width,canvas.height);
}

function _coordSigVazio(){
  const canvas=document.getElementById('coord-sig-canvas');
  if(!canvas) return true;
  const d=canvas.getContext('2d').getImageData(0,0,canvas.width,canvas.height).data;
  return !d.some(v=>v!==0);
}

function coordSigSalvar(){
  if(_coordSigVazio()){ showToast('Desenhe a assinatura antes de salvar.','error'); return; }
  const canvas=document.getElementById('coord-sig-canvas');
  const img=canvas.toDataURL('image/png');
  const hoje=new Date().toISOString().slice(0,10);

  if(_coordSigMode==='reuniao'){
    const reuId=_coordSigReuId;
    const mat=_coordSigMat;
    const r=REUNIOES_DB.find(x=>x.id===reuId);
    if(r){ if(!r.assinaturas) r.assinaturas={}; r.assinaturas[mat]={assinatura:img,assinadoEm:hoje}; }
    fbSalvar(); reuRender();
    
    coordSigFechar();
    reuAssinarModal(reuId);
    showToast('Assinatura salva! ✅','success');
    return;
  }
  if(_coordSigMode==='advertencia'){
    const a=ADVERTENCIAS_DB.find(x=>x.id===_coordSigAdvId);
    if(a){ a.assinatura=img; a.assinadoEm=hoje; }
    fbSalvar(); advRender();
  }
  coordSigFechar();
  showToast('Assinatura salva! ✅','success');
}

function coordSigFechar(){
  const modal=document.getElementById('coord-sig-modal');
  if(modal) modal.style.display='none';
  _coordSigMode=null; _coordSigReuId=null; _coordSigMat=null; _coordSigAdvId=null;
}



function coordFuncRender(){
  const funcs=(typeof FUNCIONARIOS!=='undefined'?FUNCIONARIOS:[]).filter(f=>f.status!=='inativo');
  const busca=(document.getElementById('coord-func-busca')?.value||'').toLowerCase().trim();

  
  const advCount={};
  (ADVERTENCIAS_DB||[]).forEach(a=>{ advCount[a.mat]=(advCount[a.mat]||0)+1; });

  
  const grafDiv=document.getElementById('coord-func-grafico');
  if(grafDiv){
    
    const sorted=[...funcs].sort((a,b)=>{
      const da=(advCount[a.mat]||0), db=(advCount[b.mat]||0);
      return db!==da ? db-da : (a.nome||'').localeCompare(b.nome||'');
    });
    const maxAdv=Math.max(1,...sorted.map(f=>advCount[f.mat]||0));

    if(!sorted.length){
      grafDiv.innerHTML='<div style="text-align:center;color:#aaa;padding:20px">Nenhum funcionário ativo.</div>';
    } else {
      grafDiv.innerHTML=sorted.map(f=>{
        const cnt=advCount[f.mat]||0;
        const pct=Math.round((cnt/maxAdv)*100);
        const obs=COORD_FUNC_OBS[f.mat];
        const av=obs?.avaliacao||'bom';
        const barCor=cnt===0?'#2e7d32':cnt<=2?'#f57f17':'#c62828';
        const badge=cnt===0
          ?'<span style="background:#e8f5e9;color:#2e7d32;border-radius:10px;padding:2px 8px;font-size:.72rem;font-weight:700">✅ Sem advertências</span>'
          :`<span style="background:#ffebee;color:#c62828;border-radius:10px;padding:2px 8px;font-size:.72rem;font-weight:700">⚠️ ${cnt} advertência${cnt>1?'s':''}</span>`;
        const avIcon={bom:'🟢',atencao:'🟡',critico:'🔴'}[av]||'🟢';
        return `<div style="display:flex;align-items:center;gap:10px;margin-bottom:7px">
          <span style="font-size:.82rem;min-width:160px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis" title="${esc(f.nome)}">${avIcon} ${esc(f.nome)}</span>
          <div style="flex:1;background:#e8eaf6;border-radius:6px;height:18px;overflow:hidden">
            <div style="width:${pct||2}%;height:100%;background:${barCor};border-radius:6px;transition:width .4s;min-width:${cnt>0?'18px':'0'}"></div>
          </div>
          <span style="min-width:90px;text-align:right">${badge}</span>
        </div>`;
      }).join('');
    }
  }

  
  const cardsDiv=document.getElementById('coord-func-cards');
  if(!cardsDiv) return;

  let lista=funcs;
  if(busca) lista=lista.filter(f=>(f.nome+f.cargo+f.mat).toLowerCase().includes(busca));

  if(!lista.length){ cardsDiv.innerHTML='<div style="text-align:center;color:#aaa;padding:30px;grid-column:1/-1">Nenhum funcionário encontrado.</div>'; return; }

  const avLabel={bom:'Bom desempenho',atencao:'Requer atenção',critico:'Situação crítica'};
  const avCor={bom:{bg:'#e8f5e9',bord:'#a5d6a7',txt:'#2e7d32'},atencao:{bg:'#fff8e1',bord:'#ffe082',txt:'#e65100'},critico:{bg:'#ffebee',bord:'#ef9a9a',txt:'#c62828'}};

  cardsDiv.innerHTML=lista.map(f=>{
    const cnt=advCount[f.mat]||0;
    const obs=COORD_FUNC_OBS[f.mat]||{};
    const av=obs.avaliacao||'bom';
    const cor=avCor[av]||avCor.bom;
    const ultimaAdv=(ADVERTENCIAS_DB||[]).filter(a=>a.mat===f.mat).sort((a,b)=>(b.data||'')>(a.data||'')?1:-1)[0];
    return `<div style="background:${cor.bg};border:2px solid ${cor.bord};border-radius:12px;padding:14px">
      <div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:8px">
        <div>
          <div style="font-weight:800;font-size:.88rem;color:#222">${esc(f.nome)}</div>
          <div style="font-size:.75rem;color:#777">${esc(f.cargo||'—')} · Mat. ${esc(f.mat||'?')}</div>
        </div>
        <span style="font-size:1.3rem" title="${avLabel[av]}">${{bom:'🟢',atencao:'🟡',critico:'🔴'}[av]}</span>
      </div>

      ${cnt>0?`<div style="font-size:.78rem;color:#c62828;font-weight:700;margin-bottom:4px">⚠️ ${cnt} advertência${cnt>1?'s':''}${ultimaAdv?' · última: '+(ultimaAdv.data||'').split('-').reverse().join('/'):''}
      </div>`:'<div style="font-size:.78rem;color:#2e7d32;margin-bottom:4px">✅ Sem advertências</div>'}

      <div style="margin-bottom:8px">
        <label style="font-size:.72rem;font-weight:700;color:#555;text-transform:uppercase;display:block;margin-bottom:3px">Status</label>
        <select onchange="coordFuncSalvarAv('${esc(f.mat)}',this.value)" style="width:100%;padding:6px;border:1.5px solid ${cor.bord};border-radius:6px;font-size:.82rem;background:#fff">
          <option value="bom"${av==='bom'?' selected':''}>🟢 Bom desempenho</option>
          <option value="atencao"${av==='atencao'?' selected':''}>🟡 Requer atenção</option>
          <option value="critico"${av==='critico'?' selected':''}>🔴 Situação crítica</option>
        </select>
      </div>

      <div style="margin-bottom:8px">
        <label style="font-size:.72rem;font-weight:700;color:#555;text-transform:uppercase;display:block;margin-bottom:3px">Observação do Coordenador</label>
        <textarea id="coord-fobs-${esc(f.mat)}" rows="2" placeholder="Anotações sobre o funcionário..."
          style="width:100%;padding:7px;border:1.5px solid ${cor.bord};border-radius:6px;font-size:.8rem;resize:vertical;box-sizing:border-box;font-family:inherit;background:#fff">${esc(obs.obs||'')}</textarea>
      </div>

      ${obs.atualizadoEm?`<div style="font-size:.72rem;color:#aaa;margin-bottom:6px">Atualizado em ${(obs.atualizadoEm||'').split('-').reverse().join('/')} por ${esc(obs.atualizadoPor||'?')}</div>`:''}

      <div style="display:flex;gap:6px;margin-top:4px">
        <button onclick="coordFuncSalvarObs('${esc(f.mat)}')" style="flex:1;padding:6px;background:#1565c0;color:#fff;border:none;border-radius:6px;font-weight:700;cursor:pointer;font-size:.8rem">💾 Salvar</button>
        <button onclick="coordImprimirFuncionario('${esc(f.mat)}')" style="padding:6px 12px;background:#2e7d32;color:#fff;border:none;border-radius:6px;font-weight:700;cursor:pointer;font-size:.8rem">🖨️</button>
      </div>
    </div>`;
  }).join('');
}

let _coordImpMat='';

function coordImprimirFuncionario(mat){
  const funcs=(typeof FUNCIONARIOS!=='undefined'?FUNCIONARIOS:[]);
  const f=funcs.find(x=>x.mat===mat);
  if(!f){ showToast('Funcionário não encontrado','warning'); return; }
  _coordImpMat=mat;
  const hoje=new Date().toISOString().slice(0,10);
  const body=document.getElementById('modal-body');
  body.className='modal';
  body.innerHTML=`
    <h3 style="margin:0 0 4px;color:#1565c0">🖨️ Imprimir Ficha — ${esc(f.nome)}</h3>
    <div style="font-size:.8rem;color:#888;margin-bottom:16px">Mat. ${esc(f.mat||'?')} · ${esc(f.cargo||'—')}</div>

    <div style="background:#f5f5f5;border-radius:8px;padding:12px;margin-bottom:14px">
      <div style="font-size:.78rem;font-weight:700;color:#555;text-transform:uppercase;margin-bottom:8px">📅 Período</div>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px">
        <div class="fg"><label>De</label><input type="date" id="cimp-de"></div>
        <div class="fg"><label>Até</label><input type="date" id="cimp-ate" value="${hoje}"></div>
      </div>
      <div style="font-size:.73rem;color:#aaa;margin-top:5px">Deixe em branco para incluir todos os registros.</div>
    </div>

    <div style="background:#f0f4ff;border-radius:8px;padding:12px;margin-bottom:18px">
      <div style="font-size:.78rem;font-weight:700;color:#555;text-transform:uppercase;margin-bottom:10px">📋 O que imprimir</div>
      <label style="display:flex;align-items:center;gap:8px;margin-bottom:8px;cursor:pointer">
        <input type="checkbox" id="cimp-obs" checked style="width:16px;height:16px">
        <span style="font-size:.88rem">📝 Observações do Coordenador</span>
      </label>
      <label style="display:flex;align-items:center;gap:8px;margin-bottom:8px;cursor:pointer">
        <input type="checkbox" id="cimp-adv" checked style="width:16px;height:16px">
        <span style="font-size:.88rem">⚠️ Advertências</span>
      </label>
      <label style="display:flex;align-items:center;gap:8px;cursor:pointer">
        <input type="checkbox" id="cimp-epi" checked style="width:16px;height:16px">
        <span style="font-size:.88rem">🗄️ Retiradas de EPI / Almoxarifado</span>
      </label>
    </div>

    <div class="modal-ft">
      <button class="btn-cancel" onclick="cm()">Cancelar</button>
      <button class="btn-save" onclick="coordExecutarImpressao()">🖨️ Imprimir</button>
    </div>`;
  document.getElementById('modal-ov').classList.add('open');
}

function coordExecutarImpressao(){
  const mat=_coordImpMat;
  const funcs=(typeof FUNCIONARIOS!=='undefined'?FUNCIONARIOS:[]);
  const f=funcs.find(x=>x.mat===mat);
  if(!f) return;
  const obs=(typeof COORD_FUNC_OBS!=='undefined'?COORD_FUNC_OBS:{})[mat]||{};
  const dtDe=document.getElementById('cimp-de')?.value||'';
  const dtAte=document.getElementById('cimp-ate')?.value||'';
  const incObs=document.getElementById('cimp-obs')?.checked;
  const incAdv=document.getElementById('cimp-adv')?.checked;
  const incEpi=document.getElementById('cimp-epi')?.checked;

  
  const esc2=s=>String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
  const hoje=new Date().toLocaleDateString('pt-BR');
  
  const brToISO=d=>{ if(!d)return''; const p=d.split('/'); return p.length===3?`${p[2]}-${p[1]}-${p[0]}`:d; };
  const inRange=(iso)=>{
    if(!iso) return true;
    if(dtDe && iso<dtDe) return false;
    if(dtAte && iso>dtAte) return false;
    return true;
  };

  const tipoLabel={verbal:'Verbal',escrita:'Escrita',suspensao:'Suspensão'};
  const avLabel={bom:'🟢 Bom desempenho',atencao:'🟡 Requer atenção',critico:'🔴 Situação crítica'};
  const av=avLabel[obs.avaliacao]||'🟢 Bom desempenho';

  
  const advsAll=(ADVERTENCIAS_DB||[]).filter(a=>a.mat===mat);
  const advsFilt=advsAll.filter(a=>inRange(a.data||'')).sort((a,b)=>(b.data||'')>(a.data||'')?1:-1);

  
  const alxAll=(typeof ALX_MOV!=='undefined'?ALX_MOV:[]).filter(m=>m.mat===mat);
  const alxFilt=alxAll.filter(m=>inRange(brToISO(m.data||''))).slice(0,200);

  const periodoTxt=(dtDe||dtAte)
    ?`Período: ${dtDe?dtDe.split('-').reverse().join('/'):'início'} até ${dtAte?dtAte.split('-').reverse().join('/'):'hoje'}`
    :'Período: todos os registros';

  
  let secoes='';

  if(incObs){
    secoes+=`<h2>📝 Observações do Coordenador</h2>
    <div class="obs-box">${esc2(obs.obs||'—')}</div>
    ${obs.atualizadoEm?`<div style="font-size:10px;color:#aaa;margin:-10px 0 14px">Atualizado em ${(obs.atualizadoEm||'').split('-').reverse().join('/')} por ${esc2(obs.atualizadoPor||'?')}</div>`:''}`;
  }

  if(incAdv){
    secoes+=`<h2>⚠️ Advertências (${advsFilt.length}${advsAll.length!==advsFilt.length?' no período de '+advsAll.length+' total':''})</h2>`;
    if(!advsFilt.length){
      secoes+='<p style="color:#888;font-style:italic">Nenhuma advertência no período.</p>';
    } else {
      secoes+=`<table>
        <thead><tr><th>Data</th><th>Tipo</th><th>Motivo</th><th>Descrição</th><th>Assinado</th></tr></thead>
        <tbody>${advsFilt.map(a=>`<tr>
          <td>${fmtDate(a.data)||''}</td>
          <td>${tipoLabel[a.tipo]||a.tipo}${a.tipo==='suspensao'&&a.dias?' ('+a.dias+'d)':''}</td>
          <td>${esc2(a.motivo)}</td>
          <td>${esc2(a.descricao||'—')}</td>
          <td>${a.assinatura?'✅ Sim':'⏳ Pendente'}</td>
        </tr>`).join('')}</tbody></table>`;
    }
  }

  if(incEpi){
    secoes+=`<h2>🗄️ Retiradas de EPI / Almoxarifado (${alxFilt.length}${alxAll.length!==alxFilt.length?' no período de '+alxAll.length+' total':''})</h2>`;
    if(!alxFilt.length){
      secoes+='<p style="color:#888;font-style:italic">Nenhuma retirada no período.</p>';
    } else {
      secoes+=`<table>
        <thead><tr><th>Data</th><th>Item / EPI</th><th>Tipo</th><th>Qtd</th><th>Obs</th></tr></thead>
        <tbody>${alxFilt.map(m=>`<tr>
          <td>${esc2(fmtDate(m.data)||'—')}</td>
          <td>${esc2(m.item||'—')}</td>
          <td>${m.tipo==='saida'?'Retirada':'Devolução'}</td>
          <td style="text-align:center">${m.qtd||0}</td>
          <td>${esc2(m.obs||'—')}</td>
        </tr>`).join('')}</tbody></table>`;
    }
  }

  cm();
  const w=window.open('','_blank','width=860,height=720');
  w.document.write(`<!DOCTYPE html><html><head><meta charset="utf-8">
  <title>Ficha — ${esc2(f.nome)}</title>
  <style>
    body{font-family:Arial,sans-serif;font-size:12px;color:#222;margin:0;padding:20px}
    .header{border-bottom:3px solid #1565c0;padding-bottom:10px;margin-bottom:16px}
    h1{font-size:17px;margin:0 0 3px;color:#1565c0}
    h2{font-size:13px;color:#333;margin:18px 0 6px;border-left:4px solid #1565c0;padding-left:8px;page-break-after:avoid}
    .info-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;background:#f5f5f5;padding:10px;border-radius:6px;margin-bottom:14px}
    .info-item label{display:block;font-size:10px;color:#777;text-transform:uppercase;font-weight:700}
    .info-item span{font-size:13px;font-weight:700}
    .obs-box{background:#fffde7;border:1px solid #ffe082;padding:10px;border-radius:6px;font-size:12px;margin-bottom:4px;min-height:40px}
    table{width:100%;border-collapse:collapse;margin-bottom:14px;font-size:11px}
    th{background:#1565c0;color:#fff;padding:5px 8px;text-align:left}
    td{padding:5px 8px;border-bottom:1px solid #ddd;vertical-align:top}
    tr:nth-child(even) td{background:#f9f9f9}
    .footer{margin-top:30px;border-top:1px solid #ccc;padding-top:12px;display:flex;gap:40px}
    .assin{flex:1;text-align:center}
    .assin-linha{border-top:1px solid #333;margin-top:40px;padding-top:4px;font-size:10px;color:#666}
    @media print{body{margin:0;padding:10px}}
  </style></head><body>
  <div class="header">
    <h1>📋 Ficha do Funcionário — ${_empresaPrincipalRazao()}</h1>
    <div style="font-size:11px;color:#666">Impresso em: ${hoje} &bull; ${periodoTxt}</div>
  </div>
  <div class="info-grid">
    <div class="info-item"><label>Nome</label><span>${esc2(f.nome)}</span></div>
    <div class="info-item"><label>Matrícula</label><span>${esc2(f.mat||'—')}</span></div>
    <div class="info-item"><label>Cargo</label><span>${esc2(f.cargo||'—')}</span></div>
    <div class="info-item"><label>Status</label><span>${f.status==='Inativo'?'Inativo':'Ativo'}</span></div>
    <div class="info-item"><label>Avaliação</label><span>${av}</span></div>
    <div class="info-item"><label>Total Advertências</label><span style="color:${advsAll.length>=3?'#c62828':advsAll.length>0?'#e65100':'#2e7d32'}">${advsAll.length}</span></div>
  </div>
  ${secoes}
  <div class="footer">
    <div class="assin"><div class="assin-linha">Coordenador(a)</div></div>
    <div class="assin"><div class="assin-linha">${esc2(f.nome)} — Funcionário(a)</div></div>
  </div>
  <script>window.onload=function(){window.print();}<\/script>
  </body></html>`);
  w.document.close();
}

function coordFuncSalvarAv(mat, avaliacao){
  if(!COORD_FUNC_OBS[mat]) COORD_FUNC_OBS[mat]={};
  COORD_FUNC_OBS[mat].avaliacao=avaliacao;
  COORD_FUNC_OBS[mat].atualizadoEm=new Date().toISOString().slice(0,10);
  COORD_FUNC_OBS[mat].atualizadoPor=(typeof cu!=='undefined'&&cu)?cu.name:'?';
  fbSalvar();
  coordFuncRender();
}

function coordFuncSalvarObs(mat){
  const ta=document.getElementById('coord-fobs-'+mat);
  const obs=(ta?.value||'').trim();
  if(!COORD_FUNC_OBS[mat]) COORD_FUNC_OBS[mat]={avaliacao:'bom'};
  COORD_FUNC_OBS[mat].obs=obs;
  COORD_FUNC_OBS[mat].atualizadoEm=new Date().toISOString().slice(0,10);
  COORD_FUNC_OBS[mat].atualizadoPor=(typeof cu!=='undefined'&&cu)?cu.name:'?';
  fbSalvar();
  showToast('Observação salva! ✅','success');
  coordFuncRender();
}

function alxSalvarItem(){
  const nome=(document.getElementById('alx-edit-nome')?.value||'').trim().toUpperCase();
  if(!nome){ showToast('Informe o nome do item!','error'); return; }
  const cat=(document.getElementById('alx-edit-cat')?.value||'').trim();
  const un=(document.getElementById('alx-edit-un')?.value||'un').trim();
  const tam=(document.getElementById('alx-edit-tam')?.value||'').trim();
  const qtd=parseFloat(document.getElementById('alx-edit-qtd')?.value)||0;
  const min=parseFloat(document.getElementById('alx-edit-min')?.value)||0;
  const preco=parseFloat(document.getElementById('alx-edit-preco')?.value)||0;
  const obs=(document.getElementById('alx-edit-obs')?.value||'').trim();

  const idxVal=document.getElementById('alx-edit-id')?.value;
  if(idxVal!=='' && idxVal!==undefined && idxVal!==null && ALX_ITENS[+idxVal]){
    const idx=+idxVal;
    ALX_ITENS[idx]={...ALX_ITENS[idx], nome, cat, un, tam, qtd, min, preco, obs};
    showToast('✅ Item atualizado!','success');
  } else {
    
    
    const _k=nome+'|'+String(tam).toUpperCase();
    const _ja=ALX_ITENS.findIndex(x=>x && (String(x.nome||'').trim().toUpperCase()+'|'+String(x.tam||'').trim().toUpperCase())===_k);
    if(_ja>=0){
      ALX_ITENS[_ja]={...ALX_ITENS[_ja], nome, cat, un, tam, qtd, min, preco, obs};
      showToast('Item já existia (mesmo nome e tamanho) — atualizei em vez de duplicar.','success');
    } else {
      const _nid=(typeof _syncAlxItens!=='undefined'&&_syncAlxItens.novoId)?_syncAlxItens.novoId():('AI'+Date.now().toString(36));
      ALX_ITENS.push({nome, cat, un, tam, qtd, min, preco, obs, id:_nid, ts:new Date().toISOString()});
      showToast('✅ Item cadastrado!','success');
    }
  }

  saveAlmoxa();
  alxFecharModal();
  alxRenderItens();
  _alxPopMovSel();
}

function alxSalvarMov(){
  const idxVal=document.getElementById('alx-mov-item')?.value;
  if(idxVal===''||idxVal===undefined||idxVal===null){ showToast('Selecione o item!','error'); return; }
  const idx=+idxVal;
  if(!ALX_ITENS[idx]){ showToast('Item não encontrado!','error'); return; }

  const tipo=document.getElementById('alx-mov-tipo')?.value||'entrada';
  const qtd=parseFloat(document.getElementById('alx-mov-qtd')?.value)||0;
  if(!qtd){ showToast('Informe a quantidade!','error'); return; }
  const data=document.getElementById('alx-mov-data')?.value||new Date().toISOString().slice(0,10);
  const respEl=document.getElementById('alx-mov-resp');
  const mat=(respEl?.value||'').trim();
  const resp=mat?((typeof FUNCIONARIOS!=='undefined'?FUNCIONARIOS:[]).find(f=>f.mat===mat)?.nome||mat):'';
  const obs=(document.getElementById('alx-mov-obs')?.value||'').trim();

  const before=parseFloat(ALX_ITENS[idx].qtd||0);
  if(tipo==='entrada') ALX_ITENS[idx].qtd=before+qtd;
  else ALX_ITENS[idx].qtd=Math.max(0,before-qtd);
  const after=parseFloat(ALX_ITENS[idx].qtd);

  ALX_MOV.unshift({
    item:ALX_ITENS[idx].nome, tipo, qtd, data, mat, resp, obs,
    before, after, ts:new Date().toISOString()
  });

  
  
  
  let _epiAuto=false;
  try{
    if(tipo!=='entrada' && mat && typeof EPI_DB!=='undefined'){
      const _nomeIt=String(ALX_ITENS[idx].nome||'');
      const _catIt=String(ALX_ITENS[idx].cat||'');
      const _norm=function(s){ return String(s||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,''); };
      let _ce=null;
      (typeof _EPI_CATALOGO!=='undefined'?_EPI_CATALOGO:[]).forEach(function(c){
        if(!_ce && (_norm(_nomeIt).indexOf(_norm(c.epi))>=0 || _norm(c.epi).indexOf(_norm(_nomeIt))>=0)) _ce=c;
      });
      
      const _palavrasEpi=['luva','capacete','bota','botina','oculos','mascara','protetor','auricular','abafador','avental','mangote','cinto de seguranca','colete','respirador','viseira','perneira','japona','epi'];
      const _nomeNorm=_norm(_nomeIt);
      const _ehEpiNome=_palavrasEpi.some(function(p){ return _nomeNorm.indexOf(p)>=0; });
      if(!_ce && _ehEpiNome){
        (typeof _EPI_CATALOGO!=='undefined'?_EPI_CATALOGO:[]).forEach(function(c){
          if(!_ce){ const cn=_norm(c.epi).split(' ')[0]; if(cn && _nomeNorm.indexOf(cn)>=0) _ce=c; }
        });
      }
      if(_ce || _ehEpiNome || _norm(_catIt).indexOf('epi')>=0){
        EPI_DB.push({
          id:'epi_'+Date.now()+Math.floor(Math.random()*1000),
          mat:mat,
          data:String(data).split('-').reverse().join('/'),
          epi:_nomeIt+(qtd>1?(' (x'+qtd+')'):''),
          atividade:_ce?_ce.atividade:'',
          risco:_ce?_ce.risco:'',
          ca:'',
          motivo:'Saída do almoxarifado'+(obs?(' — '+obs):'')
        });
        try{ saveEpi(); }catch(e){}
        try{ renderEpi(); }catch(e){}
        _epiAuto=true;
      }
    }
  }catch(e){}

  try{ alxRenderMovRecentes(); }catch(e){}

  ['alx-mov-qtd','alx-mov-resp','alx-mov-obs'].forEach(id=>{ const el=document.getElementById(id); if(el) el.value=''; });
  document.getElementById('alx-mov-item').value='';

  saveAlmoxa();
  alxRenderItens();
  _alxPopMovSel();
  showToast(_epiAuto?'✅ Movimentação registrada — e a entrega do EPI já foi pra aba EPI/NR-06!':'✅ Movimentação registrada!','success');
}

function alxRenderObs(){
  const el=document.getElementById('alx-obs-list');
  if(!el) return;
  if(!ALX_NOTAS.length){
    el.innerHTML='<div style="color:#aaa;font-style:italic;padding:10px">Nenhuma observação ainda.</div>';
    return;
  }
  el.innerHTML=ALX_NOTAS.slice().reverse().map((n,i)=>{
    return `<div style="background:#f9f9f9;border-left:4px solid #1a3a2a;border-radius:0 8px 8px 0;padding:10px 14px;margin-bottom:8px;font-size:.83rem">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:4px">
        <span style="font-weight:700;color:#1a3a2a">${esc(n.autor||'—')}</span>
        <span style="color:#aaa;font-size:.75rem">${n.data?n.data.split('-').reverse().join('/'):'—'}</span>
      </div>
      <div style="color:#333;white-space:pre-wrap">${esc(n.texto||'')}</div>
    </div>`;
  }).join('');
}

function alxSalvarObs(){
  const texto=(document.getElementById('alx-obs-texto')?.value||'').trim();
  if(!texto){ showToast('Escreva a observação!','error'); return; }
  const autor=(document.getElementById('alx-obs-autor')?.value||(typeof cu!=='undefined'&&cu?.name)||'—').trim();
  const data=new Date().toISOString().slice(0,10);
  ALX_NOTAS.push({texto, autor, data, ts:new Date().toISOString()});
  saveAlmoxa();
  document.getElementById('alx-obs-texto').value='';
  alxRenderObs();
  showToast('✅ Observação salva!','success');
}





let _chatConvAtiva = null;

function hdrAtualizarBadge(){
  
  
  
  try{
    const badge=document.getElementById('hdr-chat-badge');
    if(badge) badge.style.display='none';
  }catch(e){}
}

function hdrAbrirChat(){
  
  
  switchTab('chat');
  setTimeout(()=>{ try{ _chatAjustarAltura(); chatRenderConvs(); }catch(e){} },100);
}
window.addEventListener('resize',()=>{ try{ _chatAjustarAltura(); }catch(e){} });

function _chatAjustarAltura(){
  const container=document.getElementById('chat-container');
  if(!container) return;
  
  const rect=container.getBoundingClientRect();
  const h=Math.max(400, window.innerHeight - rect.top - 16);
  container.style.height=h+'px';
}

function chatRenderConvs(){
  const el=document.getElementById('chat-conv-list');
  if(!el) return;
  
  let html=`<div onclick="chatAbrirConv('geral')" style="padding:11px 14px;cursor:pointer;border-bottom:1px solid #eee;background:${_chatConvAtiva==='geral'?'#e8f5e9':'#fff'};font-size:.83rem;display:flex;gap:8px;align-items:center">
    <span style="font-size:1.1rem">💬</span>
    <div><div style="font-weight:700;color:#1a3a2a">Geral</div><div style="font-size:.7rem;color:#888">Todos os usuários</div></div>
  </div>`;
  
  Object.entries(USERS||{}).forEach(([k,u])=>{
    if(!u||!u.name) return;
    if(cu&&u.name===cu.name) return; 
    const convId='dm_'+[cu?cu.name:'',u.name].sort().join('__');
    const ativo=_chatConvAtiva===convId;
    const ini=(u.name||'?')[0].toUpperCase();
    html+=`<div onclick="chatAbrirConv('${convId}','${esc(u.name)}')" style="padding:10px 14px;cursor:pointer;border-bottom:1px solid #eee;background:${ativo?'#e8f5e9':'#fff'};font-size:.83rem;display:flex;gap:8px;align-items:center">
      <div style="width:30px;height:30px;border-radius:50%;background:#1a3a2a;color:#fff;display:flex;align-items:center;justify-content:center;font-weight:800;font-size:.78rem;flex-shrink:0">${ini}</div>
      <div style="overflow:hidden"><div style="font-weight:700;color:#1a3a2a;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${esc(u.name)}</div><div style="font-size:.68rem;color:#888">${esc(u.role||'')}</div></div>
    </div>`;
  });
  el.innerHTML=html;
  if(!_chatConvAtiva) chatAbrirConv('geral','Geral');
}

let _chatConvNome='Geral';
const _CHAT_PAGE_SIZE=60;
const _CHAT_HISTORY_BATCH=120;
const _CHAT_TEXT_PREVIEW=1800;
const _CHAT_TEXT_MAX=12000;
let _chatRenderLimit=_CHAT_PAGE_SIZE;
let _chatCarregandoHistorico=false;
let _chatTemMaisAntigas=true;
const _chatStorageUrlCache=new Map();

function _chatMsgConv(m){ return m&&m.conv?String(m.conv):'geral'; }
function _chatMsgTs(m){ const n=m&&m.ts?Date.parse(m.ts):0; return Number.isFinite(n)?n:0; }
function _chatMsgKey(m){ return m&&m._chatKey?String(m._chatKey):''; }
function _chatOrdenar(){
  CHAT_MSGS.sort(function(a,b){
    const ka=_chatMsgKey(a), kb=_chatMsgKey(b);
    if(ka&&kb&&ka!==kb) return ka<kb?-1:1;
    return _chatMsgTs(a)-_chatMsgTs(b);
  });
}
function _chatUpsertMensagem(msg){
  if(!msg) return false;
  const key=_chatMsgKey(msg);
  let idx=-1;
  if(key) idx=CHAT_MSGS.findIndex(function(x){ return _chatMsgKey(x)===key; });
  if(idx<0 && !key){
    idx=CHAT_MSGS.findIndex(function(x){
      return !x._chatKey && x.ts===msg.ts && x.autor===msg.autor && x.texto===msg.texto && _chatMsgConv(x)===_chatMsgConv(msg);
    });
  }
  if(idx>=0) CHAT_MSGS[idx]=msg;
  else CHAT_MSGS.push(msg);
  _chatOrdenar();
  return idx<0;
}
function _chatAttr(v){
  return String(v==null?'':v).replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
}
function _chatMensagensDaConversa(){
  return (typeof CHAT_MSGS!=='undefined'?CHAT_MSGS:[]).filter(function(m){
    return _chatMsgConv(m)===(_chatConvAtiva||'geral');
  });
}
function _chatResolverFotosStorage(area){
  const storage=window.__fbRaw&&window.__fbRaw.storage;
  if(!storage||!area) return;
  area.querySelectorAll('img[data-chat-storage-path]').forEach(function(img){
    const path=img.getAttribute('data-chat-storage-path');
    if(!path) return;
    const cached=_chatStorageUrlCache.get(path);
    if(cached){ img.src=cached; return; }
    if(img.dataset.loading==='1') return;
    img.dataset.loading='1';
    storage.ref(path).getDownloadURL().then(function(url){
      _chatStorageUrlCache.set(path,url);
      if(img.isConnected) img.src=url;
    }).catch(function(){
      if(img.isConnected){ img.alt='Imagem indisponível'; img.style.minHeight='0'; }
    }).finally(function(){ img.dataset.loading='0'; });
  });
}
function _chatFotoHtml(m){
  if(m&&m.imgPath){
    return '<img loading="lazy" decoding="async" data-chat-storage-path="'+_chatAttr(m.imgPath)+'" onclick="chatAbrirFoto(this.src)" style="max-width:220px;max-height:260px;min-height:70px;border-radius:10px;cursor:pointer;display:block;background:#eef2ee;'+(m.texto?'margin-bottom:5px':'')+'" title="Clique para ampliar" alt="Carregando imagem...">';
  }
  if(m&&m.img){
    return '<img loading="lazy" decoding="async" src="'+_chatAttr(m.img)+'" onclick="chatAbrirFoto(this.src)" style="max-width:220px;max-height:260px;border-radius:10px;cursor:pointer;display:block;'+(m.texto?'margin-bottom:5px':'')+'" title="Clique para ampliar">';
  }
  return '';
}
function _chatTextId(m){
  const k=_chatMsgKey(m)||String(_chatMsgTs(m))||Math.random().toString(36).slice(2);
  return 'chat-text-'+String(k).replace(/[^a-zA-Z0-9_-]/g,'_');
}
function _chatTextoHtml(m){
  const texto=String(m&&m.texto||'');
  if(!texto) return '';
  const id=_chatTextId(m);
  if(texto.length<=_CHAT_TEXT_PREVIEW){
    return '<div id="'+id+'" style="white-space:pre-wrap;overflow-wrap:anywhere;word-break:break-word">'+esc(texto)+'</div>';
  }
  return '<div id="'+id+'" data-chat-collapsed="1" style="white-space:pre-wrap;overflow-wrap:anywhere;word-break:break-word">'
    +esc(texto.slice(0,_CHAT_TEXT_PREVIEW))+'…</div>'
    +'<button type="button" data-chat-text-btn="1" onclick="chatToggleTexto(\''+_chatAttr(_chatMsgKey(m))+'\',this)" style="margin-top:6px;border:0;background:transparent;color:inherit;text-decoration:underline;font-size:.7rem;font-weight:800;cursor:pointer">Ver mensagem completa</button>';
}
function chatToggleTexto(key,btn){
  const msg=(CHAT_MSGS||[]).find(function(x){ return _chatMsgKey(x)===String(key||''); });
  if(!msg||!btn) return;
  const el=document.getElementById(_chatTextId(msg));
  if(!el) return;
  const aberto=btn.dataset.open==='1';
  if(aberto){
    el.textContent=String(msg.texto||'').slice(0,_CHAT_TEXT_PREVIEW)+'…';
    btn.dataset.open='0';
    btn.textContent='Ver mensagem completa';
  }else{
    el.textContent=String(msg.texto||'');
    btn.dataset.open='1';
    btn.textContent='Ver menos';
  }
}
window.chatToggleTexto=chatToggleTexto;
function _chatMensagemHtml(m,meuNome){
  const proprio=meuNome&&m.autor===meuNome;
  const align=proprio?'flex-end':'flex-start';
  const bg=proprio?'#1a3a2a':'#f0f4f0';
  const fg=proprio?'#fff':'#222';
  const ts=m.ts?new Date(m.ts).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'}):'';
  return '<div style="display:flex;justify-content:'+align+';margin-bottom:8px;content-visibility:auto;contain-intrinsic-size:72px">'
    +'<div style="max-width:72%;background:'+bg+';color:'+fg+';padding:9px 13px;border-radius:'+(proprio?'14px 14px 4px 14px':'14px 14px 14px 4px')+';font-size:.87rem;word-break:break-word;contain:layout paint style">'
    +(!proprio?'<div style="font-size:.7rem;font-weight:800;color:#1a5e2a;margin-bottom:3px">'+esc(m.autor||'—')+'</div>':'')
    +_chatFotoHtml(m)
    +_chatTextoHtml(m)
    +'<div style="font-size:.63rem;color:'+(proprio?'#9ec69a':'#bbb')+';text-align:right;margin-top:3px">'+ts+'</div>'
    +'</div></div>';
}

function chatAbrirConv(conv,nome){
  _chatConvAtiva=conv;
  _chatConvNome=nome||(conv==='geral'?'Geral':conv);
  _chatRenderLimit=_CHAT_PAGE_SIZE;
  _chatTemMaisAntigas=true;
  const hdr=document.getElementById('chat-header');
  if(hdr) hdr.textContent='💬 '+(conv==='geral'?'Chat Geral — todos os usuários':_chatConvNome);
  try{
    if(typeof window.__chatOpenConversationRealtime==='function'){
      window.__chatOpenConversationRealtime(conv,_CHAT_PAGE_SIZE);
    }else{
      chatRenderMsgs();
    }
  }catch(e){ chatRenderMsgs(); }
  chatRenderConvs();
}

function chatRenderMsgs(opcoes){
  const area=document.getElementById('chat-msgs-area');
  if(!area) return;
  _chatAjustarAltura();
  const opts=opcoes||{};
  const msgs=_chatMensagensDaConversa();
  if(!msgs.length){
    area.innerHTML='<div style="color:#aaa;text-align:center;font-size:.85rem;margin-top:40px">Nenhuma mensagem ainda. Diga olá! 👋</div>';
    return;
  }
  const oldHeight=area.scrollHeight;
  const oldTop=area.scrollTop;
  const inicio=Math.max(0,msgs.length-_chatRenderLimit);
  const visiveis=msgs.slice(inicio);
  const temMaisLocal=inicio>0;
  const meuNome=cu&&cu.name;
  let html='';
  if(temMaisLocal||_chatTemMaisAntigas){
    html='<div style="text-align:center;padding:6px 0 12px">'
      +'<button type="button" onclick="chatCarregarAnteriores()" '+(_chatCarregandoHistorico?'disabled':'')+' style="border:1px solid #c8d6cc;background:#fff;color:#1a3a2a;border-radius:16px;padding:6px 14px;font-size:.72rem;font-weight:700;cursor:pointer">'
      +(_chatCarregandoHistorico?'Carregando...':'↑ Carregar mensagens anteriores')+'</button></div>';
  }
  html+=visiveis.map(function(m){ return _chatMensagemHtml(m,meuNome); }).join('');
  area.innerHTML=html;
  _chatResolverFotosStorage(area);
  if(opts.preservarScroll) area.scrollTop=Math.max(0,area.scrollHeight-oldHeight+oldTop);
  else area.scrollTop=area.scrollHeight;
}

async function chatCarregarAnteriores(){
  if(_chatCarregandoHistorico) return;
  const atuais=_chatMensagensDaConversa();
  if(atuais.length>_chatRenderLimit){
    _chatRenderLimit+=_CHAT_PAGE_SIZE;
    chatRenderMsgs({preservarScroll:true});
    return;
  }
  if(!_chatTemMaisAntigas||!window._fbDB) return;
  _chatCarregandoHistorico=true;
  window.__CHAT_HISTORY_LOADING__=true;
  chatRenderMsgs({preservarScroll:true});
  try{
    const alvo=Math.max(_CHAT_PAGE_SIZE,atuais.length)+_CHAT_HISTORY_BATCH;
    if(typeof window.__chatLoadConversationHistory==='function'){
      const info=await window.__chatLoadConversationHistory(_chatConvAtiva||'geral',alvo);
      if(info&&info.hasMore===false) _chatTemMaisAntigas=false;
      _chatRenderLimit=Math.max(_chatRenderLimit,alvo);
    }else{
      _chatTemMaisAntigas=false;
    }
  }catch(e){
    showToast('Não consegui carregar mensagens anteriores.','error');
  }finally{
    _chatCarregandoHistorico=false;
    window.__CHAT_HISTORY_LOADING__=false;
    chatRenderMsgs({preservarScroll:true});
  }
}
window.chatCarregarAnteriores=chatCarregarAnteriores;
window.__chatUpsertMensagem=_chatUpsertMensagem;

const _CHAT_EMOJIS='😀 😁 😂 🤣 😊 🙂 😉 😍 😘 😎 🤩 🥳 😇 🤔 😴 😅 😭 😢 😡 😱 😴 🤗 🙌 👏 👍 👎 👌 🙏 💪 🤝 👋 🫶 ✅ ❌ ⚠️ ❤️ 🧡 💛 💚 💙 💜 🔥 ⭐ ✨ 🎉 🎊 💰 💵 💸 🧾 📦 🚛 🏭 🛒 📅 ⏰ 📌 📎 ☕ 🍀 😂'.split(' ').filter(function(v,i,a){return v && a.indexOf(v)===i;});
function chatToggleEmojis(){
  const p=document.getElementById('chat-emoji-panel'); if(!p) return;
  if(!p.dataset.built){ p.innerHTML=_CHAT_EMOJIS.map(function(e){return '<span style="cursor:pointer;padding:2px 5px;display:inline-block;border-radius:6px" onmouseover="this.style.background=&#39;#eee&#39;" onmouseout="this.style.background=&#39;transparent&#39;" onclick="chatInsertEmoji(&#39;'+e+'&#39;)">'+e+'</span>';}).join(''); p.dataset.built='1'; }
  p.style.display=(p.style.display==='none'||!p.style.display)?'block':'none';
}
function chatInsertEmoji(e){
  const inp=document.getElementById('chat-input'); if(!inp) return;
  const s=(inp.selectionStart!=null?inp.selectionStart:inp.value.length);
  const en=(inp.selectionEnd!=null?inp.selectionEnd:inp.value.length);
  inp.value=inp.value.slice(0,s)+e+inp.value.slice(en);
  inp.focus();
  const pos=s+e.length; try{ inp.setSelectionRange(pos,pos); }catch(_){}
}
function chatKeyDown(e){
  if(e.key==='Enter'&&!e.shiftKey){ e.preventDefault(); chatEnviar(); }
}

let _chatFotoPendente=null;
function chatEscolherFoto(){
  const inp=document.getElementById('chat-img-input');
  if(inp){ inp.value=''; inp.click(); }
}
function chatCarregarFoto(inputEl){
  const file=inputEl&&inputEl.files&&inputEl.files[0];
  if(!file) return;
  if(!/^image\//.test(file.type)){ showToast('Selecione uma imagem.','error'); return; }
  const reader=new FileReader();
  reader.onload=function(ev){
    const img=new Image();
    img.onload=function(){
      try{
        const MAX=1200;
        let w=img.width,h=img.height;
        if(w>MAX||h>MAX){ if(w>=h){ h=Math.round(h*MAX/w); w=MAX; } else { w=Math.round(w*MAX/h); h=MAX; } }
        const cv=document.createElement('canvas'); cv.width=w; cv.height=h;
        const ctx=cv.getContext('2d');
        ctx.fillStyle='#fff'; ctx.fillRect(0,0,w,h); ctx.drawImage(img,0,0,w,h);
        const data=cv.toDataURL('image/jpeg',0.72);
        if(data.length>6.5*1024*1024){ showToast('A imagem ficou grande demais. Escolha uma foto menor.','error'); return; }
        _chatFotoPendente=data;
        _chatRenderPreviewFoto();
      }catch(e){ showToast('Não consegui preparar a imagem.','error'); }
    };
    img.onerror=function(){ showToast('Arquivo de imagem inválido.','error'); };
    img.src=ev.target.result;
  };
  reader.onerror=function(){ showToast('Não consegui ler o arquivo.','error'); };
  reader.readAsDataURL(file);
}
function _chatRenderPreviewFoto(){
  const box=document.getElementById('chat-foto-preview');
  if(!box) return;
  if(!_chatFotoPendente){ box.style.display='none'; box.innerHTML=''; return; }
  box.style.display='block';
  box.innerHTML='<div style="display:inline-flex;align-items:flex-start;gap:6px;background:#fff;border:1.5px solid #ccc;border-radius:10px;padding:6px">'
    +'<img src="'+_chatFotoPendente+'" style="max-width:90px;max-height:90px;border-radius:6px;display:block">'
    +'<button type="button" onclick="chatCancelarFoto()" title="Remover foto" style="background:#c0392b;color:#fff;border:none;border-radius:50%;width:24px;height:24px;font-weight:800;cursor:pointer;line-height:1">×</button>'
    +'</div>';
}
function chatCancelarFoto(){ _chatFotoPendente=null; _chatRenderPreviewFoto(); }
function chatAbrirFoto(src){
  if(!src) return;
  const ov=document.createElement('div');
  ov.style.cssText='position:fixed;inset:0;background:rgba(0,0,0,.85);z-index:99999;display:flex;align-items:center;justify-content:center;padding:20px;cursor:zoom-out';
  ov.onclick=function(){ ov.remove(); };
  const im=document.createElement('img');
  im.src=src; im.style.cssText='max-width:95%;max-height:95%;border-radius:8px;box-shadow:0 6px 30px rgba(0,0,0,.5)';
  ov.appendChild(im); document.body.appendChild(ov);
}
function _chatSafeSegment(v){ return String(v||'geral').replace(/[^a-zA-Z0-9._-]+/g,'_').slice(0,120)||'geral'; }
async function _chatUploadFoto(dataUrl,conv){
  const storage=window.__fbRaw&&window.__fbRaw.storage;
  if(!storage) throw new Error('Firebase Storage indisponível.');
  const path='erp-files/chat/'+_chatSafeSegment(conv)+'/'+Date.now()+'_'+Math.random().toString(36).slice(2,10)+'.jpg';
  const ref=storage.ref(path);
  await ref.putString(dataUrl,'data_url',{contentType:'image/jpeg',cacheControl:'private,max-age=3600'});
  return path;
}

async function chatEnviar(){
  const input=document.getElementById('chat-input');
  const texto=(input&&input.value||'').trim();
  const foto=_chatFotoPendente;
  if(!texto&&!foto) return;
  if(texto.length>_CHAT_TEXT_MAX){
    showToast('Mensagem muito grande. Limite: '+_CHAT_TEXT_MAX.toLocaleString('pt-BR')+' caracteres.','error',7000);
    return;
  }
  if(typeof cu==='undefined'||!cu){ showToast('Faça login primeiro!','error'); return; }
  const conv=_chatConvAtiva||'geral';
  const msg={
    autor:cu.name||'Usuário',
    autorLogin:(typeof cuKey!=='undefined'?String(cuKey||''):''),
    texto:texto,
    ts:new Date().toISOString(),
    conv:conv
  };
  if(input) input.value='';
  _chatFotoPendente=null;
  _chatRenderPreviewFoto();
  try{
    if(foto) msg.imgPath=await _chatUploadFoto(foto,conv);
    const ref=firebase.database().ref('erp/chat').push();
    const local=Object.assign({_chatKey:ref.key},msg);
    _chatUpsertMensagem(local);
    chatRenderMsgs();
    await ref.set(msg);
  }catch(e){
    if(texto&&input&&!input.value) input.value=texto;
    if(foto&&!_chatFotoPendente){ _chatFotoPendente=foto; _chatRenderPreviewFoto(); }
    showToast('Não consegui enviar a mensagem'+(foto?' ou a imagem':'')+'. Tente novamente.','error');
  }
}

function _chatMsgsFromRemote(dChat){
  if(!dChat) return [];
  let arr=[];
  if(Array.isArray(dChat)){
    arr=dChat.map(function(v,i){ return v&&typeof v==='object'?Object.assign({_chatKey:String(i)},v):v; });
  }else if(typeof dChat==='object'){
    arr=Object.entries(dChat).map(function(entry){
      const k=entry[0],v=entry[1];
      return v&&typeof v==='object'?Object.assign({_chatKey:k},v):null;
    });
  }
  return arr.filter(Boolean).sort(function(a,b){
    const ka=_chatMsgKey(a),kb=_chatMsgKey(b);
    if(ka&&kb&&ka!==kb) return ka<kb?-1:1;
    return _chatMsgTs(a)-_chatMsgTs(b);
  });
}




let _impDbKey = null;




function _atualizarDicaScroll(tbodyId, dicaId){
  const tbody=document.getElementById(tbodyId);
  const dica=document.getElementById(dicaId);
  if(!tbody||!dica) return;
  const wrapper=tbody.closest('div');
  if(!wrapper) return;
  dica.style.display = wrapper.scrollHeight > wrapper.clientHeight + 2 ? 'block' : 'none';
}

function csAbrirImpureza(dbKey){
  const t=TICKETS_DB[dbKey];
  if(!t){ showToast('Ticket não encontrado.','error'); return; }
  _impDbKey=dbKey;
  const modal=document.getElementById('modal-impureza');
  if(!modal) return;
  const titulo=document.getElementById('imp-titulo');
  
  
  
  
  
  
  
  const info=document.getElementById('imp-info');
  if(titulo) titulo.textContent='✏️ Editar Preço/kg e Impureza — Ticket '+(t.ticket||dbKey);
  if(info) info.innerHTML=`<b>Fornecedor:</b> ${esc(t.fornecedor||'—')} &nbsp;|&nbsp; <b>Data:</b> ${(t.criadoEm||'').slice(0,10)}`;
  const tbody=document.getElementById('imp-itens-body');
  if(!tbody) return;
  const itens=t.itens||[];
  tbody.innerHTML=itens.length===0
    ?'<tr><td colspan="7" style="text-align:center;color:#aaa">Nenhum item no ticket</td></tr>'
    :itens.map((it,i)=>{
      
      
      
      
      
      const bruto=Number(it.pesoBruto!=null?it.pesoBruto:(it.br||0));
      const liqOrig=Number(it.pesoLiq!=null?it.pesoLiq:(it.lq!=null?it.lq:bruto));
      const imp=Number(it.impureza||0);
      const liqAjust=Math.max(liqOrig-imp,0);
      const preco=Number(it.preco||0);
      return `<tr>
      <td style="font-size:.82rem">${esc(it.mat||'—')}</td>
      <td style="text-align:right">${bruto.toFixed(3)}</td>
      <td style="text-align:right" id="imp-liqorig-${i}">${liqOrig.toFixed(3)}</td>
      <td style="text-align:center"><input type="number" id="imp-imp-${i}" value="${imp}" min="0" step="0.001"
        oninput="csRecalcRow(${i},${liqOrig})"
        style="width:80px;padding:4px;border:1px solid #ccc;border-radius:5px;text-align:right"></td>
      <td style="text-align:right" id="imp-liq-${i}">${liqAjust.toFixed(3)}</td>
      <td style="text-align:right"><input type="number" id="imp-preco-${i}" value="${preco}" min="0" step="0.01"
        oninput="csRecalcRow(${i},${liqOrig})" title="Corrigir o preço por kg desta linha"
        style="width:90px;padding:4px;border:1.5px solid #f0a500;border-radius:5px;text-align:right;background:#fff8e1"></td>
      <td style="text-align:right;font-weight:700" id="imp-tot-${i}">R$ ${(liqAjust*preco).toLocaleString('pt-BR',{minimumFractionDigits:2})}</td>
    </tr>`;
    }).join('');
  modal.style.display='flex';
  setTimeout(()=>_atualizarDicaScroll('imp-itens-body','imp-scroll-dica'),0);
}

function csRecalcRow(i,liqOrig,preco){
  const impEl=document.getElementById('imp-imp-'+i);
  const liqEl=document.getElementById('imp-liq-'+i);
  const totEl=document.getElementById('imp-tot-'+i);
  const precoEl=document.getElementById('imp-preco-'+i);
  if(!impEl) return;
  const imp=parseFloat(impEl.value)||0;
  
  
  if(precoEl){ const _p=parseFloat(precoEl.value); if(!isNaN(_p)) preco=_p; }
  
  
  
  const liqAjust=Math.max(liqOrig-imp,0);
  if(liqEl) liqEl.textContent=liqAjust.toFixed(3);
  if(totEl) totEl.textContent='R$ '+(liqAjust*preco).toLocaleString('pt-BR',{minimumFractionDigits:2});
}

function csAplicarGlobal(){
  
  const gEl=document.getElementById('imp-global-pct');
  if(!gEl) return;
  const val=parseFloat(gEl.value)||0;
  const t=TICKETS_DB[_impDbKey];
  if(!t||!t.itens) return;
  t.itens.forEach((it,i)=>{
    const el=document.getElementById('imp-imp-'+i);
    if(el){
      el.value=val;
      const bruto=Number(it.pesoBruto!=null?it.pesoBruto:(it.br||0));
      const liqOrig=Number(it.pesoLiq!=null?it.pesoLiq:(it.lq!=null?it.lq:bruto));
      csRecalcRow(i,liqOrig,Number(it.preco||0));
    }
  });
}

function csFecharImpureza(){
  const modal=document.getElementById('modal-impureza');
  if(modal) modal.style.display='none';
  _impDbKey=null;
}

function csSalvarImpureza(){
  const t=TICKETS_DB[_impDbKey];
  if(!t||!t.itens){ showToast('Erro: ticket não encontrado.','error'); return; }
  let totalKg=0;
  t.itens.forEach((it,i)=>{
    const impEl=document.getElementById('imp-imp-'+i);
    const imp=impEl?parseFloat(impEl.value)||0:it.impureza||0;
    
    const precoEl=document.getElementById('imp-preco-'+i);
    if(precoEl){ const _p=parseFloat(precoEl.value); if(!isNaN(_p)&&_p>=0) it.preco=_p; }
    const bruto=Number(it.pesoBruto!=null?it.pesoBruto:(it.br||0));
    const liqOrig=Number(it.pesoLiq!=null?it.pesoLiq:(it.lq!=null?it.lq:bruto));
    const liqAjust=Math.max(liqOrig-imp,0);
    it.impureza=imp;
    it.pesoLiqAjust=liqAjust;
    totalKg+=liqAjust;
  });
  t.totalKgAjust=totalKg;
  
  
  
  
  t.totalGeral=t.itens.reduce(function(s,it){
    const liq=Number(it.pesoLiqAjust!=null?it.pesoLiqAjust:(it.pesoLiq!=null?it.pesoLiq:(it.pesoBruto||0)));
    const preco=Number(it.preco||0);
    const tot=_r2(liq*preco);
    it.total=tot; 
    return s+tot;
  },0) + Number(t.acrescimo||0);
  t.totalGeral=_r2(t.totalGeral);
  
  
  
  
  var _cpTk=CONTAS_PAGAR.find(function(cp){ return cp.ticket===t.ticket && cp.status!=='Pago'; });
  var _jaPagoCP=_cpTk?Number(_cpTk.valorPago||0):0;
  t.saldoPagar=_r2(Number(t.totalGeral||0) - Number(t.adiantamento||0) + Number(t.saldoAnterior||0) - _jaPagoCP);
  if(t.saldoPagar<0) t.saldoPagar=0;
  try{
    if(_cpTk){
      _cpTk.valor=Math.max(t.saldoPagar,0);
      if(_cpTk.valor<=0.01){ _cpTk.status='Pago'; if(!_cpTk.dataPgto) _cpTk.dataPgto=t.data||''; }
      _cpTk._upd=Date.now();
      saveContasPagar();
      try{ renderContasPagar(); }catch(e){}
    }
  }catch(e){}
  
  
  
  
  
  
  
  saveDB();
  csFecharImpureza();
  showToast('Desconto salvo! Valor e saldo recalculados.','success');
  try{ renderComprasSucata(); }catch(e){}
  try{ renderTickets(); }catch(e){}
}




function _rodGetHistoricoExport(){
  
  
  
  
  try{
    const atual=_rodGetHistorico();
    if(Array.isArray(atual)&&atual.length){
      return atual.map(function(item){ return Array.isArray(item)?item[1]:item; }).filter(Boolean);
    }
  }catch(e){}
  if(typeof ROD_HISTORICO!=='undefined'&&ROD_HISTORICO.length) return ROD_HISTORICO;
  try{
    const s=localStorage.getItem('mm_rod_hist');
    if(s) return JSON.parse(s);
  }catch(e){}
  return [];
}

