function fiscalToggleParcelamento(){
  const tipo=document.getElementById('ns-tipo')?.value||'';
  const box=document.getElementById('ns-parcelas-box');
  if(!box) return;
  const mostra=['Despesa','Imposto','Folha','Outros'].includes(tipo);
  box.style.display=mostra?'':'none';
  if(mostra) fiscalPreviewParcelas();
}

function fiscalPreviewParcelas(){
  const nparc=parseInt(document.getElementById('ns-nparc')?.value)||1;
  const venc1=document.getElementById('ns-venc1')?.value||'';
  const div=document.getElementById('ns-parc-preview');
  if(!div) return;
  if(nparc<=1){ div.innerHTML='<span style="color:#2e7d32">✅ Pagamento à vista — 1 lançamento em Contas a Pagar</span>'; return; }
  if(!venc1){ div.innerHTML='<span style="color:#aaa">Informe o vencimento da 1ª parcela para ver o preview.</span>'; return; }
  const [y,m,d]=venc1.split('-').map(Number);
  const rows=Array.from({length:nparc},(_,i)=>{
    let mi=m+i, ai=y+Math.floor((mi-1)/12); mi=((mi-1)%12)+1;
    const dv=Math.min(d,new Date(ai,mi,0).getDate());
    const fmt=String(dv).padStart(2,'0')+'/'+String(mi).padStart(2,'0')+'/'+ai;
    return `<div style="display:flex;gap:12px;padding:3px 0;border-bottom:1px solid #f0e0cc">
      <span style="min-width:60px;color:#e67e22;font-weight:700">${i+1}/${nparc}</span>
      <span>Vence: <b>${fmt}</b></span>
      <span style="margin-left:auto;color:#888">Valor: calculado ao salvar</span>
    </div>`;
  }).join('');
  div.innerHTML=rows;
}

function fiscalSalvarSaida(){
  const itens=_fiscalColetarItens('ns');
  if(!itens.length){alert('Adicione ao menos um item!');return;}
  const chave=fiscalChave();
  if(!FISCAL_DB[chave]) FISCAL_DB[chave]={entradas:[],saidas:[],impostos:{}};
  if(!Array.isArray(FISCAL_DB[chave].saidas)) FISCAL_DB[chave].saidas=[];
  const dataV=document.getElementById('ns-data')?.value||'';
  const tipo=document.getElementById('ns-tipo')?.value||'Saída';
  const cli=document.getElementById('ns-cli')?.value||'';
  const num=document.getElementById('ns-num')?.value||'';
  const valorTotal=itens.reduce((s,it)=>s+it.valor,0);

  const tiposParcelavel=['Despesa','Imposto','Folha','Outros'];
  const nparc=tiposParcelavel.includes(tipo)?parseInt(document.getElementById('ns-nparc')?.value||'1'):1;
  const venc1=document.getElementById('ns-venc1')?.value||'';
  const cat=(document.getElementById('ns-cat')?.value||'Serviços').trim();

  let parcelas=[];
  if(tiposParcelavel.includes(tipo) && nparc>1 && venc1){
    const [y,m,d]=venc1.split('-').map(Number);
    const valorParcela=parseFloat((valorTotal/nparc).toFixed(2));
    for(let i=0;i<nparc;i++){
      let mi=m+i, ai=y+Math.floor((mi-1)/12); mi=((mi-1)%12)+1;
      const dv=Math.min(d,new Date(ai,mi,0).getDate());
      const vencFmt=String(dv).padStart(2,'0')+'/'+String(mi).padStart(2,'0')+'/'+ai;
      const valor=i===nparc-1?parseFloat((valorTotal-(valorParcela*(nparc-1))).toFixed(2)):valorParcela;
      parcelas.push({parcela:i+1, vencimento:vencFmt, valor, pago:false, dataPgto:''});
    }
  }

  FISCAL_DB[chave].saidas.push({
    data:dataV?dataV.split('-').reverse().join('/'):'',
    num, cliente:cli, pessoaTipo:document.getElementById('ns-pessoa-tipo')?.value||'cliente', tipo, itens, valorTotal,
    parcelado:nparc>1, numParcelas:nparc,
    parcelas: parcelas.length?parcelas:undefined
  });

  if(tipo==='Venda'){
    try{ _fiscalSomarPisCofinsVenda(chave, valorTotal); }catch(_){}
  }

  fiscalSalvar(); cm(); fiscalRenderSaidas(); fiscalRenderDespesas();
  showToast('Saída adicionada!','success');
}

function _fiscalSomarPisCofinsVenda(chave, valorVenda){
  const regime=_fiscalRegimeAtual();
  const rt=_REGIME_RATES[regime];
  if(!rt || (!rt.pis && !rt.cofins)) return;
  const pis=valorVenda*rt.pis/100, cofins=valorVenda*rt.cofins/100;
  const r2=v=>Math.round(v*100)/100;

  if(!FISCAL_DB[chave].impostos) FISCAL_DB[chave].impostos={};
  FISCAL_DB[chave].impostos.pis=r2((FISCAL_DB[chave].impostos.pis||0)+pis);
  FISCAL_DB[chave].impostos.cofins=r2((FISCAL_DB[chave].impostos.cofins||0)+cofins);

  const mm2=chave.match(/(\d{4})-(\d{2})$/);
  if(mm2){
    const mesObj=_apurGetMes(mm2[1],mm2[2]);
    mesObj.imp=r2((Number(mesObj.imp)||0)+pis+cofins);
    saveFiscalApur();
  }
}

function fiscalExcluirSaida(idx){
  if(!_fiscalGateLock('excluir saída')) return;
  if(!confirm('Excluir esta saída?')) return;
  const chave=fiscalChave();
  const sai=FISCAL_DB[chave]?.saidas;
  if(sai && sai[idx]){
    const removida=sai[idx];
    sai.splice(idx,1);
    if(removida && removida.tipo==='Venda'){
      try{ _fiscalSomarPisCofinsVenda(chave, -Number(removida.valorTotal||0)); }catch(_){}
    }
  }
  fiscalSalvar(); fiscalRenderSaidas(); fiscalRenderDespesas();
}

function fiscalMoverParaEntrada(idx){
  const chave=fiscalChave();
  const sai=FISCAL_DB[chave]?.saidas;
  if(!sai||!sai[idx]) return;
  const item=sai.splice(idx,1)[0];
  if(item && item.tipo==='Venda'){
    try{ _fiscalSomarPisCofinsVenda(chave, -Number(item.valorTotal||0)); }catch(_){}
  }
  if(!Array.isArray(FISCAL_DB[chave].entradas)) FISCAL_DB[chave].entradas=[];
  item.fornecedor=item.fornecedor||item.cliente||'';
  FISCAL_DB[chave].entradas.push(item);
  fiscalSalvar(); fiscalRenderEntradas(); fiscalRenderSaidas(); fiscalRenderDespesas();
  showToast('Movido para Entradas','success');
}

function fiscalLimparMes(){
  if(!_fiscalGateLock('limpar mês')) return;
  const chave=fiscalChave();
  const mes=document.getElementById('fiscal-sel-mes')?.value||'';
  const ano=document.getElementById('fiscal-sel-ano')?.value||'';
  const nomeMes=_MESES_NOME[parseInt(mes)-1]||mes;
  const ent=(FISCAL_DB[chave]?.entradas||[]).length;
  const sai=(FISCAL_DB[chave]?.saidas||[]).length;
  if(!ent&&!sai){ showToast('Nenhum lançamento neste mês.','info'); return; }
  if(!confirm(`⚠️ Limpar ${nomeMes}/${ano}?\n\nIsso vai apagar:\n• ${ent} NF(s) de Entradas\n• ${sai} NF(s) de Saídas/Despesas\n\nO Resumo (faturamento, compras, etc.) será mantido.\nEssa ação não pode ser desfeita.`)) return;
  if(!FISCAL_DB[chave]) FISCAL_DB[chave]={entradas:[],saidas:[],impostos:{}};
  FISCAL_DB[chave].entradas=[];
  FISCAL_DB[chave].saidas=[];
  fiscalSalvar();
  fiscalRenderEntradas();
  fiscalRenderSaidas();
  fiscalRenderDespesas();
  const statusEl=document.getElementById('fiscal-import-status');
  if(statusEl){ statusEl.style.color='#e74c3c'; statusEl.textContent=`🗑️ ${nomeMes}/${ano} limpo — ${ent+sai} NF(s) removidas. Pronto para reimportar.`; }
  showToast(`Mês ${nomeMes} limpo!`,'success');
}


function _fiscalMesFechado(){
  const chave=fiscalChave();
  return !!(FISCAL_DB[chave]?.resumo?.fechado);
}

function _fiscalVerificarSenha(acao){
  const chave=fiscalChave();
  const hash=FISCAL_DB[chave]?.resumo?.senhaHash;
  if(!hash){ showToast('Mês não possui senha cadastrada.','error'); return false; }
  const entrada=prompt(`🔒 Mês fechado. Digite a senha para ${acao}:`);
  if(entrada===null) return false;
  if(btoa(unescape(encodeURIComponent(entrada)))===hash) return true;
  showToast('Senha incorreta.','error');
  return false;
}

function fiscalFecharMes(){
  const chave=fiscalChave();
  const mes=document.getElementById('fiscal-sel-mes')?.value||'';
  const ano=document.getElementById('fiscal-sel-ano')?.value||'';
  const nomeMes=_MESES_NOME[parseInt(mes)-1]||mes;
  if(_fiscalMesFechado()){ showToast('Mês já está fechado. Use 🔓 Reabrir para desbloquear.','info'); return; }
  const senha=prompt(`🔒 Fechar ${nomeMes}/${ano}\n\nDefina uma senha para proteger este mês (ou cancele para fechar sem senha):`);
  if(senha===null) return; 
  if(!confirm(`⚠️ Fechar ${nomeMes}/${ano}?\n\nApós fechar, exclusões e edições vão exigir senha.\n\nDeseja continuar?`)) return;
  if(!FISCAL_DB[chave]) FISCAL_DB[chave]={entradas:[],saidas:[],impostos:{}};
  if(!FISCAL_DB[chave].resumo) FISCAL_DB[chave].resumo={};
  FISCAL_DB[chave].resumo.fechado=true;
  FISCAL_DB[chave].resumo.senhaHash=senha?btoa(unescape(encodeURIComponent(senha))):'';
  FISCAL_DB[chave].resumo.fechadoEm=new Date().toISOString().slice(0,10);
  fiscalSalvar();
  _fiscalAtualizarLockUI();
  showToast(`🔒 ${nomeMes}/${ano} fechado com sucesso!`,'success');
}

function fiscalReabrirMes(){
  const chave=fiscalChave();
  const mes=document.getElementById('fiscal-sel-mes')?.value||'';
  const ano=document.getElementById('fiscal-sel-ano')?.value||'';
  const nomeMes=_MESES_NOME[parseInt(mes)-1]||mes;
  if(!_fiscalMesFechado()){ showToast('Mês já está aberto.','info'); return; }
  if(FISCAL_DB[chave]?.resumo?.senhaHash){
    if(!_fiscalVerificarSenha('reabrir')) return;
  }
  FISCAL_DB[chave].resumo.fechado=false;
  FISCAL_DB[chave].resumo.senhaHash='';
  fiscalSalvar();
  _fiscalAtualizarLockUI();
  showToast(`🔓 ${nomeMes}/${ano} reaberto!`,'success');
}

function _fiscalAtualizarLockUI(){
  const fechado=_fiscalMesFechado();
  const badge=document.getElementById('fiscal-lock-badge');
  const btnFechar=document.getElementById('fiscal-btn-fechar');
  const btnReabrir=document.getElementById('fiscal-btn-reabrir');
  if(badge){ badge.style.display=fechado?'inline-block':'none'; }
  if(btnFechar){ btnFechar.style.display=fechado?'none':'inline-block'; }
  if(btnReabrir){ btnReabrir.style.display=fechado?'inline-block':'none'; }
}

function _fiscalGateLock(acao){
  if(!_fiscalMesFechado()) return true;
  return _fiscalVerificarSenha(acao);
}


function fiscalAdicionarUsuario(){

  const existentes=Object.entries(USERS)
    .filter(([,u])=>u.tabs&&u.tabs.includes('fiscal'))
    .map(([k,u])=>`<tr style="font-size:.82rem">
      <td style="padding:5px 8px;border-bottom:1px solid #eee">${k}</td>
      <td style="padding:5px 8px;border-bottom:1px solid #eee">${u.name||''}</td>
      <td style="padding:5px 8px;border-bottom:1px solid #eee;color:#888">${u.role||''}</td>
    </tr>`).join('');

  om('fiscalAdicionarUsuario');
  const body=document.getElementById('modal-body');
  body.innerHTML=`<h3>👤 Usuário Fiscal — Firebase</h3>
    <p style="font-size:.83rem;color:#555;margin-bottom:14px">Cria um usuário com acesso <strong>somente à aba Fiscal</strong>. Salvo automaticamente no Firebase.</p>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:14px">
      <div class="fg"><label>Login (sem espaço)</label><input id="fu-login" placeholder="ex: fiscal"></div>
      <div class="fg"><label>Nome</label><input id="fu-nome" placeholder="ex: Contador João"></div>
      <div class="fg"><label>Senha</label><input id="fu-pass" type="password" placeholder="mínimo 4 caracteres"></div>
      <div class="fg"><label>Cargo</label><input id="fu-role" placeholder="ex: Contador" value="Fiscal"></div>
    </div>
    <div style="display:flex;gap:10px;margin-bottom:18px">
      <button class="btn-save" onclick="fiscalSalvarUsuario()">💾 Criar e Salvar no Firebase</button>
      <button class="btn-cancel" onclick="cm()">Cancelar</button>
    </div>
    ${existentes?`<div style="font-weight:700;font-size:.82rem;color:var(--primary);margin-bottom:6px">Usuários com acesso ao Fiscal:</div>
    <table style="width:100%;border-collapse:collapse;background:#f9f9f9;border-radius:8px;overflow:hidden">
      <thead><tr style="background:#e8eaf6;font-size:.8rem;text-align:left">
        <th style="padding:6px 8px">Login</th><th style="padding:6px 8px">Nome</th><th style="padding:6px 8px">Cargo</th>
      </tr></thead><tbody>${existentes}</tbody>
    </table>`:
    '<div style="color:#aaa;font-size:.82rem">Nenhum usuário com acesso ao Fiscal ainda.</div>'}
  `;
}

function fiscalSalvarUsuario(){
  const login=(document.getElementById('fu-login').value||'').trim().toLowerCase().replace(/\s+/g,'');
  const nome=(document.getElementById('fu-nome').value||'').trim();
  const pass=(document.getElementById('fu-pass').value||'').trim();
  const role=(document.getElementById('fu-role').value||'').trim()||'Fiscal';
  if(!login||!nome||!pass){ showToast('Preencha login, nome e senha!','error'); return; }
  if(pass.length<4){ showToast('Senha deve ter no mínimo 4 caracteres.','error'); return; }
  if(USERS[login]){ showToast('Login "'+login+'" já existe!','error'); return; }
  USERS[login]={password:pass, name:nome, role:role, descricao:'Acesso Fiscal', tabs:['fiscal']};
  _usersDesmarcarApagado(login);
  saveUsers();
  cm();
  showToast('Usuário "'+nome+'" criado e salvo no Firebase! ✅','success');
}


function fiscalDrop(e){
  e.preventDefault();
  document.getElementById('fiscal-drop-zone').style.background='#f8fff8';
  const files=e.dataTransfer&&e.dataTransfer.files?Array.from(e.dataTransfer.files):[];
  _fiscalImportarLista(files);
}

function fiscalImportarArquivo(inp){
  const files=inp&&inp.files?Array.from(inp.files):[];
  _fiscalImportarLista(files);
  inp.value='';
}


function _garantirJSZip(cb){
  if(window.JSZip){ cb(); return; }
  const s=document.createElement('script');
  s.src='https://cdnjs.cloudflare.com/ajax/libs/jszip/3.10.1/jszip.min.js';
  s.onload=function(){ cb(); };
  s.onerror=function(){ cb(new Error('não consegui carregar o leitor de ZIP (sem internet?)')); };
  document.head.appendChild(s);
}
function _fiscalLerTexto(file){ return new Promise((res,rej)=>{ const r=new FileReader(); r.onload=e=>res(e.target.result); r.onerror=rej; r.readAsText(file,'UTF-8'); }); }
function _fiscalLerBuffer(file){ return new Promise((res,rej)=>{ const r=new FileReader(); r.onload=e=>res(e.target.result); r.onerror=rej; r.readAsArrayBuffer(file); }); }

async function _fiscalColetarXmls(zips, xmls){
  const out=[]; let aviso='';
  for(const f of xmls){ try{ out.push({name:f.name, text:await _fiscalLerTexto(f)}); }catch(e){} }
  if(zips.length){
    try{ await new Promise((res,rej)=>_garantirJSZip(err=>err?rej(err):res())); }
    catch(e){ return {out, aviso:'⚠️ Não consegui abrir os arquivos .zip (precisa de internet). Você pode descompactar o zip e soltar os .xml direto.'}; }
    for(const z of zips){
      try{
        const buf=await _fiscalLerBuffer(z);
        const zip=await window.JSZip.loadAsync(buf);
        const names=Object.keys(zip.files).filter(n=>!zip.files[n].dir && n.toLowerCase().endsWith('.xml'));
        for(const n of names){ try{ const t=await zip.files[n].async('string'); out.push({name:n, text:t}); }catch(e){} }
      }catch(e){ aviso='⚠️ Um dos .zip não pôde ser lido: '+((e&&e.message)||e); }
    }
  }
  return {out, aviso};
}
function _fiscalImportarLista(files){
  if(!files||!files.length) return;
  const statusEl=document.getElementById('fiscal-import-status');
  const low=n=>String(n||'').toLowerCase();
  const zips =files.filter(f=>low(f.name).endsWith('.zip'));
  const xmls =files.filter(f=>low(f.name).endsWith('.xml'));
  const pdfs =files.filter(f=>low(f.name).endsWith('.pdf'));
  const outros=files.filter(f=>{const n=low(f.name);return n.endsWith('.csv')||n.endsWith('.xlsx')||n.endsWith('.xls');});
  if(zips.length || xmls.length){
    if(!_fiscalGateLock('importar XML')) return;
    if(statusEl){ statusEl.style.whiteSpace='pre-line'; statusEl.style.color='#555'; statusEl.textContent='⏳ Lendo os arquivos'+(zips.length?' (abrindo o zip)':'')+'...'; }
    _fiscalColetarXmls(zips, xmls).then(function(r){
      const xmlList=r.out||[];
      if(!xmlList.length){ if(statusEl){ statusEl.style.color='#e74c3c'; statusEl.textContent='Nenhum XML de NF-e encontrado nos arquivos.'+(r.aviso?'\n'+r.aviso:''); } return; }
      let ok=0; const resumo=[];
      xmlList.forEach(function(item){
        const res=fiscalParsearXMLNFe(item.text);
        if(res&&res.ok){ ok++; resumo.push('✅ '+res.tipo+' — NF '+(res.nNF||'?')+' — '+(res.nome||'')+' — R$ '+Number(res.vNF||0).toLocaleString('pt-BR',{minimumFractionDigits:2})); }
        else { resumo.push('❌ '+item.name+': '+((res&&res.erro)||'não é NF-e')); }
      });
      if(statusEl){ statusEl.style.color=ok?'#27ae60':'#e74c3c';
        statusEl.textContent=ok+' de '+xmlList.length+' nota(s) importada(s) — cada uma foi pro mês da própria data:\n'+resumo.slice(0,60).join('\n')+(resumo.length>60?'\n...':'')+(r.aviso?'\n\n'+r.aviso:'')+(pdfs.length?'\n\n⚠️ '+pdfs.length+' PDF ignorado(s) — o PDF não é lido automático, use o XML.':''); }
    }).catch(function(e){ if(statusEl){ statusEl.style.color='#e74c3c'; statusEl.textContent='Erro ao ler os arquivos: '+((e&&e.message)||e); } });
  } else if(outros.length){
    fiscalProcessarArquivo(outros[0]);
  } else if(pdfs.length){
    if(statusEl){ statusEl.style.whiteSpace='pre-line'; statusEl.style.color='#e67e22';
      statusEl.textContent='⚠️ O PDF da nota não é lido automaticamente — ele é só a "impressão" (DANFE), sem os dados estruturados por dentro.\n\nPara importar automático, use o arquivo XML da NF-e (.xml) — pode ser dentro de um .zip que eu abro sozinho.'; }
  } else if(statusEl){
    statusEl.style.color='#e74c3c'; statusEl.textContent='❌ Formato não suportado. Use XML (NF-e) — solto ou dentro de .zip — CSV ou XLSX.';
  }
}

function fiscalParsearXMLNFe(text){
  try{
    const doc=new DOMParser().parseFromString(text,'text/xml');
    if(doc.getElementsByTagName('parsererror').length) return {ok:false,erro:'arquivo não é um XML válido'};
    const inf=doc.getElementsByTagName('infNFe')[0]||doc;
    const g=(parent,tag)=>{ if(!parent) return ''; const el=parent.getElementsByTagName(tag)[0]; return el?el.textContent.trim():''; };
    const ide =inf.getElementsByTagName('ide')[0];
    const emit=inf.getElementsByTagName('emit')[0];
    const dest=inf.getElementsByTagName('dest')[0];
    if(!ide||!emit) return {ok:false,erro:'não parece uma NF-e (sem ide/emit)'};
    const tpNF=g(ide,'tpNF');
    const nNF=g(ide,'nNF');
    const dhEmi=g(ide,'dhEmi')||g(ide,'dEmi');
    const dataISO=(dhEmi||'').slice(0,10);
    const dataBR=dataISO?dataISO.split('-').reverse().join('/'):'';
    const emitNome=g(emit,'xNome');
    const destNome=dest?g(dest,'xNome'):'';
    const dets=inf.getElementsByTagName('det');
    const itens=[];
    for(let i=0;i<dets.length;i++){
      const prod=dets[i].getElementsByTagName('prod')[0]; if(!prod) continue;
      itens.push({ produto:g(prod,'xProd'), valor:parseFloat(g(prod,'vProd'))||0, kg:parseFloat(g(prod,'qCom'))||0 });
    }
    const totEl=inf.getElementsByTagName('ICMSTot')[0];
    const vNF=totEl?(parseFloat(g(totEl,'vNF'))||0):itens.reduce((s,i)=>s+i.valor,0);
    const isEntrada=(tpNF==='0');

    const chave=(dataISO&&/^\d{4}-\d{2}/.test(dataISO))?dataISO.slice(0,7):fiscalChave();
    if(!FISCAL_DB[chave]) FISCAL_DB[chave]={entradas:[],saidas:[],impostos:{}};
    if(!Array.isArray(FISCAL_DB[chave].entradas)) FISCAL_DB[chave].entradas=[];
    if(!Array.isArray(FISCAL_DB[chave].saidas))   FISCAL_DB[chave].saidas=[];
    const nota={ data:dataBR, num:nNF, tipo:isEntrada?'Compra':'Venda',
      emitente:emitNome, destinatario:destNome,
      itens: itens.length?itens:[{produto:'',valor:vNF,kg:0}], valorTotal:vNF };
    if(isEntrada){ nota.fornecedor=emitNome; FISCAL_DB[chave].entradas.push(nota); }
    else { nota.cliente=destNome||emitNome; FISCAL_DB[chave].saidas.push(nota); }
    fiscalSalvar();
    try{ fiscalRenderEntradas(); }catch(e){}
    try{ fiscalRenderSaidas(); }catch(e){}
    try{ fiscalRenderDespesas(); }catch(e){}
    return { ok:true, tipo:isEntrada?'Entrada':'Saída', nNF:nNF, nome:isEntrada?emitNome:destNome, vNF:vNF };
  }catch(e){ return {ok:false,erro:(e&&e.message)||String(e)}; }
}

function fiscalProcessarArquivo(file){
  if(!_fiscalGateLock('importar arquivo')) return;
  const statusEl=document.getElementById('fiscal-import-status');
  statusEl.textContent='⏳ Processando arquivo...';
  const ext=file.name.split('.').pop().toLowerCase();
  if(ext==='csv'){
    const reader=new FileReader();
    reader.onload=e=>fiscalParsearCSV(e.target.result);
    reader.readAsText(file,'UTF-8');
  } else if(ext==='xlsx'||ext==='xls'){
    const reader=new FileReader();
    reader.onload=e=>fiscalParsearXLSX(e.target.result);
    reader.readAsArrayBuffer(file);
  } else {
    statusEl.textContent='❌ Formato não suportado. Use CSV ou XLSX.';
    statusEl.style.color='#e74c3c';
  }
}

const _KW_REMESSA=['remessa','transferencia soci','transferencia para soci','retirada soci',
  'distribuicao lucro','pro labore','prolabore','sangria','retirada dos soci'];
const _KW_SALARIO=['salari','folha','holerit','holerito','funcionari','vale transp','vale aliment','vale refei',
  'decimo','13 sal','13o sal','pgto func','pagto func','pagamento func','adiant func','rescisao',
  'ferias','licenca maternidade'];
const _KW_IMPOSTO=['simples nac','das ','das-','darf','irpj','csll','cofins',' pis ','iss ','icms','pgfn',
  'receita federal','prefeitura','taxa ','tributo','multa fiscal'];
const _KW_DESPESA_FIXA=['aluguel','energia','agua ','telefon','internet','manutencao pred','seguro',
  'contabilidade','juridico','escritorio'];
const _KW_COMPRA=['compra','aquisic','sucata','cobre','alumin','latao','latão','inox','ferro velho',
  'zinco','estanho','cabo','fio ','chapa','tubul','peca','scrap'];
const _RE_CPF=/\b\d{3}[.\s]\d{3}[.\s]\d{3}[-\s]\d{2}\b/;
const _RE_NF=/\bNF[\s\-]?(\d+)\b|\bNota\s*(\d+)\b/i;

function _fiscalClassificar(desc, tipo, valor){
  const dl=(desc||'').toLowerCase();
  const tl=(tipo||'').toLowerCase();


  if(_KW_REMESSA.some(k=>dl.includes(k)||tl.includes(k)))
    return { isEntrada:false, tipoFinal:'Remessa' };

  if(_KW_SALARIO.some(k=>dl.includes(k)||tl.includes(k)))
    return { isEntrada:false, tipoFinal:'Folha / Salário' };

  if(_KW_IMPOSTO.some(k=>dl.includes(k)||tl.includes(k)))
    return { isEntrada:false, tipoFinal:'Imposto / Tributo' };


  if(_KW_DESPESA_FIXA.some(k=>dl.includes(k)))
    return { isEntrada:false, tipoFinal:'Despesa Fixa' };


  if(_KW_COMPRA.some(k=>dl.includes(k)))
    return { isEntrada:true, tipoFinal:'Compra Sucata' };


  if(tl.includes('receit')||tl.includes('venda')||dl.includes('venda '))
    return { isEntrada:false, tipoFinal:'Venda' };

  if(_RE_CPF.test(desc))
    return { isEntrada:true, tipoFinal:'Compra / CPF' };


  const isEntrada = valor < 0;
  return { isEntrada, tipoFinal: isEntrada ? 'Compra' : 'Receita / Venda' };
}

function _fiscalExtrairNum(desc, numBruto){
  if(numBruto){

    return numBruto.trim();
  }
  const m=_RE_NF.exec(desc);
  return m?(m[1]||m[2]):'';
}
function _fiscalNumExibir(num){
  return (num||'').replace(/^NF-?e[:\s]*/i,'').replace(/^NFe?\s*/i,'').trim();
}

function _iCol(headers, ...terms){
  return headers.findIndex(h=>terms.some(t=>h.includes(t)));
}

function _csvParseRow(line, sep){
  const result=[];
  let cur='', inQ=false;
  for(let i=0;i<line.length;i++){
    const ch=line[i];
    if(ch==='"'){ inQ=!inQ; }
    else if(ch===sep&&!inQ){ result.push(cur.trim()); cur=''; }
    else { cur+=ch; }
  }
  result.push(cur.trim());
  return result;
}

function _origemIsEntrada(origem){
  const o=(origem||'').toLowerCase().trim();
  if(o==='compra'||o.includes('entrada')||o.includes('recebi')||o.includes('devolução fornec')) return true;
  if(o==='venda'||o.includes('saída')||o.includes('saida')||o.includes('despesa')) return false;
  return null;
}


function _matchCadastro(_nome){ return null; }

function fiscalParsearCSV(text){
  const statusEl=document.getElementById('fiscal-import-status');
  try{
    const linhas=text.split(/\r?\n/).filter(l=>l.trim());
    if(linhas.length<2){ statusEl.textContent='❌ Arquivo CSV vazio.'; return; }
    const sep=linhas[0].includes(';')?';':',';
    const rawHeaders=_csvParseRow(linhas[0], sep);
    const headers=rawHeaders.map(h=>h.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,''));

    const iData   =_iCol(headers,'data da compra','data da venda','data de movim','data vencim','data');
    const iDesc   =_iCol(headers,'nome do produto','nome produto','produto/servico','produto/serviço',
                          'descricao','descri','histor','memo','lançamento','lancamento');
    const iSKU    =_iCol(headers,'sku','codigo do prod','referência do prod');
    const iForn   =_iCol(headers,'fornecedor','cliente/forn','cliente forn','cliente','benefici',
                          'favoreci','contato','razao','sacado','cedente','payee');

    const iVendedor=_iCol(headers,'vendedor','numero da venda','num venda');
    const iOrigem =_iCol(headers,'tipo de negoc','origem da movim','origem da','movimentacao','movimento');

    let iValor    =_iCol(headers,'valor liquido','liquido no financeiro','valor net','net value');
    if(iValor<0) iValor=_iCol(headers,'valor bruto','valor total','total');
    if(iValor<0) iValor=_iCol(headers,'valor','montant','quantia','amount','credito','debito');
    const iQtd    =_iCol(headers,'quantidade de itens','quantidade','qtd','peso','kg','qtde','unidades');
    const iTipoOp =_iCol(headers,'tipo de mov','tipo mov','operacao','operação');

    let iNum=_iCol(headers,'nota fiscal/rps','nota fiscal','codigo de referencia','codigo ref',
                           'numero nf','numero da nota','nf-e','nfe','num doc','numero doc');
    if(iNum<0) iNum=_iCol(headers,'referencia','referência','pedido','lote','documento','doc num');
    if(iNum<0) iNum=_iCol(headers,'numero','nº','n°');
    const iCpfCnpj=_iCol(headers,'cpf','cnpj');


    const colInfo=`📋 Colunas do CSV: ${rawHeaders.join(' | ')}\n`
      +`✅ Mapeado → Data:${iData>=0?rawHeaders[iData]:'❌'} | Fornecedor:${iForn>=0?rawHeaders[iForn]:'❌'} | Material:${iDesc>=0?rawHeaders[iDesc]:'❌'} | Nº NF:${iNum>=0?rawHeaders[iNum]:'❌'} | Valor:${iValor>=0?rawHeaders[iValor]:'❌'} | Kg:${iQtd>=0?rawHeaders[iQtd]:'❌'}`;
    statusEl.style.whiteSpace='pre-line';
    statusEl.style.color='#555';
    statusEl.textContent=colInfo;

    const grupos={};
    for(let i=1;i<linhas.length;i++){
      const cols=_csvParseRow(linhas[i], sep);
      if(!cols.length||!cols[0]) continue;

      const data    =iData>=0   ?cols[iData]  :'';
      const descProd=iDesc>=0   ?cols[iDesc]  :'';
      const sku     =iSKU>=0    ?cols[iSKU]   :'';
      const fornRaw =iForn>=0&&cols[iForn]?cols[iForn]:'';
      const origem  =iOrigem>=0 ?cols[iOrigem]:'';
      const valorR  =iValor>=0  ?cols[iValor] :'0';
      const qtdR    =iQtd>=0    ?cols[iQtd]   :'';
      const tipoOp  =iTipoOp>=0 ?cols[iTipoOp]:'';
      const numB    =iNum>=0    ?cols[iNum]   :'';
      const cpfDoc  =iCpfCnpj>=0?cols[iCpfCnpj]:'';

      const valor=parseFloat(valorR.replace(/\./g,'').replace(',','.'))||0;
      const kg   =parseFloat(qtdR  .replace(/\./g,'').replace(',','.'))||0;
      const num  =_fiscalExtrairNum(descProd+'|'+fornRaw, numB);
      const pessoa=fornRaw||descProd;

      let isEntrada=null;
      let tipoForcado=null;


      if(iVendedor>=0){ isEntrada=false; tipoForcado='Venda'; }


      const descL=(descProd||'').toLowerCase();
      const pessoaL=pessoa.toLowerCase();
      if(isEntrada===null && _KW_REMESSA.some(k=>descL.includes(k)||pessoaL.includes(k))){
        isEntrada=false; tipoForcado='Remessa';
      }
      if(isEntrada===null && descL.includes('uso e consumo')){
        isEntrada=false; tipoForcado='Despesa';
      }

      const _KW_MAT=['sucata','cobre','alumin','ferro','inox','latao','latão','zinco','estanho','scrap','vergalhao','vergalhão'];
      if(isEntrada===null && _KW_MAT.some(k=>descL.includes(k))){
        isEntrada=true; tipoForcado='Compra Sucata';
      }

      if(isEntrada===null){
        const cadastro=_matchCadastro(pessoa);
        if(cadastro==='entrada') isEntrada=true;
        else if(cadastro==='saida') isEntrada=false;
      }
      if(isEntrada===null){
        const toL=(tipoOp||'').toLowerCase();
        if(toL.includes('entrada')) isEntrada=true;
        else if(toL.includes('saida')||toL.includes('saída')) isEntrada=false;
      }

      if(isEntrada===null) isEntrada=_origemIsEntrada(origem);

      if(isEntrada===null) isEntrada=_fiscalClassificar(pessoa+'|'+descProd, origem, valor).isEntrada;


      const tipoGrupo = tipoForcado || (isEntrada?'Compra Sucata':'Saída');
      const grpKey = num ? `NF:${num}:${tipoGrupo}` : `SEM-NF:${i}`;
      if(!grupos[grpKey]){
        const obs=rawHeaders.map((h,idx)=>cols[idx]?`${h}: ${cols[idx]}`:'').filter(Boolean).join(' | ');
        grupos[grpKey]={ isEntrada, data, num, pessoa, cpfDoc, obs, tipo:tipoGrupo, itens:[] };
      }
      grupos[grpKey].itens.push({produto:descProd, sku, kg, valor:Math.abs(valor)});
    }

    let entradas=0, saidas=0;
    Object.values(grupos).forEach(g=>{
      const valorTotal=g.itens.reduce((s,it)=>s+it.valor,0);
      fiscalAdicionarLinha(g.isEntrada,{
        data:g.data, num:g.num,
        fornecedor:g.isEntrada?g.pessoa:'',
        cliente:!g.isEntrada?g.pessoa:'',
        obs:g.obs, cpfDoc:g.cpfDoc,
        itens:g.itens, valorTotal, tipo:g.tipo
      });
      if(g.isEntrada) entradas++; else saidas++;
    });

    fiscalSalvar(); fiscalRenderEntradas(); fiscalRenderSaidas(); fiscalRenderDespesas();
    statusEl.style.color='#27ae60';
    const avisoNF =iNum<0?' ⚠️ Sem coluna de Nº NF — cada linha foi salva separada.':'';
    const avisoKg =(iVendedor>=0&&iQtd<0)
      ?'\n⚠️ Este CSV de vendas não tem coluna de peso/material (é o resumo financeiro). Para importar com Kg e produto, exporte pelo Conta Azul o relatório de vendas com itens (pivot 6 — tem colunas "Nome do produto" e "Quantidade de itens").'
      :'';
    statusEl.textContent=`✅ Importado! ${entradas} NFs de entrada, ${saidas} NFs de saída.`+avisoNF+avisoKg;
  } catch(err){
    statusEl.textContent='❌ Erro ao processar CSV: '+err.message;
    statusEl.style.color='#e74c3c';
  }
}

function fiscalParsearXLSX(buffer){
  const statusEl=document.getElementById('fiscal-import-status');
  try{
    if(!window.XLSX){ statusEl.textContent='⚠️ Biblioteca XLSX não disponível. Use o formato CSV.'; statusEl.style.color='#f39c12'; return; }
    const wb=XLSX.read(new Uint8Array(buffer),{type:'array'});
    const ws=wb.Sheets[wb.SheetNames[0]];
    const rows=XLSX.utils.sheet_to_json(ws,{defval:''});
    let entradas=0, saidas=0, salarios=0, cpfs=0;
    rows.forEach(row=>{
      const keys=Object.keys(row);
      const get=(...terms)=>{ for(const t of terms){ const k=keys.find(k=>k.toLowerCase().includes(t)); if(k&&row[k]!==''&&row[k]!==undefined) return String(row[k]); } return ''; };
      const data  =get('data','date','vencimento');
      const desc  =get('descri','histor','memo','detalhe','observa','lançamento','lancamento');
      const fornRaw=get('benefici','favoreci','fornecedor','cliente','contato','razao','sacado','cedente','nome','payee')||desc;
      const valorR=get('valor','montant','quantia','amount','credito','débito','debito');
      const tipo  =get('tipo','categ','natureza','classific');
      const numB  =get('número','numero','nf','documento','referência','referencia','doc','nota');
      const cpfDoc=get('cpf','cnpj');
      const valor =parseFloat(String(valorR).replace(/\./g,'').replace(',','.'))||0;
      const detalhes=keys.map(k=>row[k]?`${k}: ${row[k]}`:'').filter(Boolean).join(' | ');
      const {isEntrada, tipoFinal}=_fiscalClassificar(fornRaw+'|'+desc,tipo,valor);
      const num=_fiscalExtrairNum(desc+'|'+fornRaw,numB);
      if(tipoFinal==='Folha / Salário') salarios++;
      if(tipoFinal.includes('CPF')) cpfs++;
      fiscalAdicionarLinha(isEntrada,{
        data:String(data), num,
        fornecedor:isEntrada?fornRaw:'',
        cliente:!isEntrada?fornRaw:'',
        obs:detalhes||desc,
        cpfDoc, produto:'', valor:Math.abs(valor), tipo:tipoFinal
      });
      if(isEntrada) entradas++; else saidas++;
    });
    fiscalSalvar(); fiscalRenderEntradas(); fiscalRenderSaidas(); fiscalRenderDespesas();
    statusEl.style.color='#27ae60';
    statusEl.textContent=`✅ Importado! ${entradas} entradas, ${saidas} saídas`
      +(salarios?` (${salarios} folha/salário detectados)`:'')
      +(cpfs?` (${cpfs} CPF/Pessoa Física)`:'')+'.';
  } catch(err){
    statusEl.textContent='❌ Erro ao processar XLSX: '+err.message;
    statusEl.style.color='#e74c3c';
  }
}

function fiscalAdicionarLinha(isEntrada, obj){
  const chave=fiscalChave();
  if(!FISCAL_DB[chave]) FISCAL_DB[chave]={entradas:[],saidas:[],impostos:{}};
  if(!Array.isArray(FISCAL_DB[chave].entradas)) FISCAL_DB[chave].entradas=[];
  if(!Array.isArray(FISCAL_DB[chave].saidas))   FISCAL_DB[chave].saidas=[];

  const entry = Array.isArray(obj.itens) ? obj : {
    data: obj.data, num: obj.num,
    fornecedor: obj.fornecedor||'', cliente: obj.cliente||'',
    tipo: obj.tipo||( isEntrada?'Entrada':'Saída'),
    obs: obj.obs||'', cpfDoc: obj.cpfDoc||'', sku: obj.sku||'',
    itens:[{produto:obj.produto||'', kg:Number(obj.kg)||0, valor:Number(obj.valor)||0}],
    valorTotal:Number(obj.valor)||0
  };

  const arr=isEntrada?FISCAL_DB[chave].entradas:FISCAL_DB[chave].saidas;
  if(entry.num){
    const existIdx=arr.findIndex(e=>e.num===entry.num && (e.tipo||'')===(entry.tipo||''));
    if(existIdx>=0) arr.splice(existIdx,1);
  }
  arr.push(entry);
}

function fiscalRenderAnual(){
  const ano=document.getElementById('fiscal-sel-ano-anual')?.value||_anoAtual();
  const fmt=v=>'R$ '+_numFinito(v,0).toLocaleString('pt-BR',{minimumFractionDigits:2});
  const trimestres=[
    {label:'1º Tri (jan-mar)', meses:['01','02','03']},
    {label:'2º Tri (abr-jun)', meses:['04','05','06']},
    {label:'3º Tri (jul-set)', meses:['07','08','09']},
    {label:'4º Tri (out-dez)', meses:['10','11','12']},
  ];
  let totalFat=0, totalRes=0, totalImpIRC=0, totalImpCPF=0;
  const tb=document.getElementById('tb-fiscal-anual');
  if(!tb)return;
  let rows='';
  trimestres.forEach(tri=>{
    let fat=0,res=0,irc=0,cpf=0;
    tri.meses.forEach(m=>{
      const d=FISCAL_DB[_fPfx()+ano+'-'+m]||{};
      const r=d.resumo||{};
      const imp=d.impostos||{};
      const custo=(r.compras||0)+(r.despesas||0)+((r.estoqueInicial||0)-(r.estoqueFinal||0));
      fat+=r.faturamento||0;
      res+=(r.faturamento||0)-custo;
      irc+=(imp.irpj||0)+(imp.csll||0);
      cpf+=(imp.cofins||0)+(imp.pis||0);
    });
    totalFat+=fat; totalRes+=res; totalImpIRC+=irc; totalImpCPF+=cpf;
    rows+=`<tr><td><b>${tri.label}</b></td><td style="text-align:right">${fmt(fat)}</td><td style="text-align:right">${fmt(res)}</td><td style="text-align:right;color:#c0392b">${fmt(irc)}</td><td style="text-align:right;color:#c0392b">${fmt(cpf)}</td><td style="text-align:right;color:#c0392b;font-weight:700">${fmt(irc+cpf)}</td></tr>`;
  });
  rows+=`<tr style="background:#f5f5f5;font-weight:800"><td>TOTAL DO ANO</td><td style="text-align:right">${fmt(totalFat)}</td><td style="text-align:right">${fmt(totalRes)}</td><td style="text-align:right;color:#c0392b">${fmt(totalImpIRC)}</td><td style="text-align:right;color:#c0392b">${fmt(totalImpCPF)}</td><td style="text-align:right;color:#c0392b">${fmt(totalImpIRC+totalImpCPF)}</td></tr>`;
  tb.innerHTML=rows;

  const folhaEl=document.getElementById('fiscal-folha-anual');
  if(folhaEl){
    let totalFolha=0;
    folhaEl.innerHTML=_MESES_NOME.slice(1).map((nm,i)=>{
      const m=String(i+1).padStart(2,'0');
      const v=(FISCAL_DB[_fPfx()+ano+'-'+m]?.resumo?.folha)||0;
      totalFolha+=v;
      return `<div style="background:#fff;border:1.5px solid #ddd;border-radius:8px;padding:10px;text-align:center"><div style="font-size:.8rem;color:#666">${nm}</div><div style="font-weight:700;font-size:.95rem">${v?'R$ '+Number(v).toLocaleString('pt-BR',{minimumFractionDigits:2}):'—'}</div></div>`;
    }).join('')+`<div style="background:#e8f5e9;border:2px solid #27ae60;border-radius:8px;padding:10px;text-align:center"><div style="font-size:.8rem;color:#27ae60;font-weight:700">TOTAL ANO</div><div style="font-weight:800;font-size:.95rem;color:#27ae60">R$ ${Number(totalFolha).toLocaleString('pt-BR',{minimumFractionDigits:2})}</div></div>`;
  }
}


const _REGIME_HINTS={
  simples:'Simples Nacional: pagamento unificado via DAS + ICMS separado conforme estado.',
  presumido:'Lucro Presumido: IRPJ 15% (+ 10% adicional), CSLL 9%, COFINS 3%, PIS 0,65%, ICMS conforme estado.',
  real:'Lucro Real: IRPJ 15% (+ 10% adicional), CSLL 9%, COFINS 7,6%, PIS 1,65%, ICMS conforme estado.'
};

const _REGIME_RATES={ simples:{pis:0,cofins:0}, presumido:{pis:0.65,cofins:3.00}, real:{pis:1.65,cofins:7.60} };

function _fiscalRegimeAtual(){
  const rk=_fPfx()+'_regime';
  if(typeof FISCAL_DB!=='undefined' && FISCAL_DB[rk]) return FISCAL_DB[rk];
  const ls=localStorage.getItem('mm_fiscal_regime_'+_fiscalEmpresa);
  if(ls) return ls;
  if(_fPfx()===''){ const old=localStorage.getItem('mm_fiscal_regime'); if(old) return old; }
  return 'presumido';
}
function fiscalSetRegime(regime){
  const rk=_fPfx()+'_regime';
  if(typeof FISCAL_DB!=='undefined') FISCAL_DB[rk]=regime;
  try{ localStorage.setItem('mm_fiscal_regime_'+_fiscalEmpresa,regime); }catch(e){}

  if(typeof fiscalSalvar==='function') fiscalSalvar();
  const blocoS=document.getElementById('imp-bloco-simples');
  const blocoO=document.getElementById('imp-bloco-outros');
  const hint=document.getElementById('regime-hint');
  const lIrc=document.getElementById('imp-tot-linha-irpjcsll');
  const lCof=document.getElementById('imp-tot-linha-cofpis');
  if(blocoS) blocoS.style.display=regime==='simples'?'block':'none';
  if(blocoO) blocoO.style.display=regime==='simples'?'none':'block';
  if(lIrc) lIrc.style.display=regime==='simples'?'none':'block';
  if(lCof) lCof.style.display=regime==='simples'?'none':'block';
  if(hint) hint.textContent=_REGIME_HINTS[regime]||'';
  ['simples','presumido','real'].forEach(r=>{
    const btn=document.getElementById('rg-btn-'+r);
    if(btn) btn.style.borderColor=r===regime?'var(--primary)':'#ddd';
  });
  fiscalCalcImpostos();
}

function fiscalCarregarRegime(){
  const r=_fiscalRegimeAtual();
  const el=document.querySelector(`input[name="regime"][value="${r}"]`);
  if(el) el.checked=true;
  fiscalSetRegime(r);
}

function fiscalRenderImpostos(){
  const m=document.getElementById('fiscal-imp-mes')?.value||'01';
  const a=document.getElementById('fiscal-imp-ano')?.value||_anoAtual();
  const chave=_fPfx()+a+'-'+m;
  const imp=(FISCAL_DB[chave]?.impostos)||{};
  const fmtV=v=>v?Number(v).toLocaleString('pt-BR',{minimumFractionDigits:2}):'';
  const _si=id=>{ const el=document.getElementById(id); if(el) el.value=fmtV(imp[id.replace('imp-','')]); };
  _si('imp-irpj'); _si('imp-csll'); _si('imp-cofins'); _si('imp-pis');
  _si('imp-juros'); _si('imp-multas');
  if(document.getElementById('imp-icms')) document.getElementById('imp-icms').value=fmtV(imp.icms);
  if(document.getElementById('imp-icms-s')) document.getElementById('imp-icms-s').value=fmtV(imp.icms);
  if(document.getElementById('imp-das')) document.getElementById('imp-das').value=fmtV(imp.das);
  fiscalCarregarRegime();
  fiscalCalcImpostos();
}

function _parseImpNum(id){
  const v=(document.getElementById(id)?.value||'').replace(/\./g,'').replace(',','.');
  return parseFloat(v)||0;
}

function fiscalCalcImpostos(){
  const regime=_fiscalRegimeAtual();
  const fmt=v=>'R$ '+v.toLocaleString('pt-BR',{minimumFractionDigits:2});
  let total=0;
  if(regime==='simples'){
    const das=_parseImpNum('imp-das');
    const icms=_parseImpNum('imp-icms-s');
    total=das+icms;
    const el=document.getElementById('imp-tot-icms'); if(el) el.textContent=fmt(icms);
  } else {
    const irpj  =_parseImpNum('imp-irpj');
    const csll  =_parseImpNum('imp-csll');
    const cofins=_parseImpNum('imp-cofins');
    const pis   =_parseImpNum('imp-pis');
    const icms  =_parseImpNum('imp-icms');
    const juros =_parseImpNum('imp-juros');
    const multas=_parseImpNum('imp-multas');
    total=irpj+csll+cofins+pis+icms+juros+multas;
    const tIrc=document.getElementById('imp-tot-irpjcsll'); if(tIrc) tIrc.textContent=fmt(irpj+csll);
    const tCof=document.getElementById('imp-tot-cofpis');   if(tCof) tCof.textContent=fmt(cofins+pis);
    const tIcm=document.getElementById('imp-tot-icms');     if(tIcm) tIcm.textContent=fmt(icms);
  }
  const tG=document.getElementById('imp-tot-geral'); if(tG) tG.textContent=fmt(total);
}

function fiscalSalvarImpostos(){
  const m=document.getElementById('fiscal-imp-mes')?.value||'01';
  const a=document.getElementById('fiscal-imp-ano')?.value||_anoAtual();
  const chave=_fPfx()+a+'-'+m;
  if(!FISCAL_DB[chave]) FISCAL_DB[chave]={entradas:[],saidas:[],resumo:{}};
  const regime=_fiscalRegimeAtual();
  if(regime==='simples'){
    FISCAL_DB[chave].impostos={
      das:   _parseImpNum('imp-das'),
      icms:  _parseImpNum('imp-icms-s'),
      juros: _parseImpNum('imp-juros'),
      multas:_parseImpNum('imp-multas')
    };
  } else {
    FISCAL_DB[chave].impostos={
      irpj:  _parseImpNum('imp-irpj'),
      csll:  _parseImpNum('imp-csll'),
      cofins:_parseImpNum('imp-cofins'),
      pis:   _parseImpNum('imp-pis'),
      icms:  _parseImpNum('imp-icms'),
      juros: _parseImpNum('imp-juros'),
      multas:_parseImpNum('imp-multas')
    };
  }
  fiscalSalvar();
  showToast('Impostos salvos!','success');
}

function fiscalAutoPisCofins(){
  const regime=_fiscalRegimeAtual();
  if(regime==='simples'){
    try{ showToast('No Simples Nacional o PIS e o COFINS já vêm embutidos na guia DAS — não há cálculo separado.','info'); }catch(_){}
    return;
  }
  const rt=_REGIME_RATES[regime]||_REGIME_RATES.presumido;
  const m=document.getElementById('fiscal-imp-mes')?.value||'01';
  const a=document.getElementById('fiscal-imp-ano')?.value||_anoAtual();
  const chave=_fPfx()+a+'-'+m;
  const fat=Number((FISCAL_DB[chave]&&FISCAL_DB[chave].resumo&&FISCAL_DB[chave].resumo.faturamento)||0);
  if(!fat){
    try{ showToast('Preencha e salve o Faturamento deste mês em Lançamento Mensal antes de calcular o PIS/COFINS.','info'); }catch(_){}
    return;
  }
  const pis=fat*rt.pis/100, cofins=fat*rt.cofins/100;
  const fmt2=v=>Number(v).toLocaleString('pt-BR',{minimumFractionDigits:2});
  const elP=document.getElementById('imp-pis');   if(elP) elP.value=fmt2(pis);
  const elC=document.getElementById('imp-cofins'); if(elC) elC.value=fmt2(cofins);
  fiscalCalcImpostos();
  try{ showToast('PIS ('+rt.pis+'%) e COFINS ('+rt.cofins+'%) calculados sobre o faturamento de R$ '+fmt2(fat)+'. Confira e clique em Salvar Impostos.','success'); }catch(_){}
}

function renderFiscal(){
  _fiscalEnsureEmpresa();
  _fiscalRenderEmpresaBotoes();
  _popularAnosFiscais();

  const hoje=new Date();
  const m=String(hoje.getMonth()+1).padStart(2,'0');
  const a=String(hoje.getFullYear());
  const selM=document.getElementById('fiscal-sel-mes');
  const selA=document.getElementById('fiscal-sel-ano');
  if(selM&&!selM.dataset.init){ selM.value=m; selA.value=a; selM.dataset.init='1'; }
  fiscalCarregarMes();
}
